ES(`root_category`),`name`=VALUES(`name`),`slug`=VALUES(`slug`),`sku`=VALUES(`sku`),`short_description`=VALUES(`short_description`),`description_html`=VALUES(`description_html`),`image`=VALUES(`image`),`unit`=VALUES(`unit`),`price`=VALUES(`price`),`request_hint`=VALUES(`request_hint`),`active`=VALUES(`active`),`featured`=VALUES(`featured`),`sort_order`=VALUES(`sort_order`),`seo_title`=VALUES(`seo_title`),`seo_description`=VALUES(`seo_description`),`source_file`=VALUES(`source_file`),`specs_json`=VALUES(`specs_json`),`gallery_json`=VALUES(`gallery_json`),`old_urls_json`=VALUES(`old_urls_json`);
INSERT INTO `products` (`id`,`category_id`,`root_category`,`name`,`slug`,`sku`,`short_description`,`description_html`,`image`,`unit`,`price`,`request_hint`,`active`,`featured`,`sort_order`,`seo_title`,`seo_description`,`source_file`,`specs_json`,`gallery_json`,`old_urls_json`) VALUES (8,6,'cable','КПБК-90','561-kpbk-90','MNP-0008','Кабели предназначены для электропитания погружных электродвигателей на максимальное рабочее напряжение переменного тока 3300 В частоты 50 Гц.','<div><p>КПБК-90 </p><p><img alt="kpbk" loading="lazy" src="assets/img/products/kpbk__1e5856d856cc9b927ac994a5.jpg"/></p><ol><li>Медная однопроволочная жила (класс 1) </li><li>Двухслойная изоляция из полиэтилена (HDPE) </li><li>Подушка из лент нетканого полотна </li><li>Броня из стальной оцинкованной ленты </li></ol><p><strong>Область применения КПБК-90: </strong><br/></p><p>Кабели предназначены для электропитания погружных электродвигателей на максимальное рабочее напряжение переменного тока 3300 В частоты 50 Гц. <br/></p><p>Кабели предназначены для эксплуатации в макроклиматических районах с умеренным и холодным климатом (УХЛ 1, 5). Ток утечки при напряжении постоянного тока 18 кВ, пересчитанный на 1 км длины и температуру 20°С - не более 1 х 10-5 А. Раздавливающее усилие кабелей - не менее 158 кН (16000 кгс). Изолированные жилы кабелей продольно герметичны при перепаде давления 0,02 МПа на 1 м длины. При спуско-подъемных и перемоточных операциях не допускается закручивание кабеля вокруг его продольной оси более чем на 10° на длине 5 м. Кабели могут эксплуатироваться в среде скважинной жидкости (смеси воды, нефти, газа) с газовым фактором не более 0,5 м3/кг и гидростатическом давлении не более 25 МПа. Содержание сероводорода в скважинной жидкости не более 0,01 г/л. </p><p><strong>Технические характеристики КПБК-90 </strong><br/><br/></p><table><tbody><tr><td>Гарантийный срок эксплуатации [месяц] </td><td><strong>18 </strong></td></tr><tr><td>Испытательное постоянное напряжение [кВ] </td><td><strong>18 </strong></td></tr><tr><td>Максимальная рабочая температура жилы [°С] </td><td><strong>90 </strong></td></tr><tr><td>Монтаж при температуре, не ниже [°C] </td><td><strong>-35 </strong></td></tr><tr><td>Номинальное переменное напряжение частотой 50 Гц [кВ] </td><td><strong>3.3 </strong></td></tr><tr><td>Температура окружающей среды, верхний предел [°C] </td><td><strong>+90 </strong></td></tr><tr><td>Температура окружающей среды, нижний предел [°C] </td><td><strong>-60 </strong></td></tr><tr><td>Электрическое сопротивление изоляции, не менее [МОм*км] </td><td><strong>2500 </strong></td></tr></tbody></table><p>Срок службы - не менее 5 лет. </p><table><tbody><tr><td><strong>Количество и сечение жил, <br/>шт х кв.мм </strong></td><td><strong>Масса кабеля, <br/>кг/км </strong></td><td><strong>Наружный диаметр, <br/>мм </strong></td></tr><tr><td>КПБК-90 3х6 </td><td>712 </td><td>25,0 </td></tr><tr><td>КПБК-90 3х10 </td><td>898 </td><td>29,0 </td></tr><tr><td>КПБК-90 3х16 </td><td>1125 </td><td>32,0 </td></tr><tr><td>КПБК-90 3х25 </td><td>1564 </td><td>35,6 </td></tr><tr><td>КПБК-90 3х35 </td><td>1913 </td><td>38,3 </td></tr><tr><td>КПБК-90 3х50 </td><td>2425 </td><td>44,0 </td></tr></tbody></table></div>','assets/img/products/kpbk__1e5856d856cc9b927ac994a5.jpg','м',NULL,'Укажите марку, число и сечение жил, рабочее напряжение, длину и условия прокладки.',1,0,8,'КПБК-90 — купить по заявке | Монополия','КПБК-90: подбор и поставка в Санкт-Петербурге. Укажите марку, число и сечение жил, рабочее напряжение, длину и условия прокладки. Расчет стоимости — по заявке.','site/www.monopoly-torg.ru/561-kpbk-90__f0630e5f726e43413daad14a.html','[["Гарантийный срок эксплуатации [месяц]", "18"], ["Испытательное постоянное напряжение [кВ]", "18"], ["Максимальная рабочая температура жилы [°С]", "90"], ["Монтаж при температуре, не ниже [°C]", "-35"], ["Номинальное переменное напряжение частотой 50 Гц [кВ]", "3.3"], ["Температура окружающей среды, верхний предел [°C]", "+90"], ["Температу