INSERT INTO `products` (`id`,`category_id`,`root_category`,`name`,`slug`,`sku`,`short_description`,`description_html`,`image`,`unit`,`price`,`request_hint`,`active`,`featured`,`sort_order`,`seo_title`,`seo_description`,`source_file`,`specs_json`,`gallery_json`,`old_urls_json`) VALUES (24,6,'cable','КППТФБП-150','577-kpptfbp-150','MNP-0024','1. Медная токопроводящая однопроволочная жила (класс 1); 2. Двухслойная изоляция:','<div><p>КППТФБП-150 </p><p><img alt="kektfbp140" loading="lazy" src="assets/img/products/kpptfbp__bf10ea9c022c3f184969f699.jpg"/></p><p>1. Медная токопроводящая однопроволочная жила (класс 1); <br/>2. Двухслойная изоляция: <br/></p><ul><li>1й слой - из композиций блоксополимера пропилена с этиленом; </li><li>2й слой - из термопластичного эластомера "Тефаблок"; </li></ul><p>3. Подушка из лент нетканого полотна; <br/>4. Броня из стальной оцинкованной бронеленты. </p><p><em>Примечание: </em>По требованию потребителя может быть изготовлен круглый кабель. </p><p><strong>Область применения КППТФБП-150: <br/></strong>Кабели <strong>КППТФБП-150 </strong>предназначены для электропитания погружных электродвигателей на максимальное рабочее напряжение переменного тока 3300 В частоты 50 Гц. </p><p>Кабели <strong>КППТФБП-150 </strong>предназначены для эксплуатации на суше в макроклиматических районах с умеренным и холодным климатом (УХЛ1). Первый слой изоляции устойчив к ионам меди. Ток утечки при напряжении постоянного тока 18 кВ, пересчитанный на 1 км длины и температуру 20°С - не более 1 х 10-5 А. Раздавливающее усилие кабелей - не менее 158 кН (16000 кгс). Изолированные жилы кабелей продольно герметичны при перепаде давления 0,1 МПа на 1 м длины. Кабели могут эксплуатироваться в среде скважинной жидкости (смеси воды, нефти, газа) с газовым фактором не более 0,5 м3/кг и гидростатическом давлении не более 25 МПа. Содержание сероводорода в скважинной жидкости не более 0,01 г/л. <br/><strong>Технические характеристики КППТФБП-150 </strong><br/><br/></p><table><tbody><tr><td>Гарантийный срок эксплуатации [месяц] </td><td><strong>18 </strong></td></tr><tr><td>Испытательное переменное напряжение частотой 50 Гц, 5 мин. [кВ] </td><td><strong>18 </strong></td></tr><tr><td>Испытательное постоянное напряжение [кВ] </td><td><strong>18 </strong></td></tr><tr><td>Максимальная рабочая температура жилы [°С] </td><td><strong>150 </strong></td></tr><tr><td>Монтаж при температуре, не ниже [°C] </td><td><strong>-40 </strong></td></tr><tr><td>Номинальное переменное напряжение частотой 50 Гц [кВ] </td><td><strong>3.3 </strong></td></tr><tr><td>Радиус изгиба при монтаже, не менее [мм] </td><td><strong>380 </strong></td></tr><tr><td>Температура окружающей среды, верхний предел [°C] </td><td><strong>+150 </strong></td></tr><tr><td>Температура окружающей среды, нижний предел [°C] </td><td><strong>-60 </strong></td></tr><tr><td>Электрическое сопротивление изоляции, не менее [МОм*км] </td><td><strong>2500 </strong></td></tr></tbody></table><p><br/>Срок службы - не менее 5 лет. <br/></p><table><tbody><tr><td><strong>Количество и сечение жил, <br/>шт х кв.мм </strong></td><td><strong>Масса кабеля, <br/>кг/км </strong></td><td><strong>Наружный размер, <br/>не более мм </strong></td></tr><tr><td>КППТФБП-150 3х10 </td><td>817 </td><td>12,7 х 30,5 </td></tr><tr><td>КППТФБП-150 3х16 </td><td>1036 </td><td>13,5 х 33,3 </td></tr><tr><td>КППТФБП-150 3х25 </td><td>1358 </td><td>14,6 х 36,6 </td></tr></tbody></table></div>','assets/img/products/kpptfbp__bf10ea9c022c3f184969f699.jpg','м',NULL,'Укажите марку, число и сечение жил, рабочее напряжение, длину и условия прокладки.',1,0,24,'КППТФБП-150 — купить по заявке | Монополия','КППТФБП-150: подбор и поставка в Санкт-Петербурге. Укажите марку, число и сечение жил, рабочее напряжение, длину и условия прокладки. Расчет стоимости — по заявке.','site/www.monopoly-torg.ru/577-kpptfbp-150__f345ba22b10664f6041d8851.html','[["Гарантийный срок эксплуатации [месяц]", "18"], ["Испытательное переменное напряжение частотой 50 Гц, 5 мин. [кВ]", "18"], ["Испытательное постоянное напряжение [кВ]", "18"], ["Максимальная рабочая температура жилы [°С]", "150"], ["Монтаж при температуре, не ниже [°C]", "-40"], ["Номинальное переменное напряжение частотой 50 Гц [кВ]", "3.3"], ["Радиус изгиба при монтаже, не менее [мм]", "380"], ["Температура окружающей среды, верхний предел [°C]", "+150"], ["Температура окружающей среды, нижний предел [°C]", "-60"], ["Электрическое сопротивление изоляции, не менее [МОм*км]", "2500"]]','["assets/img/products/kpptfbp__bf10ea9c022c3f184969f699.jpg"]','["http://www.monopoly-torg.ru/index.php/kabelnaya-produkciya/kabeli-dlya-pit-pogr-nasosov/577-kpptfbp-150"]') ON DUPLICATE KEY UPDATE `category_id`=VALUES(`category_id`),`root_category`=VALUES(`root_category`),`name`=VALUES(`name`),`slug`=VALUES(`slug`),`sku`=VALUES(`sku`),`short_description`=VALUES(`short_description`),`description_html`=VALUES(`description_html`),`image`=VALUES(`image`),`unit`=VALUES(`unit`),`price`=VALUES(`price`),`request_hint`=VALUES(`request_hint`),`active`=VALUES(`active`),`featured`=VALUES(`featured`),`sort_order`=VALUES(`sort_order`),`seo_title`=VALUES(`seo_title`),`seo_description`=VALUES(`seo_description`),`source_file`=VALUES(`source_file`),`specs_json`=VALUES(`specs_json`),`gallery_json`=VALUES(`gallery_json`),`old_urls_json`=VALUES(`old_urls_json`);
INSERT INTO `products` (`id`,`category_id`,`root_category`,`name`,`slug`,`sku`,`short_description`,`description_html`,`image`,`unit`,`price`,`request_hint`,`active`,`featured`,`sort_order`,`seo_title`,`seo_description`,`source_file`,`specs_json`,`gallery_json`,`old_urls_json`) VALUES (25,6,'cable','КПсПБП-120, КПсПБК-120','578-kpspbp-120-kpspbk-120','MNP-0025','КПсПБкП-120, КПсПБкК-120 – коррозионностойкое исполнение с длительно-допустимой температурой нагрева жил +120°С','<div><p>КПсПБП-120, КПсПБК-120 </p><p><strong>КПсПБкП-120, КПсПБкК-120 </strong>– коррозионностойкое исполнение <br/>с длительно-допустимой температурой нагрева жил +120°С </p><p>Кабели предназначены для подачи электрической энергии к электродвигателям установок добычи нефти, на номинальное переменное напряжение 3,3 кВ частотой 50 Гц, для эксплуатации в макроклиматических районах с умеренным и холодным климатом (УХЛ 1 и 5). </p><p><strong>Конструкция КПсПБП-120, КПсПБК-120: </strong></p><p><img alt="kektfbp140" loading="lazy" src="assets/img/products/kpspbp__8f9480813f766d6c0f7bc4c4.jpg"/></p><p><img alt="kektfbp140" loading="lazy" src="assets/img/products/kpspbk__d0c18aa637e8eb1a4b7956e8.jpg"/></p><ol><li><p>Токопроводящая жила – медная; </p></li><li><p>Изоляция - радиационно модифицированная композиция; </p></li><li><p>Изоляция - полиэтилен; </p></li><li><p>Обмотка - нетканый материал; </p></li><li><p>Броня - стальная лента </p></li></ol><p><strong>Технические характеристики КПсПБП-120, КПсПБК-120 </strong></p><table><tbody><tr><td><p>Кабели предназначены для эксплуатации в скважинной жидкости, <br/></p><p>содержащей нефть, а также воду и газ со следующими показателями: </p><p>- содержание воды </p><p>- водородный показатель попутной воды </p><p>- концентрация сероводорода не более </p><p>- гидростатическое давление не более </p><p>- газовый фактор не более </p></td><td><p>до 100% </p><p>РН 6,0-8,5 </p><p>0,01 г/л </p><p>25 МПа </p><p>500м3/м3 </p></td></tr><tr><td><p>Ток утечки при напряжении постоянного тока 18 кВ, <br/></p><p>пересчитанный на 1 км длины и t0+200С, не более: </p></td><td><p>1х10-5А </p></td></tr><tr><td><p>Электрическое сопротивление изоляции, пересчитанное <br/></p><p>на длину 1 км и t0+200С, составляет не менее </p></td><td><p>2500 МОм </p></td></tr><tr><td><p>Раздавливающее усилие кабелей не менее: </p><p>– для кабелей с жилами сечением 8 мм2 ; </p><p>– для кабелей с жилами остальных сечений. </p></td><td><p>98 кН (10 тс) </p><p>158 Кн (16 тс) </p></td></tr><tr><td><p>Кабели стойки к воздействию смены температур <br/></p><p>при неподвижной прокладке: </p></td><td><p>от - 600С до +1200С </p></td></tr><tr><td><p>Относительная влажность воздуха (при t0 +35 0С) </p></td><td><p>98% </p></td></tr><tr><td><p>Радиус изгиба кабелей при спускоподъемных и <br/></p><p>перемоточных опе­рациях не менее </p></td><td><p>380 мм </p></td></tr><tr><td><p>Спуско - подъемные и перемоточные операции с кабелем <br/></p><p>должны производиться при температуре не ниже (в условиях <br/></p><p>искусственного обогрева кабеля) </p></td><td><p>- 400С </p></td></tr><tr><td><p>Спуск кабеля в скважину и подъем из нее должны производиться <br/></p><p>плавно со скоростью не более: </p></td><td><p>0,25 м/с </p></td></tr><tr><td><p>Средний срок службы кабелей при соблюдении требований <br/></p><p>к условиям хранения и эксплуатации </p></td><td><p>5 лет </p></td></tr></tbody></table><p>Изолированные жилы кабеля продольно герметичны при перепаде давления жидкости 0,02МПа на 1 м длины. </p><p>Кабели стойки к изгибам при навивании на цилиндр диаметром, равным 15-кратному мак. диаметру кабеля. </p><p>При прохождении участков колонны труб скважины кривизной более 1,50 на 10 м и мест перехода колонны на меньший диаметр труб скорости спуска и подъема не должны быть более 0,1 м/с. </p><p>При креплении кабеля к насосно-компрессорным трубам и свинчивании труб не допускаются закручивание кабеля вокруг труб, а также перекручивание плоского кабеля относительно собственной оси. </p><p>Кабели <strong>КПсПБП-120 </strong>, <strong>КПсПБК-120 </strong>соответствуют ГОСТ Р 51777-2001 и изготавливаются по ТУ 16К13-012-2002. <br/></p><table><tbody><tr><td rowspan="4">Марка кабеля </td><td rowspan="4">Сечение, мм2 </td><td rowspan="4">Предельные размеры кабеля, мм </td><td rowspan="4">Расчетная масса кабеля кг/км </td><td colspan="3" rowspan="2">Максимальная намотка кабеля на барабан, м </td></tr><tr><td>Барабан №18 </td><td>Барабан №18 </td><td>Барабан №20 </td></tr><tr><td>деревянный </td><td>металлический </td><td>металлический </td></tr><tr><td rowspan="7">КПсПБП –120 </td><td>3х8 </td><td>13,0x32,0 </td><td>717 </td><td>2650 </td><td>3000 </td><td>4450 </td></tr><tr><td>3x10 </td><td>14,2x34,4 </td><td>878 </td><td>2450 </td><td>2700 </td><td>4000 </td></tr><tr><td>3x13,3 </td><td>14,6x35,9 </td><td>1019 </td><td>2200 </td><td>2450 </td><td>3600 </td></tr><tr><td>3x16 </td><td>15,0x37,4 </td><td>1097 </td><td>2050 </td><td>2250 </td><td>3300 </td></tr><tr><td>3x21,15 </td><td>16,2x42,5 </td><td>1352 </td><td>1650 </td><td>1850 </td><td>2750 </td></tr><tr><td>3x25 </td><td>16,2x42,5 </td><td>1509 </td><td>1350 </td><td>1500 </td><td>2300 </td></tr><tr><td>3x35 </td><td>18,0x48,2 </td><td>1823 </td><td>1150 </td><td>1300 </td><td>2000 </td></tr><tr><td rowspan="7">КПсПБК-120 </td><td>3x8 </td><td>25 </td><td>652 </td><td>2500 </td><td>2750 </td><td>4050 </td></tr><tr><td>3x10 </td><td>29 </td><td>806 </td><td>2350 </td><td>2600 </td><td>3750 </td></tr><tr><td>3x13,3 </td><td>32 </td><td>932 </td><td>2100 </td><td>2350 </td><td>3450 </td></tr><tr><td>3x16 </td><td>32 </td><td>1020 </td><td>2000 </td><td>2200 </td><td>3200 </td></tr><tr><td>3x21,15 </td><td>35,6 </td><td>1257 </td><td>1650 </td><td>2800 </td><td>2700 </td></tr><tr><td>3x25 </td><td>35,6 </td><td>1428 </td><td>1500 </td><td>1700 </td><td>2600 </td></tr><tr><td>3x35 </td><td>38,3 </td><td>1739 </td><td>1350 </td><td>1450 </td><td>2300 </td></tr></tbody></table><p>Кабель марки КПсПБП-120 