INSERT INTO `products` (`id`,`category_id`,`root_category`,`name`,`slug`,`sku`,`short_description`,`description_html`,`image`,`unit`,`price`,`request_hint`,`active`,`featured`,`sort_order`,`seo_title`,`seo_description`,`source_file`,`specs_json`,`gallery_json`,`old_urls_json`) VALUES (75,9,'cable','АКРВГ','511-akrvg','MNP-0075','Предназначены для неподвижного присоединения к электрическим приборам, аппаратам, сборкам зажимов электрических распределительных устройств с номинальным переменным напряжением до 660 Вольт, частотой до 100 Гц или постоянным напряжением до 1000.','<div><p>АКРВГ </p><p><img alt="akvbbshv" loading="lazy" src="assets/img/products/akvvg__acbaa5e44f2faa7e70d4b880.jpg"/></p><ol><li>Алюминиевая однопроволочная жила (класс 1); </li><li>Изоляция из резины, счетная пара жил в каждом повиве; </li><li>Оболочка из ПВХ пластиката. </li></ol><p><strong>Область применения АКРВГ: </strong></p><p>Предназначены для неподвижного присоединения к электрическим приборам, аппаратам, сборкам зажимов электрических распределительных устройств с номинальным переменным напряжением до 660 Вольт, частотой до 100 Гц или постоянным напряжением до 1000 Вольт. </p><p>Кабели <strong>АКРВГ </strong>применяются для прокладки на открытом воздухе, в помещениях, каналах, туннелях, в условиях агрессивной среды, при отсутствии механических воздействий на кабели. Не распространяют горение при одиночной прокладке (нормы ГОСТ 1276-89). Стойки к монтажным изгибам. </p><p><strong>Технические характеристики АКРВГ </strong><br/></p><table><tbody><tr><td>Влажность воздуха при 35° C [%] </td><td><strong>98 </strong></td></tr><tr><td>Гарантийный срок эксплуатации [месяц] </td><td><strong>36 </strong></td></tr><tr><td>Испытательное переменное напряжение частотой 50 Гц, 5 мин. [кВ] </td><td><strong>2.5 </strong></td></tr><tr><td>Максимальная рабочая температура жилы [°С] </td><td><strong>70 </strong></td></tr><tr><td>Монтаж при температуре, не ниже [°C] </td><td><strong>-15 </strong></td></tr><tr><td>Номинальное постоянное напряжение [кВ] </td><td><strong>0.66 </strong></td></tr><tr><td>Радиус изгиба кабелей [наружных диаметров] </td><td><strong>6 </strong></td></tr><tr><td>Строительная длина, не менее [м] </td><td><strong>150 </strong></td></tr><tr><td>Температура окружающей среды, верхний предел [°C] </td><td><strong>+50 </strong></td></tr><tr><td>Температура окружающей среды, нижний предел [°C] </td><td><strong>-50 </strong></td></tr></tbody></table><p>Срок службы при прокладке на открытом воздухе - 15 лет, при прокладке в помещениях, каналах и туннелях - 25лет. </p><table><tbody><tr><td><strong>Количество и сечение жил <br/>шт х кв.мм </strong></td><td><strong>Масса кабеля <br/>кг/км </strong></td><td><strong>Наружный диаметр <br/>мм </strong></td><td><strong>Сопротивление изоляции, <br/>не менее МОм х км </strong></td></tr><tr><td>АКРВГ 4x2,5 </td><td>190,7 </td><td>12,2 </td><td>60 </td></tr><tr><td>АКРВГ 5x2,5 </td><td>253,3 </td><td>13,3 </td><td>60 </td></tr><tr><td>АКРВГ 7x2,5 </td><td>277,7 </td><td>14,4 </td><td>60 </td></tr><tr><td>АКРВГ 10x2,5 </td><td>445,5 </td><td>18,6 </td><td>60 </td></tr><tr><td>АКРВГ 14x2,5 </td><td>515,9 </td><td>20,2 </td><td>60 </td></tr><tr><td>АКРВГ 19x2,5 </td><td>649,6 </td><td>22,4 </td><td>60 </td></tr><tr><td>АКРВГ 27x2,5 </td><td>923,7 </td><td>27,2 </td><td>60 </td></tr><tr><td>АКРВГ 37x2,5 </td><td>1178,0 </td><td>30,4 </td><td>60 </td></tr><tr><td>АКРВГ 4x4 </td><td>235,1 </td><td>13,4 </td><td>60 </td></tr><tr><td>АКРВГ 7x4 </td><td>346,5 </td><td>15,9 </td><td>60 </td></tr><tr><td>АКРВГ 10x4 </td><td>558,7 </td><td>20,6 </td><td>60 </td></tr><tr><td>АКРВГ 4x6 </td><td>284,6 </td><td>14,6 </td><td>60 </td></tr><tr><td>АКРВГ 7x6 </td><td>427,2 </td><td>17,4 </td><td>60 </td></tr><tr><td>АКРВГ 10x6 </td><td>677,6 </td><td>22,6 </td><td>60 </td></tr><tr><td>АКРВГ 4x10 </td><td>416,8 </td><td>17,5 </td><td>60 </td></tr></tbody></table></div>','assets/img/products/akvvg__acbaa5e44f2faa7e70d4b880.jpg','м',NULL,'Укажите марку, число и сечение жил, рабочее напряжение, длину и условия прокладки.',1,0,75,'АКРВГ — купить по заявке | Монополия','АКРВГ: подбор и поставка в Санкт-Петербурге. Укажите марку, число и сечение жил, рабочее напряжение, длину и условия прокладки. Расчет стоимости — по заявке.','site/www.monopoly-torg.ru/511-akrvg__fc91f4d75e91ace8ec72009b.html','[["Влажность воздуха при 35° C [%]", "98"], ["Гарантийный срок эксплуатации [месяц]", "36"], ["Испытательное переменное напряжение частотой 50 Гц, 5 мин. [кВ]", "2.5"], ["Максимальная рабочая температура жилы [°С]", "70"], ["Монтаж при температуре, не ниже [°C]", "-15"], ["Номинальное постоянное напряжение [кВ]", "0.66"], ["Радиус изгиба кабелей [наружных диаметров]", "6"], ["Строительная длина, не менее [м]", "150"], ["Температура окружающей среды, верхний предел [°C]", "+50"], ["Температура окружающей среды, нижний предел [°C]", "-50"]]','["assets/img/products/akvvg__acbaa5e44f2faa7e70d4b880.jpg"]','["http://www.monopoly-torg.ru/index.php/kabelnaya-produkciya/kabeli-kontrolnye/511-akrvg"]') ON DUPLICATE KEY UPDATE `category_id`=VALUES(`category_id`),`root_category`=VALUES(`root_category`),`name`=VALUES(`name`),`slug`=VALUES(`slug`),`sku`=VALUES(`sku`),`short_description`=VALUES(`short_description`),`description_html`=VALUES(`description_html`),`image`=VALUES(`image`),`unit`=VALUES(`unit`),`price`=VALUES(`price`),`request_hint`=VALUES(`request_hint`),`active`=VALUES(`active`),`featured`=VALUES(`featured`),`sort_order`=VALUES(`sort_order`),`seo_title`=VALUES(`seo_title`),`seo_description`=VALUES(`seo_description`),`source_file`=VALUES(`source_file`),`specs_json`=VALUES(`specs_json`),`gallery_json`=VALUES(`gallery_json`),`old_urls_json`=VALUES(`old_urls_json`);
INSERT INTO `products` (`id`,`category_id`,`root_category`,`name`,`slug`,`sku`,`short_description`,`description_html`,`image`,`unit`,`price`,`request_hint`,`active`,`featured`,`sort_order`,`seo_title`,`seo_description`,`source_file`,`specs_json`,`gallery_json`,`old_urls_json`) VALUES (76,9,'cable','АКРВГЭ','512-akrvge','MNP-0076','Предназначены для неподвижного присоединения к электрическим приборам, аппаратам, сборкам зажимов электрических распределительных устройств с номинальным переменным напряжением до 660 Вольт частотой до 100 Гц или постоянным напряжением до 1000 Вольт.','<div><p>АКРВГЭ </p><p><img alt="akvbbshv" loading="lazy" src="assets/img/products/akrvge__adc22a3839c858855e8b2240.jpg"/></p><ol><li>Алюминиевая однопроволочная жила (класс 1); </li><li>Изоляция из резины, наличие счетной пары в каждом повиве; </li><li>Разделительный слой из ПВХ пластиката; </li><li>Экран из алюминиевой или медной ленты; </li><li>Обмотка из полотна нетканого; </li><li>Оболочка из ПВХ пластиката. </li></ol><p><strong>Область применения АКРВГЭ: </strong></p><p>Предназначены для неподвижного присоединения к электрическим приборам, аппаратам, сборкам зажимов электрических распределительных устройств с номинальным переменным напряжением до 660 Вольт частотой до 100 Гц или постоянным напряжением до 1000 Вольт. </p><p>Применяются для прокладки на открытом воздухе, в помещениях, каналах, туннелях, в условиях агрессивной среды, при отсутствии механических воздействий на кабели и необходимости защиты электрических цепей от влияния внешних электрических полей. Не распространяют горение при одиночной прокладке (нормы ГОСТ 12176-89). Стойки к монтажным изгибам. <br/></p><p><strong>Технические характеристики АКРВГЭ </strong></p><table><tbody><tr><td>Влажность воздуха при 35° C [%] </td><td><strong>98 </strong></td></tr><tr><td>Гарантийный срок эксплуатации [месяц] </td><td><strong>36 </strong></td></tr><tr><td>Испытательное переменное напряжение частотой 50 Гц, 5 мин. [В] </td><td><strong>2500 </strong></td></tr><tr><td>Максимальная рабочая температура жилы [°С] </td><td><strong>70 </strong></td></tr><tr><td>Монтаж при температуре, не ниже [°C] </td><td><strong>-15 </strong></td></tr><tr><td>Номинальное напряжение переменного тока, частотой до 100 Гц [В] </td><td><strong>660 </strong></td></tr><tr><td>Строительная длина, не менее [м] </td><td><strong>150 </strong></td></tr><tr><td>Температура окружающей среды, верхний предел [°C] </td><td><strong>+50 </strong></td></tr><tr><td>Температура окружающей среды, нижний предел [°C] </td><td><strong>-50 </strong></td></tr></tbody></table><p>Срок службы при прокладке на открытом воздухе - 15 лет, при прокладке в помещениях, каналах и туннелях - 25лет. </p><table><tbody><tr><td><strong>Количество <br/>и сечение <br/>жил, шт х кв.мм </strong></td><td><strong>Масса <br/>кабеля, <br/>кг/км </strong></td><td><strong>Наружный <br/>диаметр, <br/>мм </strong></td></tr><tr><td>АКРВГЭ 4x2,5 </td><td>281 </td><td>15,4 </td></tr><tr><td>АКРВГЭ 5x2,5 </td><td>334 </td><td>16,5 </td></tr><tr><td>АКРВГЭ 7x2,5 </td><td>386 </td><td>17,6 </td></tr><tr><td>АКРВГЭ 10x2,5 </td><td>551 </td><td>21,8 </td></tr><tr><td>АКРВГЭ 14x2,5 </td><td>652 </td><td>23,4 </td></tr><tr><td>АКРВГЭ 19x2,5 </td><td>827 </td><td>26 </td></tr><tr><td>АКРВГЭ 27x2,5 </td><td>1090 </td><td>30,4 </td></tr><tr><td>АКРВГЭ 37x2,5 </td><td>1339 </td><td>33,6 </td></tr><tr><td>АКРВГЭ 4x4,0 </td><td>329 </td><td>16,6 </td></tr><tr><td>АКРВГЭ 7x4,0 </td><td>477 </td><td>19,5 </td></tr><tr><td>АКРВГЭ 10x4,0 </td><td>684 </td><td>24,2 </td></tr><tr><td>АКРВГЭ 4x6,0 </td><td>382 </td><td>17,8 </td></tr><tr><td>АКРВГЭ 7x6,0 </td><td>564 </td><td>21 </td></tr><tr><td>АКРВГЭ 10x6,0 </td><td>807 </td><td>26,2 </td></tr></tbody></table></div>','assets/img/products/akrvge__adc22a3839c858855e8b2240.jpg','м',NULL,'Укажите марку, число и сечение жил, рабочее напряжение, длину и условия прокладки.',1,0,76,'АКРВГЭ — купить по заявке | Монополия','АКРВГЭ: подбор и поставка в Санкт-Петербурге. Укажите марку, число и сечение жил, рабочее напряжение, длину и условия прокладки. Расчет стоимости — по заявке.','site/www.monopoly-torg.ru/512-akrvge__97c366b1e47df7d6c4ca18e3.html','[["Влажность воздуха при 35° C [%]", "98"], ["Гарантийный срок эксплуатации [месяц]", "36"], ["Испытательное переменное напряжение частотой 50 Гц, 5 мин. [В]", "2500"], ["Максимальная рабочая температура жилы [°С]", "70"], ["Монтаж при температуре, не ниже [°C]", "-15"], ["Номинальное напряжение переменного тока, частотой до 100 Гц [В]", "660"], ["Строительная длина, не менее [м]", "150"], ["Температура окружающей среды, верхний предел [°C]", "+50"], ["Температура окружающей среды, нижний предел [°C]", "-50"]]','["assets/img/products/akrvge__adc22a3839c858855e8b2240.jpg"]','["http://www.monopoly-torg.ru/index.php/kabelnaya-produkciya/kabeli-kontrolnye/512-akrvge"]') ON DUPLICATE KEY UPDATE `category_id`=VALUES(`category_id`),`root_category`=VALUES(`root_category`),`name`=VALUES(`name`),`slug`=VALUES(`slug`),`sku`=VALUES(`sku`),`short_description`=VALUES(`short_description`),`description_html`=VALUES(`description_html`),`image`=VALUES(`image`),`unit`=VALUES(`unit`),`price`=VALUES(`price`),`request_hint`=VALUES(`request_hint`),`active`=VALUES(`active`),`featured`=VALUES(`featured`),`sort_order`=VALUES(`sort_order`),`seo_title`=VALUES(`seo_title`),`seo_description`=VALUES(`seo_description`),`source_file`=VALUES(`source_file`),`specs_json`=VALUES(`specs_json`),`gallery_json`=VALUES(`gallery_json`),`old_urls_json`=VALUES(`old_urls_json`);
INSERT INTO `products` (`id`,`category_id`,`root_category`,`name`,`slug`,`sku`,`short_description`,`description_html`,`image`,`unit`,`price`,`request_hint`,`active`,`featured`,`sort_order`,`seo_title`,`seo_description`,`source_file`,`specs_json`,`gallery_json`,`old_urls_json`) VALUES (77,9,'cable','КВБбШв','513-kvbbshv','MNP-0077','Кабели КВБбШв предназначены для неподвижного присоединения к электрическим приборам, аппаратам, сборкам зажимов электрических распределительных устройств с номинальным переменным напряжением до 660 В частоты до 100 Гц или постоянным напряжением.','<div><p>КВБбШв </p><p><img alt="akvbbshv" loading="lazy" src="assets/img/products/kvbbshv__be067ee97cfb14dff0836ef7.jpg"/></p><ol><li>Медная однопроволочная токопроводящая жила круглой формы класса 1 по ГОСТ 22483; </li><li>Изоляция из поливинилхлоридного пластиката. </li><li>Изолированные жилы кабелей скручены. В каждом повиве имеется счетная пара, изолированные жилы которой отличаются по цвету друг от друга и от остальных жил; </li><li>Броня из двух стальных оцинкованных лент; </li><li>Оболочка из поливинилхлоридного пластиката; </li></ol><p><strong>Область применения КВБбШв: </strong></p><p>Кабели <strong>КВБбШв </strong>предназначены для неподвижного присоединения к электрическим приборам, аппаратам, сборкам зажимов электрических распределительных устройств с номинальным переменным напряжением до 660 В частоты до 100 Гц или постоянным напряжением до 1000 В. </p><p>Кабели <strong>КВБбШв </strong>применяются для прокладки на открытом воздухе, в помещениях, каналах, туннелях, в земле (траншеях) в условиях агрессивной среды, в местах, подверженных воздействию блуждающих токов, если кабели не подвергаются значительным растягивающим усилиям и при наличии опасности механических повреждений в ходе эксплуатации. Кабели не распространяют горение при одиночной прокладке (нормы ГОСТ 12176-89). </p><p><strong>Технические характеристики КВБбШв </strong><br/></p><table><tbody><tr><td>Влажность воздуха при 35° C [%] </td><td><strong>98 </strong></td></tr><tr><td>Гарантийный срок эксплуатации [месяц] </td><td><strong>36 </strong></td></tr><tr><td>Испытательное переменное напряжение частотой 50 Гц, 5 мин. [кВ] </td><td><strong>2.5 </strong></td></tr><tr><td>Максимальная рабочая температура жилы [°С] </td><td><strong>70 </strong></td></tr><tr><td>Монтаж при температуре, не ниже [°C] </td><td><strong>-7 </strong></td></tr><tr><td>Номинальное переменное напряжение частотой 50 Гц [кВ] </td><td><strong>0.66 </strong></td></tr><tr><td>Строительная длина, не менее [м] </td><td><strong>150 </strong></td></tr><tr><td>Температура окружающей среды, верхний предел [°C] </td><td><strong>+50 </strong></td></tr><tr><td>Температура окружающей среды, нижний предел [°C] </td><td><strong>-50 </strong></td></tr></tbody></table><p><br/><strong>Срок службы: </strong><br/>При прокладке на открытом воздухе, в земле (траншеях) не менее 15 лет <br/>При прокладке в помещениях, туннелях, каналах не менее 25 лет <br/></p><table><tbody><tr><td><strong>Количество и сечение жил <br/>шт х кв.мм </strong></td><td><strong>Масса кабеля <br/>кг/км </strong></td><td><strong>Наружный диаметр <br/>мм </strong></td><td><strong>Сопротивление изоляции, <br/>не менее МОм х км </strong></td></tr><tr><td>КВБбШв 4х0,75 </td><td>217 </td><td>11,3 </td><td>10,0 </td></tr><tr><td>КВБбШв 5х0,75 </td><td>240 </td><td>11,9 </td><td>10,0 </td></tr><tr><td>КВБбШв 7х0,75 </td><td>275 </td><td>12,5 </td><td>10,0 </td></tr><tr><td>КВБбШв 10х0,75 </td><td>348 </td><td>14,6 </td><td>10,0 </td></tr><tr><td>КВБбШв 14х0,75 </td><td>407 </td><td>15,4 </td><td>10,0 </td></tr><tr><td>КВБбШв 19х0,75 </td><td>485 </td><td>16,6 </td><td>10,0 </td></tr><tr><td>КВБбШв 27х0,75 </td><td>318 </td><td>19,0 </td><td>10,0 </td></tr><tr><td>КВБбШв 37х0,75 </td><td>758 </td><td>20,8 </td><td>10,0 </td></tr><tr><td>КВБбШв 4x1 </td><td>235 </td><td>11,6 </td><td>10,0 </td></tr><tr><td>КВБбШв 5x1 </td><td>262 </td><td>12,3 </td><td>10,0 </td></tr><tr