INSERT INTO `products` (`id`,`category_id`,`root_category`,`name`,`slug`,`sku`,`short_description`,`description_html`,`image`,`unit`,`price`,`request_hint`,`active`,`featured`,`sort_order`,`seo_title`,`seo_description`,`source_file`,`specs_json`,`gallery_json`,`old_urls_json`) VALUES (91,9,'cable','КВВГнг(А)-FRLSLTx','527-kvvgng-a-frlsltx','MNP-0091','КВВГнг(А)- FRLSLTx – кабели контрольные , не распространяющие горение , с низким дымо - и газо в ыделением , низкой токсичностью продукто в горения , с изоляцией и наружной оболочкой из ПВХ пластиката пониженной пожарной опасности, огнестойкие.','<div><p>КВВГнг(А)-FRLSLTx </p><p><strong>КВВГнг(А)- FRLSLTx </strong>– кабели контрольные , не распространяющие горение , с низким дымо - и газо в ыделением , низкой токсичностью продукто в горения , с изоляцией и наружной оболочкой из ПВХ пластиката пониженной пожарной опасности, огнестойкие. </p><p><strong>Конструкция КВВГнг(А)-FRLSLTx: </strong></p><p><img alt="akrvb" loading="lazy" src="assets/img/products/kvvgngfrls__2b624fbfd4f9ee61d776736d.jpg"/></p><ol><li>Токопроводящая жила – медная, однопроволочная, 1 класса по ГОСТ 22483-77. </li><li>Обмотка – из двух слоев слюдосодержащей ленты. </li><li>Изоляция – из ПВХ пластиката пониженной пожарной опасности, изолированные жилы имеют цифровую или цветовую маркировку всех изолированных жил, обеспечивающую возможность идентификации каждой жилы при монтаже и ремонтных работах. </li><li>Скрутка – изолированные жилы многожильных кабелей скручены. </li><li>Оболочка - из ПВХ пластиката пониженной пожарной опасности. </li></ol><table><tbody><tr><td colspan="7"><p>Номинальное сечение жилы, мм <sup>2 </sup></p></td></tr><tr><td><p>0,75 </p></td><td><p>1 </p></td><td><p>1,5 </p></td><td><p>2,5 </p></td><td><p>4 </p></td><td><p>6 </p></td><td><p>10 </p></td></tr><tr><td colspan="7"><p>Число жил в кабеле </p></td></tr><tr><td colspan="3"><p>4; 5; 7; 10; 14; 19; 27; 37; 52; 61 </p></td><td><p>4; 5; 7; 10; 14; 19; 27; 37 </p></td><td colspan="2"><p>4; 7; 10 </p></td><td><p>- </p></td></tr></tbody></table><p><strong>Применение КВВГнг(А)-FRLSLTx: </strong><br/></p><p>Кабели предназначены: </p><ul><li>для неподвижного присоединения к электрическим приборам, аппаратам, сборкам зажимов электрических распределительных устройств с номинальным переменным напряжением до 660 В частоты до 100 Гц или постоянным напряжением до 1000 В; </li><li>для групповой прокладки во взрывоопасных зонах, в зданиях и сооружениях с массовым пребыванием людей, метрополитенов, объектов АС в не гермозоны. Огнестойкие – для систем, которые должны сохранять работоспособность при пожаре; </li><li>для эксплуатации во взрывоопасных зонах класса В-1; </li><li>Класс пожарной опасности по ГОСТ Р 53315-2009. П1б.1.2.1.2 </li></ul><p><strong>Технические характеристики КВВГнг(А)-FRLSLTx: </strong><br/></p><ul><li>Климатическое исполнение УХЛ, категорий размещения 3 и 4 по ГОСТ 15150-69 </li><li>Диапазон температур эксплуатации: от -50°С до +50°С </li></ul><ul><li>Относительная влажность воздуха при температуре до +35 <sup>0 </sup>С до 98% </li><li>Прокладка без предварительного подогрева производится при температуре воздуха не ниже -15 <sup>0 </sup>С </li><li>Наименьший радиус изгиба 6 макс. наружных диаметров кабеля </li><li>Кабели не распространяют горение при групповой прокладке по категории А </li><li>Дымообразование при горении и тлении кабелей не приводит к снижению светопроницаемости в испытательной камере более чем на 50%. </li><li>Огнестойкость кабелей – не менее 180 мин. </li><li>Предельная температура нагрева жил по условию не возгорания кабеля при коротком замыкании не более 400 <sup>0 </sup>С </li><li>Кабели экологически безопасны </li><li>Строительная длина кабелей не менее 150 м </li></ul><ul><li>Срок службы – 30 лет с даты изготовления кабелей </li><li>Гарантийный срок эксплуатации 3 года с даты ввода кабелей в эксплуатацию, но не позднее 6 месяцев с даты изготовления </li><li>Срок хранения: </li></ul><p>- на открытых площадках не более 2 лет; </p><p>- под навесом не более 5 лет; </p><p>- в закрытых помещениях – не более 10 лет. </p></div>','assets/img/products/kvvgngfrls__2b624fbfd4f9ee61d776736d.jpg','м',NULL,'Укажите марку, число и сечение жил, рабочее напряжение, длину и условия прокладки.',1,0,91,'КВВГнг(А)-FRLSLTx — купить по заявке | Монополия','КВВГнг(А)-FRLSLTx: подбор и поставка в Санкт-Петербурге. Укажите марку, число и сечение жил, рабочее напряжение, длину и условия прокладки. Расчет стоимости — по заявке.','site/www.monopoly-torg.ru/527-kvvgng-a-frlsltx__df58d614750f4914ffe232e5.html','[]','["assets/img/products/kvvgngfrls__2b624fbfd4f9ee61d776736d.jpg"]','["http://www.monopoly-torg.ru/index.php/kabelnaya-produkciya/kabeli-kontrolnye/527-kvvgng-a-frlsltx"]') ON DUPLICATE KEY UPDATE `category_id`=VALUES(`category_id`),`root_category`=VALUES(`root_category`),`name`=VALUES(`name`),`slug`=VALUES(`slug`),`sku`=VALUES(`sku`),`short_description`=VALUES(`short_description`),`description_html`=VALUES(`description_html`),`image`=VALUES(`image`),`unit`=VALUES(`unit`),`price`=VALUES(`price`),`request_hint`=VALUES(`request_hint`),`active`=VALUES(`active`),`featured`=VALUES(`featured`),`sort_order`=VALUES(`sort_order`),`seo_title`=VALUES(`seo_title`),`seo_description`=VALUES(`seo_description`),`source_file`=VALUES(`source_file`),`specs_json`=VALUES(`specs_json`),`gallery_json`=VALUES(`gallery_json`),`old_urls_json`=VALUES(`old_urls_json`);
INSERT INTO `products` (`id`,`category_id`,`root_category`,`name`,`slug`,`sku`,`short_description`,`description_html`,`image`,`unit`,`price`,`request_hint`,`active`,`featured`,`sort_order`,`seo_title`,`seo_description`,`source_file`,`specs_json`,`gallery_json`,`old_urls_json`) VALUES (92,9,'cable','КВВГнг(А)-LSLTx','528-kvvgng-a-lsltx','MNP-0092','КВВГнг(А) -LSLTx – кабели контрольные , не распространяющие горение , с низким дымо - и газо в ыделением , низкой токсичностью продукто в горения , с изоляцией и наружной оболочкой из ПВХ пластиката пониженной пожарной опасности .','<div><p>КВВГнг(А)-LSLTx </p><p><strong>КВВГнг(А) -LSLTx </strong>– кабели контрольные , не распространяющие горение , с низким дымо - и газо в ыделением , низкой токсичностью продукто в горения , с изоляцией и наружной оболочкой из ПВХ пластиката пониженной пожарной опасности . <br/></p><p><img alt="akrvb" loading="lazy" src="assets/img/products/kvvg__b9bd622b2b1daaaf20ca3215.jpg"/></p><ol><li>Токопро в одящая жила – медная , однопро в олочная , 1 класса по ГОСТ 22483-77. </li><li>Изоляция – из ПВХ пластиката пониженной пожарной опасности , изолиро в анные жилы имеют цифро в ую или цветов ую маркиро в ку всех изолиро в анных жил, обеспечи в ающую в озможность идентификации каждой жилы при монтаже и ремонтных работах . </li><li>Скрутка – изолиро в анные жилы многожильных кабелей скручены . </li><li>Оболочка - из ПВХ пластиката пониженной пожарной опасности . </li></ol><table><tbody><tr><td colspan="7">Номинальное сечение жилы, мм <sup>2 </sup></td></tr><tr><td>0,75 </td><td>1 </td><td>1,5 </td><td>2,5 </td><td>4 </td><td>6 </td><td>10 </td></tr><tr><td colspan="7">Число жил в кабеле </td></tr><tr><td colspan="3">4; 5; 7; 10; 14; 19; 27; 37; 52; 61 </td><td>4; 5; 7; 10; 14; 19; 27; 37 </td><td colspan="2">4; 7; 10 </td><td>- </td></tr></tbody></table><p><strong>Применение КВВГнг(А)-LSLTx: </strong><br/></p><p>Кабели предназначены : </p><ul><li>для непод в ижного присоединения к электрическим приборам , аппаратам , сборкам зажимо в электрических распределительных устройст в с номинальным переменным напряжением до 660 В частоты до 100 Гц или постоянным напряжением до 1000 В; </li><li>для группо в ой прокладки во взрыв оопасных зонах , в зданиях и сооружениях с массо в ым пребы в анием людей , метрополитено в, объекто в АС в не гермозоны . Огнестойкие – для систем , которые должны сохранять работоспособность при пожаре ; </li><li>для эксплуатации во взрыв оопасных зонах класса В-1; </li><li>Класс пожарной опасности по ГОСТ Р 53315-2009. П1б.8.2.1.2 </li></ul><p><strong>Технические характеристики КВВГнг(А)-LSLTx: </strong><br/></p><ul><li>Климатическое исполнение УХЛ, категорий размещения 3 и 4 по ГОСТ 15150-69 </li><li>Диапазон температур эксплуатации : от -50°С до +50°С </li><li>Относительная влажность воздуха при температуре до +35 <sup>0 </sup>С до 98% </li><li>Прокладка без предварительного подогрева производится при температуре воздуха не ниже -15 <sup>0 </sup>С </li><li>Наименьший радиус изгиба 6 макс. наружных диаметров кабеля </li><li>Кабели не распространяют горение при группо в ой прокладке по категории А </li><li>Дымообразование при горении и тлении кабелей не приводит к снижению светопроницаемости в испытательной камере более чем на 50%. </li><li>Предельная температура нагрева жил по условию не возгорания кабеля при коротком замыкании не более 350 <sup>0 </sup>С </li><li>Кабели экологически безопасны </li><li>Строительная длина кабелей не менее 150 м </li><li>Срок службы – 30 лет с даты изготовления кабелей </li><li>Гарантийный срок эксплуатации 3 года с даты ввода кабелей в эксплуатацию, но не позднее 6 месяцев с даты изготовления </li><li>Срок хранения: </li></ul><p>- на открытых площадках не более 2 лет; </p><p>- под навесом не более 5 лет; </p><p>- в закрытых помещениях – не более 10 лет. </p></div>','assets/img/products/kvvg__b9bd622b2b1daaaf20ca3215.jpg','м',NULL,'Укажите марку, число и сечение жил, рабочее напряжение, длину и условия прокладки.',1,0,92,'КВВГнг(А)-LSLTx — купить по заявке | Монополия','КВВГнг(А)-LSLTx: подбор и поставка в Санкт-Петербурге. Укажите марку, число и сечение жил, рабочее напряжение, длину и условия прокладки. Расчет стоимости — по заявке.','site/www.monopoly-torg.ru/528-kvvgng-a-lsltx__eec7b7a0a4c7e3ea5e3c2bb7.html','[]','["assets/img/products/kvvg__b9bd622b2b1daaaf20ca3215.jpg"]','["http://www.monopoly-torg.ru/index.php/kabelnaya-produkciya/kabeli-kontrolnye/528-kvvgng-a-lsltx"]') ON DUPLICATE KEY UPDATE `category_id`=VALUES(`category_id`),`root_category`=VALUES(`root_category`),`name`=VALUES(`name`),`slug`=VALUES(`slug`),`sku`=VALUES(`sku`),`short_description`=VALUES(`short_description`),`description_html`=VALUES(`description_html`),`image`=VALUES(`image`),`unit`=VALUES(`unit`),`price`=VALUES(`price`),`request_hint`=VALUES(`request_hint`),`active`=VALUES(`active`),`featured`=VALUES(`featured`),`sort_order`=VALUES(`sort_order`),`seo_title`=VALUES(`seo_title`),`seo_description`=VALUES(`seo_description`),`source_file`=VALUES(`source_file`),`specs_json`=VALUES(`specs_json`),`gallery_json`=VALUES(`gallery_json`),`old_urls_json`=VALUES(`old_urls_json`);
INSERT INTO `products` (`id`,`category_id`,`root_category`,`name`,`slug`,`sku`,`short_description`,`description_html`,`image`,`unit`,`price`,`request_hint`,`active`,`featured`,`sort_order`,`seo_title`,`seo_description`,`source_file`,`specs_json`,`gallery_json`,`old_urls_json`) VALUES (93,9,'cable','КВВГнг-FRLS','529-kvvgng-frls','MNP-0093','Климатическое исполнение В, категории размещения 5 по ГОСТ 15150-69.','<div><p>КВВГнг-FRLS </p><p><img alt="akrvb" loading="lazy" src="assets/img/products/kvvgngfrls__2b624fbfd4f9ee61d776736d.jpg"/></p><ol><li>Медная однопроволочная токопроводящая жила круглой формы класса 1 по ГОСТ 22483; </li><li>Термический барьер поверх медной жилы из двух слюдосодержащих лент; </li><li>Изоляция из поливинилхлоридного пластиката пониженной пожароопасности; </li><li>Наружная оболочка из поливинилхлоридного пластиката пониженной пожароопасности. </li></ol><div><strong>КВВГнг- </strong><strong>FRLS <br/></strong>К-кабель контрольный <br/>В- изоляция из ПВХ пластиката <br/>В- оболочка из ПВХ пластиката <br/>Г-не бронированный нг- не распространяющий горение <br/>FR- от англ. Fire Resistance (сопротивление огню) <br/>LS- от англ. Low Smoke (низкое дымовыделение) <p><strong>Область применения КВВГнг-FRLS: </strong></p></div><div>Контрольные кабели <strong>КВВГнг-FRLS </strong>, огнестойкие, не распространяющие горение, с низким дымо- и газовыделением предназначены для передачи и распределения электроэнергии и электрических сигналов в стационарных электротехнических установках при переменном напряжении до 1000 В частотой до 100 Гц и постоянном напряжении до 1000 В. </div><div>Кабели <strong>КВВГнг-FRLS </strong>изготовляются для общепромышленного применения и применения в системах АС вне гермозоны и в системах АС класса 2 по классификации ОПБ 88/97 (ПНАЭ Г-01-011). </div><p>Климатическое исполнение В, категории размещения 5 по ГОСТ 15150-69. </p><p><strong>Технические характеристики КВВГнг-FRLS </strong><br/></p><table><tbody><tr><td>Влажность воздуха при 35° C [%] </td><td><strong>98 </strong></td></tr><tr><td>Испытательное переменное напряжение частотой 50 Гц, 10 мин. [кВ] </td><td><strong>3,0 </strong></td></tr><tr><td>Максимальная рабочая температура жилы [°С] </td><td><strong>70 </strong></td></tr><tr><td>Максимальное переменное напряжение частоты 50 Гц [кВ] </td><td><strong>0,72 </strong></td></tr><tr><td>Монтаж при температуре, не ниже [°C] </td><td><strong>-15 </strong></td></tr><tr><td>Номинальное переменное напряжение частотой 50 Гц [кВ] </td><td><strong>0,66 </strong></td></tr><tr><td>Радиус изгиба кабелей [наружных диаметров] </td><td><strong>3-4 </strong></td></tr><tr><td>Сопротивление изоляции при температуре +70° С, не менее [МОм х км] </td><td><strong>0,005 </strong></td></tr><tr><td>Температура окружающей среды, верхний предел [°C] </td><td><strong>+50 </strong></td></tr><tr><td>Температура окружающей среды, нижний предел [°C] </td><td><strong>-50 </strong></td></tr><tr><td>Температура токопроводящих жил при коротком замыкании [°С] </td><td><strong>160 </strong></td></tr></tbody></table><table><tbody><tr><td><strong>Количество и сечение жил, </strong></td><td><strong>Расчётная масса <br/>кабеля, кг/км </strong></td><td><strong>Расчётный наружный <br/>диаметр, мм </strong></td></tr><tr><td>шт. х мм2 </td><td></td><td></td></tr><tr><td>КВВГнг-FRLS 4х1 </td><td>176 </td><td>10,0 </td></tr><tr><td>КВВГнг-FRLS 4х1,5 </td><td>208 </td><td>10,6 </td></tr><tr><td>КВВГнг-FRLS 4х2,5 </td><td>269 </td><td>11,6 </td></tr><tr><td>КВВГнг-FRLS 4х4 </td><td>353 </td><td>13,2 </td></tr><tr><td>КВВГнг-FRLS 4х6 </td><td>431 </td><td>14,4 </td></tr><tr><td>КВВГнг-FRLS 5х1 </td><td>198 </td><td>10,8 </td></tr><tr><td>КВВГнг-FRLS 5х1,5 </td><td>253 </td><td>11,5 </td></tr><tr><td>КВВГнг-FRLS 5х2,5 </td><td>307 </td><td>12,6 </td></tr><tr><td>КВВГнг-FRLS 7х1 </td><td>243 </td><td>11,7 </td></tr><tr><td>КВВГнг-FRLS 7х1,5 </td><td>298 </td><td>12,2 </td></tr><tr><td>КВВГнг-FRLS 7х2,5 </td><td>384 </td><td>13,7 </td></tr><tr><td>КВВГнг-FRLS 7х4 </td><td>541 </td><td>14,7 </td></tr><tr><td>КВВГнг-FRLS 7х6 </td><td>698 </td><td>17,2 </td></tr><tr><td>КВВГнг-FRLS 10х1 </td><td>321 </td><td>14,6 </td></tr><tr><td>КВВГнг-FRLS 10х1,5 </td><td>399 </td><td>16,7 </td></tr><tr><td>КВВГнг-FRLS 10х2,5 </td><td>531 </td><td>17,2 </td></tr><tr><td>КВВГнг-FRLS 10х4 </td><td>751 </td><td>20,3 </td></tr><tr><td>КВВГнг-FRLS 10х6 </td><td>1008 </td><td>22,3 </td></tr><tr><td>КВВГнг-FRLS 14х1 </td><td>391 </td><td>15,8 </td></tr><tr><td>КВВГнг-FRLS 14х1,5 </td><td>493 </td><td>16,9 </td></tr><tr><td>КВВГнг-FRLS 14х2,5 </td><td>653 </td><td>18,7 </td></tr><tr><td>КВВГнг-FRLS 19х1 </td><td>489 </td><td>17,5 </td></tr><tr><td>КВВГнг-FRLS 19х1,5 </td><td>602 </td><td>19,1 </td></tr><tr><td>КВВГнг-FRLS 19х2,5 </td><td>831 </td><td>21,1 </td></tr><tr><td>КВВГнг-FRLS 27х1 </td><td>629 </td><td>21,2 </td></tr><tr><td>КВВГнг-FRLS 27х1,5 </td><td>809 </td><td>22,8 </td></tr><tr><td>КВВГнг-FRLS 27х2,5 </td><td>1169 </td><td>25,6 </td></tr><tr><td>КВВГнг-FRLS 37х1 </td><td>802 </td><td>24,1 </td></tr><tr><td>КВВГнг-FRLS 37х1,5 </td><td>1098 </td><td>25,8 </td></tr><tr><td>КВВГнг-FRLS 37х2,5 </td><td>1507 </td><td>28,6 </td></tr><tr><td>КВВГнг-FRLS 52х1 </td><td>1281 </td><td>28,1 </td></tr><tr><td>КВВГнг-FRLS 52х1,5 </td><td>1571 </td><td>32,5 </td></tr><tr><td>КВВГнг-FRLS 52х2,5 </td><td>2141 </td><td>33,6 </td></tr></tbody></table></div>','assets/img/products/kvvgngfrls__2b624fbfd4f9ee61d776736d.jpg','м',NULL,'Укажите марку, число и сечение жил, рабочее напряжение, длину и условия прокладки.',1,0,93,'КВВГнг-FRLS — купить по заявке | Монополия','КВВГнг-FRLS: подбор и поставка в Санкт-Петербурге. Укажите марку, число и сечение жил, рабочее напряжение, длину и условия прокладки. Расчет стоимости — по заявке.','site/www.monopoly-torg.ru/529-kvvgng-frls__1f39d2ba3eef66cbe199d7ae.html','[["Влажность воздуха при 35° C [%]", "98"], ["Испытательное переменное напряжение частотой 50 Гц, 10 мин. [кВ]", "3,0"], ["Максимальная рабочая температура жилы [°С]", "70"], ["Максимальное переменное напряжение частоты 50 Гц [кВ]", "0,72"], ["Монтаж при температуре, не ниже [°C]", "-15"], ["Номинальное переменное напряжение частотой 50 Гц [кВ]", "0,66"], ["Радиус изгиба кабелей [наружных диаметров]", "3-4"], ["Сопротивление изоляции при температуре +70° С, не менее [МОм х км]", "0,005"], ["Температура окружающей среды, верхний предел [°C]", "+50"], ["Температура окружающей среды, нижний предел [°C]", "-50"], ["Температура токопроводящих жил при коротком замыкании [°С]", "160"]]','["assets/img/products/kvvgngfrls__2b624fbfd4f9ee61d776736d.jpg"]','["http://www.monopoly-torg.ru/index.php/kabelnaya-produkciya/kabeli-kontrolnye/529-kvvgng-frls"]') ON DUPLICATE KEY UPDATE `category_id`=VALUES(`category_id`),`root_category`=VALUES(`root_category`),`name`=VALUES(`name`),`slug`=VALUES(`slug`),`sku`=VALUES(`sku`),`short_description`=VALUES(`short_description`),`description_html`=VALUES(`description_html`),`image`=VALUES(`image`),`unit`=VALUES(`unit`),`price`=VALUES(`price`),`request_hint`=VALUES(`request_hint`),`active`=VALUES(`active`),`featured`=VALUES(`featured`),`sort_order`=VALUES(`sort_order`),`seo_title`=VALUES(`seo_title`),`seo_description`=VALUES(`seo_description`),`source_file`=VALUES(`source_file`),`specs_json`=VALUES(`specs_json`),`gallery_json`=VALUES(`gallery_json`),`old_urls_json`=VALUES(`old_urls_json`);
INSERT INTO `products` (`id`,`category_id`,`root_category`,`name`,`slug`,`sku`,`short_description`,`description_html`,`image`,`unit`,`price`,`request_hint`,`active`,`featured`,`sort_order`,`seo_title`,`seo_description`,`source_file`,`specs_json`,`gallery_json`,`old_urls_json`) VALUES (94,9,'cable','КВВГнг-LS','530-kvvgng-ls','MNP-0094','Кабели КВВГнг-LS предназначены для неподвижного присоединения к электрическим приборам, аппаратам, сборкам зажимов электрических распределительных устройств с номинальным переменным напряжением до 660 В частоты до 100 Гц или постоянным.','<div><p>КВВГнг-LS </p><p><img alt="akrvge" loading="lazy" src="assets/img/products/kvvg__b9bd622b2b1daaaf20ca3215.jpg"/></p><ol><li>Медная однопроволочная токопроводящая жила круглой формы класса 1 по ГОСТ 22483; </li><li>Изоляция из поливинилхлоридной композиции пониженной пожароопасности. <br/>Изолированные жилы кабелей скручены. В каждом повиве имеется счетная пара, изолированные жилы которой отличаются по цвету друг от друга и от остальных жил; </li><li>Оболочка из поливинилхлоридной композиции пониженной пожароопасности. </li></ol><p><strong>Область применения КВВГнг-LS: </strong></p><p>Кабели <strong>КВВГнг-LS </strong>предназначены для неподвижного присоединения к электрическим приборам, аппаратам, сборкам зажимов электрических распределительных устройств с номинальным переменным напряжением до 660 В частоты до 100 Гц или постоянным напряжением до 1000 В. </p><p>Кабели <strong>КВВГнг-LS </strong>применяются для прокладки на открытом воздухе, в кабельных сооружениях и помещениях, в условиях агрессивной среды, при отсутствии механических воздействий на кабели, в том числе для использования в системах атомных электростанций классов 2, 3 и 4 по классификации ОПББ-88/97 (ПНАЭ Г-01-011-97). Кабели преимущественно применяются для обеспечения пожарной безопасности кабельных цепей при прокладке в пучках. Кабели не распространяют горение при прокладке в пучках (нормы ГОСТ Р МЭК 332-3-96 категории А). Снижение светопроницаемости от дымообразования при горении и тлении кабелей не более 40%. </p><p>Сопротивление проводника согласно ГОСТ 22483 <br/>Климатическое исполнение УХЛ по ГОСТ 15150-69 <br/>Категория размещения 1-5 по ГОСТ 15150-69 </p><p><strong>Радиус изгиба кабеля при прокладке </strong><br/>Кабель наружным диаметром до 10 мм. включительно не менее 3-х диаметров кабеля <br/>Кабель наружным диаметром от 10 до 25 мм. включительно не менее 4-х диаметров кабеля <br/>Кабель наружным диаметром от 25 мм. не менее 6-ти диаметров кабеля </p><p><strong>Технические характеристики КВВГнг-LS </strong></p><table><tbody><tr><td>Влажность воздуха при 35° C [%] </td><td><strong>98 </strong></td></tr><tr><td>Гарантийный срок эксплуатации [месяц] </td><td><strong>36 </strong></td></tr><tr><td>Испытательное переменное напряжение частотой 50 Гц, 5 мин. [кВ] </td><td><strong>2.5 </strong></td></tr><tr><td>Максимальная рабочая температура жилы [°С] </td><td><strong>70 </strong></td></tr><tr><td>Монтаж при температуре, не ниже [°C] </td><td><strong>0 </strong></td></tr><tr><td>Номинальное постоянное напряжение [кВ] </td><td><strong>0.66 </strong></td></tr><tr><td>Строительная длина, не менее [м] </td><td><strong>150 </strong></td></tr><tr><td>Температура окружающей среды, верхний предел [°C] </td><td><strong>+50 </strong></td></tr><tr><td>Температура окружающей среды, нижний предел [°C] </td><td><strong>-30 </strong></td></tr></tbody></table><p>Срок службы не менее 30 лет </p><table><tbody><tr><td><strong>Количество и сечение жил <br/>шт х кв.мм </strong></td><td><strong>Масса кабеля <br/>кг/км </strong></td><td><strong>Наружный диаметр <br/>мм </strong></td></tr><tr><td>КВВГнг-LS 4х1 </td><td>102 </td><td>8 </td></tr><tr><td>КВВГнг-LS 4х1,5 </td><td>141 </td><td>9,2 </td></tr><tr><td>КВВГнг-LS 4х2,5 </td><td>186 </td><td>10,1 </td></tr><tr><td>КВВГнг-LS 4х4 </td><td>265 </td><td>11,7 </td></tr><tr><td>КВВГнг-LS 4х6 </td><td>353 </td><td>12,9 </td></tr><tr><td>КВВГнг-LS 5х1 </td><td>134 </td><td>9,3 </td></tr><tr><td>КВВГнг-LS 5х1,5 </td><td>166 </td><td>10 </td></tr><tr><td>КВВГнг-LS 5х2,5 </td><td>222 </td><td>11 </td></tr><tr><td>КВВГнг-LS 7х1 </td><td>169 </td><td>10 </td></tr><tr><td>КВВГнг-LS 7х1,5 </td><td>212 </td><td>10,7 </td></tr><tr><td>КВВГнг-LS 7х2,5 </td><td>287 </td><td>11,9 </td></tr><tr><td>КВВГнг-LS 7х4 </td><td>42 </td><td>13,9 </td></tr><tr><td>КВВГнг-LS 7х6 </td><td>569 </td><td>15,4 </td></tr><tr><td>КВВГнг-LS 10х1 </td><td>227 </td><td>12,3 </td></tr><tr><td>КВВГнг-LS 10х1,5 </td><td>286 </td><td>13,3 </td></tr><tr><td>КВВГнг-LS 10х2,5 </td><td>390 </td><td>14,8 </td></tr><tr><td>КВВГнг-LS 10х4 </td><td>573 </td><td>17,5 </td></tr><tr><td>КВВГнг-LS 10х6 </td><td>800 </td><td>19,9 </td></tr><tr><td>КВВГнг-LS 14х1 </td><td>291 </td><td>13,3 </td></tr><tr><td>КВВГнг-LS 14х1,5 </td><td>371 </td><td>14,4 </td></tr><tr><td>КВВГнг-LS 14х2,5 </td><td>513 </td><td>16 </td></tr><tr><td>КВВГнг-LS 19х1 </td><td>372 </td><td>14,7 </td></tr><tr><td>КВВГнг-LS 19х1,5 </td><td>479 </td><td>15,9 </td></tr><tr><td>КВВГнг-LS 19х2,5 </td><td>669 </td><td>17,8 </td></tr><tr><td>КВВГнг-LS 27х1 </td><td>506 </td><td>17,3 </td></tr><tr><td>КВВГнг-LS 27х1,5 </td><td>677 </td><td>19,3 </td></tr><tr><td>КВВГнг-LS 27х2,5 </td><td>946 </td><td>21,5 </td></tr><tr><td>КВВГнг-LS 37х1 </td><td>683 </td><td>19,7 </td></tr><tr><td>КВВГнг-LS 37х1,5 </td><td>889 </td><td>21,5 </td></tr><tr><td>КВВГнг-LS 37х2,5 </td><td>1278 </td><td>24,5 </td></tr><tr><td>КВВГнг-LS 52х1 </td><td>923 </td><td>23 </td></tr><tr><td>КВВГнг-LS 52х1,5 </td><td>1236 </td><td>25,5 </td></tr><tr><td>КВВГнг-LS 61х1 </td><td>1088 </td><td>24,8 </td></tr><tr><td>КВВГнг-LS 61х1,5 </td><td>1424 </td><td>27 </td></tr></tbody></table></div>','assets/img/products/kvvg__b9bd622b2b1daaaf20ca3215.jpg','м',NULL,'Укажите марку, число и сечение жил, рабочее напряжение, длину и условия прокладки.',1,0,94,'КВВГнг-LS — купить по заявке | Монополия','КВВГнг-LS: подбор и поставка в Санкт-Петербурге. Укажите марку, число и сечение жил, рабочее напряжение, длину и условия прокладки. Расчет стоимости — по заявке.','site/www.monopoly-torg.ru/530-kvvgng-ls__18436161cfce0bc2f286f80c.html','[["Влажность воздуха при 35° C [%]", "98"], ["Гарантийный срок эксплуатации [месяц]", "36"], ["Испытательное переменное напряжение частотой 50 Гц, 5 мин. [кВ]", "2.5"], ["Максимальная рабочая температура жилы [°С]", "70"], ["Монтаж при температуре, не ниже [°C]", "0"], ["Номинальное постоянное напряжение [кВ]", "0.66"], ["Строительная длина, не менее [м]", "150"], ["Температура окружающей среды, верхний предел [°C]", "+50"], ["Температура окружающей среды, нижний предел [°C]", "-30"]]','["assets/img/products/kvvg__b9bd622b2b1daaaf20ca3215.jpg"]','["http://www.monopoly-torg.ru/index.php/kabelnaya-produkciya/kabeli-kontrolnye/530-kvvgng-ls"]') ON DUPLICATE KEY UPDATE `category_id`=VALUES(`category_id`),`root_category`=VALUES(`root_category`),`name`=VALUES(`name`),`slug`=VALUES(`slug`),`sku`=VALUES(`sku`),`short_description`=VALUES(`short_description`),`description_html`=VALUES(`description_html`),`image`=VALUES(`image`),`unit`=VALUES(`unit`),`price`=VALUES(`price`),`request_hint`=VALUES(`request_hint`),`active`=VALUES(`active`),`featured`=VALUES(`featured`),`sort_order`=VALUES(`sort_order`),`seo_title`=VALUES(`seo_title`),`seo_description`=VALUES(`seo_description`),`source_file`=VALUES(`source_file`),`specs_json`=VALUES(`specs_json`),`gallery_json`=VALUES(`gallery_json`),`old_urls_json`=VALUES(`old_urls_json`);
INSERT INTO `products` (`id`,`category_id`,`root_category`,`name`,`slug`,`sku`,`short_description`,`description_html`,`image`,`unit`,`price`,`request_hint`,`active`,`featured`,`sort_order`,`seo_title`,`seo_description`,`source_file`,`specs_json`,`gallery_json`,`old_urls_json`) VALUES (95,9,'cable','КВВГЭ','531-kvvge','MNP-0095','Кабели КВВГЭ предназначены для неподвижного присоединения к электрическим приборам, аппаратам, сборкам зажимов электрических распределительных устройств с номинальным переменным напряжением до 660 В частоты до 100 Гц или постоянным напряжением до.','<div><p>КВВГЭ </p><p><img alt="akrvb" loading="lazy" src="assets/img/products/kvvge__70f66de6537fdd4dfab236fb.jpg"/></p><ol><li>Медная однопроволочная токопроводящая жила круглой формы класса 1 по ГОСТ 22483; </li><li>Изоляция из поливинилхлоридного пластиката. <br/>Изолированные жилы кабелей скручены. В каждом повиве имеется счетная пара, изолированные жилы которой отличаются по цвету друг от друга и от остальных жил; </li><li>Разделительный слой в виде оболочки из поливинилхлоридного пластиката толщиной не менее 0,5 мм или в виде обмотки лентами из полиэтилентерефталатной пленки; </li><li>Экран в виде обмотки из медной или алюминиевой фольги с перекрытием, обеспечивающим сплошность экрана при допустимых радиусах изгиба кабелей. Вдоль экрана из алюминиевой фольги продольно прокладывается медная проволока; </li><li>Разделительный слой в виде обмотки лентами, обеспечивающий сохранность экрана при монтаже кабелей; </li><li>Оболочка из поливинилхлоридного пластиката. </li></ol><p><strong>Область применения КВВГЭ: </strong></p><p>Кабели <strong>КВВГЭ </strong>предназначены для неподвижного присоединения к электрическим приборам, аппаратам, сборкам зажимов электрических распределительных устройств с номинальным переменным напряжением до 660 В частоты до 100 Гц или постоянным напряжением до 1000 В. </p><p>Кабели <strong>КВВГЭ </strong>применяются для прокладки на открытом воздухе, в помещениях, каналах, туннелях, в условиях агрессивной среды, при отсутствии механических воздействий на кабели. Кабели преимущественно применяются при необходимости защиты электрических цепей от влияния внешних электрических полей. Кабели не распространяют горение при одиночной прокладке (нормы ГОСТ 12176-89). </p><p>Сопротивление проводника согласно ГОСТ 22483 <br/>Климатическое исполнение УХЛ по ГОСТ 15150-69 <br/>Категория размещения 1-5 по ГОСТ 15150-69 </p><p><strong>Радиус изгиба кабеля при прокладке: </strong><br/>Кабель наружным диаметром до 10 мм. включительно не менее 3-х диаметров кабеля <br/>Кабель наружным диаметром от 10 до 25 мм. вк лючительно не менее 4-х диаметров кабеля <br/>Кабель наружным диаметром от 25 мм. не менее 6-ти диаметров кабеля </p><p><strong><br/><strong>Технические характеристики КВВГЭ </strong><br/></strong></p><table><tbody><tr><td>Влажность воздуха при 35° C [%] </td><td><strong>98 </strong></td></tr><tr><td>Гарантийный срок эксплуатации [месяц] </td><td><strong>36 </strong></td></tr><tr><td>Испытательное переменное напряжение частотой 50 Гц, 5 мин. [кВ] </td><td><strong>2.5 </strong></td></tr><tr><td>Максимальная рабочая температура жилы [°С] </td><td><strong>70 </strong></td></tr><tr><td>Монтаж при температуре, не ниже [°C] </td><td><strong>0 </strong></td></tr><tr><td>Номинальное постоянное напряжение [кВ] </td><td><strong>0.66 </strong></td></tr><tr><td>Строительная длина, не менее [м] </td><td><strong>150 </strong></td></tr><tr><td>Температура окружающей среды, верхний предел [°C] </td><td><strong>+50 </strong></td></tr><tr><td>Температура окружающей среды, нижний предел [°C] </td><td><strong>-50 </strong></td></tr></tbody></table><p><strong>Срок службы: </strong><br/>При прокладке на открытом воздухе не менее 15 лет <br/>При прокладке в помещениях, туннелях, каналах не менее 25 лет </p><table><tbody><tr><td><strong>Количество и сечение жил <br/>шт х кв.мм </strong></td><td><strong>Масса кабеля <br/>кг/км </strong></td><td><strong>Наружный диаметр <br/>мм </strong></td><td><strong>Сопротивление <br/>изоляции, <br/>не менее МОм х км </strong></td></tr><tr><td>КВВГЭ 4x0,75 </td><td>104 </td><td>9,2 </td><td>10,0 </td></tr><tr><td>КВВГЭ 5x0,75 </td><td>119 </td><td>9,8 </td><td>10,0 </td></tr><tr><td>КВВГЭ 7x0,75 </td><td>145 </td><td>10,4 </td><td>10,0 </td></tr><tr><td>КВВГЭ 10x0,75 </td><td>191 </td><td>12,5 </td><td>10,0 </td></tr><tr><td>КВВГЭ 14x0,75 </td><td>239 </td><td>13,3 </td><td>10,0 </td></tr><tr><td>КВВГЭ 19x0,75 </td><td>299 </td><td>14,5 </td><td>10,0 </td></tr><tr><td>КВВГЭ 27x0,75 </td><td>401 </td><td>16,9 </td><td>10,0 </td></tr><tr><td>КВВГЭ 37x0,75 </td><td>534 </td><td>19,1 </td><td>10,0 </td></tr><tr><td>КВВГЭ 4x1 </td><td>117 </td><td>9,5 </td><td>10,0 </td></tr><tr><td>КВВГЭ 5x1 </td><td>136 </td><td>10,2 </td><td>10,0 </td></tr><tr><td>КВВГЭ 7x1 </td><td>167 </td><td>10,8 </td><td>10,0 </td></tr><tr><td>КВВГЭ 10x1 </td><td>221 </td><td>13,1 </td><td>10,0 </td></tr><tr><td>КВВГЭ 14x1 </td><td>280 </td><td>14,0 </td><td>10,0 </td></tr><tr><td>КВВГЭ 19x1 </td><td>354 </td><td>15,3 </td><td>10,0 </td></tr><tr><td>КВВГЭ 27x1 </td><td>494 </td><td>18,2 </td><td>10,0 </td></tr><tr><td>КВВГЭ 37x1 </td><td>638 </td><td>20,1 </td><td>10,0 </td></tr><tr><td>КВВГЭ 4x1,5 </td><td>141 </td><td>10,1 </td><td>10,0 </td></tr><tr><td>КВВГЭ 5x1,5 </td><td>164 </td><td>10,8 </td><td>10,0 </td></tr><tr><td>КВВГЭ 7x1,5 </td><td>206 </td><td>11,5 </td><td>10,0 </td></tr><tr><td>КВВГЭ 10x1,5 </td><td>274 </td><td>14,0 </td><td>10,0 </td></tr><tr><td>КВВГЭ 14x1,5 </td><td>352 </td><td>15,0 </td><td>10,0 </td></tr><tr><td>КВВГЭ 19x1,5 </td><td>450 </td><td>16,4 </td><td>10,0 </td></tr><tr><td>КВВГЭ 27x1,5 </td><td>629 </td><td>19,6 </td><td>10,0 </td></tr><tr><td>КВВГЭ 37x1,5 </td><td>821 </td><td>21,7 </td><td>10,0 </td></tr><tr><td>КВВГЭ 4x2,5 </td><td>187 </td><td>11,0 </td><td>9,0 </td></tr><tr><td>КВВГЭ 5x2,5 </td><td>221 </td><td>11,8 </td><td>9,0 </td></tr><tr><td>КВВГЭ 7x2,5 </td><td>283 </td><td>1