INSERT INTO `products` (`id`,`category_id`,`root_category`,`name`,`slug`,`sku`,`short_description`,`description_html`,`image`,`unit`,`price`,`request_hint`,`active`,`featured`,`sort_order`,`seo_title`,`seo_description`,`source_file`,`specs_json`,`gallery_json`,`old_urls_json`) VALUES (96,9,'cable','КВВГЭ-ХЛ','532-kvvge-khl','MNP-0096','Кабели контрольные, экранированные, предназначены для фиксированного присоединения к электрическим приборам, аппаратам, сборкам зажимов электрических распределительных устройств с номинальным переменным напряжением до 660 В частоты до 100 Гц или.','<div><p>КВВГЭ-ХЛ </p><p><img alt="akrvb" loading="lazy" src="assets/img/products/kvvge__70f66de6537fdd4dfab236fb.jpg"/></p><h2><strong>Область применения КВВГЭ-ХЛ <br/></strong></h2><p>Кабели контрольные, экранированные, предназначены для фиксированного присоединения к электрическим приборам, аппаратам, сборкам зажимов электрических распределительных устройств с номинальным переменным напряжением до 660 В частоты до 100 Гц или постоянным напряжением до 1000 В. </p><h2><strong>Конструкция КВВГЭ-ХЛ <br/></strong></h2><ol><li>Жила: 1 класса из медных проволок, круглой формы; Число жил: 4-61, Сечение 0,75-6,0 мм <sup>2 </sup></li><li>Изоляция: ПВХ - пластикат с температурой хрупкости минус 60 <sup>о </sup>С </li><li>Разделительный слой: ПВХ - пластикат с температурой хрупкости минус 65 <sup>о </sup>С </li><li>Экран алюминиевая фольга </li><li>Оболочка ПВХ - пластикат с температурой хрупкости минус 65 <sup>о </sup>С. </li></ol><h2><strong>Технико-эксплуатационные характеристики кабелей КВВГЭ-ХЛ </strong></h2><ul><li>Номинальное переменное напряжение частоты 50 Гц, кВ 0,66 </li><li>Испытательное переменное напряжение 50Гц 10 мин, кВ 2,5 </li><li>Температура окружающей среды, <sup>о </sup>С -60/+50 </li><li>Кабели морозостойкие, не распространяют горение при одиночной прокладке. </li></ul></div>','assets/img/products/kvvge__70f66de6537fdd4dfab236fb.jpg','м',NULL,'Укажите марку, число и сечение жил, рабочее напряжение, длину и условия прокладки.',1,0,96,'КВВГЭ-ХЛ — купить по заявке | Монополия','КВВГЭ-ХЛ: подбор и поставка в Санкт-Петербурге. Укажите марку, число и сечение жил, рабочее напряжение, длину и условия прокладки. Расчет стоимости — по заявке.','site/www.monopoly-torg.ru/532-kvvge-khl__278c4c328ef991b2b4fbdf3c.html','[]','["assets/img/products/kvvge__70f66de6537fdd4dfab236fb.jpg"]','["http://www.monopoly-torg.ru/index.php/kabelnaya-produkciya/kabeli-kontrolnye/532-kvvge-khl"]') ON DUPLICATE KEY UPDATE `category_id`=VALUES(`category_id`),`root_category`=VALUES(`root_category`),`name`=VALUES(`name`),`slug`=VALUES(`slug`),`sku`=VALUES(`sku`),`short_description`=VALUES(`short_description`),`description_html`=VALUES(`description_html`),`image`=VALUES(`image`),`unit`=VALUES(`unit`),`price`=VALUES(`price`),`request_hint`=VALUES(`request_hint`),`active`=VALUES(`active`),`featured`=VALUES(`featured`),`sort_order`=VALUES(`sort_order`),`seo_title`=VALUES(`seo_title`),`seo_description`=VALUES(`seo_description`),`source_file`=VALUES(`source_file`),`specs_json`=VALUES(`specs_json`),`gallery_json`=VALUES(`gallery_json`),`old_urls_json`=VALUES(`old_urls_json`);
INSERT INTO `products` (`id`,`category_id`,`root_category`,`name`,`slug`,`sku`,`short_description`,`description_html`,`image`,`unit`,`price`,`request_hint`,`active`,`featured`,`sort_order`,`seo_title`,`seo_description`,`source_file`,`specs_json`,`gallery_json`,`old_urls_json`) VALUES (97,9,'cable','КВВГЭнг','533-kvvgeng','MNP-0097','Кабели КВВГЭнг предназначены для неподвижного присоединения к электрическим приборам, аппаратам, сборкам зажимов электрических распределительных устройств с номинальным переменным напряжением до 660 В частоты до 100 Гц или постоянным напряжением.','<div><p>КВВГЭнг </p><p><img alt="akrvb" loading="lazy" src="assets/img/products/kvvge__70f66de6537fdd4dfab236fb.jpg"/></p><ol><li>Медная однопроволочная токопроводящая жила круглой формы класса 1 по ГОСТ 22483; </li><li>Изоляция из поливинилхлоридного пластиката. <br/>Изолированные жилы кабелей скручены. В каждом повиве имеется счетная пара, изолированные жилы которой отличаются по цвету друг от друга и от остальных жил; </li><li>Разделительный слой в виде оболочки из поливинилхлоридного пластиката пониженной горючести толщиной не менее 0,5 мм; </li><li>Экран в виде обмотки из медной или алюминиевой фольги с перекрытием, обеспечивающим сплошность экрана при допустимых радиусах изгиба кабелей. Вдоль экрана из алюминиевой фольги продольно прокладывается медная проволока; </li><li>Разделительный слой в виде обмотки лентами, обеспечивающий сохранность экрана при монтаже кабелей; </li><li>Оболочка из поливинилхлоридного пластиката пониженной горючести. </li></ol><p><strong>Оптовые цены на КВВГЭнг </strong><strong><br/></strong></p><p><strong>Область применения КВВГЭнг: </strong></p><p>Кабели <strong>КВВГЭнг </strong>предназначены для неподвижного присоединения к электрическим приборам, аппаратам, сборкам зажимов электрических распределительных устройств с номинальным переменным напряжением до 660 В частоты до 100 Гц или постоянным напряжением до 1000 В. </p><p>Кабели <strong>КВВГЭнг </strong>применяются для прокладки на открытом воздухе, в помещениях, каналах, туннелях, в условиях агрессивной среды, при отсутствии механических воздействий на кабели. Кабели преимущественно применяются при необходимости защиты электрических цепей от влияния внешних электрических полей и для обеспечения пожарной безопасности кабельных цепей при прокладке в пучках. Кабели не распространяют горение при прокладке в пучках (нормы ГОСТ Р МЭК 332-3-96 категории А). </p><p>Сопротивление проводника согласно ГОСТ 22483 <br/>Климатическое исполнение УХЛ по ГОСТ 15150-69 <br/>Категория размещения 1-5 по ГОСТ 15150-69 </p><p><strong>Радиус изгиба кабеля КВВГЭнг при прокладке: </strong><br/>Для кабеля наружным диаметром до 10 мм. включительно не менее 3-х диаметров кабеля <br/>Для кабеля наружным диаметром от 10 до 25 мм. включительно не менее 4-х диаметров кабеля <br/>Для кабеля наружным диаметром от 25 мм. не менее 6-ти диаметров кабеля </p><p><strong>Технические характеристики КВВГЭнг </strong></p><table><tbody><tr><td>Влажность воздуха при 35° C [%] </td><td><strong>98 </strong></td></tr><tr><td>Гарантийный срок эксплуатации [месяц] </td><td><strong>36 </strong></td></tr><tr><td>Испытательное переменное напряжение частотой 50 Гц, 5 мин. [кВ] </td><td><strong>2.5 </strong></td></tr><tr><td>Максимальная рабочая температура жилы [°С] </td><td><strong>70 </strong></td></tr><tr><td>Монтаж при температуре, не ниже [°C] </td><td><strong>0 </strong></td></tr><tr><td>Номинальное постоянное напряжение [кВ] </td><td><strong>0.66 </strong></td></tr><tr><td>Строительная длина, не менее [м] </td><td><strong>150 </strong></td></tr><tr><td>Температура окружающей среды, верхний предел [°C] </td><td><strong>+50 </strong></td></tr><tr><td>Температура окружающей среды, нижний предел [°C] </td><td><strong>-50 </strong></td></tr></tbody></table><p><strong>Срок службы: <br/></strong>При прокладке на открытом воздухе не менее 15 лет <br/>При прокладке в помещениях, туннелях, каналах не менее 25 лет </p><table><tbody><tr><td><strong>Количество и сечение жил <br/>шт х кв.мм </strong></td><td><strong>Масса кабеля <br/>кг/км </strong></td><td><strong>Наружный диаметр <br/>мм </strong></td><td><strong>Сопротивление <br/>изоляции, <br/>не менее МОм х км </strong></td></tr><tr><td>КВВГЭнг 4x0,75 </td><td>152 </td><td>11,1 </td><td>10,0 </td></tr><tr><td>КВВГЭнг 5x0,75 </td><td>171 </td><td>11,7 </td><td>10,0 </td></tr><tr><td>КВВГЭнг 7x0,75 </td><td>200 </td><td>12,3 </td><td>10,0 </td></tr><tr><td>КВВГЭнг 10x0,75 </td><td>256 </td><td>14,4 </td><td>10,0 </td></tr><tr><td>КВВГЭнг 14x0,75 </td><td>309 </td><td>15,2 </td><td>10,0 </td></tr><tr><td>КВВГЭнг 19x0,75 </td><td>376 </td><td>16,5 </td><td>10,0 </td></tr><tr><td>КВВГЭнг 27x0,75 </td><td>508 </td><td>19,2 </td><td>10,0 </td></tr><tr><td>КВВГЭнг 37x0,75 </td><td>635 </td><td>21,0 </td><td>10,0 </td></tr><tr><td>КВВГЭнг 4x1 </td><td>168 </td><td>11,5 </td><td>10,0 </td></tr><tr><td>КВВГЭнг 5x1 </td><td>189 </td><td>12,1 </td><td>10,0 </td></tr><tr><td>КВВГЭнг 7x1 </td><td>225 </td><td>12,8 </td><td>10,0 </td></tr><tr><td>КВВГЭнг 10x1 </td><td>290 </td><td>15,0 </td><td>10,0 </td></tr><tr><td>КВВГЭнг 14x1 </td><td>353 </td><td>15,9 </td><td>10,0 </td></tr><tr><td>КВВГЭнг 19x1 </td><td>435 </td><td>17,2 </td><td>10,0 </td></tr><tr><td>КВВГЭнг 27x1 </td><td>590 </td><td>20,2 </td><td>10,0 </td></tr><tr><td>КВВГЭнг 37x1 </td><td>745 </td><td>22,0 </td><td>10,0 </td></tr><tr><td>КВВГЭнг 4x1,5 </td><td>194 </td><td>12,0 </td><td>10,0 </td></tr><tr><td>КВВГЭнг 5x1,5 </td><td>221 </td><td>12,7 </td><td>10,0 </td></tr><tr><td>КВВГЭнг 7x1,5 </td><td>267 </td><td>13,5 </td><td>10,0 </td></tr><tr><td>КВВГЭнг 10x1,5 </td><td>348 </td><td>15,9 </td><td>10,0 </td></tr><tr><td>КВВГЭнг 14x1,5 </td><td>431 </td><td>16,9 </td><td>10,0 </td></tr><tr><td>КВВГЭнг 19x1,5 </td><td>555 </td><td>18,8 </td><td>10,0 </td></tr><tr><td>КВВГЭнг 27x1,5 </td><td>733 </td><td>21,6 </td><td>10,0 </td></tr><tr><td>КВВГЭнг 37x1,5 </td><td>1049 </td><td>25,7 </t