INSERT INTO `products` (`id`,`category_id`,`root_category`,`name`,`slug`,`sku`,`short_description`,`description_html`,`image`,`unit`,`price`,`request_hint`,`active`,`featured`,`sort_order`,`seo_title`,`seo_description`,`source_file`,`specs_json`,`gallery_json`,`old_urls_json`) VALUES (102,9,'cable','КВКбШв','538-kvkbshv','MNP-0102','Кабели контрольные с защитным покровом КбШв предназначены для фиксированного присоединения к электрическим приборам, аппаратам, сборкам зажимов электрических распределительных устройств с номинальным переменным напряжением до 660 В частоты до 100.','<div><p>КВКбШв </p><p><img alt="akrvb" loading="lazy" src="assets/img/products/kvbbshv__be067ee97cfb14dff0836ef7.jpg"/></p><h2>Область применения КВКбШв <br/></h2><p>Кабели контрольные с защитным покровом КбШв предназначены для фиксированного присоединения к электрическим приборам, аппаратам, сборкам зажимов электрических распределительных устройств с номинальным переменным напряжением до 660 В частоты до 100 Гц или постоянным напряжением до 1000 В . </p><h2>Конструкция КВКбШв <br/></h2><ol><li>Жила: 1-2 класса из медных проволок, круглой формы; Число жил: 4-61; Сечение 0,75-6,0 мм <sup>2 </sup></li><li>Изоляция: ПВХ -пластикат </li><li>Поясная изоляция: экструдированная из ПВХ - пластиката </li><li>Броня стальные оцинкованные проволоки для покрова КбШв </li><li>Защитный шланг ПВХ - пластикат </li></ol><h2>Технико-эксплуатационные характеристики кабелей КВКбШв <br/></h2><ul><li>Номинальное переменное напряжение частоты 50 Гц, кВ 0,66 </li><li>Испытательное переменное напряжение 50Гц 10 мин, кВ 2,5 </li><li>Температура окружающей среды, <sup>о </sup>С -50/+50 </li></ul><p><strong>Кабели не распространяют горение при одиночной прокладке. </strong></p></div>','assets/img/products/kvbbshv__be067ee97cfb14dff0836ef7.jpg','м',NULL,'Укажите марку, число и сечение жил, рабочее напряжение, длину и условия прокладки.',1,0,102,'КВКбШв — купить по заявке | Монополия','КВКбШв: подбор и поставка в Санкт-Пет