INSERT INTO `products` (`id`,`category_id`,`root_category`,`name`,`slug`,`sku`,`short_description`,`description_html`,`image`,`unit`,`price`,`request_hint`,`active`,`featured`,`sort_order`,`seo_title`,`seo_description`,`source_file`,`specs_json`,`gallery_json`,`old_urls_json`) VALUES (103,9,'cable','КВКбШв-ХЛ','539-kvkbshv-khl','MNP-0103','Кабели контрольные с защитным покровом БбШв или КбШв предназначены для фиксированного присоединения к электрическим приборам, аппаратам, сборкам зажимов электрических распределительных устройств с номинальным переменным напряжением до 660 В.','<div><p>КВКбШв-ХЛ </p><p><img alt="akvbbshv" loading="lazy" src="assets/img/products/kvbbshv__be067ee97cfb14dff0836ef7.jpg"/></p><h2><strong>Область применения КВКбШв-ХЛ <br/></strong></h2><p>Кабели контрольные с защитным покровом БбШв или КбШв предназначены для фиксированного присоединения к электрическим приборам, аппаратам, сборкам зажимов электрических распределительных устройств с номинальным переменным напряжением до 660 В частоты до 100 Гц или постоянным напряжением до 1000В. </p><h2><strong>Конструкция КВКбШв-ХЛ <br/></strong></h2><ol><li>Жила: 1-2 класса из медных проволок, круглой формы; Число жил: 4-61; Сечение 0,75-6,0 мм <sup>2 </sup></li><li>Изоляция: ПВХ - пластикат с температурой хрупкости минус 60 <sup>о </sup>С </li><li>Поясная изоляция: экструдированная из ПВХ - пластиката с температурой хрупкости минус 65 <sup>о </sup>С </li><li>Броня стальные оцинкованные ленты для покрова БбШв и стальные оцинкованные проволоки для покрова КбШв </li><li>Защитный шланг ПВХ - пластикат с температурой хрупкости минус 65 <sup>о </sup>С </li></ol><h2><strong>Технико-эксплуатационные характеристики кабелей КВКбШв-ХЛ </strong></h2><ul><li>Номинальное переменное напряжение частоты 50 Гц, кВ 0,66 </li><li>Испытательное переменное напряжение 50Гц 10 мин, кВ 2,5 </li><li>Температура окружающей среды, <sup>о </sup>С -60/+50 </li><li>Кабели морозостойкие, не распространяют горение при одиночной прокладке. <br/></li></ul><h2><strong>Табличные данные кабелей КВКбШв-ХЛ </strong></h2><table><tbody><tr><td colspan="3"><strong>Число жил и номинальное сечение </strong></td><td><strong>Расчетный диаметр кабеля, мм </strong></td><td><strong>Расчетная масса кабеля, кг/км </strong></td></tr><tr><td>4 </td><td>х </td><td>0,75 </td><td>10,9 </td><td>199 </td></tr><tr><td>5 </td><td>х </td><td>0,75 </td><td>11,5 </td><td>221 </td></tr><tr><td>7 </td><td>х </td><td>0,75 </td><td>12,2 </td><td>256 </td></tr><tr><td>10 </td><td>х </td><td>0,75 </td><td>14,4 </td><td>337 </td></tr><tr><td>14 </td><td>х </td><td>0,75 </td><td>15,3 </td><td>393 </td></tr><tr><td>19 </td><td>х </td><td>0,75 </td><td>16,5 </td><td>468 </td></tr><tr><td>27 </td><td>х </td><td>0,75 </td><td>18,8 </td><td>596 </td></tr><tr><td>37 </td><td>х </td><td>0,75 </td><td>20,5 </td><td>730 </td></tr><tr><td>52 </td><td>х </td><td>0,75 </td><td>23,5 </td><td>943 </td></tr><tr><td>61 </td><td>х </td><td>0,75 </td><td>24,7 </td><td>1056 </td></tr><tr><td>4 </td><td>х </td><td>1 </td><td>11,3 </td><td>216 </td></tr><tr><td>5 </td><td>х </td><td>1 </td><td>11,9 </td><td>243 </td></tr><tr><td>7 </td><td>х </td><td>1 </td><td>12,7 </td><td>283 </td></tr><tr><td>10 </td><td>х </td><td>1 </td><td>15 </td><td>375 </td></tr><tr><td>14 </td><td>х </td><td>1 </td><td>15,9 </td><td>443 </td></tr><tr><td>19 </td><td>х </td><td>1 </td><td>17,2 </td><td>532 </td></tr><tr><td>27 </td><td>х </td><td>1 </td><td>19,7 </td><td>684 </td></tr><tr><td>37 </td><td>х </td><td>1 </td><td>21,7 </td><td>851 </td></tr><tr><td>52 </td><td>х </td><td>1 </td><td>24,7 </td><td>1101 </td></tr><tr><td>61 </td><td>х </td><td>1 </td><td>26,4 </td><td>1261 </td></tr><tr><td>4 </td><td>х </td><td>1,5 </td><td>11,9 </td><td>249 </td></tr><tr><td>5 </td><td>х </td><td>1,5 </td><td>12,7 </td><td>284 </td></tr><tr><td>7 </td><td>х </td><td>1,5 </td><td>13,4 </td><td>333 </td></tr><tr><td>10 </td><td>х </td><td>1,5 </td><td>16 </td><td>445 </td></tr><tr><t