INSERT INTO `products` (`id`,`category_id`,`root_category`,`name`,`slug`,`sku`,`short_description`,`description_html`,`image`,`unit`,`price`,`request_hint`,`active`,`featured`,`sort_order`,`seo_title`,`seo_description`,`source_file`,`specs_json`,`gallery_json`,`old_urls_json`) VALUES (110,9,'cable','КПоЭПЭнг-FRHF','546-kpoepeng-frhf','MNP-0110','(индекс FR в марках кабелей означает огнестойкость (Fire Resistans) (индекс HF в марках кабелей означает не содержащий галогенов (Halogen-Free)','<div><p>КПоЭПЭнг-FRHF </p><p>(индекс FR в марках кабелей означает огнестойкость (Fire Resistans) <br/>(индекс HF в марках кабелей означает не содержащий галогенов (Halogen-Free) </p><p>Кабели контрольные, не распространяющие горение и огнестойкие, предназначены для передачи электрических сигналов и распределения энергии в стационарных электротехнических установках при переменном напряжении до 660В частотой до 100Гц и постоянном напряжении до 1000В при эксплуатации внутри гермозоны АС в системах АС классов 2У, 2О по классификации ОПБ 88/97(ПНАЭ Г 01-011-97). Климатическое исполнение УХЛ и Т, категория размещения 5 по ГОСТ 15150-69. </p><p><img alt="akrvb" loading="lazy" src="assets/img/products/kpoehpeng-frhf__38043e850edd17ff00812a03.jpg"/></p><ol><li>Токопроводящая жила – медная проволока. </li><li>Обмотка – стеклослюденитовая лента (КПоЭПЭнг-FRHF). </li><li>Изоляция – полимерная композиция не содержащая галогенов. </li><li>Экран – оплетка из медной проволоки </li><li>Обмотка – полиэтилентерафталатная лента или полиимидная пленка. </li><li>Внутренняя экструдированная оболочка - полимерная композиция не содержащая галогенов. </li><li>Общий экран – обмотка медной лентой. </li><li>Наружная оболочка - полимерная композиция не содержащая галогенов. </li></ol><p><strong>Технические и эксплуатационные характеристики КПоЭПЭнг-FRHF </strong><br/></p><p>Электрическая безопасность – ГОСТ 12.2.007.14-75. </p><p>Нераспространение горения – ГОСТ Р12176-89 (ГОСТ Р МЭК 332-3-96) категория А. </p><table><tbody><tr><td>Температура окружающей среды при эксплуатации: </td><td>от +60 <sup>0 </sup>С до -50 <sup>0 </sup>С </td></tr><tr><td>Относительная влажность воздуха (при t <sup>0 </sup>+35 <sup>0 </sup>С) </td><td>98% </td></tr><tr><td>Длительно допустимая t <sup>0 </sup>нагрева жил при эксплуатации </td><td>+90 <sup>0 </sup>С </td></tr><tr><td>Максимально допустимая t <sup>0 </sup>жил при коротком замыкании (4 сек.) </td><td>+250 <sup>0 </sup>С <br/></td></tr><tr><td>Минимальная t <sup>0 </sup>прокладки кабеля без предварительного подогрева </td><td>- 15 <sup>0 </sup>С </td></tr><tr><td>Предельная t <sup>0 </sup>токопроводящих жил кабелей по условию невозгорания кабеля при коротком замыкании </td><td>+400 <sup>0 </sup>С </td></tr><tr><td>Содержание газов галогеносодержащих кислот в пересчете на HCl : </td><td>5,0 мг/г </td></tr><tr><td>Показатель pH (кислотное число): </td><td>4,3 </td></tr><tr><td>Снижение светопроницаемости при горении и тлении </td><td>не более 40%. </td></tr><tr><td>Огнестойкость кабеля <strong>КПоЭПЭнг-FRHF </strong>не менее: </td><td>90 мин. </td></tr><tr><td>Минимально допустимый радиус изгиба при прокладке: </td><td>6 диам. кабеля </td></tr><tr><td>Срок службы </td><td>30 лет </td></tr><tr><td>Гарантийный срок эксплуатации </td><td>3 года </td></tr></tbody></table><p><strong>Кабель стойкий к специальным воздействиям (test LOCA). </strong></p><p>Кабели не являются опасными в экологическом отношении и специальных требований по утилизации кабелей при выводе их эксплуатации, кроме предусмотренных в действующей на АС документации, не предъявляется. </p><p><strong>Кабели соответствуют требованиям ТУ 16.К71-320-2002 </strong></p><table><tbody><tr><td><strong>Число жил, сечение, мм <sup>2 </sup></strong></td><td><strong>Номинальный наружный диаметр, мм </strong></td><td><strong>Расчетная масса, кг/км </strong></td></tr><tr><td>КПоЭПЭнг-FRHF 7х0,75 </td><td>19,3 </td><td>562 </td></tr><tr><td>КПоЭПЭнг-FRHF 4x1 </td><td>17,3 </td><td>435 </td>