INSERT INTO `products` (`id`,`category_id`,`root_category`,`name`,`slug`,`sku`,`short_description`,`description_html`,`image`,`unit`,`price`,`request_hint`,`active`,`featured`,`sort_order`,`seo_title`,`seo_description`,`source_file`,`specs_json`,`gallery_json`,`old_urls_json`) VALUES (122,9,'cable','КРНГ','558-krng','MNP-0122','Примечание: По требованию потребителей кабели марки КРНГ могут поставляться с медной луженой и/или многопроволочной жилой.','<div><p>КРНГ </p><p><img alt="akrvb" loading="lazy" src="assets/img/products/KRNG__561177814e702fdb02fecfab.jpg"/></p><ol><li>Медная однопроволочная жила (класс 1); </li><li>Изоляция из резины, счетная пара жил в каждом повиве; </li><li>Оболочка из резины, не распространяющей горение. </li></ol><p><em>Примечание: </em>По требованию потребителей кабели марки КРНГ могут поставляться с медной луженой и/или многопроволочной жилой. </p><p><strong>Область применения КРНГ: </strong></p><p>Предназначены для неподвижного присоединения к электрическим приборам, аппаратам, сборкам зажимов электрических распределительных устройств с номинальным переменным напряжением до 660 Вольт частотой до 100 Гц или постоянным напряжением до 1000 Вольт. </p><p>Применяются для прокладки на открытом воздухе, в помещениях, каналах, туннелях, в условиях агрессивной среды, при отсутствии механических воздействий на кабели. Не распространяют горение при одиночной прокладке (нормы ГОСТ 12176-89). Стойки к монтажным изгибам. </p><p>Срок службы кабелей при прокладке на открытом воздухе - 15 лет, при прокладке в помещениях, каналах и туннелях - 25лет. </p><p><strong>Технические характеристики КРНГ </strong></p><table><tbody><tr><td>Влажность воздуха при 35° C [%] </td><td><strong>98 </strong></td></tr><tr><td>Гарантийный срок эксплуатации [месяц] </td><td><strong>36 </strong></td></tr><tr><td>Испытательное переменное напряжение частотой 50 Гц, 5 мин. [кВ] </td><td><strong>2.5 </strong></td></tr><tr><td>Максимальная рабочая температура жилы [°С] </td><td><strong>70 </strong></td></tr><tr><td>Монтаж при температуре, не ниже [°C] </td><td><strong>-15 </strong></td></tr><tr><td>Номинальное постоянное напряжение [кВ] </td><td><strong>0.66 </strong></td></tr><tr><td>Радиус изгиба кабелей [наружных диаметров] </td><td><strong>6 </strong></td></tr><tr><td>Строительная длина, не менее [м] </td><td><strong>150 </strong></td></tr><tr><td>Температура окружающей среды, верхний предел [°C] </td><td><strong>+50 </strong></td></tr><tr><td>Температура окружающей среды, нижний предел [°C] </td><td><strong>-50 </strong></td></tr><tr><td>Электрическое сопротивление изоляции, не менее [МОм*км] </td><td><strong>60 </strong></td></tr></tbody></table><table><tbody><tr><td><strong>Количество и сечение жил <br/>шт х кв.мм </strong></td><td><strong>Масса кабеля <br/>кг/км </strong></td><td><strong>Наружный диаметр <br/>мм </strong></td></tr><tr><td>КРНГ 4x1,0 </td><td>176,1 </td><td>11,1 </td></tr><tr><td>КРНГ 5x1,0 </td><td>212,6 </td><td>12,0 </td></tr><tr><td>КРНГ 7x1,0 </td><td>258,8 </td><td>13,0 </td></tr><tr><td>КРНГ 10x1,0 </td><td>409,0 </td><td>16,8 </td></tr><tr><td>КРНГ 14x1,0 </td><td>486,6 </td><td>18,1 </td></tr><tr><td>КРНГ 19x1,0 </td><td>615,5 </td><td>20,0 </td></tr><tr><td>КРНГ 27x1,0 </td><td>847,3 </td><td>23,7 </td></tr><tr><td>КРНГ 37x1,0 </td><td>1150,0 </td><td>27,4 </td></tr><tr><td>КРНГ 4x1,5 </td><td>203,3 </td><td>11,6 </td></tr><tr><td>КРНГ 5x1,5 </td><td>248,5 </td><td>12,6 </td></tr><tr><td>КРНГ 7x1,5 </td><td>321,2 </td><td>14,2 </td></tr><tr><td>КРНГ 10x1,5 </td><td>474,9 </td><td>17,6 </td></tr><tr><td>КРНГ 14x1,5 </td><td>573,5 </td><td>19,0 </td></tr><tr><td>КРНГ 19x1,5 </td><td>730,3 </td><td>21,0 </td></tr><tr><td>КРНГ 27x1,5 </td><td>1064,7 </td><td>25,9 </td></tr><tr><td>КРНГ 37x1,5 </td><td>1370,0 </td><td>28,8 </td></tr><tr><td>КРНГ 4x2,5 </td><td>258,8 </td><td>12,6 </td></tr><tr><td>КРНГ 5x2,5 </td><td>337,6 </td><td>14,3 </td></tr><tr><td>КРНГ 7x2,5 </td><td>413,1 </td><td>15,4 </td></tr><tr><td>