INSERT INTO `products` (`id`,`category_id`,`root_category`,`name`,`slug`,`sku`,`short_description`,`description_html`,`image`,`unit`,`price`,`request_hint`,`active`,`featured`,`sort_order`,`seo_title`,`seo_description`,`source_file`,`specs_json`,`gallery_json`,`old_urls_json`) VALUES (125,10,'cable','КПКЭВнг(А)-FRLS 180','879-kpkevng-a-frls-180','MNP-0125','КПКЭВнг(А)-FRLS 180 огнестойкий экранированный кабель с низким дымо- и газовыделением','<div><p>КПКЭВнг(А)-FRLS 180 </p><p><strong>КПКЭВнг(А)-FRLS 180 огнестойкий экранированный кабель с низким дымо- и газовыделением </strong></p><p><img alt="kpkevngfrls" loading="lazy" src="assets/img/products/kpkevngfrls__457a1665bedb427531729831.jpg"/></p><p><strong><strong>Конструкция </strong>КПКЭВнг-FRLS (КПКЭВнг(А)-FRLS) <strong>: </strong></strong></p><ol><li>Однопроволочные медные жилы сечинием 0,2; 0,35; 0,5; 0,75; 1,0; 1,5; 2,5 мм <sup>2 </sup><br/></li><li>Изоляция из огнестойкой керамообразующейся резины </li><li>Изолированные жилы скручены попарно. <br/></li><li>Проводники в парах имеют цветовую кодировку <br/></li><li>Общий экран из ламинированной алюминиевой фольги </li><li>Дренажный проводник из медной луженой проволоки под экраном </li><li>Оболочка из поливинилхлоридного пластиката пониженной пожароопасности c низким дымо- и газовыделением </li></ol><p><strong>Применение КПКЭВнг(А)-FRLS 180: </strong></p><p>• <strong>Огнестойкий кабель </strong>предназначен для одиночной и групповой прокладки в системах противопожарной защиты, охранно-пожарной сигнализации (ОПС), оповещения и управления эвакуацией людей при пожаре (СОУЭ), аварийного оповещения на путях эвакуации, аварийной вентиляции и противодымной защиты, автоматического пожаротушения, а так же в зданиях, сооружениях и строениях, где предъявляются требования к кабелям и проводам по сохранению работоспособности в условиях пожара <br/></p><p>• Кабель <strong>с низким показателем дымо.-газовыделения </strong>применяется для прокладки в помещениях промышленных предприятий,жилых и общественных зданий, а также в помещениях других объектов повышенной опасности </p><p><strong><strong>Условия эксплуатации КПКЭВнг(А)-FRLS 180: </strong></strong></p><p>Эксплуатируется внутри и вне помещений, при условии защиты от прямого солнечного излучения и атмосферных осадков. Вид климатического исполнения по ГОСТ 15150-69 - УХЛ категории размещения 2,3,4 <br/></p><table><tbody><tr><td><strong>Число жил и сечение <br/></strong></td><td><strong>Наружные размеры, мм </strong></td><td><strong>Расчетная масса,кг\\км </strong></td></tr><tr><td>КПКЭВнг-FRLS (КПКЭВнг(А)-FRLS) 1х2х0,20 </td><td>4,9 </td><td>24,0 </td></tr><tr><td>КПКЭВнг-FRLS (КПКЭВнг(А)-FRLS) 1х2х0,35 </td><td>5,2 </td><td>29,0 </td></tr><tr><td>КПКЭВнг-FRLS (КПКЭВнг(А)-FRLS) 1х2х0,50 </td><td>5,8 </td><td>40,5 </td></tr><tr><td>КПКЭВнг-FRLS (КПКЭВнг(А)-FRLS) 1х2х0,75 </td><td>6,2 </td><td>47,5 </td></tr><tr><td>КПКЭВнг-FRLS (КПКЭВнг(А)-FRLS) 1х2х1,00 </td><td>6,5 </td><td>53,5 </td></tr><tr><td>КПКЭВнг-FRLS (КПКЭВнг(А)-FRLS) 1х2х1,50 </td><td>8,2 </td><td>81,5 </td></tr><tr><td>КПКЭВнг-FRLS (КПКЭВнг(А)-FRLS) 1х2х2,50 </td><td>9,0 </td><td>107,0 </td></tr><tr><td>КПКЭВнг-FRLS (КПКЭВнг(А)-FRLS) 2х2х0,20 </td><td>4,9*8,5 </td><td>39,0 </td></tr><tr><td>КПКЭВнг-FRLS (КПКЭВнг(А)-FRLS) 2х2х0,35 </td><td>5,2*9,2 </td><td>47,0 </td></tr><tr><td>КПКЭВнг-FRLS (КПКЭВнг(А)-FRLS) 2х2х0,50 </td><td>5,8*10,0 </td><td>82,5 </td></tr><tr><td>КПКЭВнг-FRLS (КПКЭВнг(А)-FRLS) 2х2х0,75 </td><td>6,2*10,7 </td><td>96,5 </td></tr><tr><td>КПКЭВнг-FRLS (КПКЭВнг(А)-FRLS) 2х2х1,00 </td><td>6,5*11,3 </td><td>109,5 </td></tr><tr><td>КПКЭВнг-FRLS (КПКЭВнг(А)-FRLS) 2х2х1,50 </td><td>8,2*14,3 </td><td>169,5 </td></tr><tr><td>КПКЭВнг-FRLS (КПКЭВнг(А)-FRLS) 2х2х2,50 </td><td>9,0*15,9 </td><td>218,5 </td></tr></tbody></table></div>','assets/img/products/kpkevngfrls__457a1665bedb427531729831.jpg','м',NULL,'Укажите марку, число и сечение жил, рабочее напряжение, длину и условия прокладки.',1,0,125,'КПКЭВнг(А)-FRLS 180 — купить по заявке | Монополия','КПКЭВнг(А)-FRLS 180: подбор и поставка в Санкт-Петербурге. Укажите марку, число и сечение жил, рабочее напряжение, длину и условия прокладки. Расчет стоимости — по заявке.','site/www.monopoly-torg.ru/879-kpkevng-a-frls-180__bd652ef01f68d453fa6c8224.html','[]','["assets/img/products/kpkevngfrls__457a1665bedb427531729831.jpg"]','["http://www.monopoly-torg.ru/index.php/kabelnaya-produkciya/kabeli-ognestojkie/879-kpkevng-a-frls-180"]') ON DUPLICATE KEY UPDATE `category_id`=VALUES(`category_id`),`root_category`=VALUES(`root_category`),`name`=VALUES(`name`),`slug`=VALUES(`slug`),`sku`=VALUES(`sku`),`short_description`=VALUES(`short_description`),`description_html`=VALUES(`description_html`),`image`=VALUES(`image`),`unit`=VALUES(`unit`),`price`=VALUES(`price`),`request_hint`=VALUES(`request_hint`),`active`=VALUES(`active`),`featured`=VALUES(`featured`),`sort_order`=VALUES(`sort_order`),`seo_title`=VALUES(`seo_title`),`seo_description`=VALUES(`seo_description`),`source_file`=VALUES(`source_file`),`specs_json`=VALUES(`specs_json`),`gallery_json`=VALUES(`gallery_json`),`old_urls_json`=VALUES(`old_urls_json`);
INSERT INTO `products` (`id`,`category_id`,`root_category`,`name`,`slug`,`sku`,`short_description`,`description_html`,`image`,`unit`,`price`,`request_hint`,`active`,`featured`,`sort_order`,`seo_title`,`seo_description`,`source_file`,`specs_json`,`gallery_json`,`old_urls_json`) VALUES (126,10,'cable','КПКЭПнг(А)-FRHF 180','880-kpkepng-a-frhf-180','MNP-0126','1. Однопроволочные медные жилы сечием 0,2; 0,35; 0,5; 0,75; 1,0; 1,5; 2,5 мм 2','<div><p>КПКЭПнг(А)-FRHF 180 </p><p><img alt="kpstet ng hf" loading="lazy" src="assets/img/products/kpstet_ng_hf__1e5d4b264b0e7a7d98e30af3.jpg"/></p><table><tbody><tr><td></td><td><p><strong>Конструкция: </strong></p><p>1. Однопроволочные медные жилы сечием 0,2; 0,35; 0,5; 0,75; 1,0; 1,5; 2,5 мм <sup>2 </sup></p><p>2. Изоляция из огнестойкой керамообразующейся резины </p><p>• Изолированные жилы скручены попарно. Проводники в парах имеют цветовую кодировку </p><p>3. Общий экран из ламинированной алюминиевой фольги </p><p>4. Дренажный проводник из медной луженой проволоки под экраном </p><p>5. Оболочка из негорючей полимерной композиции, не содержащей галогенов </p></td></tr></tbody></table><table><tbody><tr><td><p><strong>Применение: </strong></p><p>• <strong>Огнестойкий кабель </strong>предназначен для одиночной и групповой прокладки в системах противопожарной защиты, охранно-пожарной сигнализации (ОПС), оповещения и управления эвакуацией людей при пожаре (СОУЭ), аварийного оповещения на путях эвакуации, аварийной вентиляции и противодымной защиты, автоматического пожаротушения, а так же в зданиях, сооружениях и строениях, где предъявляются требования к кабелям и проводам по сохранению работоспособности в условиях пожара <br/></p><p>• Кабель применяется для прокладки в зданиях и сооружениях с массовым пребыванием людей, в помещениях, оснащенных компьютерной и микропроцессорной техники </p></td><td></td><td><p><strong>Варианты исполнения: </strong></p><p>• Число пар в кабеле до 10,число жил до 5 </p><p>• Оболочка красного цвета </p><p>• Оболочка другого цвета (на заказ) </p></td></tr></tbody></table><table><tbody><tr><td><p><strong>Условия эксплуатации: </strong></p><p>Эксплуатируется внутри и вне помещений, при условии защиты от прямого солнечного излучения и атмосферных осадков. Вид климатического исполнения по ГОСТ 15150-69 - УХЛ категории размещения 2,3,4 </p><table><tbody><tr><td colspan="2"><p>Диапазон рабочих температур </p></td></tr><tr><td><p>при эксплуатации: </p><p>при монтаже: </p></td><td><p>от -50 <sup>о </sup>С до +125 <sup>о </sup>С </p><p>от -10 <sup>о </sup>С до +50 <sup>о </sup>С </p></td></tr><tr><td><p>Повышенная влажность воздуха (при т емпературе до +35 <sup>о </sup>С) </p></td><td><p>98% </p></td></tr><tr><td><p>Минимальный радиус изгиба при стационарной прокладке </p></td><td><p>10 номин. наружн. диаметров </p></td></tr><tr><td><p>Минимальный срок службы кабеля </p></td><td><p>20 лет </p></td></tr></tbody></table></td></tr></tbody></table><table><tbody><tr><td><p>Номинальное сечение жил </p></td><td><p>0,2 </p></td><td><p>0,35 </p></td><td><p>0,5 </p></td><td><p>0,75 </p></td><td><p>1,00 </p></td><td><p>1,50 </p></td><td><p>2,50 </p></td></tr><tr><td><p>Электрическое сопротивление шлейфа, пересчитанное на 1 км длины и t 20 <sup>0 </sup>С , Ом, не более </p></td><td><p>177,0 </p></td><td><p>114,0 </p></td><td><p>74,8 </p></td><td><p>51,0 </p></td><td><p>37,6 </p></td><td><p>25,2 </p></td><td><p>16,0 </p></td></tr><tr><td><p>Электрическое сопротивление изоляции жил, пересчитанное на 1 км длины и t 20 <sup>0 </sup>С, Ом, не менее </p></td><td colspan="7"><p>100 </p></td></tr><tr><td><p>Электрическая емкость пары на 1 км кабеля, нФ, не более </p></td><td><p>55,0 </p></td><td><p>63,0 </p></td><td><p>82,0 </p></td><td><p>92,0 </p></td><td><p>100,0 </p></td><td><p>89,0 </p></td><td><p>103,0 </p></td></tr><tr><td><p>Коэффициент затухания при частоте 1 кГц, дБ/км, не более </p></td><td><p>2,50 </p></td><td><p>1,90 </p></td><td><p>1,20 </p></td><td><p>0,91 </p></td><td><p>0,80 </p>