INSERT INTO `products` (`id`,`category_id`,`root_category`,`name`,`slug`,`sku`,`short_description`,`description_html`,`image`,`unit`,`price`,`request_hint`,`active`,`featured`,`sort_order`,`seo_title`,`seo_description`,`source_file`,`specs_json`,`gallery_json`,`old_urls_json`) VALUES (187,13,'cable','КПГН1У','479-kpgn1u','MNP-0187','КПГН1У для промышленных, строительных и энергетических объектов.','<div><p>КПГН1У </p><p><img alt="kge" loading="lazy" src="assets/img/products/kpgn1u__ba6aa8892eb612e766cfb4bb.jpg"/></p><ol><li>медные жилы класса 5; </li><li>полиэтилентерефталатная пленка; </li><li>изоляция из резины; </li><li>упрочняющий сердечник из арамидных волокон с изоляцией из резины; </li><li>слой синтетической пленки или талька; </li><li>оболочка из маслостойкой резины, не распространяющей горение </li></ol><h2>Область применения КПГН1У <br/></h2><ul><li>Кабели <strong>КПГН1У </strong>предназначены для присоединения передвижных механизмов (для подъемных и конвейерных систем), работающих в условиях изгиба при постоянно действующем растягивающем усилии, к электрическим сетям на напряжение 0,6/1 кВ переменного тока частотой до 400 Гц или постоянное напряжение 0,9/1,5 кВ. </li><li>Кабели применяются при изгибах с радиусом не менее 5 диаметров при допустимой температуре нагрева ТПЖ до +75 °С. </li><li>Кабели с номинальным сечением основных жил до 4 мм <sup>2 </sup>включительно стойки к многократным перегибам через систему роликов и выдерживают не менее 30 000 циклов перегиба. </li><li>Диапазон температур для эксплуатации при от –30 °С до +50 °С. </li><li>Кабели стойки к воздействию плесневых грибов. </li><li>Кабели КПГН1У стойки к воздействию смазочных масел. </li><li>Кабели не распространяют горение при одиночной прокладке. Класс пожарной опасности по НПВ 248-97 – 01.7.2.4 <br/></li></ul><table><thead><tr><th>Количество и сечение жил, шт х кв.мм </th><th>Масса кабеля, кг/км </th><th>Наружный диаметр, мм </th></tr></thead><tbody><tr><td>КПГН1У 3x25 </td><td>1700 </t