INSERT INTO `products` (`id`,`category_id`,`root_category`,`name`,`slug`,`sku`,`short_description`,`description_html`,`image`,`unit`,`price`,`request_hint`,`active`,`featured`,`sort_order`,`seo_title`,`seo_description`,`source_file`,`specs_json`,`gallery_json`,`old_urls_json`) VALUES (197,13,'cable','КРШУ','489-krshu','MNP-0197','КРШУ – кабели с медными жилами, с резиновой изоляцией, в резиновой оболочке повышенной озоностойкости и морозостойкости на напряжение переменного тока до 380 В частоты до 500 Гц или до 500 В постоянного тока.','<div><p>КРШУ </p><p><strong>КРШУ </strong>– кабели с медными жилами, с резиновой изоляцией, в резиновой оболочке повышенной озоностойкости и морозостойкости на напряжение переменного тока до 380 В частоты до 500 Гц или до 500 В постоянного тока. </p><p><strong>КРШУЭ </strong>– то же, с экранированными жилами. </p><p><img alt="kge" loading="lazy" src="assets/img/products/krshu__be78ad248001f9573ab36d7f.jpg"/></p><table><tbody><tr><td><p>Марка </p></td><td><p>Число жил </p></td><td><p>Сечение, мм <sup>2 </sup></p></td></tr><tr><td><p>КРШУ, КРШУЭ </p></td><td><p>4-37 </p></td><td><p>1,0 </p></td></tr></tbody></table><p><strong>Назначение и технические характеристики КРШУ <br/></strong></p><ul><li>Кабели <strong>КРШУ </strong>предназначены для гибкого соединения электрических устройств в полевых условиях на напряжение переменного тока до 380 В частоты до 500 Гц или до 500 В постоянного тока. <br/></li><li>Кабели эксплуатируются на открытом воздухе в различных климатических условиях, при относительной влажности до 98% при температуре до +35˚С, при прокладке по заболоченной местности, при воздействии морского тумана, инея, росы, в условиях загрязнения радиоактивными, отравляющими и бактериальными веществами, после дезактивации, дегазации и дезинфекции. </li><li>Кабели <strong>КРШУ </strong>устойчивы к воздействию температуры окружающей среды от -50˚С до+65˚С </li><li>Строительная длина кабелей, не менее 100 м </li><li>Срок службы (исчисляется с момента изготовления) 15 лет </li></ul><table><tbody><tr><td><strong>Маркоразмеры </strong></td><td><strong>Наружный диаметр, мм </strong></td><td><strong>Масса 1 км, кг </strong></td><td><strong>Маркоразмеры </strong></td><td><strong>Наружный диаметр, мм </strong></td><td><strong>Масса 1 км, кг </strong></td></tr><tr><td colspan="6"><strong>Кабели марки КРШУ </strong></td></tr><tr><td>КРШУ 4х1 </td><td>13,1 </td><td>195 </td><td>КРШУ 19х1 </td><td>22,7 </td><td>670 </td></tr><tr><td>КРШУ 7х1 </td><td>15,1 </td><td>270 </td><td>КРШУ 24х1 </td><td>26 </td><td>800 </td></tr><tr><td>КРШУ 10х1 </td><td>19,4 </td><td>410 </td><td>КРШУ 27х1 </td><td>26,5 </td><td>890 </td></tr><tr><td>КРШУ 12х1 </td><td>19,9 </td><td>470 </td><td>КРШУ 37х1 </td><td>29,3 </td><td>1150 </td></tr><tr><td>КРШУ 16х1 </td><td>21,7 </td><td>560 </td><td></td><td></td><td></td></tr><tr><td colspan="6"><strong>Кабели марки КРШУЭ </strong></td></tr><tr><td>КРШУЭ 4х1 </td><td>16 </td><td>290 </td><td>КРШУЭ 19х1 </td><td>28,7 </td><td>1000 </td></tr><tr><td>КРШУЭ 7х1 </td><td>18,7 </td><td>450 </td><td>КРШУЭ 24х1 </td><td>33,2 </td><td>1290 </td></tr><tr><td>КРШУЭ 10х1 </td><td>24,2 </td><td>630 </td><td>КРШУЭ 27х1 </td><td>33,9 </td><td>1400 </td></tr><tr><td>КРШУЭ 12х1 </td><td>25 </td><td>710 </td><td>КРШУЭ 37х1 </td><td>37,7 </td><td>1895 </td></tr><tr><td>КРШУЭ 16х1 </td><td>27,4 </td><td>920 </td><td></td><td></td><td></td></tr></tbody></table></div>','assets/img/products/krshu__be78ad248001f9573ab36d7f.jpg','м',NULL,'Укажите марку, число и сечение жил, рабочее напряжение, длину и условия прокладки.',1,0,197,'КРШУ — купить по заявке | Монополия','КРШУ: подбор и поставка в Санкт-Петербурге. Укажите марку, число и сечение жил, рабочее напряжение, длину и условия прокладки. Расчет стоимости — по заявке.','site/www.monopoly-torg.ru/489-krshu__35feb4bd039cf46f903fe649.html','[]','["assets/img/products/krshu__be78ad248001f9573ab36d7f.jpg"]','["http://www.monopoly-torg.ru/index.php/kabelnaya-pro