INSERT INTO `products` (`id`,`category_id`,`root_category`,`name`,`slug`,`sku`,`short_description`,`description_html`,`image`,`unit`,`price`,`request_hint`,`active`,`featured`,`sort_order`,`seo_title`,`seo_description`,`source_file`,`specs_json`,`gallery_json`,`old_urls_json`) VALUES (198,13,'cable','КСС','490-kss','MNP-0198','КСС – кабели силовые с медными жилами, с резиновой изоляцией, в резиновой оболочке на напряжение 660 В.','<div><p>КСС </p><p><strong>КСС </strong>– кабели силовые с медными жилами, с резиновой изоляцией, в резиновой оболочке на напряжение 660 В. </p><p><img alt="kg" loading="lazy" src="assets/img/products/kss__86fc673e81391480744d3724.jpg"/></p><table><tbody><tr><td><p><strong>Марка </strong></p></td><td><p><strong>Число жил </strong></p></td><td><p><strong>Сечение, мм <sup>2 </sup></strong></p></td></tr><tr><td rowspan="2"><p><strong>КСС </strong></p></td><td><p>1 </p></td><td><p>35,0; 50,0 </p></td></tr><tr><td><p>3+1 </p></td><td><p>10,0; 35,0 </p></td></tr></tbody></table><p><strong>НАЗНАЧЕНИЕ И ТЕХНИЧЕСКИЕ ХАРАКТЕРИСТИКИ КСС <br/></strong></p><p>Кабели <strong>КСС </strong>предназначены для присоединения передвижных механизмов к электрическим сетям на номинальное напряжение 660 В частоты до 400 Гц или постоянное номинальное напряжение 1 000 В, при изгибах с радиусом не менее 10 диаметров кабеля при допустимой температуре нагрева токопроводящих жил до 75˚С. Кабели используются для ремонтных целей. </p><p>Кабели <strong>КСС </strong>устойчивы к воздействию температуры окружающей среды от -40˚С до +50˚С </p><p>Строительная длина кабелей: </p><p>- с номинальным сечением основных жил до 35 мм <sup>2 </sup>включительно, не менее 150 м </p><p>- с номинальным сечением основных жил 50 мм <sup>2 </sup>и выше, не менее 125 м </p><p>Срок службы (исчисляется с момента изготовления кабеля): 4 года </p></div>','assets/img/products/kss__86fc673e81391480744d3724.jpg','м',NULL,'Укажите марку, число и сечение жил, рабочее напряжение, длину и условия прокладки.',1,0,198,'КСС — купить по заявке | Монополия','КСС: подбор и поставка в Санкт-Петербурге. Укажите марку, число и сечение жил, рабочее напряжение, длину и условия прокладки. Расчет стоимости — по заявке.','site/www.monopoly-torg.ru/490-kss__d0548e14df9da86b4c6c3da9.html','[["3+1", "10,0; 35,0"]]','["assets/img/products/kss__86fc673e81391480744d3724.jpg"]','["http://www.monopoly-torg.ru/index.php/kabelnaya-produkciya/kabeli-silovye-gibkie/490-kss"]') ON DUPLICATE KEY UPDATE `category_id`=VALUES(`category_id`),`root_category`=VALUES(`root_category`),`name`=VALUES(`name`),`slug`=VALUES(`slug`),`sku`=VALUES(`sku`),`short_description`=VALUES(`short_description`),`description_html`=VALUES(`description_html`),`image`=VALUES(`image`),`unit`=VALUES(`unit`),`price`=VALUES(`price`),`request_hint`=VALUES(`request_hint`),`active`=VALUES(`active`),`featured`=VALUES(`featured`),`sort_order`=VALUES(`sort_order`),`seo_title`=VALUES(`seo_title`),`seo_description`=VALUES(`seo_description`),`source_file`=VALUES(`source_file`),`specs_json`=VALUES(`specs_json`),`gallery_json`=VALUES(`gallery_json`),`old_urls_json`=VALUES(`old_urls_json`);
INSERT INTO `products` (`id`,`category_id`,`root_category`,`name`,`slug`,`sku`,`short_description`,`description_html`,`image`,`unit`,`price`,`request_hint`,`active`,`featured`,`sort_order`,`seo_title`,`seo_description`,`source_file`,`specs_json`,`gallery_json`,`old_urls_json`) VALUES (199,13,'cable','КТШЭ','491-ktshe','MNP-0199','КТШЭ – кабели для токоподвода к электробуру с медными жилами, с резиновой изоляцией и оболочкой.','<div><p>КТШЭ </p><p><strong>КТШЭ </strong>– кабели для токоподвода к электробуру с медными жилами, с резиновой изоляцией и оболочкой. </p><p><img alt="kg" loading="lazy" src="assets/img/products/kshte__5a0fbee3ef222efc3cd26977.jpg"/></p><table><tbody><tr><td><p>Марка </p></td><td><p>Число жил </p></td><td><p>Сечение, мм <sup>2 </sup></p></td></tr><tr><td rowspan="2"><p>КТШЭ </p></td><td><p>1 </p></td><td><p>25,0; 35,0; 50,0 </p></td></tr><tr><td><p>3 </p></td><td><p>35,0; 50,0 </p></td></tr></tbody></table><p><strong>НАЗНАЧЕНИЕ И ТЕХНИЧЕСКИЕ ХАРАКТЕРИСТИКИ КТШЭ <br/></strong></p><p>Кабели <strong>КТШЭ </strong>предназначены для передачи электроэнергии к электробурам напряжением до 3 000 В. Кабели могут эксплуатироваться при гидростатическом давлении до 122,5 МПа (1 250 кгс/см). Кабели обеспечивают надежную работу в условиях вибрации, динамических нагрузок и частых пусков. </p><p>Кабели <strong>КТШЭ </strong>устойчивы к воздействию температуры окружающей среды от -30˚С до +100˚С </p><p>Строительная длина кабелей, не менее 13 м </p><p>Срок службы (исчисляется с момента изготовления), не менее 2, 5 года </p><table><tbody><tr><td><p>Маркоразмеры </p></td><td><p>Наружный диаметр, мм </p></td><td><p>Масса 1 км, кг </p></td><td><p>Маркоразмеры </p></td><td><p>Наружный диаметр, мм </p></td><td><p>Масса 1 км, кг </p></td></tr><tr><td><p>1х25 </p></td><td><p>17,9 </p></td><td><p>595 </p></td><td><p>3х35 </p></td><td><p>34,2 </p></td><td><p>2320 </p></td></tr><tr><td><p>1х35 </p></td><td><p>20,1 </p></td><td><p>790 </p></td><td><p>3х50 </p></td><td><p>42,3 </p></td><td><p>3400 </p></td></tr><tr><td><p>1х50 </p></td><td><p>22,2 </p></td><td><p>970 </p></td><td></td><td></td><td></td></tr></tbody></table></div>','assets/img/products/kshte__5a0fbee3ef222efc3cd26977.jpg','м',NULL,'Укажите марку, число и сечение жил, рабочее напряжение, длину и условия прокладки.',1,0,199,'КТШЭ — купить по заявке | Монополия','КТШЭ: подбор и поставка в Санкт-Петербурге. Укажите марку, число и сечение жил, рабочее напряжение, длину и условия прокладки. Расчет стоимости — по заявке.','site/www.monopoly-torg.ru/491-ktshe__b59604ca4a74ebaba658b8fa.html','[["3", "35,0; 50,0"]]','["assets/img/products/kshte__5a0fbee3ef222efc3cd26977.jpg"]','["http://www.monopoly-torg.ru/index.php/kabelnaya-produkciya/kabeli-silovye-gibkie/491-ktshe"]') ON DUPLICATE KEY UPDATE `category_id`=VALUES(`category_id`),`root_category`=VALUES(`root_category`),`name`=VALUES(`name`),`slug`=VALUES(`slug`),`sku`=VALUES(`sku`),`short_description`=VALUES(`short_description`),`description_html`=VALUES(`description_html`),`image`=VALUES(`image`),`unit`=VALUES(`unit`),`price`=VALUES(`price`),`request_hint`=VALUES(`request_hint`),`active`=VALUES(`active`),`featured`=VALUES(`featured`),`sort_order`=VALUES(`sort_order`),`seo_title`=VALUES(`seo_title`),`seo_description`=VALUES(`seo_description`),`source_file`=VALUES(`source_file`),`specs_json`=VALUES(`specs_json`),`gallery_json`=VALUES(`gallery_json`),`old_urls_json`=VALUES(`old_urls_json`);
INSERT INTO `products` (`id`,`category_id`,`root_category`,`name`,`slug`,`sku`,`short_description`,`description_html`,`image`,`unit`,`price`,`request_hint`,`active`,`featured`,`sort_order`,`seo_title`,`seo_description`,`source_file`,`specs_json`,`gallery_json`,`old_urls_json`) VALUES (200,13,'cable','РПШ','492-rpsh','MNP-0200','Провода РПШ предназначены для присоединения стационарных установок в электрических сетях на номинальное переменное напряжение 380 и 660 В частотой 400 Гц, а также для монтажа радиоаппаратуры.','<div><p>РПШ </p><p><img alt="kge" loading="lazy" src="assets/img/products/rpsh__0635a25495ee85d134b76266.jpg"/></p><ol><li>Токопроводящая жила скрученная из медных проволок или медных лужёных проволок (класс 4); </li><li>Изоляция из резины на основе натурального и бутадиенового каучуков, <br/>маркировка жил: <br/>• цветовая - счётная пара; </li><li>Обмотка из полиэтилентерефталатной плёнки; </li><li>Оболочка из резины на основе полихлоропрена. </li></ol><p><strong>Область применения РПШ: </strong></p><p>Провода <strong>РПШ </strong>предназначены для присоединения стационарных установок в электрических сетях на номинальное переменное напряжение 380 и 660 В частотой 400 Гц, а также для монтажа радиоаппаратуры. </p><p>Провода <strong>РПШ </strong>предназначены для эксплуатации в макроклиматических районах с умеренным климатом при температуре окружающей среды от минус 40°С до плюс 60°С. Провода предназначены для эксплуатации в закрытых помещениях при отсутствии воздействия прямого солнечного излучения и атмосферных осадков. Провода с сечением жил до 4 кв.мм стойки к многократным перегибам и выдерживают не менее 500 циклов. Провода с сечением жил 6 и 10 кв.мм стойки к изгибам и выдерживают не менее 15 двойных изгибов. </p><p><strong>Технические характеристики РПШ </strong><br/></p><table><tbody><tr><td>Влажность воздуха при 35° C [%] </td><td><strong>98 </strong></td></tr><tr><td>Гарантийный срок эксплуатации [месяц] </td><td><strong>12 </strong></td></tr><tr><td>Длительно допустимая температура на жиле, не более [°C] </td><td><strong>65 </strong></td></tr><tr><td>Испытательное переменное напряжение частотой 50 Гц, 5 мин. [кВ] </td><td><strong>2.5 </strong></td></tr><tr><td>Монтаж при температуре, не ниже [°C] </td><td><strong>-15 </strong></td></tr><tr><td>Номинальное переменное напряжение частоты 400 Гц, [кВ] </td><td><strong>0.66 </strong></td></tr><tr><td>Номинальное постоянное напряжение [кВ] </td><td><strong>1.0 </strong></td></tr><tr><td>Строительная длина, не менее [м] </td><td><strong>50 </strong></td></tr><tr><td>Температура окружающей среды, верхний предел [°C] </td><td><strong>+60 </strong></td></tr><tr><td>Температура окружающей среды, нижний предел [°C] </td><td><strong>-40 </strong></td></tr><tr><td>Электрическое сопротивление изоляции, не менее [МОм*км] </td><td><strong>110 </strong></td></tr></tbody></table><p>Срок службы - 8 лет. </p><table><tbody><tr><td><strong>Количество <br/>и сечение <br/>жил, шт х кв.мм </strong></td><td><strong>Масса <br/>кабеля, <br/>кг/км </strong></td><td><strong>Наружный <br/>диаметр, <br/>мм </strong></td></tr><tr><td>РПШ 2х0,75 </td><td>114 </td><td>9 </td></tr><tr><td>РПШ 3х0,75 </td><td>125 </td><td>9,5 </td></tr><tr><td>РПШ 4х0,75 </td><td>148 </td><td>10,3 </td></tr><tr><td>РПШ 5х0,75 </td><td>184 </td><td>11,2 </td></tr><tr><td>РПШ 6х0,75 </td><td>216 </td><td>12,2 </td></tr><tr><td>РПШ 7х0,75 </td><td>223 </td><td>12,2 </td></tr><tr><td>РПШ 8х0,75 </td><td>277 </td><td>14,2 </td></tr><tr><td>РПШ 10х0,75 </td><td>347 </td><td>16,4 </td></tr><tr><td>РПШ 12х0,75 </td><td>366 </td><td>16,9 </td></tr><tr><td>РПШ 14х0,75 </td><td>414 </td><td>17,8 </td></tr><tr><td>РПШ 2х1 </td><td>125 </td><td>9,4 </td></tr><tr><td>РПШ 3х1 </td><td>137 </td><td>9,8 </td></tr><tr><td>РПШ 4х1 </td><td>166 </td><td>10,7 </td></tr><tr><td>РПШ 5х1 </td><td>205 </td><td>11,6 </td></tr><tr><td>РПШ 6х1 </td><td>238 </td><td>13,6 </td></tr><tr><td>РПШ 7х1 </td><td>248 </td><td>13,6 </td></tr><tr