INSERT INTO `products` (`id`,`category_id`,`root_category`,`name`,`slug`,`sku`,`short_description`,`description_html`,`image`,`unit`,`price`,`request_hint`,`active`,`featured`,`sort_order`,`seo_title`,`seo_description`,`source_file`,`specs_json`,`gallery_json`,`old_urls_json`) VALUES (203,13,'cable','РПШЭМ','495-rpshem','MNP-0203','Провода РПШЭМ предназначены для присоединения стационарных установок в электрических сетях на номинальное переменное напряжение 380 и 660 В частотой 400 Гц, а также для монтажа радиоаппаратуры.','<div><p>РПШЭМ </p><p><img alt="kg" loading="lazy" src="assets/img/products/rpshe__34f19b089e98bf68df9b79e8.jpg"/></p><ol><li>Токопроводящая жила скрученная из медных проволок (класс 4); </li><li>Изоляция из резины на основе натурального и бутадиенового каучуков, <br/>маркировка жил: <br/>• цветовая - счётная пара; </li><li>Обмотка из полиэтилентерефталатной плёнки; </li><li>Оболочка из резины на основе изопренового и бутадиенового каучуков; </li><li>Экран из медных луженых проволок. </li></ol><p><strong>Область применения РПШЭМ: </strong></p><p>Провода <strong>РПШЭМ </strong>предназначены для присоединения стационарных установок в электрических сетях на номинальное переменное напряжение 380 и 660 В частотой 400 Гц, а также для монтажа радиоаппаратуры. </p><p>Провода <strong>РПШЭМ </strong>предназначены для эксплуатации в макроклиматических районах с умеренным климатом при температуре окружающей среды от минус 50°С до плюс 60°С. Провода предназначены для эксплуатации в закрытых помещениях при отсутствии воздействия прямого солнечного излучения и атмосферных осадков. Провода преимущественно предназначены для монтажа электроустановок, когда требуется защита от радиопомех. Провода с сечением жил 6 и 10 кв.мм. стойки к изгибам и выдерживают не менее 15 двойных изгибов. </p><p><strong>Технические характеристики РПШЭМ </strong><br/></p><table><tbody><tr><td>Влажность воздуха при 35° C [%] </td><td><strong>98 </strong></td></tr><tr><td>Гарантийный срок э