INSERT INTO `products` (`id`,`category_id`,`root_category`,`name`,`slug`,`sku`,`short_description`,`description_html`,`image`,`unit`,`price`,`request_hint`,`active`,`featured`,`sort_order`,`seo_title`,`seo_description`,`source_file`,`specs_json`,`gallery_json`,`old_urls_json`) VALUES (332,14,'cable','СБЛ -6','265-sbl-6','MNP-0332','Кабели предназначены для передачи и распределения электрической энергии в стационарных установках в электрических сетях на напряжение до 10 кВ частотой 50 Гц.','<div><p>СБЛ -6 </p><p><img alt="aab2l" loading="lazy" src="assets/img/products/sbl__3b10f5bb5688e48192122bde.jpg"/></p><ol><li>Медная токопроводящая жила: <br/>• однопроволочная сечением 25-50 кв.мм - "ож", <br/>• многопроволочная сечением 25-800 кв.мм; </li><li>Фазная бумажная изоляция, пропитанная вязким или нестекающим изоляционным пропиточным составом; <br/>маркировка жил: <br/>• цифровая: 1, 2, 3, 4, <br/>• цветовая: белая или жёлтая, синяя или зеленая, красная или малиновая, коричневая или чёрная; </li><li>Заполнение из бумажных жгутов; </li><li>Поясная бумажная изоляция, пропитанная вязким или нестекающим изоляционным пропиточным составом; </li><li>Экран из электропроводящей бумаги для кабелей на напряжение от 6 кВ и более; </li><li>Свинцовая оболочка; </li><li>Подушка из битума, пленки ПВХ и крепированной бумаги; </li><li>Броня из стальных лент; </li><li>Наружный покров из волокнистых материалов. </li></ol><p><strong>Область применения СБЛ -6: </strong></p><p>Кабели предназначены для передачи и распределения электрической энергии в стационарных установках в электрических сетях на напряжение до 10 кВ частотой 50 Гц. </p><p>Кабели предназначены для эксплуатации в макроклиматических районах с умеренным и холодным климатом. Кабели предназначены для прокладки в земле (траншеях) со средней коррозионной активностью на трассах с наличием или отсутствием блуждающих токов и в земле (траншеях) с высокой коррозионной активностью на трассах с отсутствием блуждающих токов, если в процессе эксплуатации не подвергаются растягивающим усилиям. Кабели с нестекающим изоляционным пропиточным составом (ЦСБл) предназначены для прокладки на вертикальных и наклонных участках трасс без ограничения разности уровней. </p><p><strong>Технические характеристики СБЛ -6 </strong></p><table><tbody><tr><td>Влажность воздуха при 35° C [%] </td><td><strong>98 </strong></td></tr><tr><td>Гарантийный срок эксплуатации [месяц] </td><td><strong>54 </strong></td></tr><tr><td>Испытательное переменное напряжение частотой 50 Гц, 5 мин. [кВ] </td><td><strong>17 </strong></td></tr><tr><td>Максимальная рабочая температура жилы при перегрузке [°С] </td><td><strong>90 </strong></td></tr><tr><td>Максимальная рабочая температура жилы [°С] </td><td><strong>65 </strong></td></tr><tr><td>Монтаж при температуре, не ниже [°C] </td><td><strong>0 </strong></td></tr><tr><td>Номинальное переменное напряжение частотой 50 Гц [кВ] </td><td><strong>6 </strong></td></tr><tr><td>Номинальное постоянное напряжение [кВ] </td><td><strong>15 </strong></td></tr><tr><td>Радиус изгиба многожильных кабелей, не менее [наружных диаметров] </td><td><strong>15 </strong></td></tr><tr><td>Радиус изгиба одножильных кабелей, не менее [наружных диаметров] </td><td><strong>25 </strong></td></tr><tr><td>Разность уровней, не более [м] </td><td><strong>15 </strong></td></tr><tr><td>Температура окружающей среды, верхний предел [°C] </td><td><strong>+50 </strong></td></tr><tr><td>Температура окружающей среды, нижний предел [°C] </td><td><strong>-50 </strong></td></tr><tr><td>Электрическое сопротивление изоляции, не менее [МОм*км] </td><td><strong>200 </strong></td></tr></tbody></table><p>Срок службы кабелей - не менее 30 лет. </p><table><tbody><tr><td><strong>Количество <br/>и сечение <br/>жил, шт х кв.мм </strong></td><td><strong>Масса кабеля <br/>кг/км </strong></td><td><strong>Наружный диаметр <br/>мм </strong></td></tr><tr><td>СБЛ -6 3х25 ож </td><td>3200 </td><td>36,5 </td></tr><tr><td>СБЛ -6 3х25 </td><td>3427 </td><td>38,3 </td></tr><tr><td>СБЛ -6 3х35 ож </td><td>3302 </td><td>35,4 </td></tr><tr><td>СБЛ -6 3х35 </td><td>3487 </td><td>36,6 </td></tr><tr><td>СБЛ -6 3х50 ож </td><td>3866 </td><td>37,4 </td></tr><tr><td>СБЛ -6 3х50 </td><td>4027 </td><td>38,7 </td></tr><tr><td>СБЛ -6 3х70 </td><td>4977 </td><td>41,7 </td></tr><tr><td>СБЛ -6 3х95 </td><td>6082 </td><td>44,9 </td></tr><tr><td>СБЛ -6 3х120 </td><td>7084 </td><td>47,5 </td></tr><tr><td>СБЛ -6 3х150 </td><td>8196 </td><td>50,2 </td></tr><tr><td>СБЛ -6 3х185 </td><td>9591 </td><td>53,4 </td></tr><tr><td>СБЛ -6 3х240 </td><td>11796 </td><td>57,8 </td></tr></tbody></table></div>','assets/img/products/sbl__3b10f5bb5688e48192122bde.jpg','м',NULL,'Укажите марку, число и сечение жил, рабочее напряжение, длину и условия прокладки.',1,0,332,'СБЛ -6 — купить по заявке | Монополия','СБЛ -6: подбор и поставка в Санкт-Петербурге. Укажите марку, число и сечение жил, рабочее напряжение, длину и условия прокладки. Расчет стоимости — по заявке.','site/www.monopoly-torg.ru/265-sbl-6__14e905f041c23bd29720aa36.html','[["Влажность воздуха при 35° C [%]", "98"], ["Гарантийный срок эксплуатации [месяц]", "54"], ["Испытательное переменное напряжение частотой 50 Гц, 5 мин. [кВ]", "17"], ["Максимальная рабочая температура жилы при перегрузке [°С]", "90"], ["Максимальная рабочая температура жилы [°С]", "65"], ["Монтаж при температуре, не ниже [°C]", "0"], ["Номинальное переменное напряжение частотой 50 Гц [кВ]", "6"], ["Номинальное постоянное напряжение [кВ]", "15"], ["Радиус изгиба многожильных кабелей, не менее [наружных диаметров]", "15"], ["Радиус изгиба одножильных кабелей, не менее [наружных диаметров]", "25"], ["Разность уровней, не более [м]", "15"], ["Температура окружающей среды, верхний предел [°C]", "+50"], ["Температура окружающей среды, нижний предел [°C]", "-50"], ["Электрическое сопротивление изоляции, не менее [МОм*км]", "200"]]','["assets/img/products/sbl__3b10f5bb5688e48192122bde.jpg"]','["http://www.monopoly-torg.ru/index.php/kabelnaya-produkciya/kabeli-silovye-s-bumazhnoj-izolyatsiej/265-sbl-6"]') ON DUPLICATE KEY UPDATE `category_id`=VALUES(`category_id`),`root_category`=VALUES(`root_category`),`name`=VALUES(`name`),`slug`=VALUES(`slug`),`sku`=VALUES(`sku`),`short_description`=VALUES(`short_description`),`description_html`=VALUES(`description_html`),`image`=VALUES(`image`),`unit`=VALUES(`unit`),`price`=VALUES(`price`),`request_hint`=VALUES(`request_hint`),`active`=VALUES(`active`),`featured`=VALUES(`featured`),`sort_order`=VALUES(`sort_order`),`seo_title`=VALUES(`seo_title`),`seo_description`=VALUES(`seo_description`),`source_file`=VALUES(`source_file`),`specs_json`=VALUES(`specs_json`),`gallery_json`=VALUES(`gallery_json`),`old_urls_json`=VALUES(`old_urls_json`);
INSERT INTO `products` (`id`,`category_id`,`root_category`,`name`,`slug`,`sku`,`short_description`,`description_html`,`image`,`unit`,`price`,`request_hint`,`active`,`featured`,`sort_order`,`seo_title`,`seo_description`,`source_file`,`specs_json`,`gallery_json`,`old_urls_json`) VALUES (333,14,'cable','СБНЛШНГ-10','266-sbnlshng-10','MNP-0333','Кабели СБНЛШНГ-10 предназначены для передачи и распределения электрической энергии в стационарных установках в электрических сетях на напряжение до 10 кВ частотой 50 Гц.','<div><p>СБНЛШНГ-10 </p><p><img alt="aab2l" loading="lazy" src="assets/img/products/sbnlshng-10__9829db94937829228a244353.jpg"/></p><ol><li>Медная токопроводящая жила: <br/>• однопроволочная сечением 25-50 кв.мм, <br/>• многопроволочная сечением 50-240 кв.мм; </li><li>Фазная бумажная изоляция, пропитанная вязким или нестекающим изоляционным пропиточным составом; <br/>маркировка жил: <br/>• цифровая: 1, 2, 3, <br/>• цветовая: белая или жёлтая, синяя или зеленая, красная или малиновая; </li><li>Заполнение из бумажных жгутов; </li><li>Поясная бумажная изоляция, пропитанная вязким или нестекающим изоляционным пропиточным составом; </li><li>Экран из электропроводящей бумаги; </li><li>Свинцовая оболочка; </li><li>Подушка из битума, пленок ПЭТ и ПВХ, стеклянной пряжи; </li><li>Броня из стальных оцинкованных лент; </li><li>Подслой из битума и ПЭТ пленки; </li><li>Наружный покров из ПВХ пластиката пониженной горючести. </li></ol><p><strong>Область применения СБНЛШНГ-10: </strong></p><p>Кабели <strong>СБНЛШНГ-10 </strong>предназначены для передачи и распределения электрической энергии в стационарных установках в электрических сетях на напряжение до 10 кВ частотой 50 Гц. </p><p>Кабели <strong>СБНЛШНГ-10 </strong>предназначены для эксплуатации в макроклиматических районах с умеренным и холодным климатом. Кабели предназначены для прокладки в кабельных сооружениях, помещениях и сооружениях метрополитена, в том числе пожароопасных и взрывоопасных зонах В-I, В-Iа, В-Iг, В-II и В-IIа, если в процессе эксплуатации кабели не подвергаются растягивающим усилиям. Допускается прокладка кабелей в трубах и в земле (в траншеях) на отдельных участках трассы при условии дополнительной защиты от механических повреждений. Кабели не распространяют горение при прокладке в пучках (нормы МЭК 60332-3 категории А). Кабели допускают перегрузку 15% от номинального тока нагрузки продолжительностью не более 6 часов в сутки в течение 5 суток. </p><p><strong>Технические характеристики СБНЛШНГ-10 </strong><br/></p><table><tbody><tr><td>Влажность воздуха при 35° C [%] </td><td><strong>98 </strong></td></tr><tr><td>Гарантийный срок эксплуатации [месяц] </td><td><strong>54 </strong></td></tr><tr><td>Испытательное переменное напряжение частотой 50 Гц, 5 мин. [кВ] </td><td><strong>25 </strong></td></tr><tr><td>Максимальная рабочая температура жилы при перегрузке [°С] </td><td><strong>80 </strong></td></tr><tr><td>Максимальная рабочая температура жилы [°С] </td><td><strong>60 </strong></td></tr><tr><td>Монтаж при температуре, не ниже [°C] </td><td><strong>0 </strong></td></tr><tr><td>Номинальное переменное напряжение частотой 50 Гц [кВ] </td><td><strong>10 </strong></td></tr><tr><td>Номинальное постоянное напряжение [кВ] </td><td><strong>25 </strong></td></tr><tr><td>Радиус изгиба кабелей [наружных диаметров] </td><td><strong>15 </strong></td></tr><tr><td>Разность уровней, не более [м] </td><td><strong>15 </strong></td></tr><tr><td>Температура окружающей среды, верхний предел [°C] </td><td><strong>+50 </strong></td></tr><tr><td>Температура окружающей среды, нижний предел [°C] </td><td><strong>-50 </strong></td></tr><tr><td>Электрическое сопротивление изоляции, не менее [МОм*км] </td><td><strong>200 </strong></td></tr></tbody></table><p>Срок службы кабелей - не менее 30 лет. </p><table><tbody><tr><td><strong>Количество <br/>и сечение <br/>жил, шт х кв.мм </strong></td><td><strong>Масса кабеля <br/>кг/км </strong></td><td><strong>Наружный диаметр <br/>мм </strong></td></tr><tr><td>СБНЛШНГ-10 3х25 ож </td><td>3843 </td><td>39,7 </td></tr><tr><td>СБНЛШНГ-10 3х25 </td><td>4139 </td><td>41,5 </td></tr><tr><td>СБНЛШНГ-10 3х35 ож </td><td>3939 </td><td>38,4 </td></tr><tr><td>СБНЛШНГ-10 3х35 </td><td>4107 </td><td>39,7 </td></tr><tr><td>СБНЛШНГ-10 3х50 ож </td><td>4497 </td><td>40,5 </td></tr><tr><td>СБНЛШНГ-10 3х50 </td><td>4722 </td><td>41,9 </td></tr><tr><td>СБНЛШНГ-10 3х70 </td><td>5695 </td><td>45 </td></tr><tr><td>СБНЛШНГ-10 3х95 </td><td>6769 </td><td>48,1 </td></tr><tr><td>СБНЛШНГ-10 3х120 </td><td>7842 </td><td>50,8 </td></tr><tr><td>СБНЛШНГ-10 3х150 </td><td>8957 </td><td>53,5 </td></tr><tr><td>СБНЛШНГ-10 3х185 </td><td>10503 </td><td>57,2 </td></tr><tr><td>СБНЛШНГ-10 3х240 </td><td>12694 </td><td>61,5 </td></tr></tbody></table><table><tbody><tr><td>Сечение жил, кв. мм </td><td>Строительная длина, м </td></tr><tr><td>до 70 </td><td>300-450 </td></tr><tr><td>95 и 120 </td><td>250-400 </td></tr><tr><td>150 и более </td><td>200-350 </td></tr></tbody></table></div>','assets/img/products/sbnlshng-10__9829db94937829228a244353.jpg','м',NULL,'Укажите марку, число и сечение жил, рабочее напряжение, длину и условия прокладки.',1,0,333,'СБНЛШНГ-10 — купить по заявке | Монополия','СБНЛШНГ-10: подбор и поставка в Санкт-Петербурге. Укажите марку, число и сечение жил, рабочее напряжение, длину и условия прокладки. Расчет стоимости — по заявке.','site/www.monopoly-torg.ru/266-sbnlshng-10__069a3267dee4a554ef32a3cf.html','[["Влажность воздуха при 35° C [%]", "98"], ["Гарантийный срок эксплуатации [месяц]", "54"], ["Испытательное переменное напряжение частотой 50 Гц, 5 мин. [кВ]", "25"], ["Максимальная рабочая температура жилы при перегрузке [°С]", "80"], ["Максимальная рабочая температура жилы [°С]", "60"], ["Монтаж при температуре, не ниже [°C]", "0"], ["Номинальное переменное напряжение частотой 50 Гц [кВ]", "10"], ["Номинальное постоянное напряжение [кВ]", "25"], ["Радиус изгиба кабелей [наружных диаметров]", "15"], ["Разность уровней, не более [м]", "15"], ["Температура окружающей среды, верхний предел [°C]", "+50"], ["Температура окружающей среды, нижний предел [°C]", "-50"], ["Электрическое сопротивление изоляции, не менее [МОм*км]", "200"], ["Сечение жил, кв. мм", "Строительная длина, м"], ["до 70", "300-450"], ["95 и 120", "250-400"], ["150 и более", "200-350"]]','["assets/img/products/sbnlshng-10__9829db94937829228a244353.jpg"]','["http://www.monopoly-torg.ru/index.php/kabelnaya-produkciya/kabeli-silovye-s-bumazhnoj-izolyatsiej/266-sbnlshng-10"]') ON DUPLICATE KEY UPDATE `category_id`=VALUES(`category_id`),`root_category`=VALUES(`root_category`),`name`=VALUES(`name`),`slug`=VALUES(`slug`),`sku`=VALUES(`sku`),`short_description`=VALUES(`short_description`),`description_html`=VALUES(`description_html`),`image`=VALUES(`image`),`unit`=VALUES(`unit`),`price`=VALUES(`price`),`request_hint`=VALUES(`request_hint`),`active`=VALUES(`active`),`featured`=VALUES(`featured`),`sort_order`=VALUES(`sort_order`),`seo_title`=VALUES(`seo_title`),`seo_description`=VALUES(`seo_description`),`source_file`=VALUES(`source_file`),`specs_json`=VALUES(`specs_json`),`gallery_json`=VALUES(`gallery_json`),`old_urls_json`=VALUES(`old_urls_json`);
INSERT INTO `products` (`id`,`category_id`,`root_category`,`name`,`slug`,`sku`,`short_description`,`description_html`,`image`,`unit`,`price`,`request_hint`,`active`,`featured`,`sort_order`,`seo_title`,`seo_description`,`source_file`,`specs_json`,`gallery_json`,`old_urls_json`) VALUES (334,14,'cable','СБШВ-10','267-sbshv-10','MNP-0334','Кабели СБШВ-10 предназначены для передачи и распределения электрической энергии в стационарных установках в электрических сетях на напряжение до 10 кВ частотой 50 Гц.','<div><p>СБШВ-10 </p><p><img alt="aab2l" loading="lazy" src="assets/img/products/sbshv-6__4c03d157ab008281541d05e6.jpg"/></p><ol><li>Медная токопроводящая жила: <br/>• однопроволочная сечением 25-50 кв.мм - "ож", <br/>• многопроволочная сечением 25-240 кв.мм; </li><li>Фазная бумажная изоляция, пропитанная вязким или нестекающим изоляционным пропиточным составом; <br/>маркировка жил: <br/>• цифровая: 1, 2, 3, 4, <br/>• цветовая: белая или жёлтая, синяя или зеленая, красная или малиновая, коричневая или чёрная; </li><li>Заполнение из бумажных жгутов; </li><li>Поясная бумажная изоляция, пропитанная вязким или нестекающим изоляционным пропиточным составом; </li><li>Экран из электропроводящей бумаги для кабелей на напряжение от 6 кВ и более; </li><li>Свинцовая оболочка; </li><li>Подушка из битума и крепированной бумаги; </li><li>Броня из стальных лент; </li><li>Подслой из битума и ПЭТ пленки; </li><li>Наружный покров из ПВХ пластиката. </li></ol><p><strong>Область применения СБШВ-10: </strong></p><p>Кабели СБШВ-10 предназначены для передачи и распределения электрической энергии в стационарных установках в электрических сетях на напряжение до 10 кВ частотой 50 Гц. </p><p>Кабели СБШВ-10 предназначены для эксплуатации в макроклиматических районах с умеренным и холодным климатом. Кабели предназначены для прокладки в сырых помещениях (объемах), частично затапливаемых при наличии среды со средней и высокой коррозионной активностью, если существует опасность механических повреждений в ходе эксплуатации. Кабели предназначены для прокладки во взрывоопасных зонах В-I, В-Iа и в шахтах, если отсутствует опасность механических повреждений в ходе эксплуатации. Кабели не распространяют горение при одиночной прокладке (нормы МЭК 60332-1). Кабели с нестекающим изоляционным пропиточным составом (ЦСБШв) предназначены для прокладки на вертикальных и наклонных участках трасс без ограничения разности уровней. </p><p><strong>Технические характеристики СБШВ-10 </strong></p><table><tbody><tr><td>Влажность воздуха при 35° C [%] </td><td><strong>98 </strong></td></tr><tr><td>Гарантийный срок эксплуатации [месяц] </td><td><strong>54 </strong></td></tr><tr><td>Испытательное переменное напряжение частотой 50 Гц, 5 мин. [кВ] </td><td><strong>25 </strong></td></tr><tr><td>Максимальная рабочая температура жилы при перегрузке [°С] </td><td><strong>80 </strong></td></tr><tr><td>Максимальная рабочая температура жилы [°С] </td><td><strong>60 </strong></td></tr><tr><td>Монтаж при температуре, не ниже [°C] </td><td><strong>0 </strong></td></tr><tr><td>Номинальное переменное напряжение частотой 50 Гц [кВ] </td><td><strong>10 </strong></td></tr><tr><td>Номинальное постоянное напряжение [кВ] </td><td><strong>25 </strong></td></tr><tr><td>Радиус изгиба кабелей [наружных диаметров] </td><td><strong>15 </strong></td></tr><tr><td>Разность уровней, не более [м] </td><td><strong>15 </strong></td></tr><tr><td>Температура окружающей среды, верхний предел [°C] </td><td><strong>+50 </strong></td></tr><tr><td>Температура окружающей среды, нижний предел [°C] </td><td><strong>-50 </strong></td></tr><tr><td>Электрическое сопротивление изоляции, не менее [МОм*км] </td><td><strong>200 </strong></td></tr></tbody></table><p>Срок службы кабелей - не менее 30 лет. </p><table><tbody><tr><td><strong>Количество <br/>и сечение <br/>жил, шт х кв.мм </strong></td><td><strong>Масса кабеля <br/>кг/км </strong></td><td><strong>Наружный диаметр <br/>мм </strong></td></tr><tr><td>СБШВ-10 3х25 ож </td><td>3758 </td><td>40,1 </td></tr><tr><td>СБШВ-10 3х25 </td><td>4089 </td><td>42,4 </td></tr><tr><td>СБШВ-10 3х35 ож </td><td>3905 </td><td>39 </td></tr><tr><td>СБШВ-10 3х35 </td><td>4056 </td><td>40,1 </td></tr><tr><td>СБШВ-10 3х50 ож </td><td>4440 </td><td>40,9 </td></tr><tr><td>СБШВ-10 3х50 </td><td>4706 </td><td>42,7 </td></tr><tr><td>СБШВ-10 3х70 </td><td>5654 </td><td>45,6 </td></tr><tr><td>СБШВ-10 3х95 </td><td>6724 </td><td>48,8 </td></tr><tr><td>СБШВ-10 3х120 </td><td>7793 </td><td>51,5 </td></tr><tr><td>СБШВ-10 3х150 </td><td>8955 </td><td>54,5 </td></tr><tr><td>СБШВ-10 3х185 </td><td>10493 </td><td>57,8 </td></tr><tr><td>СБШВ-10 3х240 </td><td>13347 </td><td>63,8 </td></tr></tbody></table><table><tbody><tr><td>Сечение жил, кв. мм </td><td>Строительная длина, м </td></tr><tr><td>до 70 </td><td>300-450 </td></tr><tr><td>95 и 120 </td><td>250-400 </td></tr><tr><td>150 и более </td><td>200-350 </td></tr></tbody></table></div>','assets/img/products/sbshv-6__4c03d157ab008281541d05e6.jpg','м',NULL,'Укажите марку, число и сечение жил, рабочее напряжение, длину и условия прокладки.',1,0,334,'СБШВ-10 — купить по заявке | Монополия','СБШВ-10: подбор и поставка в Санкт-Петербурге. Укажите марку, число и сечение жил, рабочее напряжение, длину и условия прокладки. Расчет стоимости — по заявке.','site/www.monopoly-torg.ru/267-sbshv-10__82424221ea08452710bb0e74.html','[["Влажность воздуха при 35° C [%]", "98"], ["Гарантийный срок эксплуатации [месяц]", "54"], ["Испытательное переменное напряжение частотой 50 Гц, 5 мин. [кВ]", "25"], ["Максимальная рабочая температура жилы при перегрузке [°С]", "80"], ["Максимальная рабочая температура жилы [°С]", "60"], ["Монтаж при температуре, не ниже [°C]", "0"], ["Номинальное переменное напряжение частотой 50 Гц [кВ]", "10"], ["Номинальное постоянное напряжение [кВ]", "25"], ["Радиус изгиба кабелей [наружных диаметров]", "15"], ["Разность уровней, не более [м]", "15"], ["Температура окружающей среды, верхний предел [°C]", "+50"], ["Температура окружающей среды, нижний предел [°C]", "-50"], ["Электрическое сопротивление изоляции, не менее [МОм*км]", "200"], ["Сечение жил, кв. мм", "Строительная длина, м"], ["до 70", "300-450"], ["95 и 120", "250-400"], ["150 и более", "200-350"]]','["assets/img/products/sbshv-6__4c03d157ab008281541d05e6.jpg"]','["http://www.monopoly-torg.ru/index.php/kabelnaya-produkciya/kabeli-silovye-s-bumazhnoj-izolyatsiej/267-sbshv-10"]') ON DUPLICATE KEY UPDATE `category_id`=VALUES(`category_id`),`root_category`=VALUES(`root_category`),`name`=VALUES(`name`),`slug`=VALUES(`slug`),`sku`=VALUES(`sku`),`short_description`=VALUES(`short_description`),`description_html`=VALUES(`description_html`),`image`=VALUES(`image`),`unit`=VALUES(`unit`),`price`=VALUES(`price`),`request_hint`=VALUES(`request_hint`),`active`=VALUES(`active`),`featured`=VALUES(`featured`),`sort_order`=VALUES(`sort_order`),`seo_title`=VALUES(`seo_title`),`seo_description`=VALUES(`seo_description`),`source_file`=VALUES(`source_file`),`specs_json`=VALUES(`specs_json`),`gallery_json`=VALUES(`gallery_json`),`old_urls_json`=VALUES(`old_urls_json`);
INSERT INTO `products` (`id`,`category_id`,`root_category`,`name`,`slug`,`sku`,`short_description`,`description_html`,`image`,`unit`,`price`,`request_hint`,`active`,`featured`,`sort_order`,`seo_title`,`seo_description`,`source_file`,`specs_json`,`gallery_json`,`old_urls_json`) VALUES (335,14,'cable','СГ -1','268-sg-1','MNP-0335','Кабели СГ -1 предназначены для передачи и распределения электрической энергии в стационарных установках в электрических сетях на напряжение до 35 кВ частотой 50 Гц.','<div><p>СГ -1 </p><p><img alt="aab2l" loading="lazy" src="assets/img/products/sg__36565d2fb4604e9f2885ac4c.jpg"/></p><ol><li>Медная токопроводящая жила: <br/>• однопроволочная сечением 25-50 кв.мм - "ож", <br/>• многопроволочная сечением 25-800 кв.мм; </li><li>Фазная бумажная изоляция, пропитанная вязким изоляционным пропиточным составом; <br/>маркировка жил: <br/>• цифровая: 1, 2, 3, 4, <br/>• цветовая: белая или жёлтая, синяя или зеленая, красная или малиновая, коричневая или чёрная; </li><li>Заполнение из бумажных жгутов; </li><li>Поясная бумажная изоляция, пропитанная вязким изоляционным пропиточным составом; </li><li>Экран из электропроводящей бумаги для кабелей на напряжение от 6 кВ и более; </li><li>Оболочка из свинцового сплава, покрытая вазелином. </li></ol><p><strong>Область применения СГ -1: </strong></p><p>Кабели <strong>СГ -1 </strong>предназначены для передачи и распределения электрической энергии в стационарных установках в электрических сетях на напряжение до 35 кВ частотой 50 Гц. </p><p>Кабели <strong>СГ -1 </strong>предназначены для эксплуатации в макроклиматических районах с умеренным, холодным и тропическим климатом. Кабели предназначены для прокладки во взрывоопасных зонах В-Iб и В-IIа, если отсутствует опасность механических повреждений в ходе эксплуатации. Кабели не распространяют горение при одиночной прокладке (нормы МЭК 60332-1). Кабели предназначены для прокладки в блоках. </p><p><strong>Технические характеристики СГ -1 </strong><br/></p><table><tbod