INSERT INTO `products` (`id`,`category_id`,`root_category`,`name`,`slug`,`sku`,`short_description`,`description_html`,`image`,`unit`,`price`,`request_hint`,`active`,`featured`,`sort_order`,`seo_title`,`seo_description`,`source_file`,`specs_json`,`gallery_json`,`old_urls_json`) VALUES (412,15,'cable','АПВББШП (з)','345-apvbbshp-z','MNP-0412','Силовые кабели АПВББШП (з) предназначены для передачи и распределения электрической энергии в стационарных установках на номинальное переменное напряжение 1,0 кВ частоты 50Гц.','<div><p>АПВББШП (з) </p><p><img alt="apvbbshngals" loading="lazy" src="assets/img/products/apvbbshpz__b41c31743731101a92266cf3.jpg"/></p><ol><li>Токопроводящая жила: <br/>- материал - алюминий: <br/>от 4 до 240 мм2 (однопроволочная жила - ОЖ), <br/>от 25 до 240 мм2 (многопроволочная жила); <br/>- количество жил: 3+1, 4, 5; </li><li>Изоляция из сшитого полиэтилена (цветовая маркировка жил); </li><li>Сердечник; </li><li>Скрепляющая обмотка (для кабелей 50 мм2 и выше); </li><li>Двуслойная поясная изоляция (внутренний слой — резина, <br/>наружный — полиэтилен или ПВХ пластикат); </li><li>Броня из двух стальных оцинкованных лент; </li><li>Защитный шланг из полиэтилена. </li></ol><p><strong>Область применения АПВББШП (з): </strong></p><p>Силовые кабели <strong>АПВББШП (з) </strong>предназначены для передачи и распределения электрической энергии в стационарных установках на номинальное переменное напряжение 1,0 кВ частоты 50Гц. </p><p>Кабели <strong>АПВББШП (з) </strong>изготавливаются для эксплуатации в районах с умеренным и холодным климатом. Кабели предназначены для эксплуатации на суше, реках и озерах на высотах до 4300 м. над уровнем моря. </p><p>Кабели применяются для прокладки: </p><ul><li>в земле (траншеях) с низкой, средней или высокой коррозионной активностью, с наличием или отсутствием блуждающих токов, и если в процессе эксплуатации кабели не подвергаются значительным растягивающим усилиям; </li><li>в грунтах с повышенной влажностью; </li><li>в воде. </li></ul><p>Кабели предназначены для вертикальных, наклонных и горизонтальных трасс. Допустимый нагрев токопроводящих жил в аварийном режиме не должен превышать +130°С и продолжительность работы в аварийном режиме не должна быть более 6 часов в сутки. </p><p><strong>Технические характеристики АПВББШП (з) </strong></p><table><tbody><tr><td>Влажность воздуха при 35° C [%] </td><td><strong>98 </strong></td></tr><tr><td>Испытательное переменное напряжение частотой 50 Гц, 10 мин. [кВ] </td><td><strong>3.5 </strong></td></tr><tr><td>Максимальная рабочая температура жилы [°С] </td><td><strong>90 </strong></td></tr><tr><td>Максимальное переменное напряжение частоты 50 Гц [кВ] </td><td><strong>1.2 </strong></td></tr><tr><td>Монтаж при температуре, не ниже [°C] </td><td><strong>-20 </strong></td></tr><tr><td>Номинальное переменное напряжение частотой 50 Гц [кВ] </td><td><strong>1.0 </strong></td></tr><tr><td>Радиус изгиба кабелей [наружных диаметров] </td><td><strong>7.5 </strong></td></tr><tr><td>Сопротивление изоляции при температуре +90° С, не менее [МОм х км] </td><td><strong>50 </strong></td></tr><tr><td>Температура окружающей среды, верхний предел [°C] </td><td><strong>+50 </strong></td></tr><tr><td>Температура окружающей среды, нижний предел [°C] </td><td><strong>-60 </strong></td></tr><tr><td>Температура токопроводящих жил при коротком замыкании [°С] </td><td><strong>250 </strong></td></tr></tbody></table><p>Срок службы кабелей - 30 лет. </p><table><tbody><tr><td><strong>Количество <br/>и сечение <br/>жил, шт х кв.мм </strong></td><td><strong>Масса <br/>кабеля, <br/>кг/км </strong></td><td><strong>Наружный <br/>диаметр, <br/>мм </strong></td></tr><tr><td>АПВББШП (з) 3х10+1x6 ож </td><td>467 </td><td>19,6 </td></tr><tr><td>АПВББШП (з) 3х16+1x10 ож </td><td>577 </td><td>21,7 </td></tr><tr><td>АПВББШП (з) 3х25+1x16 ож </td><td>773 </td><td>25,3 </td></tr><tr><td>АПВББШП (з) 3х35+1x16 ож </td><td>924 </td><td>28 </td></tr><tr><td>АПВББШП (з) 3х50+1x25 ож </td><td>1180 