INSERT INTO `products` (`id`,`category_id`,`root_category`,`name`,`slug`,`sku`,`short_description`,`description_html`,`image`,`unit`,`price`,`request_hint`,`active`,`featured`,`sort_order`,`seo_title`,`seo_description`,`source_file`,`specs_json`,`gallery_json`,`old_urls_json`) VALUES (432,15,'cable','АПвВнг(А)-LS-20 кВ','365-apvvng-a-ls-20-kv','MNP-0432','Кабели марки АПвВнг(А)-LS-20 кВ могут быть использованы для прокладки во взрывоопасных зонах классов В-Iб, В-Iг, В-II, В-IIа.','<div><p>АПвВнг(А)-LS-20 кВ </p><p><img alt="apvbbshngals" loading="lazy" src="assets/img/products/apvvngals-20__03efe38106388a264d824844.jpg"/></p><ol><li>Круглая многопроволочная уплотненная токопроводящая жила из алюминия, сечение – 50–1000 кв. мм; </li><li>Экран по жиле из экструдируемого электропроводящего сшитого полиэтилена; </li><li>Изоляция из сшитого полиэтилена (Пв); </li><li>Экран по изоляции из экструдируемого электропроводящего сшитого полиэтилена; </li><li>Разделительный слой из электропроводящей ленты; </li><li>Экран из медных проволок, скрепленных медной лентой: <br/>- сечением не менее 16 кв. мм для кабелей с сечением жилы 35–120 кв. мм, <br/>- сечением не менее 25 кв. мм для кабелей с сечением жилы 150–240 кв. мм, <br/>- сечением не менее 35 кв. мм для кабелей с сечением жилы выше 300 кв. мм. <br/><em><strong>Примечание: </strong></em>сечение экрана выбирается в зависимости от токов короткого замыкания, которые необходимо рассчитать согласно условиям прокладки кабельной линии. Возможно изготовление кабеля с увеличенным сечением экрана. </li><li>Разделительный слой из стеклоленты; </li><li>Внутреннее заполнение из ПВХ-пластиката пониженной пожароопасности; </li><li>Разделительный слой из стеклоленты; </li><li>Оболочка из ПВХ-пластиката пониженной пожароопасности. </li></ol><p><br/><strong>Область применения АПвВнг(А)-LS- 20: </strong></p><div>Для групповой прокладки в кабельных сооружениях и производственных помещениях при условии отсутствия опасности механических повреждений. </div><div>Допускается прокладка в сухих грунтах. </div><p>Кабели марки <strong>АПвВнг(А)-LS-20 кВ </strong>могут быть использованы для прокладки во взрывоопасных зонах классов В-Iб, В-Iг, В-II, В-IIа. </p><p>*(А) – предел распространения горения ПРГП 1. </p><p><strong>Технические характеристики АПвВнг(А)-LS- 20 </strong></p><table><tbody><tr><td>Гарантийный срок эксплуатации [год] </td><td><strong>5 </strong></td></tr><tr><td>Допустимый нагрев жил при работе в аварийном режиме [°С] </td><td><strong>+130 </strong></td></tr><tr><td>Максимальная температура жил при коротком замыкании, [°С] </td><td><strong>+250 </strong></td></tr><tr><td>Монтаж без предварительного подогрева при температуре не ниже, [°С] </td><td><strong>-15 </strong></td></tr><tr><td>Номинальное переменное напряжение частотой 50 Гц [кВ] </td><td><strong>20 </strong></td></tr><tr><td>Рабочая температура жилы [°С] </td><td><strong>+90 </strong></td></tr><tr><td>Радиус изгиба кабелей [наружных диаметров] </td><td><strong>15 (7,5) </strong></td></tr><tr><td>Срок службы кабелей не менее, (год) </td><td><strong>30 </strong></td></tr><tr><td>Эксплуатация при температуре окружающей среды, [°С] </td><td><strong>-50/+50 </strong></td></tr></tbody></table></div>','assets/img/products/apvvngals-20__03efe38106388a264d824844.jpg','м',NULL,'Укажите марку, число и сечение жил, рабочее напряжение, длину и условия прокладки.',1,0,432,'АПвВнг(А)-LS-20 кВ — купить по заявке | Монополия','АПвВнг(А)-LS-20 кВ: подбор и поставка в Санкт-Петербурге. Укажите марку, число и сечение жил, рабочее напряжение, длину и условия прокладки. Расчет стоимости — по заявке.','site/www.monopoly-torg.ru/365-apvvng-a-ls-20-kv__38803be92ed84ceaaaf9dfd7.html','[["Гарантийный срок эксплуатации [год]", "5"], ["Допустимый нагрев жил при работе в аварийном режиме [°С]", "+130"], ["Максимальная температура жил при коротком замыкании, [°С]", "+250"], ["Монтаж без предварительного подогрева при температуре не ниже, [°С]", "-15"], ["Номинальное переменное напряжение частотой 50 Гц [кВ]", "20"], ["Рабочая температура жилы [°С]", "+90"], ["Радиус изгиба кабелей [наружных диаметров]", "15 (7,5)"], ["Срок службы кабелей не менее, (год)", "30"], ["Эксплуатация при температуре окружающей среды, [°С]", "-50/+50"]]','["assets/img/products/apvvngals-20__03efe38106388a264d824844.jpg"]','["http://www.monopoly-torg.ru/index.php/kabelnaya-produkciya/kabeli-silovye-s-izolyatsiej-iz-sshitogo-polietilena/365-apvvng-a-ls-20-kv"]') ON DUPLICATE KEY UPDATE `category_id`=VALUES(`category_id`),`root_category`=VALUES(`root_category`),`name`=VALUES(`name`),`slug`=VALUES(`slug`),`sku`=VALUES(`sku`),`short_description`=VALUES(`short_description`),`description_html`=VALUES(`description_html`),`image`=VALUES(`image`),`unit`=VALUES(`unit`),`price`=VALUES(`price`),`request_hint`=VALUES(`request_hint`),`active`=VALUES(`active`),`featured`=VALUES(`featured`),`sort_order`=VALUES(`sort_order`),`seo_title`=VALUES(`seo_title`),`seo_description`=VALUES(`seo_description`),`source_file`=VALUES(`source_file`),`specs_json`=VALUES(`specs_json`),`gallery_json`=VALUES(`gallery_json`),`old_urls_json`=VALUES(`old_urls_json`);
INSERT INTO `products` (`id`,`category_id`,`root_category`,`name`,`slug`,`sku`,`short_description`,`description_html`,`image`,`unit`,`price`,`request_hint`,`active`,`featured`,`sort_order`,`seo_title`,`seo_description`,`source_file`,`specs_json`,`gallery_json`,`old_urls_json`) VALUES (433,15,'cable','АПВВНГ-LS','366-apvvng-ls','MNP-0433','Примечание: Сечение экрана выбирается в зависимости от токов короткого замыкания. Возможно изготовление кабеля с увеличенным сечением экрана.','<div><p>АПВВНГ-LS </p><p><img alt="apvbbshngals" loading="lazy" src="assets/img/products/apvvngls__43b5838b64cec2d38266c7a6.jpg"/></p><ol><li>Круглая многопроволочная уплотнённая токопроводящая жила из алюминия, сечением от 50 до 800 кв.мм. (А); </li><li>Экран по жиле из экструдируемого полупроводящего сшитого полиэтилена; </li><li>Изоляция из сшитого полиэтилена (Пв); </li><li>Экран по изоляции из экструдируемого полупроводящего сшитого полиэтилена; </li><li>Разделительный слой; </li><li>Экран из медных проволок, скреплённых медной лентой: <br/>• сечением не менее 16 кв.мм. для кабелей с сечением жилы 50 - 120 кв.мм.; <br/>• сечением не менее 25 кв.мм. для кабелей с сечением жилы 150 - 300 кв.мм.; <br/>• сечением не менее 35 кв.мм. для кабелей с сечением жилы 400 кв.мм. и более. </li><li>Разделительный слой из прорезиненной ткани или полимерной ленты, для кабелей категории "А" пожарной безопасности накладывается дополнительный слой из слюдосодержащей ленты; </li><li>Оболочка из ПВХ пластиката пониженной пожароопасности (Внг-LS), "нг-LS" - Low Smoke (низкое дымо- и газовыделение). </li></ol><p><em>Примечание: </em>Сечение экрана выбирается в зависимости от токов короткого замыкания. Возможно изготовление кабеля с увеличенным сечением экрана. </p><p><strong>Область применения АПВВНГ-LS: </strong></p><p>Кабели <strong>АПВВНГ-LS </strong>применяются для стационарной прокладки в кабельных сооружениях и производственных помещениях. <br/>Допускается прокладка в сухих грунтах. Кабели прокладываются на трассах без ограничения разности уровней. <br/>Кабели не распространяют горение при прокладке в пучках (ГОСТ 12176-89, раздел 3, категория В). </p><p>Строительная длина кабелей определяется по согласованию с заказчиком. <br/>Допускаются маломерные отрезки длиной не менее 50 метров в количестве не более 5% от общей длины партии. </p><p><strong>Технические характеристики АПВВНГ-LS </strong><br/></p><table><tbody><tr><td>Допустимый нагрев жил при работе в аварийном режиме [°С] </td><td><strong>130 </strong></td></tr><tr><td>Монтаж при температуре, не ниже [°C] </td><td><strong>-15 </strong></td></tr><tr><td>Номинальное переменное напряжение частотой 50 Гц [кВ] </td><td><strong>10 </strong></td></tr><tr><td>Рабочая температура жилы [°С] </td><td><strong>90 </strong></td></tr><tr><td>Радиус изгиба кабелей [наружных диаметров] </td><td><strong>15 </strong></td></tr><tr><td>Температура окружающей среды, верхний предел [°C] </td><td><strong>+50 </strong></td></tr><tr><td>Температура окружающей среды, нижний предел [°C] </td><td><strong>-40 </strong></td></tr><tr><td>Температура токопроводящих жил при коротком замыкании [°С] </td><td><strong>250 </strong></td></tr></tbody></table><p>Срок службы кабелей - 30 лет. </p><table><tbody><tr><td><strong>Номинальное <br/>сечение жилы/экрана, кв. мм </strong></td><td><strong>Масса кабеля <br/>кг/км </strong></td><td><strong>Наружный диаметр <br/>мм </strong></td></tr><tr><td>АПВВНГ-LS 1х50/16 </td><td>907 </td><td>29,6 </td></tr><tr><td>АПВВНГ-LS 1х50/25 </td><td>994 </td><td>29,7 </td></tr><tr><td>АПВВНГ-LS 1х70/16 </td><td>1010 </td><td>31,1 </td></tr><tr><td>АПВВНГ-LS 1х70/25 </td><td>1097 </td><td>31,2 </td></tr><tr><td>АПВВНГ-LS 1х95/16 </td><td>1129 </td><td>32,8 </td></tr><tr><td>АПВВНГ-LS 1х95/25 </td><td>1216 </td><td>32,9 </td></tr><tr><td>АПВВНГ-LS 1х120/16 </td><td>1242 </td><td>34,2 </td></tr><tr><td>АПВВНГ-LS 1х120/25 </td><td>1329 </td><td>34,3 </td></tr><tr><td>АПВВНГ-LS 1х150/25 </td><td>1459 </td><td>35,8 </td></tr><tr><td>АПВВНГ-LS 1х150/35 </td><td>1558 </td><td>35,8 </td></tr><tr><td>АПВВНГ-LS 1х185/25 </td><td>1604 </td><td>37,4 </td></tr><tr><td>АПВВНГ-LS 1х185/35 </td><td>1705 </td><td>37,4 </td></tr><tr><td>АПВВНГ-LS 1х240/25 </td><td>1824 </td><td>39,6 </td></tr><tr><td>АПВВНГ-LS 1х240/35 </td><td>1923 </td><td>39,6 </td></tr><tr><td>АПВВНГ-LS 1х300/25 </td><td>2055 </td><td>41,8 </td></tr><tr><td>АПВВНГ-LS 1х300/35 </td><td>2154 </td><td>41,8 </td></tr><tr><td>АПВВНГ-LS 1х400/35 </td><td>2525 </td><td>45,1 </td></tr><tr><td>АПВВНГ-LS 1х400/50 </td><td>2667 </td><td>45,4 </td></tr><tr><td>АПВВНГ-LS 1х500/35 </td><td>2934 </td><td>47,9 </td></tr><tr><td>АПВВНГ-LS 1х500/50 </td><td>3078 </td><td>48,1 </td></tr><tr><td>АПВВНГ-LS 1х630/35 </td><td>3392 </td><td>51,1 </td></tr><tr><td>АПВВНГ-LS 1х630/50 </td><td>3535 </td><td>51,4 </td></tr><tr><td>АПВВНГ-LS 1x630/70 </td><td>3578 </td><td>49.3 </td></tr><tr><td>АПВВНГ-LS 1х800/35 </td><td>4033 </td><td>54,9 </td></tr><tr><td>АПВВНГ-LS 1х800/50 </td><td>4131 </td><td>55,1 </td></tr></tbody></table></div>','assets/img/products/apvvngls__43b5838b64cec2d38266c7a6.jpg','м',NULL,'Укажите марку, число и сечение жил, рабочее напряжение, длину и условия прокладки.',1,0,433,'АПВВНГ-LS — купить по заявке | Монополия','АПВВНГ-LS: подбор и поставка в Санкт-Петербурге. Укажите марку, число и сечение жил, рабочее напряжение, длину и условия прокладки. Расчет стоимости — по заявке.','site/www.monopoly-torg.ru/366-apvvng-ls__e1435c367150e32a8d3838c0.html','[["Допустимый нагрев жил при работе в аварийном режиме [°С]", "130"], ["Монтаж при температуре, не ниже [°C]", "-15"], ["Номинальное переменное напряжение частотой 50 Гц [кВ]", "10"], ["Рабочая температура жилы [°С]", "90"], ["Радиус изгиба кабелей [наружных диаметров]", "15"], ["Температура окружающей среды, верхний предел [°C]", "+50"], ["Температура окружающей среды, нижний предел [°C]", "-40"], ["Температура токопроводящих жил при коротком замыкании [°С]", "250"]]','["assets/img/products/apvvngls__43b5838b64cec2d38266c7a6.jpg"]','["http://www.monopoly-torg.ru/index.php/kabelnaya-produkciya/kabeli-silovye-s-izolyatsiej-iz-sshitogo-polietilena/366-apvvng-ls"]') ON DUPLICATE KEY UPDATE `category_id`=VALUES(`category_id`),`root_category`=VALUES(`root_category`),`name`=VALUES(`name`),`slug`=VALUES(`slug`),`sku`=VALUES(`sku`),`short_description`=VALUES(`short_description`),`description_html`=VALUES(`description_html`),`image`=VALUES(`image`),`unit`=VALUES(`unit`),`price`=VALUES(`price`),`request_hint`=VALUES(`request_hint`),`active`=VALUES(`active`),`featured`=VALUES(`featured`),`sort_order`=VALUES(`sort_order`),`seo_title`=VALUES(`seo_title`),`seo_description`=VALUES(`seo_description`),`source_file`=VALUES(`source_file`),`specs_json`=VALUES(`specs_json`),`gallery_json`=VALUES(`gallery_json`),`old_urls_json`=VALUES(`old_urls_json`);
INSERT INTO `products` (`id`,`category_id`,`root_category`,`name`,`slug`,`sku`,`short_description`,`description_html`,`image`,`unit`,`price`,`request_hint`,`active`,`featured`,`sort_order`,`seo_title`,`seo_description`,`source_file`,`specs_json`,`gallery_json`,`old_urls_json`) VALUES (434,15,'cable','АПвП-10 кВ','367-apvp-10-kv','MNP-0434','Кабели применяются для стационарной прокладки в кабельных сооружениях и производственных помещениях.','<div><p>АПвП-10 кВ </p><p><img alt="apvbbshngals" loading="lazy" src="assets/img/products/apvp-10__1daaccf7c09086325e3f2a85.jpg"/></p><ol><li>Круглая многопроволочная уплотненная токопроводящая жила из алюминия, сечение – 50–1000 кв. мм; </li><li>Экран по жиле из экструдируемого полупроводящего сшитого полиэтилена; </li><li>Изоляция из сшитого полиэтилена (Пв); </li><li>Экран по изоляции из экструдируемого полупроводящего сшитого полиэтилена; </li><li>Разделительный слой из ленты полупроводящей крепированной бумаги; </li><li>Экран из медных проволок, скрепленных медной лентой: <br/>- сечением не менее 16 кв. мм для кабелей с сечением жилы 35–120 кв. мм, <br/>- сечением не менее 25 кв. мм для кабелей с сечением жилы 150–300 кв. мм, <br/>- сечением не менее 35 кв. мм для кабелей с сечением жилы выше 300 кв. мм, <br/><strong><em>Примечание: </em></strong>сечение экрана выбирается в зависимости от токов короткого замыкания, <br/>которые необходимо рассчитать согласно условиям прокладки кабельной линии. <br/>Возможно изготовление кабеля с увеличенным сечением экрана. </li><li>Разделительный слой из двух лент крепированной бумаги, или прорезиненной ткани, <br/>или полимерной ленты; </li><li>Оболочка из полиэтилена (П). </li></ol><p><strong>Область применения АПвП-10: </strong></p><p>Кабели применяются для стационарной прокладки в кабельных сооружениях и производственных помещениях. </p><p>Герметизированы от проникновения влаги, что позволяет эксплуатировать эти кабели в грунтах с повышенной влажностью и сырых, частично затапливаемых сооружениях, а также по согласованию с предприятием-изготовителем в судоходных и несудоходных водоемах – при соблюдении мер, исключающих механическое повреждение кабеля. </p><p><strong>Технические характеристики АПвП-10 </strong></p><table><tbody><tr><td>Гарантийный срок эксплуатации [год] </td><td><strong>5 </strong></td></tr><tr><td>Допустимый нагрев жил при работе в аварийном режиме [°С] </td><td><strong>+130 </strong></td></tr><tr><td>Максимальная температура жил при коротком замыкании, [°С] </td><td><strong>+250 </strong></td></tr><tr><td>Монтаж без предварительного подогрева при температуре не ниже, [°С] </td><td><strong>-20 </strong></td></tr><tr><td>Номинальное переменное напряжение частотой 50 Гц [кВ] </td><td><strong>10 </strong></td></tr><tr><td>Рабочая температура жилы [°С] </td><td><strong>+90 </strong></td></tr><tr><td>Радиус изгиба кабелей [наружных диаметров] </td><td><strong>15(7,5) </strong></td></tr><tr><td>Срок службы кабелей не менее, (год) </td><td><strong>30 </strong></td></tr><tr><td>Эксплуатация при температуре окружающей среды, [°С] </td><td><strong>-60/+50 </strong></td></tr></tbody></table><table><tbody><tr><td><strong>Сечение, кв, мм </strong></td><td><strong>Наружный диаметр <br/>кабеля, мм </strong></td><td><strong>Масса 1 км одножильного <br/>кабеля, кг </strong></td></tr><tr><td>АПвП-10 1x50/16 </td><td>24,9 </td><td>616 </td></tr><tr><td>АПвП-10 1x70/16 </td><td>26,5 </td><td>704 </td></tr><tr><td>АПвП-10 1x95/16 </td><td>28,1 </td><td>804 </td></tr><tr><td>АПвП-10 1x120/16 </td><td>29,5 </td><td>901 </td></tr><tr><td>АПвП-10 1x150/25 </td><td>31,0 </td><td>1096 </td></tr><tr><td>АПвП-10 1x185/25 </td><td>32,6 </td><td>1216 </td></tr><tr><td>АПвП-10 1x240/25 </td><td>34,8 </td><td>1407 </td></tr><tr><td>АПвП-10 1x300/25 </td><td>37,0 </td><td>1619 </td></tr><tr><td>АПвП-10 1x400/35 </td><td>40,0 </td><td>2032 </td></tr><tr><td>АПвП-10 1x500/35 </td><td>43,5 </td><td>2410 </td></tr><tr><td>АПвП-10 1x630/35 </td><td>47,1 </td><td>2842 </td></tr><tr><td>АПвП-10 1x800/35 </td><td>50,9 </td><td>3411 </td></tr></tbody></table></div>','assets/img/products/apvp-10__1daaccf7c09086325e3f2a85.jpg','м',NULL,'Укажите марку, число и сечение жил, рабочее напряжение, длину и условия прокладки.',1,0,434,'АПвП-10 кВ — купить по заявке | Монополия','АПвП-10 кВ: подбор и поставка в Санкт-Петербурге. Укажите марку, число и сечение жил, рабочее напряжение, длину и условия прокладки. Расчет стоимости — по заявке.','site/www.monopoly-torg.ru/367-apvp-10-kv__64a2dcc2072e84106e8889da.html','[["Гарантийный срок эксплуатации [год]", "5"], ["Допустимый нагрев жил при работе в аварийном режиме [°С]", "+130"], ["Максимальная температура жил при коротком замыкании, [°С]", "+250"], ["Монтаж без предварительного подогрева при температуре не ниже, [°С]", "-20"], ["Номинальное переменное напряжение частотой 50 Гц [кВ]", "10"], ["Рабочая температура жилы [°С]", "+90"], ["Радиус изгиба кабелей [наружных диаметров]", "15(7,5)"], ["Срок службы кабелей не менее, (год)", "30"], ["Эксплуатация при температуре окружающей среды, [°С]", "-60/+50"]]','["assets/img/products/apvp-10__1daaccf7c09086325e3f2a85.jpg"]','["http://www.monopoly-torg.ru/index.php/kabelnaya-produkciya/kabeli-silovye-s-izolyatsiej-iz-sshitogo-polietilena/367-apvp-10-kv"]') ON DUPLICATE KEY UPDATE `category_id`=VALUES(`category_id`),`root_category`=VALUES(`root_category`),`name`=VALUES(`name`),`slug`=VALUES(`slug`),`sku`=VALUES(`sku`),`short_description`=VALUES(`short_description`),`description_html`=VALUES(`description_html`),`image`=VALUES(`image`),`unit`=VALUES(`unit`),`price`=VALUES(`price`),`request_hint`=VALUES(`request_hint`),`active`=VALUES(`active`),`featured`=VALUES(`featured`),`sort_order`=VALUES(`sort_order`),`seo_title`=VALUES(`seo_title`),`seo_description`=VALUES(`seo_description`),`source_file`=VALUES(`source_file`),`specs_json`=VALUES(`specs_json`),`gallery_json`=VALUES(`gallery_json`),`old_urls_json`=VALUES(`old_urls_json`);
