INSERT INTO `products` (`id`,`category_id`,`root_category`,`name`,`slug`,`sku`,`short_description`,`description_html`,`image`,`unit`,`price`,`request_hint`,`active`,`featured`,`sort_order`,`seo_title`,`seo_description`,`source_file`,`specs_json`,`gallery_json`,`old_urls_json`) VALUES (447,15,'cable','АПвПу-10 кВ','380-apvpu-10-kv','MNP-0447','Кабели применяются для стационарной прокладки в кабельных сооружениях и производственных помещениях.','<div><p>АПвПу-10 кВ </p><p><img alt="apvbbshngals" loading="lazy" src="assets/img/products/apvpu-10__627dd85518639f8dd5bb1e68.jpg"/></p><ol><li>Круглая многопроволочная уплотненная токопроводящая жила из алюминия, сечение – 50–1000 кв. мм; </li><li>Экран по жиле из экструдируемого электропроводящего сшитого полиэтилена; </li><li>Изоляция из сшитого полиэтилена (Пв); </li><li>Экран по изоляции из экструдируемого электропроводящего сшитого полиэтилена; </li><li>Разделительный слой из ленты электропроводящей крепированной бумаги; </li><li>Экран из медных проволок, скрепленных медной лентой: <br/>- сечением не менее 16 кв. мм для кабелей с сечением жилы 35–120 кв. мм, <br/>- сечением не менее 25 кв. мм для кабелей с сечением жилы 150–300 кв. мм, <br/>- сечением не менее 35 кв. мм для кабелей с сечением жилы выше 300 кв. мм, <br/><strong><em>Примечание: </em></strong>сечение экрана выбирается в зависимости от токов короткого замыкания, <br/>которые необходимо рассчитать согласно условиям прокладки кабельной линии. <br/>Возможно изготовление кабеля с увеличенным сечением экрана. </li><li>Разделительный слой из двух лент крепированной бумаги, или прорезиненной ткани, или полимерной ленты; </li><li>Оболочка из полиэтилена, увеличенной толщины (Пу). </li></ol><p><strong><br/>Область применения АПвПу-10: </strong></p><p>Кабели применяются для стационарной прокладки в кабельных сооружениях и производственных помещениях. </p><p><strong>Технические характеристики АПвПу-10 </strong></p><table><tbody><tr><td>Гарантийный срок эксплуатации [год] </td><td><strong>5 </strong></td></tr><tr><td>Допустимый нагрев жил при работе в аварийном режиме [°С] </td><td><strong>+130 </strong></td></tr><tr><td>Максимальная температура жил при коротком замыкании, [°С] </td><td><strong>+250 </strong></td></tr><tr><td>Монтаж без предварительного подогрева при температуре не ниже, [°С] </td><td><strong>-20 </strong></td></tr><tr><td>Номинальное переменное напряжение частотой 50 Гц [кВ] </td><td><strong>10 </strong></td></tr><tr><td>Рабочая температура жилы [°С] </td><td><strong>+90 </strong></td></tr><tr><td>Радиус изгиба кабелей [наружных диаметров] </td><td><strong>15(7,5) </strong></td></tr><tr><td>Срок службы кабелей не менее, (год) </td><td><strong>30 </strong></td></tr><tr><td>Эксплуатация при температуре окружающей среды, [°С] </td><td><strong>-60/+50 </strong></td></tr></tbody></table><table><tbody><tr><td><strong>Сечение, кв, мм </strong></td><td><strong>Наружный диаметр <br/>кабеля, мм </strong></td><td><strong>Масса 1 км одножильного <br/>кабеля, кг </strong></td></tr><tr><td>АПвПу-10 1x50/16 </td><td>25,9 </td><td>654 </td></tr><tr><td>АПвПу-10 1x70/16 </td><td>27,5 </td><td>744 </td></tr><tr><td>АПвПу-10 1x95/16 </td><td>29,1 </td><td>847 </td></tr><tr><td>АПвПу-10 1x120/16 </td><td>30,5 </td><td>947 </td></tr><tr><td>АПвПу-10 1x150/25 </td><td>32,0 </td><td>1144 </td></tr><tr><td>АПвПу-10 1x185/25 </td><td>33,6 </td><td>1265 </td></tr><tr><td>АПвПу-10 1x240/25 </td><td>35,8 </td><td>1460 </td></tr><tr><td>АПвПу-10 1x300/25 </td><td>38,0 </td><td>1676 </td></tr><tr><td>АПвПу-10 1x400/35 </td><td>41,0 </td><td>2093 </td></tr><tr><td>АПвПу-10 1x500/35 </td><td>44,5 </td><td>2477 </td></tr><tr><td>АПвПу-10 1x630/35 </td><td>48,1 </td><td>2914 </td></tr><tr><td>АПвПу-10 1x800/35 </td><td>51,9 </td><td>3488 </td></tr></tbody></table></div>','assets/img/products/apvpu-10__627dd85518639f8dd5bb1e68.jpg','м',NULL,'Укажите марку, число и сечение жил, рабочее напряжение, длину и условия прокладки.',1,0,447,'АПвПу-10 кВ — купить по заявке | Монополия','АПвПу-10 кВ: подбор и поставка в Санкт-Петербурге. Укажите марку, число и сечение жил, рабочее напряжение, длину и условия прокладки. Расчет стоимости — по заявке.','site/www.monopoly-torg.ru/380-apvpu-10-kv__fbf762b3de7f55583d8e1894.html','[["Гарантийный срок эксплуатации [год]", "5"], ["Допустимый нагрев жил при работе в аварийном режиме [°С]", "+130"], ["Максимальная температура жил при коротком замыкании, [°С]", "+250"], ["Монтаж без предварительного подогрева при температуре не ниже, [°С]", "-20"], ["Номинальное переменное напряжение частотой 50 Гц [кВ]", "10"], ["Рабочая температура жилы [°С]", "+90"], ["Радиус изгиба кабелей [наружных диаметров]", "15(7,5)"], ["Срок службы кабелей не менее, (год)", "30"], ["Эксплуатация при температуре окружающей среды, [°С]", "-60/+50"]]','["assets/img/products/apvpu-10__627dd85518639f8dd5bb1e68.jpg"]','["http://www.monopoly-torg.ru/index.php/kabelnaya-produkciya/kabeli-silovye-s-izolyatsiej-iz-sshitogo-polietilena/380-apvpu-10-kv"]') ON DUPLICATE KEY UPDATE `category_id`=VALUES(`category_id`),`root_category`=VALUES(`root_category`),`name`=VALUES(`name`),`slug`=VALUES(`slug`),`sku`=VALUES(`sku`),`short_description`=VALUES(`short_description`),`description_html`=VALUES(`description_html`),`image`=VALUES(`image`),`unit`=VALUES(`unit`),`price`=VALUES(`price`),`request_hint`=VALUES(`request_hint`),`active`=VALUES(`active`),`featured`=VALUES(`featured`),`sort_order`=VALUES(`sort_order`),`seo_title`=VALUES(`seo_title`),`seo_description`=VALUES(`seo_description`),`source_file`=VALUES(`source_file`),`specs_json`=VALUES(`specs_json`),`gallery_json`=VALUES(`gallery_json`),`old_urls_json`=VALUES(`old_urls_json`);
INSERT INTO `products` (`id`,`category_id`,`root_category`,`name`,`slug`,`sku`,`short_description`,`description_html`,`image`,`unit`,`price`,`request_hint`,`active`,`featured`,`sort_order`,`seo_title`,`seo_description`,`source_file`,`specs_json`,`gallery_json`,`old_urls_json`) VALUES (448,15,'cable','АПвПу-10 кВ (трехжильный)','381-apvpu-10-kv-trekhzhilnyj','MNP-0448','Кабели применяются для стационарной прокладки в кабельных сооружениях и производственных помещениях.','<div><p>АПвПу-10 кВ (трехжильный) </p><p><img alt="apvbbshngals" loading="lazy" src="assets/img/products/apvpu-10-3__2a5d80b2b9f0f10ad2d8a6ee.jpg"/></p><ol><li>Центральное заполнение из жгута; </li><li>Круглая многопроволочная уплотненная токопроводящая жила из алюминия, <br/>сечение: круглая жила – 50–240 кв. мм, сектроная жила – 120–240 кв. мм; </li><li>Экран по жиле из экструдируемого электропроводящего сшитого полиэтилена; </li><li>Изоляция из сшитого полиэтилена (Пв); </li><li>Экран по изоляции из экструдируемого электропроводящего сшитого полиэтилена; </li><li>Разделительный слой из ленты электропроводящей крепированной бумаги; </li><li>Экран из медных проволок, скрепленных медной лентой: <br/>- сечением не менее 16 кв. мм для кабелей с сечением жилы 35–120 кв. мм, <br/>- сечением не менее 25 кв. мм для кабелей с сечением жилы 150–300 кв. мм, <br/>- сечением не менее 35 кв. мм для кабелей с сечением жилы выше 300 кв. мм, <br/><em><strong>Примечание: </strong></em>сечение экрана выбирается в зависимости от токов короткого замыкания, которые необходимо рассчитать согласно условиям прокладки кабельной линии. Возможно изготовление кабеля с увеличенным сечением экрана. </li><li>Межфазное заполнение из мелонаполненной невулканизированной резиновой смеси; </li><li>Оболочка из полиэтилена увеличенной толщины (Пу). </li></ol><p><strong></strong><br/><strong>Область применения АПвПу-10: </strong></p><p>Кабели применяются для стационарной прокладки в кабельных сооружениях и производственных помещениях. </p><p><strong>Технические характеристики АПвПу-10 </strong></p><table><tbody><tr><td>Гарантийный срок эксплуатации [год] </td><td><strong>5 </strong></td></tr><tr><td>Допустимый нагрев жил при работе в аварийном режиме [°С] </td><td><strong>+130 </strong></td></tr><tr><td>Максимальная температура жил при коротком замыкании, [°С] </td><td><strong>+250 </strong></td></tr><tr><td>Монтаж без предварительного подогрева при температуре не ниже, [°С] </td><td><strong>-20 </strong></td></tr><tr><td>Номинальное переменное напряжение частотой 50 Гц [кВ] </td><td><strong>10 </strong></td></tr><tr><td>Рабочая температура жилы [°С] </td><td><strong>+90 </strong></td></tr><tr><td>Радиус изгиба кабелей [наружных диаметров] </td><td><strong>15(7,5) </strong></td></tr><tr><td>Срок службы кабелей не менее, (год) </td><td><strong>30 </strong></td></tr><tr><td>Эксплуатация при температуре окружающей среды, [°С] </td><td><strong>-60/+50 </strong></td></tr></tbody></table><table><tbody><tr><td><strong>Сечение, кв. мм </strong></td><td><strong>Наружный диаметр <br/>кабеля, мм </strong></td><td><strong>Масса 1 км <br/>одножильного кабеля, кг </strong></td></tr><tr><td>АПвПу-10 3х50/16 </td><td>47,9 </td><td>2731 </td></tr><tr><td>АПвПу-10 3х70/16 </td><td>51,3 </td><td>3192 </td></tr><tr><td>АПвПу-10 3х95/16 </td><td>54,8 </td><td>3706 </td></tr><tr><td>АПвПу-10 3х120/16 </td><td>58,2 </td><td>4209 </td></tr><tr><td>АПвПу-10 3х150/25 </td><td>61,4 </td><td>4766 </td></tr><tr><td>АПвПу-10 3х185/25 </td><td>64,9 </td><td>5374 </td></tr><tr><td>АПвПу-10 3х240/25 </td><td>69,6 </td><td>6303 </td></tr></tbody></table></div>','assets/img/products/apvpu-10-3__2a5d80b2b9f0f10ad2d8a6ee.jpg','м',NULL,'Укажите марку, число и сечение жил, рабочее напряжение, длину и условия прокладки.',1,0,448,'АПвПу-10 кВ (трехжильный) — купить по заявке | Монополия','АПвПу-10 кВ (трехжильный): подбор и поставка в Санкт-Петербурге. Укажите марку, число и сечение жил, рабочее напряжение, длину и условия прокладки. Расчет стоимости — по заявке.','site/www.monopoly-torg.ru/381-apvpu-10-kv-trekhzhilnyj__7066fb2b79d70be89515e76a.html','[["Гарантийный срок эксплуатации [год]", "5"], ["Допустимый нагрев жил при работе в аварийном режиме [°С]", "+130"], ["Максимальная температура жил при коротком замыкании, [°С]", "+250"], ["Монтаж без предварительного подогрева при температуре не ниже, [°С]", "-20"], ["Номинальное переменное напряжение частотой 50 Гц [кВ]", "10"], ["Рабочая температура жилы [°С]", "+90"], ["Радиус изгиба кабелей [наружных диаметров]", "15(7,5)"], ["Срок службы кабелей не менее, (год)", "30"], ["Эксплуатация при температуре окружающей среды, [°С]", "-60/+50"]]','["assets/img/products/apvpu-10-3__2a5d80b2b9f0f10ad2d8a6ee.jpg"]','["http://www.monopoly-torg.ru/index.php/kabelnaya-produkciya/kabeli-silovye-s-izolyatsiej-iz-sshitogo-polietilena/381-apvpu-10-kv-trekhzhilnyj"]') ON DUPLICATE KEY UPDATE `category_id`=VALUES(`category_id`),`root_category`=VALUES(`root_category`),`name`=VALUES(`name`),`slug`=VALUES(`slug`),`sku`=VALUES(`sku`),`short_description`=VALUES(`short_description`),`description_html`=VALUES(`description_html`),`image`=VALUES(`image`),`unit`=VALUES(`unit`),`price`=VALUES(`price`),`request_hint`=VALUES(`request_hint`),`active`=VALUES(`active`),`featured`=VALUES(`featured`),`sort_order`=VALUES(`sort_order`),`seo_title`=VALUES(`seo_title`),`seo_description`=VALUES(`seo_description`),`source_file`=VALUES(`source_file`),`specs_json`=VALUES(`specs_json`),`gallery_json`=VALUES(`gallery_json`),`old_urls_json`=VALUES(`old_urls_json`);
