INSERT INTO `products` (`id`,`category_id`,`root_category`,`name`,`slug`,`sku`,`short_description`,`description_html`,`image`,`unit`,`price`,`request_hint`,`active`,`featured`,`sort_order`,`seo_title`,`seo_description`,`source_file`,`specs_json`,`gallery_json`,`old_urls_json`) VALUES (457,15,'cable','КПнг (А)-FRHF 180','390-kpng-a-frhf-180','MNP-0457','3. Оболочка из полимерной композиции (негорючая, безгалогенная). Наложена с обжатием (с заливкой между жилами).','<div><p>КПнг (А)-FRHF 180 </p><p><img alt="apvbbshngals" loading="lazy" src="assets/img/products/kpngafrhf__144c9ee3c74fb047bcefc76d.jpg"/></p><p><strong>Конструкция КПнг (А)-FRHF 180: </strong></p><p>1. Однопроволочный медный проводник. </p><p>2. Изоляция из керамообразующейся огнестойкой резины </p><p>3. Оболочка из полимерной композиции (негорючая, безгалогенная). Наложена с обжатием (с заливкой между жилами). </p><table><tbody><tr><td><p><strong>Назначение КПнг (А)-FRHF 180: </strong></p><p>Для одиночной и групповой стационарной прокладки на объектах повышенной пожарной опасности для подключения электрических сетей и аварийных систем, в том числе для создания электрических систем обеспечения помещений с большим объемом радиоэлектронной аппаратуры </p></td><td></td><td><p><strong>Варианты исполнения: </strong></p><p>• Число изолированных токопроводящих жил 1;2;3;4;5 </p><p>• Оболочка черного цвета </p><p>• Оболочка другого цвета (на заказ) </p></td></tr></tbody></table><table><tbody><tr><td><p><strong>Условия эксплуатации КПнг (А)-FRHF 180: </strong></p><p>Эксплуатируется внутри и вне помещений, при условии защиты от прямого солнечного излучения и атмосферных осадков. </p><table><tbody><tr><td><p>Напряжение </p></td><td><p>до 1000 В </p></td></tr><tr><td><p>Длительно допустимая температура на токопроводящей жиле </p></td><td><p>200 C </p></td></tr><tr><td><p>Работоспособность, при воздействии пламени </p></td><td>180 минут </td></tr><tr><td><p>Диапазон рабочих температур </p></td><td>от -40 до +120 С </td></tr><tr><td><p>Минимальный радиус изгиба </p></td><td>10 диаметров </td></tr><tr><td><p>Срок службы (минимум) </p></td><td><p>25 лет </p></td></tr></tbody></table></td></tr></tbody></table><table><tbody><tr><td><p>Номинальное сечение жил </p></td><td><p>0,75 </p></td><td><p>1,0 </p></td><td><p>1,5 </p></td><td><p>2,5 </p></td><td><p>4,0 </p></td><td><p>6,0 </p></td></tr><tr><td><p>Электрическое сопротивление токопроводящих жил, в пересчете на 1 км длины и t 20 С Ом, не более </p></td><td><p>24,5 </p></td><td><p>18,1 </p></td><td><p>12,1 </p></td><td><p>7,41 </p></td><td><p>4,61 </p></td><td><p>3,08 </p></td></tr></tbody></table><table><tbody><tr><td><p>Размеры </p></td><td><p>1х0,75 </p></td><td><p>2х0,75 </p></td><td><p>3х0,75 </p></td><td><p>4х0,75 </p></td><td><p>5х0,75 </p></td><td><p>1х1,00 </p></td><td><p>2х1,00 </p></td></tr><tr><td><p>Расчетная масса, кг\\км </p></td><td><p>56 </p></td><td><p>100 </p></td><td><p>121 </p></td><td><p>143 </p></td><td><p>169 </p></td><td><p>61 </p></td><td><p>109 </p></td></tr><tr><td><p>Внешний диаметр, мм </p></td><td><p>6,2 </p></td><td><p>9,2 </p></td><td><p>9,7 </p></td><td><p>10,45 </p></td><td><p>11,4 </p></td><td><p>6,4 </p></td><td><p>9,5 </p></td></tr><tr><td><p>Размеры </p></td><td><p>1х1,50 </p></td><td><p>2х1,50 </p></td><td><p>3х1,50 </p></td><td><p>4х1,50 </p></td><td><p>5х1,50 </p></td><td><p>1х2,50 </p></td><td><p>2х2,50 </p></td></tr><tr><td><p>Расчетная масса, кг\\км </p></td><td><p>70 </p></td><td><p>126 </p></td><td><p>157 </p></td><td><p>190 </p></td><td><p>225 </p></td><td><p>84 </p></td><td><p>155 </p></td></tr><tr><td><p>Внешний диаметр, мм </p></td><td><p>6,6 </p></td><td><p>10,0 </p></td><td><p>10,6 </p></td><td><p>11,45 </p></td><td><p>12,45 </p></td><td><p>7,0 </p></td><td><p>10,8 </p></td></tr><tr><td><p>Размеры </p></td><td><p>1х4,00 </p></td><td><p>2х4,00 </p></td><td><p>3х4,00 </p></td><td><p>4х4,00 </p></td><td><p>5х4,00 </p></td><td><p>1х6,00 </p></td><td><p>2х6,00 </p></td></tr><tr><td><p