INSERT INTO `products` (`id`,`category_id`,`root_category`,`name`,`slug`,`sku`,`short_description`,`description_html`,`image`,`unit`,`price`,`request_hint`,`active`,`featured`,`sort_order`,`seo_title`,`seo_description`,`source_file`,`specs_json`,`gallery_json`,`old_urls_json`) VALUES (458,15,'cable','ПБбПГнг-HF-1','391-pbbpgng-hf-1','MNP-0458','Бронированные кабели применяются для прокладки в помещениях и кабельных сооружениях при наличии опасности механических повреждений при эксплуатации.','<div><p>ПБбПГнг-HF-1 </p><p><img alt="apvbbshngals" loading="lazy" src="assets/img/products/pbbpgng-hf__516524836c28930df1ec77aa.jpg"/></p><div><strong>Область применения ПБбПГнг-HF -1 </strong></div><div>Силовые и контрольные кабели, не распространяющие горение, с изоляцией и оболочкой из полимерных композиций, не содержащих галогенов. Предназначены для передачи и распределения электроэнергии в стационарных установках при номинальном переменном напряжении 0,66 и 1 кВ частотой до 100 Гц. </div><div>Кабели изготовляются для общепромышленного применения и применения в системах АС класса 3Н по классификации ПНАЭ Г-1-011-97. </div><div>Климатическое исполнение В, категории размещения 3, 4 по ГОСТ 15150-69. </div><div>Применяются для прокладки в помещениях и кабельных сооружениях при отсутствии опасности механических повреждений при эксплуатации. </div><p>Бронированные кабели применяются для прокладки в помещениях и кабельных сооружениях при наличии опасности механических повреждений при эксплуатации. </p><p><strong>Технические характеристики ПБбПГнг-HF -1 </strong><br/></p><table><tbody><tr><td>Влажность воздуха при 35° C [%] </td><td><strong>98 </strong></td></tr><tr><td>Испытательное переменное напряжение частотой 50 Гц, 10 мин. [кВ] </td><td><strong>3,5 </strong></td></tr><tr><td>Максимальная рабочая температура жилы [°С] </td><td><strong>+70 </strong></td></tr><tr><td>Максимальное переменное напряжение частоты 50 Гц [кВ] </td><td><strong>1,2 </strong></td></tr><tr><td>Монтаж при температуре, не ниже [°C] </td><td><strong>-15 </strong></td></tr><tr><td>Номинальное переменное напряжение частотой 50 Гц [кВ] </td><td><strong>1 </strong></td></tr><tr><td>Радиус изгиба многожильных кабелей, не менее [наружных диаметров] </td><td><strong>7,5 </strong></td></tr><tr><td>Радиус изгиба одножильных кабелей, не менее [наружных диаметров] </td><td><strong>10 </strong></td></tr><tr><td>Сопротивление изоляции при температуре +70° С, не менее [МОм х км] </td><td><strong>0,005 </strong></td></tr><tr><td>Температура окружающей среды, верхний предел [°C] </td><td><strong>+50 </strong></td></tr><tr><td>Температура окружающей среды, нижний предел [°C] </td><td><strong>-30 </strong></td></tr><tr><td>Температура токопроводящих жил при коротком замыкании [°С] </td><td><strong>160 </strong></td></tr></tbody></table><p>. <br/></p><table><tbody><tr><td><strong>Количество и сечение жил, </strong></td><td><strong>Расчётная масса кабеля, кг/км </strong></td><td><strong>Расчётный <br/>наружный диаметр, мм </strong></td></tr><tr><td>шт. х кв. мм </td><td></td><td></td></tr><tr><td>ПБбПГнг-HF -1 2х4 </td><td>480 </td><td>18,5 </td></tr><tr><td>ПБбПГнг-HF -1 2х6 </td><td>562 </td><td>19,4 </td></tr><tr><td>ПБбПГнг-HF -1 2х10 </td><td>731 </td><td>21,4 </td></tr><tr><td>ПБбПГнг-HF -1 2х16 </td><td>928 </td><td>23,3 </td></tr><tr><td>ПБбПГнг-HF -1 2х25 </td><td>1261 </td><td>26,4 </td></tr><tr><td>ПБбПГнг-HF -1 2х35 </td><td>1534 </td><td>28,3 </td></tr><tr><td>ПБбПГнг-HF -1 2х50 </td><td>1486 </td><td>23,3 </td></tr><tr><td>ПБбПГнг-HF -1 2х70 </td><td>1936 </td><td>25,0 </td></tr><tr><td>ПБбПГнг-HF -1 2х95 </td><td>2492 </td><td>28,0 </td></tr><tr><td>ПБбПГнг-HF -1 2х120 </td><td>3036 </td><td>31,1 </td></tr><tr><td>ПБбПГнг-HF -1 2х150 </td><td>3677 </td><td>33,6 </td></tr><tr><td>ПБбПГнг-HF -1 2х185 </td><td>4565 </td><td>41,8 </td></tr><tr><td>ПБбПГнг-HF -1 2х240 </td><td>5807 </td><td>47,2 </td></tr><tr><td>ПБбПГнг-HF -1 3х4 </td><td>541 </td><td>19,0 </td></tr><tr><td>П