INSERT INTO `products` (`id`,`category_id`,`root_category`,`name`,`slug`,`sku`,`short_description`,`description_html`,`image`,`unit`,`price`,`request_hint`,`active`,`featured`,`sort_order`,`seo_title`,`seo_description`,`source_file`,`specs_json`,`gallery_json`,`old_urls_json`) VALUES (464,15,'cable','ПвБВнг(А)-LS, 10 кВ (трехжильный)','397-pvbvng-a-ls-10-kv-trekhzhilnyj','MNP-0464','ПвБВнг(А)-LS, 10 кВ (трехжильный) для промышленных, строительных и энергетических объектов.','<div><p>ПвБВнг(А)-LS, 10 кВ (трехжильный) </p><p><img alt="apvbv" loading="lazy" src="assets/img/products/pvbvngals-10-3__a0417db3b2755ae79280ecf9.jpg"/></p><ul><li>Центральное заполнение из ПВХ-жгута пониженной пожарной опасности или медная <br/>проволока в центре сердечника кабелей с секторными жилами; </li></ul><ol><li>Круглая или секторная многопроволочная уплотненная токопроводящая жила из меди; <br/>сечение: круглая жила – 50–240 кв. мм, секторная жила – 120–240 кв. мм ; </li><li>Экран по жиле из экструдируемого электропроводящего сшитого полиэтилена; </li><li>Изоляция из сшитого полиэтилена (Пв); </li><li>Экран по изоляции из экструдируемого электропроводящего сшитого полиэтилена; </li><li>Разделительный слой из электропроводящей ленты; </li><li>Экран из медных проволок, скрепленных медной лентой (для кабелей с секторными <br/>жилами накладывается общий экран поверх трех изолированных жил): <br/>- сечением не менее 16 кв. мм для кабелей с сечением жилы 50–120 кв. мм, <br/>- сечением не менее 25 кв. мм для кабелей с сечением жилы 150–240 кв. мм, <br/>- сечением не менее 35 кв. мм для кабелей с сечением жилы выше 300 кв. мм. <br/><strong><em>Примечание: </em></strong>сечение экрана выбирается в зависимости от токов короткого замыкания, которые необходимо рассчитать согласно условиям прокладки кабельной линии. Возможно изготовление кабеля с увеличенным сечением экрана. </li><li>Межфазное заполнение из ПВХ-пластиката пониженной пожароопасности; </li><li>Броня из стальных оцинкованных лент (Б); </li><li>Оболочка из ПВХ-пластиката пониженной пожароопасности. </li></ol><p><br/><strong>Область применения ПвБВнг(А)-LS-10: </strong></p><div>Для групповой прокладки в кабельных сооружениях и производственных помещениях при условии отсутствия опасности механических повреждений. </div><div>Допускается прокладка в сухих грунтах. </div><div>Кабели марки ПвВнг-LS могут быть использованы для прокладки во взрывоопасных зонах классов В-I, В-Iа. </div><p><strong>Технические характеристики ПвБВнг(А)-LS-10 </strong></p><table><tbody><tr><td>Гарантийный срок эксплуатации [год] </td><td><strong>5 </strong></td></tr><tr><td>Допустимый нагрев жил при работе в аварийном режиме [°С] </td><td><strong>+130 </strong></td></tr><tr><td>Максимальная температура жил при коротком замыкании, [°С] </td><td><strong>+250 </strong></td></tr><tr><td>Монтаж без предварительного подогрева при температуре не ниже, [°С] </td><td><strong>-20 </strong></td></tr><tr><td>Номинальное переменное напряжение частотой 50 Гц [кВ] </td><td><strong>10 </strong></td></tr><tr><td>Рабочая температура жилы [°С] </td><td><strong>+90 </strong></td></tr><tr><td>Радиус изгиба кабелей [наружных диаметров] </td><td><strong>15(7,5) </strong></td></tr><tr><td>Срок службы кабелей не менее, (год) </td><td><strong>30 </strong></td></tr><tr><td>Эксплуатация при температуре окружающей среды, [°С] </td><td><strong>-60/+50 </strong></td></tr></tbody></table><table><tbody><tr><td><strong>Сечение, кв. мм </strong></td><td><strong>Наружный диаметр <br/>кабеля, мм </strong></td><td><strong>Масса 1 км одножильного <br/>кабеля, кг </strong></td><td></td></tr><tr><td>ПвБВнг(А)-LS-10 3х50/16 </td><td>52.7 </td><td>5095 </td><td></td></tr><tr><td>ПвБВнг(А)-LS-10 3х70/16 </td><td>56.1 </td><td>6049 </td><td></td></tr><tr><td>ПвБВнг(А)-LS-10 3х95/16 </td><td>60 </td><td>7219 </td><td></td></tr><tr><td>ПвБВнг(А)-LS-10 3х120/16 </td><td>63 </td><td>8266 </td><td></td></tr><tr><td>ПвБВнг(А)-LS-10 3х150/25 </td><td>66.2 </td><td>9510 </td><