INSERT INTO `products` (`id`,`category_id`,`root_category`,`name`,`slug`,`sku`,`short_description`,`description_html`,`image`,`unit`,`price`,`request_hint`,`active`,`featured`,`sort_order`,`seo_title`,`seo_description`,`source_file`,`specs_json`,`gallery_json`,`old_urls_json`) VALUES (471,15,'cable','ПвБП, 6 кВ (трехжильный)','404-pvbp-6-kv-trekhzhilnyj','MNP-0471','Кабели применяются для стационарной прокладки в кабельных сооружениях и производственных помещениях.','<div><p>ПвБП, 6 кВ (трехжильный) </p><p><img alt="apvbbshp" loading="lazy" src="assets/img/products/pvbp-6-3__98fe3d582b7190b46add05bf.jpg"/></p><ol><li>Центральное заполнение из жгута; </li><li>Круглая многопроволочная уплотненная токопроводящая жила из меди, сечение: <br/>круглая жила – 35–240 кв. мм, секторная жила – 120–240 кв. мм; </li><li>Экран по жиле из экструдируемого электропроводящего сшитого полиэтилена; </li><li>Изоляция из сшитого полиэтилена (Пв); </li><li>Экран по изоляции из экструдируемого электропроводящего сшитого полиэтилена; </li><li>Разделительный слой из ленты электропроводящей крепированной бумаги; </li><li>Экран из медных проволок, скрепленных медной лентой: <br/>- сечением не менее 16 кв. мм для кабелей с сечением жилы 35–120 кв. мм, <br/>- сечением не менее 25 кв. мм для кабелей с сечением жилы 150–300 кв. мм, <br/>- сечением не менее 35 кв. мм для кабелей с сечением жилы выше 300 кв. мм, <br/><em><strong>Примечание: </strong></em>сечение экрана выбирается в зависимости от токов короткого замыкания, которые необходимо рассчитать согласно условиям прокладки кабельной линии. Возможно изготовление кабеля с увеличенным сечением экрана. </li><li>Межфазное заполнение из мелонаполненной невулканизированной резиновой смеси; </li><li>Внутренняя оболочка из полиэтилена; </li><li>Броня из стальных оцинкованных лент; </li><li>Оболочка из полиэтилена (П). </li></ol><p><strong></strong><br/><strong>Область применения ПвБП, 6 кВ (трехжильный): </strong></p><p>Кабели применяются для стационарной прокладки в кабельных сооружениях и производственных помещениях. </p><p><strong>Технические характеристики ПвБП, 6 кВ (трехжильный) </strong></p><table><tbody><tr><td>Гарантийный срок эксплуатации [год] </td><td><strong>5 </strong></td></tr><tr><td>Допустимый нагрев жил при работе в аварийном режиме [°С] </td><td><strong>+130 </strong></td></tr><tr><td>Максимальная температура жил при коротком замыкании, [°С] </td><td><strong>+250 </strong></td></tr><tr><td>Монтаж без предварительного подогрева при температуре не ниже, [°С] </td><td><strong>-20 </strong></td></tr><tr><td>Номинальное переменное напряжение частотой 50 Гц [кВ] </td><td><strong>6 </strong></td></tr><tr><td>Рабочая температура жилы [°С] </td><td><strong>+90 </strong></td></tr><tr><td>Радиус изгиба кабелей [наружных диаметров] </td><td><strong>15(7,5) </strong></td></tr><tr><td>Срок службы кабелей не менее, (год) </td><td><strong>30 </strong></td></tr><tr><td>Эксплуатация при температуре окружающей среды, [°С] </td><td><strong>-60/+50 </strong></td></tr></tbody></table><table><tbody><tr><td><strong>Сечение, кв. мм </strong></td><td><strong>Наружный диаметр <br/>кабеля, мм </strong></td><td><strong>Масса 1 км одножильного <br/>кабеля, кг </strong></td><td></td></tr><tr><td>ПвБП- 6 3х35/16 </td><td>43.5 </td><td>3207 </td><td></td></tr><tr><td>ПвБП- 6 3х50/16 </td><td>46.7 </td><td>3897 </td><td></td></tr><tr><td>ПвБП- 6 3х70/16 </td><td>50.1 </td><td>4765 </td><td></td></tr><tr><td>ПвБП- 6 3х95/16 </td><td>53.5 </td><td>5759 </td><td></td></tr><tr><td>ПвБП- 6 3х120/16 </td><td>56.9 </td><td>6779 </td><td></td></tr><tr><td>ПвБП- 6 3х150/25 </td><td>60.2 </td><td>7939 </td><td></td></tr><tr><td>ПвБП- 6 3х185/25 </td><td>63.6 </td><td>9264 </td><td></td></tr><tr><td>ПвБП- 6 3х240/25 </td><td>68.8 </td><td>11352 </td></tr></tbody></table></div>','assets/img/products/pvbp-6-3__98fe3d582b7190b46add05bf.jpg','м',NULL,'Укажите марку, число и сечение жил, рабочее напряжение, длину и условия прокладки.',1,0,471