INSERT INTO `products` (`id`,`category_id`,`root_category`,`name`,`slug`,`sku`,`short_description`,`description_html`,`image`,`unit`,`price`,`request_hint`,`active`,`featured`,`sort_order`,`seo_title`,`seo_description`,`source_file`,`specs_json`,`gallery_json`,`old_urls_json`) VALUES (489,15,'cable','ПвП-20','422-pvp-20','MNP-0489','Кабели ПвП-20 применяются для стационарной прокладки в кабельных сооружениях и производственных помещениях.','<div><p>ПвП-20 </p><p><img alt="apvbbshpz" loading="lazy" src="assets/img/products/pvp-20__ac43348d853d98441b929773.jpg"/></p><ol><li>Круглая многопроволочная уплотненная токопроводящая жила из меди, сечение – 50–1000 кв. мм; </li><li>Экран по жиле из экструдируемого электропроводящего сшитого полиэтилена; </li><li>Изоляция из сшитого полиэтилена (Пв); </li><li>Экран по изоляции из экструдируемого электропроводящего сшитого полиэтилена; </li><li>Разделительный слой из ленты электропроводящей крепированной бумаги; </li><li>Экран из медных проволок, скрепленных медной лентой: <br/>- сечением не менее 16 кв. мм для кабелей с сечением жилы 35–120 кв. мм, <br/>- сечением не менее 25 кв. мм для кабелей с сечением жилы 150–300 кв. мм, <br/>- сечением не менее 35 кв. мм для кабелей с сечением жилы выше 300 кв. мм, <br/><strong><em>Примечание: </em></strong>сечение экрана выбирается в зависимости от токов короткого замыкания, <br/>которые необходимо рассчитать согласно условиям прокладки кабельной линии. <br/>Возможно изготовление кабеля с увеличенным сечением экрана. </li><li>Разделительный слой из двух лент крепированной бумаги, или прорезиненной ткани, <br/>или полимерной ленты; </li><li>Оболочка из полиэтилена (П). </li></ol><p><strong><br/>Область применения ПвП-20: </strong></p><p>Кабели ПвП-20 применяются для стационарной прокладки в кабельных сооружениях и производственных помещениях. </p><p><strong>Технические характеристики ПвП-20 </strong></p><table><tbody><tr><td>Гарантийный срок эксплуатации [год] </td><td><strong>5 </strong></td></tr><tr><td>Допустимый нагрев жил при работе в аварийном режиме [°С] </td><td><strong>+130 </strong></td></tr><tr><td>Максимальная температура жил при коротком замыкании, [°С] </td><td><strong>+250 </strong></td></tr><tr><td>Монтаж без предварительного подогрева при температуре не ниже, [°С] </td><td><strong>-20 </strong></td></tr><tr><td>Номинальное переменное напряжение частотой 50 Гц [кВ] </td><td><strong>20 </strong></td></tr><tr><td>Рабочая температура жилы [°С] </td><td><strong>+90 </strong></td></tr><tr><td>Радиус изгиба кабелей [наружных диаметров] </td><td><strong>15(7,5) </strong></td></tr><tr><td>Срок службы кабелей не менее, (год) </td><td><strong>30 </strong></td></tr><tr><td>Эксплуатация при температуре окружающей среды, [°С] </td><td><strong>-60/+50 </strong></td></tr></tbody></table><table><tbody><tr><td><strong>Сечение, кв, мм </strong></td><td><strong>Наружный диаметр <br/>кабеля, мм </strong></td><td><strong>Масса 1 км одножильного <br/>кабеля, кг </strong></td></tr><tr><td>ПвП-20 1x35/16 </td><td>22,0 </td><td>723 </td></tr><tr><td>ПвП-20 1x50/16 </td><td>29,1 </td><td>1082 </td></tr><tr><td>ПвП-20 1x70/16 </td><td>30,7 </td><td>1304 </td></tr><tr><td>ПвП-20 1x95/16 </td><td>32,3 </td><td>1570 </td></tr><tr><td>ПвП-20 1x120/16 </td><td>33,7 </td><td>1831 </td></tr><tr><td>ПвП-20 1x150/25 </td><td>35,2 </td><td>2225 </td></tr><tr><td>ПвП-20 1x185/25 </td><td>36,8 </td><td>2581 </td></tr><tr><td>ПвП-20 1x240/25 </td><td>39,0 </td><td>3131 </td></tr><tr><td>ПвП-20 1x300/25 </td><td>41,7 </td><td>3756 </td></tr><tr><td>ПвП-20 1x400/35 </td><td>45,1 </td><td>4848 </td></tr><tr><td>ПвП-20 1x500/35 </td><td>48,1 </td><td>5834 </td></tr><tr><td>ПвП-20 1x630/35 </td><td>51,3 </td><td>7087 </td></tr><tr><td>ПвП-20 1x800/35 </td><td>55,5 </td><td>8750 </td></tr></tbody></table></div>','assets/img/products/pvp-20__ac43348d853d98441b929773.jpg','м',NULL,'Укажите марку, число и сечение жил, рабочее напряжение, длину и условия прокладки.',1,0,489,'ПвП-20 — купить по заявке | Монополия','ПвП-20: подбор и поставка в Санкт-Петербурге. Укажите марку, число и сечение жил, рабочее напряжение, длину и условия прокладки. Расчет стоимости — по заявке.','site/www.monopoly-torg.ru/422-pvp-20__a953edac778bb5b4a4dcf074.html','[["Гарантийный срок эксплуатации [год]", "5"], ["Допустимый нагрев жил при работе в аварийном режиме [°С]", "+130"], ["Максимальная температура жил при коротком замыкании, [°С]", "+250"], ["Монтаж без предварительного подогрева при температуре не ниже, [°С]", "-20"], ["Номинальное переменное напряжение частотой 50 Гц [кВ]", "20"], ["Рабочая температура жилы [°С]", "+90"], ["Радиус изгиба кабелей [наружных диаметров]", "15(7,5)"], ["Срок службы кабелей не менее, (год)", "30"], ["Эксплуатация при температуре окружающей среды, [°С]", "-60/+50"]]','["assets/img/products/pvp-20__ac43348d853d98441b929773.jpg"]','["http://www.monopoly-torg.ru/index.php/kabelnaya-produkciya/kabeli-silovye-s-izolyatsiej-iz-sshitogo-polietilena/422-pvp-20"]') ON DUPLICATE KEY UPDATE `category_id`=VALUES(`category_id`),`root_category`=VALUES(`root_category`),`name`=VALUES(`name`),`slug`=VALUES(`slug`),`sku`=VALUES(`sku`),`short_description`=VALUES(`short_description`),`description_html`=VALUES(`description_html`),`image`=VALUES(`image`),`unit`=VALUES(`unit`),`price`=VALUES(`price`),`request_hint`=VALUES(`request_hint`),`active`=VALUES(`active`),`featured`=VALUES(`featured`),`sort_order`=VALUES(`sort_order`),`seo_title`=VALUES(`seo_title`),`seo_description`=VALUES(`seo_description`),`source_file`=VALUES(`source_file`),`specs_json`=VALUES(`specs_json`),`gallery_json`=VALUES(`gallery_json`),`old_urls_json`=VALUES(`old_urls_json`);
INSERT INTO `products` (`id`,`category_id`,`root_category`,`name`,`slug`,`sku`,`short_description`,`description_html`,`image`,`unit`,`price`,`request_hint`,`active`,`featured`,`sort_order`,`seo_title`,`seo_description`,`source_file`,`specs_json`,`gallery_json`,`old_urls_json`) VALUES (490,15,'cable','ПвП2г','423-pvp2g','MNP-0490','Примечание: Сечение экрана выбирается в зависимости от токов короткого замыкания. Возможно изготовление кабеля с увеличенным сечением экрана.','<div><p>ПвП2г </p><p><img alt="apvbbshp" loading="lazy" src="assets/img/products/pvp2g__655ff4b753cee1af514691d2.jpg"/></p><ol><li>Круглая многопроволочная уплотнённая токопроводящая жила из меди, сечением от 185 до 1600 кв.мм.; </li><li>Экран по жиле из экструдируемого полупроводящего сшитого полиэтилена; </li><li>Изоляция из сшитого полиэтилена (Пв); </li><li>Экран по изоляции из экструдируемого полупроводящего сшитого полиэтилена; </li><li>Разделительный слой из электропроводящей водоблокирующей ленты (Г); </li><li>Экран из медных проволок, скреплённых медной лентой; </li><li>Разделительный слой из водоблокирующей ленты; </li><li>Слой из алюмополимерной ленты (2Г); </li><li>Оболочка из полиэтилена (П); </li></ol><p><em>Примечание: </em>Сечение экрана выбирается в зависимости от токов короткого замыкания. Возможно изготовление кабеля с увеличенным сечением экрана. </p><p><strong>Область применения ПвП2г: </strong></p><p>Применяются для стационарной прокладки в земле (в траншеях) независимо от степени коррозионной активности грунтов и вод. Кабели герметизированы от проникновения влаги, что позволяет эксплуатировать кабели в грунтах с повышенной влажностью и сырых, частично затапливаемых сооружениях, а также, по согласованию с предприятием изготовителем, в несудоходных водоёмах и в судоходных - при соблюдении мер, исключающих механические повреждения кабеля. </p><p>Допускается прокладка на воздухе без защиты от солнечной радиации, в том числе в кабельных сооружениях, при условии обеспечения дополнительных мер противопожарной защиты, например, нанесения огнезащитных покрытий. Кабели прокладываются на трассах без ограничения разности уровней. </p><p><strong>Технические характеристики ПвП2г </strong></p><table><tbody><tr><td>Допустимый нагрев жил при работе в аварийном режиме [°С] </td><td><strong>130 </strong></td></tr><tr><td>Монтаж при температуре, не ниже [°C] </td><td><strong>-20 </strong></td></tr><tr><td>Номинальное переменное напряжение частотой 50 Гц [кВ] </td><td><strong>110 </strong></td></tr><tr><td>Рабочая температура жилы [°С] </td><td><strong>90 </strong></td></tr><tr><td>Радиус изгиба кабелей [наружных диаметров] </td><td><strong>15 </strong></td></tr><tr><td>Температура окружающей среды, верхний предел [°C] </td><td><strong>+50 </strong></td></tr><tr><td>Температура окружающей среды, нижний предел [°C] </td><td><strong>-60 </strong></td></tr><tr><td>Температура токопроводящих жил при коротком замыкании [°С] </td><td><strong>250 </strong></td></tr></tbody></table><p>Срок службы кабелей - 30 лет. </p><table><tbody><tr><td><strong>Номинальное <br/>сечение жилы/экрана, кв. мм </strong></td><td><strong>Масса кабеля <br/>кг/км </strong></td><td><strong>Наружный диаметр <br/>мм </strong></td></tr><tr><td>ПвП2г 1х50/16 </td><td>958,94 </td><td>26,0 </td></tr><tr><td>ПвП2г 1х50/25 </td><td>1042,20 </td><td>26,0 </td></tr><tr><td>ПвП2г 1х70/16 </td><td>1172,51 </td><td>27,6 </td></tr><tr><td>ПвП2г 1х70/25 </td><td>1255,77 </td><td>27,6 </td></tr><tr><td>ПвП2г 1х95/16 </td><td>1430,76 </td><td>29,2 </td></tr><tr><td>ПвП2г 1х95/25 </td><td>1514,02 </td><td>29,2 </td></tr><tr><td>ПвП2г 1х120/16 </td><td>1684,67 </td><td>30,6 </td></tr><tr><td>ПвП2г 1х120/25 </td><td>1767,93 </td><td>30,6 </td></tr><tr><td>ПвП2г 1х150/25 </td><td>2068,36 </td><td>32,1 </td></tr><tr><td>ПвП2г 1х150/35 </td><td>2151,62 </td><td>32,1 </td></tr><tr><td>ПвП2г 1х185/25 </td><td>2415,96 </td><td>33,7 </td></tr><tr><td>ПвП2г 1х185/35 </td><td>2499,22 </td><td>33,7 </td></tr><tr><td>ПвП2г 1х240/25 </td><td>2955,36 </td><td>35,9 </td></tr><tr><td>ПвП2г 1х240/35 </td><td>3038,62 </td><td>35,9 </td></tr><tr><td>ПвП2г 1х300/25 </td><td>3539,45 </td><td>38,1 </td></tr><tr><td>ПвП2г 1х300/35 </td><td>3622,71 </td><td>38,1 </td></tr><tr><td>ПвП2г 1х400/35 </td><td>4584,70 </td><td>41,1 </td></tr><tr><td>ПвП2г 1х400/50 </td><td>4716,80 </td><td>41,1 </td></tr><tr><td>ПвП2г 1х500/35 </td><td>5543,70 </td><td>44,1 </td></tr><tr><td>ПвП2г 1х500/50 </td><td>5675,81 </td><td>44,1 </td></tr><tr><td>ПвП2г 1х630/35 </td><td>6803,81 </td><td>47,7 </td></tr><tr><td>ПвП2г 1х630/50 </td><td>6935,91 </td><td>47,7 </td></tr><tr><td>ПвП2г 1х800/35 </td><td>8411,12 </td><td>51,5 </td></tr><tr><td>ПвП2г 1х800/50 </td><td>8544,50 </td><td>51,5 </td></tr></tbody></table></div>','assets/img/products/pvp2g__655ff4b753cee1af514691d2.jpg','м',NULL,'Укажите марку, число и сечение жил, рабочее напряжение, длину и условия прокладки.',1,0,490,'ПвП2г — купить по заявке | Монополия','ПвП2г: подбор и поставка в Санкт-Петербурге. Укажите марку, число и сечение жил, рабочее напряжение, длину и условия прокладки. Расчет стоимости — по заявке.','site/www.monopoly-torg.ru/423-pvp2g__784eb7c16318bf7a56a6d2d9.html','[["Допустимый нагрев жил при работе в аварийном режиме [°С]", "130"], ["Монтаж при температуре, не ниже [°C]", "-20"], ["Номинальное переменное напряжение частотой 50 Гц [кВ]", "110"], ["Рабочая температура жилы [°С]", "90"], ["Радиус изгиба кабелей [наружных диаметров]", "15"], ["Температура окружающей среды, верхний предел [°C]", "+50"], ["Температура окружающей среды, нижний предел [°C]", "-60"], ["Температура токопроводящих жил при коротком замыкании [°С]", "250"]]','["assets/img/products/pvp2g__655ff4b753cee1af514691d2.jpg"]','["http://www.monopoly-torg.ru/index.php/kabelnaya-produkciya/kabeli-silovye-s-izolyatsiej-iz-sshitogo-polietilena/423-pvp2g"]') ON DUPLICATE KEY UPDATE `category_id`=VALUES(`category_id`),`root_category`=VALUES(`root_category`),`name`=VALUES(`name`),`slug`=VALUES(`slug`),`sku`=VALUES(`sku`),`short_description`=VALUES(`short_description`),`description_html`=VALUES(`description_html`),`image`=VALUES(`image`),`unit`=VALUES(`unit`),`price`=VALUES(`price`),`request_hint`=VALUES(`request_hint`),`active`=VALUES(`active`),`featured`=VALUES(`featured`),`sort_order`=VALUES(`sort_order`),`seo_title`=VALUES(`seo_title`),`seo_description`=VALUES(`seo_description`),`source_file`=VALUES(`source_file`),`specs_json`=VALUES(`specs_json`),`gallery_json`=VALUES(`gallery_json`),`old_urls_json`=VALUES(`old_urls_json`);
INSERT INTO `products` (`id`,`category_id`,`root_category`,`name`,`slug`,`sku`,`short_description`,`description_html`,`image`,`unit`,`price`,`request_hint`,`active`,`featured`,`sort_order`,`seo_title`,`seo_description`,`source_file`,`specs_json`,`gallery_json`,`old_urls_json`) VALUES (491,15,'cable','ПвП2г 64/110','424-pvp2g-64-110','MNP-0491','ПвП2г -Силовые кабели с медными, с изоляцией из сшитого полиэтилена, с алюмополимерной лентой, в оболочке из полиэтилена высокой плотности. Для прокладки в земле (траншеях или бетонных лотках) независимо от степени коррозионной активности.','<div><p>ПвП2г 64/110 </p><p><strong>ПвП2г </strong>-Силовые кабели с медными, с изоляцией из сшитого полиэтилена, с алюмополимерной лентой, в оболочке из полиэтилена высокой плотности. Для прокладки в земле (траншеях или бетонных лотках) независимо от степени коррозионной активности грунтов, а так же в воде ( в несудоходных водоемах), если кабель защищен от механических повреждений, на трассах с неограниченной разностью уровней. </p><p><img alt="apvbbshpg" loading="lazy" src="assets/img/products/pvp2g__655ff4b753cee1af514691d2.jpg"/></p><p>1.Токопроводящая жила - медная многопроволочная , круглой формы, уплотненная, соответствует классу 2 по ГОСТ 22483-77. <br/>2.Экран по жиле- наложен экструзией из электропроводящей пероксидносшиваемой полиэтиленовой композиции. <br/>3.Изоляция - из пероксидносшиваемого полиэтилена. <br/>4.Экран по изоляции - наложен экструзией из электропроводящей пероксидносшиваемой полиэтиленовой композиции. <br/>5.Комбинированный экран: <br/>6.1 слой из электропроводящей водоблокирующей ленты, толщиной не менее 0,3 мм. <br/>7.2 повив из медных проволок 0,7-2,0 мм, поверх медных проволок спирально наложена медная лента толщиной не менее 0,1 мм. <br/>8. Разделительный слой из электропроводящей водоблокирующей ленты, поверх разделительного слоя наложена с перекрытием ламинированная алюмополимерная лента. <br/>9.Оболочка - из полиэтилена высокой плотности. </p><p><strong>Применение ПвП2г 64/110: </strong></p><p>Для передачи и распределения электрической энергии в трехфазных сетях на номинальное переменное напряжение 64/110кВ номинальной частотой 50 Гц для прокладки в земле (траншеях или бетонных лотках) независимо от степени коррозионной активности грунтов,в так же в воде (в несудоходных водоемах), если кабель защищен от механических повреждений, на трассах с неограниченной разностью уровней. </p><p>Технические характеристики ПвП2г 64/110: </p><p>- Вид климатического исполнения УХЛ, категории размещения 1 и 2 по ГОСТ 15150-69 <br/>-Электрическое сопротивление токопроводящей жилы постоянному току соответствует ГОСТ 22483-77 <br/>-Диапазон темперутур эксплуатации для марок кабелей ПвП2г от - 60 °С до + 50 °С <br/>- Прокладка и монтаж кабелей без предварительного подогрева производится при температуре, не ниже ...- 20 °С- для кабелей ПвП2г; <br/>-Минимальный радиус изгиба при прокладке не менее 15 наружных диаметров. <br/>- Номинальная частота .........50Гц <br/>-Длительно допустимая температура нагрева жилы кабеля - + 90°С <br/>-Предельно допустимая температура жилы кабеля при коротком замыкании - + 250°С <br/>-Предельно допустимая температура медного экрана кабеля при коротком замыкании - + 350°С <br/>-Температура нагрева жилы в режиме перегрузки не более +130°С <br/>-Дымообразование не должно приводить к снижению светопроницаемости в испытательной камере более чем на40% <br/>- Продолжительность работы кабеля в режиме перегрузки не более 100 ч. за год и не более 1000 ч. за срок службы <br/>- Строительная длина кабелей оговаривается при заказе <br/>-Срок службы не менее 30 лет при соблюдении условий транспортировки, хранения, монтажа,эксплуатации. <br/>- Гарантийный срок эксплуатации 5 лет. </p></div>','assets/img/products/pvp2g__655ff4b753cee1af514691d2.jpg','м',NULL,'Укажите марку, число и сечение жил, рабочее напряжение, длину и условия прокладки.',1,0,491,'ПвП2г 64/110 — купить по заявке | Монополия','ПвП2г 64/110: подбор и поставка в Санкт-Петербурге. Укажите марку, число и сечение жил, рабочее напряжение, длину и условия прокладки. Расчет стоимости — по заявке.','site/www.monopoly-torg.ru/424-pvp2g-64-110__0803bf4cbbf278d65993712a.html','[]','["assets/img/products/pvp2g__655ff4b753cee1af514691d2.jpg"]','["http://www.monopoly-torg.ru/index.php/kabelnaya-produkciya/kabeli-silovye-s-izolyatsiej-iz-sshitogo-polietilena/424-pvp2g-64-110"]') ON DUPLICATE KEY UPDATE `category_id`=VALUES(`category_id`),`root_category`=VALUES(`root_category`),`name`=VALUES(`name`),`slug`=VALUES(`slug`),`sku`=VALUES(`sku`),`short_description`=VALUES(`short_description`),`description_html`=VALUES(`description_html`),`image`=VALUES(`image`),`unit`=VALUES(`unit`),`price`=VALUES(`price`),`request_hint`=VALUES(`request_hint`),`active`=VALUES(`active`),`featured`=VALUES(`featured`),`sort_order`=VALUES(`sort_order`),`seo_title`=VALUES(`seo_title`),`seo_description`=VALUES(`seo_description`),`source_file`=VALUES(`source_file`),`specs_json`=VALUES(`specs_json`),`gallery_json`=VALUES(`gallery_json`),`old_urls_json`=VALUES(`old_urls_json`);
INSERT INTO `products` (`id`,`category_id`,`root_category`,`name`,`slug`,`sku`,`short_description`,`description_html`,`image`,`unit`,`price`,`request_hint`,`active`,`featured`,`sort_order`,`seo_title`,`seo_description`,`source_file`,`specs_json`,`gallery_json`,`old_urls_json`) VALUES (492,15,'cable','ПвП2г-10','425-pvp2g-10','MNP-0492','Кабели применяются для стационарной прокладки в кабельных сооружениях и производственных помещениях.','<div><p>ПвП2г-10 </p><p><img alt="apvbbshv" loading="lazy" src="assets/img/products/pvp2g-10__ca956f44dfcd1dcb37d03f5b.jpg"/></p><ol><li>Круглая многопроволочная уплотненная токопроводящая жила из меди, сечение – 50–1000 кв. мм; </li><li>Экран по жиле из экструдируемого электропроводящего сшитого полиэтилена; </li><li>Изоляция из сшитого полиэтилена (Пв); </li><li>Экран по изоляции из экструдируемого электропроводящего сшитого полиэтилена; </li><li>Разделительный слой из электропроводящей водоблокирующей ленты; </li><li>Экран из медных проволок, скрепленных медной лентой: <br/>- сечением не менее 16 кв. мм для кабелей с сечением жилы 35–120 кв. мм, <br/>- сечением не менее 25 кв. мм для кабелей с сечением жилы 150–300 кв. мм, <br/>- сечением не менее 35 кв. мм для кабелей с сечением жилы выше 300 кв. мм, <br/><strong><em>Примечание: </em></strong>сечение экрана выбирается в зависимости от токов короткого замыкания, <br/>которые необходимо рассчитать согласно условиям прокладки кабельной линии. <br/>Возможно изготовление кабеля с увеличенным сечением экрана. </li><li>Разделительный слой из двух лент крепированной бумаги или прорезиненной ткани; </li><li>Разделительный слой из алюмополимерной ленты; </li><li>Оболочка из полиэтилена (П). </li></ol><p><strong><br/>Область применения ПвП2г-10: </strong></p><p>Кабели применяются для стационарной прокладки в кабельных сооружениях и производственных помещениях. </p><p>Герметизированы от проникновения влаги, что позволяет эксплуатировать эти кабели в грунтах с повышенной влажностью и сырых, частично затапливаемых сооружениях, а также по согласованию с предприятием-изготовителем в судоходных и несудоходных водоемах – при соблюдении мер, исключающих механическое повреждение кабеля. </p><p><strong>Технические характеристики ПвП2г-10 </strong></p><table><tbody><tr><td>Гарантийный срок эксплуатации [год] </td><td><strong>5 </strong></td></tr><tr><td>Допустимый нагрев жил при работе в аварийном режиме [°С] </td><td><strong>+130 </strong></td></tr><tr><td>Максимальная температура жил при коротком замыкании, [°С] </td><td><strong>+250 </strong></td></tr><tr><td>Монтаж без предварительного подогрева при температуре не ниже, [°С] </td><td><strong>-20 </strong></td></tr><tr><td>Номинальное переменное напряжение частотой 50 Гц [кВ] </td><td><strong>10 </strong></td></tr><tr><td>Рабочая температура жилы [°С] </td><td><strong>+90 </strong></td></tr><tr><td>Радиус изгиба кабелей [наружных диаметров] </td><td><strong>15(7,5) </strong></td></tr><tr><td>Срок службы кабелей не менее, (год) </td><td><strong>30 </strong></td></tr><tr><td>Эксплуатация при температуре окружающей среды, [°С] </td><td><strong>-60/+50 </strong></td></tr></tbody></table><table><tbody><tr><td><strong>Сечение, кв, мм </strong></td><td><strong>Наружный диаметр <br/>кабеля, мм </strong></td><td><strong>Масса 1 км одножильного <br/>кабеля, кг </strong></td></tr><tr><td>ПвП2г-10 1x50/16 </td><td>26,0 </td><td>959 </td></tr><tr><td>ПвП2г-10 1x70/16 </td><td>27,6 </td><td>1173 </td></tr><tr><td>ПвП2г-10 1x95/16 </td><td>29,2 </td><td>1431 </td></tr><tr><td>ПвП2г-10 1x120/16 </td><td>30,6 </td><td>1685 </td></tr><tr><td>ПвП2г-10 1x150/25 </td><td>32,1 </td><td>2068 </td></tr><tr><td>ПвП2г-10 1x185/25 </td><td>33,7 </td><td>2416 </td></tr><tr><td>ПвП2г-10 1x240/25 </td><td>35,9 </td><td>2955 </td></tr><tr><td>ПвП2г-10 1x300/25 </td><td>38,1 </td><td>3539 </td></tr><tr><td>ПвП2г-10 1x400/35 </td><td>41,1 </td><td>4586 </td></tr><tr><td>ПвП2г-10 1x500/35 </td><td>44,1 </td><td>5544 </td></tr><tr><td>ПвП2г-10 1x630/35 </td><td>47,7 </td><td>6804 </td></tr><tr><td>ПвП2г-10 1x800/35 </td><td>51,5 </td><td>8411 </td></tr></tbody></table></div>','assets/img/products/pvp2g-10__ca956f44dfcd1dcb37d03f5b.jpg','м',NULL,'Укажите марку, число и сечение жил, рабочее напряжение, длину и условия прокладки.',1,0,492,'ПвП2г-10 — купить по заявке | Монополия','ПвП2г-10: подбор и поставка в Санкт-Петербурге. Укажите марку, число и сечение жил, рабочее напряжение, длину и условия прокладки. Расчет стоимости — по заявке.','site/www.monopoly-torg.ru/425-pvp2g-10__a0a8d3beeb509e08863476d5.html','[["Гарантийный срок эксплуатации [год]", "5"], ["Допустимый нагрев жил при работе в аварийном режиме [°С]", "+130"], ["Максимальная температура жил при коротком замыкании, [°С]", "+250"], ["Монтаж без предварительного подогрева при температуре не ниже, [°С]", "-20"], ["Номинальное переменное напряжение частотой 50 Гц [кВ]", "10"], ["Рабочая температура жилы [°С]", "+90"], ["Радиус изгиба кабелей [наружных диаметров]", "15(7,5)"], ["Срок службы кабелей не менее, (год)", "30"], ["Эксплуатация при температуре окружающей среды, [°С]", "-60/+50"]]','["assets/img/products/pvp2g-10__ca956f44dfcd1dcb37d03f5b.jpg"]','["http://www.monopoly-torg.ru/index.php/kabelnaya-produkciya/kabeli-silovye-s-izolyatsiej-iz-sshitogo-polietilena/425-pvp2g-10"]') ON DUPLICATE KEY UPDATE `category_id`=VALUES(`category_id`),`root_category`=VALUES(`root_category`),`name`=VALUES(`name`),`slug`=VALUES(`slug`),`sku`=VALUES(`sku`),`short_description`=VALUES(`short_description`),`description_html`=VALUES(`description_html`),`image`=VALUES(`image`),`unit`=VALUES(`unit`),`price`=VALUES(`price`),`request_hint`=VALUES(`request_hint`),`active`=VALUES(`active`),`featured`=VALUES(`featured`),`sort_order`=VALUES(`sort_order`),`seo_title`=VALUES(`seo_title`),`seo_description`=VALUES(`seo_description`),`source_file`=VALUES(`source_file`),`specs_json`=VALUES(`specs_json`),`gallery_json`=VALUES(`gallery_json`),`old_urls_json`=VALUES(`old_urls_json`);
INSERT INTO `products` (`id`,`category_id`,`root_category`,`name`,`slug`,`sku`,`short_description`,`description_html`,`image`,`unit`,`price`,`request_hint`,`active`,`featured`,`sort_order`,`seo_title`,`seo_description`,`source_file`,`specs_json`,`gallery_json`,`old_urls_json`) VALUES (493,15,'cable','ПвП2г-10 (трехжильный)','426-pvp2g-10-trekhzhilnyj','MNP-0493','Кабели применяются для стационарной прокладки в кабельных сооружениях и производственных помещениях.','<div><p>ПвП2г-10 (трехжильный) </p><p><img alt="apvbbshpz" loading="lazy" src="assets/img/products/pvp2g-10-3__56685b410fe213b6494069a3.jpg"/></p><ol><li>Центральное заполнение из жгута; </li><li>Круглая многопроволочная уплотненная токопроводящая жила из меди, <br/>сечение: круглая жила – 50–240 кв. мм, секторная жила – 120–240 кв. мм; </li><li>Экран по жиле из экструдируемого электропроводящего сшитого полиэтилена; </li><li>Изоляция из сшитого полиэтилена (Пв); </li><li>Экран по изоляции из экструдируемого электропроводящего сшитого полиэтилена; </li><li>Разделительный слой из ленты электропроводящей водоблокирующей ленты; </li><li>Экран из медных проволок, скрепленных медной лентой: <br/>- сечением не менее 16 кв. мм для кабелей с сечением жилы 35–120 кв. мм, <br/>- сечением не менее 25 кв. мм для кабелей с сечением жилы 150–300 кв. мм, <br/>- сечением не менее 35 кв. мм для кабелей с сечением жилы выше 300 кв. мм, <br/><em><strong>Примечание: </strong></em>сечение экрана выбирается в зависимости от токов короткого замыкания, которые необходимо рассчитать согласно условиям прокладки кабельной линии. Возможно изготовление кабеля с увеличенным сечением экрана. </li><li>Межфазное заполнение из мелонаполненной невулканизированной резиновой смеси; </li><li>Разделительный слой из алюмополимерной ленты; </li><li>Оболочка из полиэтилена (П). </li></ol><p><strong></strong><br/><strong>Область применения ПвП2г-10: </strong></p><p>Кабели применяются для стационарной прокладки в кабельных сооружениях и производственных помещениях. </p><p><strong>Технические характеристики ПвП2г-10 </strong></p><table><tbody><tr><td>Гарантийный срок эксплуатации [год] </td><td><strong>5 </strong></td></tr><tr><td>Допустимый нагрев жил при работе в аварийном режиме [°С] </td><td><strong>+130 </strong></td></tr><tr><td>Максимальная температура жил при коротком замыкании, [°С] </td><td><strong>+250 </strong></td></tr><tr><td>Монтаж без предварительного подогрева при температуре не ниже, [°С] </td><td><strong>-20 </strong></td></tr><tr><td>Номинальное переменное напряжение частотой 50 Гц [кВ] </td><td><strong>10 </strong></td></tr><tr><td>Рабочая температура жилы [°С] </td><td><strong>+90 </strong></td></tr><tr><td>Радиус изгиба кабелей [наружных диаметров] </td><td><strong>15(7,5) </strong></td></tr><tr><td>Срок службы кабелей не менее, (год) </td><td><strong>30 </strong></td></tr><tr><td>Эксплуатация при температуре окружающей среды, [°С] </td><td><strong>-60/+50 </strong></td></tr></tbody></table><table><tbody><tr><td><strong>Сечение, кв. мм </strong></td><td><strong>Наружный диаметр <br/>кабеля, мм </strong></td><td><strong>Масса 1 км одножильного <br/>кабеля, кг </strong></td></tr><tr><td>ПвП2г-10 3х50/16 </td><td>51,7 </td><td>3959 </td></tr><tr><td>ПвП2г-10 3х70/16 </td><td>55,5 </td><td>4855 </td></tr><tr><td>ПвП2г-10 3х95/16 </td><td>59,0 </td><td>5872 </td></tr><tr><td>ПвП2г-10 3х120/16 </td><td>62,0 </td><td>6836 </td></tr><tr><td>ПвП2г-10 3х150/25 </td><td>65,2 </td><td>7997 </td></tr><tr><td>ПвП2г-10 3х185/25 </td><td>68,7 </td><td>9319 </td></tr><tr><td>ПвП2г-10 3х240/25 </td><td>73,4 </td><td>11343 </td></tr></tbody></table><p><strong><br/>Токовая нагрузка ПвП2г-10 <br/></strong></p><table><tbody><tr><td><strong>Номинальное сечение жилы, кв. мм </strong></td><td><strong>Ток при прокладке в земле, А </strong></td></tr><tr><td>50 </td><td>207 </td></tr><tr><td>70 </td><td>253 </td></tr><tr><td>95 </td><td>300 </td></tr><tr><td>120 </td><td>340 </td></tr><tr><td>150 </td><td>384 </td></tr><tr><td>185 </td><td>433 </td></tr><tr><td>240 </td><td>500 </td></tr></tbody></table></div>','assets/img/products/pvp2g-10-3__56685b410fe213b6494069a3.jpg','м',NULL,'Укажите марку, число и сечение жил, рабочее напряжение, длину и условия прокладки.',1,0,493,'ПвП2г-10 (трехжильный) — купить по заявке | Монополия','ПвП2г-10 (трехжильный): подбор и поставка в Санкт-Петербурге. Укажите марку, число и сечение жил, рабочее напряжение, длину и условия прокладки. Расчет стоимости — по заявке.','site/www.monopoly-torg.ru/426-pvp2g-10-trekhzhilnyj__daaeb146ba82869949078cf4.html','[["Гарантийный срок эксплуатации [год]", "5"], ["Допустимый нагрев жил при работе в аварийном режиме [°С]", "+130"], ["Максимальная температура жил при коротком замыкании, [°С]", "+250"], ["Монтаж без предварительного подогрева при температуре не ниже, [°С]", "-20"], ["Номинальное переменное напряжение частотой 50 Гц [кВ]", "10"], ["Рабочая температура жилы [°С]", "+90"], ["Радиус изгиба кабелей [наружных диаметров]", "15(7,5)"], ["Срок службы кабелей не менее, (год)", "30"], ["Эксплуатация при температуре окружающей среды, [°С]", "-60/+50"], ["Номинальное сечение жилы, кв. мм", "Ток при прокладке в земле, А"], ["50", "207"], ["70", "253"], ["95", "300"], ["120", "340"], ["150", "384"], ["185", "433"], ["240", "500"]]','["assets/img/products/pvp2g-10-3__56685b410fe213b6494069a3.jpg"]','["http://www.monopoly-torg.ru/index.php/kabelnaya-produkciya/kabeli-silovye-s-izolyatsiej-iz-sshitogo-polietilena/426-pvp2g-10-trekhzhilnyj"]') ON DUPLICATE KEY UPDATE `category_id`=VALUES(`category_id`),`root_category`=VALUES(`root_category`),`name`=VALUES(`name`),`slug`=VALUES(`slug`),`sku`=VALUES(`sku`),`short_description`=VALUES(`short_description`),`description_html`=VALUES(`description_html`),`image`=VALUES(`image`),`unit`=VALUES(`unit`),`price`=VALUES(`price`),`request_hint`=VALUES(`request_hint`),`active`=VALUES(`active`),`featured`=VALUES(`featured`),`sort_order`=VALUES(`sort_order`),`seo_title`=VALUES(`s