INSERT INTO `products` (`id`,`category_id`,`root_category`,`name`,`slug`,`sku`,`short_description`,`description_html`,`image`,`unit`,`price`,`request_hint`,`active`,`featured`,`sort_order`,`seo_title`,`seo_description`,`source_file`,`specs_json`,`gallery_json`,`old_urls_json`) VALUES (502,15,'cable','ПвПГнг-HF- 1','435-pvpgng-hf-1','MNP-0502','Бронированные кабели применяются для прокладки в помещениях и кабельных сооружениях при наличии опасности механических повреждений при эксплуатации. Технические характеристики ПвПГнг-HF- 1','<div><p>ПвПГнг-HF- 1 </p><p><img alt="apvbbshpg" loading="lazy" src="assets/img/products/pvpgng__c3854602dfbf93e9a3770c8e.jpg"/></p><div><strong>Область применения ПвПГнг-HF- 1 </strong></div><div>Силовые и контрольные кабели, не распространяющие горение, с изоляцией и оболочкой из полимерных композиций, не содержащих галогенов. Предназначены для передачи и распределения электроэнергии в стационарных установках при номинальном переменном напряжении 0,66 и 1 кВ частотой до 100 Гц. </div><div>Кабели <strong>ПвПГнг-HF- </strong>изготовляются для общепромышленного применения и применения в системах АС класса 3Н по классификации ПНАЭ Г-1-011-97. </div><div>Климатическое исполнение В, категории размещения 3, 4 по ГОСТ 15150-69. </div><div>Применяются для прокладки в помещениях и кабельных сооружениях при отсутствии опасности механических повреждений при эксплуатации. </div><p>Бронированные кабели применяются для прокладки в помещениях и кабельных сооружениях при наличии опасности механических повреждений при эксплуатации. <br/><strong>Технические характеристики ПвПГнг-HF- 1 </strong><br/><br/></p><table><tbody><tr><td>Влажность воздуха при 35° C [%] </td><td><strong>98 </strong></td></tr><tr><td>Испытательное переменное напряжение частотой 50 Гц, 10 мин. [кВ] </td><td><strong>3,5 </strong></td></tr><tr><td>Максимальная рабочая температура жилы [°С] </td><td><strong>+70 </strong></td></tr><tr><td>Максимальное переменное напряжение частоты 50 Гц [кВ] </td><td><strong>1,2 </strong></td></tr><tr><td>Монтаж при температуре, не ниже [°C] </td><td><strong>-15 </strong></td></tr><tr><td>Номинальное переменное напряжение частотой 50 Гц [кВ] </td><td><strong>1 </strong></td></tr><tr><td>Радиус изгиба многожильных кабелей, не менее [наружных диаметров] </td><td><strong>7,5 </strong></td></tr><tr><td>Радиус изгиба одножильных кабелей, не менее [наружных диаметров] </td><td><strong>10 </strong></td></tr><tr><td>Сопротивление изоляции при температуре +70° С, не менее [МОм х км] </td><td><strong>0,005 </strong></td></tr><tr><td>Температура окружающей среды, верхний предел [°C] </td><td><strong>+50 </strong></td></tr><tr><td>Температура окружающей среды, нижний предел [°C] </td><td><strong>-30 </strong></td></tr><tr><td>Температура токопроводящих жил при коротком замыкании [°С] </td><td><strong>250 </strong></td></tr></tbody></table><table><tbody><tr><td><strong>Количество и сечение жил, </strong></td><td><strong>Расчётная масса <br/>кабеля, кг/км </strong></td><td><strong>Расчётный наружный <br/>диаметр, мм </strong></td></tr><tr><td>шт. х кв. мм </td><td></td><td></td></tr><tr><td>ПвПГнг-HF- 1 1х1,5 </td><td>115 </td><td>8,8 </td></tr><tr><td>ПвПГнг-HF- 1 1х2,5 </td><td>133 </td><td>9,2 </td></tr><tr><td>ПвПГнг-HF- 1 1х4,0 </td><td>155 </td><td>9,7 </td></tr><tr><td>ПвПГнг-HF- 1 1х6,0 </td><td>182 </td><td>10,2 </td></tr><tr><td>ПвПГнг-HF- 1 1х10 </td><td>235 </td><td>11,0 </td></tr><tr><td>ПвПГнг-HF- 1 1х16 </td><td>308 </td><td>12,0 </td></tr><tr><td>ПвПГнг-HF- 1 1х25 </td><td>420 </td><td>13,5 </td></tr><tr><td>ПвПГнг-HF- 1 1х35 </td><td>526 </td><td>14,5 </td></tr><tr><td>ПвПГнг-HF- 1 1х50 </td><td>689 </td><td>15,5 </td></tr><tr><td>ПвПГнг-HF- 1 1х70 </td><td>898 </td><td>16,9 </td></tr><tr><td>ПвПГнг-HF- 1 1х95 </td><td>1161 </td><td>18,5 </td></tr><tr><td>ПвПГнг-HF- 1 1х120 </td><td>1413 </td><td>19,8 </td></tr><tr><td>ПвПГнг-HF- 1 1х150 </td><td>1729 </td><td>21,5 </td></tr><tr><td>ПвПГнг-HF- 1 1х185 </td><td>20