INSERT INTO `products` (`id`,`category_id`,`root_category`,`name`,`slug`,`sku`,`short_description`,`description_html`,`image`,`unit`,`price`,`request_hint`,`active`,`featured`,`sort_order`,`seo_title`,`seo_description`,`source_file`,`specs_json`,`gallery_json`,`old_urls_json`) VALUES (518,15,'cable','ПвПу2г-35 (трехжильный)','451-pvpu2g-35-trekhzhilnyj','MNP-0518','Кабели применяются для стационарной прокладки в кабельных сооружениях и производственных помещениях.','<div><p>ПвПу2г-35 (трехжильный) </p><p><img alt="apvbbshp" loading="lazy" src="assets/img/products/pvpug-6-3__1e2aba95877b9fa870550036.jpg"/></p><ol><li>Центральное заполнение из жгута; </li><li>Круглая многопроволочная уплотненная токопроводящая жила из меди, <br/>сечение: круглая жила – 50–240 кв. мм,секторная жила – 120–240 кв. мм; </li><li>Экран по жиле из экструдируемого электропроводящего сшитого полиэтилена; </li><li>Изоляция из сшитого полиэтилена (Пв); </li><li>Экран по изоляции из экструдируемого электропроводящего сшитого полиэтилена; </li><li>Разделительный слой из электропроводящей водоблокирующей ленты; </li><li>Экран из медных проволок, скрепленных медной лентой: <br/>- сечением не менее 16 кв. мм для кабелей с сечением жилы 35–120 кв. мм, <br/>- сечением не менее 25 кв. мм для кабелей с сечением жилы 150–300 кв. мм, <br/>- сечением не менее 35 кв. мм для кабелей с сечением жилы выше 300 кв. мм, <br/><em><strong>Примечание: </strong></em>сечение экрана выбирается в зависимости от токов короткого замыкания, которые необходимо рассчитать согласно условиям прокладки кабельной линии. Возможно изготовление кабеля с увеличенным сечением экрана. </li><li>Межфазное заполнение из мелонаполненной невулканизированной резиновой смеси; </li><li>Разделительный слой из алюмополимерной ленты; </li><li>Оболочка из полиэтилена увеличенной толщины (Пу). </li></ol><p><strong>Область применения ПвПу2г-35: </strong></p><p>Кабели применяются для стационарной прокладки в кабельных сооружениях и производственных помещениях. </p><p><strong>Технические характеристики ПвПу2г-35 </strong></p><table><tbody><tr><td>Гарантийный срок эксплуатации [год] </td><td><strong>5 </strong></td></tr><tr><td>Допустимый нагрев жил при работе в аварийном режиме [°С] </td><td><strong>+130 </strong></td></tr><tr><td>Максимальная температура жил при коротком замыкании, [°С] </td><td><strong>+250 </strong></td></tr><tr><td>Монтаж без предварительного подогрева при температуре не ниже, [°С] </td><td><strong>-20 </strong></td></tr><tr><td>Номинальное переменное напряжение частотой 50 Гц [кВ] </td><td><strong>35 </strong></td></tr><tr><td>Рабочая температура жилы [°С] </td><td><strong>+90 </strong></td></tr><tr><td>Радиус изгиба кабелей [наружных диаметров] </td><td><strong>15(7,5) </strong></td></tr><tr><td>Срок службы кабелей не менее, (год) </td><td><strong>30 </strong></td></tr><tr><td>Эксплуатация при температуре окружающей среды, [°С] </td><td><strong>-60/+50 </strong></td></tr></tbody></table><table><tbody><tr><td><strong>Сечение, кв. мм </strong></td><td><strong>Наружный диаметр <br/>кабеля, мм </strong></td><td><strong>Масса 1 км одножильного <br/>кабеля, кг </strong></td><td></td></tr><tr><td>ПвПу2г-35 3х50/16 </td><td>75 </td><td>6918 </td><td></td></tr><tr><td>ПвПу2г-35 3х70/16 </td><td>78.5 </td><td>7932 </td><td></td></tr><tr><td>ПвПу2г-35 3х95/16 </td><td>81.9 </td><td>9101 </td><td></td></tr><tr><td>ПвПу2г-35 3х120/16 </td><td>84.9 </td><td>10217 </td><td></td></tr><tr><td>ПвПу2г-35 3х150/25 </td><td>88.1 </td><td>11502 </td></tr></tbody></table></div>','assets/img/products/pvpug-6-3__1e2aba95877b9fa870550036.jpg','м',NULL,'Укажите марку, число и сечение жил, рабочее напряжение, длину и условия прокладки.',1,0,518,'ПвПу2г-35 (трехжильный) — купить по заявке | Монополия','ПвПу2г-35 (трехжильный): подбор и поставка в Санкт-Петербурге. Укажите марку, число и сечение жил, рабочее напряжение, длину и условия прокладки. Расчет стоимости — по заявке.','site/www.monopoly-torg.ru/451-pvpu2g-35-trekhzhilnyj__955d30f1f7ae7fcc9b500aa8.html','[["Гарантийный срок эксплуатации [год]", "5"], ["Допустимый нагрев жил при работе в аварийном режиме [°С]", "+130"], ["Максимальная температура жил при коротком замыкании, [°С]", "+250"], ["Монтаж без предварительного подогрева при температуре не ниже, [°С]", "-20"], ["Номинальное переменное напряжение частотой 50 Гц [кВ]", "35"], ["Рабочая температура жилы [°С]", "+90"], ["Радиус изгиба кабелей [наружных диаметров]", "15(7,5)"], ["Срок службы кабелей не менее, (год)", "30"], ["Эксплуатация при температуре окружающей среды, [°С]", "-60/+50"]]','["assets/img/products/pvpug-6-3__1e2aba95877b9fa870550036.jpg"]','["http://www.monopoly-torg.ru/index.php/kabelnaya-produkciya/kabeli-silovye-s-izolyatsiej-iz-sshitogo-polietilena/451-pvpu2g-35-trekhzhilnyj"]') ON DUPLICATE KEY UPDATE `category_id`=VALUES(`category_id`),`root_category`=VALUES(`root_category`),`name`=VALUES(`name`),`slug`=VALUES(`slug`),`sku`=VALUES(`sku`),`short_description`=VALUES(`short_description`),`description_html`=VALUES(`description_html`),`image`=VALUES(`image`),`unit`=VALUES(`unit`),`price`=VALUES(`price`),`request_hint`=VALUES(`request_hint`),`active`=VALUES(`active`),`featured`=VALUES(`featured`),`sort_order`=VALUES(`sort_order`),`seo_title`=VALUES(`seo_title`),`seo_description`=VALUES(`seo_description`),`source_file`=VALUES(`source_file`),`specs_json`=VALUES(`specs_json`),`gallery_json`=VALUES(`gallery_json`),`old_urls_json`=VALUES(`old_urls_json`);
