ilnyj__22c89eb1614badbc5fc935cb.html','[["Гарантийный срок эксплуатации [год]", "5"], ["Допустимый нагрев жил при работе в аварийном режиме [°С]", "+130"], ["Максимальная температура жил при коротком замыкании, [°С]", "+250"], ["Монтаж без предварительного подогрева при температуре не ниже, [°С]", "-20"], ["Номинальное переменное напряжение частотой 50 Гц [кВ]", "35"], ["Рабочая температура жилы [°С]", "+90"], ["Радиус изгиба кабелей [наружных диаметров]", "15(7,5)"], ["Срок службы кабелей не менее, (год)", "30"], ["Эксплуатация при температуре окружающей среды, [°С]", "-60/+50"]]','["assets/img/products/pvpug-6-3__1e2aba95877b9fa870550036.jpg"]','["http://www.monopoly-torg.ru/index.php/kabelnaya-produkciya/kabeli-silovye-s-izolyatsiej-iz-sshitogo-polietilena/455-pvpug-35-kv-trekhzhilnyj"]') ON DUPLICATE KEY UPDATE `category_id`=VALUES(`category_id`),`root_category`=VALUES(`root_category`),`name`=VALUES(`name`),`slug`=VALUES(`slug`),`sku`=VALUES(`sku`),`short_description`=VALUES(`short_description`),`description_html`=VALUES(`description_html`),`image`=VALUES(`image`),`unit`=VALUES(`unit`),`price`=VALUES(`price`),`request_hint`=VALUES(`request_hint`),`active`=VALUES(`active`),`featured`=VALUES(`featured`),`sort_order`=VALUES(`sort_order`),`seo_title`=VALUES(`seo_title`),`seo_description`=VALUES(`seo_description`),`source_file`=VALUES(`source_file`),`specs_json`=VALUES(`specs_json`),`gallery_json`=VALUES(`gallery_json`),`old_urls_json`=VALUES(`old_urls_json`);
