INSERT INTO `products` (`id`,`category_id`,`root_category`,`name`,`slug`,`sku`,`short_description`,`description_html`,`image`,`unit`,`price`,`request_hint`,`active`,`featured`,`sort_order`,`seo_title`,`seo_description`,`source_file`,`specs_json`,`gallery_json`,`old_urls_json`) VALUES (528,15,'cable','ППГЭнг-FRHF-1','461-ppgeng-frhf-1','MNP-0528','1. Токопроводящая жила, скрученная из медных проволок (класс 1, 2); 2. Термический барьер поверх медной жилы из слюдосодержащей ленты; 3. Изоляция из полимерных композиций, не содержащих галогенов; 4. Скрепляющая лента; 5. Внутренняя оболочка; 6..','<div><p>ППГЭнг-FRHF-1 </p><p><img alt="apvbbshngals" loading="lazy" src="assets/img/products/ppgngehf__bfde2b0d7f940128d976de80.jpg"/></p><p>1. Токопроводящая жила, скрученная из медных проволок (класс 1, 2); <br/>2. Термический барьер поверх медной жилы из слюдосодержащей ленты; <br/>3. Изоляция из полимерных композиций, не содержащих галогенов; <br/>4. Скрепляющая лента; <br/>5. Внутренняя оболочка; <br/>6. Обмотка лентой из негорючего материала; <br/>7. Общий экран из медной ленты или фольги; <br/>8. Оболочка из полимерных композиций, не содержащих галогенов. </p><div><strong>Область применения ППГЭнг-FRHF-1: </strong></div><div>Кабели огнестойкие силовые и контрольные, не распространяющие горение, с изоляцией и оболочкой из полимерных композиций, не содержащих галогенов. Предназначены для передачи и распределения электроэнергии в стационарных установках при номинальном переменном напряжении 0,66 и 1 кВ частотой до 100 Гц. </div><div>Кабели изготовляются для общепромышленного применения и применения на атомных станциях (АС) в системах АС класса 2 по классификации ОПБ 88/97 (ПНАЭ Г-01-011). </div><div>Климатическое исполнение В, категория размещения 5 по ГОСТ 15150-69. </div><p>Преимущественно применяются для прокладки в помещениях и кабельных сооружениях при отсутствии опасности механических повреждений при эксплуатации. <br/><strong>Технические характеристики ППГЭнг-FRHF-1 </strong><br/><br/></p><table><tbody><tr><td>Влажность воздуха при 35° C [%] </td><td><strong>98 </strong></td></tr><tr><td>Испытательное переменное напряжение частотой 50 Гц, 10 мин. [кВ] </td><td><strong>3,5 </strong></td></tr><tr><td>Максимальная рабочая температура жилы [°С] </td><td><strong>90 </strong></td></tr><tr><td>Максимальное переменное напряжение частоты 50 Гц [кВ] </td><td><strong>1,2 </strong></td></tr><tr><td>Монтаж при температуре, не ниже [°C] </td><td><strong>-15 </strong></td></tr><tr><td>Номинальное переменное напряжение частотой 50 Гц [кВ] </td><td><strong>1 </strong></td></tr><tr><td>Радиус изгиба кабелей [наружных диаметров] </td><td><strong>10 </strong></td></tr><tr><td>Радиус изгиба многожильных кабелей, не менее [наружных диаметров] </td><td><strong>7,5 </strong></td></tr><tr><td>Сопротивление изоляции при температуре +70° С, не менее [МОм х км] </td><td><strong>0,005 </strong></td></tr><tr><td>Температура окружающей среды, верхний предел [°C] </td><td><strong>+50 </strong></td></tr><tr><td>Температура окружающей среды, нижний предел [°C] </td><td><strong>-50 </strong></td></tr><tr><td>Температура токопроводящих жил при коротком замыкании [°С] </td><td><strong>250 </strong></td></tr></tbody></table></div>','assets/img/products/ppgngehf__bfde2b0d7f940128d976de80.jpg','м',NULL,'Укажите марку, число и сечение жил, рабочее напряжение, длину и условия прокладки.',1,0,528,'ППГЭнг-FRHF-1 — купить по заявке | Монополия','ППГЭнг-FRHF-1: подбор и поставка в Санкт-Петербурге. Укажите марку, число и сечение жил, рабочее напряжение, длину и условия прокладки. Расчет стоимости — по заявке.','site/www.monopoly-torg.ru/461-ppgeng-frhf-1__f2256fb7915db999b66bb1fe.html','[["Влажность воздуха при 35° C [%]", "98"], ["Испытательное переменное напряжение частотой 50 Гц, 10 мин. [кВ]", "3,5"], ["Максимальная рабочая температура жилы [°С]", "90"], ["Максимальное переменное напряжение частоты 50 Гц [кВ]", "1,2"], ["Монтаж при температуре, не ниже [°C]", "-15"], ["Номинальное переменное напряжение частотой 50 Гц [кВ]", "1"], ["Радиус изгиба кабелей [наружных диаметров]", "10"], ["Радиус изгиба многожильных кабелей, не менее [наружных диаметров]", "7,5"], ["Сопротивление изоляции при температуре +70° С, не менее [МОм х км]", "0,005"], ["Температура окружающей среды, верхний предел [°C]", "+50"], ["Температура окружающей среды, нижний предел [°C]", "-50"], ["Температура токопроводящих жил при коротком замыкании [°С]", "250"]]','["assets/img/products/ppgngehf__bfde2b0d7f940128d976de80.jpg"]','["http://www.monopoly-torg.ru/index.php/kabelnaya-produkciya/kabeli-silovye-s-izolyatsiej-iz-sshitogo-polietilena/461-ppgeng-frhf-1"]') ON DUPLICATE KEY UPDATE `category_id`=VALUES(`category_id`),`root_category`=VALUES(`root_category`),`name`=VALUES(`name`),`slug`=VALUES(`slug`),`sku`=VALUES(`sku`),`short_description`=VALUES(`short_description`),`description_html`=VALUES(`description_html`),`image`=VALUES(`image`),`unit`=VALUES(`unit`),`price`=VALUES(`price`),`request_hint`=VALUES(`request_hint`),`active`=VALUES(`active`),`featured`=VALUES(`featured`),`sort_order`=VALUES(`sort_order`),`seo_title`=VALUES(`seo_title`),`seo_description`=VALUES(`seo_description`),`source_file`=VALUES(`source_file`),`specs_json`=VALUES(`specs_json`),`gallery_json`=VALUES(`gallery_json`),`old_urls_json`=VALUES(`old_urls_json`);
INSERT INTO `products` (`id`,`category_id`,`root_category`,`name`,`slug`,`sku`,`short_description`,`description_html`,`image`,`unit`,`price`,`request_hint`,`active`,`featured`,`sort_order`,`seo_title`,`seo_description`,`source_file`,`specs_json`,`gallery_json`,`old_urls_json`) VALUES (529,16,'cable','ВБШВнг(А)-LSLTx','100-vbshvng-a-lsltx','MNP-0529','Кабели силовые, не распространяющие горение, с низким дымо- и газовыделением и с низкой токсичностью продуктов горения.','<div><p>ВБШВнг(А)-LSLTx </p><p>Кабели силовые, не распространяющие горение, с низким дымо- и газовыделением и с низкой токсичностью продуктов горения. </p><p><strong>В БШ В нг (А) </strong><strong>- </strong><strong>LSLTx </strong>- кабели сило в ые , с медными жилами , не распространяющий горение , с низким дымо - и газо в ыделением , низкой токсичностью продукто в горения , с изоляцией из ПВХ пластиката пониженной пожарной опасности, с броней из стальных оцинкованных лент, с защитным шлангом из ПВХ пластиката пониженной пожарной опасности . </p><p><img alt="vbshvngfrlstx" loading="lazy" src="assets/img/products/vbshvngfrlstx__2d41ae610c9d4809fe607e58.jpg"/></p><ol><li>Токопроводящая жила – медная , однопроволочная или многопроволочная, круглой или секторной формы, 1 или 2 класса по ГОСТ 22483-77. </li><li>Изоляция – из ПВХ пластиката пониженной пожарной опасности, изолированные жилы имеют отличительную расцветку. См. общ. тех. хар-ки. </li><li>Скрутка – изолированные жилы многожильных кабелей скручены. </li><li>Внутренняя оболочка – из ПВХ пластиката пониженной пожарной опасности с заполнением между жилами . </li><li>Броня – из двух стальных оцинкованных лент. </li><li>Защитный шланг – поверх брони из ПВХ пластиката пониженной пожарной опасности. </li></ol><p>Номинальное переменное напряжение сило вых кабелей, число и номинальное сечение жил соответствуют указанным в таблице: </p><table><tbody><tr><td rowspan="3"><strong>Обозначение марки кабеля </strong></td><td rowspan="3"><strong>Число жил </strong></td><td colspan="2"><strong>Номинальное сечение основных жил, мм <sup>2 </sup></strong></td></tr><tr><td colspan="2"><strong>Номинальное напряжение, кВ </strong></td></tr><tr><td><strong>0,66 </strong></td><td><strong>1 </strong></td></tr><tr><td rowspan="3">ВБШвнг(А)-LSLTx </td><td>1* </td><td>- </td><td>10 - 630 </td></tr><tr><td>3 </td><td rowspan="2">1,5 - 50 </td><td>1,5 - 400 </td></tr><tr><td>2,4;5 </td><td>1,5 - 240 </td></tr></tbody></table><p><strong>Применение ВБШВнг(А)-LSLTx: </strong><br/></p><p>Кабели предназначены: </p><ul><li>для передачи и распределения электроэнергии и электрических сигналов в стационарных установках, при номинальном переменном напряжении до 1 кВ включительно номинальной частотой 50 Гц или при постоянном напряжении до1,5 кВ; </li><li>для групповой прокладки во взрывоопасных зонах, в зданиях и сооружениях с массовым пребыванием людей, метрополитенов, объектов АС в не гермозоны. Огнестойкие – для систем, которые должны сохранять работоспособность при пожаре; </li><li>для эксплуатации во взрывоопасных зонах класса В-1 кабели марок <strong>В БШ в нг (А) -LSLTx </strong>; </li><li>Класс пожарной опасности по ГОСТ Р 53315-2009. П1б.8.2.1.2 </li></ul><p><strong>Технические характеристики ВБШВнг(А)-LSLTx: </strong><br/></p><ul><li>Климатическое исполнение УХЛ, категорий размещения 3 и 4 по ГОСТ 15150-69 </li><li>Диапазон температур эксплуатации: от -50°С до +50°С </li><li>Относительная влажность воздуха при температуре до +35 <sup>0 </sup>С до 98% </li><li>Прокладка без предварительного подогрева производится при температуре воздуха не ниже -15 <sup>0 </sup>С </li><li>Наименьший радиус изгиба: </li></ul><p><strong>- </strong>для одножильных кабелей 10 макс. наружных диаметров кабеля; </p><p><strong>- </strong>для многожильных кабелей 7,5 макс. наружных диаметров кабеля; </p><ul><li>Кабели не распространяют горение при групповой прокладке по категории А </li><li>Дымообразование при горении и тлении кабелей не приводит к снижению светопроницаемости в испытательной камере более чем на 50%. </li><li>Предельная температура нагрева жил по условию не возгорания кабеля при коротком замыкании не более 350 <sup>0 </sup>С </li><li>Строительная длина кабелей устанавливается при заказе </li></ul><ul><li>Кабели экологически безопасны </li><li>Срок службы – 30 лет с даты изготовления кабелей </li><li>Гарантийный срок эксплуатации 5 лет с даты ввода кабелей в эксплуатацию, но не позднее 6 месяцев с даты изготовления </li><li>Срок хранения: </li></ul><p>- на открытых площадках не более 2 лет; </p><p>- под навесом не более 5 лет; </p><p>- в закрытых помещениях – не более 10 лет. </p></div>','assets/img/products/vbshvngfrlstx__2d41ae610c9d4809fe607e58.jpg','м',NULL,'Укажите марку, число и сечение жил, рабочее напряжение, длину и условия прокладки.',1,0,529,'ВБШВнг(А)-LSLTx — купить по заявке | Монополия','ВБШВнг(А)-LSLTx: подбор и поставка в Санкт-Петербурге. Укажите марку, число и сечение жил, рабочее напряжение, длину и условия прокладки. Расчет стоимости — по заявке.','site/www.monopoly-torg.ru/100-vbshvng-a-lsltx__fb8fca8d67a20a5c533b2757.html','[["0,66", "1"], ["2,4;5", "1,5 - 240"]]','["assets/img/products/vbshvngfrlstx__2d41ae610c9d4809fe607e58.jpg"]','["http://www.monopoly-torg.ru/index.php/kabelnaya-produkciya/kabeli-silovye-s-pvkh-izolyatsiej/100-vbshvng-a-lsltx"]') ON DUPLICATE KEY UPDATE `category_id`=VALUES(`category_id`),`root_category`=VALUES(`root_category`),`name`=VALUES(`name`),`slug`=VALUES(`slug`),`sku`=VALUES(`sku`),`short_description`=VALUES(`short_description`),`description_html`=VALUES(`description_html`),`image`=VALUES(`image`),`unit`=VALUES(`unit`),`price`=VALUES(`price`),`request_hint`=VALUES(`request_hint`),`active`=VALUES(`active`),`featured`=VALUES(`featured`),`sort_order`=VALUES(`sort_order`),`seo_title`=VALUES(`seo_title`),`seo_description`=VALUES(`seo_description`),`source_file`=VALUES(`source_file`),`specs_json`=VALUES(`specs_json`),`gallery_json`=VALUES(`gallery_json`),`old_urls_json`=VALUES(`old_urls_json`);
INSERT INTO `products` (`id`,`category_id`,`root_category`,`name`,`slug`,`sku`,`short_description`,`description_html`,`image`,`unit`,`price`,`request_hint`,`active`,`featured`,`sort_order`,`seo_title`,`seo_description`,`source_file`,`specs_json`,`gallery_json`,`old_urls_json`) VALUES (530,16,'cable','ВВБГ-1','101-vvbg-1','MNP-0530','3. Обмотка из нетканого полотна для многожильных кабелей сечением 16 кв. мм. и выше; 4. Оболочка из ПВХ пластиката; 5. Подушка из крепированной бумаги; 6. Броня из стальных или стальных оцинкованных лент. Область применения ВВБГ-1: Силовые кабели.','<div><p>ВВБГ-1 </p><p><img alt="vvbg" loading="lazy" src="assets/img/products/vvbg__62acdc9dd5a3b45e72cf00ee.jpg"/></p><p>Медная токопроводящая жила: <br/></p><ul><li>однопроволочная (класс 1) сечением 2,5—240 кв. мм—”ож”, </li><li>многопроволочная (класс 2) сечением 70—240 кв. мм; </li></ul><p>2. Изоляция из ПВХ пластиката, маркировка жил: <br/></p><ul><li>цветовая, </li><li>цифровая; </li></ul><p>3. Обмотка из нетканого полотна для многожильных кабелей сечением 16 кв. мм. и выше; <br/>4. Оболочка из ПВХ пластиката; <br/>5. Подушка из крепированной бумаги; <br/>6. Броня из стальных или стальных оцинкованных лент. <strong>Область применения ВВБГ-1: <br/></strong>Силовые кабели <strong>ВВБГ </strong>предназначены для передачи и распределения электрической энергии в стационарных установках на номинальное переменное напряжение 1,0 кВ частоты 50Гц. Изготавливаются для эксплуатации в районах с умеренным и холодным климатом. Кабели предназначены для эксплуатации на суше, реках и озерах на высотах до 4300 м. над уровнем моря. <strong>Прокладка ВВБГ-1: </strong><br/></p><ul><li>в земле (траншеях) с низкой, средней или высокой коррозионной активностью, с наличием или отсутствием блуждающих токов, и если в процессе эксплуатации кабели не подвергаются значительным растягивающим усилиям; </li><li>в воздухе при наличии опасности механических повреждений в ходе эксплуатации; </li><li>в сухих или сырых помещениях (туннелях), каналах, кабельных полуэтажах, шахтах, коллекторах, производственных помещениях, частично затапливаемых сооружениях при наличии среды со слабой, средней и высокой коррозионной активностью; </li><li>в пожароопасных помещениях; </li><li>во взрывоопасных зонах класса B-I, B-Iа, B-Iб, B-Iг, В-II, В-IIа. </li></ul><p>Кабели <strong>ВВБГ </strong>предназначены для вертикальных, наклонных и горизонтальных трасс. Не распространяют горение при одиночной прокладке (нормы МЭК 60332-1). Допустимый нагрев токопроводящих жил в аварийном режиме не должен превышать +80°С c продолжительностью работы не более 8 часов в сутки и не более 1000 часов за срок службы. <strong>Технические характеристики </strong><strong></strong><strong>ВВБГ-1 </strong><br/></p><table><tbody><tr><td>Влажность воздуха при 35° C [%] </td><td><strong>98 </strong></td></tr><tr><td>Испытательное переменное напряжение частотой 50 Гц, 10 мин. [кВ] </td><td><strong>3.5 </strong></td></tr><tr><td>Максимальная рабочая температура жилы [°С] </td><td><strong>70 </strong></td></tr><tr><td>Максимальное переменное напряжение частоты 50 Гц [кВ] </td><td><strong>1.2 </strong></td></tr><tr><td>Монтаж при температуре, не ниже [°C] </td><td><strong>-15 </strong></td></tr><tr><td>Номинальное переменное напряжение частотой 50 Гц [кВ] </td><td><strong>1 </strong></td></tr><tr><td>Радиус изгиба кабелей [наружных диаметров] </td><td><strong>7.5 </strong></td></tr><tr><td>Сопротивление изоляции при температуре +70° С, не менее [МОм х км] </td><td><strong>0.005 </strong></td></tr><tr><td>Температура окружающей среды, верхний предел [°C] </td><td><strong>+50 </strong></td></tr><tr><td>Температура окружающей среды, нижний предел [°C] </td><td><strong>-50 </strong></td></tr><tr><td>Температура токопроводящих жил при коротком замыкании [°С] </td><td><strong>160 </strong></td></tr></tbody></table><p><br/>Срок службы — 30 лет. <br/><br/></p><table><tbody><tr><td><strong>Число и номинальное сечение жил, мм2 </strong></td><td><strong>Наружный диаметр кабеля, мм </strong></td><td><strong>Масса 1 км кабеля, кг </strong></td></tr><tr><td>ВВБГ-1 2х1,5 </td><td>11 </td><td>267 </td></tr><tr><td>ВВБГ-1 2х2,5 </td><td>12,3 </td><td>326 </td></tr><tr><td>ВВБГ-1 2х4 </td><td>14,1 </td><td>404 </td></tr><tr><td>ВВБГ-1 2х6 </td><td>15,1 </td><td>465 </td></tr><tr><td>ВВБГ-1 2х10 </td><td>16,7 </td><td>573 </td></tr><tr><td>ВВБГ-1 2х16 </td><td>19,7 </td><td>775 </td></tr><tr><td>ВВБГ-1 2х25 </td><td>22,4 </td><td>1035 </td></tr><tr><td>ВВБГ-1 2х35 </td><td>24,8 </td><td>1449 </td></tr><tr><td>ВВБГ-1 2х50 </td><td>28,2 </td><td>1824 </td></tr><tr><td></td><td></td><td></td></tr><tr><td>ВВБГ-1 3х1,5 </td><td>124 </td><td>321 </td></tr><tr><td>ВВБГ-1 3х2,5 </td><td>12,9 </td><td>368 </td></tr><tr><td>ВВБГ-1 3х4 </td><td>14,7 </td><td>467 </td></tr><tr><td>ВВБГ-1 3х6 </td><td>15,8 </td><td>541 </td></tr><tr><td>ВВБГ-1 3х10 </td><td>17,5 </td><td>700 </td></tr><tr><td>ВВБГ-1 3х16 </td><td>21,2 </td><td>996 </td></tr><tr><td>ВВБГ-1 3х25 </td><td>24 </td><td>1507 </td></tr><tr><td>ВВБГ-1 3х35 </td><td>26,2 </td><td>1848 </td></tr><tr><td>ВВБГ-1 3х50 </td><td>29,8 </td><td>2356 </td></tr><tr><td>ВВБГ-1 3х1,5+1х1 </td><td>12,8 </td><td>355 </td></tr><tr><td>ВВБГ-1 3х1,5+1х1,5 </td><td>12,8 </td><td>361 </td></tr><tr><td>ВВБГ-1 3х2,5+1х1,5 </td><td>13,7 </td><td>410 </td></tr><tr><td>ВВБГ-1 3х4+1х2,5 </td><td>15,4 </td><td>514 </td></tr><tr><td>ВВБГ-1 3х6+1х2,5 </td><td>16,5 </td><td>589 </td></tr><tr><td>ВВБГ-1 3х6+1х4 </td><td>17 </td><td>618 </td></tr><tr><td>ВВБГ-1 3х10+1х4 </td><td>18,4 </td><td>769 </td></tr><tr><td>ВВБГ-1 3х10+1х6 </td><td>19 </td><td>802 </td></tr><tr><td>ВВБГ-1 3х16+1х6 </td><td>21,8 </td><td>1078 </td></tr><tr><td>ВВБГ-1 3х16+1х10 </td><td>22,3 </td><td>1131 </td></tr><tr><td>ВВБГ-1 3х25+1х10 </td><td>24,7 </td><td>1636 </td></tr><tr><td>ВВБГ-1 3х25+1х16 </td><td>26,2 </td><td>1746 </td></tr><tr><td>ВВБГ-1 3х35+1х16 </td><td>28,1 </td><td>2099 </td></tr><tr><td>ВВБГ-1 3х50+1х16 </td><td>30,7 </td><td>2556 </td></tr><tr><td>ВВБГ-1 3х50+1х25 </td><td>31,5 </td><td>2675 </td></tr><tr><td></td><td></td><td></td></tr><tr><td>ВВБГ-1 4х1,5 </td><td>12,8 </td><td>361 </td></tr><tr><td>ВВБГ-1 4х2,5 </td><td>13,7 </td><td>420 </td></tr><tr><td>ВВБГ-1 4х4 </td><td>15,8 </td><td>533 </td></tr><tr><td>ВВБГ-1 4х6 </td><td>17 </td><td>637 </td></tr><tr><td>ВВБГ-1 4х10 </td><td>19 </td><td>841 </td></tr><tr><td>ВВБГ-1 4х16 </td><td>23,4 </td><td>1386 </td></tr><tr><td>ВВБГ-1 4х25 </td><td>26,2 </td><td>1838 </td></tr><tr><td>ВВБГ-1 4х35 </td><td>29 </td><td>2311 </td></tr><tr><td>ВВБГ-1 4х50 </td><td>32,6 </td><td>2925 </td></tr><tr><td></td><td></td><td></td></tr><tr><td>ВВБГ-1 5х1,5 </td><td>14,7 </td><td>477 </td></tr><tr><td>ВВБГ-1 5х2,5 </td><td>15,7 </td><td>548 </td></tr><tr><td>ВВБГ-1 5х4 </td><td>18,1 </td><td>721 </td></tr><tr><td>ВВБГ-1 5х6 </td><td>19,4 </td><td>861 </td></tr><tr><td>ВВБГ-1 5х10 </td><td>22 </td><td>1164 </td></tr><tr><td>ВВБГ-1 5х16 </td><td>26,9 </td><td>1875 </td></tr><tr><td>ВВБГ-1 5х25 </td><td>29,9 </td><td>2487 </td></tr><tr><td>ВВБГ-1 5х35 </td><td>32,6 </td><td>3082 </td></tr></tbody></table><p><br/><br/>При сечении основных жил 16 кв.мм. и менее, строительная длина составляет не менее 450 м. <br/>При сечении основных жил 25-70 кв.мм., строительная длина составляет не менее 300 м. <br/>При сечении основных жил 95 кв.мм. и выше, строительная длина составляет не менее 200 м. </p></div>','assets/img/products/vvbg__62acdc9dd5a3b45e72cf00ee.jpg','м',NULL,'Укажите марку, число и сечение жил, рабочее напряжение, длину и условия прокладки.',1,0,530,'ВВБГ-1 — купить по заявке | Монополия','ВВБГ-1: подбор и поставка в Санкт-Петербурге. Укажите марку, число и сечение жил, рабочее напряжение, длину и условия прокладки. Расчет стоимости — по заявке.','site/www.monopoly-torg.ru/101-vvbg-1__8b8b440a764bb64a7b246305.html','[["Влажность воздуха при 35° C [%]", "98"], ["Испытательное переменное напряжение частотой 50 Гц, 10 мин. [кВ]", "3.5"], ["Максимальная рабочая температура жилы [°С]", "70"], ["Максимальное переменное напряжение частоты 50 Гц [кВ]", "1.2"], ["Монтаж при температуре, не ниже [°C]", "-15"], ["Номинальное переменное напряжение частотой 50 Гц [кВ]", "1"], ["Радиус изгиба кабелей [наружных диаметров]", "7.5"], ["Сопротивление изоляции при температуре +70° С, не менее [МОм х км]", "0.005"], ["Температура окружающей среды, верхний предел [°C]", "+50"], ["Температура окружающей среды, нижний предел [°C]", "-50"], ["Температура токопроводящих жил при коротком замыкании [°С]", "160"]]','["assets/img/products/vvbg__62acdc9dd5a3b45e72cf00ee.jpg"]','["http://www.monopoly-torg.ru/index.php/kabelnaya-produkciya/kabeli-silovye-s-pvkh-izolyatsiej/101-vvbg-1"]') ON DUPLICATE KEY UPDATE `category_id`=VALUES(`category_id`),`root_category`=VALUES(`root_category`),`name`=VALUES(`name`),`slug`=VALUES(`slug`),`sku`=VALUES(`sku`),`short_description`=VALUES(`short_description`),`description_html`=VALUES(`description_html`),`image`=VALUES(`image`),`unit`=VALUES(`unit`),`price`=VALUES(`price`),`request_hint`=VALUES(`request_hint`),`active`=VALUES(`active`),`featured`=VALUES(`featured`),`sort_order`=VALUES(`sort_order`),`seo_title`=VALUES(`seo_title`),`seo_description`=VALUES(`seo_description`),`source_file`=VALUES(`source_file`),`specs_json`=VALUES(`specs_json`),`gallery_json`=VALUES(`gallery_json`),`old_urls_json`=VALUES(`old_urls_json`);
INSERT INTO `products` (`id`,`category_id`,`root_category`,`name`,`slug`,`sku`,`short_description`,`description_html`,`image`,`unit`,`price`,`request_hint`,`active`,`featured`,`sort_order`,`seo_title`,`seo_description`,`source_file`,`specs_json`,`gallery_json`,`old_urls_json`) VALUES (531,16,'cable','ВВГ','102-vvg','MNP-0531','Кабели с ПВХ изоляцией в ПВХ оболочке на напряжение 660 В, 1000 В. ГОСТ 16442-80','<div><p>ВВГ </p><p><img alt="avvg-vvg" loading="lazy" src="assets/img/products/avvg-vvg__575c87b359d0352fdf3bb183.jpg"/></p><p>Кабели с ПВХ изоляцией в ПВХ оболочке на напряжение 660 В, 1000 В. ГОСТ 16442-80 <br/></p><div><h2>Аналоги ВВГ <br/></h2><p>NYY, NYY-J, NYY-O, NY2Y </p></div><div><h2>Конструкция ВВГ <br/></h2><ol><li>Токопроводящая жила — медная, однопроволочная или многопроволочная, круглой или секторной формы, 1 или 2 класса по ГОСТ 22483-77. Число жил: 1-5. Четырехжильные кабели могут иметь 3 жилы одинакового сечения и одну жилу меньшего сечения (жилу заземления или нулевую). </li><li>Изоляция — из поливинилхлоридного пластиката (ПВХ). Изолированные жилы многожильных кабелей имеют отличительную расцветку. Изоляция жил заземления выполняется двухцветной (зелено-желтой), нулевых жил — голубого цвета. </li><li>Расположение жил в кабеле — изолированные жилы 2-5 жильных кабелей скручены в сердечник. В кабелях с секторными жилами поверх скрученных жил накладывается лента из полиэтилентерефталатной пленки. В кабелях марок ВВГ-П (плоское исполнение) две или три изолированных жилы уложены параллельно в одной плоскости. </li><li>Оболочка: — из ПВХ пластиката. </li></ol></div><div><h2>Применение ВВГ <br/></h2><p>Кабели <strong>ВВГ </strong>предназначены для передачи и распределения электроэнергии в стационарных установках на номинальное переменное напряжение 660 и 1000 В частоты 50 Гц. </p><p>Кабели <strong>ВВГ </strong>применяются для прокладки в сухих и влажных производственных помещениях, на специальных кабельных эстакадах, в блоках, а также для прокладки на открытом воздухе. Кабели не рекомендуются для прокладки в земле (траншеях). </p><p>Кабели не распространяют горение при одиночной прокладке. </p></div><h2>Технические характеристики ВВГ <br/></h2><p>Вид климатического исполнения кабелей по ГОСТ 15150-69: УХЛ и Т, категории размещения 1 и 5. </p><table><tbody><tr><td>Диапазон температур эксплуатации (относительная влажность воздуха при температуре до +35°С — до 98%) </td><td>от -50°С до +50°С </td></tr><tr><td>Длительно допустимая температура нагрева жил кабелей при эксплуатации </td><td>не более +70°С </td></tr><tr><td>Строительная длина кабелей для номин. сечений основных жил </td><td><ul><li>до 16 мм² — не менее 450 м </li><li>25 – 70 мм² — не менее 300 м </li><li>95 мм² и выше — не менее 200 м </li></ul></td></tr><tr><td>Прокладка и монтаж кабелей без предварительного подогрева </td><td>не ниже -15°С </td></tr><tr><td>Минимальный радиус изгиба при прокладке </td><td><ul><li>кабелей одножильных — 10 наружных диаметров </li><li>кабелей многожильных — 7,5 наружных диаметров </li></ul></td></tr><tr><td>Гарантийный срок эксплуатации </td><td>5 лет с даты ввода кабелей в эксплуатацию </td></tr><tr><td>Срок службы </td><td>30 лет </td></tr></tbody></table></div>','assets/img/products/avvg-vvg__575c87b359d0352fdf3bb183.jpg','м',NULL,'Укажите марку, число и сечение жил, рабочее напряжение, длину и условия прокладки.',1,1,531,'ВВГ — купить по заявке | Монополия','ВВГ: подбор и поставка в Санкт-Петербурге. Укажите марку, число и сечение жил, рабочее напряжение, длину и условия прокладки. Расчет стоимости — по заявке.','site/www.monopoly-torg.ru/102-vvg__45482971d5aa3d4fb2e9e9c2.html','[["Диапазон температур эксплуатации (относительная влажность воздуха при температуре до +35°С — до 98%)", "от -50°С до +50°С"], ["Длительно допустимая температура нагрева жил кабелей при эксплуатации", "не более +70°С"], ["Строительная длина кабелей для номин. сечений основных жил", "до 16 мм² — не менее 450 м 25 – 70 мм² — не менее 300 м 95 мм² и выше — не менее 200 м"], ["Прокладка и монтаж кабелей без предварительного подогрева", "не ниже -15°С"], ["Минимальный радиус изгиба при прокладке", "кабелей одножильных — 10 наружных диаметров кабелей многожильных — 7,5 наружных диаметров"], ["Гарантийный срок эксплуатации", "5 лет с даты ввода кабелей в эксплуатацию"], ["Срок службы", "30 лет"]]','["assets/img/products/avvg-vvg__575c87b359d0352fdf3bb183.jpg"]','["http://www.monopoly-torg.ru/index.php/kabelnaya-produkciya/kabeli-silovye-s-pvkh-izolyatsiej/102-vvg"]') ON DUPLICATE KEY UPDATE `category_id`=VALUES(`category_id`),`root_category`=VALUES(`root_category`),`name`=VALUES(`name`),`slug`=VALUES(`slug`),`sku`=VALUES(`sku`),`short_description`=VALUES(`short_description`),`description_html`=VALUES(`description_html`),`image`=VALUES(`image`),`unit`=VALUES(`unit`),`price`=VALUES(`price`),`request_hint`=VALUES(`request_hint`),`active`=VALUES(`active`),`featured`=VALUES(`featured`),`sort_order`=VALUES(`sort_order`),`seo_title`=VALUES(`seo_title`),`seo_description`=VALUES(`seo_description`),`source_file`=VALUES(`source_file`),`specs_json`=VALUES(`specs_json`),`gallery_json`=VALUES(`gallery_json`),`old_urls_json`=VALUES(`old_urls_json`);
INSERT INTO `products` (`id`,`category_id`,`root_category`,`name`,`slug`,`sku`,`short_description`,`description_html`,`image`,`unit`,`price`,`request_hint`,`active`,`featured`,`sort_order`,`seo_title`,`seo_description`,`source_file`,`specs_json`,`gallery_json`,`old_urls_json`) VALUES (532,16,'cable','ВВГ-0,66','103-vvg-0-66','MNP-0532','Силовые кабели ВВГ предназначены для передачи и распределения электрической энергии в стационарных установках на номинальное переменное напряжение 0,66 кВ и 1,0 кВ частоты 50Гц или на постоянное напряжение в 2,4 раза больше переменного напряжения.','<div><p>ВВГ-0,66 </p><p><img alt="vvg660" loading="lazy" src="assets/img/products/vvg660__964809ca8a19eeb83430d1f1.jpg"/></p><ol><li>Медная токопроводящая однопроволочная или многопроволочная жила сечением 1,5-50 кв. мм <br/>(количество жил: 1, 2, 3, 3+1, 4 и 5 шт); </li><li>Изоляция из ПВХ пластиката, маркировка жил: <br/>цветовая: белая или желтая, синяя или зеленая, красная или малиновая, коричневая или черная, или желто-зеленая; </li><li>Оболочка из ПВХ пластиката ; </li><li>Обмотка из нетканого полотна для многожильных кабелей сечением жил 16 кв. мм и выше (допускается изготовление без обмотки) . </li></ol><p><strong>Область применения ВВГ-0,66: </strong></p><p>Силовые кабели <strong>ВВГ </strong>предназначены для передачи и распределения электрической энергии в стационарных установках на номинальное переменное напряжение 0,66 кВ и 1,0 кВ частоты 50Гц или на постоянное напряжение в 2,4 раза больше переменного напряжения. </p><p>Кабели изготавливаются для эксплуатации в районах с умеренным, холодным и тропическим климатом. Кабели предназначены для эксплуатации на суше, реках и озерах на высотах до 4300 м. над уровнем моря. </p><p>Кабели применяются для прокладки: </p><ul><li>в воздухе при отсутствии опасности механических повреждений в ходе эксплуатации; </li><li>для прокладки в сухих или сырых помещениях (туннелях), каналах, кабельных полуэтажах, шахтах, коллекторах, производственных помещениях, частично затапливаемых сооружениях при наличии среды со слабой, средней и высокой коррозионной активностью; </li><li>для прокладки на специальных кабельных эстакадах, по мостам и в блоках; </li><li>для прокладки в пожароопасных помещениях; </li><li>для прокладки во взрывоопасных зонах класса B-Iб, B-Iг, В-II, В-IIа; </li><li>кабели с медными жилами применяются для прокладки групповых осветительных сетей во взрывоопасных зонах класса В-Iа. </li></ul><p>Кабели <strong>ВВГ-0,66 кВ </strong>предназначены для вертикальных, наклонных и горизонтальных трасс. Небронированные кабели могут использоваться в местах подверженных вибрации. Кабели не распространяют горение при одиночной прокладке (нормы МЭК 60332-1). Кабели в тропическом климатическом исполнении (индекс «-Т») устойчивы к воздействию плесневых грибов. Допустимый нагрев токопроводящих жил в аварийном режиме не должен превышать +80°С и продолжительность работы в аварийном режиме не должна быть более 8 часов в сутки, но не более 1000 часов за срок службы. </p><p><strong>Технические характеристики кабеля ВВГ-0,66 </strong><br/></p><table><tbody><tr><td>Влажность воздуха при 35° C [%] </td><td><strong>98 </strong></td></tr><tr><td>Гарантийный срок эксплуатации [месяц] </td><td><strong>60 </strong></td></tr><tr><td>Испытательное переменное напряжение частотой 50 Гц, 10 мин. [кВ] </td><td><strong>3.0 </strong></td></tr><tr><td>Максимальная рабочая температура жилы [°С] </td><td><strong>70 </strong></td></tr><tr><td>Максимальное переменное напряжение частоты 50 Гц [кВ] </td><td><strong>0.72 </strong></td></tr><tr><td>Монтаж при температуре, не ниже [°C] </td><td><strong>-15 </strong></td></tr><tr><td>Номинальное переменное напряжение частотой 50 Гц [кВ] </td><td><strong>0.66 </strong></td></tr><tr><td>Радиус изгиба многожильных кабелей, не менее [наружных диаметров] </td><td><strong>7.5 </strong></td></tr><tr><td>Радиус изгиба одножильных кабелей, не менее [наружных диаметров] </td><td><strong>10 </strong></td></tr><tr><td>Сопротивление изоляции при температуре +70° С, не менее [МОм х км] </td><td><strong>0.005 </strong></td></tr><tr><td>Температура окружающей среды, верхний предел [°C] </td><td><strong>+50 </strong></td></tr><tr><td>Температура окружающей среды, нижний предел [°C] </td><td><strong>-50 </strong></td></tr><tr><td>Температура токопроводящих жил при коротком замыкании [°С] </td><td><strong>160 </strong></td></tr></tbody></table><p>Срок службы кабелей - 30 лет. </p><table><tbody><tr><td><strong>Количество и сечение <br/>жил, шт. х кв. мм </strong></td><td><strong>Масса, кг/км </strong></td><td><strong>Наружный размер, мм </strong></td></tr><tr><td>ВВГ -0,66 1 х 1,5 </td><td>36,0 </td><td>4,7 </td></tr><tr><td>ВВГ -0,66 1 х 2,5 </td><td>47,0 </td><td>5,0 </td></tr><tr><td>ВВГ -0,66 1 х 4 </td><td>65,0 </td><td>5,7 </td></tr><tr><td>ВВГ -0,66 1 х 6 </td><td>87,0 </td><td>6,2 </td></tr><tr><td>ВВГ -0,66 1 х 10 </td><td>134,0 </td><td>7,4 </td></tr><tr><td>ВВГ -0,66 1 х 16 ож </td><td>204,0 </td><td>8,8 </td></tr><tr><td>ВВГ -0,66 1 х 16 </td><td>219 </td><td>9,5 </td></tr><tr><td>ВВГ -0,66 1 х 25 ож </td><td>304,0 </td><td>10,4 </td></tr><tr><td>ВВГ -0,66 1 х 25 </td><td>327,0 </td><td>11,2 </td></tr><tr><td>ВВГ -0,66 1 х 35 ож </td><td>399,0 </td><td>11,4 </td></tr><tr><td>ВВГ -0,66 1 х 35 </td><td>429,0 </td><td>12,4 </td></tr><tr><td>ВВГ -0,66 1 х 50 ож </td><td>528,0 </td><td>12,8 </td></tr><tr><td>ВВГ -0,66 1 х 50 </td><td>578,0 </td><td>13,5 </td></tr><tr><td>ВВГ -0,66 2 х 1,5 </td><td>66,0 </td><td>7,1 </td></tr><tr><td>ВВГ -0,66 2 х 2,5 </td><td>88,0 </td><td>7,9 </td></tr><tr><td>ВВГ -0,66 2 х 4 </td><td>139,0 </td><td>9,8 </td></tr><tr><td>ВВГ -0,66 2 х 6 </td><td>183,0 </td><td>10,8 </td></tr><tr><td>ВВГ -0,66 2 х 10 </td><td>281,0 </td><td>13,2 </td></tr><tr><td>ВВГ -0,66 2 х 16 ож </td><td>443,0 </td><td>15,5 </td></tr><tr><td>ВВГ -0,66 1 х 25 ож </td><td>681,0 </td><td>19,0 </td></tr><tr><td>ВВГ -0,66 1 х 35 ож </td><td>898,0 </td><td>20,9 </td></