INSERT INTO `products` (`id`,`category_id`,`root_category`,`name`,`slug`,`sku`,`short_description`,`description_html`,`image`,`unit`,`price`,`request_hint`,`active`,`featured`,`sort_order`,`seo_title`,`seo_description`,`source_file`,`specs_json`,`gallery_json`,`old_urls_json`) VALUES (552,16,'cable','ВВГнг-ХЛ','123-vvgng-khl','MNP-0552','Согласно ГОСТ Р 53769-2010 кабель соответствует марке ВВГнг(А)-ХЛ','<div><p>ВВГнг-ХЛ </p><p><img alt="vvgng" loading="lazy" src="assets/img/products/vvgng__7cd8429dfadf77c44279db2a.jpg"/></p><ol><li>Токопроводящая жила - медная, однопроволочная или многопроволочная, круглой или секторной формы, 1 или 2 класса по ГОСТ 22483. </li><li>Изоляция - из поливинилхлоридного пластиката (ПВХ). Изолированные жилы многожильных кабелей имеют отличительную расцветку. Изоляция нулевых жил выполняется голубого цвета. Изоляция жил заземления выполняется двухцветной (зелено-желтой расцветки). </li><li>Поясная изоляция - в одножильных кабелях выпрессована из поливинилхлоридного пластиката пониженной горючести </li><li>Скрутка - изолированные жилы скручены; изолированные жилы трех-, четырех- и пятижильных кабелей скручиваются в сердечник вокруг жгута из ПВХ пластиката пониженной горючести. Кабели имеют заполнение между жилами из ПВХ пластиката пониженной горючести или невулканизированной резиновой смеси пониженной горючести, которое накладывается одновременно с поясной изоляцией или оболочкой. </li><li>Оболочка - из ПВХ пластиката пониженной горючести, в холодостойком исполнении </li></ol><p><br/><strong>Область применения кабеля ВВГнг-ХЛ: </strong><br/></p><ul><li>Для передачи и распределения электроэнергии в стационарных установках на номинальное переменное напряжение 660 В и 1000 В частоты 50 Гц. </li><li>Для прокладки в сухих и влажных производственных помещениях, на специальных кабельных эстакадах, в блоках, а также для прокладки на открытом воздухе </li></ul><p><br/><strong>Технические характеристики ВВГнг-ХЛ: </strong><br/></p><ul><li>Вид климатического исполнения кабелей УХЛ и Т, категорий размещения 1 и 5 по ГОСТ 15150-69 </li><li>Диапазон температур эксплуатации: от -60°С до +40°С </li><li>Относительная влажность воздуха при температуре до +35°С: до 98% </li><li>Номинальная частота: 50 Гц </li><li>Изоляция и оболочка стойка к растрескиванию после выдержки при температуре 1350 в течение 1 ч. </li><li>Кабели распространяют горение при испытании в пучках по категории А </li><li>Длительно допустимая температура нагрева жил кабелей при эксплуатации: +70°С -Прокладка производится при температуре указанных в ГОСТ 16442-80 и ГОСТ 1508-78 </li><li>Гарантийный срок эксплуатации кабеля <strong>ВВГнг-ХЛ </strong>- 3 года с даты ввода кабелей в эксплуатацию. </li></ul><p><br/>Согласно ГОСТ Р 53769-2010 кабель соответствует марке <strong>ВВГнг(А)-ХЛ </strong></p></div>','assets/img/products/vvgng__7cd8429dfadf77c44279db2a.jpg','м',NULL,'Укажите марку, число и сечение жил, рабочее напряжение, длину и условия прокладки.',1,0,552,'ВВГнг-ХЛ — купить по заявке | Монополия','ВВГнг-ХЛ: подбор и поставка в Санкт-Петербурге. Укажите марку, число и сечение жил, рабочее напряжение, длину и условия прокладки. Расчет стоимости — по заявке.','site/www.monopoly-torg.ru/123-vvgng-khl__d3c23ad63ee24c374d27312b.html','[]','["assets/img/products/vvgng__7cd8429dfadf77c44279db2a.jpg"]','["http://www.monopoly-torg.ru/index.php/kabelnaya-produkciya/kabeli-silovye-s-pvkh-izolyatsiej/123-vvgng-khl"]') ON DUPLICATE KEY UPDATE `category_id`=VALUES(`category_id`),`root_category`=VALUES(`root_category`),`name`=VALUES(`name`),`slug`=VALUES(`slug`),`sku`=VALUES(`sku`),`short_description`=VALUES(`short_description`),`description_html`=VALUES(`description_html`),`image`=VALUES(`image`),`unit`=VALUES(`unit`),`price`=VALUES(`price`),`request_hint`=VALUES(`request_hint`),`active`=VALUES(`active`),`featured`=VALUES(`featured`),`sort_order`=VALUES(`sort_order`),`seo_title`=VALUES(`seo_title`),`seo_description`=VALUES(`seo_description`),`source_file`=VALUES(`source_file`),`specs_json`=VALUES(`specs_json`),`gallery_json`=VALUES(`gallery_json`),`old_urls_json`=VALUES(`old_urls_json`);
INSERT INTO `products` (`id`,`category_id`,`root_category`,`name`,`slug`,`sku`,`short_description`,`description_html`,`image`,`unit`,`price`,`request_hint`,`active`,`featured`,`sort_order`,`seo_title`,`seo_description`,`source_file`,`specs_json`,`gallery_json`,`old_urls_json`) VALUES (553,16,'cable','ВВГнгLS','124-vvgngls','MNP-0553','Кабели с ПВХ изоляцией в ПВХ оболочке, не распространяющие горение, с низким дымо— и газовыделением (LS — Low Smoke), на напряжение 660 В, 1000 В.','<div><p>ВВГнгLS </p><p><img alt="avvg-vvg" loading="lazy" src="assets/img/products/avvg-vvg__575c87b359d0352fdf3bb183.jpg"/></p><p>Кабели с ПВХ изоляцией в ПВХ оболочке, не распространяющие горение, с низким дымо— и газовыделением (LS — Low Smoke), на напряжение 660 В, 1000 В. <br/></p><div><h2>Аналоги ВВГнгLS <br/></h2><p>NHMH </p></div><div><h2>Конструкция ВВГнгLS <br/></h2><ol><li>Токопроводящая жила — медная, однопроволочная или многопроволочная, круглой или секторной формы, 1 или 2 класса по ГОСТ 22483-77. Число жил: 5. Четырехжильные кабели могут иметь 3 жилы одинакового сечения и одну жилу меньшего сечения (жилу заземления или нулевую). </li><li>Изоляция — из ПВХ композиции пониженной пожароопасности. Изолированные жилы многожильных кабелей имеют отличительную расцветку. Изоляция жил заземления выполняется двухцветной (зелено-желтой), нулевых жил – голубого цвета. </li><li>Расположение жил в кабеле — изолированные жилы 2-5 жильных кабелей скручены в сердечник. В кабелях с секторными жилами поверх скрученных жил накладывается лента из полиэтилентерефталатной пленки. </li><li>Оболочка: — по скрученным изолированным круглым жилам накладывается внутренняя оболочка из ПВХ композиции пониженной пожароопасности, которая заполняет промежутки между жилами. Минимальная толщина оболочки — 0,3 мм. Кабели с секторными жилами изготавливаются без внутренней оболочки. Наружная оболочка — из ПВХ композиции пониженной пожароопасности. Для кабелей с сечением круглых жил до 16 мм² допускается наложение наружной оболочки с одновременным заполнением промежутков между жилами. В этом случае внутренняя экструдированная оболочка не накладывается. </li></ol></div><div><h2>Применение ВВГнгLS <br/></h2><div><p>Кабели <strong>ВВГнгLS </strong>предназначены для передачи и распределения электроэнергии в стационарных установках на номинальное переменное напряжение 660 и 1000 В или соответственно при постоянном напряжении 1000 и 1500В. </p><p>Кабели изготавливаются для общепромышленного применения и атомных станций (АС) при поставках на внутренний рынок и на экспорт. </p><p>Кабели <strong>ВВГнгLS </strong>предназначены для групповой прокладки кабельных линий в кабельных сооружениях и помещениях внутренних электроустановок, в том числе для объектов использования атомной энергии в системах АС классов 3 и 4 по классификации ОПБ—88 (ПНАЭ Г-01-011-97). </p><p>Кабели не распространяют горение при групповой прокладке. </p><p>Обозначение класса пожарной безопасности по классификации НПБ 248—П1.7.2.1. </p></div></div><h2>Технические характеристики ВВГнгLS <br/></h2><p>Вид климатического исполнения кабелей по ГОСТ 15150-69: УХЛ и Т, категории размещения 1 и 5. </p><table><tbody><tr><td>Диапазон температур эксплуатации (относительная влажность воздуха при температуре до +35°С —до 98% ) </td><td>от -50°С до +50°С </td></tr><tr><td>Длительно допустимая температура нагрева жил кабелей при эксплуатации </td><td>не более +70°С </td></tr><tr><td>Предельная температура токопроводящих жил по условию невозгорания кабеля при коротком замыкании </td><td>+400°С </td></tr><tr><td>Строительная длина кабелей для номин. сечений основных жил </td><td><ul><li>до 16 мм² — не менее 450 м </li><li>25 – 70 мм² — не менее 300 м </li><li>95 мм² и выше — не менее 200 м </li></ul></td></tr><tr><td>Прокладка и монтаж кабелей без предварительного подогрева </td><td>не ниже -15°С </td></tr><tr><td>Минимальный радиус изгиба при прокладке </td><td><ul><li>кабелей одножильных — 10 наружных диаметров </li><li>кабелей многожильных — 7,5 наружных диаметров </li></ul></td></tr><tr><td>Гарантийный срок эксплуатации </td><td>5 лет с даты ввода кабелей в эксплуатацию, но не позднее 6 месяцев с даты изготовления </td></tr><tr><td>Срок службы </td><td>30 лет </td></tr></tbody></table></div>','assets/img/products/avvg-vvg__575c87b359d0352fdf3bb183.jpg','м',NULL,'Укажите марку, число и сечение жил, рабочее напряжение, длину и условия прокладки.',1,0,553,'ВВГнгLS — купить по заявке | Монополия','ВВГнгLS: подбор и поставка в Санкт-Петербурге. Укажите марку, число и сечение жил, рабочее напряжение, длину и условия прокладки. Расчет стоимости — по заявке.','site/www.monopoly-torg.ru/124-vvgngls__7bbbb99a1085b8a9ec97c31d.html','[["Диапазон температур эксплуатации (относительная влажность воздуха при температуре до +35°С —до 98% )", "от -50°С до +50°С"], ["Длительно допустимая температура нагрева жил кабелей при эксплуатации", "не более +70°С"], ["Предельная температура токопроводящих жил по условию невозгорания кабеля при коротком замыкании", "+400°С"], ["Строительная длина кабелей для номин. сечений основных жил", "до 16 мм² — не менее 450 м 25 – 70 мм² — не менее 300 м 95 мм² и выше — не менее 200 м"], ["Прокладка и монтаж кабелей без предварительного подогрева", "не ниже -15°С"], ["Минимальный радиус изгиба при прокладке", "кабелей одножильных — 10 наружных диаметров кабелей многожильных — 7,5 наружных диаметров"], ["Гарантийный срок эксплуатации", "5 лет с даты ввода кабелей в эксплуатацию, но не позднее 6 месяцев с даты изготовления"], ["Срок службы", "30 лет"]]','["assets/img/products/avvg-vvg__575c87b359d0352fdf3bb183.jpg"]','["http://www.monopoly-torg.ru/index.php/kabelnaya-produkciya/kabeli-silovye-s-pvkh-izolyatsiej/124-vvgngls"]') ON DUPLICATE KEY UPDATE `category_id`=VALUES(`category_id`),`root_category`=VALUES(`root_category`),`name`=VALUES(`name`),`slug`=VALUES(`slug`),`sku`=VALUES(`sku`),`short_description`=VALUES(`short_description`),`description_html`=VALUES(`description_html`),`image`=VALUES(`image`),`unit`=VALUES(`unit`),`price`=VALUES(`price`),`request_hint`=VALUES(`request_hint`),`active`=VALUES(`active`),`featured`=VALUES(`featured`),`sort_order`=VALUES(`sort_order`),`seo_title`=VALUES(`seo_title`),`seo_description`=VALUES(`seo_description`),`source_file`=VALUES(`source_file`),`specs_json`=VALUES(`specs_json`),`gallery_json`=VALUES(`gallery_json`),`old_urls_json`=VALUES(`old_urls_json`);
INSERT INTO `products` (`id`,`category_id`,`root_category`,`name`,`slug`,`sku`,`short_description`,`description_html`,`image`,`unit`,`price`,`request_hint`,`active`,`featured`,`sort_order`,`seo_title`,`seo_description`,`source_file`,`specs_json`,`gallery_json`,`old_urls_json`) VALUES (554,16,'cable','ВВГЭ, ВВГЭнг, ВВГЭнг-LS','125-vvge-vvgeng-vvgeng-ls','MNP-0554','ВВГЭ, ВВГЭнг, ВВГЭнг-LS - Кабели силовые с медными жилами с пластмассовой изоляцией, экранированные','<div><p>ВВГЭ, ВВГЭнг, ВВГЭнг-LS </p><p><strong>ВВГЭ, ВВГЭнг, </strong><strong>ВВГЭнг-LS - </strong>Кабели силовые с медными жилами с пластмассовой изоляцией, экранированные </p><p><img alt="VVGE" loading="lazy" src="assets/img/products/VVGE__369cdcc33e1e776600d1363d.jpg"/></p><ol><li><strong>Токопроводящая жила </strong>– медная или алюминиевая </li><li><strong>Изоляция </strong>– из поливинилхлоридного пластиката. <em>Многожильные т </em>рех- и четырехжильные кабели скручены в сердечник вокруг жгута ,экструдированного из поливинилхлоридного пластиката , или ПВХ пластиката пониженной горючести, или поливинилхлоридной композиций пониженной пожароопасности, или невулканизированной резины. </li><li><strong>Поясная изоляция </strong>- с заполнением для кабелей марок <strong>ВВГЭ </strong>из поливинилхлоридного пластиката; для кабелей марок ВВГЭнг – из поливинилхлоридного пластиката пониженной горючести <br/><em>Одножильные кабели: </em><br/>- Поверх изолированной жилы одножильных кабелей всех марок наложена экструдированная поясная изоляция толщиной не менее 1,5 мм, поверх которой наложен слой обмоткой не менее 0,2 мм из лент электропроводящей кабельной бумаги или электропроводящей полимерной ленты </li><li><strong>Экран </strong>– из медных проволок и спирально наложенной медной ленты. </li><li><strong>Разделительный слой </strong>- для кабелей марок <strong>ВВГЭ </strong>из крепированной или кабельной бумаги, для кабелей марок <strong>ВВГЭнг </strong>прорезиненной ткани или пластмассовой ленты. В кабелях с индексом «г» допускается наложение разделительного слоя из водоблокирующей ленты. </li><li><strong>Оболочка </strong>– для кабелей марок <strong>ВВГЭ </strong>–из поливинилхлоридного пластиката,для кабелей марок ВВГЭнг – из ПВХ пластиката пониженной горючести, </li></ol><p><strong>Применение ВВГЭ, ВВГЭнг, ВВГЭнг-LS: </strong></p><p>Кабели <strong>ВВГЭ, ВВГЭнг, ВВГЭнг-LS </strong>предназначены для передачи и распределения электрической энергии в стационарных электротехнических установках, где требуется высокий уровень электрической и механической защиты,на номинальное переменное напряжение до 1 кВ номинальной частотой 50Гц <br/>Кабели предназначены для одиночной и групповой прокладки в производственных помещениях. </p><p><strong>Технические характеристики ВВГЭ, ВВГЭнг, ВВГЭнг-LS: </strong></p><ul><li>Вид климатического исполнения УХЛ и Т, категории размещения 1 и 5 по ГОСТ 15150-69 </li><li>Кабели стойки к воздействию окружающей среды от - 50°С до + 50°С </li><li>Кабели стойки к воздействию повышенной относительной влажности воздуха до 98% при температуре окружающей среды до 35°С </li><li>Длительно допустимая температура нагрева жил кабелей при эксплуатации не более: 70°С </li><li>Кабели ВВГЭ не распространяют горение при одиночной прокладке </li><li>Кабели ВВГЭнг, ВВГЭнг-LS н е распространяют горение при испытании в пучках по категории А. <br/></li></ul><p>Согласно ГОСТ Р 53769-2010 кабель <strong>ВВГЭнг </strong>соответствует марке <strong>ВВГЭнг(А) </strong>, <strong>ВВГЭнг-LS </strong>соответствует марке <strong>ВВГЭнг(А)-LS </strong><br/></p><ul><li>Срок службы не менее 30 лет при соблюдении требований по транспортированию, хранению, прокладке(монтажу) и эксплуатации </li></ul><p><strong>Оптовые цены на ВВГЭ, ВВГЭнг, ВВГЭнг-LS </strong></p></div>','assets/img/products/VVGE__369cdcc33e1e776600d1363d.jpg','м',NULL,'Укажите марку, число и сечение жил, рабочее напряжение, длину и условия прокладки.',1,0,554,'ВВГЭ, ВВГЭнг, ВВГЭнг-LS — купить по заявке | Монополия','ВВГЭ, ВВГЭнг, ВВГЭнг-LS: подбор и поставка в Санкт-Петербурге. Укажите марку, число и сечение жил, рабочее напряжение, длину и условия прокладки. Расчет стоимости — по заявке.','site/www.monopoly-torg.ru/125-vvge-vvgeng-vvgeng-ls__836bca464e68c16e78f12044.html','[]','["assets/img/products/VVGE__369cdcc33e1e776600d1363d.jpg"]','["http://www.monopoly-torg.ru/index.php/kabelnaya-produkciya/kabeli-silovye-s-pvkh-izolyatsiej/125-vvge-vvgeng-vvgeng-ls"]') ON DUPLICATE KEY UPDATE `category_id`=VALUES(`category_id`),`root_category`=VALUES(`root_category`),`name`=VALUES(`name`),`slug`=VALUES(`slug`),`sku`=VALUES(`sku`),`short_description`=VALUES(`short_description`),`description_html`=VALUES(`description_html`),`image`=VALUES(`image`),`unit`=VALUES(`unit`),`price`=VALUES(`price`),`request_hint`=VALUES(`request_hint`),`active`=VALUES(`active`),`featured`=VALUES(`featured`),`sort_order`=VALUES(`sort_order`),`seo_title`=VALUES(`seo_title`),`seo_description`=VALUES(`seo_description`),`source_file`=VALUES(`source_file`),`specs_json`=VALUES(`specs_json`),`gallery_json`=VALUES(`gallery_json`),`old_urls_json`=VALUES(`old_urls_json`);
INSERT INTO `products` (`id`,`category_id`,`root_category`,`name`,`slug`,`sku`,`short_description`,`description_html`,`image`,`unit`,`price`,`request_hint`,`active`,`featured`,`sort_order`,`seo_title`,`seo_description`,`source_file`,`specs_json`,`gallery_json`,`old_urls_json`) VALUES (555,16,'cable','ВВГЭнг(А)-FRLSLTx','126-vvgeng-a-frlsltx','MNP-0555','ВВ ГЭнг (А) - FRLSLTx - кабели сило в ые , с медными жилами , не распространяющий горение , с низким дымо - и газо в ыделением , низкой токсичностью продукто в горения, с изоляцией и оболочкой из ПВХ пластиката пониженной пожарной опасности, с.','<div><p>ВВГЭнг(А)-FRLSLTx </p><p><strong>ВВ ГЭнг (А) </strong><strong>- </strong><strong>FRLSLTx </strong>- кабели сило в ые , с медными жилами , не распространяющий горение , с низким дымо - и газо в ыделением , низкой токсичностью продукто в горения, с изоляцией и оболочкой из ПВХ пластиката пониженной пожарной опасности, с термическим барьером из слюдосодержащей ленты по каждой медной токопроводящей жиле, огнестойкий, с общим экраном из медных лент, фольги ил проволок под оболочкой. </p><p><img alt="vvgngls-6kv" loading="lazy" src="assets/img/products/vvgngls-6kv__3cf308a9b439880f1ef2b4b0.jpg"/></p><ol><li>Токопро в одящая жила – медная или алюминие в ая , однопро в олочная или многопро в олочная , круглой или секторной формы , 1 или 2 класса по ГОСТ 22483-77. </li><li>Обмотка – из дв ух слое в слюдосодержащей ленты . </li><li>Изоляция – из ПВХ пластиката пониженной пожарной опасности, изолированные жилы имеют отличительную расцветку. См. общ. тех. хар-ки. </li><li>Скрутка – изолированные жилы многожильных кабелей скручены. </li><li>Внутренняя оболочка – из ПВХ пластиката пониженной пожарной опасности с заполнением между жилами </li><li>Экран – из медных лент. </li><li>Оболочка - из ПВХ пластиката пониженной пожарной опасности. </li></ol><p>Номинальное переменное напряжение силовых кабелей, число и номинальное сечение жил соответствуют указанным в таблице: </p><table><tbody><tr><td rowspan="3"><p>Обозначение марки кабеля </p></td><td rowspan="3"><p>Число жил </p></td><td colspan="2"><p>Номинальное сечение основных жил, мм <sup>2 </sup></p></td></tr><tr><td colspan="2"><p>Номинальное напряжение, кВ </p></td></tr><tr><td><p>0,66 </p></td><td><p>1 </p></td></tr><tr><td rowspan="3"><p>ВВГЭнг(А)-FRLSLTx </p></td><td><p>1 </p></td><td rowspan="3"><p>1,5 - 50 </p></td><td><p>1,5 -1000 </p></td></tr><tr><td><p>3,4 </p></td><td><p>1,5 - 400 </p></td></tr><tr><td><p>2,5 </p></td><td><p>1,5 - 240 </p></td></tr></tbody></table><p><strong>Применение ВВГЭнг(А)-FRLSLTx: </strong><br/></p><p>Кабели <strong>ВВГЭнг(А)-FRLSLTx </strong>предназначены : </p><ul><li>для передачи и распределения электроэнергии и электрических сигнало в в стационарных устано вках, при номинальном переменном напряжении до 1 кВ в ключительно номинальной частотой 50 Гц или при постоянном напряжении до1 ,5 кВ; </li><li>для группо в ой прокладки во взрыв оопасных зонах , в зданиях и сооружениях с массо в ым пребы в анием людей , метрополитено в, объекто в АС в не гермозоны . Огнестойкие – для систем , которые должны сохранять работоспособность при пожаре ; </li><li>для эксплуатации во взрыв оопасных зонах класса В -1а </li><li>Класс пожарной опасности по ГОСТ Р 53315-2009 П1б.1.2.1.2 </li></ul><p><strong>Технические характеристики ВВГЭнг(А)-FRLSLTx: </strong><br/></p><ul><li>Климатическое исполнение УХЛ, категорий размещения 3 и 4 по ГОСТ 15150-69 </li><li>Диапазон температур эксплуатации: от -50°С до +50°С </li><li>Относительная влажность воздуха при температуре до +35 <sup>0 </sup>С до 98% </li><li>Прокладка без предварительного подогрева производится при температуре воздуха не ниже -15 <sup>0 </sup>С </li><li>Наименьший радиус изгиба: </li></ul><p><strong>- </strong>для одножильных кабелей 10 макс. наружных диаметров кабеля; </p><p><strong>- </strong>для многожильных кабелей 7,5 макс. наружных диаметров кабеля; </p><ul><li>Кабели не распространяют горение при группо в ой прокладке по категории А </li><li>Дымообразование при горении и тлении кабелей не приводит к снижению светопроницаемости в испытательной камере более чем на 50%. </li><li>Предельная температура нагрева жил по условию не возгорания кабеля при коротком замыкании не более 400 <sup>0 </sup>С </li><li>Строительная длина кабелей устанавливается при заказе </li><li>Кабели экологически безопасны </li><li>Срок службы – 30 лет с даты изготовления кабелей </li><li>Гарантийный срок эксплуатации 5 лет с даты ввода кабелей в эксплуатацию, но не позднее 6 месяцев с даты изготовления </li></ul><ul><li>Срок хранения: </li></ul><p>- на открытых площадках не более 2 лет; </p><p>- под навесом не более 5 лет; </p><p>- в закрытых помещениях – не более 10 лет. </p></div>','assets/img/products/vvgngls-6kv__3cf308a9b439880f1ef2b4b0.jpg','м',NULL,'Укажите марку, число и сечение жил, рабочее напряжение, длину и условия прокладки.',1,0,555,'ВВГЭнг(А)-FRLSLTx — купить по заявке | Монополия','ВВГЭнг(А)-FRLSLTx: подбор и поставка в Санкт-Петербурге. Укажите марку, число и сечение жил, рабочее напряжение, длину и условия прокладки. Расчет стоимости — по заявке.','site/www.monopoly-torg.ru/126-vvgeng-a-frlsltx__50d89cc6118e4429c5df5c48.html','[["0,66", "1"], ["3,4", "1,5 - 400"], ["2,5", "1,5 - 240"]]','["assets/img/products/vvgngls-6kv__3cf308a9b439880f1ef2b4b0.jpg"]','["http://www.monopoly-torg.ru/index.php/kabelnaya-produkciya/kabeli-silovye-s-pvkh-izolyatsiej/126-vvgeng-a-frlsltx"]') ON DUPLICATE KEY UPDATE `category_id`=VALUES(`category_id`),`root_category`=VALUES(`root_category`),`name`=VALUES(`name`),`slug`=VALUES(`slug`),`sku`=VALUES(`sku`),`short_description`=VALUES(`short_description`),`description_html`=VALUES(`description_html`),`image`=VALUES(`image`),`unit`=VALUES(`unit`),`price`=VALUES(`price`),`request_hint`=VALUES(`request_hint`),`active`=VALUES(`active`),`featured`=VALUES(`featured`),`sort_order`=VALUES(`sort_order`),`seo_title`=VALUES(`seo_title`),`seo_description`=VALUES(`seo_description`),`source_file`=VALUES(`source_file`),`specs_json`=VALUES(`specs_json`),`gallery_json`=VALUES(`gallery_json`),`old_urls_json`=VALUES(`old_urls_json`);
INSERT INTO `products` (`id`,`category_id`,`root_category`,`name`,`slug`,`sku`,`short_description`,`description_html`,`image`,`unit`,`price`,`request_hint`,`active`,`featured`,`sort_order`,`seo_title`,`seo_description`,`source_file`,`specs_json`,`gallery_json`,`old_urls_json`) VALUES (556,16,'cable','ВВГЭнг(А)-LS','127-vvgeng-a-ls','MNP-0556','Кабель не распространяющий горение, с низким дымо- и газовыделением, предназначен для передачи и распределения электроэнергии в стационарных установках на номинальное переменное напряжение 660В и 1000В частоты 50 Гц.','<div><p>ВВГЭнг(А)-LS </p><p>Кабель не распространяющий горение, с низким дымо- и газовыделением, предназначен для передачи и распределения электроэнергии в стационарных установках на номинальное переменное напряжение 660В и 1000В частоты 50 Гц. </p><p><strong>ВВГЭнг(А)-LS </strong>– кабель с медными жилами, в поливинилхлоридной изоляции, в поливинилхлоридной оболочке пониженной горючести, с пониженным дымо- и газовыделением, с экраном из медной ленты, предназначен для прокладки в сухих и влажных помещениях, к которым предъявляются повышенные требования пожарной безопасности, где требуется высокий уровень электрической и механической безопасности, на специальных эстакадах, а так же на открытом воздухе, применяется для передачи и распределения электроэнергии в стационарных установках. Кабель применяется в системе электроснабжения собственных нужд нормальной эксплуатации АЭС и в системе аварийного электроснабжения при прокладке внутри герметичной зоны реакторного отделения. Кабель не рекомендуется прокладывать в земле или траншеях. Кабель не распространяет горение при прокладке в пучках. </p><p><img alt="vvgengLS" loading="lazy" src="assets/img/products/vvgengLS__c67ba22bcdb97f959af780e0.gif"/></p><p><strong>ВВГЭнг(А)-LS </strong>, с нулевой жилой (N) – то же, изоляция нулевой жилы синего цвета. </p><p><strong>ВВГЭнг(А)-LS </strong>, с жилой заземления (PE) – то же, изоляция жилы заземления двухцветная (зелено-желтая). </p><p><strong>ВВГЭнг(А)-LS </strong>, с нулевой жилой и жилой заземления (N,PE) – то же, изоляция нулевой жилы синего цвета, изоляция жилы заземления двухцветная (зелено-желтая). <br/></p><ul><li>Рабочее напряжение - 0,66кВ, 1кВ </li><li>Рабочая температура - От -50°С до +50°С </li><li>Допустимая t° нагрева жил - +70°С - при эксплуатации, +160°С - при коротком замыкании </li></ul><table><tbody><tr><td><strong>Марка </strong></td><td><strong>Число жил </strong></td><td><strong>Сечение жил, мм² </strong></td></tr><tr><td>ВВГЭнг(А)-LS </td><td>1; 2; 3; 4; 5 </td><td>1,5; 2,5; 4,0; 6,0; 10,0; 16,0; 25,0; 35,0; 50,0 </td></tr><tr><td>ВВГЭнг(А)-LS, с нулевой жилой (N) </td><td>1; 2; 4 </td><td>1,5; 2,5; 4,0; 6,0; 10,0; 16,0; 25,0; 35,0; 50,0 </td></tr><tr><td>ВВГЭнг(А)-LS, с жилой заземления (PE) </td><td>1; 4 </td><td>1,5; 2,5; 4,0; 6,0; 10,0; 16,0; 25,0; 35,0; 50,0 </td></tr><tr><td>ВВГЭнг(А)-LS, с нулевой жилой и жилой заземления (N,PE) </td><td>3; 5 </td><td>1,5; 2,5; 4,0; 6,0; 10,0; 16,0; 25,0; 35,0; 50,0 </td></tr></tbody></table></div>','assets/img/products/vvgengLS__c67ba22bcdb97f959af780e0.gif','м',NULL,'Укажите марку, число и сечение жил, рабочее напряжение, длину и условия прокладки.',1,0,556,'ВВГЭнг(А)-LS — купить по заявке | Монополия','ВВГЭнг(А)-LS: подбор и поставка в Санкт-Петербурге. Укажите марку, число и сечение жил, рабочее напряжение, длину и условия прокладки. Расчет стоимости — по заявке.','site/www.monopoly-torg.ru/127-vvgeng-a-ls__763b88776f9d5bdc1013f9f2.html','[]','["assets/img/products/vvgengLS__c67ba22bcdb97f959af780e0.gif"]','["http://www.monopoly-torg.ru/index.php/kabelnaya-produkciya/kabeli-silovye-s-pvkh-izolyatsiej/127-vvgeng-a-ls"]') ON DUPLICATE KEY UPDATE `category_id`=VALUES(`category_id`),`root_category`=VALUES(`root_category`),`name`=VALUES(`name`),`slug`=VALUES(`slug`),`sku`=VALUES(`sku`),`short_description`=VALUES(`short_description`),`description_html`=VALUES(`description_html`),`image`=VALUES(`image`),`unit`=VALUES(`unit`),`price`=VALUES(`price`),`request_hint`=VALUES(`request_hint`),`active`=VALUES(`active`),`featured`=VALUES(`featured`),`sort_order`=VALUES(`sort_order`),`seo_title`=VALUES(`seo_title`),`seo_description`=VALUES(`seo_description`),`source_file`=VALUES(`source_file`),`specs_json`=VALUES(`specs_json`),`gallery_json`=VALUES(`gallery_json`),`old_urls_json`=VALUES(`old_urls_json`);
INSERT INTO `products` (`id`,`category_id`,`root_category`,`name`,`slug`,`sku`,`short_description`,`description_html`,`image`,`unit`,`price`,`request_hint`,`active`,`featured`,`sort_order`,`seo_title`,`seo_description`,`source_file`,`specs_json`,`gallery_json`,`old_urls_json`) VALUES (557,16,'cable','ВВГЭнг(А)-LSLTx','128-vvgeng-a-lsltx','MNP-0557','ВВ ГЭнг (А) - LSLTx - кабели сило в ые , с медными жилами , не распространяющий горение , с низким дымо - и газо в ыделением , низкой токсичностью продукто в горения , с изоляцией и оболочкой из ПВХ пластиката пониженной пожарной опасности , с.','<div><p>ВВГЭнг(А)-LSLTx </p><p><strong>ВВ ГЭнг (А) </strong><strong>- </strong><strong>LSLTx </strong>- кабели сило в ые , с медными жилами , не распространяющий горение , с низким дымо - и газо в ыделением , низкой токсичностью продукто в горения , с изоляцией и оболочкой из ПВХ пластиката пониженной пожарной опасности , с общим экраном из медных лент , фольги или пров олок под оболочкой </p><p><img alt="vvgngls-6kv" loading="lazy" src="assets/img/products/vvgngls-6kv__3cf308a9b439880f1ef2b4b0.jpg"/></p><ol><li>Токопро в одящая жила – медная , однопро в олочная или многопро в олочная , круглой или секторной формы , 1 или 2 класса по ГОСТ 22483-77. </li><li>Изоляция – из ПВХ пластиката пониженной пожарной опасности , изолиро в анные жилы имеют отличительную расц в етку . </li><li>Скрутка – изолиро в анные жилы многожильных кабелей скручены . </li><li>В нутренняя оболочка – из ПВХ пластиката пониженной пожарной опасности с заполнением между жилами . </li><li>Экран – из медных лент . </li><li>Оболочка - из ПВХ пластиката пониженной пожарной опасности . </li></ol><p>Номинальное переменное напряжение сило в ых кабелей , число и номинальное сечение жил соот в етст вуют указанным в таблице : </p><table><tbody><tr><td rowspan="3"><p>Обозначение марки кабеля </p></td><td rowspan="3"><p>Число жил </p></td><td colspan="2"><p>Номинальное сечение осно вных жил, мм <sup>2 </sup></p></td></tr><tr><td colspan="2"><p>Номинальное напряжение , кВ </p></td></tr><tr><td><p>0,66 </p></td><td><p>1 </p></td></tr><tr><td rowspan="3"><p>ВВ ГЭнг (А) -LSLTx </p></td><td><p>1 </p></td><td rowspan="3"><p>1,5 - 50 </p></td><td><p>1,5 -1000 </p></td></tr><tr><td><p>3,4 </p></td><td><p>1,5 - 400 </p></td></tr><tr><td><p>2,5 </p></td><td><p>1,5 - 240 </p></td></tr></tbody></table><p><strong>Применение ВВГЭнг(А)-LSLTx: </strong><br/></p><p>Кабели <strong>ВВГЭнг(А)-LSLTx </strong>предназначены : </p><ul><li>для передачи и распределения электроэнергии и электрических сигнало в в стационарных устано вках, при номинальном переменном напряжении до 1 кВ в ключительно номинальной частотой 50 Гц или при постоянном напряжении до1 ,5 кВ; </li><li>для группо в ой прокладки во взрыв оопасных зонах , в зданиях и сооружениях с массо в ым пребы в анием людей , метрополитенов, объектов АС в не гермозоны. Огнестойкие – для систем, которые должны сохранять работоспособность при пожаре; </li><li>для эксплуатации во взрыв оопасных зонах класса В-1а </li><li>Класс пожарной опасности по ГОСТ Р 53315-2009 П1б.8.2.1.2 </li></ul><p><strong>Технические характеристики ВВГЭнг(А)-LSLTx: </strong><br/></p><ul><li>Климатическое исполнение УХЛ, категорий размещения 3 и 4 по ГОСТ 15150-69 </li><li>Диапазон температур эксплуатации : от -50°С до +50°С </li><li>Относительная влажность воздуха при температуре до +35 <sup>0 </sup>С до 98% </li><li>Прокладка без предварительного подогрева производится при температуре воздуха не ниже -15 <sup>0 </sup>С </li><li>Наименьший радиус изгиба: </li></ul><p><strong>- </strong>для одножильных кабелей 10 макс. наружных диаметров кабеля ; </p><p><strong>- </strong>для многожильных кабелей 7,5 макс. наружных диаметров кабеля ; </p><ul><li>Кабели не распространяют горение при группо в ой прокладке по категории А </li><li>Дымообразование при горении и тлении кабелей не приводит к снижению светопроницаемости в испытательной камере более чем на 50%. </li><li>Предельная температура нагрева жил по условию не возгорания кабеля при коротком замыкании не более 350 <sup>0 </sup>С </li><li>Строительная длина кабелей устанавливается при заказе </li><li>Кабели <strong>ВВГЭнг(А)-LSLTx </strong>экологически безопасны </li><li>Срок службы – 30 лет с даты изготовления кабелей </li><li>Гарантийный срок эксплуатации 5 лет с даты ввода кабелей в эксплуатацию, но не позднее 6 месяцев с даты изготовления </li><li>Срок хранения: </li></ul><p>- на открытых площадках не более 2 лет; </p><p>- под навесом не более 5 лет; </p><p>- в закрытых помещениях – не более 10 лет. </p></div>','assets/img/products/vvgngls-6kv__3cf308a9b439880f1ef2b4b0.jpg','м',NULL,'Укажите марку, число и сечение жил, рабочее напряжение, длину и условия прокладки.',1,0,557,'ВВГЭнг(А)-LSLTx — купить по заявке | Монополия','ВВГЭнг(А)-LSLTx: подбор и поставка в Санкт-Петербурге. Укажите марку, число и сечение жил, рабочее напряжение, длину и условия прокладки. Расчет стоимости — по заявке.','site/www.monopoly-torg.ru/128-vvgeng-a-lsltx__9c0f7709ec04d3895475305c.html','[["0,66", "1"], ["3,4", "1,5 - 400"], ["2,5", "1,5 - 240"]]','["assets/img/products/vvgngls-6kv__3cf308a9b439880f1ef2b4b0.jpg"]','["http://www.monopoly-torg.ru/index.php/kabelnaya-produkciya/kabeli-silovye-s-pvkh-izolyatsiej/128-vvgeng-a-lsltx"]') ON DUPLICATE KEY UPDATE `category_id`=VALUES(`category_id`),`root_category`=VALUES(`root_category`),`name`=VALUES(`name`),`slug`=VALUES(`slug`),`sku`=VALUES(`sku`),`short_description`=VALUES(`short_description`),`description_html`=VALUES(`description_html`),`image`=VALUES(`image`),`unit`=VALUES(`unit`),`price`=VALUES(`price`),`request_hint`=VALUES(`request_hint`),`active`=VALUES(`active`),`featured`=VALUES(`featured`),`sort_order`=VALUES(`sort_order`),`seo_title`=VALUES(`seo_title`),`seo_description`=VALUES(`seo_description`),`source_file`=VALUES(`source_file`),`specs_json`=VALUES(`specs_json`),`gallery_json`=VALUES(`gallery_json`),`old_urls_json`=VALUES(`old_urls_json`);
INSERT INTO `products` (`id`,`category_id`,`root_category`,`name`,`slug`,`sku`,`short_description`,`description_html`,`image`,`unit`,`price`,`request_hint`,`active`,`featured`,`sort_order`,`seo_title`,`seo_description`,`source_file`,`specs_json`,`gallery_json`,`old_urls_json`) VALUES (558,16,'cable','ВВГЭнг-FRLS','129-vvgeng-frls','MNP-0558','ВВГЭнг-FRLS для промышленных, строительных и энергетических объектов.','<div><p>ВВГЭнг-FRLS </p><p><img alt="vvgengfrls" loading="lazy" src="assets/img/products/vvgengfrls__7f67df12cb9406f4f27e1085.jpg"/></p><div><strong>Область применения ВВГЭнг-FRLS-1: </strong></div><div>Силовые кабели <strong>ВВГЭнг-FRLS </strong>, огнестойкие, не распространяющие горение, с низким дымо- и газовыделением. Предназначены для передачи и распределения электроэнергии и электрических сигналов в стационарных электротехнических установках при переменном напряжении до 1000 В частотой до 100 Гц и постоянном напряжении до 1000 В. </div><div>Кабели <strong>ВВГЭнг-FRLS </strong>изготовляются для общепромышленного применения и применения в системах АС вне гермозоны и в системах АС класса 2 по классификации ОПБ 88/97 (ПНАЭ Г-01-011). </div><div>Климатическое исполнение В, категории размещения 5 по ГОСТ 15150-69. </div><p><strong>Технические характеристики ВВГЭнг-FRLS-1 </strong><br/><br/></p><table><tbody><tr><td>Влажность воздуха при 35° C [%] </td><td><strong>98 </strong></td></tr><tr><td>Испытательное переменное напряжение частотой 50 Гц, 10 мин. [кВ] </td><td><strong>3,5 </strong></td></tr><tr><td>Максимальная рабочая температура жилы [°С] </td><td><strong>70 </strong></td></tr><tr><td>Максимальное переменное напряжение частоты 50 Гц [кВ] </td><td><strong>1,2 </strong></td></tr><tr><td>Монтаж при температуре, не ниже [°C] </td><td><strong>-15 </strong></td></tr><tr><td>Номинальное переменное напряжение частотой 50 Гц [кВ] </td><td><strong>1 </strong></td></tr><tr><td>Радиус изгиба кабелей [наружных диаметров] </td><td><strong>10 </strong></td></tr><tr