INSERT INTO `products` (`id`,`category_id`,`root_category`,`name`,`slug`,`sku`,`short_description`,`description_html`,`image`,`unit`,`price`,`request_hint`,`active`,`featured`,`sort_order`,`seo_title`,`seo_description`,`source_file`,`specs_json`,`gallery_json`,`old_urls_json`) VALUES (644,17,'cable','Термоэлектродные кабели КМТВ, КМТВнг, КМТВТ, КМТВТнг','743-termoelektrodnye-kabeli-kmtv-kmtvng-kmtvt-kmtvtng','MNP-0644','Термоэлектродные кабели предназначены для прокладки под навесом или в помещениях, где отсутствует прямое воздействие солнечного излучения и атмосферных осадков, при температуре эксплуатации от -40 до +70 o С. Не рекомендуется прокладка в земле.','<div><p>Термоэлектродные кабели КМТВ, КМТВнг, КМТВТ, КМТВТнг </p><p><strong>КМТВ (М, ХА, ХК) </strong><br/>Кабель термоэлектродный многопроволочный с температурой эксплуатации от -40 до +70° С, с изолированными токоведущими жилами из меди и сплава (М) или пары сплавов (ХА, ХК), в защитной оболочке из ПВХ пластиката <strong>КМТВнг (М, ХА, ХК) негорючий </strong><br/>Кабель термоэлектродный многопроволочный с температурой эксплуатации от -40 до +70° С, с изолированными токоведущими жилами из меди и сплава (М) или пары сплавов (ХА, ХК), в защитной оболочке из ПВХ пластиката пониженной горючести <strong>КМТВТ (М, ХА, ХК) теплостойкий </strong><br/>Кабель термоэлектродный многопроволочный с температурой эксплуатации от -40 до +105° С, с изолированными токоведущими жилами из меди и сплава (М) или пары сплавов (ХА, ХК), в защитной оболочке из теплостойкого ПВХ пластиката <br/><strong><br/>КМТВТнг (М, ХА, ХК) теплостойкий негорючий </strong><br/>Кабель термоэлектродный многопроволочный с температурой эксплуатации от -40 до +105° С, с изолированными токоведущими жилами из меди и сплава (М) или пары сплавов (ХА, ХК), в защитной оболочке из ПВХ пластиката пониженной гоючести </p><h3>МАРКОРАЗМЕРЫ </h3><table><tbody><tr><td><p>Число жил и номинальное сечение, мм <sup>2 </sup></p></td><td><p>Условное обозначение токопроводящей жилы </p></td><td><p>Наружный диаметр, мм </p></td></tr><tr><td><p>4х1,0 </p></td><td rowspan="13"><p>ХК </p><p>ХА </p><p>М </p></td><td><p>7,64 </p></td></tr><tr><td><p>6х1,0 </p></td><td><p>8,99 </p></td></tr><tr><td><p>8х1,0 </p></td><td><p>10,04 </p></td></tr><tr><td><p>10х1,0 </p></td><td><p>11,32 </p></td></tr><tr><td><p>12х1,0 </p></td><td><p>11,69 </p></td></tr><tr><td><p>14х1,0 </p></td><td><p>12,28 </p></td></tr><tr><td><p>16х1,0 </p></td><td><p>12,95 </p></td></tr><tr><td><p>18х1,0 </p></td><td><p>13,65 </p></td></tr><tr><td><p>20х1,0 </p></td><td><p>14,42 </p></td></tr><tr><td><p>22х1,0 </p></td><td><p>15,21 </p></td></tr><tr><td><p>24х1,0 </p></td><td><p>15,98 </p></td></tr><tr><td><p>26х1,0 </p></td><td><p>16,0 </p></td></tr><tr><td><p>28х1,0 </p></td><td><p>16,94 </p></td></tr><tr><td><p>4х1,5 </p></td><td rowspan="13"><p>ХК </p><p>ХА </p><p>М </p></td><td><p>8,27 </p></td></tr><tr><td><p>6х1,5 </p></td><td><p>9,74 </p></td></tr><tr><td><p>8х1,5 </p></td><td><p>10,94 </p></td></tr><tr><td><p>10х1,5 </p></td><td><p>12,36 </p></td></tr><tr><td><p>12х1,5 </p></td><td><p>12,77 </p></td></tr><tr><td><p>14х1,5 </p></td><td><p>13,42 </p></td></tr><tr><td><p>16х1,5 </p></td><td><p>14,17 </p></td></tr><tr><td><p>18х1,5 </p></td><td><p>14,95 </p></td></tr><tr><td><p>20х1,5 </p></td><td><p>15,8 </p></td></tr><tr><td><p>22х1,5 </p></td><td><p>16,69 </p></td></tr><tr><td><p>24х1,5 </p></td><td><p>17,54 </p></td></tr><tr><td><p>26х1,5 </p></td><td><p>17,6 </p></td></tr><tr><td><p>28х1,5 </p></td><td><p>18,6 </p></td></tr><tr><td><p>4х2,5 </p></td><td rowspan="13"><p>ХК </p><p>ХА </p><p>М </p></td><td><p>9,16 </p></td></tr><tr><td><p>6х2,5 </p></td><td><p>10,88 </p></td></tr><tr><td><p>8х2,5 </p></td><td><p>12,21 </p></td></tr><tr><td><p>10х2,5 </p></td><td><p>13,84 </p></td></tr><tr><td><p>12х2,5 </p></td><td><p>14,31 </p></td></tr><tr><td><p>14х2,5 </p></td><td><p>15,05 </p></td></tr><tr><td><p>16х2,5 </p></td><td><p>15,91 </p></td></tr><tr><td><p>18х2,5 </p