INSERT INTO `products` (`id`,`category_id`,`root_category`,`name`,`slug`,`sku`,`short_description`,`description_html`,`image`,`unit`,`price`,`request_hint`,`active`,`featured`,`sort_order`,`seo_title`,`seo_description`,`source_file`,`specs_json`,`gallery_json`,`old_urls_json`) VALUES (645,17,'cable','Термоэлектродные кабели с экраном КМТВЭВ, КМТВЭВнг, КМТВЭВТ, КМТВЭВТнг','744-termoelektrodnye-kabeli-s-ekranom-kmtvev-kmtvevng-kmtvevt-kmtvevtng','MNP-0645','Термоэлектродные кабели с экраном КМТВЭВ, КМТВЭВнг, КМТВЭВТ, КМТВЭВТнг для промышленных, строительных и энергетических объектов.','<div><p>Термоэлектродные кабели с экраном КМТВЭВ, КМТВЭВнг, КМТВЭВТ, КМТВЭВТнг </p><p><strong>КМТВЭВ (М, ХА, ХК) </strong><br/>Кабель термоэлектродный многопроволочный с температурой эксплуатации от -40 до +70° С, с изолированными токоведущими жилами из меди и сплава (М) или пары сплавов (ХА, ХК), с поясной изоляцией и экраном из алюмофлекса, в защитной оболочке из ПВХ пластиката </p><p><strong>КМТВЭВнг (М, ХА, ХК) негорючий </strong><br/>Кабель термоэлектродный многопроволочный с температурой эксплуатации от -40 до +70° С, с изолированными токоведущими жилами из меди и сплава (М) или пары сплавов (ХА, ХК), с поясной изоляцией и экраном из алюмофлекса, в защитной оболочке из ПВХ пластиката пониженной горючести </p><p><strong>КМТВЭВТ (М, ХА, ХК) теплостойкий </strong><br/>Кабель термоэлектродный многопроволочный с температурой эксплуатации от -40 до +105° С, с изолированными токоведущими жилами из меди и сплава (М) или пары сплавов (ХА, ХК), с поясной изоляцией и экраном из алюмофлекса, в защитной оболочке из теплостойкого ПВХ пластиката </p><p><strong>КМТВЭВТнг (М, ХА, ХК) теплостойкий негорючий </strong><br/>Кабель термоэлектродный многопроволочный с температурой эксплуатации от -40 до +105° С, с изолированными токоведущими жилами из меди и сплава (М) или пары сплавов (ХА, ХК), с поясной изоляцией и экраном из алюмофлекса, в защитной оболочке из ПВХ пластиката пониженной горючести </p>