INSERT INTO `products` (`id`,`category_id`,`root_category`,`name`,`slug`,`sku`,`short_description`,`description_html`,`image`,`unit`,`price`,`request_hint`,`active`,`featured`,`sort_order`,`seo_title`,`seo_description`,`source_file`,`specs_json`,`gallery_json`,`old_urls_json`) VALUES (656,18,'cable','КМПвЭВнг(А)-FRLS','595-kmpvevng-a-frls','MNP-0656','(индекс FR в марках кабелей означает огнестойкость (Fire Resistance), индекс LS в марках означает низкое дымо- и газовыделение (Low Smoke)) (индекс (А) в марках означает, что кабель соответствует категории А по нераспространению горения по ГОСТ Р.','<div><p>КМПвЭВнг(А)-FRLS </p><p>(индекс FR в марках кабелей означает огнестойкость (Fire Resistance), <br/>индекс LS в марках означает низкое дымо- и газовыделение (Low Smoke)) <br/>(индекс (А) в марках означает, что кабель соответствует категории А по нераспространению горения по ГОСТ Р МЭК 332-3-96) </p><p>Кабели <strong>КМПвЭВнг(А)-FRLS </strong>малогабаритные огнестойкие не распространяющие горение, с низким дымо- и газовыделением, предназначены для передачи и распределения электрической энергии и электрических сигналов в стационарных электротехнических установках при переменном напряжении до 1000В частотой до 100 Гц и постоянным напряжением до 1000 В. Кабели изготавливаются для общепромышленного применения и на атомных станциях (АС) вне гермозоны в системах АС класса 2 по классификации ОПБ 88/97. Климатическое исполнение В, категория размещения 5 по ГОСТ 15150-69. </p><p><img alt="kgns" loading="lazy" src="assets/img/products/kmpvevngfrls__fd5a523789db04dc2854fff6.jpg"/></p><p><strong>Конструкция КМПвЭВнг(А)-FRLS: </strong></p><ol><li>Жила - медные проволоки. </li><li>Термический барьер. </li><li>Изоляция - сшитый полиэтилен </li><li>Экран - обмотка из медных проволок. </li><li>Термический барьер. </li><li>Оболочки - ПВХ пластикат пониженной пожароопасности </li></ol><p>Кабели <strong>КМПвЭВнг(А)-FRLS </strong>предназначены для прокладки в кабельных сооружениях и помещениях, в том числе во взрывоопасных зонах всех классов, кроме взрывоопасных зон класса В-1. </p><p><strong>Технические и эксплуатационные характеристики КМПвЭВнг(А)-FRLS </strong></p><p>Электрическая безопасность - ГОСТ 12.2.007.14-75. </p><p>Нераспространение горения - ГОСТ Р12176-89 (ГОСТ Р МЭК 332-3-96) категория А. </p><table><tbody><tr><td>Температура окружающей среды при эксплуатации </td><td>от +50 <sup>0 </sup>С до -30 <sup>0 </sup>С </td></tr><tr><td>Относительная влажность воздуха (при t <sup>0 </sup>+35 <sup>0 </sup>С) </td><td>98% </td></tr><tr><td>Длительно допустимая t <sup>0 </sup>нагрева жил при эксплуатации </td><td>+90 <sup>0 </sup>С </td></tr><tr><td>Максимально допустимая t <sup>0 </sup>жил при коротком замыкании (4 сек.) </td><td>+250 <sup>0 </sup>С </td></tr><tr><td>Минимальная t <sup>0 </sup>прокладки кабеля без предварительного подогрева </td><td>- 15 <sup>0 </sup>С </td></tr><tr><td>Предельная температура токопроводящих жил кабелей по условию невозгорания кабеля при коротком замыкании </td><td>+400 <sup>0 </sup>С </td></tr><tr><td>Снижение светопроницаемости при горении и тлении </td><td>не более 40%. </td></tr><tr><td>Огнестойкость кабелей не менее: </td><td>90 мин. </td></tr><tr><td>Минимально допустимый радиус изгиба при прокладке </td><td>3 диам. кабеля </td></tr><tr><td>Срок службы </td><td>30 лет </td></tr><tr><td>Гарантийный срок эксплуатации </td><td>3 года </td></tr></tbody></table><p><br/>Кабели не являются опасными в экологическом отношении и специальных требований по утилизации кабелей при выводе их эксплуатации, кроме предусмотренных в действующей на АС документации, не предъявляется. </p><p><strong>Кабели соответствуют требованиям ТУ 16.К71-337-2004 </strong></p><table><tbody><tr><td colspan="1"><strong>Число жил, сечение, мм <sup>2 </sup></strong></td><td colspan="1"><strong>Номинальный наружный диаметр, мм </strong></td><td colspan="1"><strong>Расчетная масса, кг/км </strong></td></tr><tr><td>КМПвЭВнг(А)-FRLS 2 х0,35 </td><td