INSERT INTO `products` (`id`,`category_id`,`root_category`,`name`,`slug`,`sku`,`short_description`,`description_html`,`image`,`unit`,`price`,`request_hint`,`active`,`featured`,`sort_order`,`seo_title`,`seo_description`,`source_file`,`specs_json`,`gallery_json`,`old_urls_json`) VALUES (657,18,'cable','КМПВЭВнг-LS','596-kmpvevng-ls','MNP-0657','(индекс LS в марках означает низкое дымо- и газовыделение (Low Smoke))','<div><p>КМПВЭВнг-LS </p><p>(индекс LS в марках означает низкое дымо- и газовыделение (Low Smoke)) </p><p>Кабели малогабаритные <strong>КМПВЭВнг-LS </strong>не распространяющие горение, с низким дымо- и газовыделением, предназначены для передачи и распределения электрической энергии и электрических сигналов в стационарных установках при переменном и постоянном напряжении до 1000В. Климатическое исполнение УХЛ и Т, категория размещения 5 по ГОСТ 15150-69. </p><p><img alt="kgns" loading="lazy" src="assets/img/products/kmpvevngls__c9627e1ae8c7dce9c5d837de.jpg"/></p><p><strong>Конструкция КМПВЭВнг-LS: </strong></p><ol><li>Токопроводящая жила - медные проволоки. </li><li>Изоляция - полиэтилен. </li><li>Экран - оплетка из медных проволок. </li><li>Оболочка - ПВХ композиция пониженной пожароопасности. </li></ol><p>Кабели предназначены для эксплуатации в кабельных сооружениях и помещениях, в том числе в системах АС классов 2,3 и 4 по классификации ОПБ-88/97 </p><p><strong>Технические и эксплуатационные характеристики КМПВЭВнг-LS </strong></p><p>Электрическая безопасность - ГОСТ 12.2.007.14-75. </p><p>Нераспространение горения - ГОСТ Р12176-89 (ГОСТ Р МЭК 332-3-96) категория А. </p><table><tbody><tr><td>Температура окружающей среды при эксплуатации </td><td>от +50 <sup>0 </sup>С до -50 <sup>0 </sup>С </td></tr><tr><td>Относительная влажность воздуха (при t <sup>0 </sup>+35 <sup>0 </sup>С) </td><td>98% </td></tr><tr><td>Предельно допустимая t <sup>0 </sup>нагрева жил при эксплуатации </td><td>+70 <sup>0 </sup>С </td></tr><tr><td>Минимальная t <sup>0 </sup>прокладки кабеля без предварительного подогрева </td><td>- 15 <sup>0 </sup>С </td></tr><tr><td>Предельная температура токопроводящих жил кабелей по условию невозгорания кабеля при коротком замыкании </td><td>+400 <sup>0 </sup>С </td></tr><tr><td>Снижение светопроницаемости при горении и тлении </td><td>не более 40%. </td></tr><tr><td>Минимально допустимый радиус изгиба при прокладке </td><td>3 диам. кабеля </td></tr><tr><td>Срок службы </td><td>30 лет </td></tr><tr><td>Гарантийный срок эксплуатации </td><td>3 года </td></tr></tbody></table><p>Кабели не являются опасными в экологическом отношении и специальных требований по утилизации кабелей при выводе их эксплуатации, кроме предусмотренных в действующей на АС документации, не предъявляется. </p><p><strong>Кабели КМПВЭВнг-LS соответствуют требованиям ТУ 16.К71-310-2001 </strong></p><table><tbody><tr><td colspan="1"><strong>Число жил, сечение, мм <sup>2 </sup></strong></td><td colspan="1"><strong>Номинальный наружный диаметр, мм <br/></strong></td><td colspan="1"><strong>Расчетная масса, кг/км </strong></td></tr><tr><td>КМПВЭВнг-LS 2 х0,35 </td><td>8,8 </td><td>126 </td></tr><tr><td>КМПВЭВнг-LS 3 х0,35 </td><td>9 </td><td>134 </td></tr><tr><td>КМПВЭВнг-LS 4 х0,35 </td><td>9,4 </td><td>146 </td></tr><tr><td>КМПВЭВнг-LS 7 х0,35 </td><td>10,3 </td><td>178 </td></tr><tr><td>КМПВЭВнг-LS 10 х0,35 </td><td>12 </td><td>222 </td></tr><tr><td>КМПВЭВнг-LS 12 х0,35 </td><td>12,2 </td><td>237 </td></tr><tr><td>КМПВЭВнг-LS 14 х0,35 </td><td>12,6 </td><td>255 </td></tr><tr><td>КМПВЭВнг-LS 19 х0,35 </td><td>13,9 </td><td>335 </td></tr><tr><td>КМПВЭВнг-LS 24 х0,35 </td><td>16,1 </td><td>418 </td></tr><tr><td>КМПВЭВнг-LS 27 х0,35 </td><td>16,4 </td><td>440 </td></tr><tr><td>КМПВЭВнг-LS 30 х0,35 </td><td>16,8 </td><td>469 </td></tr><tr><td>КМПВЭВнг-LS 37 х0,35 </td><td>18,3 </td><td>550 </td></tr><tr><td>КМПВЭВнг-LS 52 х0,35 </td><td>20,5 </td><td>682 </td></tr><tr><td>КМПВЭВнг-LS 2 х0,5 </td><td>9 </td><td>134 </td></tr><tr><td>КМПВЭВнг-LS 3 х0,