INSERT INTO `products` (`id`,`category_id`,`root_category`,`name`,`slug`,`sku`,`short_description`,`description_html`,`image`,`unit`,`price`,`request_hint`,`active`,`featured`,`sort_order`,`seo_title`,`seo_description`,`source_file`,`specs_json`,`gallery_json`,`old_urls_json`) VALUES (659,18,'cable','КМПЭВ','598-kmpev','MNP-0659','Малогабаритные кабели КМПЭВ предназначены для неподвижной прокладки монтажа цепей управления, сигнализации, связи, межприборных соединений, в том числе на судах морского флота неограниченного района плавания, речного флота, береговых плавучих.','<div><p>КМПЭВ </p><p>Малогабаритные кабели <strong>КМПЭВ </strong>предназначены для неподвижной прокладки монтажа цепей управления, сигнализации, связи, межприборных соединений, в том числе на судах морского флота неограниченного района плавания, речного флота, береговых плавучих сооружениях, работающих при номинальных переменных напряжениях 500 и 1000В частоты не более 200 кГц или соответственно при постоянных 750 и 1500 В. Климатическое исполнение В по ГОСТ В 20.39.404-81. </p><p><img alt="kgns" loading="lazy" src="assets/img/products/kmpev__6c569da8b1cdc2cde5628091.jpg"/></p><p><strong>Конструкция КМПЭВ : </strong></p><ol><li>Токопроводящая жила - медные проволоки. </li><li>Изоляция - полиэтилен </li><li>Экран - оплетка из медных проволок </li><li>Оболочка - ПВХ пластикат </li></ol><p><strong>Технические и эксплуатационные характеристики КМПЭВ </strong></p><table><tbody><tr><td>Температура окружающей среды при эксплуатации </td><td>от +65 <sup>0 </sup>С до -50 <sup>0 </sup>С </td></tr><tr><td>Относительная влажность воздуха (при t <sup>0 </sup>+35 <sup>0 </sup>С) </td><td>98% </td></tr><tr><td>Длительно допустимая t <sup>0 </sup>нагрева жил при эксплуатации </td><td>+70 <sup>0 </sup>С </td></tr><tr><td>Минимальная t <sup>0 </sup>прокладки кабеля без предварительного подогрева </td><td>- 15 <sup>0 </sup>С </td></tr><tr><td>Минимально допустимый радиус изгиба при прокладке: </td><td>3 диам. кабеля </td></tr><tr><td>Срок службы </td><td>23 года </td></tr><tr><td>Гарантийный срок эксплуатации </td><td>23 года </td></tr></tbody></table><p><br/>Кабели стойки к синусоидальной вибрации, акустическому шуму, механическим ударам одиночного и многократного действия, линейному ускорению, повышенному атмосферному давлению, соляному туману, плесневым грибам и статической пыли. </p><p>Кабели при эксплуатации в цепях управления и сигнализации. Межприборных соединений, в силовых и осветительных сетях, при неподвижной прокладке должны быть защищены от прямого воздействия солнечной радиации и механических повреждений. </p><p><strong>Кабели КМПЭВ соответствуют требованиям ТУ 16-705.169-80 </strong></p><table><tbody><tr><td colspan="1"><strong>Число жил, сечение, мм <sup>2 </sup></strong></td><td colspan="1"><strong>Номинальный диаметр, мм </strong></td><td colspan="1"><strong>Расчетная масса, кг/км </strong></td></tr><tr><td>КМПЭВ 2 х0,35 </td><td>6,4 </td><td>46,7 </td></tr><tr><td>КМПЭВ 3 х0,35 </td><td>6,7 </td><td>58,2 </td></tr><tr><td>КМПЭВ 4 х0,35 </td><td>7,2 </td><td>70,9 </td></tr><tr><td>КМПЭВ 7 х0,35 </td><td>8,4 </td><td>106,9 </td></tr><tr><td>КМПЭВ 12 х0,35 </td><td>11,3 </td><td>183,1 </td></tr><tr><td>КМПЭВ 14 х0,35 </td><td>11,8 </td><td>206,6 </td></tr><tr><td>КМПЭВ 19 х0,35 </td><td>13 </td><td>264 </td></tr><tr><td>КМПЭВ 24 х0,35 </td><td>15 </td><td>327 </td></tr><tr><td>КМПЭВ 27 х0,35 </td><td>15,3 </td><td>359,6 </td></tr><tr><td>КМПЭВ 37 х0,35 </td><td>17 </td><td>471,1 </td></tr><tr><td>КМПЭВ 52 х0,35 </td><td>20,4 </td><td>665 </td></tr><tr><td>КМПЭВ 2 х0,5 </td><td>6,6 </td><td>50,6 </td></tr><tr><td>КМПЭВ 3 х0,5 </td><td>7 </td><td>63,6 </td></tr><tr><td>КМПЭВ 4 х0,5 </td><td>7,5 </td><td>77,7 </td></tr><tr><td>КМПЭВ 7 х0,5 </td><td>8,7 </td><td>117,9 </td></tr><tr><td>КМПЭВ 12 х0,5 </td><td>11,8 </td><td>202,3 </td></tr><tr><td>КМПЭВ 14 х0,5 </td><td>12,3 </td><td>228,4 </td></tr><tr><td>КМПЭВ 19 х0,5 </td><td>13,6 </td><td>292,9 </td></tr><tr><td