INSERT INTO `products` (`id`,`category_id`,`root_category`,`name`,`slug`,`sku`,`short_description`,`description_html`,`image`,`unit`,`price`,`request_hint`,`active`,`featured`,`sort_order`,`seo_title`,`seo_description`,`source_file`,`specs_json`,`gallery_json`,`old_urls_json`) VALUES (662,18,'cable','КМПЭВЭВнг-LS','601-kmpevevng-ls','MNP-0662','(индекс LS в марках означает низкое дымо- и газовыделение (Low Smoke))','<div><p>КМПЭВЭВнг-LS </p><p>(индекс LS в марках означает низкое дымо- и газовыделение (Low Smoke)) </p><p>Кабели малогабаритные <strong>КМПЭВЭВнг-LS </strong>не распространяющие горение, с низким дымо- и газовыделением, предназначены для передачи и распределения электрической энергии и электрических сигналов в стационарных установках при переменном и постоянном напряжении до 1000В. Климатическое исполнение УХЛ и Т, категория размещения 5 по ГОСТ 15150-69 </p><p><img alt="kgns" loading="lazy" src="assets/img/products/kmpevevngls__fb049f9fe52aa891879b95e8.jpg"/></p><p><strong>Конструкция КМПЭВЭВнг-LS: </strong></p><ol><li>Токопроводящая жила - медные проволоки. </li><li>Изоляция - полиэтилен. </li><li>Экран - оплетка из медных проволок. </li><li>Оболочка - ПВХ композиция пониженной пожароопасности. </li></ol><p>Кабели предназначены для эксплуатации в кабельных сооружениях и помещениях, в том числе в системах АС классов 2,3 и 4 по классификации ОПБ-88/97 </p><p><strong>Технические и эксплуатационные характеристики КМПЭВЭВнг-LS </strong></p><p>Электрическая безопасность - ГОСТ 12.2.007.14-75. </p><p>Нераспространение горения - ГОСТ Р12176-89 (ГОСТ Р МЭК 332-3-96) категория А. <br/></p><table><tbody><tr><td>Температура окружающей среды при эксплуатации </td><td>от +50 <sup>0 </sup>С до -50 <sup>0 </sup>С </td></tr><tr><td>Относительная влажность воздуха (при t <sup>0 </sup>+35 <sup>0 </sup>С) </td><td>98% </td></tr><tr><td>Предельно допустимая t <sup>0 </sup>нагрева жил при эксплуатации </td><td>+70 <sup>0 </sup>С </td></tr><tr><td>Минимальная t <sup>0 </sup>прокладки кабеля без предварительного подогрева </td><td>- 15 <sup>0 </sup>С </td></tr><tr><td>Предельная температура токопроводящих жил кабелей по условию невозгорания кабеля при коротком замыкании </td><td>+400 <sup>0 </sup>С </td></tr><tr><td>Снижение светопроницаемости при горении и тлении </td><td>не более 40%. </td></tr><tr><td>Минимально допустимый радиус изгиба при прокладке </td><td>3 диам. кабеля </td></tr><tr><td>Срок службы </td><td>30 лет </td></tr><tr><td>Гарантийный срок эксплуатации </td><td>3 года </td></tr></tbody></table><p>Кабели не являются опасными в экологическом отношении и специальных требований по утилизации кабелей при выводе их эксплуатации, кроме предусмотренных в действующей на АС документации, не предъявляется. </p><p><strong>Кабели КМПЭВЭВнг-LS соответствуют требованиям ТУ 16.К71-310-2001 </strong></p><table><tbody><tr><td><strong>Число жил, сечение, мм <sup>2 </sup></strong></td><td><strong>Номинальный наружный диаметр, мм </strong></td><td><strong>Расчетная масса, кг/км </strong></td></tr><tr><td>КМПЭВЭВнг-LS 2 х0,35 </td><td>9,6 </td><td>147 </td></tr><tr><td>КМПЭВЭВнг-LS 3 х0,35 </td><td>9,9 </td><td>161 </td></tr><tr><td>КМПЭВЭВнг-LS 4 х0,35 </td><td>10,4 </td><td>179 </td></tr><tr><td>КМПЭВЭВнг-LS 7 х0,35 </td><td>11,6 </td><td>232 </td></tr><tr><td>КМПЭВЭВнг-LS 12 х0,35 </td><td>14,9 </td><td>386 </td></tr><tr><td>КМПЭВЭВнг-LS 14 х0,35 </td><td>15,4 </td><td>417 </td></tr><tr><td>КМПЭВЭВнг-LS 19 х0,35 </td><td>16,6 </td><td>493 </td></tr><tr><td>КМПЭВЭВнг-LS 24 х0,35 </td><td>19,2 </td><td>621 </td></tr><tr><td>КМПЭВЭВнг-LS 27 х0,35 </td><td>19,5 </td><td>658 </td></tr><tr><td>КМПЭВЭВнг-LS 37 х0,35 </td><td>21,2 </td><td>800 </td></tr><tr><td>КМПЭВЭВнг-LS 52 х0,35 </td><td>24,6 </td><td>1059 </td></tr><tr><td>КМПЭВЭВнг-LS 2 х0,5 </td><td>9,8 </td><td>153 </td></tr><tr><td>КМПЭВЭВнг-LS 3 х0,5 </td><td>10,2 </td><td>170 </td></tr><tr><td>КМПЭВЭВнг-LS 4 х0,5 </td><td>10,7 </td><td>190 </td></tr><tr><td>КМПЭВЭВнг-LS 7 х0,5 </td><td