ALUES(`root_category`),`name`=VALUES(`name`),`slug`=VALUES(`slug`),`sku`=VALUES(`sku`),`short_description`=VALUES(`short_description`),`description_html`=VALUES(`description_html`),`image`=VALUES(`image`),`unit`=VALUES(`unit`),`price`=VALUES(`price`),`request_hint`=VALUES(`request_hint`),`active`=VALUES(`active`),`featured`=VALUES(`featured`),`sort_order`=VALUES(`sort_order`),`seo_title`=VALUES(`seo_title`),`seo_description`=VALUES(`seo_description`),`source_file`=VALUES(`source_file`),`specs_json`=VALUES(`specs_json`),`gallery_json`=VALUES(`gallery_json`),`old_urls_json`=VALUES(`old_urls_json`);
INSERT INTO `products` (`id`,`category_id`,`root_category`,`name`,`slug`,`sku`,`short_description`,`description_html`,`image`,`unit`,`price`,`request_hint`,`active`,`featured`,`sort_order`,`seo_title`,`seo_description`,`source_file`,`specs_json`,`gallery_json`,`old_urls_json`) VALUES (663,18,'cable','КМПЭВЭнг(А)-LS','602-kmpeveng-a-ls','MNP-0663','(индекс LS в марках означает низкое дымо- и газовыделение (Low Smoke)) (индекс (А) в марках означает, что кабель соответствует категории А по нераспространению горения по ГОСТ Р МЭК 332-3-96)','<div><p>КМПЭВЭнг(А)-LS </p><p>(индекс LS в марках означает низкое дымо- и газовыделение (Low Smoke)) <br/>(индекс (А) в марках означает, что кабель соответствует категории А по нераспространению горения по ГОСТ Р МЭК 332-3-96) </p><p>Кабели малогабаритные, не распространяющие горение, с низким дымо- и газовыделением, предназначены для передачи и распределения электрической энергии и электрических сигналов в стационарных установках при переменном и постоянном напряжении до 1000В. Климатическое исполнение УХЛ и Т, категория размещения 5 по ГОСТ 15150-69. <br/></p><p><img alt="kgns" loading="lazy" src="assets/img/products/kmpevengals__0cddebf02b909e962d15fbe7.jpg"/></p><p><strong>Конструкция КМПЭВЭнг(А)-LS: </strong></p><ol><li>Токопроводящая жила - медные проволоки. </li><li>Изоляция - полиэтилен. </li><li>Обмотка - слюдосодержащая лента. </li><li>Экран - оплетка из медных проволок. </li><li>Оболочка - ПВХ композиция пониженной пожароопаснсти. </li><li>Общий экран - оплетка из медных луженых проволок. </li></ol><p>Кабели предназначены для эксплуатации в кабельных сооружениях и помещениях, в том числе в системах АС классов 2,3 и 4 по классификации ОПБ-88/97 </p><p><strong>Технические и эксплуатационные характеристики КМПЭВЭнг(А)-LS </strong></p><p>Электрическая безопасность - ГОСТ 12.2.007.14-75. </p><p>Нераспространение горения - ГОСТ Р12176-89 (ГОСТ Р МЭК 332-3-96) категория А. <br/></p><table><tbody><tr><td>Температура окружающей среды при эксплуатации </td><td>от +50 <sup>0 </sup>С до -50 <sup>0 </sup>С </td></tr><tr><td>Относительная влажность воздуха (при t <sup>0 </sup>+35 <sup>0 </sup>С) </td><td>98% </td></tr><tr><td>Предельно допустимая t <sup>0 </sup>нагрева жил при эксплуатации </td><td>+70 <sup>0 </sup>С </td></tr><tr><td>Минимальная t <sup>0 </sup>прокладки кабеля без предварительного подогрева </td><td>- 15 <sup>0 </sup>С </td></tr><tr><td>Предельная температура токопроводящих жил кабелей по условию невозгорания кабеля при коротком замыкании </td><td>+400 <sup>0 </sup>С </td></tr><tr><td>Снижение светопроницаемости при горении и тлении </td><td>не более 40%. </td></tr><tr><td>Минимально допустимый радиус изгиба при прокладке </td><td>3 диам. кабеля </td></tr><tr><td>Срок службы </td><td>30 лет </td></tr><tr><td>Гарантийный срок эксплуатации </td><td>3 года </td></tr></tbody></table><p>Кабели не являются опасными в экологическом отношении и специальных требований по утилизации кабелей при выводе их эксплуатации, кроме предусмотренных в действующей на АС документации, не предъявляется. </p><p><strong>Кабели КМПЭВЭнг(А)-LS соответствуют требованиям ТУ 16.К71-310-2001 </strong></p><table><tbody><tr><td rowspan="1"><strong>Число жил, сечение, мм <sup>2 </sup></strong></td><td><strong>Номинальный наружный диаметр, мм </strong></td><td><strong>Расчетная масса, кг/км </strong></td></tr><tr><td>КМПЭВЭнг(А)-LS 2 х0,35 </td><td>7,2 </td><td>94 </td></tr><tr><td>КМПЭВЭнг(А)-LS 3 х0,35 </td><td>7,5 </td><td>106 </td></tr><tr><td>КМПЭВЭнг(А)-LS 4 х0,35 </td><td>8 </td><td>121 </td></tr><tr><td>КМПЭВЭнг(А)-LS 7 х0,35 </td><td>9,2 </td><td>166 </td></tr><tr><td>КМПЭВЭнг(А)-LS 12 х0,35 </td><td>12,5 </td><td>300 </td></tr><tr><td>КМПЭВЭнг(А)-LS 14 х0,35 </td><td>13 </td><td>328 </td></tr><tr><td>КМПЭВЭнг(А)-LS 19 х0,35 </td><td>14,2 </td><td>396 </td></tr><tr><td>КМПЭВЭнг(А)-LS 24 х0,35 </td><td>16,2 </td><td>481 </td></tr><tr><td>КМПЭВЭнг(А)-LS 27 х0,35 </td><td>16,5 </td><td>518 </td></tr><tr><td