INSERT INTO `products` (`id`,`category_id`,`root_category`,`name`,`slug`,`sku`,`short_description`,`description_html`,`image`,`unit`,`price`,`request_hint`,`active`,`featured`,`sort_order`,`seo_title`,`seo_description`,`source_file`,`specs_json`,`gallery_json`,`old_urls_json`) VALUES (680,19,'cable','ЗКП','750-zkp','MNP-0680','КАБЕЛИ СВЯЗИ ВЫСОКОЧАСТОТНЫЕ ОДНОЧЕТВЕРОЧНЫЕ С ПОЛИЭТИЛЕНОВОЙ ИЗОЛЯЦИЕЙ','<div><p>ЗКП </p><p>КАБЕЛИ СВЯЗИ ВЫСОКОЧАСТОТНЫЕ ОДНОЧЕТВЕРОЧНЫЕ С ПОЛИЭТИЛЕНОВОЙ ИЗОЛЯЦИЕЙ </p><p><img alt="zkp" loading="lazy" src="assets/img/products/zkp__0f15cbb2d9ad2cdda8d11271.jpg"/></p><p><strong>ТОКОПРОВОДЯЩАЯ ЖИЛА </strong><br/>Круглая медная однопроволочная диаметром 1,2 мм. <br/><br/><strong>ИЗОЛЯЦИЯ </strong><br/>Полиэтилен высокого давления (ПЭВД). <br/><br/><strong>СЕРДЕЧНИК </strong><br/>Четвёрка, скрученная из четырёх изолированных жил вокруг корделя. <br/><br/><strong>ПОЯСНАЯ ИЗОЛЯЦИЯ </strong><br/>Композиция полиэтилена <br/><br/><strong>ЭКРАН </strong><br/>Алюминиевая фольга (по желанию заказчика экран может быть заменён на медный). <br/><br/><strong>ОБОЛОЧКА </strong><br/>Светостабилизированный полиэтилен. <br/><br/><strong>Применение ЗКП : </strong><br/>Кабели предназначены для кабельных линий зоновой связи систем передачи К-60, (для частот 250 кГЦ), при переменном напряжении дистанционного питания до 690В /50Гц <br/>Технические характеристики: <br/></p><ul><li>Электрическое сопротивление токопроводящей жилы, при температуре 20 °С, не более 15,95 Ом/км. </li><li>Электрическое сопротивление изоляции, при температуре 20 °С, ,не менее 30 Мом/км. </li><li>Омическая асимметрия жил в рабочей паре, не более 0,21 Ом/км. </li><li>Переходное затухание на ближнем конце, не менее 58,1 дБ/км. </li><li>Строительная длина 1000 м. </li></ul></div>','assets/img/products/zkp__0f15cbb2d9ad2cdda8d11271.jpg','м',NULL,'Укажите марку, число и сечение жил, рабочее напряжение, длину и условия прокладки.',1,0,680,'ЗКП — купить по заявке | Монополия','ЗКП: подбор и поставка в Санкт-Петербурге. Укажите марку, число и сечение жил, рабочее напряжение, длину и условия прокладки. Расчет стоимости — по заявке.','site/www.monopoly-torg.ru/750-zkp__61e6aaee920fad1ed1aa340b.html','[]','["assets/img/products/zkp__0f15cbb2d9ad2cdda8d11271.jpg"]','["http://www.monopoly-torg.ru/index.php/kabelnaya-produkciya/kabeli-svyazi/750-zkp"]') ON DUPLICATE KEY UPDATE `category_id`=VALUES(`category_id`),`root_category`=VALUES(`root_category`),`name`=VALUES(`name`),`slug`=VALUES(`slug`),`sku`=VALUES(`sku`),`short_description`=VALUES(`short_description`),`description_html`=VALUES(`description_html`),`image`=VALUES(`image`),`unit`=VALUES(`unit`),`price`=VALUES(`price`),`request_hint`=VALUES(`request_hint`),`active`=VALUES(`active`),`featured`=VALUES(`featured`),`sort_order`=VALUES(`sort_order`),`seo_title`=VALUES(`seo_title`),`seo_description`=VALUES(`seo_description`),`source_file`=VALUES(`source_file`),`specs_json`=VALUES(`specs_json`),`gallery_json`=VALUES(`gallery_json`),`old_urls_json`=VALUES(`old_urls_json`);
INSERT INTO `products` (`id`,`category_id`,`root_category`,`name`,`slug`,`sku`,`short_description`,`description_html`,`image`,`unit`,`price`,`request_hint`,`active`,`featured`,`sort_order`,`seo_title`,`seo_description`,`source_file`,`specs_json`,`gallery_json`,`old_urls_json`) VALUES (681,19,'cable','ЗКПБ','751-zkpb','MNP-0681','КАБЕЛИ СВЯЗИ ВЫСОКОЧАСТОТНЫЕ ОДНОЧЕТВЕРОЧНЫЕ С ПОЛИЭТИЛЕНОВОЙ ИЗОЛЯЦИЕЙ','<div><p>ЗКПБ </p><p>КАБЕЛИ СВЯЗИ ВЫСОКОЧАСТОТНЫЕ ОДНОЧЕТВЕРОЧНЫЕ С ПОЛИЭТИЛЕНОВОЙ ИЗОЛЯЦИЕЙ </p><p><img alt="zkp" loading="lazy" src="assets/img/products/zkp__0f15cbb2d9ad2cdda8d11271.jpg"/></p><p><strong>ТОКОПРОВОДЯЩАЯ ЖИЛА </strong><br/>Круглая медная однопроволочная диаметром 1,2 мм. <br/><br/><strong>ИЗОЛЯЦИЯ </strong><br/>Полиэтилен высокого давления (ПЭВД). <br/><br/><strong>СЕРДЕЧНИК </strong><br/>Четвёрка, скрученая из четырёх изолированных жил вокруг корделя. <br/><br/><strong>ПОЯСНАЯ ИЗОЛЯЦИЯ </strong><br/>Композиция полиэтилена <br/><br/><strong>ЭКРАН </strong><br/>Алюминиевая фольга (по желанию заказчика экран может быть заменён на медный). <br/><br/><strong>ОБОЛОЧКА </strong><br/>Светостабилизированный полиэтилен. <br/><br/><strong>ЗАЩИТНЫЙ ПОКРОВ </strong><br/>Поверх экрана накладывается броня из стальной ленты <br/><br/><strong>Применение ЗКПБ : </strong><br/>Кабели предназначены для кабельных линий зоновой связи систем передачи К-60, (для частот 250 кГЦ), при переменном напряжении дистанционного питания до 690В /50Гц <br/><br/><strong>Технические характеристики ЗКПБ : </strong><br/>- Электрическое сопротивление токопроводящей жилы, при температуре 20 °С, не более 15,95 Ом/км. <br/>- Электрическое сопротивление изоляции, при температуре 20 °С, ,не менее 30 Мом/км. <br/>- Омическая асимметрия жил в рабочей паре, не более 0,21 Ом/км. <br/>- Переходное затухание на ближнем конце, не менее 58,1 дБ/км. <br/>- Строительная длина 1000 м. </p></div>','assets/img/products/zkp__0f15cbb2d9ad2cdda8d11271.jpg','м',NULL,'Укажите марку, число и сечение жил, рабочее напряжение, длину и условия прокладки.',1,0,681,'ЗКПБ — купить по заявке | Монополия','ЗКПБ: подбор и поставка в Санкт-Петербурге. Укажите марку, число и сечение жил, рабочее напряжение, длину и условия прокладки. Расчет стоимости — по заявке.','site/www.monopoly-torg.ru/751-zkpb__da09f96507372e85d53a6977.html','[]','["assets/img/products/zkp__0f15cbb2d9ad2cdda8d11271.jpg"]','["http://www.monopoly-torg.ru/index.php/kabelnaya-produkciya/kabeli-svyazi/751-zkpb"]') ON DUPLICATE KEY UPDATE `category_id`=VALUES(`category_id`),`root_category`=VALUES(`root_category`),`name`=VALUES(`name`),`slug`=VALUES(`slug`),`sku`=VALUES(`sku`),`short_description`=VALUES(`short_description`),`description_html`=VALUES(`description_html`),`image`=VALUES(`image`),`unit`=VALUES(`unit`),`price`=VALUES(`price`),`request_hint`=VALUES(`request_hint`),`active`=VALUES(`active`),`featured`=VALUES(`featured`),`sort_order`=VALUES(`sort_order`),`seo_title`=VALUES(`seo_title`),`seo_description`=VALUES(`seo_description`),`source_file`=VALUES(`source_file`),`specs_json`=VALUES(`specs_json`),`gallery_json`=VALUES(`gallery_json`),`old_urls_json`=VALUES(`old_urls_json`);
