INSERT INTO `products` (`id`,`category_id`,`root_category`,`name`,`slug`,`sku`,`short_description`,`description_html`,`image`,`unit`,`price`,`request_hint`,`active`,`featured`,`sort_order`,`seo_title`,`seo_description`,`source_file`,`specs_json`,`gallery_json`,`old_urls_json`) VALUES (708,19,'cable','МКСГШп','778-mksgshp','MNP-0708','Кабели симметричные высокочастотные с кордельно-полистирольной изоляцией в свинцовой оболочке с защитным покровом типа Шп','<div><p>МКСГШп </p><p>Кабели симметричные высокочастотные с кордельно-полистирольной изоляцией в свинцовой оболочке с защитным покровом типа Шп </p><p><img alt="kvpvep" loading="lazy" src="assets/img/products/mksgshp__9cf919e53ec674b4dba3ff2d.jpg"/></p><p>1. Токопроводящие жилы изготовлены из медной проволоки и изолированны полистирольной нитью (корделем), наложенной открытой спиралью, и полистирольной лентой, наложенной с перекрытием в сторону, противоположную направлению наложения нити. <br/><br/>2. Четыре жилы с изоляцией различных цветов скручены в звездную четверку с центральным заполнителем из круглой полистирольной нити. Шаги скрутки изолированных жил в различных четверках различны и находится в диапазоне от 100 до 300 мм. <br/><br/>3. В четверке две жилы, расположенные по диагонали, образуют рабочую пару. Изоляция жил первой пары четверки имеет красный и желтый цвета, второй пары – синий и зеленый. <br/><br/>4. Скрученная четверка обмотана по открытой спирали цветной хлопчатобумажной или синтетической пряжей или лентой из синтетического материала. Цвета пряжи или ленты всех четверок различны; цвета двух смежных четверок (счетной и направляющей) – соответственно красный и зеленый. <br/><br/><strong>Применение МКСГШп : </strong><br/>Кабель МКСГ предназначен для прокладки в канализациях, трубах, блоках, коллекторах, тоннелях и внутри помещений при отсутствии механических воздействий на кабель, в среде, нейтральной по отношению к оболочке, в условиях, не характеризующихся повышенным электромагнитным влиянием. Кабель МКСБ предназначен для прокладки в грунтах, нейтральных по отношению к оболочке, если кабель не подвергается значительным растягивающим или сдавливающим усилиям, в районах, не характеризующихся повышенным электромагнитным влиянием. <br/><br/>Предназначенны для использования на магистральных и внутризоновых первичных сетях (ГТС), в цифровых системах передачи со скоростью 8448 кбит/с(тактовой частотой), 34368 кбит/с и аналоговых системах передачи в диапазоне частот до 5000 кГц для работы при переменном напряжении дистанционного питания до 690 В или постоянном напряжении до 1000 В. Кабели с токопроводящими жилами диаметром 1,0 мм используются в диапазоне частот до 552 кГц. </p></div>','assets/img/products/mksgshp__9cf919e53ec674b4dba3ff2d.jpg','м',NULL,'Укажите марку, число и сечение жил, рабочее напряжение, длину и условия прокладки.',1,0,708,'МКСГШп — купить по заявке | Монополия','МКСГШп: подбор и поставка в Санкт-Петербурге. Укажите марку, число и сечение жил, рабочее напряжение, длину и условия прокладки. Расчет стоимости — по заявке.','site/www.monopoly-torg.ru/778-mksgshp__24926ebf5d5fa40b1533a1d1.html','[]','["assets/img/products/mksgshp__9cf919e53ec674b4dba3ff2d.jpg"]','["http://www.monopoly-torg.ru/index.php/kabelnaya-produkciya/kabeli-svyazi/778-mksgshp"]') ON DUPLICATE KEY UPDATE `category_id`=VALUES(`category_id`),`root_category`=VALUES(`root_category`),`name`=VALUES(`name`),`slug`=VALUES(`slug`),`sku`=VALUES(`sku`),`short_description`=VALUES(`short_description`),`description_html`=VALUES(`description_html`),`image`=VALUES(`image`),`unit`=VALUES(`unit`),`price`=VALUES(`price`),`request_hint`=VALUES(`request_hint`),`active`=VALUES(`active`),`featured`=VALUES(`featured`),`sort_order`=VALUES(`sort_order`),`seo_title`=VALUES(`seo_title`),`seo_description`=VALUES(`seo_description`),`source_file`=VALUES(`source_file`),`specs_json`=VALUES(`specs_json`),`gallery_json`=VALUES(`gallery_json`),`old_urls_json`=VALUES(`old_urls_json`);
INSERT INTO `products` (`id`,`category_id`,`root_category`,`name`,`slug`,`sku`,`short_description`,`description_html`,`image`,`unit`,`price`,`request_hint`,`active`,`featured`,`sort_order`,`seo_title`,`seo_description`,`source_file`,`specs_json`,`gallery_json`,`old_urls_json`) VALUES (709,19,'cable','МКСКл','779-mkskl','MNP-0709','Кабели симметричные высокочастотные с кордельно-полистирольной изоляцией в свинцовой оболочке с защитным покровом типа Кл','<div><p>МКСКл </p><p>Кабели симметричные высокочастотные с кордельно-полистирольной изоляцией в свинцовой оболочке с защитным покровом типа Кл </p><p><img alt="mksashp" loading="lazy" src="assets/img/products/mkskl__0c54bbbff19e68a56667f2ef.jpg"/></p><p>1. Токопроводящие жилы изготовлены из медной проволоки и изолированны полистирольной нитью (корделем), наложенной открытой спиралью, и полистирольной лентой, наложенной с перекрытием в сторону, противоположную направлению наложения нити. <br/><br/>2. Четыре жилы с изоляцией различных цветов скручены в звездную четверку с центральным заполнителем из круглой полистирольной нити. Шаги скрутки изолированных жил в различных четверках различны и находится в диапазоне от 100 до 300 мм. <br/><br/>3. В четверке две жилы, расположенные по диагонали, образуют рабочую пару. Изоляция жил первой пары четверки имеет красный и желтый цвета, второй пары – синий и зеленый. <br/><br/>4. Скрученная четверка обмотана по открытой спирали цветной хлопчатобумажной или синтетической пряжей или лентой из синтетического материала. Цвета пряжи или ленты всех четверок различны; цвета двух смежных четверок (счетной и направляющей) – соответственно красный и зеленый. <br/><br/><strong>Применение МКСКл : </strong><br/>Кабель МКСГ предназначен для прокладки в канализациях, трубах, блоках, коллекторах, тоннелях и внутри помещений при отсутствии механических воздействий на кабель, в среде, нейтральной по отношению к оболочке, в условиях, не характеризующихся повышенным электромагнитным влиянием. Кабель МКСБ предназначен для прокладки в грунтах, нейтральных по отношению к оболочке, если кабель не подвергается значительным растягивающим или сдавливающим усилиям, в районах, не характеризующихся повышенным электромагнитным влиянием. <br/><br/>Предназначены для использования на магистральных и внутризоновых первичных сетях (ГТС), в цифровых системах передачи со скоростью 8448 кбит/с (тактовой частотой), 34368 кбит/с и аналоговых системах передачи в диапазоне частот до 5000 кГц для работы при переменном напряжении дистанционного питания до 690 В или постоянном напряжении до 1000 В. Кабели с токопроводящими жилами диаметром 1,0 мм используются в диапазоне частот до 552 кГц. </p></div>','assets/img/products/mkskl__0c54bbbff19e68a56667f2ef.jpg','м',NULL,'Укажите марку, число и сечение жил, рабочее напряжение, длину и условия прокладки.',1,0,709,'МКСКл — купить по заявке | Монополия','МКСКл: подбор и поставка в Санкт-Петербурге. Укажите марку, число и сечение жил, рабочее напряжение, длину и условия прокладки. Расчет стоимости — по заявке.','site/www.monopoly-torg.ru/779-mkskl__d8a5e2ecb6c74b02ac826da0.html','[]','["assets/img/products/mkskl__0c54bbbff19e68a56667f2ef.jpg"]','["http://www.monopoly-torg.ru/index.php/kabelnaya-produkciya/kabeli-svyazi/779-mkskl"]') ON DUPLICATE KEY UPDATE `category_id`=VALUES(`category_id`),`root_category`=VALUES(`root_category`),`name`=VALUES(`name`),`slug`=VALUES(`slug`),`sku`=VALUES(`sku`),`short_description`=VALUES(`short_description`),`description_html`=VALUES(`description_html`),`image`=VALUES(`image`),`unit`=VALUES(`unit`),`price`=VALUES(`price`),`request_hint`=VALUES(`request_hint`),`active`=VALUES(`active`),`featured`=VALUES(`featured`),`sort_order`=VALUES(`sort_order`),`seo_title`=VALUES(`seo_title`),`seo_description`=VALUES(`seo_description`),`source_file`=VALUES(`source_file`),`specs_json`=VALUES(`specs_json`),`gallery_json`=VALUES(`gallery_json`),`old_urls_json`=VALUES(`old_urls_json`);
INSERT INTO `products` (`id`,`category_id`,`root_category`,`name`,`slug`,`sku`,`short_description`,`description_html`,`image`,`unit`,`price`,`request_hint`,`active`,`featured`,`sort_order`,`seo_title`,`seo_description`,`source_file`,`specs_json`,`gallery_json`,`old_urls_json`) VALUES (710,19,'cable','НВП, НВПп, НВПЭ','780-nvp-nvpp-nvpe','MNP-0710','Симметричные кабели для структурированных кабельных систем связи марок НВП, НВПп, НВПЭ и НВПпЭ предназначены для стационарной прокладки внутри зданий и сооружений и работы в диапазоне частот использования до 100 МГц (категорий 3, 5 и 5е) при.','<div><p>НВП, НВПп, НВПЭ </p><p><img alt="kcppep" loading="lazy" src="assets/img/products/nvp__a43a891354e11d201be6ab8e.jpg"/></p><p><strong>Конструкция НВП, НВПп, НВПЭ: </strong><br/></p><p><strong>НВП </strong>- кабель с медными жилами со сплошной полиэтиленовой изоляцией в ПВХ оболочке <br/><strong>НВПп </strong>- кабель с медными жилами со сплошной полиэтиленовой изоляцией в ПВХ оболочке, с пленко-пористо-пленочной изоляцией <br/><strong>НВПЭ </strong>- кабель с медными жилами со сплошной полиэтиленовой изоляцией,с общим экраном из фольгированного лавсана в ПВХ оболочке. <br/>1. Токопроводящие жилы - однопроволочные, из медной мягкой круглой проволоки номинальным диаметром 0.52 мм. <br/>2. Изоляция из полиэтилена наложена в виде сплошного слоя в кабелях марок НВП и НВПЭ или пленко-пористо-пленочного слоя в кабелях марок НВПп. <br/>3. Витая пара из двух изолированных жил, отличающихся по цвету, скрученных в пару с согласованными шагами. Расцветка жил указана в таблице ниже. <br/>4. Витые пары скручиваются в сердечник. Число пар в кабеле - 2 или 4. <br/>5. В кабелях марок НВПЭ поверх скрученных в сердечник витых пар наложен общий экран из фольгированного лавсана. Под экраном проложена медная луженая контактная проволока номинальным диаметром 0.4 - 0.5 мм. <br/>6. Оболочка из ПВХ пластиката серого цвета различных оттенков. Допускается изготовление оболочки других цветов по согласованию с заказчиком. </p><p><strong>Применение НВП, НВПп, НВПЭ: </strong><br/></p><p>Симметричные кабели для структурированных кабельных систем связи марок НВП, НВПп, НВПЭ и НВПпЭ предназначены для стационарной прокладки внутри зданий и сооружений и работы в диапазоне частот использования до 100 МГц (категорий 3, 5 и 5е) при напряжении до 145 В переменного тока частотой 50 Гц или 200 В постоянного тока. Не распространяют горение при одиночной прокладке. </p><p>Кабели марок НВП и НВПп используются в горизонтальной подсистеме структурированных систем на участке от коммутационного оборудования в кроссовом помещении этажа до информационных розеток рабочих мест, а так же в системе абонентского доступа. Области применения кабелей марок НВПЭ те же, только в условиях повышенных электромагнитных явлений или при повышенных требованиях к безопасности кабельной системы. </p><p>Кабели по конструкции, техническим требованиям, эксплуатационным параметрам соответствуют требованиям международного стандарта ISO/IEC 11801. Обозначение кабелей по стандарту ISO/ IEC 11801: марок НВП, НВПп - UTP; марок НВПЭ - S/UTP. </p><p>Кабели не распространяют горение при одиночной прокладке. <br/>Класс пожарной опасности кабелей по ГОСТ Р 53315-2009 - О1.8.2.4.4. </p><p><strong>Технические характеристики НВП, НВПп, НВПЭ: </strong><br/></p><p>- Вид климатического исполнения У категории размещения 3, 4 по ГОСТ 15150 <br/>- Диапазон температур экусплуатации: от + 60°С до - 20°С <br/>- Кабели стойки в условиях монтажных и эксплуатационных изгибов на радиус не менее 8 наружных диаметров кабеля при пониженной температуре окружающей среды до минус 20°С <br/>- Электрическое сопротивление ТПЖ постоянному току, пересчитанное на 1км длины кабеля и температуру 20°С, не более: 95 Ом <br/>- Электрическое сопротивление изоляции ТПЖ постоянному току, пересчитанное на 1км длины и температуру 20°С, не менее: 6500 МОм <br/>- Омическая асимметрия жил в рабочей паре на длине 1км, не более: 3% <br/>- Электрическая емкость цепи при переменном токе частотой 800 или 1000 Гц на 1км длины кабеля, не более: 56 нФ <br/>- Волновое сопротивление цепей в рабочем диапазоне частот 0.772-100 МГц: 100±15 Ом <br/>- Испытательное напряжение в течение 1 мин между жилами, между жилами и экраном: <br/>при постоянном токе - 1000 В <br/>при переменном токе частотой 50 Гц - 700 В <br/>- Значения затухания цепей в рабочем диапазоне частот на длине 100 м приведены ниже. <br/>- Значения переходного затухания на ближнем конце Ао (NEXT) в рабочем диапазоне частот на длине 100 м приведены ниже. <br/>- Строительная длина кабелей, не менее: 90 м <br/>- Гарантийный срок эксплуатации: 2 года с даты ввода кабелей в эксплуатацию <br/>- Минимальный срок службы кабелей: 15 лет </p>Табличные данные <p><strong>Расцветка жил указана в таблице: </strong></p><table><tbody><tr><td rowspan="2"><div><strong>Условный номер пары </strong></div></td><td colspan="2"><div><strong>Расцветка жилы в паре </strong></div></td></tr><tr><td><div><strong>а </strong></div></td><td><div><strong>б </strong></div></td></tr><tr><td><div>1 </div></td><td><div>голубая (синяя) </div></td><td><div>бело-голубая (синяя) </div></td></tr><tr><td><div>2 </div></td><td><div>оранжевая </div></td><td><div>бело-оранжевая </div></td></tr><tr><td><div>3 </div></td><td><div>коричневая </div></td><td><div>бело-коричневая </div></td></tr><tr><td><div>4 </div></td><td><div>зеленая </div></td><td><div>бело-зеленая </div></td></tr><tr><td colspan="3"><div><strong>Допускается расцветка жилы "б" белого цвета </strong></div></td></tr></tbody></table><p><strong>Значения затухания цепей в рабочем диапазоне частот на длине 100 м приведены в таблице: </strong></p><table><tbody><tr><td rowspan="2"><div><strong>Частота, МГц </strong></div></td><td colspan="3"><div><strong>Затухание, дБ/100 м, не более </strong></div></td></tr><tr><td><div><strong>Категория 3 </strong></div></td><td><div><strong>Категория 5 </strong></div></td><td><div><strong>Категория 5е </strong></div></td></tr><tr><td><div>1.0 </div></td><td><div>2.6 </div></td><td><div>2.1 </div></td><td><div>2.1 </div></td></tr><tr><td><div>4.0 </div></td><td><div>5.6 </div></td><td><div>4.3 </div></td><td><div>4.3 </div></td></tr><tr><td><div>8.0 </div></td><td><div>8.5 </div></td><td><div>5.8 </div></td><td><div>5.8 </div></td></tr><tr><td><div>10.0 </div></td><td><div>9.8 </div></td><td><div>6.6 </div></td><td><div>6.6 </div></td></tr><tr><td><div>16.0 </div></td><td><div>13.1 </div></td><td><div>8.2 </div></td><td><div>8.2 </div></td></tr><tr><td><div>20.0 </div></td><td><div>- </div></td><td><div>9.2 </div></td><td><div>9.2 </div></td></tr><tr><td><div>25.0 </div></td><td><div>- </div></td><td><div>10.4 </div></td><td><div>10.4 </div></td></tr><tr><td><div>31.25 </div></td><td><div>- </div></td><td><div>11.8 </div></td><td><div>11.8 </div></td></tr><tr><td><div>62.5 </div></td><td><div>- </div></td><td><div>17.1 </div></td><td><div>17.1 </div></td></tr><tr><td><div>100 </div></td><td><div>- </div></td><td><div>22.0 </div></td><td><div>22.0 </div></td></tr></tbody></table><p><strong>Значения переходного затухания на ближнем конце Ао (NEXT) в рабочем диапазоне частот на длине 100 м приведены в таблице: </strong></p><table><tbody><tr><td rowspan="2"><div><strong>Частота, МГц </strong></div></td><td colspan="3"><div><strong>Переходное затухание на ближнем конце Ао, дБ/100 м, не менее </strong></div></td></tr><tr><td><div><strong>Категория 3 </strong></div></td><td><div><strong>Категория 5 </strong></div></td><td><div><strong>Категория 5е </strong></div></td></tr><tr><td><div>1.0 </div></td><td><div>41 </div></td><td><div>62 </div></td><td><div>65 </div></td></tr><tr><td><div>4.0 </div></td><td><div>32 </div></td><td><div>53 </div></td><td><div>60 </div></td></tr><tr><td><div>8.0 </div></td><td><div>27 </div></td><td><div>48 </div></td><td><div>51 </div></td></tr><tr><td><div>10.0 </div></td><td><div>26 </div></td><td><div>47 </div></td><td><div>50 </div></td></tr><tr><td><div>16