INSERT INTO `products` (`id`,`category_id`,`root_category`,`name`,`slug`,`sku`,`short_description`,`description_html`,`image`,`unit`,`price`,`request_hint`,`active`,`featured`,`sort_order`,`seo_title`,`seo_description`,`source_file`,`specs_json`,`gallery_json`,`old_urls_json`) VALUES (721,19,'cable','ТЗАБпШп','791-tzabpshp','MNP-0721','КАБЕЛИ СВЯЗИ НИЗКОЧАСТОТНЫЕ С КОРДЕЛЬНО-БУМАЖНОЙ ИЗОЛЯЦИЕЙ В АЛЮМИНИЕВОЙ ОБОЛОЧКЕ','<div><p>ТЗАБпШп </p><p><br/>КАБЕЛИ СВЯЗИ НИЗКОЧАСТОТНЫЕ С КОРДЕЛЬНО-БУМАЖНОЙ ИЗОЛЯЦИЕЙ В АЛЮМИНИЕВОЙ ОБОЛОЧКЕ </p><p><strong>Конструкция ТЗАБпШп : </strong></p><p><strong>ТОКОПРОВОДЯЩАЯ ЖИЛА </strong><br/>Круглые, медные однопроволочные диаметром 0,9 или 1,2 мм. </p><p><strong>ИЗОЛЯЦИЯ </strong><br/>Обмотка бумажным корделем и лентой кабельной бумаги К-120 </p><p><strong>ЧЕТВЕРКА </strong><br/>Четыре изолированных жилы разной расцветки скручены с шагом не более 300 мм </p><p><strong>ПОЯСНАЯ ИЗОЛЯЦИЯ </strong><br/>Четыре ленты кабельной бумаги К-120. </p><p><strong>СЕРДЕЧНИК </strong><br/>Четверки скручены вместе концентрическими повивами в разные стороны. Количество четверок 4-52 </p><p><strong>ЗАЩИТНЫЕ ПОКРОВЫ </strong><br/>Типа БпШп </p><p><strong>ОБОЛОЧКА </strong><br/>Алюминиевая </p><p><strong>Применение ТЗАБпШп : </strong></p><p>Кабели предназначены для соединения телефонных и телеграфных узлов, устройств кабельных вводов и вставок в воздушные линии связи, соединительных линий между АТС, а также АТС и МТС при температуре окружающей среды от минус 40° С до плюс 45° С. В зависимости от типа защитного покрова прокладываются в телефонной канализации, трубах, грунтах с низкой и высокой коррозионной активностью, а также в районах с низким и повышенным электромагнитным влиянием. </p><p><strong>Технические характеристики ТЗАБпШп : </strong><br/>- Электрическое сопротивление жил постоянному току, пересчитанное на 1 км длины и температуру 20° С: <br/>а) при диаметре жил 0,9 мм - не более 28,5 Ом <br/>б) при диаметре жил 1,2 мм - не более 16,0 Ом. </p><p>- Электрическое сопротивление изоляции, пересчитанное на 1 км длины и температуру 20° С, не менее 10 000 МОм. </p><p>- Испытательное напряжение между жилами переменным напряжением частотой 50 Гц в течение 2 мин: <br/>а) при диаметре жил 0,9 мм - 700 В <br/>б) при диаметре жил 1,2 мм - 1000 В </p><p>- Строительная длина 425± 5 м, 850± 10 м, 1275± 15 м. </p><p>- Срок службы кабеля, не менее 30 лет. </p></div>','assets/img/product-placeholder.svg','м',NULL,'Укажите марку, число и сечение жил, рабочее напряжение, длину и условия прокладки.',1,0,721,'ТЗАБпШп — купить по заявке | Монополия','ТЗАБпШп: подбор и поставка в Санкт-Петербурге. Укажите марку, число и сечение жил, рабочее напряжение, длину и условия прокладки. Расчет стоимости — по заявке.','site/www.monopoly-torg.ru/791-tzabpshp__3bf202d2e2c6c8ed5331244e.html','[]','[]','["http://www.monopoly-torg.ru/index.php/kabelnaya-produkciya/kabeli-svyazi/791-tzabpshp"]') ON DUPLICATE KEY UPDATE `category_id`=VALUES(`category_id`),`root_category`=VALUES(`root_category`),`name`=VALUES(`name`),`slug`=VALUES(`slug`),`sku`=VALUES(`sku`),`short_description`=VALUES(`short_description`),`description_html`=VALUES(`description_html`),`image`=VALUES(`image`),`unit`=VALUES(`unit`),`price`=VALUES(`price`),`request_hint`=VALUES(`request_hint`),`active`=VALUES(`active`),`featured`=VALUES(`featured`),`sort_order`=VALUES(`sort_order`),`seo_title`=VALUES(`seo_title`),`seo_description`=VALUES(`seo_description`),`source_file`=VALUES(`source_file`),`specs_json`=VALUES(`specs_json`),`gallery_json`=VALUES(`gallery_json`),`old_urls_json`=VALUES(`old_urls_json`);
