INSERT INTO `products` (`id`,`category_id`,`root_category`,`name`,`slug`,`sku`,`short_description`,`description_html`,`image`,`unit`,`price`,`request_hint`,`active`,`featured`,`sort_order`,`seo_title`,`seo_description`,`source_file`,`specs_json`,`gallery_json`,`old_urls_json`) VALUES (759,20,'cable','КУГПЭПнг-FRHF','835-kugpepng-frhf','MNP-0759','Кабели для систем управления и сигнализации, не распространяющие горение, с изоляцией и оболочкой из полимерных композиций, не содержащих галогенов, предназначены для передачи электрических сигналов и распределения электрической энергии в цепях.','<div><p>КУГПЭПнг-FRHF </p><p><img alt="kugvvengfrls" loading="lazy" src="assets/img/products/kugpepnghf__32de120336302b6cbf01fd5d.jpg"/></p><ul><li>медные гибкие многопроволочные жилы класса 4; </li><li>термический барьер из слюдосодержащей ленты по медной жиле; </li><li>изоляция из полимерной композиции, не содержащей галогенов; </li><li>общий экран оплёткой из медных проволок; </li><li>оболочка из полимерной композиции, не содержащей галогенов </li></ul><h2>Область применения КУГПЭПнг-FRHF <br/></h2><p>Кабели для систем управления и сигнализации, не распространяющие горение, с изоляцией и оболочкой из полимерных композиций, не содержащих галогенов, предназначены для передачи электрических сигналов и распределения электрической энергии в цепях управления, cигнализации, связи, межприборных соединений при напряжении 250, 380 и 1000 В переменного тока частотой до 200 Гц или при напряжении соответственно 350, 750 и 1500 В постоянного тока. </p><p>Кабели <strong>КУГПЭПнг-FRHF </strong>применяются для цепей систем управления при прокладке в кабельных сооружениях и помещениях, в том числе для использования в системах АС класса 3 по классификации ОПБ-88 /97 (ПНАЭ Г- 01-011-97 ). </p><p><strong>КУГПЭПнг-FRHF </strong>применяется в том числе для цепей, сохраняющих работоспособность при пожаре, включая системы безопасности АС. </p><p>Нераспространение горения — ГОСТ Р МЭК 332-3-96 , категория А. </p><p>Предельная температура токопроводящих жил кабелей по условию невозгорания кабеля при коротком замыкании: +400 °С. </p><p>Содержание газов галогеносодержащих кислот в пересчете на HCI — 5,0 мг/г. </p><p>Кабели стойки к монтажным изгибам. </p><p>Кабели выдерживают 10 циклов изгибов на угол ±90 ° вокруг пары цилиндров диаметром, равным 5 наружным диаметрам кабеля. </p><p>Кабели стойки к воздействию плесневых грибов. </p><p>Кабели <strong>КУГПЭПнг-FRHF </strong>не распространяют горение при групповой прокладке. </p><p>Кабели имеют низкие значения показателей коррозионной активности продуктов газовыделения при горении и тлении. </p><p>Кабели имеют низкое дымообразование при горении и тлении. </p><p>Кабели с индексом «нг-FRHF» огнестойки в течение не менее 90 мин. </p><p>Диапазон температур эксплуатации: от -50 °С до +50 °С. </p><p>Монтаж кабеля должен осуществляться при температуре не ниже -15 °С. </p><p>Срок службы — не менее 40 лет. </p><p>Радиус изгиба — не менее 6 наружных диаметров кабеля. </p><p>Допустимая температура нагрева жил при эксплуатации — не более +70 °С. </p></div>','assets/img/products/kugpepnghf__32de120336302b6cbf01fd5d.jpg','м',NULL,'Укажите марку, число и сечение жил, рабочее напряжение, длину и условия прокладки.',1,0,759,'КУГПЭПнг-FRHF — купить по заявке | Монополия','КУГПЭПнг-FRHF: подбор и поставка в Санкт-Петербурге. Укажите марку, число и сечение жил, рабочее напряжение, длину и условия прокладки. Расчет стоимости — по заявке.','site/www.monopoly-torg.ru/835-kugpepng-frhf__1d988983e5b4b69a667c41a0.html','[]','["assets/img/products/kugpepnghf__32de120336302b6cbf01fd5d.jpg"]','["http://www.monopoly-torg.ru/index.php/kabelnaya-produkciya/kabeli-upravleniya/835-kugpepng-frhf"]') ON DUPLICATE KEY UPDATE `category_id`=VALUES(`category_id`),`root_category`=VALUES(`root_category`),`name`=VALUES(`name`),`slug`=VALUES(`slug`),`sku`=VALUES(`sku`),`short_description`=VALUES(`short_description`),`description_html`=VALUES(`description_html`),`image`=VALUES(`image`),`unit`=VALUES(`unit`),`price`=VALUES(`price`),`request_hint`=VALUES(`request_hint`),`active`=VALUES(`active`),`featured`=VALUES(`featured`),`sort_order`=VALUES(`sort_order`),`seo_title`=VALUES(`seo_title`),`seo_description`=VALUES(`seo_description`),`source_file`=VALUES(`source_file`),`specs_json`=VALUES(`specs_json`),`gallery_json`=VALUES(`gallery_json`),`old_urls_json`=VALUES(`old_urls_json`);
INSERT INTO `products` (`id`,`category_id`,`root_category`,`name`,`slug`,`sku`,`short_description`,`description_html`,`image`,`unit`,`price`,`request_hint`,`active`,`featured`,`sort_order`,`seo_title`,`seo_description`,`source_file`,`specs_json`,`gallery_json`,`old_urls_json`) VALUES (760,20,'cable','КУГПЭПнг-HF','836-kugpepng-hf','MNP-0760','Кабели для систем управления и сигнализации не распространяющие горение, предназначены для передачи электрических сигналов и распределения электрической энергии в цепях управления, сигнализации, связи, межприборных соединений при напряжении 250,.','<div><p>КУГПЭПнг-HF </p><p>Кабели для систем управления и сигнализации не распространяющие горение, предназначены для передачи электрических сигналов и распределения электрической энергии в цепях управления, сигнализации, связи, межприборных соединений при напряжении 250, 380 И 1000В переменного тока частотой до 200Гц или при напряжении соответственно 350, 750 И 1000В постоянного тока. Климатическое исполнение В, категория размещения 5 по ГОСТ 15150-69. </p><p><img alt="kugppnghf" loading="lazy" src="assets/img/products/kugpepnghf__32de120336302b6cbf01fd5d.jpg"/></p><p><strong>Конструкция КУГПЭПнг-HF <br/></strong></p><ol><li>Токопроводящая жила – многопроволочная медная мягкая проволока. </li><li>Изоляция – полимерная композиция, не содержащая галогенов. </li><li>Экран – оплетка из медной проволоки. </li><li>Оболочка - полимерная композиция, не содержащая галогенов. </li></ol><p>Кабели предназначены для эксплуатации в кабельных сооружениях и помещениях, в том числе для использования в системах АС класс 3 по классификации ОПБ-88/97 (ПНАЭ Г –01-011). </p><p><strong>Технические и эксплуатационные характеристики КУГПЭПнг-HF </strong><br/></p><p>Электрическая безопасность – ГОСТ 12.2.007-75 <br/>Нераспространение горения – ГОСТ Р МЭК 332-3-96, категория А. </p><table><tbody><tr><td>Температура окружающей среды при эксплуатации: </td><td>от +50 <sup>0 </sup>С до -50 <sup>0 </sup>С </td></tr><tr><td>Относительная влажность воздуха (при t <sup>0 </sup>+35 <sup>0 </sup>С): </td><td>98% </td></tr><tr><td>Длительно допустимая t <sup>0 </sup>нагрева жил при эксплуатации: </td><td>+70 <sup>0 </sup>С </td></tr><tr><td>Минимальная t <sup>0 </sup>прокладки кабеля без предварительного подогрева: </td><td>- 15 <sup>0 </sup>С </td></tr><tr><td>Предельная t <sup>0 </sup>токопроводящих жил кабелей по условию невозгорания кабеля при коротком замыкании: </td><td>+400 <sup>0 </sup>С </td></tr><tr><td>Содержание газов галогеносодержащих кислот в пересчете на HCl : </td><td>5,0 мг/г </td></tr><tr><td>Показатель pH (кислотное число): </td><td>4,3 </td></tr><tr><td>Снижение светопроницаемости при горении и тлении: </td><td>не более 40%. </td></tr><tr><td>Минимально допустимый радиус изгиба при прокладке: </td><td>6 диам. кабеля </td></tr><tr><td>Срок службы </td><td>40 лет </td></tr><tr><td>Гарантийный срок эксплуатации </td><td>3 года </td></tr></tbody></table><p>Кабели не являются опасными в экологическом отношении и специальных требований по утилизации кабелей при выводе их эксплуатации, кроме предусмотренных в действующей на АС документации, не предъявляется. </p></div>','assets/img/products/kugpepnghf__32de120336302b6cbf01fd5d.jpg','м',NULL,'Укажите марку, число и сечение жил, рабочее напряжение, длину и условия прокладки.',1,0,760,'КУГПЭПнг-HF — купить по заявке | Монополия','КУГПЭПнг-HF: подбор и поставка в Санкт-Петербурге. Укажите марку, число и сечение жил, рабочее напряжение, длину и условия прокладки. Расчет стоимости — по заявке.','site/www.monopoly-torg.ru/836-kugpepng-hf__dab45bd66e3fd74a63263a4e.html','[["Температура окружающей среды при эксплуатации:", "от +50 0 С до -50 0 С"], ["Относительная влажность воздуха (при t 0 +35 0 С):", "98%"], ["Длительно допустимая t 0 нагрева жил при эксплуатации:", "+70 0 С"], ["Минимальная t 0 прокладки кабеля без предварительного подогрева:", "- 15 0 С"], ["Предельная t 0 токопроводящих жил кабелей по условию невозгорания кабеля при коротком замыкании:", "+400 0 С"], ["Содержание газов галогеносодержащих кислот в пересчете на HCl :", "5,0 мг/г"], ["Показатель pH (кислотное число):", "4,3"], ["Снижение светопроницаемости при горении и тлении:", "не более 40%."], ["Минимально допустимый радиус изгиба при прокладке:", "6 диам. кабеля"], ["Срок службы", "40 лет"], ["Гарантийный срок эксплуатации", "3 года"]]','["assets/img/products/kugpepnghf__32de120336302b6cbf01fd5d.jpg"]','["http://www.monopoly-torg.ru/index.php/kabelnaya-produkciya/kabeli-upravleniya/836-kugpepng-hf"]') ON DUPLICATE KEY UPDATE `category_id`=VALUES(`category_id`),`root_category`=VALUES(`root_category`),`name`=VALUES(`name`),`slug`=VALUES(`slug`),`sku`=VALUES(`sku`),`short_description`=VALUES(`short_description`),`description_html`=VALUES(`description_html`),`image`=VALUES(`image`),`unit`=VALUES(`unit`),`price`=VALUES(`price`),`request_hint`=VALUES(`request_hint`),`active`=VALUES(`active`),`featured`=VALUES(`featured`),`sort_order`=VALUES(`sort_order`),`seo_title`=VALUES(`seo_title`),`seo_description`=VALUES(`seo_description`),`source_file`=VALUES(`source_file`),`specs_json`=VALUES(`specs_json`),`gallery_json`=VALUES(`gallery_json`),`old_urls_json`=VALUES(`old_urls_json`);
INSERT INTO `products` (`id`,`category_id`,`root_category`,`name`,`slug`,`sku`,`short_description`,`description_html`,`image`,`unit`,`price`,`request_hint`,`active`,`featured`,`sort_order`,`seo_title`,`seo_description`,`source_file`,`specs_json`,`gallery_json`,`old_urls_json`) VALUES (761,20,'cable','КУГЭППнг-HF','837-kugeppng-hf','MNP-0761','Кабели для систем управления и сигнализации не распространяющие горение, предназначены для передачи электрических сигналов и распределения электрической энергии в цепях управления, сигнализации, связи, межприборных соединений при напряжении 250,.','<div><p>КУГЭППнг-HF </p><p>Кабели для систем управления и сигнализации не распространяющие горение, предназначены для передачи электрических сигналов и распределения электрической энергии в цепях управления, сигнализации, связи, межприборных соединений при напряжении 250, 380 И 1000В переменного тока частотой до 200Гц или при напряжении соответственно 350, 750 И 1000В постоянного тока. Климатическое исполнение В, категория размещения 5 по ГОСТ 15150-69. </p><p><img alt="kugppnghf" loading="lazy" src="assets/img/products/kugeppnghf__14b14a75b62a9c22220b7068.jpg"/></p><ol><li>Токопроводящая жила – многопроволочная медная мягкая проволока. </li><li>Изоляция – полимерная композиция, не содержащая галогенов. </li><li>Экран – оплетка из медных луженых проволок. </li><li>Внутренняя оболочка - полимерная композиция, не содержащая галогенов </li></ol><p>Кабели <strong>КУГЭППнг-HF </strong>предназначены для эксплуатации в кабельных сооружениях и помещениях, в том числе для использования в системах АС класс 3 по классификации ОПБ-88/97 (ПНАЭ Г –01-011). </p><p><strong>Технические и эксплутационные характеристики КУГЭППнг-HF </strong><br/></p><p>Электрическая безопасность – ГОСТ 12.2.007-75 <br/>Нераспространение горения – ГОСТ Р МЭК 332-3-96, категория А. </p><table><tbody><tr><td><p>Температура окружающей среды при эксплуатации: </p></td><td><p>от +50 <sup>0 </sup>С до -50 <sup>0 </sup>С </p></td></tr><tr><td><p>Относительная влажность воздуха (при t <sup>0 </sup>+35 <sup>0 </sup>С): </p></td><td><p>98% </p></td></tr><tr><td><p>Длительно допустимая t <sup>0 </sup>нагрева жил при эксплуатации: </p></td><td><p>+70 <sup>0 </sup>С </p></td></tr><tr><td><p>Минимальная t <sup>0 </sup>прокладки кабеля без предварительного подогрева: </p></td><td><p>- 15 <sup>0 </sup>С </p></td></tr><tr><td><p>Предельная t <sup>0 </sup>токопроводящих жил кабелей по условию невозгорания кабеля при </p><p>коротком замыкании: </p></td><td><p>+400 <sup>0 </sup>С </p></td></tr><tr><td><p>Содержание газов галогеносодержащих кислот в пересчете на HCl : </p></td><td><p>5,0 мг/г </p></td></tr><tr><td><p>Показатель pH (кислотное число): </p></td><td><p>4,3 </p></td></tr><tr><td><p>Снижение светопроницаемости при горении и тлении: </p></td><td><p>не более 40%. </p></td></tr><tr><td><p>Минимально допустимый радиус изгиба при прокладке: </p></td><td><p>6 диам. кабеля </p></td></tr><tr><td><p>Срок службы </p></td><td><p>40 лет </p></td></tr><tr><td><p>Гарантийный срок эксплуатации </p></td><td><p>3 года </p></td></tr></tbody></table><p>Кабели не являются опасными в экологическом отношении и специальных требований по утилизации кабелей при выводе их эксплуатации, кроме предусмотренных в действующей на АС документации, не предъявляется </p><p><strong>Кабель соответствует требованиям ТУ 16К.71-338-2004 </strong></p><table><tbody><tr><td><strong>Число жил, сечение, мм <sup>2 </sup></strong></td><td><strong>Номинальный наружный диаметр, мм </strong></td><td><strong>Расчетная масса кг/км </strong></td></tr><tr><td>1 х0,35 </td><td>4,8 </td><td>34,7 </td></tr><tr><td>2 х0,35 </td><td>6,8 </td><td>59,8 </td></tr><tr><td>3 х0,35 </td><td>7,1 </td><td>72 </td></tr><tr><td>4 х0,35 </td><td>7,6 </td><td>85,9 </td></tr><tr><td>7 х0,35 </td><td>8,8 </td><td>125 </td></tr><tr><td>10 х0,35 </td><td>10,8 </td><td>170 </td></tr><tr><td>12 х0,35 </td><td>11,1 </td><td>193 </td></tr><tr><td>14 х0,35 </td><td>11,