INSERT INTO `products` (`id`,`category_id`,`root_category`,`name`,`slug`,`sku`,`short_description`,`description_html`,`image`,`unit`,`price`,`request_hint`,`active`,`featured`,`sort_order`,`seo_title`,`seo_description`,`source_file`,`specs_json`,`gallery_json`,`old_urls_json`) VALUES (767,20,'cable','КУПРУ, КУПРУ-П, КУПРУ-Пн','843-kupru-kupru-p-kupru-pn','MNP-0767','КУПРУ – кабели управления с медными многопроволочными экранированными или неэкранированными жилами с полиэтиленовой изоляцией в резиновой усиленной оболочке на номинальное напряжение до 250 В переменного тока частоты до 5 кГц.','<div><p>КУПРУ, КУПРУ-П, КУПРУ-Пн </p><p><img alt="kupr" loading="lazy" src="assets/img/products/kupr__3e5cea2b4b8382cde0dc33c9.jpg"/></p><p><strong>КУПРУ </strong>– кабели управления с медными многопроволочными экранированными или неэкранированными жилами с полиэтиленовой изоляцией в резиновой усиленной оболочке на номинальное напряжение до 250 В переменного тока частоты до 5 кГц. </p><p><strong>КУПРУ-П </strong>– то же, в панцирной оплетке из стальных оцинкованных проволок. </p><p><strong>КУПРУ-Пн </strong>– то же, в панцирной оплетке из стальных нержавеющих проволок. </p><table><tbody><tr><td><p>Марка </p></td><td><p>Число жил </p></td><td><p>Сечение, мм <sup>2 </sup></p></td></tr><tr><td rowspan="2"><p>КУПРУ, КУПРУ-П, КУПРУ-Пн </p></td><td><p>52э </p></td><td><p>0,35-0,5 </p></td></tr><tr><td><p>52-108 </p></td><td><p>0,35-0,5 </p></td></tr></tbody></table><p><strong>НАЗНАЧЕНИЕ И ТЕХНИЧЕСКИЕ ХАРАКТЕРИСТИКИ </strong></p><p>Кабели выдерживают 50 изгибов на угол +90˚ при радиусе изгиба, равном 3,5 диаметрам кабеля, 50 перемоток при радиусе изгиба, равном 3,5 диаметрам, и 100 перемоток при радиусе изгиба, равном 6 диаметрам кабеля, 50 осевых кручений на угол +180˚ на длине 1 м. Кабели стойки к вибрационным, ударным и линейным нагрузкам, а также к акустическим шумам. Кабели предназначены для работы в диапазоне температур от -50˚С до +70˚С. Допускается одноразовое использование при температуре до 1100˚С в течение 2 с. Кабели стойки к воздействию относительной влажности воздуха до 98% при температуре +35˚С, атмосферному пониженному рабочему давлению до 53 кПа, атмосферным осадкам (инею, росе), соляному туману и плесневым грибам. </p><p>Срок службы 15 лет </p><p><strong>Расшифровка кабеля КУПРУ: </strong><br/>К - Кабель <br/>У - Управления и контроля <br/>П - Изоляция жил из полиэтилена <br/>Р - Оболочка из резины <br/>У - Усиленная оболочка </p><p><strong>Элементы конструкции кабеля КУПРУ: </strong><br/>Кабель управления с токопроводящими жилами из медных проволок, изоляцией из полиэтилена, экраном в виде оплетки из медных луженых проволок, скруткой изолированных жил (экранированных и неэкранированных) концентрическими повивами, обмоткой полиамидной или полиэтилентерефталатной пленкой с перекрытием между повивами экранированных жил, оболочкой из двух слоев резины с промежуточной оплеткой из асбестовых нитей между внутренним и внешним слоями. </p><p><strong>Условия эксплуатации кабеля КУПРУ: </strong><br/>Предназначены для работы при номинальном переменном напряжении до 250 В частоты до 5000 Гц и постоянном напряжении до 350 В. <br/>Изменение температуры окружающей среды от минус 50 до 70°С. <br/>Относительная влажность воздуха до 98% при температуре 35°С (степень жесткости Х). <br/>Одноразовое воздействие температуры 1100°С в течение 20 с (без дальнейшего использования). <br/>Атмосферное рабочее давление до 5,3·10000 Па (400 мм рт. ст.). <br/>Допускаются монтажные изгибы кабелей при температуре среды минус 30°С. <br/>Кабели устойчивы к воздействию специальных факторов, атмосферных конденсируемых осадков (росы, инея), соляного (морского) тумана, плесневых грибов. <br/>Кабели выпускаются в климатическом исполнении В. <br/>Кабели соответствуют ТУ 16-505.926-81. </p><p><strong>Технические характеристики кабеля КУПРУ: </strong><br/>Электрическое сопротивление 1 км жилы постоянному току при температуре 20°С от значения при приемке и поставке, %, не более - 120 <br/>Испытательное напряжение изолированных жил частоты 50 Гц в течение 1 мин, В - 1000 <br/>Электрическое сопротивление 1 м изоляции кабеля, МОм, не менее - 103 <br/>Кабели выдерживают, циклов, не менее: <br/>- изгибов на угол +0,5 П рад по радиусу, равному 3,5 наружным диаметрам кабеля - 50 <br/>- перемоток при радиусе изгиба, равном 3,5 наружным диаметрам кабеля - 50 <br/>- перемоток при радиусе изгиба, равном 6 наружным диаметрам кабеля - 1000 <br/>- осевых кручений на угол +П рад на 1 м длины - 50 <br/>Минимальная наработка кабелей, ч - 10000 <br/>Минимальный срок службы и сохраняемости, лет - 15 <br/></p><p><strong>Расшифровка кабеля КУПРУ-П: </strong><br/>К - Кабель <br/>У - Управления и контроля <br/>П - Изоляция жил из полиэтилена <br/>Р - Оболочка из резины <br/>У - Усиленная оболочка <br/>П - Панцерная оплетка из стальных оцинкованных проволок </p><p><strong>Элементы конструкции кабеля КУПРУ-П: </strong><br/>кабеля КУПРУ-П с медными многопроволочными экранированными или неэкранированными жилами с полиэтиленовой изоляцией, в резиновой усиленной оболочке, в панцирной оплетке из стальных оцинкованных проволок на номинальное напряжение до 250 В переменного тока частоты до 5 кГц. </p><p><strong>Назначение и технические характеристики кабеля КУПРУ-П: </strong><br/>кабеля КУПРУ-П предназначен для работы при номинальном переменном напряжении до 250 В частоты до 5000 Гц и постоянном напряжении до 350 В и температуре от – 50°С до + 70°С. Допускается одноразовое использование при температуре до 1100°С в течение 2 с. <br/>кабеля КУПРУ-П выдерживает 50 изгибов на угол +90° при радиусе изгиба, равном 3,5 диаметрам кабеля кабеля КУПРУ-П, 50 перемоток при радиусе изгиба, равном 3,5 диаметрам кабеля кабеля КУПРУ-П, и 100 перемоток при радиусе изгиба, равном 6 диаметрам кабеля кабеля КУПРУ-П, 50 осевых кручений на угол +180° на длине 1м. <br/>кабеля КУПРУ-П стоек к вибрационным, ударным и линейным нагрузкам, а также к акустическим шумам. <br/>Допускается одноразовое использование при температуре до 1100°С в течение 2 с. <br/>кабеля КУПРУ-П стоек к воздействию относительной влажности воздуха до 98% при температуре +35°С, атмосферному пониженному рабочему давлению до 53 кПа, атмосферным осадкам (инею, росе), соляному туману и плесневым грибам. </p><p>Срок службы кабеля КУПРУ-П 15 лет. <br/></p><p><strong>Расшифровка кабеля КУПРУ-Пн: </strong><br/>К - Кабель <br/>У - Управления и контроля <br/>П - Изоляция жил из полиэтилена <br/>Р - Оболочка из резины <br/>У - Усиленная оболочка <br/>Пн - Панцерная оплетка из стальных нержавеющих проволок </p><p><strong>Элементы конструкции кабеля КУПРУ-Пн: </strong><br/>Кабели управления с медными многопроволочными экранированными или неэкранированными жилами с полиэтиленовой изоляцией, в резиновой усиленной оболочке, в панцирной оплетке из стальных нержавеющих проволок на номинальное напряжение до 250 В переменного тока частоты до 5 кГц. </p><p><strong>Назначение и технические характеристики кабеля КУПРУ-Пн: </strong><br/>Кабель предназначен для работы при номинальном переменном напряжении до 250 В частоты до 5000 Гц и постоянном напряжении до 350 В и температуре от – 50°С до + 70°С. Допускается одноразовое использование при температуре до 1100°С в течение 2 с. <br/>Кабель выдерживает 50 изгибов на угол +90° при радиусе изгиба, равном 3,5 диаметрам кабеля, 50 перемоток при радиусе изгиба, равном 3,5 кабельдиаметрам, и 100 перемоток при радиусе изгиба, равном 6 диаметрам, 50 осевых кручений на угол +180° на длине 1м. <br/>стоек к вибрационным, ударным и линейным нагрузкам, а также к акустическим шумам <br/>Допускается одноразовое использование при температуре до 1100°С в течение 2 с. <br/>Cтоек к воздействию относительной влажности воздуха до 98% при температуре +35°С, атмосферному пониженному рабочему давлению до 53 кПа, атмосферным осадкам (инею, росе), соляному туману и плесневым грибам. </p><p>Срок службы кабеля КУПРУ-Пн - 15 лет. </p></div>','assets/img/products/kupr__3e5cea2b4b8382cde0dc33c9.jpg','м',NULL,'Укажите марку, число и сечение жил, рабочее напряжение, длину и условия прокладки.',1,0,767,'КУПРУ, КУПРУ-П, КУПРУ-Пн — купить по заявке | Монополия','КУПРУ, КУПРУ-П, КУПРУ-Пн: подбор и поставка в Санкт-Петербурге. Укажите марку, число и сечение жил, рабочее напряжение, длину и условия прокладки. Расчет стоимости — по заявке.','site/www.monopoly-torg.ru/843-kupru-kupru-p-kupru-pn__a7f7eb141a92dd6818f20a8b.html','[["52-108", "0,35-0,5"]]','["assets/img/products/kupr__3e5cea2b4b8382cde0dc33c9.jpg"]','["http://www.monopoly-torg.ru/index.php/kabelnaya-produkciya/kabeli-upravleniya/843-kupru-kupru-p-kupru-pn"]') ON DUPLICATE KEY UPDATE `category_id`=VALUES(`category_id`),`root_category`=VALUES(`root_category`),`name`=VALUES(`name`),`slug`=VALUES(`slug`),`sku`=VALUES(`sku`),`short_description`=VALUES(`short_description`),`description_html`=VALUES(`description_html`),`image`=VALUES(`image`),`unit`=VALUES(`unit`),`price`=VALUES(`price`),`request_hint`=VALUES(`request_hint`),`active`=VALUES(`active`),`featured`=VALUES(`featured`),`sort_order`=VALUES(`sort_order`),`seo_title`=VALUES(`seo_title`),`seo_description`=VALUES(`seo_description`),`source_file`=VALUES(`source_file`),`specs_json`=VALUES(`specs_json`),`gallery_json`=VALUES(`gallery_json`),`old_urls_json`=VALUES(`old_urls_json`);
INSERT INTO `products` (`id`,`category_id`,`root_category`,`name`,`slug`,`sku`,`short_description`,`description_html`,`image`,`unit`,`price`,`request_hint`,`active`,`featured`,`sort_order`,`seo_title`,`seo_description`,`source_file`,`specs_json`,`gallery_json`,`old_urls_json`) VALUES (768,20,'cable','КУПЭВ, КУПЭВ-П, КУПЭВнг','844-kupev-kupev-p-kupevng','MNP-0768','Кабели управления, парной скрутки с полиэтиленовой изоляцией экранированные','<div><p>КУПЭВ, КУПЭВ-П, КУПЭВнг </p><p><strong>Кабели управления, парной скрутки с полиэтиленовой изоляцией экранированные <br/></strong></p><div><p><strong>Назначение </strong></p><p>Кабели предназначены для работы при номинальном переменном напряжении до 250 В частоты до 5 000 Гц или постоянном напряжении до 350 В. </p><p>Кабели марок КУПЭВ, КУПЭВ-П эксплуатируются в диапазоне температур от -50 до +70 °С. </p><p>Кабели стойки к воздействию относительной влажности до 98 % при температуре до +35 °С, к действию росы, инея, соляного тумана, динамической пыли (песка), плесневых грибов и многократным, до 100 раз, перегибам, к осевому кручению до 50 раз. </p><p>Монтажные работы разрешаются при температуре окружающей среды -30 °С при радиусе изгиба, равном 5 диаметрам кабеля. </p></div><p><img alt="kugv" loading="lazy" src="assets/img/products/kupev__dfe56a707e1fa83cc6861125.jpg"/></p><p><strong>КУПЭВ </strong>— кабель управления с изоляцией из полиэтилена, в общем экране, в оболочке из поливинилхлоридного пластиката. </p><p><strong>КУПЭВ-П </strong>— кабель управления с изоляцией из полиэтилена, в общем экране, в оболочке из поливинилхлоридного пластиката, в панцирной оплетке из стальных оцинкованных проволок. </p><p><strong>КУПЭВнг </strong>— кабель управления с изоляцией из полиэтилена, в общем экране, в оболочке из поливинилхлоридного пластиката пониженной горючести, не распространяет горение при прокладке в пучках, эксплуатируется при температуре от -50 до +50 °С. </p><p><strong>Сортамент и наружный диаметр </strong></p><table><tbody><tr><td rowspan="3"><strong>Марка кабеля </strong></td><td rowspan="3"><strong>Число пар и номинальное сечение жил, мм <sup>2 </sup></strong></td><td colspan="4"><strong>Наружный диаметр, мм </strong></td></tr><tr><td colspan="2"><strong>без панцирной оплетки </strong></td><td colspan="2"><strong>в панцирной оплетке </strong></td></tr><tr><td><strong>мин. </strong></td><td><strong>макс. </strong></td><td><strong>мин. </strong></td><td><strong>макс. </strong></td></tr><tr><td rowspan="16">КУПЭВ, КУПЭВ-П </td><td>2 x 2 x 0,35 </td><td>6,5 </td><td>9,2 </td><td>7,7 </td><td>10,4 </td></tr><tr><td>4 x 2 x 0,35 </td><td>7,5 </td><td>10,3 </td><td>8,7 </td><td>11,5 </td></tr><tr><td>7 x 2 x 0,35 </td><td>8,9 </td><td>11,8 </td><td>10,1 </td><td>13 </td></tr><tr><td>10 x 2 x 0,35 </td><td>11,1 </td><td>14,4 </td><td>12,3 </td><td>15,6 </td></tr><tr><td>14 x 2 x 0,35 </td><td>12,5 </td><td>16 </td><td>13,7 </td><td>17,2 </td></tr><tr><td>19 x 2 x 0,35 </td><td>14 </td><td>18 </td><td>15,2 </td><td>19,2 </td></tr><tr><td>27 x 2 x 0,35 </td><td>16,4 </td><td>21 </td><td>17,6 </td><td>22,2 </td></tr><tr><td>37 x 2 x 0,35 </td><td>18,6 </td><td>23,5 </td><td>19,8 </td><td>24,7 </td></tr><tr><td>2 x 2 x 0,50 </td><td>6,9 </td><td>9,6 </td><td>8,1 </td><td>10,2 </td></tr><tr><td>4 x 2 x 0,50 </td><td>7,8 </td><td>10,7 </td><td>9 </td><td>11,9 </td></tr><tr><td>7 x 2 x 0,50 </td><td>9,4 </td><td>12,3 </td><td>10,6 </td><td>13,5 </td></tr><tr><td>10 x 2 x 0,50 </td><td>11,7 </td><td>15,1 </td><td>12,9 </td><td>16,3 </td></tr><tr><td>14 x 2 x 0,50 </td><td>13,1 </td><td>16,8 </td><td>14,3 </td><td>18 </td></tr><tr><td>19 x 2 x 0,50 </td><td>14,7 </td><td>18,8 </td><td>15,9 </td><td>20 </td></tr><tr><td>27 x 2 x 0,50 </td><td>17,4 </td><td>22 </td><td>18,6 </td><td>23,2 </td></tr><tr><td>37 x 2 x 0,50 </td><td>19,6 </td><td>24,7 </td><td>20,8 </td><td>25,9 </td></tr></tbody></table><p><strong>Расчетная масса кабеля </strong></p><table><tbody><tr><td rowspan="2"><strong>Число пар и номинальное сечение жил, мм <sup>2 </sup></strong></td><td colspan="2"><strong>Масса кг/км </strong></td></tr><tr><td><strong>КУПЭВ </strong></td><td><strong>| КУПЭВ-П </strong></td></tr><tr><td>2 x 2 x 0,35 </td><td>93 </td><td>140 </td></tr><tr><td>4 x 2 x 0,35 </td><td>131 </td><td>186 </td></tr><tr><td>7 x 2 x 0,35 </td><td>180 </td><td>244 </td></tr><tr><td>10 x 2 x 0,35 </td><td>230 </td><td>302 </td></tr><tr><td>14 x 2 x 0,35 </td><td>306 </td><td>389 </td></tr><tr><td>19 x 2 x 0,35 </td><td>389 </td><td>483 </td></tr><tr><td>27 x 2 x 0,35 </td><td>503 </td><td>610 </td></tr><tr><td>37 x 2 x 0,35 </td><td>650 </td><td>771 </td></tr><tr><td>2 x 2 x 0,50 </td><td>101 </td><td>150 </td></tr><tr><td>4 x 2 x 0,50 </td><td>146 </td><td>204 </td></tr><tr><td>7 x 2 x 0,50 </td><td>205 </td><td>271 </td></tr><tr><td>10 x 2 x 0,50 </td><td>264 </td><td>340 </td></tr><tr><td>14 x 2 x 0,50 </td><td>352 </td><td>440 </td></tr><tr><td>19 x 2 x 0,50 </td><td>451 </td><td>550 </td></tr><tr><td>27 x 2 x 0,50 </td><td>587 </td><td>700 </td></tr><tr><td>37 x 2 x 0,50 </td><td>764 </td><td>890 </td></tr></tbody></table><p>Электрическое сопротивление изоляции , пересчитанное на 1 м длины и температуру +20 °С, — не менее 103 МОм. </p><p>Строительная длина кабелей <strong>КУПЭВ </strong>и <strong>КУПЭВ-П </strong>— 150 м. </p><p>Срок службы —22 года. </p><p>Гарантийный срок эксплуатации кабелей <strong>КУПЭВ </strong>, КУПЭВ-П — 22 года и исчисляется со дня приемки представителем заказчика. <br/></p><p><strong>Расшифровка кабеля КУПЭВ: </strong><br/>К - Кабель <br/>У - Управления и контроля <br/>П - Изоляция жил из полиэтилена <br/>Э - Экран в виде оплетки или обмотки из медных проволок <br/>В - Оболочка из поливинилхлоридного пластиката <strong>Элементы конструкции кабеля КУПЭВ: </strong><br/>1. Медная токопроводящая жила 7x0,30. <br/>2. Полиэтиленовая изоляция. <br/>3. Пленка ПЭТ-Э. <br/>4. Оплетка медная. <br/>5. Оболочка из ПВХ пластиката. <strong>Область применения кабеля КУПЭВ: </strong><br/>Кабели предназначены для работы при номинальном переменном напряжении до 250 В частоты до 5000 Гц или постоянном напряжении до 350 В. <br/>Кабели эксплуатируются в диапазоне температур от -50°С до +70°С. <br/>Кабели стойки к воздействию относительной влажности до 98% при температуре до +35°С, к действию росы, инея, соляного тумана, динамической пыли (песка), плесневых грибов и многократным, до 100 раз, перегибам, к осевому кручению до 50 раз. <br/>Монтажные работы разрешаются при температуре окружающей среды -30°С при радиусе изгиба, равном 5 диаметрам кабеля. <strong>Технические характеристики кабеля КУПЭВ: </strong><br/>Электрическое сопротивление изоляции, пересчитанное на 1 км длины и температуру +20°С — не менее 10 МОм. <br/>Срок службы кабеля КУПЭВ — 22 года. <br/>Строительная длина — 150 м. <br/>Пример условного обозначения: кабель КУПЭВ-П (2в2 в 0,50)э — 250 ТУ 16.705.096—79. </p><p><strong>Расшифровка кабеля КУПЭВ-П: </strong><br/>К - Кабель <br/>У - Управления и контроля <br/>П - Изоляция жил из полиэтилена <br/>Э - Экран в виде оплетки или обмотки из медных проволок <br/>В - Оболочка из поливинилхлоридного пластиката <br/>П - Панцерная оплетка из стальных оцинкованных проволок <strong>Элементы конструкции кабеля КУПЭВ-П: </strong><br/>1 - токопроводящая жила <br/>2 - изоляция <br/>3 - обмотка <br/>4 - экран <br/>5 - оболочка Кабели управления парной скрутки с изоляцией из полиэтилена в общем экране, в оболочке из ПВХ пластиката, в панцирной оплётке из стальных оцинкованных проволок. <strong>Назначение и технические характеристики кабеля КУПЭВ-П: </strong><br/>Кабель предназначен для работы при номинальном переменном напряжении до 250 В частоты до 5000 Гц и постоянном напряжении до 350 В и температуре от – 50°С до + 70°С. Кабель выдерживает 100 циклов перемоток при радиусе изгиба, равном 5 наружным диаметрам кабеля, 50 осевых кручений на угол + 180° на длине 1м. <br/>Устойчив к вибрационным, ударным и линейным нагрузкам, а также к акустическим шумам, воздействию относительной влажности воздуха до 98% при температуре +35°С, пониженному рабочему атмосферному давлению до 53 кПа, соляному туману, динамической пыли. <br/>Строительная длина кабеля: <br/>- с числом пар до 14 не менее 100 м; <br/>- с числом пар до 30 не менее 150 м; <br/>- с числом пар до 52 не менее 43 м. <br/>Срок службы кабеля КУПЭВ-П - 22 года. <br/></p><p><strong>Расшифровка кабеля КУПЭВнг: </strong><br/>К - Кабель <br/>У - Управления и контроля <br/>П - Изоляция жил из полиэтилена <br/>Э - Экран в виде оплетки или обмотки из медных проволок <br/>Внг - Оболочка из поливинилхлоридного пластиката пониженной горючести <strong>Элементы конструкции кабеля КУПЭВнг: </strong><br/>Кабель управления с изоляцией из полиэтилена, в общем экране, в оболочке из поливинил-хлоридного пластиката пониженной горючести. <strong>Область применения кабеля КУПЭВнг: </strong><br/>Кабели предназначены для работы при номинальном переменном напряжении до 250 В частоты до 5000 Гц или постоянном напряжении до 350 В. <br/>Кабели эксплуатируются в диапазоне температур от -50°С до +70°С. <br/>Кабели стойки к воздействию относительной влажности до 98% при температуре до +35°С, к действию росы, инея, соляного тумана, динамической пыли (песка), плесневых грибов и многократным, до 100 раз, перегибам, к осевому кручению до 50 раз. <br/>Монтажные работы разрешаются при температуре окружающей среды -30°С при радиусе изгиба, равном 5 диаметрам кабеля. <strong>Технические характеристики кабеля КУПЭВнг: </strong><br/>Электрическое сопротивление изоляции, пересчитанное на 1 км длины и температуру +20°С — не менее 10 МОм. Срок службы кабеля КУПЭВнг — 22 года. </p><p><strong>Расшифровка кабеля КУПЭВнг-LS: </strong><br/>К - Кабель <br/>У - Управления и контроля <br/>П - Изоляция жил из полиэтилена <br/>Э - Экран в виде оплетки или обмотки из медных проволок <br/>Внг-LS - Оболочка из поливинилхлоридного пластиката пониженной горючести с пониженным газо- дымовыделением <strong>Элементы конструкции кабеля КУПЭВнг-LS: </strong><br/>Токопроводящая жила – скрученная из медных проволок <br/>Изоляция жил – полиэтилен <br/>Поясная изоляция – ПЭТ-Э лента <br/>Экран – алюмофлекс Защитная оболочка – поливинилхлоридная композиция пониженной пожароопасности <strong>Область применения кабеля КУПЭВнг-LS: </strong><br/>Кабели предназначены стационарной прокладки и передачи электрических сигналов малой мощности в цепях управления, контроля и информации с номинальным переменным напряжением до 250 В частоты 5 кГц или постоянным напряжением 350 В. Условия эксплуатации кабеля КУПЭВнг-LS: от – 50°С до + 70° С <br/>Строительная длина кабеля КУПЭВнг-LS, м, не менее 100 <br/></p></div>','assets/img/products/kupev__dfe56a707e1fa83cc6861125.jpg','м',NULL,'Укажите марку, число и сечение жил, рабочее напряжение, длину и условия прокладки.',1,0,768,'КУПЭВ, КУПЭВ-П, КУПЭВнг — купить по заявке | Монополия','КУПЭВ, КУПЭВ-П, КУПЭВнг: подбор и поставка в Санкт-Петербурге. Укажите марку, число и сечение жил, рабочее напряжение, длину и условия прокладки. Расчет стоимости — по заявке.','site/www.monopoly-torg.ru/844-kupev-kupev-p-kupevng__ebca44547be9a1c63d77ab7c.html','[["без панцирной оплетки", "в панцирной оплетке"], ["Число пар и номинальное сечение жил, мм 2", "Масса кг/км"], ["КУПЭВ", "| КУПЭВ-П"]]','["assets/img/products/kupev__dfe56a707e1fa83cc6861125.jpg"]','["http://www.monopoly-torg.ru/index.php/kabelnaya-produkciya/kabeli-upravleniya/844-kupev-kupev-p-kupevng"]') ON DUPLICATE KEY UPDATE `category_id`=VALUES(`category_id`),`root_category`=VALUES(`root_category`),`name`=VALUES(`name`),`slug`=VALUES(`slug`),`sku`=VALUES(`sku`),`short_description`=VALUES(`short_description`),`description_html`=VALUES(`description_html`),`image`=VALUES(`image`),`unit`=VALUES(`unit`),`price`=VALUES(`price`),`request_hint`=VALUES(`request_hint`),`active`=VALUES(`active`),`featured`=VALUES(`featured`),`sort_order`=VALUES(`sort_order`),`seo_title`=VALUES(`seo_title`),`seo_description`=VALUES(`seo_description`),`source_file`=VALUES(`source_file`),`specs_json`=VALUES(`specs_json`),`gallery_json`=VALUES(`gallery_json`),`old_urls_json`=VALUES(`old_urls_json`);
INSERT INTO `products` (`id`,`category_id`,`root_category`,`name`,`slug`,`sku`,`short_description`,`description_html`,`image`,`unit`,`price`,`request_hint`,`active`,`featured`,`sort_order`,`seo_title`,`seo_description`,`source_file`,`specs_json`,`gallery_json`,`old_urls_json`) VALUES (769,20,'cable','КУПЭР, КУПЭР-П, КУПЭР-Пн','845-kuper-kuper-p-kuper-pn','MNP-0769','КУПЭР – кабели управления парной скрутки с изоляцией из полиэтилена в общем экране, в резиновой оболочке.','<div><p>КУПЭР, КУПЭР-П, КУПЭР-Пн </p><p><strong>КУПЭР </strong>– кабели управления парной скрутки с изоляцией из полиэтилена в общем экране, в резиновой оболочке. </p><p><strong>КУПЭР-П </strong>– то же, в панцирной оплетке из стальных оцинкованных проволок. </p><p><strong>КУПЭР-Пн </strong>– то же, в панцирной оплетке из стальных нержавеющих проволок. </p><p><img alt="kugpepnghf" loading="lazy" src="assets/img/products/kuper__c0d01eeb9454cfed564b57c6.jpg"/></p><p><strong>Элементы конструкции </strong></p><ul><li>медные многопроволочные жилы класса 4; </li><li>изоляция из полиэтилена; </li><li>(жилы скручены в пары); </li><li>обмотка полиэтилентерефталатной пленкой ПЭТ-Э ; </li><li>общий экран оплеткой или обмоткой из медных проволок (э), либо общий экран обмоткой фольгированной пленкой (эф); </li><li>наружная оболочка из резины </li></ul><p><strong>Назначение и технические характеристики <br/></strong></p><p>Кабели предназначены для работы при номинальном напряжении до 250 В частоты до 5000 Гц и постоянном напряжении до 350 В и температуре от -50˚С до +70˚С. Кабели выдерживают 100 перемоток при радиусе изгиба, равном 5 диаметрам кабеля, 50 осевых кручений на угол +180˚ на длине 1 м, устойчивы к вибрационным, ударным и линейным нагрузкам, а также к акустическим шумам, воздействию относительной влажности воздуха до 98% при температуре +35˚С, атмосферному пониженному рабочему давлению до 53 кПа, соляному туману. </p><p>Строительная длина кабелей: </p><p>- с числом пар до 14, не менее 100 м </p><p>- с числом пар до 30, не менее 150 м </p><p>- с числом пар до 52, не менее 43 м </p><p>Срок службы 22 года </p><p><strong>Расшифровка кабеля КУПЭР: </strong><br/>К - Кабель <br/>У - Управления и контроля <br/>П - Изоляция жил из полиэтилена <br/>Э - Экран в виде оплетки или обмотки из медных проволок <br/>Р - Оболочка из резины </p><p><strong>Элементы конструкции кабеля КУПЭР: </strong><br/>1.Токопроводящая жила - из меди <br/>2.Изоляция из полиэтилена <br/>3.Резиновая оболочка <br/>4.Экран пар состоит из медной оплетки </p><p><strong>Область применения кабеля КУПЭР: </strong><br/>Кабель управления парной скрутки. Работает при номинальном напряжении до 250 В с частотой 5000 Гц, постоянное напряжение до 350 В. Устойчив к вибрационным, линейным и ударным нагрузкам, акустическим шумам, а так же к атмосферным осадкам, туманам и плесневым грибкам. <br/>Длина от 43(до 52 пар жил) до 100 метров(число пар до 14). </p><p><strong>Условия эксплуатации кабеля КУПЭР: </strong><br/>Температура кабеля КУПЭР: от - 50 до +70 С <br/>Атмосферное давление: 400 мм. рт. стобла <br/>Электрическое сопротивление: 1000000 МОм <br/>Выдерживает давление до 53 кПа <br/>Влажность воздуха до 98% <br/>Срок службы кабеля КУПЭР - 22 года <br/></p><p><strong>Расшифровка кабеля КУПЭР-П: </strong><br/>К - Кабель <br/>У - Управления и контроля <br/>П - Изоляция жил из полиэтилена <br/>Э - Экран в виде оплетки или обмотки из медных проволок <br/>Р - Оболочка из резины <br/>П - Панцерная оплетка из стальных оцинкованных проволок </p><p><strong>Элементы конструкции кабеля КУПЭР-П: </strong><br/>1 - токопроводящая жила <br/>2 - изоляция <br/>3 - обмотка <br/>4 - экран <br/>5 - оболочка </p><p>Кабели управления парной скрутки с изоляцией из полиэтилена в общем экране, в резиновой оболочке, в панцирной оплётке из стальных оцинкованных проволок. </p><p><strong>Назначение и технические характеристики кабеля КУПЭР-П: </strong><br/>Кабель предназначен для работы при номинальном переменном напряжении до 250 В частоты до 5000 Гц и постоянном напряжении до 350 В и температуре от – 50°С до + 70°С. <br/>Кабель выдерживает 100 циклов перемоток при радиусе изгиба, равном 5 диаметрам кабеля, 50 осевых кручений на угол + 180° на длине 1м. <br/>Устойчив к вибрационным, ударным и линейным нагрузкам, а также к акустическим шумам, воздействию относительной влажности воздуха до 98% при температуре +35°С, атмосферному пониженному рабочему давлению до 53 кПа, соляному туману. <br/>Строительная длина кабеля: <br/>- с числом пар до 14 не менее 100 м; <br/>- с числом пар до 30 не менее 150 м; <br/>- с числом пар до 52 не менее 43 м. <br/>Срок службы кабеля КУПЭР-П - 15 лет. <br/></p><p><strong>Расшифровка кабеля КУПЭР-Пн: </strong><br/>К - Кабель <br/>У - Управления и контроля <br/>П - Изоляция жил из полиэтилена <br/>Э - Экран в виде оплетки или обмотки из медных проволок <br/>Р - Оболочка из резины <br/>Пн - Панцерная оплетка из стальных нержавеющих проволок </p><p><strong>Элементы конструкции кабеля КУПЭР-Пн: </strong><br/>Кабель управления с изоляцией из полиэтилена в общем экране в оболочке из резины, в панцирной оплетке из стальных нержавеющих проволок. </p><p>Токопроводящая жила - из медных проволок; ГОСТ 22483-77, класс 4-й. <br/>Изоляция - полиэтилен высокой плотности; номинальная толщина изоляции при сечении жил 0,35 мм <sup>2 </sup>- 0,31 мм, при сечении 0,5 мм <sup>2 </sup>- 0,30 мм, минимальная для жил всех сечений - 0,2 мм. <br/>Скрутка - в пары; шаг скрутки 70 мм; <br/>Пары скручены в кабель; в каждом повиве одна жила в счетной паре отличается по цвету. <br/>Обмотка - полиамидной или полиэтилентерефталатной пленкой с перекрытием по наружному повиву. <br/>Экран - в виде обмотки или оплетки из медных луженых проволок <br/>диаметр проволок - не более 0,30 мм. <br/>Обмотка - из полиамидной или полиэтилентерефталатной пленки с перекрытием. <br/>Оболочка - из резины. <br/>Оплетка - панцирная из стальных нержавеющих проволок <br/>диаметр проволок - не более 0,30 мм. </p><p><strong>Условия эксплуатации кабеля КУПЭР-Пн: </strong><br/>Максимальная рабочая температура 70°С. <br/>Пониженная рабочая температура среды, при которой допускаются монтажные изгибы - минус 50°С; <br/>Атмосферное пониженное рабочее давление - 5,3·10 <sup>4 </sup>Па (400 мм рт. ст.). <br/>Повышенная относительная влажность воздуха до 98% при температуре 35°С. <br/>Степень жесткости Х. <br/>Кабели устойчивы к воздействию специальных факторов, динамической пыли, соляного тумана, кабели устойчивы к плесневым грибам. <br/>Кабели с отличительным индексом 0 стойки к воздействию паров амила и гептила. <br/>Кабели выпускаются в климатическом исполнении В. <br/>Кабели соответствуют ТУ 16-705.096-79. </p><p><strong>Технические характеристики кабеля КУПЭР-Пн: </strong><br/>Электрическое сопротивление токопроводящих жил постоянному току , пересчитанное на 1 км длины и температуру 20°С, Ом: для жилы сечением 0,35 мм <sup>2 </sup>- 66,6 для жилы сечением 0,50 мм <sup>2 </sup>- 50,0 <br/>Электрическое сопротивление изоляции жил, пересчитанное на 1 м длины, МОм, не менее - 10 <sup>3 </sup><br/>Изолированные жилы выдерживают в течение 1 мин испытание напряжением 1000 В частоты 50 Гц. <br/>Кабели выдерживают не менее 100 циклов перемоток при радиусе изгиба, равном 5 наружным диаметрам кабеля. <br/>Кабели выдерживают не менее 50 осевых кручений на угол + рад/м. <br/>Минимальная наработка кабелей, ч, - 10000 <br/>в том числе: для кабелей с индексом 0 в диапазоне рабочих температур от минус 50 до 50°С - 45000 <br/>Минимальный срок службы кабеля КУПЭР-Пн - 22 года <br/>95%-ный ресурс кабелей при температуре 70°С, ч - 20000 </p><table><tbody><tr><th>Число и диаметр жил, шт х кв.мм </th><th>Масса кабеля, кг/км </th><th>Максимальный наружный диаметр, мм </th></tr><tr><td>КУПЭР (2х2х0,35)э </td><td>104 </td><td>9,5 </td></tr><tr><td>КУПЭР (4х2х0,35)э </td><td>144 </td><td>11 </td></tr><tr><td>КУПЭР (7х2х0,35)э </td><td>205 </td><td>13,2 </td></tr><tr><td>КУПЭР (10х2х0,35)э </td><td>258 </td><td>15 </td></tr><tr><td>КУПЭР (14х2х0,35)э </td><td>332 </td><td>17 </td></tr><tr><td>КУПЭР (19х2х0,35)э </td><td>419 </td><td>19,1 </td></tr><tr><td>КУПЭР (27х2х0,35)э </td><td>536 </td><td>21,6 </td></tr><tr><td>КУПЭР (37х2х0,35)э </td><td>671 </td><td>24,2 </td></tr><tr><td>КУПЭР (52х2х0,35)э </td><td>889 </td><td>28 </td></tr><tr><td>КУПЭР (2х2х0,35)эф </td><td>78 </td><td>9,5 </td></tr><tr><td>КУПЭР (4х2х0,35)эф </td><td>105 </td><td>11 </td></tr><tr><td>КУПЭР (7х2х0,35)эф </td><td>155 </td><td>13,2 </td></tr><tr><td>КУПЭР (10х2х0,35)эф </td><td>214 </td><td>15 </td></tr><tr><td>КУПЭР (14х2х0,35)эф </td><td>272 </td><td>17 </td></tr><tr><td>КУПЭР (19х2х0,35)эф </td><td>341 </td><td>19,1 </td></tr><tr><td>КУПЭР (27х2х0,35)эф </td><td>447 </td><td>21,6 </td></tr><tr><td>КУПЭР (37х2х0,35)эф </td><td>565 </td><td>24,2 </td></tr><tr><td>КУПЭР (52х2х0,35)эф </td><td>766 </td><td>28 </td></tr><tr><td>КУПЭР (2х2х0,50)э </td><td>113 </td><td>9,6 </td></tr><tr><td>КУПЭР (4х2х0,50)э </td><td>160 </td><td>11,4 </td></tr><tr><td>КУПЭР (7х2х0,50)э </td><td>231 </td><td>13,7 </td></tr><tr><td>КУПЭР (10х2х0,50)э </td><td>293 </td><td>15,6 </td></tr><tr><td>КУПЭР (14х2х0,50)э </td><td>380 </td><td>17,7 </td></tr><tr><td>КУПЭР (19х2х0,50)э </td><td>481 </td><td>20 </td></tr><tr><td>КУПЭР (27х2х0,50)э </td><td>622 </td><td>22,7 </td></tr><tr><td>КУПЭР (37х2х0,50)э </td><td>804 </td><td>25,8 </td></tr><tr><td>КУПЭР (52х2х0,50)э </td><td>1046 </td><td>29,4 </td></tr><tr><td>КУПЭР (2х2х0,50)эф </td><td>86 </td><td>9,6 </td></tr><tr><td>КУПЭР (4х2х0,50)эф </td><td>120 </td><td>11,4 </td></tr><tr><td>КУПЭР (7х2х0,50)эф </td><td>179 </td><td>13,7 </td></tr><tr><td>КУПЭР (10х2х0,50)эф </td><td>236 </td><td>15,6 </td></tr><tr><td>КУПЭР (14х2х0,50)эф </td><td>311 </td><td>17,7 </td></tr><tr><td>КУПЭР (19х2х0,50)эф </td><td>400 </td><td>20 </td></tr><tr><td>КУПЭР (27х2х0,50)эф </td><td>530 </td><td>22,7 </td></tr><tr><td>КУПЭР (37х2х0,50)эф </td><td>695 </td><td>25,8 </td></tr><tr><td>КУПЭР (52х2х0,50)эф </td><td>922 </td><td>29,4 </td></tr></tbody></table></div>','assets/img/products/kuper__c0d01eeb9454cfed564b57c6.jpg','м',NULL,'Укажите марку, число и сечение жил, рабочее напряжение, длину и условия прокладки.',1,0,769,'КУПЭР, КУПЭР-П, КУПЭР-Пн — купить по заявке | Монополия','КУПЭР, КУПЭР-П, КУПЭР-Пн: подбор и поставка в Санкт-Петербурге. Укажите марку, число и сечение жил, рабочее напряжение, длину и условия прокладки. Расчет стоимости — по заявке.','site/www.monopoly-torg.ru/845-kuper-kuper-p-kuper-pn__5b1bfb98d31fe1af4d03c53a.html','[]','["assets/img/products/kuper__c0d01eeb9454cfed564b57c6.jpg"]','["http://www.monopoly-torg.ru/index.php/kabelnaya-produkciya/kabeli-upravleniya/845-kuper-kuper-p-kuper-pn"]') ON DUPLICATE KEY UPDATE `category_id`=VALUES(`category_id`),`root_category`=VALUES(`root_category`),`name`=VALUES(`name`),`slug`=VALUES(`slug`),`sku`=VALUES(`sku`),`short_description`=VALUES(`short_description`),`description_html`=VALUES(`description_html`),`image`=VALUES(`image`),`unit`=VALUES(`unit`),`price`=VALUES(`price`),`request_hint`=VALUES(`request_hint`),`active`=VALUES(`active`),`featured`=VALUES(`featured`),`sort_order`=VALUES(`sort_order`),`seo_title`=VALUES(`seo_title`),`seo_description`=VALUES(`seo_description`),`source_file`=VALUES(`source_file`),`specs_json`=VALUES(`specs_json`),`gallery_json`=VALUES(`gallery_json`),`old_urls_json`=VALUES(`old_urls_json`);
INSERT INTO `products` (`id`,`category_id`,`root_category`,`name`,`slug`,`sku`,`short_description`,`description_html`,`image`,`unit`,`price`,`request_hint`,`active`,`featured`,`sort_order`,`seo_title`,`seo_description`,`source_file`,`specs_json`,`gallery_json`,`old_urls_json`) VALUES (770,20,'cable','СПОЭВнг-HF, СПОЭВЭнг-HF','846-spoevng-hf-spoeveng-hf','MNP-0770','СПОЭВнг-HF, СПОЭВЭнг-HF для промышленных, строительных и энергетических объектов.','<div><p>СПОЭВнг-HF, СПОЭВЭнг-HF </p><h2>Кабели контрольные и управления с пластмассовой изоляцией и оболочкой, с отдельно экранированными жилами </h2><p><img alt="SPOEVng-HF" loading="lazy" src="assets/img/products/SPOEVng-HF__47d6eea9fad540257f1547ad.jpg"/></p><p><strong>Конструкция </strong></p><table><tbody><tr><td>Токопроводящая жила </td><td>Медная многопроволочная </td></tr><tr><td>Изоляция </td><td>Сшитый полиэтилен <br/>типа HF XLPE </td></tr><tr><td>Экран жил </td><td>Медные проволоки </td></tr><tr><td>заполнитель </td><td>Безгалогенная композиция </td></tr><tr><td>Обмотка </td><td>Полиэтилентерефталатная пленка </td></tr><tr><td>Общий экран кабеля СПОЭвЭнг-HF </td><td>Медные проволоки </td></tr><tr><td>Обмотка </td><td>Полиэтилентерефталатная пленка </td></tr></tbody></table><p><strong>Оболочка </strong></p><table><tbody><tr><td>Материалы </td><td>МЭК 60228 Класс 2 (жила) МЭК 60092-351 (изоляция) МЭК 60092-359 (оболочка) </td></tr><tr><td>Нераспространение горения </td><td>МЭК 60332-3-22 (кат. А) и МЭК 60332-1 </td></tr><tr><td>Отсутствие галогенов </td><td>МЭК 60754-2 </td></tr><tr><td>Малое выделение дыма </td><td>МЭК 61034-2 </td></tr><tr><td>Максимальная температура нагрева токопроводящей жилы </td><td>+90°С </td></tr><tr><td>Срок службы </td><td>30 лет </td></tr></tbody></table></div>','assets/img/products/SPOEVng-HF__47d6eea9fad540257f1547ad.jpg','м',NULL,'Укажите марку, число и сечение жил, рабочее напряжение, длину и условия прокладки.',1,0,770,'СПОЭВнг-HF, СПОЭВЭнг-HF — купить по заявке | Монополия','СПО