INSERT INTO `products` (`id`,`category_id`,`root_category`,`name`,`slug`,`sku`,`short_description`,`description_html`,`image`,`unit`,`price`,`request_hint`,`active`,`featured`,`sort_order`,`seo_title`,`seo_description`,`source_file`,`specs_json`,`gallery_json`,`old_urls_json`) VALUES (775,21,'cable','А Провод неизолированный','619-a-provod-neizolirovannyj','MNP-0775','Провода предназначены для передачи электрической энергии в воздушных электрических сетях (ЛЭП).','<div><p>А Провод неизолированный </p><p><img alt="a" loading="lazy" src="assets/img/products/a__3b32e4c222155416ffd87343.jpg"/></p><ol><li>Алюминиевая проволока. </li></ol><p><strong>Область применения провода неизолированного А: </strong></p><p>Провода предназначены для передачи электрической энергии в воздушных электрических сетях (ЛЭП). </p><p>Провода применяются для эксплуатации на суше в районах с умеренным и холодным климатом. Прокладываются в атомсфере с содержанием сернистого газа не более 150 мг/м3 х сут. и хлоридов менее 0,3 мг/м3 х сут. Длительно-допустимая температура проводов в процессе эксплуатации не должна превышать плюс 90°С. </p><p>Срок службы — 45 лет. Гарантийный срок эксплуатации — 4 года с момента ввода в эксплуатацию. </p><table><tbody><tr><td><strong>Сечение, <br/>кв.мм </strong></td><td><strong>Масса <br/>провода, <br/>кг/км </strong></td><td><strong>Наружный <br/>диаметр, мм </strong></td><td><strong>Разрывное <br/>усилие провода, <br/>не менее Н </strong></td><td><strong>Строительная <br/>длина, <br/>не менее м </strong></td></tr><tr><td>А 16 </td><td>43 </td><td>5,1 </td><td>3021 </td><td>4500 </td></tr><tr><td>А 25 </td><td>68 </td><td>6,4 </td><td>4500 </td><td>4000 </td></tr><tr><td>А 35 </td><td>94 </td><td>7,5 </td><td>5913 </td><td>4000 </td></tr><tr><td>А 50 </td><td>135 </td><td>9 </td><td>8198 </td><td>3500 </td></tr><tr><td>А 70 </td><td>189 </td><td>10,7 </td><td>11080 </td><td>2500 </td></tr><tr><td>А 95 </td><td>252 </td><td>12,3 </td><td>14784 </td><td>2000 </td></tr><tr><td>А 120 </td><td>321 </td><td>14 </td><td>19890 </td><td>1500 </td></tr><tr><td>А 150 </td><td>406 </td><td>15,8 </td><td>24420 </td><td>1250 </td></tr><tr><td>А 185 </td><td>502 </td><td>17,5 </td><td>29832 </td><td>1000 </td></tr><tr><td>А 240 </td><td>655 </td><td>20 </td><td>38192 </td><td>1000 </td></tr><tr><td>А 300 </td><td>794 </td><td>22,1 </td><td>47569 </td><td>1000 </td></tr></tbody></table><table><tbody><tr><td colspan="3">Таблица перевода неизолированного провода км/тн </td></tr><tr><td>Марка провода </td><td>Сечение </td><td>Коэффициент перевода км/тн </td></tr><tr><td>А </td><td>16 </td><td>23,105 </td></tr><tr><td>А </td><td>25 </td><td>14,718 </td></tr><tr><td>А </td><td>35 </td><td>10,684 </td></tr><tr><td>А </td><td>50 </td><td>7,419 </td></tr><tr><td>А </td><td>70 </td><td>5,298 </td></tr><tr><td>А </td><td>95 </td><td>3,972 </td></tr><tr><td>А </td><td>120 </td><td>3,114 </td></tr><tr><td>А </td><td>150 </td><td>2,46 </td></tr><tr><td>А </td><td>185 </td><td>1,993 </td></tr><tr><td>А </td><td>240 </td><td>1,526 </td></tr><tr><td>А </td><td>300 </td><td>1,26 </td></tr></tbody></table></div>','assets/img/products/a__3b32e4c222155416ffd87343.jpg','м',NULL,'Укажите марку, число и сечение жил, рабочее напряжение, длину и условия прокладки.',1,0,775,'А Провод неизолированный — купить по заявке | Монополия','А Провод неизолированный: подбор и поставка в Санкт-Петербурге. Укажите марку, число и сечение жил, рабочее напряжение, длину и условия прокладки. Расчет стоимости — по заявке.','site/www.monopoly-torg.ru/619-a-provod-neizolirovannyj__c58f23a6b0112a5c182ad1dc.html','[]','["assets/img/products/a__3b32e4c222155416ffd87343.jpg"]','["http://www.monopoly-torg.ru/index.php/kabelnaya-produkciya/provoda/619-a-provod-neizolirovannyj"]') ON DUPLICATE KEY UPDATE `category_id`=VALUES(`category_id`),`root_category`=VALUES(`root_category`),`name`=VALUES(`name`),`slug`=VALUES(`slug`),`sku`=VALUES(`sku`),`short_description`=VALUES(`short_description`),`d