INSERT INTO `products` (`id`,`category_id`,`root_category`,`name`,`slug`,`sku`,`short_description`,`description_html`,`image`,`unit`,`price`,`request_hint`,`active`,`featured`,`sort_order`,`seo_title`,`seo_description`,`source_file`,`specs_json`,`gallery_json`,`old_urls_json`) VALUES (799,21,'cable','МКЭШВнг','643-mkeshvng','MNP-0799','МКЭШВнг для промышленных, строительных и энергетических объектов.','<div><p>МКЭШВнг </p>Кабель МКЭШВнг монтажный многожильный с пластмассовой изоляцией. <p><img alt="a" loading="lazy" src="assets/img/products/mkesh_14_5__b9183c85f9574c096d9a8fc7.jpg"/></p><p><strong>Конструкция кабелей МКЭШВнг </strong><br/></p><ol><li>Токопроводящая жила - медная, многопроволочная, класс по ГОСТ 22483. </li><li>Изоляция - из поливинилхлоридного пластиката пониженной горючести (ПВХ). </li><li>Скрученная пара - в кабелях парной скрутки. </li><li>Экран пар - из медных проволок диаметром не более 0,2 мм в виде оплетки плотностью не менее 65%. Под оплеткой – лента ПЭТ-Э. Пары жил с индексом "Э” должны иметь индивидуальные экраны в виде оплетки - для кабелей МКЭШВ(э). Под оплеткой – лента ПЭТ-Э. </li><li>Сердечник - одиночные жилы или пары скрученные в сердечник. </li><li>Поясная изоляция - лента полиэтилентерефталатная. </li><li>Экран (кроме кабелей с индексом "Э”) - оплетка из медных проволок диаметром не более 0,25 мм. Коэффициент плотности оплетки – не менее 65%. </li><li>Оболочка промежуточная - из ПВХ пластика толщиной не менее 0,8 мм. </li><li>Защитный шланг - их ПВХ пластиката пониженной горючести . </li></ol><div><strong>Применение кабелей МКЭШВнг </strong>Кабели <strong>МКЭШВнг </strong>предназначены для передачи электрических сигналов управления, контроля, сигнализации, регулирования электрического оборудования и устройств, а также для межприборного монтажа электрических установок, работающих при переменном напряжении до 750 В, в условиях повышенных внешних электромагнитных влияний, для эксплуатации в промышленных пожаровзрывоопасных зонах. </div><p><strong>Технические характеристики кабеля МКЭШВнг </strong><br/></p><ul><li>Климатическое исполнение УХЛ категорий размещения 2–5 по ГОСТ 15150. <br/></li><li>Диапазон температур эксплуатации: от –50 до +70°С <br/></li><li>Относительная влажность воздуха при температуре до 35°С 98% <br/></li><li>Прокладка кабелей без предварительного прогрева должна производиться при температуре не ниже –15°С <br/></li><li>Минимальный радиус изгиба при монтаже, не менее 5 наружных диаметров <br/></li><li>Испытательное переменное напряжение частотой 50 Гц (продолжительность испытания – 1 мин) 2 кВ <br/></li><li>Электрическое сопротивление изоляции жил, на 1 км длины и при температуре 20°С не менее 5 МОм <br/></li><li>Кабели не распространяют горение при одиночной прокладке <br/></li><li>Кабели с индексом "нг” и "LS” не распространяют горение при пучковой прокладке по ГОСТ 12176 <br/></li><li>Строительная длина кабелей <strong>МКЭШВнг, </strong>не менее 100 м <br/></li><li>Гарантийный срок эксплуатации 3 года с даты ввода кабелей в эксплуатацию <br/></li><li>Срок службы 15 лет </li></ul><table><tbody><tr><td><strong>Число жил и сечение, мм² </strong></td><td><strong>Диаметр кабеля, мм </strong></td><td><strong>Масса кабеля, кг/км </strong></td></tr><tr><td>МКЭШВнг 1х2х0,5 </td><td>6,9 </td><td>63,5 </td></tr><tr><td>МКЭШВнг 2х2х0,5 </td><td>11,3 </td><td>131,3 </td></tr><tr><td>МКЭШВнг 4х2х0,5 </td><td>12,8 </td><td>179,8 </td></tr><tr><td>МКЭШВнг 5х2х0,5 </td><td>13,9 </td><td>207,3 </td></tr><tr><td>МКЭШВнг 7х2х0,5 </td><td>15,1 </td><td>251,1 </td></tr><tr><td>МКЭШВнг 10х2х0,5 </td><td>19,3 </td><td>359,3 </td></tr><tr><td>МКЭШВнг 14х2х0,5 </td><td>20,8 </td><td>441,0 </td></tr><tr><td>МКЭШВнг 1х2х0,75 </td><td>7,3 </td><td>70,4 </td></tr><tr><td>МКЭШВнг 2х2х0,75 </td><td>12,1 </td><td>146,5 </td></tr><tr><td>МКЭШВнг 4х2х0,75 </td><td>13,8 </td><td>203,3 </td></tr><tr><td>МКЭШВнг 5х2х0,75 </td><td>15,0 </td><td>235,2 </td></tr><tr><td>МКЭШВнг 7х2х0,75 </td><td>16,3 </td><td>28