INSERT INTO `products` (`id`,`category_id`,`root_category`,`name`,`slug`,`sku`,`short_description`,`description_html`,`image`,`unit`,`price`,`request_hint`,`active`,`featured`,`sort_order`,`seo_title`,`seo_description`,`source_file`,`specs_json`,`gallery_json`,`old_urls_json`) VALUES (800,21,'cable','МЛТП','644-mltp','MNP-0800','Для подвижного и фиксированного внутриприборного и межприборного монтажа электрических устройств и выводных концов электроаппаратуры при напряжении до 500В переменного тока частотой до 1000 Гц или до 750В постоянного тока при температуре от -60°С.','<div><p>МЛТП </p><p><img alt="a" loading="lazy" src="assets/img/products/mltp__a49057e415dac8bc9ae31959.jpg"/></p><ol><li>Токопроводящая жила скрученная из медных лужёных проволок </li><li>Изоляция в виде обмотки из лавсановой (полиэфирной) нити </li><li>Оболочка из радиационно-сшитого термостабилизированного полиэтилена. </li></ol><p><strong>Область применения МЛТП: </strong></p><p>Для подвижного и фиксированного внутриприборного и межприборного монтажа электрических устройств и выводных концов электроаппаратуры при напряжении до 500В переменного тока частотой до 1000 Гц или до 750В постоянного тока при температуре от -60°С до +150°С. Климатическое исполнение В. </p><p><strong>Технические характеристики МЛТП </strong></p><table><tbody><tr><td>Влажность воздуха при 35° C [%] </td><td><strong>98 </strong></td></tr><tr><td>Испытательное напряжение на проход [кВ] </td><td><strong>16 </strong></td></tr><tr><td>Испытательное переменное напряжение частотой 50 Гц, 5 мин. [кВ] </td><td><strong>9 </strong></td></tr><tr><td>Испытательное постоянное напряжение [кВ] </td><td><strong>35 </strong></td></tr><tr><td>Максимальная рабочая температура жилы [°С] </td><td><strong>200 </strong></td></tr><tr><td>Напряжение начала частичных разрядов в изоляции при частоте 50 Гц, не менее [кВ]: </td><td><strong>4.2 </strong></td></tr><tr><td>Напряжение униполярных импульсов [кВ]: </td><td><strong>8 </strong></td></tr><tr><td>Строительная длина, не менее [м] </td><td><strong>10 </strong></td></tr><tr><td>Температура окружающей среды, верхний предел [°C] </td><td><strong>+200 </strong></td></tr><tr><td>Температура окружающей среды, нижний предел [°C] </td><td><strong>-60 </strong></td></tr><tr><td>Электрическое сопротивление изоляции, не менее [МОм*км] </td><td><strong>100000 </strong></td></tr></tbody></table><table><tbody><tr><td><strong>Число жил и номинальное <br/>сечение, <br/>кв.мм </strong></td><td><strong>Номинальный <br/>диаметр, кв.мм </strong></td><td><strong>Масса провода, кг/км </strong></td><td></td></tr><tr><td>МЛТП 0,12 </td><td>1,45 </td><td>2,4 </td><td></td></tr><tr><td>МЛТП 0,20 </td><td>1,6 </td><td>3,6 </td><td></td></tr><tr><td>МЛТП 0,35 </td><td>1,9 </td><td>5,5 </td><td></td></tr><tr><td>МЛТП 0,50 </td><td>2,1 </td><td>7,1 </td><td></td></tr><tr><td>МЛТП 0,75 </td><td>2,4 </td><td>10,0 </td><td></td></tr><tr><td>МЛТП 1,00 </td><td>2,5 </td><td>12,3 </td><td></td></tr><tr><td>МЛТП 1,5 </td><td>2,9 </td><td>17,7 </td><td></td></tr><tr><td>МЛТП 2,5 </td><td>3,5 </td><td>29,2 </td><td></td></tr><tr><td>МЛТП 4,0 </td><td>4,3 </td><td>43,9 </td><td></td></tr><tr><td>МЛТП 6,0 </td><td>5,2 </td><td>64,5 </td><td></td></tr></tbody></table></div>','assets/img/products/mltp__a49057e415dac8bc9ae31959.jpg','м',NULL,'Укажите марку, число и сечение жил, рабочее напряжение, длину и условия прокладки.',1,0,800,'МЛТП — купить по заявке | Монополия','МЛТП: подбор и поставка в Санкт-Петербурге. Укажите марку, число и сечение жил, рабочее напряжение, длину и условия прокладки. Расчет стоимости — по заявке.','site/www.monopoly-torg.ru/644-mltp__b55b55c0629d9f3d89b1c264.html','[["Влажность воздуха при 35° C [%]", "98"], ["Испытательное напряжение на проход [кВ]", "16"], ["Испытательное переменное напряжение частотой 50 Гц, 5 мин. [кВ]", "9"], ["Испытательное постоянное напряжение [кВ]", "35"], ["Максимальная рабочая температура жилы [°С]", "200"], ["Напряжение начала частичных разрядов в изоляции при частоте 50 Гц, не менее [кВ]:", "4.2"], ["Напряжение униполярных импульсов [кВ]:", "8"], ["Строительная длина, не менее [м]", "10"], ["Температура окружающей среды, верхний предел [°C]", "+200"], ["Температура окружающей среды, нижний предел [°C]", "-60"], ["Электрическое сопротивление изоляции, не менее [МОм*км]", "100000"]]','["assets/img/products/mltp__a49057e415dac8bc9ae31959.jpg"]','["http://www.monopoly-torg.ru/index.php/kabelnaya-produkciya/provoda/644-mltp"]') ON DUPLICATE KEY UPDATE `category_id`=VALUES(`category_id`),`root_category`=VALUES(`root_category`),`name`=VALUES(`name`),`slug`=VALUES(`slug`),`sku`=VALUES(`sku`),`short_description`=VALUES(`short_description`),`description_html`=VALUES(`description_html`),`image`=VALUES(`image`),`unit`=VALUES(`unit`),`price`=VALUES(`price`),`request_hint`=VALUES(`request_hint`),`active`=VALUES(`active`),`featured`=VALUES(`featured`),`sort_order`=VALUES(`sort_order`),`seo_title`=VALUES(`seo_title`),`seo_description`=VALUES(`seo_description`),`source_file`=VALUES(`source_file`),`specs_json`=VALUES(`specs_json`),`gallery_json`=VALUES(`gallery_json`),`old_urls_json`=VALUES(`old_urls_json`);
INSERT INTO `products` (`id`,`category_id`,`root_category`,`name`,`slug`,`sku`,`short_description`,`description_html`,`image`,`unit`,`price`,`request_hint`,`active`,`featured`,`sort_order`,`seo_title`,`seo_description`,`source_file`,`specs_json`,`gallery_json`,`old_urls_json`) VALUES (801,21,'cable','МСЭ','645-mse','MNP-0801','Провода предназначены для работы при номинальном переменном напряжении 100, 250 и 500 В частоты до 10000 Гц и соответственно постоянном напряжении 150, 350 и 700 В и темпера-туре от -60° до +155 °С для проводов с экраном из медных луженых.','<div><p>МСЭ </p><p><img alt="a" loading="lazy" src="assets/img/products/mse__00960f70bc1d79ac35ead1b5.jpg"/></p><ol><li>Токопроводящая жила из медных посеребренных проволок или посеребренных проволок сплава БрХЦрК. </li><li>Изоляция в виде обмотки с последующей запечкой из пленки фторопласта-4Д. Изоляция должна быть белого (натурального), красного, желтого, синего, зеленого, коричневого или черного цвета. Расцветка должна быть сплошной. </li><li>Экран в виде оплетки из медных луженых оловом проволок, или из медных посеребренных проволок. </li><li>Оболочка в виде обмотки с последующей запечкой из пленки из фторопласта-4Д </li></ol><p><strong>Область применения МСЭ: </strong></p><p>Провода предназначены для работы при номинальном переменном напряжении 100, 250 и 500 В частоты до 10000 Гц и соответственно постоянном напряжении 150, 350 и 700 В и темпера-туре от -60° до +155 °С для проводов с экраном из медных луженых проволок и от -60° до +200° С для проводов с экраном из медных посеребренных проволок и неэкранированных. </p><p><strong>Основные характеристики МСЭ: </strong></p><p>Строительная длина проводов на номинальное напряжение 100 В должна быть не менее 25 м, остальных проводов – не менее 20 м. Допускается сдача маломерных отрезков длиной не менее 10 м и не менее 5 м в количестве не более 30% и 20% соответственно от сдаваемой партии. </p><p>Испытательное напряжение </p><table><tbody><tr><td rowspan="3">Номинальное напряжение, В </td><td colspan="3">Испытательное напряжение переменного тока частоты 50 Гц в течение 1 мин, В </td></tr><tr><td colspan="2">при приемке и поставке </td><td rowspan="2">на период эксплуатации и хранения </td></tr><tr><td>без внешних воздействующих факторов </td><td>после внешних воз действующих факторов </td></tr><tr><td>100 </td><td>1500 </td><td>1000 </td><td>500 </td></tr><tr><td>250 </td><td>2000 </td><td>1000 </td><td>700 </td></tr><tr><td>500 </td><td>3000 </td><td>2000 </td><td>1500 </td></tr></tbody></table><p>Электрическое сопротивление изоляции 1 м длины, МОм, не менее </p><table><tbody><tr><td><p>В нормальных климатических условиях </p></td><td><p>2х10 <sup>6 </sup></p></td></tr><tr><td><p>При температуре 200° С </p></td><td><p>1х10 <sup>5 </sup></p></td></tr><tr><td><p>При относительной влажности воздуха 98 % и температуре 35° С </p></td><td><p>1х10 <sup>4 </sup></p></td></tr></tbody></table><p>Число циклов изгибов на угол ±90° при радиусе изгиба не менее 5 наружных диаметров провода </p><table><tbody><tr><td>Для проводов на номинальное напряжение 100 В сечений от 0,02 до 0,12 мм <sup>2 </sup></td><td><p>130 </p></td></tr><tr><td>Для проводов на номинальное напряжение 100 В сечений 0,20 и 0,35 мм <sup>2 </sup></td><td><p>100 </p></td></tr><tr><td>Для проводов на номинальное напряжение 100 В сечения 0,50 мм <sup>2 </sup>неэкранированных </td><td><p>75 </p></td></tr><tr><td>Для проводов на номинальное напряжение 100 В сечения 0,50 мм <sup>2 </sup>экранированных </td><td><p>50 </p></td></tr><tr><td>Для проводов на номинальное напряжение 250 и 500 В всех сечений </td><td><p>50 </p></td></tr></tbody></table><p>95% ресурс проводов в режимах и условиях, допускаемых ТУ 16-505.083-70, составляет не менее 15000 ч, при температуре 155 °С для проводов с экраном из медной луженой проволоки и при температуре 200 °С для остальных проводов. </p><p>Сопротивление связи на частоте 10 МГц для экранированных проводов должны быть не более 300 МОм/м. </p></div>','assets/img/products/mse__00960f70bc1d79ac35ead1b5.jpg','м',NULL,'Укажите марку, число и сечение жил, рабочее напряжение, длину и условия прокладки.',1,0,801,'МСЭ — купить по заявке | Монополия','МСЭ: подбор и поставка в Санкт-Петербурге. Укажите марку, число и сечение жил, рабочее напряжение, длину и условия прокладки. Расчет стоимости — по заявке.','site/www.monopoly-torg.ru/645-mse__03cefe0cb28560ce66fd7d16.html','[["Номинальное напряжение, В", "Испытательное напряжение переменного тока частоты 50 Гц в течение 1 мин, В"], ["при приемке и поставке", "на период эксплуатации и хранения"], ["без внешних воздействующих факторов", "после внешних воз действующих факторов"], ["В нормальных климатических условиях", "2х10 6"], ["При температуре 200° С", "1х10 5"], ["При относительной влажности воздуха 98 % и температуре 35° С", "1х10 4"], ["Для проводов на номинальное напряжение 100 В сечений от 0,02 до 0,12 мм 2", "130"], ["Для проводов на номинальное напряжение 100 В сечений 0,20 и 0,35 мм 2", "100"], ["Для проводов на номинальное напряжение 100 В сечения 0,50 мм 2 неэкранированных", "75"], ["Для проводов на номинальное напряжение 100 В сечения 0,50 мм 2 экранированных", "50"], ["Для проводов на номинальное напряжение 250 и 500 В всех сечений", "50"]]','["assets/img/products/mse__00960f70bc1d79ac35ead1b5.jpg"]','["http://www.monopoly-torg.ru/index.php/kabelnaya-produkciya/provoda/645-mse"]') ON DUPLICATE KEY UPDATE `category_id`=VALUES(`category_id`),`root_category`=VALUES(`root_category`),`name`=VALUES(`name`),`slug`=VALUES(`slug`),`sku`=VALUES(`sku`),`short_description`=VALUES(`short_description`),`description_html`=VALUES(`description_html`),`image`=VALUES(`image`),`unit`=VALUES(`unit`),`price`=VALUES(`price`),`request_hint`=VALUES(`request_hint`),`active`=VALUES(`active`),`featured`=VALUES(`featured`),`sort_order`=VALUES(`sort_order`),`seo_title`=VALUES(`seo_title`),`seo_description`=VALUES(`seo_description`),`source_file`=VALUES(`source_file`),`specs_json`=VALUES(`specs_json`),`gallery_json`=VALUES(`gallery_json`),`old_urls_json`=VALUES(`old_urls_json`);
