INSERT INTO `products` (`id`,`category_id`,`root_category`,`name`,`slug`,`sku`,`short_description`,`description_html`,`image`,`unit`,`price`,`request_hint`,`active`,`featured`,`sort_order`,`seo_title`,`seo_description`,`source_file`,`specs_json`,`gallery_json`,`old_urls_json`) VALUES (820,21,'cable','ПГВА-ХЛ','664-pgva-khl','MNP-0820','Провода марки ПГВА-ХЛ предназначены для подвижного соединения автотракторного оборудования и приборов с номинальным напряжением до 48 В.','<div><p>ПГВА-ХЛ </p><p><img alt="a" loading="lazy" src="assets/img/products/pgva__525ad7b0a642d0730fb4215e.jpg"/></p><ol><li>Токопроводящая жила скрученная из медных проволок; </li><li>Изоляция ПВХ пластиката, <br/>• цвет изоляции: белый, жёлтый, оранжевый, красный, розовый, синий, <br/>зеленый, коричневый, серый, черный, фиолетовый. </li></ol><p><strong>Область применения ПГВА-ХЛ: </strong></p><p>Провода марки <strong>ПГВА-ХЛ </strong>предназначены для подвижного соединения автотракторного оборудования и приборов с номинальным напряжением до 48 В. </p><p>Провода предназначены для эксплуатации на суше, реках, озёрах в макроклиматических районах с холодным ( <strong>ПГВА-ХЛ </strong>), умеренным и тропическим (ПГВА-Т) климатом. Провода марки <strong>ПГВА-ХЛ </strong>устойчивы к воздействию многократных ударов с ускорением 1470 м/с2 с длительностью удара 1-5 мс при температуре -60°С. Провода устойчивы к воздействию минерального масла, бензина, дизельного топлива и в исполнении Т - плесневых грибов. </p><p>Провода не распространяют горение при одиночной прокладке. </p><p><strong>Технические характеристики ПГВА-ХЛ </strong><br/></p><table><tbody><tr><td>Монтаж при температуре, не ниже [°C] </td><td><strong>-60 </strong></td></tr><tr><td>Пиковое значение испытательного напряжения в зависимости от толщины изоляции [кВ] </td><td><strong>8/24 </strong></td></tr><tr><td>Радиус изгиба кабелей [наружных диаметров] </td><td><strong>10 </strong></td></tr><tr><td>Температура окружающей среды, верхний предел [°C] </td><td><strong>+70 </strong></td></tr><tr><td>Температура окружающей среды, нижний предел [°C] </td><td><strong>-60 </strong></td></tr></tbody></table><p>Срок службы - 10 лет. </p><table><tbody><tr><td><strong>Сечение, кв.мм </strong></td><td><strong>Расчетная масса <br/>провода, кг/км </strong></td><td><strong>Максимальный <br/>наружный диаметр, мм </strong></td><td><strong>Строительная длина, <br/>не менее [м] </strong></td></tr><tr><td>ПГВА-ХЛ 0,2 </td><td>3 </td><td>1,5 </td><td>100 </td></tr><tr><td>ПГВА-ХЛ 0,35 </td><td>5 </td><td>1,7 </td><td>100 </td></tr><tr><td>ПГВА-ХЛ 0,5 </td><td>10 </td><td>2,3 </td><td>100 </td></tr><tr><td>ПГВА-ХЛ 0,75 </td><td>13 </td><td>2,6 </td><td>100 </td></tr><tr><td>ПГВА-ХЛ 1 </td><td>15 </td><td>2,7 </td><td>100 </td></tr><tr><td>ПГВА-ХЛ 1,5 </td><td>21 </td><td>3 </td><td>100 </td></tr><tr><td>ПГВА-ХЛ 2,5 </td><td>33 </td><td>3,8 </td><td>100 </td></tr><tr><td>ПГВА-ХЛ 4 </td><td>50 </td><td>4,5 </td><td>100 </td></tr><tr><td>ПГВА-ХЛ 6 </td><td>74 </td><td>5,3 </td><td>100 </td></tr><tr><td>ПГВА-ХЛ 10 </td><td>117 </td><td>6,7 </td><td>100 </td></tr><tr><td>ПГВА-ХЛ 16 </td><td>182 </td><td>8,6 </td><td>100 </td></tr><tr><td>ПГВА-ХЛ 25 </td><td>263 </td><td>10,8 </td><td>100 </td></tr><tr><td>ПГВА-ХЛ 35 </td><td>385 </td><td>11,6 </td><td>50 </td></tr><tr><td>ПГВА-ХЛ 50 </td><td>526 </td><td>14,9 </td><td>50 </td></tr><tr><td>ПГВА-ХЛ 70 </td><td>734 </td><td>16,9 </td><td>50 </td></tr><tr><td>ПГВА-ХЛ 95 </td><td>1003 </td><td>18,3 </td><td>50 </td></tr></tbody></table></div>','assets/img/products/pgva__525ad7b0a642d0730fb4215e.jpg','м',NULL,'Укажите марку, число и сечение жил, рабочее напряжение, длину и условия прокладки.',1,0,820,'ПГВА-ХЛ — купить по заявке | Монополия','ПГВА-ХЛ: подбор и поставка в Санкт-Петербурге. Укажите марку, число и сечение жил, рабочее напряжение, длину и условия прокладки. Расчет стоимости — по заявке.','site/www.monopoly-torg.ru/664-pgva-khl__781aae0ea1e90867eaf1fccd.html','[["Монтаж при температуре, не ниже [°C]", "-60"], ["Пиковое значение испытательного напряжения в зависимости от толщины изоляции [кВ]", "8/24"], ["Радиус изгиба кабелей [наружных диаметров]", "10"], ["Температура окружающей среды, верхний предел [°C]", "+70"], ["Температура окружающей среды, нижний предел [°C]", "-60"]]','["assets/img/products/pgva__525ad7b0a642d0730fb4215e.jpg"]','["http://www.monopoly-torg.ru/index.php/kabelnaya-produkciya/provoda/664-pgva-khl"]') ON DUPLICATE KEY UPDATE `category_id`=VALUES(`category_id`),`root_category`=VALUES(`root_category`),`name`=VALUES(`name`),`slug`=VALUES(`slug`),`sku`=VALUES(`sku`),`short_description`=VALUES(`short_description`),`description_html`=VALUES(`description_html`),`image`=VALUES(`image`),`unit`=VALUES(`unit`),`price`=VALUES(`price`),`request_hint`=VALUES(`request_hint`),`active`=VALUES(`active`),`featured`=VALUES(`featured`),`sort_order`=VALUES(`sort_order`),`seo_title`=VALUES(`seo_title`),`seo_description`=VALUES(`seo_description`),`source_file`=VALUES(`source_file`),`specs_json`=VALUES(`specs_json`),`gallery_json`=VALUES(`gallery_json`),`old_urls_json`=VALUES(`old_urls_json`);
INSERT INTO `products` (`id`,`category_id`,`root_category`,`name`,`slug`,`sku`,`short_description`,`description_html`,`image`,`unit`,`price`,`request_hint`,`active`,`featured`,`sort_order`,`seo_title`,`seo_description`,`source_file`,`specs_json`,`gallery_json`,`old_urls_json`) VALUES (821,21,'cable','ПГР','665-pgr','MNP-0821','Провода ПГР предназначены для фиксированного соединения электрооборудования вагонов метрополитена, работающих при номинальном напряжении до 660 В переменного тока частоты до 400 Гц или 1000 В постоянного тока.','<div><p>ПГР </p><p><img alt="a" loading="lazy" src="assets/img/products/pgr__fb23ba605ac55407ccae2d16.jpg"/></p><ol><li>Медная токопроводящая жила; </li><li>Изоляция из кремнийорганической резины. </li></ol><p><strong>Область применения ПГР: </strong></p><p>Провода <strong>ПГР </strong>предназначены для фиксированного соединения электрооборудования вагонов метрополитена, работающих при номинальном напряжении до 660 В переменного тока частоты до 400 Гц или 1000 В постоянного тока. </p><p>Провода предназначены для эксплуатации в закрытых помещениях (объемах) в районах с умеренным холодным климатом. Провода устойчивы к воздействию озона, допускается воздействие дождя, инея и росы. В течение срока службы провода допускают 200 изгибов на радиус, равный не менее четырёх диаметров провода при температуре окружающей среды не ниже минус 5°С. Провода не распространяют и не поддерживают горение. В ходе эксплуатации провода не должны подвергаться прямому воздействию солнечного излучения. <br/></p><p><strong>Технические характеристики ПГР </strong><br/></p><table><tbody><tr><td>Влажность воздуха при 40°С [%] </td><td><strong>98 </strong></td></tr><tr><td>Гарантийный срок эксплуатации [месяц] </td><td><strong>24 </strong></td></tr><tr><td>Испытательное переменное напряжение частотой 50 Гц, 5 мин. [кВ] </td><td><strong>2.5 </strong></td></tr><tr><td>Монтаж при температуре, не ниже [°C] </td><td><strong>-15 </strong></td></tr><tr><td>Номинальное напряжение переменного тока, частотой до 400 Гц [В] </td><td><strong>660 </strong></td></tr><tr><td>Номинальное постоянное напряжение [кВ] </td><td><strong>1 </strong></td></tr><tr><td>Рабочая температура жилы [°С] </td><td><strong>150 </strong></td></tr><tr><td>Радиус изгиба кабелей [наружных диаметров] </td><td><strong>4 </strong></td></tr><tr><td>Температура окружающей среды, верхний предел [°C] </td><td><strong>+150 </strong></td></tr><tr><td>Температура окружающей среды, нижний предел [°C] </td><td><strong>-60 </strong></td></tr><tr><td>Электрическое сопротивление изоляции, не менее [МОм*км] </td><td><strong>150 </strong></td></tr></tbody></table><p><strong>Срок службы: </strong></p><p>при температуре +80°С - 25 лет, <br/>при температуре +115°С - 12,5 лет, <br/>при температуре +150°С - 2,5 года, <br/>при температуре +180°С - 0,5 года. </p><table><tbody><tr><td><strong>Сечение жилы, кв. мм </strong></td><td><strong>Масса провода, <br/>кг/км </strong></td><td><strong>Наружный диаметр, <br/>не более, мм </strong></td><td><strong>Строительная длина, <br/>не менее, м </strong></td></tr><tr><td>ПГР 2,5 </td><td>38 </td><td>3,9 </td><td>100 </td></tr><tr><td>ПГР 4 </td><td>55 </td><td>4,6 </td><td>100 </td></tr><tr><td>ПГР 6 </td><td>85 </td><td>6,0 </td><td>100 </td></tr><tr><td>ПГР 10 </td><td>123 </td><td>6,9 </td><td>100 </td></tr><tr><td>ПГР 16 </td><td>192 </td><td>8,5 </td><td>100 </td></tr><tr><td>ПГР 25 </td><td>296 </td><td>10,2 </td><td>50 </td></tr><tr><td>ПГР 35 </td><td>398 </td><td>11,5 </td><td>50 </td></tr><tr><td>ПГР 50 </td><td>542 </td><td>13,4 </td><td>50 </td></tr><tr><td>ПГР 70 </td><td>748 </td><td>15,8 </td><td>50 </td></tr><tr><td>ПГР 95 </td><td>1016 </td><td>17,9 </td><td>50 </td></tr><tr><td>ПГР 120 </td><td>1278 </td><td>19,8 </td><td>50 </td></tr></tbody></table></div>','assets/img/products/pgr__fb23ba605ac55407ccae2d16.jpg','м',NULL,'Укажите марку, число и сечение жил, рабочее напряжение, длину и условия прокладки.',1,0,821,'ПГР — купить по заявке | Монополия','ПГР: подбор и поставка в Санкт-Петербурге. Укажите марку, число и сечение жил, рабочее напряжение, длину и условия прокладки. Расчет стоимости — по заявке.','site/www.monopoly-torg.ru/665-pgr__62bc70425c72bae87dce9717.html','[["Влажность воздуха при 40°С [%]", "98"], ["Гарантийный срок эксплуатации [месяц]", "24"], ["Испытательное переменное напряжение частотой 50 Гц, 5 мин. [кВ]", "2.5"], ["Монтаж при температуре, не ниже [°C]", "-15"], ["Номинальное напряжение переменного тока, частотой до 400 Гц [В]", "660"], ["Номинальное постоянное напряжение [кВ]", "1"], ["Рабочая температура жилы [°С]", "150"], ["Радиус изгиба кабелей [наружных диаметров]", "4"], ["Температура окружающей среды, верхний предел [°C]", "+150"], ["Температура окружающей среды, нижний предел [°C]", "-60"], ["Электрическое сопротивление изоляции, не менее [МОм*км]", "150"]]','["assets/img/products/pgr__fb23ba605ac55407ccae2d16.jpg"]','["http://www.monopoly-torg.ru/index.php/kabelnaya-produkciya/provoda/665-pgr"]') ON DUPLICATE KEY UPDATE `category_id`=VALUES(`category_id`),`root_category`=VALUES(`root_category`),`name`=VALUES(`name`),`slug`=VALUES(`slug`),`sku`=VALUES(`sku`),`short_description`=VALUES(`short_description`),`description_html`=VALUES(`description_html`),`image`=VALUES(`image`),`unit`=VALUES(`unit`),`price`=VALUES(`price`),`request_hint`=VALUES(`request_hint`),`active`=VALUES(`active`),`featured`=VALUES(`featured`),`sort_order`=VALUES(`sort_order`),`seo_title`=VALUES(`seo_title`),`seo_description`=VALUES(`seo_description`),`source_file`=VALUES(`source_file`),`specs_json`=VALUES(`specs_json`),`gallery_json`=VALUES(`gallery_json`),`old_urls_json`=VALUES(`old_urls_json`);
INSERT INTO `products` (`id`,`category_id`,`root_category`,`name`,`slug`,`sku`,`short_description`,`description_html`,`image`,`unit`,`price`,`request_hint`,`active`,`featured`,`sort_order`,`seo_title`,`seo_description`,`source_file`,`specs_json`,`gallery_json`,`old_urls_json`) VALUES (822,21,'cable','ПГРО','666-pgro','MNP-0822','Провода ПГРО предназначены для фиксированного соединения электрооборудования вагонов метрополитена, работающих при номинальном напряжении до 660 В переменного тока частоты до 400 Гц или 1000 В постоянного тока.','<div><p>ПГРО </p><p><img alt="a" loading="lazy" src="assets/img/products/pgro__dc5d6b305e8855bbdf2b2f6f.jpg"/></p><ol><li>Медная токопроводящая жила </li><li>Изоляция из кремнийорганической резины </li><li>Оплётка из полиэфирных нитей пропитанная кремнийорганическим лаком </li></ol><p><strong>Область применения ПГРО: </strong></p><p>Провода <strong>ПГРО </strong>предназначены для фиксированного соединения электрооборудования вагонов метрополитена, работающих при номинальном напряжении до 660 В переменного тока частоты до 400 Гц или 1000 В постоянного тока. </p><p>Провода предназначены для эксплуатации в закрытых помещениях (объемах) в районах с умеренным холодным климатом. Провода устойчивы к воздействию озона, допускается воздействие дождя, инея и росы. В течение срока службы провода допускают 200 изгибов на радиус, равный не менее четырёх диаметров провода при температуре окружающей среды не ниже минус 5°С. Провода не распространяют и не поддерживают горение. Провода устойчивы к воздействию плесневых грибов. В ходе эксплуатации провода не должны подвергаться прямому воздействию солнечного излучения. <br/></p><p><strong>Технические характеристики ПГРО </strong><br/></p><table><tbody><tr><td>Влажность воздуха при 40°С [%] </td><td><strong>98 </strong></td></tr><tr><td>Гарантийный срок эксплуатации [месяц] </td><td><strong>24 </strong></td></tr><tr><td>Испытательное переменное напряжение частотой 50 Гц, 5 мин. [кВ] </td><td><strong>2.5 </strong></td></tr><tr><td>Монтаж при температуре, не ниже [°C] </td><td><strong>-15 </strong></td></tr><tr><td>Номинальное напряжение переменного тока, частотой до 400 Гц [В] </td><td><strong>660 </strong></td></tr><tr><td>Номинальное постоянное напряжение [кВ] </td><td><strong>1 </strong></td></tr><tr><td>Рабочая температура жилы [°С] </td><td><strong>115 </strong></td></tr><tr><td>Радиус изгиба кабелей [наружных диаметров] </td><td><strong>4 </strong></td></tr><tr><td>Температура окружающей среды, верхний предел [°C] </td><td><strong>+115 </strong></td></tr><tr><td>Температура окружающей среды, нижний предел [°C] </td><td><strong>-60 </strong></td></tr><tr><td>Электрическое сопротивление изоляции, не менее [МОм*км] </td><td><strong>150 </strong></td></tr></tbody></table><p><strong>Срок службы: </strong></p><p>при температуре +80°С - 25 лет, <br/>при температуре +115°С - 12,5 лет. </p><table><tbody><tr><td><strong>Сечение жилы, кв. мм </strong></td><td><strong>Масса провода, <br/>кг/км </strong></td><td><strong>Наружный диаметр, <br/>не более, мм </strong></td><td><strong>Строительная длина, <br/>не менее, м </strong></td></tr><tr><td>ПГРО 0,75 </td><td>19 </td><td>3,6 </td><td>100 </td></tr><tr><td>ПГРО 1 </td><td>21 </td><td>3,7 </td><td>100 </td></tr><tr><td>ПГРО 1,5 </td><td>27 </td><td>4,0 </td><td>100 </td></tr><tr><td>ПГРО 2,5 </td><td>42 </td><td>4,7 </td><td>100 </td></tr><tr><td>ПГРО 4 </td><td>60 </td><td>5,4 </td><td>100 </td></tr><tr><td>ПГРО 6 </td><td>90 </td><td>6,8 </td><td>100 </td></tr><tr><td>ПГРО 10 </td><td>129 </td><td>7,7 </td><td>100 </td></tr><tr><td>ПГРО 16 </td><td>204 </td><td>9,3 </td><td>100 </td></tr><tr><td>ПГРО 25 </td><td>309 </td><td>11,0 </td><td>50 </td></tr><tr><td>ПГРО 35 </td><td>412 </td><td>12,3 </td><td>50 </td></tr><tr><td>ПГРО 50 </td><td>559 </td><td>14,2 </td><td>50 </td></tr><tr><td>ПГРО 70 </td><td>767 </td><td>16,6 </td><td>50 </td></tr><tr><td>ПГРО 95 </td><td>1036 </td><td>18,7 </td><td>50 </td></tr><tr><td>ПГРО 120 </td><td>1299 </td><td>20,6 </td><td>50 </td></tr></tbody></table></div>','assets/img/products/pgro__dc5d6b305e8855bbdf2b2f6f.jpg','м',NULL,'Укажите марку, число и сечение жил, рабочее напряжение, длину и условия прокладки.',1,0,822,'ПГРО — купить по заявке | Монополия','ПГРО: подбор и поставка в Санкт-Петербурге. Укажите марку, число и сечение жил, рабочее напряжение, длину и условия прокладки. Расчет стоимости — по заявке.','site/www.monopoly-torg.ru/666-pgro__982da1244d25241844dfe7b8.html','[["Влажность воздуха при 40°С [%]", "98"], ["Гарантийный срок эксплуатации [месяц]", "24"], ["Испытательное переменное напряжение частотой 50 Гц, 5 мин. [кВ]", "2.5"], ["Монтаж при температуре, не ниже [°C]", "-15"], ["Номинальное напряжение переменного тока, частотой до 400 Гц [В]", "660"], ["Номинальное постоянное напряжение [кВ]", "1"], ["Рабочая температура жилы [°С]", "115"], ["Радиус изгиба кабелей [наружных диаметров]", "4"], ["Температура окружающей среды, верхний предел [°C]", "+115"], ["Температура окружающей среды, нижний предел [°C]", "-60"], ["Электрическое сопротивление изоляции, не менее [МОм*км]", "150"]]','["assets/img/products/pgro__dc5d6b305e8855bbdf2b2f6f.jpg"]','["http://www.monopoly-torg.ru/index.php/kabelnaya-produkciya/provoda/666-pgro"]') ON DUPLICATE KEY UPDATE `category_id`=VALUES(`category_id`),`root_category`=VALUES(`root_category`),`name`=VALUES(`name`),`slug`=VALUES(`slug`),`sku`=VALUES(`sku`),`short_description`=VALUES(`short_description`),`description_html`=VALUES(`description_html`),`image`=VALUES(`image`),`unit`=VALUES(`unit`),`price`=VALUES(`price`),`request_hint`=VALUES(`request_hint`),`active`=VALUES(`active`),`featured`=VALUES(`featured`),`sort_order`=VALUES(`sort_order`),`seo_title`=VALUES(`seo_title`),`seo_description`=VALUES(`seo_description`),`source_file`=VALUES(`source_file`),`specs_json`=VALUES(`specs_json`),`gallery_json`=VALUES(`gallery_json`),`old_urls_json`=VALUES(`old_urls_json`);
