INSERT INTO `products` (`id`,`category_id`,`root_category`,`name`,`slug`,`sku`,`short_description`,`description_html`,`image`,`unit`,`price`,`request_hint`,`active`,`featured`,`sort_order`,`seo_title`,`seo_description`,`source_file`,`specs_json`,`gallery_json`,`old_urls_json`) VALUES (882,23,'cable','СИП-5, Самонесущие изолированные провода','748-sip-5-samonesushchie-izolirovannye-provoda','MNP-0882','СИП-5, Самонесущие изолированные провода для промышленных, строительных и энергетических объектов.','<div><p>СИП-5, Самонесущие изолированные провода </p><p><img alt="sip-4" loading="lazy" src="assets/img/products/sip-4__c462519624c8074d148dd8e2.jpg"/></p><ol><li>4 токопроводящих жилы из алюминия, многопроволочных, уплотненных, равного сечения, одна из которых может быть нулевой. </li><li>Изоляция из светостабилизированного сшитого полиэтилена. </li></ol><p><strong>Область применения СИП-5: </strong></p><p>Для применения в воздушных линиях электропередачи. <br/></p><p><strong>Технические характеристики СИП-5 </strong></p><table><tbody><tr><td>Гарантийный срок эксплуатации [месяц] </td><td><strong>36 </strong></td></tr><tr><td>Монтаж при температуре, не ниже [°C] </td><td><strong>-20 </strong></td></tr><tr><td>Рабочая температура жилы [°С] </td><td><strong>90 </strong></td></tr><tr><td>Температура окружающей среды, верхний предел [°C] </td><td><strong>50 </strong></td></tr><tr><td>Температура окружающей среды, нижний предел [°C] </td><td><strong>-60 </strong></td></tr></tbody></table><p>. </p><table><tbody><tr><td><strong>Сечение, мм2 </strong></td><td><strong>Расчётная масса, кг/км </strong></td><td><strong>Наружный диаметр, мм </strong></td></tr><tr><td>СИП-5 4x35 </td><td>515 </td><td>23 </td></tr><tr><td>СИП-5 4x50 </td><td>720 </td><td>27 </td></tr><tr><td>СИП-5 4x70 </td><td>993 </td><td>31 </td></tr><tr><td>СИП-5 4x95 </td><td>1322 </td><td>36 </td></tr><tr><td>СИП-5 4x120 </td><td>1616 </td><td>39 </td></tr></tbody></table></div>','assets/img/products/sip-4__c462519624c8074d148dd8e2.jpg','м',NULL,'Укажите марку, число и сечение жил, рабочее напряжение, длину и условия прокладки.',1,0,882,'СИП-5, Самонесущие изолированные провода — купить по заявке | Монополия','СИП-5, Самонесущие изолированные провода: подбор и поставка в Санкт-Петербурге. Укажите марку, число и сечение жил, рабочее напряжение, длину и условия прокладки. Расчет стоимости — по заявке.','site/www.monopoly-torg.ru/748-sip-5-samonesushchie-izolirovannye-provoda__71f44828649c94966dfbc7ec.html','[["Гарантийный срок эксплуатации [месяц]", "36"], ["Монтаж при температуре, не ниже [°C]", "-20"], ["Рабочая температура жилы [°С]", "90"], ["Температура окружающей среды, верхний предел [°C]", "50"], ["Температура окружающей среды, нижний предел [°C]", "-60"]]','["assets/img/products/sip-4__c462519624c8074d148dd8e2.jpg"]','["http://www.monopoly-torg.ru/index.php/kabelnaya-produkciya/sip/748-sip-5-samonesushchie-izolirovannye-provoda"]') ON DUPLICATE KEY UPDATE `category_id`=VALUES(`category_id`),`root_category`=VALUES(`root_category`),`name`=VALUES(`name`),`slug`=VALUES(`slug`),`sku`=VALUES(`sku`),`short_description`=VALUES(`short_description`),`description_html`=VALUES(`description_html`),`image`=VALUES(`image`),`unit`=VALUES(`unit`),`price`=VALUES(`price`),`request_hint`=VALUES(`request_hint`),`active`=VALUES(`active`),`featured`=VALUES(`featured`),`sort_order`=VALUES(`sort_order`),`seo_title`=VALUES(`seo_title`),`seo_description`=VALUES(`seo_description`),`source_file`=VALUES(`source_file`),`specs_json`=VALUES(`specs_json`),`gallery_json`=VALUES(`gallery_json`),`old_urls_json`=VALUES(`old_urls_json`);
INSERT INTO `products` (`id`,`category_id`,`root_category`,`name`,`slug`,`sku`,`short_description`,`description_html`,`image`,`unit`,`price`,`request_hint`,`active`,`featured`,`sort_order`,`seo_title`,`seo_description`,`source_file`,`specs_json`,`gallery_json`,`old_urls_json`) VALUES (883,2,'metal','Арматурный прокат','metal-armatura','MNP-0883','Наименование каждого класса арматурной стали, начинается с буквы «А». Первой отличительной характеристикой определяющейпринадлежность арматуры к тому или другому классу является ее поверхность, она может быть гладкой либо рифленой.','<div>Арматурный прокат <p>Наименование каждого класса арматурной стали, начинается с буквы «А». Первой отличительной характеристикой определяющейпринадлежность арматуры к тому или другому классу является ее поверхность, она может быть гладкой либо рифленой. </p><p><img alt="Арматурный прокат" loading="lazy" src="assets/img/products/p2__69966bb45d886e01e78a0993.jpg"/><strong>Арматурный прокат </strong>с поперечными выступами и двумя продольными ребрами называют периодической либо рифленой, согласно старому обозначению этот вид маркируется как Арматура строительная рифленая А3 (А500С, А400С, 35ГС, 25Г2С). Именно такое наименование периодического профиля чаще всего можно встретить в Типоразмеры и исполненияах поставщиков металлопроката. Кроме А-III к арматуре с периодическим профилем относятся согласно старой маркировке: арматура строительная А-II, А-IV, А-V, А-VI. Хотя на сегодняшний день используется другой способ обозначения, включающий показатель предела текучести: АЗООС, А400С, А500С, А600, А600С, А600К, А800, А800К, А1000. </p><p><strong>Арматура строительная гладкая А1 </strong>(класс А240 в новой редакции) в сечении представляет из себя металлический круг, который чаще всего применяется для сооружения металлоконструкций или в машиностроении. <strong>Арматура строительная гладкая А1 </strong>изготавливается из рядовых углеродистых марок стали (Ст3кп, Ст3пс, Ст3сп), которые легко поддаются свариванию. </p><p>Свое же главное предназначение арматура рифленого профиля нашла в армировании железобетонных конструкций. Особенности ее поверхности обеспечивают наиболее надежное сцепление с бетоном. Особенную популярность приобрела <strong>Арматура строительная рифленая А3 </strong>при широком распространении монолитного строительства. </p><p>Арматурный прокат может быть изготовлен способом горячей прокатки или холодного деформирования. До недавнего времени наиболее используемой считалась горячекатаная <strong>Арматура строительная рифленая А3 </strong>(А400) которая производилась на отечественных заводах из сталей 25Г2С, 35ГС по ГОСТу 5781-82. </p><h2>Арматурный прокат Типоразмеры и исполнения </h2><table><tbody><tr><td colspan="3"><p><strong>Арматура строительная гладкая А1 </strong></p></td><td></td><td rowspan="9"><p><strong>отправить заявку </strong></p></td></tr><tr><td><p><strong>Наименование </strong></p></td><td><p><strong>Марка стали </strong></p></td><td><p><strong>ГОСТ </strong></p></td><td><p><strong>Цена, тн. </strong></p></td></tr><tr><td><p><strong>Арматура 8 </strong></p></td><td><p>ст3сп </p></td><td><p>ГОСТ 5781-82 </p></td><td></td></tr><tr><td><p><strong>Арматура 10 </strong></p></td><td><p>ст3сп </p></td><td><p>ГОСТ 5781-82 </p></td><td></td></tr><tr><td><p><strong>Арматура 12 </strong></p></td><td><p>ст3сп </p></td><td><p>ГОСТ 5781-82 </p></td><td></td></tr><tr><td><p><strong>Арматура 14 </strong></p></td><td><p>ст3сп </p></td><td><p>ГОСТ 5781-82 </p></td><td></td></tr><tr><td><p><strong>Арматура 16 </strong></p></td><td><p>ст3сп </p></td><td><p>ГОСТ 5781-82 </p></td><td></td></tr><tr><td><p><strong>Арматура 18 </strong></p></td><td><p>ст3сп </p></td><td><p>ГОСТ 5781-82 </p></td><td></td></tr><tr><td><p><strong>Арматура 20 </strong></p></td><td><p>ст3сп </p></td><td><p>ГОСТ 5781-82 </p></td><td></td></tr><tr><td></td><td></td><td></td><td></td><td></td></tr><tr><td colspan="3"><p><strong>Арматура строительная рифленая А500С </strong></p></td><td></td><td rowspan="16"><p><strong>отправить заявку </strong></p></td></tr><tr><td><p><strong>Наименование </strong></p></td><td><p><strong>Марка стали </strong></p></td><td><p><strong>ГОСТ </strong></p></td><td><p><strong>Цена, тн. </strong></p></td></tr><tr><td><p><strong>Арматура 6 </strong></p></td><td><p>35ГС, 25Г2С </p></td><td><p>ГОСТ 5781-82 </p></td><td></td></tr><tr><td><p><strong>Арматура 8 </strong></p></td><td><p>35ГС, 25Г2С </p></td><td><p>ГОСТ 5781-82 </p></td><td></td></tr><tr><td><p><strong>Арматура 10 </strong></p></td><td><p>35ГС, 25Г2С </p></td><td><p>ГОСТ 5781-82 </p></td><td></td></tr><tr><td><p><strong>Арматура 12 </strong></p></td><td><p>35ГС, 25Г2С </p></td><td><p>ГОСТ 5781-82 </p></td><td></td></tr><tr><td><p><strong>Арматура 14 </strong></p></td><td><p>35ГС, 25Г2С </p></td><td><p>ГОСТ 5781-82 </p></td><td></td></tr><tr><td><p><strong>Арматура 16 </strong></p></td><td><p>35ГС, 25Г2С </p></td><td><p>ГОСТ 5781-82 </p></td><td></td></tr><tr><td><p><strong>Арматура 18 </strong></p></td><td><p>35ГС, 25Г2С </p></td><td><p>ГОСТ 5781-82 </p></td><td></td></tr><tr><td><p><strong>Арматура 20 </strong></p></td><td><p>35ГС, 25Г2С </p></td><td><p>ГОСТ 5781-82 </p></td><td></td></tr><tr><td><p><strong>Арматура 22 </strong></p></td><td><p>35ГС, 25Г2С </p></td><td><p>ГОСТ 5781-82 </p></td><td></td></tr><tr><td><p><strong>Арматура 25 </strong></p></td><td><p>35ГС, 25Г2С </p></td><td><p>ГОСТ 5781-82 </p></td><td></td></tr><tr><td><p><strong>Арматура 28 </strong></p></td><td><p>35ГС, 25Г2С </p></td><td><p>ГОСТ 5781-82 </p></td><td></td></tr><tr><td><p><strong>Арматура 32 </strong></p></td><td><p>35ГС, 25Г2С </p></td><td><p>ГОСТ 5781-82 </p></td><td></td></tr><tr><td><p><strong>Арматура 36 </strong></p></td><td><p>35ГС, 25Г2С </p></td><td><p>ГОСТ 5781-82 </p></td><td></td></tr><tr><td><p><strong>Арматура 40 </strong></p></td><td><p>35ГС, 25Г2С </p></td><td><p>ГОСТ 5781-82 </p></td><td></td></tr></tbody></table><p>На главную страницу </p></div>','assets/img/products/p2__69966bb45d886e01e78a0993.jpg','т',NULL,'Укажите размеры, марку стали, требуемый стандарт, количество или массу и условия поставки.',1,1,883,'Арматурный прокат — купить по заявке | Монополия','Арматурный прокат: подбор и поставка в Санкт-Петербурге. Укажите размеры, марку стали, требуемый стандарт, количество или массу и условия поставки. Расчет стоимости — по заявке.','site/www.monopoly-torg.ru/armatura__d0546a61f9983d333d99e526.html','[]','["assets/img/products/p2__69966bb45d886e01e78a0993.jpg"]','["http://www.monopoly-torg.ru/index.php/metalloprocat/armatura"]') ON DUPLICATE KEY UPDATE `category_id`=VALUES(`category_id`),`root_category`=VALUES(`root_category`),`name`=VALUES(`name`),`slug`=VALUES(`slug`),`sku`=VALUES(`sku`),`short_description`=VALUES(`short_description`),`description_html`=VALUES(`description_html`),`image`=VALUES(`image`),`unit`=VALUES(`unit`),`price`=VALUES(`price`),`request_hint`=VALUES(`request_hint`),`active`=VALUES(`active`),`featured`=VALUES(`featured`),`sort_order`=VALUES(`sort_order`),`seo_title`=VALUES(`seo_title`),`seo_description`=VALUES(`seo_description`),`source_file`=VALUES(`source_file`),`specs_json`=VALUES(`specs_json`),`gallery_json`=VALUES(`gallery_json`),`old_urls_json`=VALUES(`old_urls_json`);
INSERT INTO `products` (`id`,`category_id`,`root_category`,`name`,`slug`,`sku`,`short_description`,`description_html`,`image`,`unit`,`price`,`request_hint`,`active`,`featured`,`sort_order`,`seo_title`,`seo_description`,`source_file`,`specs_json`,`gallery_json`,`old_urls_json`) VALUES (884,2,'metal','Балка двутавровая стальная','metal-balka-dvutavrovaya-stalnaya','MNP-0884','Балка двутавровая стальная – является элементов несущей конструкции, который широко используют в промышленном и гражданском строительстве. Балка двутавровая представляет собой металлический профиль формы «Н», такая форма помогает наиболее выгодно.','<div>Балка двутавровая стальная <p><strong>Балка двутавровая стальная </strong>– является элементов несущей конструкции, который широко используют в промышленном и гражданском строительстве. <em>Балка двутавровая </em>представляет собой металлический профиль формы «Н», такая форма помогает наиболее выгодно распределять нагрузки на материал. В несущей конструкции двутавровая балка работает на изгиб. </p><p><img alt="Балка двутавровая стальная" loading="lazy" src="assets/img/products/p1__34dd9013d798ff14c74856da.jpg"/>Балка двутавровая стальная это материал, обладающий высокими прочностными характеристиками, очень широко используется в строительстве, балки применяются в междуэтажных перекрытиях, колонн, мостов. Так же к основным отличительным характеристикам относятся экономичность и легкость использования. </p><p>В зависимости от внешней формы и полок, способов производства балка двутавровая подразделяется на: </p><ul><li>ГОСТ8239-89. Балка двутавровая горячекатаная. Наиболее трудоемки в производстве. Производятся двух типов – с уклоном внутренних и параллельными гранями полок. Производятся из материала углеродистой или низколегированной стали. По точности прокатки различаются на: балки двутавровые горячекатаные повешенной прочности (Б) и обычной прочности (В). </li><li>ГОСТ 19425-74. Балка двутавровая стальная специальная. Используется в строительстве подвесных путей, армировании шахтных стволов, в качестве швеллера для автомобильной промышленности. По прочности прокатки балки двутавровые специальные различают: высокой прочности (А) и обычной прочности (В) </li><li>ГОСТ 26020-83. Балка двутавровая с параллельными гранями полок. Высота полок от 100 до 1000 мм., ширина полок 55-400 мм. Является наиболее распространенным в использовании. Балки двутавровые с параллельными гранями полок разделяют на: нормальные двутавры (Б), широкополочные двутавры (Ш), колонные двутавры (К). </li></ul><p>Торговая Компания Монополия предлагает различные марки балки двутавровой стальной. Менеджеры нашей компании произведут расчеты необходимого количества материалов, организуют доставку на объект. </p><h2>Балка двутавровая стальная Типоразмеры и исполнения </h2><table><tbody><tr><td colspan="3"><p><strong>Балка двутавровая стальная </strong></p></td><td></td><td rowspan="20"><p><strong>отправить заявку </strong></p></td></tr><tr><td><p><strong>Наименование </strong></p></td><td><p><strong>Марка стали </strong></p></td><td><p><strong>ГОСТ </strong></p></td><td><p><strong>Цена, тн. </strong></p></td></tr><tr><td><p><strong>Балка 10 </strong></p></td><td><p>Ст. 3сп/пс5 </p></td><td><p>ГОСТ 8239-89 </p></td><td></td></tr><tr><td><p><strong>Балка 12 </strong></p></td><td><p>Ст. 3сп/пс5 </p></td><td><p>ГОСТ 8239-89 </p></td><td></td></tr><tr><td><p><strong>Балка 14 </strong></p></td><td><p>Ст. 3сп/пс5 </p></td><td><p>ГОСТ 8239-89 </p></td><td></td></tr><tr><td><p><strong>Балка 16 </strong></p></td><td><p>Ст. 3сп/пс5 </p></td><td><p>ГОСТ 8239-89 </p></td><td></td></tr><tr><td><p><strong>Балка 18 </strong></p></td><td><p>Ст. 3сп/пс5 </p></td><td><p>ГОСТ 8239-89 </p></td><td></td></tr><tr><td><p><strong>Балка 20 </strong></p></td><td><p>Ст. 3сп/пс5 </p></td><td><p>ГОСТ 8239-89 </p></td><td></td></tr><tr><td><p><strong>Балка 30 </strong></p></td><td><p>Ст. 3сп/пс5 </p></td><td><p>ГОСТ 8239-89 </p></td><td></td></tr><tr><td><p><strong>Балка 36 </strong></p></td><td><p>Ст. 3сп/пс5 </p></td><td><p>ГОСТ 8239-89 </p></td><td></td></tr><tr><td><p><strong>Балка 45 </strong></p></td><td><p>Ст. 3сп/пс5 </p></td><td><p>ГОСТ 8239-89 </p></td><td></td></tr><tr><td><p><strong>Балка 10 </strong></p></td><td><p>Ст.09г2с </p></td><td><p>ГОСТ 8239-89 </p></td><td></td></tr><tr><td><p><strong>Балка 12 </strong></p></td><td><p>Ст.09г2с </p></td><td><p>ГОСТ 8239-89 </p></td><td></td></tr><tr><td><p><strong>Балка 14 </strong></p></td><td><p>Ст.09г2с </p></td><td><p>ГОСТ 8239-89 </p></td><td></td></tr><tr><td><p><strong>Балка 16 </strong></p></td><td><p>Ст.09г2с </p></td><td><p>ГОСТ 8239-89 </p></td><td></td></tr><tr><td><p><strong>Балка 18 </strong></p></td><td><p>Ст.09г2с </p></td><td><p>ГОСТ 8239-89 </p></td><td></td></tr><tr><td><p><strong>Балка 20 </strong></p></td><td><p>Ст.09г2с </p></td><td><p>ГОСТ 8239-89 </p></td><td></td></tr><tr><td><p><strong>Балка 30 </strong></p></td><td><p>Ст.09г2с </p></td><td><p>ГОСТ 8239-89 </p></td><td></td></tr><tr><td><p><strong>Балка 36 </strong></p></td><td><p>Ст.09г2с </p></td><td><p>ГОСТ 8239-89 </p></td><td></td></tr><tr><td><p><strong>Балка 45 </strong></p></td><td><p>Ст.09г2с </p></td><td><p>ГОСТ 8239-89 </p></td><td></td></tr></tbody></table><p>На главную страницу </p></div>','assets/img/products/p1__34dd9013d798ff14c74856da.jpg','т',NULL,'Укажите размеры, марку стали, требуемый стандарт, количество или массу и условия поставки.',1,0,884,'Балка двутавровая стальная — купить по заявке | Монополия','Балка двутавровая стальная: подбор и поставка в Санкт-Петербурге. Укажите размеры, марку стали, требуемый стандарт, количество или массу и условия поставки. Расчет стоимости — по заявке.','site/www.monopoly-torg.ru/balka-dvutavrovaya-stalnaya__1d4ee58fc6508bd7a5e7f8fe.html','[]','["assets/img/products/p1__34dd9013d798ff14c74856da.jpg"]','["http://www.monopoly-torg.ru/index.php/metalloprocat/balka-dvutavrovaya-stalnaya"]') ON DUPLICATE KEY UPDATE `category_id`=VALUES(`category_id`),`root_category`=VALUES(`root_category`),`name`=VALUES(`name`),`slug`=VALUES(`slug`),`sku`=VALUES(`sku`),`short_description`=VALUES(`short_description`),`description_html`=VALUES(`description_html`),`image`=VALUES(`image`),`unit`=VALUES(`unit`),`price`=VALUES(`price`),`request_hint`=VALUES(`request_hint`),`active`=VALUES(`active`),`featured`=VALUES(`featured`),`sort_order`=VALUES(`sort_order`),`seo_title`=VALUES(`seo_title`),`seo_description`=VALUES(`seo_description`),`source_file`=VALUES(`source_file`),`specs_json`=VALUES(`specs_json`),`gallery_json`=VALUES(`gallery_json`),`old_urls_json`=VALUES(`old_urls_json`);
INSERT INTO `products` (`id`,`category_id`,`root_category`,`name`,`slug`,`sku`,`short_description`,`description_html`,`image`,`unit`,`price`,`request_hint`,`active`,`featured`,`sort_order`,`seo_title`,`seo_description`,`source_file`,`specs_json`,`gallery_json`,`old_urls_json`) VALUES (885,2,'metal','Катанка','metal-katanka','MNP-0885','Катанка – представляет собой горячекатаную проволоку круглого сечения от 5 до 10 миллиметров в диаметре. Изготавливается и наматывается в бухты катанка на различных станках – проволочных или проволочно-сортовых.','<div>Катанка <p><strong>Катанка </strong>– представляет собой горячекатаную проволоку круглого сечения от 5 до 10 миллиметров в диаметре. Изготавливается и наматывается в бухты катанка на различных станках – проволочных или проволочно-сортовых. </p><p><img alt="Катанка" loading="lazy" src="assets/img/products/i1__9c4e692b0e5377ac05b42c85.jpg"/>В зависимости от того, какого размера или из какого материала сделана <em>катанка </em>, а так же благодаря отличной тонко и тепло проводимостью исходных материалов - ее применение разнообразно – к примеру, алюминиевая и медная катанка используется в приборостроении, производстве конструкций для электроники и оборудования, кабельная продукция. </p><p>Различают <strong>оцинкованную катанку </strong>, отличающуюся эстетическими качествами, которые позволяют применять ее как отделочных материал интерьера. Так же катанку применяют для изготовления оборудования механизмов заземления, устройства систем молниезащиты. Оцинкованную стальную катанку применяют для защиты от возгорания легко воспламеняемых проводов. </p><p>Катанка так же выпускается без покрытий, такая продукция используется в качестве заготовки разнообразных изделий проволоки и арматуры. </p><p>Торговая Компания Монополия предлагает продукцию катанка по доступным ценам и в кротчайшие сроки. Менеджера компании помогут рассчитать необходимое количество и марку требуемой продукции, а так же организуют доставку на объект. </p><h2>Катанка Типоразмеры и исполнения </h2><table><tbody><tr><td colspan="2"><p><strong>Катанка </strong></p></td><td></td><td rowspan="13"><p><strong>отправить заявку </strong></p></td></tr><tr><td><p><strong>Наименование </strong></p></td><td><p><strong>ГОСТ </strong></p></td><td><p><strong>Цена, тн. </strong></p></td></tr><tr><td><p><strong>Катанка 5,5 </strong></p></td><td><p>ГОСТ 30136-94 </p></td><td></td></tr><tr><td><p><strong>Катанка 5,5 </strong></p></td><td><p>ГОСТ 30136-95 </p></td><td></td></tr><tr><td><p><strong>Катанка 6,5 </strong></p></td><td><p>ГОСТ 30136-94 </p></td><td></td></tr><tr><td><p><strong>Катанка 6,5 </strong></p></td><td><p>ГОСТ 30136-95 </p></td><td></td></tr><tr><td><p><strong>Катанка 6,5 </strong></p></td><td><p>ТУ 14-1-5282-94 </p></td><td></td></tr><tr><td><p><strong>Катанка 6,5 </strong></p></td><td><p>ТУ 14-1-5283-94 </p></td><td></td></tr><tr><td><p><strong>Катанка 8 </strong></p></td><td><p>ГОСТ 30136-95 </p></td><td></td></tr><tr><td><p><strong>Катанка 8 </strong></p></td><td><p>ТУ 14-1-5282-94 </p></td><td></td></tr><tr><td><p><strong>Катанка 8 </strong></p></td><td><p>ТУ 14-1-5283-94 </p></td><td></td></tr><tr><td><p><strong>Катанка 10 </strong></p></td><td><p>ГОСТ 30136-95 </p></td><td></td></tr><tr><td><p><strong>Катанка 10 </strong></p></td><td><p>ТУ 14-1-5283-94 </p></td><td></td></tr></tbody></table><p>На главную страницу </p></div>','assets/img/products/i1__9c4e692b0e5377ac05b42c85.jpg','т',NULL,'Укажите размеры, марку стали, требуемый стандарт, количество или массу и условия поставки.',1,0,885,'Катанка — купить по заявке | Монополия','Катанка: подбор и поставка в Санкт-Петербурге. Укажите размеры, марку стали, требуемый стандарт, количество или массу и условия поставки. Расчет стоимости — по заявке.','site/www.monopoly-torg.ru/katanka__3e4105360e85b7f67b441d6c.html','[]','["assets/img/products/i1__9c4e692b0e5377ac05b42c85.jpg"]','["http://www.monopoly-torg.ru/index.php/metalloprocat/katanka"]') ON DUPLICATE KEY UPDATE `category_id`=VALUES(`category_id`),`root_category`=VALUES(`root_category`),`name`=VALUES(`name`),`slug`=VALUES(`slug`),`sku`=VALUES(`sku`),`short_description`=VALUES(`short_description`),`description_html`=VALUES(`description_html`),`image`=VALUES(`image`),`unit`=VALUES(`unit`),`price`=VALUES(`price`),`request_hint`=VALUES(`request_hint`),`active`=VALUES(`active`),`featured`=VALUES(`featured`),`sort_order`=VALUES(`sort_order`),`seo_title`=VALUES(`seo_title`),`seo_description`=VALUES(`seo_description`),`source_file`=VALUES(`source_file`),`specs_json`=VALUES(`specs_json`),`gallery_json`=VALUES(`gallery_json`),`old_urls_json`=VALUES(`old_urls_json`);
INSERT INTO `products` (`id`,`category_id`,`root_category`,`name`,`slug`,`sku`,`short_description`,`description_html`,`image`,`unit`,`price`,`request_hint`,`active`,`featured`,`sort_order`,`seo_title`,`seo_description`,`source_file`,`specs_json`,`gallery_json`,`old_urls_json`) VALUES (886,2,'metal','Квадрат металлический','metal-kvadrat','MNP-0886','Квадрат металлический представляет собой изделие сортового проката, квадратной формы, без полостей. Изготавливается квадрат металлический из углеродистой легированной или низколегированной стали.','<div>Квадрат металлический <p><strong>Квадрат металлический </strong>представляет собой изделие сортового проката, квадратной формы, без полостей. Изготавливается <em>квадрат металлический </em>из углеродистой легированной или низколегированной стали. </p><p><img alt="Квадрат металлический" loading="lazy" src="assets/img/products/z3503__93cb84da93d4cf49aee490c2.jpg"/>Квадрат металлический способен выдерживать большие нагрузки, обладает высоким уровнем прочности и отличается химической и механической стойкостью. </p><p>Квадрат металлический применяется в промышленном строительстве в качестве декоративных изделий, так же в качестве деталей для машиностроения и сельскохозяйственной техники. Так же квадрат используется как элемент заготовки при производстве осей, шпинделей, втулок и пр. </p><p>Квадрат стальной производится шириной от 5 – 20 мм. </p><h2>Квадрат металлический Типоразмеры и исполнения </h2><table><tbody><tr><td colspan="3"><p><strong>Квадрат </strong></p></td><td></td><td rowspan="7"><p><strong>отправить заявку </strong></p></td></tr><tr><td><p><strong>Наименование </strong></p></td><td><p><strong>Марка стали </strong></p></td><td><p><strong>ГОСТ </strong></p></td><td><p><strong>Цена, тн. </strong></p></td></tr><tr><td><p><strong>Квадрат 10 </strong></p></td><td><p>Ст3 </p></td><td><p>ГОСТ 2591-88 </p></td><td></td></tr><tr><td><p><strong>Квадрат 12 </strong></p></td><td><p>Ст3 </p></td><td><p>ГОСТ 2591-88 </p></td><td></td></tr><tr><td><p><strong>Квадрат 14 </strong></p></td><td><p>Ст3 </p></td><td><p>ГОСТ 2591-88 </p></td><td></td></tr><tr><td><p><strong>Квадрат 16 </strong></p></td><td><p>Ст3 </p></td><td><p>ГОСТ 2591-88 </p></td><td></td></tr><tr><td><p><strong>Квадрат 20 </strong></p></td><td><p>Ст3 </p></td><td><p>ГОСТ 2591-88 </p></td><td></td></tr></tbody></table><p>На главную страницу </p></div>','assets/img/products/z3503__93cb84da93d4cf49aee490c2.jpg','т',NULL,'Укажите размеры, марку стали, требуемый стандарт, количество или массу и условия поставки.',1,1,886,'Квадрат металлический — купить по заявке | Монополия','Квадрат металлический: подбор и поставка в Санкт-Петербурге. Укажите размеры, марку стали, требуемый стандарт, количество или массу и условия поставки. Расчет стоимости — по заявке.','site/www.monopoly-torg.ru/kvadrat__578f38e9b12c38cd0986ab50.html','[]','["assets/img/products/z3503__93cb84da93d4cf49aee490c2.jpg"]','["http://www.monopoly-torg.ru/index.php/metalloprocat/kvadrat"]') ON DUPLICATE KEY UPDATE `category_id`=VALUES(`category_id`),`root_category`=VALUES(`root_category`),`name`=VALUES(`name`),`slug`=VALUES(`slug`),`sku`=VALUES(`sku`),`short_description`=VALUES(`short_description`),`description_html`=VALUES(`description_html`),`image`=VALUES(`image`),`unit`=VALUES(`unit`),`price`=VALUES(`price`),`request_hint`=VALUES(`request_hint`),`active`=VALUES(`active`),`featured`=VALUES(`featured`),`sort_order`=VALUES(`sort_order`),`seo_title`=VALUES(`seo_title`),`seo_description`=VALUES(`seo_description`),`source_file`=VALUES(`source_file`),`specs_json`=VALUES(`specs_json`),`gallery_json`=VALUES(`gallery_json`),`old_urls_json`=VALUES(`old_urls_json`);
INSERT INTO `products` (`id`,`category_id`,`root_category`,`name`,`slug`,`sku`,`short_description`,`description_html`,`image`,`unit`,`price`,`request_hint`,`active`,`featured`,`sort_order`,`seo_title`,`seo_description`,`source_file`,`specs_json`,`gallery_json`,`old_urls_json`) VALUES (887,2,'metal','Листовой прокат','metal-listovoj-prokat','MNP-0887','Листовой прокат (листы стальные) предназначается для изготовления сварных труб и конструкций, гнутых профилей, корпусов судов, химической и теплообменной аппаратуры, кузовов автомобилей, летательных аппаратов и вагонов, корпусов электрошкафов,.','<div>Листовой прокат <p><strong><img alt="Листовой прокат" loading="lazy" src="assets/img/products/v1__eb8666d9e4d74271d8561c9d.jpg"/>Листовой прокат </strong>(листы стальные) предназначается для изготовления сварных труб и конструкций, гнутых профилей, корпусов судов, химической и теплообменной аппаратуры, кузовов автомобилей, летательных аппаратов и вагонов, корпусов электрошкафов, электронных машин, холодильников и многих других изделий. Лист стальной обеспечивает оптимальные решения конструкционных задач при минимизации затрат металла. </p><p><strong>По способу производства </strong><em>листовой прокат </em><strong>подразделяются на: </strong></p><ul><li>Горячекатаные; </li><li>Холоднокатаные. </li></ul><p><strong>По толщине: </strong></p><ul><li>Тонколистовой прокат – 0,4-3,9мм; </li><li>Толстолистовой прокат – 4-160мм. </li></ul><p><strong>По видам поставки </strong>листовой прокат <strong>: </strong></p><ul><li>В рулонах; </li><li>В листах. </li></ul><p><strong>По наличию покрытия: </strong></p><ul><li>Непокрытый листовой прокат; </li><li>Оцинкованный листовой прокат; </li><li>Листовой прокат с полимерным покрытием. </li></ul><h2>Листовой прокат </h2><p><strong>Прокат листовой горячекатаный по ГОСТ 19903-74 </strong></p><p>Стандарт распространяется на листовой г/к прокат шириной 500мм и более, изготовляемый в листах толщиной от 0,4мм до 160мм и рулонах толщиной от 1,2мм до 12мм. </p><p>Листовой прокат подразделяют: </p><ol><li>По точности прокатки при толщине до 12мм: <ul><li><strong>A </strong>— повышенной точности; </li><li><strong>Б </strong>— нормальной точности. </li></ul></li><li>По плоскостности: <ul><li><strong>ПН </strong>— нормальной плоскостности; </li><li><strong>ПУ </strong>— улучшеной плоскостности; </li><li><strong>ПВ </strong>— высокой плоскостности; </li><li><strong>ПО </strong>— особо высокой плоскостности. </li></ul></li><li>По характеру кромки: <ul><li><strong>НО </strong>— с необрезной кромкой; </li><li><strong>О </strong>— с обрезной кромкой. </li></ul></li><li>По размерам: <ul><li><strong>I </strong>— с указанием размеров по толщине, ширине и длине; </li><li><strong>II </strong>— с указанием размеров по толщине; </li><li><strong>III </strong>— с указанием размеров, кратных по ширине и длине; </li><li><strong>IV </strong>— с указанием мерных размеров по ширине и длине. </li></ul></li></ol><p>Прокат в рулонах может состоять не более чем из 2-х кусков (отдельных или соединенных сварным швом). </p><p>Прокат тонколистовой (толщина 0,4–3,9мм) из углеродистой стали качественной и обыкновенного качества общего назначения изготавливается по <strong>ГОСТ 16523-89 </strong></p><p>Прокат толстолистовой (толщина 4–160мм) из углеродистой стали обыкновенного качества изготавливается по <strong>ГОСТ 14637-89. </strong></p><p>Прокат листовой из низколегированной стали изготавливается согласно <strong>ГОСТ 19281-89. </strong><br/>В зависимости от вида металлопродукции и толщины, листы стальные г/к низколегированные изготавливают из сталей марок: I09Г2, 09Г2С, 09Г2С-12, 17Г1С, 17Г1СУ, 10ХСНД. </p><p><strong>Прокат листовой для судостроения по ГОСТ 5521-93 </strong></p><p><br/>Стандарт распространяется на толстолистовой, широкополосный универсальный, полосовой и фасонный прокат из стали нормальной и повышенной прочности для судостроения. </p><p>Прокат изготавливают из стали марок: </p><ul><li><strong>A, B, D, E </strong>— нормальной прочности; </li><li><strong>A27S, D27S, E27S, A32, D32, E32, A36,D36, E36, A40, D40, E40, A40S, D40S, E40S </strong>— повышенной прочности. </li></ul><p>Индекс «РС» перед обозначением марки стали указывает на то, что изготовление проката проходило под надзором Регистра (например, РС А32). Инспектор Регистра оформляет сертификат, свидетельствующий о соответствии стали Правилам Регистра. </p><p>Листы стальные с ромбическим и чечевичным рифлением производятся согласно <strong>ГОСТ 8568-77. </strong><br/>Стандарт распространяется на стальные горячекатаные с односторонним ромбическим или чечевичным рифлением листы общего назначения. Рифленый прокат изготавливают из углеродистой стали обыкновенного качества марок Ст0, Ст1, Ст2, Ст3 (кипящей, спокойной и полуспокойной) с химическим составом по ГОСТ 380. <br/>Основное назначение стали листовой рифленой — это напольные и стеновые покрытия. </p><p>Просечно-вытяжной лист (лист ПВЛ) производится по <strong>ТУ 36.26.11-5-89. </strong><br/>Изготовление просечно-вытяжного листа заключается в прорезании и вытягивании листов из горячекатаной стали, холоднокатаной стали, оцинкованной или нержавеющей стали. <br/>Просечно-вытяжной лист применяется: </p><ul><li>для изготовления настилов и ступеней маршевых лестниц; </li><li>для разнообразных ограждений по требованиям безопасности и эстетики; </li><li>для изготовления ограждений садовых и дворовых участков, окон, квартир, балконов, веранд, отопительных батарей; </li><li>для заделки смотровых, вентиляционных окон в станках, приборах, сельхозмашинах; </li><li>для изготовления различной тары; </li><li>для просеивания измельченной породы; </li><li>в качестве арматуры для нанесения штукатурки; </li><li>для изготовления крепи при проходческих работах в шахтах и т.п.; </li><li>для изготовления светорассеивающих ограждений на дорогах со встречным движением. </li></ul><p><strong>Прокат листовой холоднокатаный по ГОСТ 19904-90 </strong></p><p>Стандарт распространяется на листовой холоднокатаный прокат шириной 500мм и более, изготовляемый в листах толщиной от 0,35мм до 5,0мм и рулонах толщиной от 0,35 до 3,5 мм. </p><p>Листовой прокат подразделяют: </p><ol><li>По точности изготовления: <ol><li>По толщине: <ul><li><strong>БТ </strong>— нормальная; </li><li><strong>АТ </strong>— повышенная; </li><li><strong>ВТ </strong>— высокая; </li></ul></li><li>По ширине: <ul><li><strong>БШ </strong>— нормальная; </li><li><strong>АШ </strong>— повышенная; </li><li><strong>ВШ </strong>— высокая; </li></ul></li><li>По длине: <ul><li><strong>БД </strong>— нормальная; </li><li><strong>АД </strong>— повышенная; </li><li><strong>ВД </strong>— высокая; </li></ul></li></ol></li><li>По плоскостности: <ul><li><strong>ПН </strong>— нормальной плоскостности; </li><li><strong>ПУ </strong>— улучшеной плоскостности; </li><li><strong>ПВ </strong>— высокой плоскостности; </li><li><strong>ПО </strong>— особо высокой плоскостности; </li></ul></li><li>По характеру кромки: <ul><li><strong>НО </strong>— с необрезной кромкой; </li><li><strong>О </strong>— с обрезной кромкой. </li></ul></li></ol><p>Сталь тонколистовая оцинкованная с непрерывных линий <strong>ГОСТ 14918-80. </strong><br/>Стандарт распространяется на листовую и рулонную холоднокатаную сталь, оцинкованную горячим способом в агрегатах непрерывного цинкования, предназначенную для холодного профилирования, под окраску, изготовления штампованных деталей, посуды, тары и других металлических изделий. </p><p>Сталь тонколистовая оцинкованная подразделяется: </p><ol><li>По назначению на группы: <ul><li><strong>ХШ </strong>— для холодной штамповки; </li><li><strong>ХП </strong>— для холодного профилирования; </li><li><strong>ПК </strong>— под окраску (дрессированная); </li><li><strong>ОН </strong>— общего назначения. </li></ul></li><li>По способности к вытяжке (сталь группы ХШ) на категории: <ul><li><strong>Н </strong>— нормально вытяжки; </li><li><strong>Г </strong>— глубокой вытяжки; </li><li><strong>ВГ </strong>— весьма глубокой вытяжки. </li></ul></li><li>По равномерности толщины покрытия: <ul><li><strong>НР </strong>— с нормальной разнотолщинностью; </li><li><strong>УР </strong>— с уменьшенной разнотолщинностью. </li></ul></li></ol><p>По согласованию потребителя с изготовителем оцинкованная сталь может изготовляться: </p><ul><li><strong>КР </strong>– с узором кристаллизации; </li><li><strong>МТ </strong>– без узора кристаллизации. </li></ul><p>Типоразмеры и исполнения на листовой прокат </p><p>На главную страницу сайта </p></div>','assets/img/products/v1__eb8666d9e4d74271d8561c9d.jpg','т',NULL,'Укажите размеры, марку стали, требуемый стандарт, количество или массу и условия поставки.',1,0,887,'Листовой прокат — купить по заявке | Монополия','Листовой прокат: подбор и поставка в Санкт-Петербурге. Укажите размеры, марку стали, требуемый стандарт, количество или массу и условия поставки. Расчет стоимости — по заявке.','site/www.monopoly-torg.ru/listovoj-prokat__5b45c698e1c115507ec50a00.html','[]','["assets/img/products/v1__eb8666d9e4d74271d8561c9d.jpg"]','["http://www.monopoly-torg.ru/index.php/metalloprocat/listovoj-prokat"]') ON DUPLICATE KEY UPDATE `category_id`=VALUES(`category_id`),`root_category`=VALUES(`root_category`),`name`=VALUES(`name`),`slug`=VALUES(`slug`),`sku`=VALUES(`sku`),`short_description`=VALUES(`short_description`),`description_html`=VALUES(`description_html`),`image`=VALUES(`image`),`unit`=VALUES(`unit`),`price`=VALUES(`price`),`request_hint`=VALUES(`request_hint`),`active`=VALUES(`active`),`featured`=VALUES(`featured`),`sort_order`=VALUES(`sort_order`),`seo_title`=VALUES(`seo_title`),`seo_description`=VALUES(`seo_description`),`source_file`=VALUES(`source_file`),`specs_json`=VALUES(`specs_json`),`gallery_json`=VALUES(`gallery_json`),`old_urls_json`=VALUES(`old_urls_json`);
INSERT INTO `products` (`id`,`category_id`,`root_category`,`name`,`slug`,`sku`,`short_description`,`description_html`,`image`,`unit`,`price`,`request_hint`,`active`,`featured`,`sort_order`,`seo_title`,`seo_description`,`source_file`,`specs_json`,`gallery_json`,`old_urls_json`) VALUES (888,24,'metal','Лист горячекатаный','metal-list-goryachekatanyj-g-k','MNP-0888','Лист горячекатаный относится к черному металлопрокату – плоскому прокату. Лист горячекатаный – изделие плоской формы, представленный в различных толщинах. Производство горячекатаного листа происходит методом горячей прокатки.','<div>Лист горячекатаный <p><strong>Лист горячекатаный </strong>относится к черному металлопрокату – плоскому прокату. <em>Лист горячекатаный </em>– изделие плоской формы, представленный в различных толщинах. Производство горячекатаного листа происходит методом горячей прокатки. </p><p><img alt="Лист горячекатаный" loading="lazy" src="assets/img/products/v2__71dc75e94425521cbb5d0eaf.jpg"/>Ширина листа горячекатаного должна быть более 500 мм. Толщина будет зависеть от формы изготовления. Если лист производится отдельными листами – толщина может быть от 0,4 до 16 мм., если же лист горячекатаный изготавливается в рулонах – толщина составляет от 1,2 до 12 мм. </p><p>Материалом для производства горячекатаного листа может служить углеродистая сталь, конструкционная сталь или легированная сталь. </p><p>Так же лист горячекатаный , как и другие изделия металлопроката, подразделяется по точности прокатки, что составляет: Повышенная точность –А и нормальная точность –В. </p><p>Размеры выпускаемых листов: форма I – с указанием размеров по толщине, ширине и длине; форма II – с указанием размеров по толщине; форма III – с указанием кратных размеров по ширине и длине; форма IV – с указанием мерных размеров по ширине и длине. </p><p>По плоскости лист горячекатаный бывает: ПО – особо высокая плоскостность, ПВ – высокая плоскостность, ПУ – улучшенная плоскостность, ПН – нормальная плоскостность. </p><p>По характеру кромки листа лист горячекатаный бывает с необрезанной кровмкой, обозначается НО, и с обрезанной кромкой – О. </p><p>По отделке поверхности листа горячекатаного подразделяется на группу повышенной отделки – группа III , и группу обычной отделки – группа IV . </p><p>Помимо всего, лист горячекатаный может быть изготовлен с различной поверхностью – глянцевой, матовой и шероховатой, травленной и не травленной. </p><ul><li>Лист горячекатаный изготовляется в соответствии с <strong>ГОСТ 19903-74 </strong>, который определяет взаимозависимость толщины проката, ширины и длины листов, ширины рулона и его толщины. </li><li><strong>ГОСТ 14637-89 </strong>определяет допустимые марки стали для толстолистового проката. </li><li><strong>ГОСТ 16523-97 </strong>изложены требования к технологиям производства и маркам стали для тонколистового проката. </li></ul><h2>Лист горячекатаный цена </h2><table><tbody><tr><td colspan="3"><p><strong>Лист горячекатанный </strong></p></td><td></td><td rowspan="17"><p><strong>отправить заявку </strong></p></td></tr><tr><td><p><strong>Наименование </strong></p></td><td><p><strong>Марка стали </strong></p></td><td><p><strong>ГОСТ </strong></p></td><td><p><strong>Цена, тн. </strong></p></td></tr><tr><td><p><strong>1.5х1250х2500 </strong></p></td><td><p>3СП5 </p></td><td><p>ГОСТ 16523-89 </p></td><td></td></tr><tr><td><p><strong>2х1250х2500 </strong></p></td><td><p>3СП5 </p></td><td><p>ГОСТ 16523-89 </p></td><td></td></tr><tr><td><p><strong>2.5х1250х2500 </strong></p></td><td><p>3СП5 </p></td><td><p>ГОСТ 16523-89 </p></td><td></td></tr><tr><td><p><strong>3х1250х2500 </strong></p></td><td><p>3СП5 </p></td><td><p>ГОСТ 16523-89 </p></td><td></td></tr><tr><td><p><strong>4х1500х6000 </strong></p></td><td><p>3СП5 </p></td><td><p>ГОСТ 16523-89 </p></td><td></td></tr><tr><td><p><strong>5х1500х6000 </strong></p></td><td><p>3СП5 </p></td><td><p>ГОСТ 16523-89 </p></td><td></td></tr><tr><td><p><strong>6х1500х6000 </strong></p></td><td><p>3СП5 </p></td><td><p>ГОСТ 16523-89 </p></td><td></td></tr><tr><td><p><strong>8х1500х6000 </strong></p></td><td><p>3СП5 </p></td><td><p>ГОСТ 16523-89 </p></td><td></td></tr><tr><td><p><strong>10х1500х6000 </strong></p></td><td><p>3СП5 </p></td><td><p>ГОСТ 16523-89 </p></td><td></td></tr><tr><td><p><strong>12х1500х6000 </strong></p></td><td><p>3СП5 </p></td><td><p>ГОСТ 16523-89 </p></td><td></td></tr><tr><td><p><strong>14х1500х6000 </strong></p></td><td><p>3СП5 </p></td><td><p>ГОСТ 16523-89 </p></td><td></td></tr><tr><td><p><strong>16 х1500х6000 </strong></p></td><td><p>3СП5 </p></td><td><p>ГОСТ 16523-89 </p></td><td></td></tr><tr><td><p><strong>18 х1500х6000 </strong></p></td><td><p>3СП5 </p></td><td><p>ГОСТ 16523-89 </p></td><td></td></tr><tr><td><p><strong>20х1500х6000 </strong></p></td><td><p>3СП5 </p></td><td><p>ГОСТ 16523-89 </p></td><td></td></tr><tr><td><p><strong>25х1500х6000 </strong></p></td><td><p>3СП5 </p></td><td><p>ГОСТ 16523-89 </p></td><td></td></tr></tbody></table><p>На главную страницу сайта </p></div>','assets/img/products/v2__71dc75e94425521cbb5d0eaf.jpg','т',NULL,'Укажите размеры, марку стали, требуемый стандарт, количество или массу и условия поставки.',1,0,888,'Лист горячекатаный — купить по заявке | Монополия','Лист горячекатаный: подбор и поставка в Санкт-Петербурге. Укажите размеры, марку стали, требуемый стандарт, количество или массу и условия поставки. Расчет стоимости — по заявке.','site/www.monopoly-torg.ru/list-goryachekatanyj-g-k__baa3abad98d1eacbc03dc39c.html','[]','["assets/img/products/v2__71dc75e94425521cbb5d0eaf.jpg"]','["http://www.monopoly-torg.ru/index.php/metalloprocat/listovoj-prokat/list-goryachekatanyj-g-k"]') ON DUPLICATE KEY UPDATE `category_id`=VALUES(`category_id`),`root_category`=VALUES(`root_category`),`name`=VALUES(`name`),`slug`=VALUES(`slug`),`sku`=VALUES(`sku`),`short_description`=VALUES(`short_description`),`description_html`=VALUES(`description_html`),`image`=VALUES(`image`),`unit`=VALUES(`unit`),`price`=VALUES(`price`),`request_hint`=VALUES(`request_hint`),`active`=VALUES(`active`),`featured`=VALUES(`featured`),`sort_order`=VALUES(`sort_order`),`seo_title`=VALUES(`seo_title`),`seo_description`=VALUES(`seo_description`),`source_file`=VALUES(`source_file`),`specs_json`=VALUES(`specs_json`),`gallery_json`=VALUES(`gallery_json`),`old_urls_json`=VALUES(`old_urls_json`);
INSERT INTO `products` (`id`,`category_id`,`root_category`,`name`,`slug`,`sku`,`short_description`,`description_html`,`image`,`unit`,`price`,`request_hint`,`active`,`featured`,`sort_order`,`seo_title`,`seo_description`,`source_file`,`specs_json`,`gallery_json`,`old_urls_json`) VALUES (889,24,'metal','Лист холоднокатаный','metal-list-kholodnokatanyj-kh-k','MNP-0889','Лист холоднокатаный относится к черному металлопрокату – к листовому прокату. Листом холоднокатаным называют сталь листовую, произведенную методом холодной прокатки. Лист выпускается в виде листов и рулонов. Листы могут изготавливаться шириной от.','<div>Лист холоднокатаный <p><strong>Лист холоднокатаный </strong>относится к черному металлопрокату – к листовому прокату. Листом холоднокатаным называют сталь листовую, произведенную методом холодной прокатки. Лист выпускается в виде листов и рулонов. Листы могут изготавливаться шириной от 500 мм и толщине от 0,35 до 5 мм., при производстве рулонов, толщина допускается от 0,35 до 3,5 мм. </p><p><img alt="Лист холоднокатаный" loading="lazy" src="assets/img/products/v3__7ac49b335376c958ac071471.jpg"/><em>Лист холоднокатаный </em>общего назначения изготовляется из сталей следующих марок: 08кп, 08пс, 10кп, 10пс, 15кп, 15пс, 20кп, 20пс, 25, 30, 35, 40, 45. Химический состав сталей определяется ГОСТ 1050-88. Лист холоднокатаный из качественной стали для холодной штамповки изготовляется из сталей: 08Ю, 08пс, 08кп. </p><p>Производство листа холоднокатаного - осуществляется из горячекатаного листового проката путём удаления окалины с помощью кислотного травления. После травленый горячекатаный лист повторно пропускается через прокатный стан, но без предварительного нагрева. Так, достигается нужная толщина стального листа. После этого производится отжиг для достижения необходимых свойств. </p><p>Лист холоднокатаный подразделяется на группы: </p><p><strong>Первая группа - точность изготовления. </strong></p><ul><li>По толщине лист холоднокатаный подразделяется: высокая точность - ВТ; повышенная точность - АТ; нормальная точность - БТ. </li><li>По ширине листы подразделяются: ВШ - высокая точность; АШ - повышенная точность; БШ - нормальная точность. </li></ul><p><strong>Вторая группа - плоскостность </strong>: ПО - особо высокая плоскостность; ПВ - высокая плоскостность; ПУ - улучшенная плоскостность; ПН - нормальная плоскостность. </p><p><strong>Третья - по характеру кромки </strong>: О - обрезная кромка; НО - необрезная кромка. </p><p>Так же по отделке поверхности лист холоднокатаный различают: группа I - особо высокой отделки; группа II - высокой отделки; группа III - повышенной отделки. </p><p>Качество отделки поверхности листа холоднокатаного: I - особо высокой отделки (возможна глянцевая, матовая, шероховатая); II - высокой отделки (возможно нормирование шероховатости поверхности); III - повышенной отделки. </p><h2>Лист холоднокатаный цена </h2><table><tbody><tr><td colspan="3"><p><strong>Лист холоднокатанный </strong></p></td><td></td><td rowspan="15"><p><strong>отправить заявку </strong></p></td></tr><tr><td><p><strong>Наименование </strong></p></td><td><p><strong>Марка стали </strong></p></td><td><p><strong>ГОСТ </strong></p></td><td><p><strong>Цена, тн. </strong></p></td></tr><tr><td><p><strong>0.5х1250х2500 </strong></p></td><td><p>08ПС </p></td><td><p>ГОСТ 16523-89 </p></td><td></td></tr><tr><td><p><strong>0.6х1250х2500 </strong></p></td><td><p>08ПС </p></td><td><p>ГОСТ 16523-89 </p></td><td></td></tr><tr><td><p><strong>0.7х1250х2500 </strong></p></td><td><p>08ПС </p></td><td><p>ГОСТ 16523-89 </p></td><td></td></tr><tr><td><p><strong>0.8х1250х2500 </strong></p></td><td><p>08ПС </p></td><td><p>ГОСТ 16523-89 </p></td><td></td></tr><tr><td><p><strong>0.9х1250х2500 </strong></p></td><td><p>08ПС </p></td><td><p>ГОСТ 16523-89 </p></td><td></td></tr><tr><td><p><strong>1.0х1250х2500 </strong></p></td><td><p>08ПС </p></td><td><p>ГОСТ 16523-89 </p></td><td></td></tr><tr><td><p><strong>1.2х1250х2500 </strong></p></td><td><p>08ПС </p></td><td><p>ГОСТ 16523-89 </p></td><td></td></tr><tr><td><p><strong>1.4х1250х2500 </strong></p></td><td><p>08ПС </p></td><td><p>ГОСТ 16523-89 </p></td><td></td></tr><tr><td><p><strong>1.5х1250х2500 </strong></p></td><td><p>08ПС </p></td><td><p>ГОСТ 16523-89 </p></td><td></td></tr><tr><td><p><strong>1.8х1250х2500 </strong></p></td><td><p>08ПС </p></td><td><p>ГОСТ 16523-89 </p></td><td></td></tr><tr><td><p><strong>2.0х1250х2500 </strong></p></td><td><p>08ПС </p></td><td><p>ГОСТ 16523-89 </p></td><td></td></tr><tr><td><p><strong>2.5х1250х2500 </strong></p></td><td><p>08ПС </p></td><td><p>ГОСТ 16523-89 </p></td><td></td></tr><tr><td><p><strong>3.0х1250х2500 </strong></p></td><td><p>08ПС </p></td><td><p>ГОСТ 16523-89 </p></td><td></td></tr></tbody></table><p>На главную страницу сайта </p></div>','assets/img/products/v3__7ac49b335376c958ac071471.jpg','т',NULL,'Укажите размеры, марку стали, требуемый стандарт, количество или массу и условия поставки.',1,0,889,'Лист холоднокатаный — купить по заявке | Монополия','Лист холоднокатаный: подбор и поставка в Санкт-Петербурге. Укажите размеры, марку стали, требуемый стандарт, количество или массу и условия поставки. Расчет стоимости — по заявке.','site/www.monopoly-torg.ru/list-kholodnokatanyj-kh-k__60da34e88c99760cd953c1ba.html','[]','["assets/img/products/v3__7ac49b335376c958ac071471.jpg"]','["http://www.monopoly-torg.ru/index.php/metalloprocat/listovoj-prokat/list-kholodnokatanyj-kh-k"]') ON DUPLICATE KEY UPDATE `category_id`=VALUES(`category_id`),`root_category`=VALUES(`root_category`),`name`=VALUES(`name`),`slug`=VALUES(`slug`),`sku`=VALUES(`sku`),`short_description`=VALUES(`short_description`),`description_html`=VALUES(`description_html`),`image`=VALUES(`image`),`unit`=VALUES(`unit`),`price`=VALUES(`price`),`request_hint`=VALUES(`request_hint`),`active`=VALUES(`active`),`featured`=VALUES(`featured`),`sort_order`=VALUES(`sort_order`),`seo_title`=VALUES(`seo_title`),`seo_description`=VALUES(`seo_description`),`source_file`