INSERT INTO `products` (`id`,`category_id`,`root_category`,`name`,`slug`,`sku`,`short_description`,`description_html`,`image`,`unit`,`price`,`request_hint`,`active`,`featured`,`sort_order`,`seo_title`,`seo_description`,`source_file`,`specs_json`,`gallery_json`,`old_urls_json`) VALUES (890,24,'metal','Лист нержавеющий','metal-list-nerzhaveyushchij','MNP-0890','Лист нержавеющий – изделие листового металлопроката, выпускаемый в виде пластин, к нему относят тонколистовую и толстолистовую коррозионностойкую, жаростойкую и жаропрочную сталь. По способу изготовления может быть холоднокатаным и горячекатаным..','<div>Лист нержавеющий <p><strong><img alt="Лист нержавеющий" loading="lazy" src="assets/img/products/v6__68f9245f47c0876c4c496ac0.jpg"/>Лист нержавеющий </strong>– изделие листового металлопроката, выпускаемый в виде пластин, к нему относят тонколистовую и толстолистовую коррозионностойкую, жаростойкую и жаропрочную сталь. По способу изготовления может быть холоднокатаным и горячекатаным. <em>Лист нержавеющий </em>выпускается в различных формах, которые зависят от требуемой конфигурации изделия – от 1000 x 2000 мм. до 1500 x 6000 мм. </p><p>Лист нержавеющий нашел широкое применение в строительстве, архитектуре и дизайне. Нержавеющие листы с зеркальной поверхностью часто используют для отделки фасадов зданий и внутренней отделки. </p><p>Лист нержавеющий разделяется по типам поверхности: </p><ul><li>2В – матовая поверхность, </li><li>4 N – шлифованная поверхность, </li><li>ВА – зеркальная (различается на зеркало, матовое заркало, суперзеркало), </li><li>1 D – матовая, слегка шероховатая. </li></ul></div>','assets/img/products/v6__68f9245f47c0876c4c496ac0.jpg','т',NULL,'Укажите размеры, марку стали, требуемый стандарт, количество или массу и условия поставки.',1,0,890,'Лист нержавеющий — купить по заявке | Монополия','Лист нержавеющий: подбор и поставка в Санкт-Петербурге. Укажите размеры, марку стали, требуемый стандарт, количество или массу и условия поставки. Расчет стоимости — по заявке.','site/www.monopoly-torg.ru/list-nerzhaveyushchij__679d282a25cb22f954855d78.html','[]','["assets/img/products/v6__68f9245f47c0876c4c496ac0.jpg"]','["http://www.monopoly-torg.ru/index.php/metalloprocat/listovoj-prokat/list-nerzhaveyushchij"]') ON DUPLICATE KEY UPDATE `category_id`=VALUES(`category_id`),`root_category`=VALUES(`root_category`),`name`=VALUES(`name`),`slug`=VALUES(`slug`),`sku`=VALUES(`sku`),`short_description`=VALUES(`short_description`),`description_html`=VALUES(`description_html`),`image`=VALUES(`image`),`unit`=VALUES(`unit`),`price`=VALUES(`price`),`request_hint`=VALUES(`request_hint`),`active`=VALUES(`active`),`featured`=VALUES(`featured`),`sort_order`=VALUES(`sort_order`),`seo_title`=VALUES(`seo_title`),`seo_description`=VALUES(`seo_description`),`source_file`=VALUES(`source_file`),`specs_json`=VALUES(`specs_json`),`gallery_json`=VALUES(`gallery_json`),`old_urls_json`=VALUES(`old_urls_json`);
INSERT INTO `products` (`id`,`category_id`,`root_category`,`name`,`slug`,`sku`,`short_description`,`description_html`,`image`,`unit`,`price`,`request_hint`,`active`,`featured`,`sort_order`,`seo_title`,`seo_description`,`source_file`,`specs_json`,`gallery_json`,`old_urls_json`) VALUES (891,24,'metal','Лист оцинкованный','metal-list-otsinkovannyj-ot-0-3-do-3','MNP-0891','Лист оцинкованный широко применяется в промышленном строительстве, индивидуальном строительстве, а так же медицине, пищевой промышленности и машиностроении.','<div>Лист оцинкованный <p><strong><img alt="Лист оцинкованный" loading="lazy" src="assets/img/products/v5__73d1ff44f349aacaf6704e16.jpg"/>Лист оцинкованный </strong>широко применяется в промышленном строительстве, индивидуальном строительстве, а так же медицине, пищевой промышленности и машиностроении. </p><p><em>Лист оцинкованный </em>тонколистовой ГОСТ 14918-80 изготавливается шириной от 0,71 до 1,8 метров, при толщине 0,5-2,5 мм. Лист стальной электролитический при ширине от 0,71 до 1,8 м., может выпускаться в толщине 3 мм. </p><p>Лист оцинкованный выпускается с односторонним или двухсторонним цинкованием, что обеспечивает сохранение всех свойств при дальнейших методах обработки. Для цинкования используется цинк марок ЦО и Ц, согласно ГОСТ 3640-79 с добавление алюминия, свинца и пр. металлов. </p><p>Листы оцинкованные подразделяются на обычные листы и листы для холодной штамповки. </p><h2>Лист оцинкованный цена </h2><table><tbody><tr><td colspan="3"><p><strong>Лист оцинкованный </strong></p></td><td></td><td rowspan="11"><p><strong>отправить заявку </strong></p></td></tr><tr><td><p><strong>Наименование </strong></p></td><td><p><strong>Марка стали </strong></p></td><td><p><strong>ГОСТ </strong></p></td><td><p><strong>Цена, тн. </strong></p></td></tr><tr><td><p><strong>0.5х1250х2500 </strong></p></td><td><p>08ПС </p></td><td><p>ГОСТ 14918-80 </p></td><td></td></tr><tr><td><p><strong>0.55х1250х2500 </strong></p></td><td><p>08ПС </p></td><td><p>ГОСТ 14918-80 </p></td><td></td></tr><tr><td><p><strong>0.6х1250х2500 </strong></p></td><td><p>08ПС </p></td><td><p>ГОСТ 14918-80 </p></td><td></td></tr><tr><td><p><strong>0.7х1250х2500 </strong></p></td><td><p>08ПС </p></td><td><p>ГОСТ 14918-80 </p></td><td></td></tr><tr><td><p><strong>0.8х1250х2500 </strong></p></td><td><p>08ПС </p></td><td><p>ГОСТ 14918-80 </p></td><td></td></tr><tr><td><p><strong>1.0х1250х2500 </strong></p></td><td><p>08ПС </p></td><td><p>ГОСТ 14918-80 </p></td><td></td></tr><tr><td><p><strong>1.2х1250х2500 </strong></p></td><td><p>08ПС </p></td><td><p>ГОСТ 14918-80 </p></td><td></td></tr><tr><td><p><strong>1.4х1250х2500 </strong></p></td><td><p>08ПС </p></td><td><p>ГОСТ 14918-80 </p></td><td></td></tr><tr><td><p><strong>1.5х1250х2500 </strong></p></td><td><p>08ПС </p></td><td><p>ГОСТ 14918-80 </p></td><td></td></tr></tbody></table><p>На главную страницу </p></div>','assets/img/products/v5__73d1ff44f349aacaf6704e16.jpg','т',NULL,'Укажите размеры, марку стали, требуемый стандарт, количество или массу и условия поставки.',1,0,891,'Лист оцинкованный — купить по заявке | Монополия','Лист оцинкованный: подбор и поставка в Санкт-Петербурге. Укажите размеры, марку стали, требуемый стандарт, количество или массу и условия поставки. Расчет стоимости — по заявке.','site/www.monopoly-torg.ru/list-otsinkovannyj-ot-0-3-do-3__bcabe4b45ff112935ea25f59.html','[]','["assets/img/products/v5__73d1ff44f349aacaf6704e16.jpg"]','["http://www.monopoly-torg.ru/index.php/metalloprocat/listovoj-prokat/list-otsinkovannyj-ot-0-3-do-3"]') ON DUPLICATE KEY UPDATE `category_id`=VALUES(`category_id`),`root_category`=VALUES(`root_category`),`name`=VALUES(`name`),`slug`=VALUES(`slug`),`sku`=VALUES(`sku`),`short_description`=VALUES(`short_description`),`description_html`=VALUES(`description_html`),`image`=VALUES(`image`),`unit`=VALUES(`unit`),`price`=VALUES(`price`),`request_hint`=VALUES(`request_hint`),`active`=VALUES(`active`),`featured`=VALUES(`featured`),`sort_order`=VALUES(`so