INSERT INTO `products` (`id`,`category_id`,`root_category`,`name`,`slug`,`sku`,`short_description`,`description_html`,`image`,`unit`,`price`,`request_hint`,`active`,`featured`,`sort_order`,`seo_title`,`seo_description`,`source_file`,`specs_json`,`gallery_json`,`old_urls_json`) VALUES (892,24,'metal','Лист рифленый','metal-list-riflenyj-chechevitsa-romb','MNP-0892','Лист рифленый может быть изготовлен как в листе, так и в рулоне, по типу тиснения бывает ромбическим и чечевичным. Лист рифленый производится согласно ГОСТ 380-88 из углеродистой стали марок Ст0, Ст1, Ст2, Ст3. Лист рифленый может быть произведен.','<div>Лист рифленый <p><img alt="Лист рифленый" loading="lazy" src="assets/img/products/v4__bbd2a467933ac2e0af6a635d.jpg"/><strong>Лист рифленый </strong>может быть изготовлен как в листе, так и в рулоне, по типу тиснения бывает ромбическим и чечевичным. <em>Лист рифленый </em>производится согласно ГОСТ 380-88 из углеродистой стали марок Ст0, Ст1, Ст2, Ст3. Лист рифленый может быть произведен из стали другой марки. </p><p>Лист рифленый производится шириной от 600 до 2200 мм., длиной от 1400 до 8000 мм, толщиной от 2,5 до 12 мм. </p><p>Конфигурация рифлений и положение больших диагоналей ромба вдоль или поперек листа устанавливаются изготовителем. Листы с чечевичным рифлением изготовляют с расстоянием между рифлями 20, 25 и 30 мм. </p><p>Лист рифленый обладает анти скользящими свойствами, благодаря рифлению, и широко применяется в декоративных элементах отделки помещений, а так же в отделки лестниц и пандусов. </p><h2>Лист рифленый цена </h2><table><tbody><tr><td colspan="3"><p><strong>Лист рифленый </strong></p></td><td></td><td rowspan="10"><p><strong>отправить заявку </strong></p></td></tr><tr><td><p><strong>Наименование </strong></p></td><td><p><strong>Марка стали </strong></p></td><td><p><strong>ГОСТ </strong></p></td><td><p><strong>Цена, тн. </strong></p></td></tr><tr><td><p><strong>3х1250х2500 чечев. </strong></p></td><td><p>3сп/пс5 </p></td><td><p>ГОСТ 8568-77 </p></td><td></td></tr><tr><td><p><strong>3х1250х2500 ромб. </strong></p></td><td><p>3сп/пс5 </p></td><td><p>ГОСТ 8568-77 </p></td><td></td></tr><tr><td><p><strong>4х1500х6000 чечев. </strong></p></td><td><p>3сп/пс5 </p></td><td><p>ГОСТ 8568-77 </p></td><td></td></tr><tr><td><p><strong>4х1500х6000 ромб. </strong></p></td><td><p>3сп/пс5 </p></td><td><p>ГОСТ 8568-77 </p></td><td></td></tr><tr><td><p><strong>5х1500х6000 чечев </strong></p></td><td><p>3сп/пс5 </p></td><td><p>ГОСТ 8568-77 </p></td><td></td></tr><tr><td><p><strong>5х1500х6000 ромб. </strong></p></td><td><p>3сп/пс5 </p></td><td><p>ГОСТ 8568-77 </p></td><td></td></tr><tr><td><p><strong>6х1500х6000 чечев </strong></p></td><td><p>3сп/пс5 </p></td><td><p>ГОСТ 8568-77 </p></td><td></td></tr><tr><td><p><strong>6х1500х6000 ромб. </strong></p></td><td><p>3сп/пс5 </p></td><td><p>ГОСТ 8568-77 </p></td><td></td></tr></tbody></table><p>На главную страницу </p></div>','assets/img/products/v4__bbd2a467933ac2e0af6a635d.jpg','т',NULL,'Укажите размеры, марку стали, требуемый стандарт, количество или массу и условия поставки.',1,0,892,'Лист рифленый — купить по заявке | Монополия','Лист рифленый: подбор и поставка в Санкт-Петербурге. Укажите размеры, марку стали, требуемый стандарт, количество или массу и условия поставки. Расчет стоимости — по заявке.','site/www.monopoly-torg.ru/list-riflenyj-chechevitsa-romb__7017778d01a99998739c0687.html','[]','["assets/img/products/v4__bbd2a467933ac2e0af6a635d.jpg"]','["http://www.monopoly-torg.ru/index.php/metalloprocat/listovoj-prokat/list-riflenyj-chechevitsa-romb"]') ON DUPLICATE KEY UPDATE `category_id`=VALUES(`category_id`),`root_category`=VALUES(`root_category`),`name`=VALUES(`name`),`slug`=VALUES(`slug`),`sku`=VALUES(`sku`),`short_description`=VALUES(`short_description`),`description_html`=VALUES(`description_html`),`image`=VALUES(`image`),`unit`=VALUES(`unit`),`price`=VALUES(`price`),`request_hint`=VALUES(`request_hint`),`active`=VALUES(`active`),`featured`=VALUES(`featu