INSERT INTO `products` (`id`,`category_id`,`root_category`,`name`,`slug`,`sku`,`short_description`,`description_html`,`image`,`unit`,`price`,`request_hint`,`active`,`featured`,`sort_order`,`seo_title`,`seo_description`,`source_file`,`specs_json`,`gallery_json`,`old_urls_json`) VALUES (894,2,'metal','Полоса стальная','metal-polosa','MNP-0894','Полоса стальная горячекатаная изготавливается из различных марок стали, различных размеров. Полоса стальная используется в строительстве при необходимости достижения особой твердости и износостойкости.','<div>Полоса стальная <p><em>Полоса стальная </em>горячекатаная изготавливается из различных марок стали, различных размеров. Полоса стальная используется в строительстве при необходимости достижения особой твердости и износостойкости. </p><ul><li>ГОСТ 103-76 </li></ul><p><img alt="Полоса" loading="lazy" src="assets/img/products/o1__a1dce15c220d6636634ac244.jpg"/><strong>Полоса стальная </strong>используется в производстве конструктивных деталей, гнутых профилей. Полоса стальная изготавливается различных стандартных размеров: </p><p>Толщина изделия от 4 – 60 мм, ширина от 12 – 200 мм, длина от 4 – 9 м. </p><p>Так же возможно изготовление стальной полосы не стандартных размеров – длиной от 3 – 10 м. – из углеродной стали, низколегированной и фосфористой стали, а так же размеры длиной от 2 – 6 метров – из углеродистой и легированной стали. </p><h2>Полоса стальная Типоразмеры и исполнения </h2><table><tbody><tr><td colspan="3"><p><strong>Полоса </strong></p></td><td></td><td rowspan="5"><p><strong>отправить заявку </strong></p></td></tr><tr><td><p><strong>Наименование </strong></p></td><td><p><strong>Марка стали </strong></p></td><td><p><strong>ГОСТ </strong></p></td><td><p><strong>Цена, тн. </strong></p></td></tr><tr><td><p><strong>Полоса 25x4 </strong></p></td><td><p>Ст3 </p></td><td><p>ГОСТ 103-76 </p></td><td></td></tr><tr><td><p><strong>Полоса 40x4 </strong></p></td><td><p>Ст3 </p></td><td><p>ГОСТ 103-76 </p></td><td></td></tr><tr><td><p><strong>Полоса 50x4 </strong></p></td><td><p>Ст3 </p></td><td><p>ГОСТ 103-76 </p></td><td></td></tr></tbody></table><p>На главную страницу </p></div>','assets/img/products/o1__a1dce15c220d6636634ac244.jpg','т',NULL,'Укажите размеры, марку стали, требуемый стандарт, количество или массу и условия поставки.',1,0,894,'Полоса стальная — купить по заявке | Монополия','Полоса стальная: подбор и поставка в Санкт-Петербурге. Укажите размеры, марку стали, требуемый стандарт, количество или массу и условия поставки. Расчет стоимости — по заявке.','site/www.monopoly-torg.ru/polosa__52dc742deb308e982606d62b.html','[]','["assets/img/products/o1__a1dce15c220d6636634ac244.jpg"]','["http://www.monopoly-torg.ru/index.php/metalloprocat/polosa"]') ON DUPLICATE KEY UPDATE `category_id`=VALUES(`category_id`),`root_category`=VALUES(`root_category`),`name`=VALUES(`name`),`slug`=VALUES(`slug`),`sku`=VALUES(`sku`),`short_description`=VALUES(`short_description`),`description_html`=VALUES(`description_html`),`image`=VALUES(`image`),`unit`=VALUES(`unit`),`price`=VALUES(`price`),`request_hint`=VALUES(`request_hint`),`active`=VALUES(`active`),`featured`=VALUES(`featured`),`sort_order`=VALUES(`sort_order`),`seo_title`=VALUES(`seo_title`),`seo_description`=VALUES(`seo_description`),`source_file`=VALUES(`source_file`),`specs_json`=VALUES(`specs_json`),`gallery_json`=VALUES(`gallery_json`),`old_urls_json`=VALUES(`old_urls_json`);
INSERT INTO `products` (`id`,`category_id`,`root_category`,`name`,`slug`,`sku`,`short_description`,`description_html`,`image`,`unit`,`price`,`request_hint`,`active`,`featured`,`sort_order`,`seo_title`,`seo_description`,`source_file`,`specs_json`,`gallery_json`,`old_urls_json`) VALUES (895,2,'metal','Сетка сварная','metal-setka-svarnaya-iz-vr1-a3','MNP-0895','Торговая компания монополия предлагает поставку сетки сварной ВР1 и из арматуры кл. А3. Сварная сетка используется в промышленном строительстве для армирования железобетонных конструкций, кирпичной кладки, а так же при закладке фундаментов. Сетка.','<div>Сетка сварная <p><img alt="Сетка сварная" loading="lazy" src="assets/img/products/v9__77d5abbf7b264ce4650e2306.jpg"/>Торговая компания монополия предлагает поставку <strong>сетки сварной </strong>ВР1 и из арматуры кл. А3. <em>Сварная сетка </em>используется в промышленном строительстве для армирования железобетонных конструкций, кирпичной кладки, а так же при закладке фундаментов. Сетка сварная обеспечивает прочность возводимой конструкции. Так же сетка сварная применяется в индивидуальном строительстве, из нее сооружают теплицы и ограждения. Сварная сетка дополнительно может быть покрыта защитным цветным покрытием, что обеспечивает красивый внешний вид и повышает антикоррозийную устойчивость. </p><p>Сетка сварная для армирования продается картами, сетка сварная оцинкованная и с полимерным покрытием - в рулонах. </p><h2>Сетка сварная цена </h2><table><tbody><tr><td colspan="2"><p><strong>Сетка сварная ВР, А3 </strong></p></td><td></td><td rowspan="28"><p><strong>отправить заявку </strong></p></td></tr><tr><td><p><strong>Наименование </strong></p></td><td><p><strong>ГОСТ </strong></p></td><td><p><strong>Цена, кв.м. </strong></p></td></tr><tr><td><p><strong>3Вр1 50х50 </strong></p></td><td><p>ГОСТ 23279-85 </p></td><td></td></tr><tr><td><p><strong>5Вр1 50х50 </strong></p></td><td><p>ГОСТ 23279-85 </p></td><td></td></tr><tr><td><p><strong>3Вр1 100х100 </strong></p></td><td><p>ГОСТ 23279-85 </p></td><td></td></tr><tr><td><p><strong>5Вр1 100х100 </strong></p></td><td><p>ГОСТ 23279-85 </p></td><td></td></tr><tr><td><p><strong>3Вр1 150х150 </strong></p></td><td><p>ГОСТ 23279-85 </p></td><td></td></tr><tr><td><p><strong>5Вр1 150х150 </strong></p></td><td><p>ГОСТ 23279-85 </p></td><td></td></tr><tr><td><p><strong>4Вр1 50х50 </strong></p></td><td><p>ГОСТ 23279-85 </p></td><td></td></tr><tr><td><p><strong>5Вр1 200х200 </strong></p></td><td><p>ГОСТ 23279-85 </p></td><td></td></tr><tr><td><p><strong>4Вр1 100х100 </strong></p></td><td><p>ГОСТ 23279-85 </p></td><td></td></tr><tr><td><p><strong>6Вр1 100х100 </strong></p></td><td><p>ГОСТ 23279-85 </p></td><td></td></tr><tr><td><p><strong>4Вр1 150х150 </strong></p></td><td><p>ГОСТ 23279-85 </p></td><td></td></tr><tr><td><p><strong>6Вр1 200х200 </strong></p></td><td><p>ГОСТ 23279-85 </p></td><td></td></tr><tr><td><p><strong>4 Вр1 200х200 </strong></p></td><td><p>ГОСТ 23279-85 </p></td><td></td></tr><tr><td><p><strong>А3 50х 50х10 </strong></p></td><td><p>ГОСТ 23279-85 </p></td><td></td></tr><tr><td><p><strong>А3100х100х 6 </strong></p></td><td><p>ГОСТ 23279-85 </p></td><td></td></tr><tr><td><p><strong>А3 100х100х 8 </strong></p></td><td><p>ГОСТ 23279-85 </p></td><td></td></tr><tr><td><p><strong>А3 100х100х10 </strong></p></td><td><p>ГОСТ 23279-85 </p></td><td></td></tr><tr><td><p><strong>А3 100х100х12 </strong></p></td><td><p>ГОСТ 23279-85 </p></td><td></td></tr><tr><td><p><strong>А3 150х150х 6 </strong></p></td><td><p>ГОСТ 23279-85 </p></td><td></td></tr><tr><td><p><strong>А3 150х150х 8 </strong></p></td><td><p>ГОСТ 23279-85 </p></td><td></td></tr><tr><td><p><strong>А3 150х150х10 </strong></p></td><td><p>ГОСТ 23279-85 </p></td><td></td></tr><tr><td><p><strong>А3 150х150х12 </strong></p></td><td><p>ГОСТ 23279-85 </p></td><td></td></tr><tr><td><p><strong>А3 200х200х 6 </strong></p></td><td><p>ГОСТ 23279-85 </p></td><td></td></tr><tr><td><p><strong>А3 200х200х 8 </strong></p></td><td><p>ГОСТ 2