INSERT INTO `products` (`id`,`category_id`,`root_category`,`name`,`slug`,`sku`,`short_description`,`description_html`,`image`,`unit`,`price`,`request_hint`,`active`,`featured`,`sort_order`,`seo_title`,`seo_description`,`source_file`,`specs_json`,`gallery_json`,`old_urls_json`) VALUES (900,25,'metal','Шпунт Ларсена','metal-shpunt-larsena','MNP-0900','Шпунт Ларсена – является видом металлического профиля, представляющего из себя желоб, края которого закруглены в виде замков. Благодаря замкам отдельные шпунты могут соединяться между собой и достигать длины 34 метра. Основная форма шпунта.','<div>Шпунт Ларсена <p><strong><img alt="Шпунт Ларсена" loading="lazy" src="assets/img/products/v20__d0e948807c66d4af621a472b.jpg"/>Шпунт Ларсена </strong>– является видом металлического профиля, представляющего из себя желоб, края которого закруглены в виде замков. Благодаря замкам отдельные шпунты могут соединяться между собой и достигать длины 34 метра. Основная форма шпунта корытообразная, такая форма создает особую прочность на сгибание, так же изготавливается <em>шпунт Ларсена </em>в форме Z , L , S , плоский. Шпунт Ларсена так же может быть изготовлен особой длины и не иметь замков. Самыми же популярными и наиболее часто продаваемыми являются разновидности Л5 и Л4. </p><p>Шпунт Ларсена может быть изготовлен из различных, требуемых материалов – углеродистая сталь, сталь легированная медью, чаще применяется сталь марок 235,240,270 и другие. </p><h2>Шпунт Ларсена </h2><p><img alt="Л5 Профиль" loading="lazy" src="assets/img/products/v20.1__713dbbda82f77dcf37b4b9c0.png"/></p><p>Шпунт Ларсена Л5 (профиль) </p><p><img alt="Л5 замок" loading="lazy" src="assets/img/products/v20.2__161e14b2de7f0f5e065c0b9f.png"/></p><p>Шпунт Ларсена Л5 (замок) </p><p><img alt="Л4 профиль" loading="lazy" src="assets/img/products/v20.4__61da3f3544723e78ffd14556.jpg"/></p><p>Шпунт Ларсена Л4 (профиль) </p><p><img alt="Схема и конструкция продукции" loading="lazy" src="assets/img/products/v20.3__c8ac6aee735fe117719decc6.png"/></p><p>Шпунт Ларсена Л4 (замок) </p><p>Шпунт Ларсена выпускается мерной и немерной длины. Мерная длина шпунта Ларсена от 12-24 метров, а немерной длины от 5-24 метров. </p><h2>Шпунт Ларсена прайс </h2><table><tbody><tr><td colspan="2"><p><strong>Шпунт </strong></p></td><td></td><td rowspan="4"><p><strong>отправить заявку </strong></p></td></tr><tr><td><p><strong>Наименование </strong></p></td><td><p><strong>Производитель </strong></p></td><td><p><strong>Цена, тн. </strong></p></td></tr><tr><td><p><strong>Шпунт Ласерна Л4 </strong></p></td><td><p>Россия </p></td><td></td></tr><tr><td><p><strong>Шпунт Ласерна Л5 </strong></p></td><td><p>Россия </p></td><td></td></tr></tbody></table><p>В раздел «Шпунт» </p><p>На главную страницу сайта </p></div>','assets/img/products/v20__d0e948807c66d4af621a472b.jpg','т',NULL,'Укажите размеры, марку стали, требуемый стандарт, количество или массу и условия поставки.',1,0,900,'Шпунт Ларсена — купить по заявке | Монополия','Шпунт Ларсена: подбор и поставка в Санкт-Петербурге. Укажите размеры, марку стали, требуемый стандарт, количество или массу и условия поставки. Расчет стоимости — по заявке.','site/www.monopoly-torg.ru/shpunt-larsena__8c2d83d6e5ff8358bf4e567c.html','[]','["assets/img/products/v20__d0e948807c66d4af621a472b.jpg", "assets/img/products/v20.1__713dbbda82f77dcf37b4b9c0.png", "assets/img/products/v20.2__161e14b2de7f0f5e065c0b9f.png", "assets/img/products/v20.4__61da3f3544723e78ffd14556.jpg", "assets/img/products/v20.3__c8ac6aee735fe117719decc6.png"]','["http://www.monopoly-torg.ru/index.php/metalloprocat/shpunt/shpunt-larsena"]') ON DUPLICATE KEY UPDATE `category_id`=VALUES(`category_id`),`root_category`=VALUES(`root_category`),`name`=VALUES(`name`),`slug`=VALUES(`slug`),`sku`=VALUES(`sku`),`short_description`=VALUES(`short_description`),`description_html`=VALUES(`description_html`),`image`=VALUES(`image`),`unit`=VALUES(`unit`),`price`=VALUES(`price`),`request_hint`=VALUES(`request_hint`),`active`=VALUES(`active`),`featured`=VALUES(`featured`),`sort_order`=VALUES(`sort_order`),`seo_title`=VALUES(`seo_title`),`seo_description`=VALUES(`seo_description`),`source_file`=VALUES(`source_file`),`specs_json`=VALUES(`specs_json`),`gallery_json`=VALUES(`gallery_json`),`old_urls_json`=VALUES(`old_urls_json`);
