INSERT INTO `products` (`id`,`category_id`,`root_category`,`name`,`slug`,`sku`,`short_description`,`description_html`,`image`,`unit`,`price`,`request_hint`,`active`,`featured`,`sort_order`,`seo_title`,`seo_description`,`source_file`,`specs_json`,`gallery_json`,`old_urls_json`) VALUES (907,26,'metal','Труба профильная квадратная, прямоугольная','metal-truba-profilnaya-kvadratnaya','MNP-0907','Труба профильная квадратная , прямоугольная изготавливается путем прокатки профильной трубы и придания ей различного, квадратного или прямоугольного сечения, иногда сечение выполняется овальным.','<div>Труба профильная квадратная, прямоугольная <p><strong><img alt="Труба профильная квадратная, прямоугольная" loading="lazy" src="assets/img/products/v16__eb58d6c2eea916a098246ac6.jpg"/>Труба профильная квадратная </strong>, прямоугольная изготавливается путем прокатки профильной трубы и придания ей различного, квадратного или прямоугольного сечения, иногда сечение выполняется овальным. </p><p>К главным преимуществам <em>труб профильных квадратных или прямоугольных </em>можно отнести: экономия затрат, хорошая переносимость к различным механическим и вибрационным нагрузкам, удобство монтажа. </p><p>Труба профильная квадратная, прямоугольная применяются для конструкций различного назначения - в производстве металлоконструкций, для производства каркасных систем, а так же в качестве опор, перекрытий. Так же труба профильная применяется в машиностроении и производстве конструкций мебели и интерьера. </p><p>Труба профильная квадратная, прямоугольная по виду производства подразделяется – горячедеформированные, холоднодеформированные, электросварные, электросварные холоднодеформированные. </p><h2>Труба профильная квадратная, прямоугольная цена </h2><table><tbody><tr><td colspan="3"><p><strong>Труба профильная квадратная, прямоугольная </strong></p></td><td><p><strong>отправить заявку </strong></p></td></tr><tr><td><p><strong>Наименование </strong></p></td><td><p><strong>ГОСТ </strong></p></