INSERT INTO `products` (`id`,`category_id`,`root_category`,`name`,`slug`,`sku`,`short_description`,`description_html`,`image`,`unit`,`price`,`request_hint`,`active`,`featured`,`sort_order`,`seo_title`,`seo_description`,`source_file`,`specs_json`,`gallery_json`,`old_urls_json`) VALUES (909,26,'metal','Труба тонкостенная','metal-truba-tonkostennaya','MNP-0909','Труба тонкостенная – это пластичная труба, соединяющаяся сваркой. Труба тонкостенные имеют гладкую и ровную поверхность, окрашиваемую декоративными и защитными покрытиями.','<div>Труба тонкостенная <p><strong><img alt="Труба тонкостенная" loading="lazy" src="assets/img/products/v11__330b73666d7c0877de047c18.jpg"/>Труба тонкостенная </strong>– это пластичная труба, соединяющаяся сваркой. <em>Труба тонкостенные </em>имеют гладкую и ровную поверхность, окрашиваемую декоративными и защитными покрытиями. </p><p>Труба тонкостенная стальная применяется в строительстве для прокладки трубопроводов, кабельных сетей, служат защитой от механических повреждений. </p><p>Не смотря на тонкую стенку, стальные тонкостенные трубы имеют высокие визикомеханические характеристики, что значительно снижает стоимость материала при прокладке инженерии. </p><h2>Труба тонкостенная стоимость </h2><table><tbody><tr><td colspan="2"><p><strong>Труба тонкостенная </strong></p></td><td></td><td rowspan="29"><p><strong>отправить заявку </strong></p></td></tr><tr><td><p><strong>Наименование </strong></p></td><td><p><strong>ГОСТ </strong></p></td><td><p><strong>Цена, тн. </strong></p></td></tr><tr><td><p><strong>Труба Ф16х1,2 </strong></p></td><td><p>ГОСТ 10704-91 </p></td><td></td></tr><tr><td><p><strong>Труба Ф16х1,5 </strong></p></td><td><p>ГОСТ 10704-91 </p></td><td></td></tr><tr><td><p><strong>Труба Ф18х1,0 </strong></p></td><td><p>ГОСТ 10704-91 </p></td><td></td></tr><tr><td><p><strong>Труба Ф18х1,5 </strong></p></td><td><p>ГОСТ 10704-91 </p></td><td></td></tr><tr><td><p><strong>Труба Ф20х1,2 </strong></p></td><td><p>ГОСТ 10704-91 </p></td><