INSERT INTO `products` (`id`,`category_id`,`root_category`,`name`,`slug`,`sku`,`short_description`,`description_html`,`image`,`unit`,`price`,`request_hint`,`active`,`featured`,`sort_order`,`seo_title`,`seo_description`,`source_file`,`specs_json`,`gallery_json`,`old_urls_json`) VALUES (910,26,'metal','Труба водо-газопроводная оцинкованная','metal-truba-vodogazop-otsink','MNP-0910','Труба водо-газопроводная оцинкованная производится из черной трубы водо-газопроводной с дальнейшим нанесением на нее тонкого слоя цинка, который обеспечивает надежную защиту от коррозии. Нанесение защитного слоя происходит методом горячего.','<div>Труба водо-газопроводная оцинкованная <p><strong><img alt="Труба водогазопроводная оцинкованная" loading="lazy" src="assets/img/products/v13__98229218128310f3e206c426.jpg"/>Труба водо-газопроводная оцинкованная </strong>производится из черной трубы водо-газопроводной с дальнейшим нанесением на нее тонкого слоя цинка, который обеспечивает надежную защиту от коррозии. Нанесение защитного слоя происходит методом горячего цинкования, так же используют специальные смеси, содержащие цинк. </p><p><em>Труба водо-газопроводная оцинкованная </em>производится согласно ГОСТ 10704-91 </p><h2>Труба водо-газопроводная оцинкованная Типоразмеры и исполнения </h2><table><tbody><tr><td colspan="2"><p><strong>Труба водогазопроводная оцинкованная </strong></p></td><td></td><td rowspan="8"><p><strong>отправить заявку </strong></p></td></tr><tr><td><p><strong>Наименование </strong></p></td><td><p><strong>ГОСТ </strong></p></td><td><p><strong>Цена, тн. </strong></p></td></tr><tr><td><p><strong>Труба ВГП оц. d=15х2.8мм </strong></p></td><td><p>ГОСТ 10704-91 </p></td><td></td></tr><tr><td><p><strong>Труба ВГП оц. d=20х2.8мм </strong></p></td><td><p>ГОСТ 10704-91 </p></td><td></td></tr><tr><td><p><strong>Труба ВГП оц. d=25х3.2мм </strong></p></td><td><p>ГОСТ 10704-91 </p></td><td></td></tr><tr><td><p><strong>Труба ВГП оц. d=32х3.2мм </strong></p></td><td><p>ГОСТ 10704-91 </p></td><td></td></tr><tr><td><p><strong>Труба ВГП оц. d=40х3.5мм </strong></p></td><td><p>ГОСТ 10704-91 </p></td><td></td></tr><tr><td><p><strong>Труба ВГП оц. d=50х3.5мм </strong></p></td><td><p>ГОСТ 10704-91 </p></td><td></td></tr></tbody></table><p>В раздел "Трубная продукция" </p><p>На главную страницу сайта </p></div>','assets/img/products/v13__98229218128310f3e206c426.jpg','т',NULL,'Укажите размеры, марку стали, требуемый стандарт, количество или массу и условия поставки.',1,0,910,'Труба водо-газопроводная оцинкованная — купить по заявке | Монополия','Труба водо-газопроводная оцинкованная: подбор и поставка в Санкт-Петербурге. Укажите размеры, марку стали, требуемый стандарт, количество или массу и условия поставки. Расчет стоимости — по заявке.','site/www.monopoly-torg.ru/truba-vodogazop-otsink__a2e2487994ae4fcd32753160.html','[]','["assets/img/products/v13__98229218128310f3e206c426.jpg"]','["http://www.monopoly-torg.ru/index.php/metalloprocat/trubnaya-produktsiya/truba-vodogazop-otsink"]') ON DUPLICATE KEY UPDATE `category_id`=VALUES(`category_id`),`root_category`=VALUES(`root_category`),`name`=VALUES(`name`),`slug`=VALUES(`slug`),`sku`=VALUES(`sku`),`short_description`=VALUES(`short_description`),`description_html`=VALUES(`description_html`),`image`=VALUES(`image`),`unit`=VALUES(`unit`),`price`=VALUES(`price`),`request_hint`=VALUES(`request_hint`),`active`=VALUES(`active`),`featured`=VALUES(`featured`),`sort_order`=VALUES(`sort_order`),`seo_title`=VALUES(`seo_title`),`seo_description`=VALUES(`seo_description`),`source_file`=VALUES(`source_file`),`specs_json`=VALUES(`specs_json`),`gallery_json`=VALUES(`gallery_json`),`old_urls_json`=VALUES(`old_urls_json`);
INSERT INTO `products` (`id`,`category_id`,`root_category`,`name`,`slug`,`sku`,`short_description`,`description_html`,`image`,`unit`,`price`,`request_hint`,`active`,`featured`,`sort_order`,`seo_title`,`seo_description`,`source_file`,`specs_json`,`gallery_json`,`old_urls_json`) VALUES (911,26,'metal','Труба водо-газопроводная','metal-truba-vodogazoprovodnaya','MNP-0911','Труба водо-газопроводная – электросварная труба круглого профиля, имеющая продольный шов. Трубу водо-газопроводную изготавливают из листовой стали с помощью сварки. Сырье для производства данных изделий производится методом горячей прокатки из.','<div>Труба водо-газопроводная <p><strong><img alt="Труба водогазопроводная" loading="lazy" src="assets/img/products/v12__6e096e48faaf42fb3310f096.jpg"/>Труба водо-газопроводная </strong>– электросварная труба круглого профиля, имеющая продольный шов. <em>Трубу водо-газопроводную </em>изготавливают из листовой стали с помощью сварки. Сырье для производства данных изделий производится методом горячей прокатки из углеродистой стали. </p><p>Труба водо-газопроводная благодаря своей низкой стоимости и широкому применению имеет большую значимость в строительстве – для прокладки различных трубопроводов, так же используется при проводке газа и воды. Так же трубу используют для производства различных металлоконструкций. </p><p>Труба водо-газопроводная изготавливают согласно ГОСТ 3262-75, в котором указан неизменный размер наружного диаметра. Труба водо-газопроводная различаются по толщине стенки – тонкостенные и толстостенные. </p><p>Стоимость трубы водо-газопроводной будет зависеть от толщины стенки, а соответственно ее веса, чем она легде, тем стоимость на изделие будет дешевле. </p><h2>Труба водо-газопроводная стоимость </h2><table><tbody><tr><td colspan="2"><p><strong>Труба водогазопроводная </strong></p></td><td></td><td rowspan="8"><p><strong>отправить заявку </strong></p></td></tr><tr><td><p><strong>Наименование </strong></p></td><td><p><strong>ГОСТ </strong></p></td><td><p><strong>Цена, тн. </strong></p></td></tr><tr><td><p><strong>Труба ВГП ду 15 х2,8 </strong></p></td><td><p>ГОСТ 3262-75 </p></td><td></td></tr><tr><td><p><strong>Труба ВГП ду 20 х2,8 </strong></p></td><td><p>ГОСТ 3262-75 </p></td><td></td></tr><tr><td><p><strong>Труба ВГП ду 25 х3,2 </strong></p></td><td><p>ГОСТ 3262-75 </p></td><td></td></tr><tr><td><p><strong>Труба ВГП ду 32 х3,2 </strong></p></td><td><p>ГОСТ 3262-75 </p></td><td></td></tr><tr><td><p><strong>Труба ВГП ду 40 х3,5 </strong></p></td><td><p>ГОСТ 3262-75 </p></td><td></td></tr><tr><td><p><strong>Труба ВГП ду 50 х3,5 </strong></p></td><td><p>ГОСТ 3262-75 </p></td><td></td></tr></tbody></table><p>В раздел "Трубная продукция" </p><p>На главную страницу сайта </p></div>','assets/img/products/v12__6e096e48faaf42fb3310f096.jpg','т',NULL,'Укажите размеры, марку стали, требуемый стандарт, количество или массу и условия поставки.',1,0,911,'Труба водо-газопроводная — купить по заявке | Монополия','Труба водо-газопроводная: подбор и поставка в Санкт-Петербурге. Укажите размеры, марку стали, требуемый стандарт, количество или массу и условия поставки. Расчет стоимости — по заявке.','site/www.monopoly-torg.ru/truba-vodogazoprovodnaya__f5ce623929b0367d0f557a81.html','[]','["assets/img/products/v12__6e096e48faaf42fb3310f096.jpg"]','["http://www.monopoly-torg.ru/index.php/metalloprocat/trubnaya-produktsiya/truba-vodogazoprovodnaya"]') ON DUPLICATE KEY UPDATE `category_id`=VALUES(`category_id`),`root_category`=VALUES(`root_category`),`name`=VALUES(`name`),`slug`=VALUES(`slug`),`sku`=VALUES(`sku`),`short_description`=VALUES(`short_description`),`description_html`=VALUES(`description_html`),`image`=VALUES(`image`),`unit`=VALUES(`unit`),`price`=VALUES(`price`),`request_hint`=VALUES(`request_hint`),`active`=VALUES(`active`),`featured`=VALUES(`featured`),`sort_order`=VALUES(`sort_order`),`seo_title`=VALUES(`seo_title`),`seo_description`=VALUES(`seo_description`),`source_file`=VALUES(`source_file`),`specs_json`=