INSERT INTO `products` (`id`,`category_id`,`root_category`,`name`,`slug`,`sku`,`short_description`,`description_html`,`image`,`unit`,`price`,`request_hint`,`active`,`featured`,`sort_order`,`seo_title`,`seo_description`,`source_file`,`specs_json`,`gallery_json`,`old_urls_json`) VALUES (920,3,'profile','Профилированный лист Н-114х600','profile-n114kh600','MNP-0920','Профилированный лист H-114x600 -A,B отличает большая высота профиля (114 мм) при небольшом шаге (60 мм) и ширине (104 мм), а также канавки и рельеф ребра, которые придают конструкции жесткость. Такая геометрия, вкупе с толщиной оцинкованного.','<div>Профилированный лист Н-114х600 <p><strong>Профилированный лист H-114x600 </strong>-A,B отличает большая высота профиля (114 мм) при небольшом шаге (60 мм) и ширине (104 мм), а также канавки и рельеф ребра, которые придают конструкции жесткость. Такая геометрия, вкупе с толщиной оцинкованного стального листа 0,7 – 1,2 мм и надежным полимерным покрытием, позволяют использовать материал там, где раньше его невозможно было представить. С его помощью многие задачи в строительстве решаются гораздо проще и быстрее, что в совокупности позволяет снизить затраты при неизменно высоком уровне конечного результата. </p><p>На данный момент сфера использования <em>профилированного листа Н114x600 </em>включает организацию скатной и плоской кровли, несущих конструкций, не снимаемой опалубки и многие другие области применения, где это целесообразно. </p><p><img alt="Профнастил H114x600" loading="lazy" src="assets/img/products/p_3_1__786ac0fab0808c405efaa90b.jpg"/></p><p>Кроме стандартных размеров листа, возможно индивидуальное исполнение, согласно требованиям заказчика (длиной от 0,5 до 12 метров). Для обеспечения защиты при транспортировке на профнастил наносится пленка, которая легко удаляется. Комплектация включает все необходимое для профессионального монтажа. </p><div><p>Область применения <strong>профилированного листа Н-114x600-A,B </strong></p><ul><li>несущие конструкции, </li><li>потолки, </li><li>не снимаемая опалубка, </li><li>скатные и плоские кровли. </li></ul><p><img alt="Схема и конструкция продукции" loading="lazy" src="assets/img/products/p_3_2_1__da96d6ead10c0b54bd8d0e07.jpg"/></p><p><img alt="Схема и конструкция продукции" loading="lazy" src="assets/img/products/p_3_2_2__960300f67a585f4757ecca3a.jpg"/></p><table><tbody><tr><td></td></tr></tbody></table><table><tbody><tr><td><p>Тип </p></td><td><p>Высота профиля, мм </p></td><td><p>Ширина полная, мм </p></td><td><p>Ширина рабочая, мм </p></td><td><p>Ширина заготовки, мм </p></td><td><p>Толщина листа, мм </p></td><td><p>Масса 1м длины, кг </p></td><td><p>Масса 1м <sup>2 </sup>полной ширины, кг </p></td></tr><tr><td rowspan="5"><p>Н-114х600-А </p><p>Н-114х600-В </p></td><td rowspan="5"><p>114 </p></td><td rowspan="5"><p>646 </p></td><td rowspan="5"><p>600 </p></td><td rowspan="5"><p>1250 </p></td><td><p>0,7 </p></td><td><p>7,4 </p></td><td><p>11,38 </p></td></tr><tr><td><p>0,8 </p></td><td><p>8,4 </p></td><td><p>13,0 </p></td></tr><tr><td><p>0,9 </p></td><td><p>9,3 </p></td><td><p>14,4 </p></td></tr><tr><td><p>1,0 </p></td><td><p>10,3 </p></td><td><p>15,94 </p></td></tr><tr><td><p>1,2 </p></td><td><p>12,3 </p></td><td><p>19,0 </p></td></tr></tbody></table></div></div>','assets/img/products/p_3_1__786ac0fab0808c405efaa90b.jpg','лист',NULL,'Укажите профиль, толщину, длину и количество листов, покрытие и цвет RAL.',1,0,920,'Профилированный лист Н-114х600 — купить по заявке | Монополия','Профилированный лист Н-114х600: подбор и поставка в Санкт-Петербурге. Укажите профиль, толщину, длину и количество листов, покрытие и цвет RAL. Расчет стоимости — по заявке.','site/www.monopoly-torg.ru/n114kh600__553fba0ba4a2864fa2868b2a.html','[]','["assets/img/products/p_3_1__786ac0fab0808c405efaa90b.jpg", "assets/img/products/p_3_2_1__da96d6ead10c0b54bd8d0e07.jpg", "assets/img/products/p_3_2_2__960300f67a585f4757ecca3a.jpg"]','["http://www.monopoly-torg.ru/index.php/profnactil/n114kh600"]') 