INSERT INTO `products` (`id`,`category_id`,`root_category`,`name`,`slug`,`sku`,`short_description`,`description_html`,`image`,`unit`,`price`,`request_hint`,`active`,`featured`,`sort_order`,`seo_title`,`seo_description`,`source_file`,`specs_json`,`gallery_json`,`old_urls_json`) VALUES (921,3,'profile','Профилированный лист Н-114х750','profile-n114kh750','MNP-0921','Профилированный лист Н-114х750 имеет высокий трапецевидный профиль с небольшим шагом, ребра жесткости усилены двумя канавками и рельефам по бокам, что обеспечивает конструкции устойчивость к большим нагрузкам. Для производства используется.','<div>Профилированный лист Н-114х750 <p><strong>Профилированный лист Н-114х750 </strong>имеет высокий трапецевидный профиль с небольшим шагом, ребра жесткости усилены двумя канавками и рельефам по бокам, что обеспечивает конструкции устойчивость к большим нагрузкам. Для производства используется оцинкованный стальной лист 0,7 – 1.0 мм с полимерным покрытием или без него. </p><p><img alt="Схема и конструкция продукции" loading="lazy" src="assets/img/products/p_2_1__d1b92f0cdbb4311f93f8b9d0.jpg"/></p><p><em>Профилированный лист </em>обладает необходимыми техническими показателями для применения в различных сферах: от организации кровли до не снимаемой опалубки. Кроме того, профиль обеспечивает теплоизоляцию, устойчивость конструкции и другие эксплуатационные свойства. </p><p>Безопасность транспортировки обеспечивает нанесение на поверхность профлиста пленки, которая удаляется после монтажа. В комплектацию входят необходимые инструкции по монтажу. </p><div><p>Область применения <strong>профилированного листа Н-114х750 </strong></p><ul><li>несущие конструкции, </li><li>потолки, </li><li>не снимаемая опалубка , </li><li>скатные и плоские кровли . </li></ul></div><div><img alt="Схема и конструкция продукции" loading="lazy" src="assets/img/products/p_2_2_1__ab766c7fb99f6aec715dc713.jpg"/></div><div><img alt="Схема и конструкция продукции" loading="lazy" src="assets/img/products/p_2_2_2__ca765d6b62695ecaeed48476.jpg"/></div><div><table><tbody><tr><td><p>Тип </p></td><td><p>Высота профиля, мм </p></td><td><p>Ширина полная, мм </p></td><td><p>Ширина рабочая, мм </p></td><td><p>Ширина заготовки, мм </p></td><td><p>Толщина листа, мм </p></td><td><p>Масса 1м длины, кг </p></td><td><p>Масса 1м <sup>2 </sup>полной ширины, кг </p></td></tr><tr><td rowspan="4"><p>Н-114х750-А </p><p>Н-114х750-В </p></td><td rowspan="4"><p>114 </p></td><td rowspan="4"><p>807 </p></td><td rowspan="4"><p>750 </p></td><td rowspan="4"><p>1400 </p></td><td><p>0,7 </p></td><td><p>8,2 </p></td><td><p>10,2 </p></td></tr><tr><td><p>0,8 </p></td><td><p>9,4 </p></td><td><p>11,7 </p></td></tr><tr><td><p>0,9 </p></td><td><p>10,5 </p></td><td><p>13,0 </p></td></tr><tr><td><p>1,0 </p></td><td><p>11,7 </p></td><td><p>14,5 </p></td></tr></tbody></table></div></div>','assets/img/products/p_2_1__d1b92f0cdbb4311f93f8b9d0.jpg','лист',NULL,'Укажите профиль, толщину, длину и количество листов, покрытие и цвет RAL.',1,0,921,'Профилированный лист Н-114х750 — купить по заявке | Монополия','Профилированный лист Н-114х750: подбор и поставка в Санкт-Петербурге. Укажите профиль, толщину, длину и количество листов, покрытие и цвет RAL. Расчет стоимости — по заявке.','site/www.monopoly-torg.ru/n114kh750__98f01cde2a7a05694f005ca4.html','[]','["assets/img/products/p_2_1__d1b92f0cdbb4311f93f8b9d0.jpg", "assets/img/products/p_2_2_1__ab766c7fb99f6aec715dc713.jpg", "assets/img/products/p_2_2_2__ca765d6b62695ecaeed48476.jpg"]','["http://www.monopoly-torg.ru/index.php/profnactil/n114kh750"]') ON DUPLICATE KEY UPDATE `category_id`=VALUES(`category_id`),`root_category`=VALUES(`root_category`),`name`=VALUES(`name`),`slug`=VALUES(`slug`),`sku`=VALUES(`sku`),`short_description`=VALUES(`short_description`),`description_html`=VALUES(`description_html`),`image`=VALUES(`image`),`unit`=VALUES(`unit`),`price`=VALUES(`price`),`request_hint`=VALUES(`request_hint`),`active`=VALUES(`active`),`featured`=VALUES(`featured