INSERT INTO `products` (`id`,`category_id`,`root_category`,`name`,`slug`,`sku`,`short_description`,`description_html`,`image`,`unit`,`price`,`request_hint`,`active`,`featured`,`sort_order`,`seo_title`,`seo_description`,`source_file`,`specs_json`,`gallery_json`,`old_urls_json`) VALUES (922,3,'profile','Профилированный лист Н60х845','profile-n60kh845','MNP-0922','Профилированный лист H-60x845 -A,B предназначен для организации несущих конструкций и устройства скатных кровель. Материал выполнен из холоднокатаной оцинкованной стали, толщиной 0,5-0,9 мм и имеет трапецевидную форму профиля. При достаточно.','<div>Профилированный лист Н60х845 <p><strong>Профилированный лист H-60x845 </strong>-A,B предназначен для организации несущих конструкций и устройства скатных кровель. Материал выполнен из холоднокатаной оцинкованной стали, толщиной 0,5-0,9 мм и имеет трапецевидную форму профиля. При достаточно большой ширине ребра (122 мм), расстояние шага составляет всего 50 мм, усиление конструкции и повышенную стойкость к изгибу обеспечивают дополнительные канавки. Подробные характеристики нагрузок на материал указаны в технической документации. </p><p><img alt="Профнастил H60x845" loading="lazy" src="assets/img/products/p_14_1__e91c49177bad8e0de38aba3a.jpg"/></p><div><p>Области применения профилированного листа H-60x845 -A,B: </p><ul><li>несущие конструкции </li><li>скатные кровли. </li></ul></div></div>','assets/img/products/p_14_1__e91c49177bad8e0de38aba3a.jpg','лист',NULL,'Укажите профиль, толщину, длину и количество листов, покрытие и цвет RAL.',1,0,922,'Профилированный лист Н60х845 — купить по заявке | Монополия','Профилированный лист Н60х845: подбор и поставка в Санкт-Петербурге. Укажите профиль, толщину, длину и количество листов, покрытие и цвет RAL. Расчет стоимости — по заявке.','site/www.monopoly-torg.ru/n60kh845__1d631122e37d9e2a82fb92c0.html','[]','["assets/img/products/p_14_1__e91c49177bad8e0de38aba3a.jpg"]','["http://www.monopoly-torg.ru/index.php/profnactil/n60kh84