INSERT INTO `products` (`id`,`category_id`,`root_category`,`name`,`slug`,`sku`,`short_description`,`description_html`,`image`,`unit`,`price`,`request_hint`,`active`,`featured`,`sort_order`,`seo_title`,`seo_description`,`source_file`,`specs_json`,`gallery_json`,`old_urls_json`) VALUES (923,3,'profile','Профилированный лист Н-75х750','profile-n75kh750','MNP-0923','Профилированный лист H-75x750 -A,B имеет трапецевидную форму с высотой ребра 75 мм и шириной 92 мм, шаг составляет 50 мм. К особенностям геометрии данного профиля можно отнести наличие дополнительных канавок на каждом ребре, а также рельефной.','<div>Профилированный лист Н-75х750 <p><strong>Профилированный лист H-75x750 </strong>-A,B имеет трапецевидную форму с высотой ребра 75 мм и шириной 92 мм, шаг составляет 50 мм. К особенностям геометрии данного профиля можно отнести наличие дополнительных канавок на каждом ребре, а также рельефной поверхности ребер, что в целом позволяет значительно усилить устойчивость материала к изгибу при значительных нагрузках. Это подтверждают испытания и тесты, с результатами которых можно ознакомиться в технической документации к материалу. </p><p>Данные свойства позволяют использовать <em>профилированный лист Н-75x750 </em>для организации несущих конструкций, не снимаемой опалубки, скатной и плоской кровли, перекрытий и в других целях. </p><p><img alt="профнастил H75x750" loading="lazy" src="assets/img/products/p_4_1__d534bba9b3f876c99d012ff4.jpg"/></p><p>Защитно-декоративные функции обеспечивает полимерное покрытие, которое наносится на лицевую сторону профнастила по типу А, или по типу В (по желанию клиента). На выбор предлагается широкая цветовая палитра, что позволяет использовать материал для решения различных архитектурных задач. </p><p>Профилированный лист Н-75 поставляется стандартных размеров 2.0, 3.0 и 6.0 метров, или может быть изготовлен под заказ, длиной от 0,5 до 12 м. Также по желанию заказчика возможно нанесение антиконденсатного покрытия, если профилированный лист H-75x750 используется в качестве кровельного материала. </p><div><p>Область применения профилированного листа Н75x750 : </p><ul><li>несущие конструкции, </li><li>потолки, </li><li>не снимаемая опалубка, </li><li>скатные и плоские кровли, </li><li>перекрытия. </li></ul></div><p><img alt="Схема и конструкция продукции" loading="lazy" src="assets/img/products/p_4_2_1__c4668b7b14edd30ac1494773.jpg"/></p><p><img alt="Схема и конструкция продукции" loading="lazy" src="assets/img/products/p_4_2_2__f997d373c01bfd439d76cda6.jpg"/></p><table><tbody><tr><td><p>Тип </p></td><td><p>Высота профиля, мм </p></td><td><p>Ширина полная, мм </p></td><td><p>Ширина рабочая, мм </p></td><td><p>Ширина заготовки, мм </p></td><td><p>Толщина листа, мм </p></td><td><p>Масса 1м длины, кг </p></td><td><p>Масса 1м <sup>2 </sup>полной ширины, кг </p></td></tr><tr><td rowspan="4"><p>Н-75х750-А </p><p>Н-75х750-В </p></td><td rowspan="4"><p>75 </p></td><td rowspan="4"><p>800 </p></td><td rowspan="4"><p>750 </p></td><td rowspan="4"><p>1250 </p></td><td><p>0,7 </p></td><td><p>7,4 </p></td><td><p>9,25 </p></td></tr><tr><td><p>0,8 </p></td><td><p>8,4 </p></td><td><p>10,5 </p></td></tr><tr><td><p>0,9 </p></td><td><p>9,3 </p></td><td><p>11,63 </p></td></tr><tr><td><p>1,0 </p></td><td><p>10,3 </p></td><td><p>12,9 </p></td></tr></tbody></table></div>','assets/img/products/p_4_1__d534bba9b3f876c99d012ff4.jpg','лист',NULL,'Укажите профиль, толщину, длину и количество листов, покрытие и цвет RAL.',1,0,923,'Профилированный лист Н-75х750 — купить по заявке | Монополия','Профилированный лист Н-75х750: подбор и поставка в Санкт-Петербурге. Укажите профиль, толщину, длину и количество листов, покрытие и цвет RAL. Расчет стоимости — по заявке.','site/www.monopoly-torg.ru/n75kh750__da2e234ad9307ea7dfbf7d56.html','[]','["assets/img/products/p_4_1__d534bba9b3f876c99d012ff4.jpg", "assets/img/products/p_4_2_1__c4668b7b14edd30ac1494773.jpg", "assets/img/products/p_4_2_2__f997d373c01bfd439d76cda6.jpg"]','["http://www.monopoly-torg.ru/index.php/profnactil/n75kh750"]') ON DUPLICATE KEY UPDATE `category_id`=VALUES(`category_id`),`root_category`=VALUES(`root_category`),`name`=VALUES(`name`),`slug`=VALUES(`slug`),`sku`=VALUES(`sku`),`short_description`=VALUES(`short_description`),`description_html`=VALUES(`description_html`),`image`=VALUES(`image`),`unit`=VALUES(`unit`),`price`=VALUES(`price`),`request_hint`=VALUES(`request_hint`),`active`=VALUES(`active`),`featured`=VALUES(`featured`),`sort_order`=VALUES(`sort_order`),`seo_title`=VALUES(`seo_title`),`seo_description`=VALUES(`seo_description`),`source_file`=VALUES(`source_file`),`specs_json`=VALUES(`specs_json`),`gallery_json`=VALUES(`gallery_json`),`old_urls_json`=VALUES(`old_urls_json`);
INSERT INTO `products` (`id`,`category_id`,`root_category`,`name`,`slug`,`sku`,`short_description`,`description_html`,`image`,`unit`,`price`,`request_hint`,`active`,`featured`,`sort_order`,`seo_title`,`seo_description`,`source_file`,`specs_json`,`gallery_json`,`old_urls_json`) VALUES (924,3,'profile','Профилированный лист НС-35х1000','profile-ns35kh1000','MNP-0924','Профилированный лист МП-35х1035 -A,B имеет трапецевидную форму с широкими ребрами жесткости (119 мм) и небольшим расстоянием между ними (40 мм), высота составляет 35 мм. Данная геометрия профиля обеспечивает повышенную устойчивость профиля к.','<div>Профилированный лист НС-35х1000 <p><strong>Профилированный лист МП-35х1035 </strong>-A,B имеет трапецевидную форму с широкими ребрами жесткости (119 мм) и небольшим расстоянием между ними (40 мм), высота составляет 35 мм. Данная геометрия профиля обеспечивает повышенную устойчивость профиля к изгибу, конкретные характеристики указаны в технической документации материала. </p><p><img alt="Профнастил Н35x1000" loading="lazy" src="assets/img/products/p_11_1__c875662836db24510eb9da3e.jpg"/>Для изготовления профнастила используется стальной лист 0,5 – 0,9 мм, что, вкупе с его формой, позволяет использовать материал для возведения несущих конструкций, а также ворот и организации скатной кровли. </p><p>Стандартная длина профилированного листа составляет 2.0, 3.0 и 6.0 м, под заказ возможно производство листа от 0,5 м до 12,0 м. В случае использование профнастила МП-35х1035 в кровельной системе рекомендуется нанесение дополнительного антиконденсатного покрытия. </p><div><p>Область применения профилированного листа <strong>НС-35х1035-A,B: </strong></p><ul><li>несущие конструкции, </li><li>скатные кровели, </li><li>ворота, ограждения. </li></ul><p><img alt="Схема и конструкция продукции" loading="lazy" src="assets/img/products/p_11_2_1__9833ec98aaec9d3061bb41f7.jpg"/></p><p><img alt="Схема и конструкция продукции" loading="lazy" src="assets/img/products/p_11_2_2__b63bc74ed8b73ab734a1ce6d.jpg"/></p><table><tbody><tr><td>Тип </td><td>Высота профиля, мм </td><td>Ширина полная, мм </td><td>Ширина рабочая, мм </td><td>Ширина заготовки, мм </td><td>Толщина листа, мм </td><td>Масса 1м длины, кг </td><td>Масса 1м <sup>2 </sup>полной ширины, кг </td></tr><tr><td rowspan="4">НС-35х1000-А НС-35х1000-В </td><td rowspan="4">35 </td><td rowspan="4">1060 </td><td rowspan="4">1000 </td><td rowspan="4">1250 </td><td>0,5 </td><td>5,4 </td><td>5,09 </td></tr><tr><td>0,55 </td><td>5,9 </td><td>5,57 </td></tr><tr><td>0,7 </td><td>7,4 </td><td>6,98 </td></tr><tr><td>0,8 </td><td>8,4 </td><td>7,93 </td></tr></tbody></table></div></div>','assets/img/products/p_11_1__c875662836db24510eb9da3e.jpg','лист',NULL,'Укажите профиль, толщину, длину и количество листов, покрытие и цвет RAL.',1,0,924,'Профилированный лист НС-35х1000 — купить по заявке | Монополия','Профилированный лист НС-35х1000: подбор и поставка в Санкт-Петербурге. Укажите профиль, толщину, длину и количество листов, покрытие и цвет RAL. Расчет стоимости — по заявке.','site/www.monopoly-torg.ru/ns35kh1000__02994f07520cd711e8c9146c.html','[]','["assets/img/products/p_11_1__c875662836db24510eb9da3e.jpg", "assets/img/products/p_11_2_1__9833ec98aaec9d3061bb41f7.jpg", "assets/img/products/p_11_2_2__b63bc74ed8b73ab734a1ce6d.jpg"]','["http://www.monopoly-torg.ru/index.php/profnactil/ns35kh1000"]') ON DUPLICATE KEY UPDATE `category_id`=VALUES(`category_id`),`root_category`=VALUES(`root_category`),`name`=VALUES(`name`),`slug`=VALUES(`slug`),`sku`=VALUES(`sku`),`short_description`=VALUES(`short_description`),`description_html`=VALUES(`description_html`),`image`=VALUES(`image`),`unit`=VALUES(`unit`),`price`=VALUES(`price`),`request_hint`=VALUES(`request_hint`),`active`=VALUES(`active`),`featured`=VALUES(`featured`),`sort_order`=VALUES(`sort_order`),`seo_title`=VALUES(`seo_title`),`seo_description`=VALUES(`seo_description`),`source_file`=VALUES(`source_file`),`specs_json`=VALUES(`specs_json`),`gallery_json`=VALUES(`gallery_json`),`old_urls_json`=VALUES(`old_urls_json`);
INSERT INTO `products` (`id`,`category_id`,`root_category`,`name`,`slug`,`sku`,`short_description`,`description_html`,`image`,`unit`,`price`,`request_hint`,`active`,`featured`,`sort_order`,`seo_title`,`seo_description`,`source_file`,`specs_json`,`gallery_json`,`old_urls_json`) VALUES (925,3,'profile','Профилированный лист С21х1000','profile-s21kh1000','MNP-0925','Профилированный лист С-21х1000-A,B отличает трапецевидный профиль с достаточно близко расположенными ребрами жесткости, что формирует высокую устойчивость и определенный внешний вид материала. Благодаря этому, сфера применения профилированного.','<div>Профилированный лист С21х1000 <p><strong>Профилированный лист С-21х1000-A,B </strong>отличает трапецевидный профиль с достаточно близко расположенными ребрами жесткости, что формирует высокую устойчивость и определенный внешний вид материала. Благодаря этому, сфера применения профилированного листа расширяется и включает организацию скатной кровли, стен, заборов и перегородок. </p><p><img alt="Профнастил С21x1000" loading="lazy" src="assets/img/products/p_8_1__16796be444d2f44d7a0417d6.jpg"/>Благодаря полимерному покрытию оцинкованный стальной прокат, используемый для изготовления профилированного листа, приобретает устойчивость к атмосферным явлениям и механическим повреждениям, надежность и долговечность. </p><p>Приобрести профнастил можно в любом, необходимом количестве, стандартные размеры составляют 2.0, 3.0 и 6.0 м, по индивидуальному заказу может быть изготовлен лист от 0,5 м до 12. 0 м в длину. При использовании профнастила С-21х1000 в качестве кровельного материала на его поверхность может быть нанесено антиконденсатное покрытие. </p><div><p>Область применения профилированного листа 21х1000 -A,B <strong>: </strong></p><ul><li>стены, </li><li>перегородки, </li><li>заборы, </li><li>скатные кровли. </li></ul><p><img alt="Схема и конструкция продукции" loading="lazy" src="assets/img/products/p_8_2_1__6717b029da30bee8f91d6e01.jpg"/></p><p><img alt="Схема и конструкция продукции" loading="lazy" src="assets/img/products/p_8_2_2__3c7b03359fb76f9209ba5549.jpg"/></p><table><tbody><tr><td><p>Тип </p></td><td><p>Высота профиля, мм </p></td><td><p>Ширина полная, мм </p></td><td><p>Ширина рабочая, мм </p></td><td><p>Ширина заготовки, мм </p></td><td><p>Толщина листа, мм </p></td><td><p>Масса 1м длины, кг </p></td><td><p>Масса 1м <sup>2 </sup>полной ширины, кг </p></td></tr><tr><td rowspan="4"><p>C21х1000-А </p><p>C21х1000-В </p></td><td rowspan="4"><p>21 </p></td><td rowspan="4"><p>1051 </p></td><td rowspan="4"><p>1000 </p></td><td rowspan="4"><p>1250 </p></td><td><p>0,4 </p></td><td><p>4,4 </p></td><td><p>4,19 </p></td></tr><tr><td><p>0,5 </p></td><td><p>5,42 </p></td><td><p>5,14 </p></td></tr><tr><td><p>0,55 </p></td><td><p>5,91 </p></td><td><p>5,61 </p></td></tr><tr><td><p>0,7 </p></td><td><p>7,4 </p></td><td><p>7,04 </p></td></tr></tbody></table></div></div>','assets/img/products/p_8_1__16796be444d2f44d7a0417d6.jpg','лист',NULL,'Укажите профиль, толщину, длину и количество листов, покрытие и цвет RAL.',1,1,925,'Профилированный лист С21х1000 — купить по заявке | Монополия','Профилированный лист С21х1000: подбор и поставка в Санкт-Петербурге. Укажите профиль, толщину, длину и количество листов, покрытие и цвет RAL. Расчет стоимости — по заявке.','site/www.monopoly-torg.ru/s21kh1000__bdc1eff210ca83e26d5cb53e.html','[]','["assets/img/products/p_8_1__16796be444d2f44d7a0417d6.jpg", "assets/img/products/p_8_2_1__6717b029da30bee8f91d6e01.jpg", "assets/img/products/p_8_2_2__3c7b03359fb76f9209ba5549.jpg"]','["http://www.monopoly-torg.ru/index.php/profnactil/s21kh1000"]') ON DUPLICATE KEY UPDATE `category_id`=VALUES(`category_id`),`root_category`=VALUES(`root_category`),`name`=VALUES(`name`),`slug`=VALUES(`slug`),`sku`=VALUES(`sku`),`short_description`=VALUES(`short_description`),`description_html`=VALUES(`description_html`),`image`=VALUES(`image`),`unit`=VALUES(`unit`),`price`=VALUES(`price`),`request_hint`=VALUES(`request_hint`),`active`=VALUES(`active`),`featured`=VALUES(`featured`),`sort_order`=VALUES(`sort_order`),`seo_title`=VALUES(`seo_title`),`seo_description`=VALUES(`seo_description`),`source_file`=VALUES(`source_file`),`specs_json`=VALUES(`specs_json`),`gallery_json`=VALUES(`gallery_json`),`old_urls_json`=VALUES(`old_urls_json`);
INSERT INTO `products` (`id`,`category_id`,`root_category`,`name`,`slug`,`sku`,`short_description`,`description_html`,`image`,`unit`,`price`,`request_hint`,`active`,`featured`,`sort_order`,`seo_title`,`seo_description`,`source_file`,`specs_json`,`gallery_json`,`old_urls_json`) VALUES (926,3,'profile','Профилированный лист С44х1000','profile-s44kh1000','MNP-0926','Профилированный лист C-44x1000-A,B трапецевидной формы с шагом 35 мм и высотой ребра 44 мм, предназначен для широкого спектра применения: от организации скатных кровель до возведения заборов и ограждений, исключая использование в качестве несущих.','<div>Профилированный лист С44х1000 <p><strong>Профилированный лист C-44x1000-A,B </strong>трапецевидной формы с шагом 35 мм и высотой ребра 44 мм, предназначен для широкого спектра применения: от организации скатных кровель до возведения заборов и ограждений, исключая использование в качестве несущих покрытий. </p><p>Ширина ребра 100 мм без дополнительного усиления формирует внешний вид материала, делая его уместным для большинства зданий в современных стилях. </p><p><img alt="Профилированный лист С44x1000" loading="lazy" src="assets/img/products/p_5_1__0c00ff933ff7b907d8ef5e6a.jpg"/>Продукция поставляется в стандартных размерах, а также может быть изготовлена по индивидуальным заказам, размером вплоть до 12.0 метров в длину, что удобно при организации заборов и стен. </p><p>При использовании <em>профилированного листа C-44x1000 </em>в качестве кровельного покрытия рекомендуется нанесение антиконденсатного слоя на внутреннюю поверхность материала. </p><p>Области применения профилированного листа С44x1000 : </p><div><ul><li>стены, </li><li>заборы, </li><li>скатные кровли. </li></ul><p><img alt="Схема и конструкция продукции" loading="lazy" src="assets/img/products/p_5_2_1__4dc13f92519c794fb5aaf135.jpg"/></p><p><img alt="Схема и конструкция продукции" loading="lazy" src="assets/img/products/p_5_2_2__4798e649dd4a3378169b3ba8.jpg"/></p><table><tbody><tr><td><p>Тип </p></td><td><p>Высота профиля, мм </p></td><td><p>Ширина полная, мм </p></td><td><p>Ширина рабочая, мм </p></td><td><p>Ширина заготовки, мм </p></td><td><p>Толщина листа, мм </p></td><td><p>Масса 1м длины, кг </p></td><td><p>Масса 1м <sup>2 </sup>полной ширины, кг </p></td></tr><tr><td rowspan="4"><p>C44х1000-А </p><p>C44х1000-В </p></td><td rowspan="4"><p>44 </p></td><td rowspan="4"><p>1047 </p></td><td rowspan="4"><p>1000 </p></td><td rowspan="4"><p>1250 </p></td><td><p>0,5 </p></td><td><p>5,46 </p></td><td><p>5,21 </p></td></tr><tr><td><p>0,55 </p></td><td><p>5,9 </p></td><td><p>5,64 </p></td></tr><tr><td><p>0,7 </p></td><td><p>7,4 </p></td><td><p>7,7 </p></td></tr><tr><td><p>0,8 </p></td><td><p>11,5 </p></td><td><p>10,98 </p></td></tr></tbody></table></div></div>','assets/img/products/p_5_1__0c00ff933ff7b907d8ef5e6a.jpg','лист',NULL,'Укажите профиль, толщину, длину и количество листов, покрытие и цвет RAL.',1,0,926,'Профилированный лист С44х1000 — купить по заявке | Монополия','Профилированный лист С44х1000: подбор и поставка в Санкт-Петербурге. Укажите профиль, толщину, длину и количество листов, покрытие и цвет RAL. Расчет стоимости — по заявке.','site/www.monopoly-torg.ru/s44kh1000__aa0c0d5267a4ed2095a1cbd0.html','[]','["assets/img/products/p_5_1__0c00ff933ff7b907d8ef5e6a.jpg", "assets/img/products/p_5_2_1__4dc13f92519c794fb5aaf135.jpg", "assets/img/products/p_5_2_2__4798e649dd4a3378169b3ba8.jpg"]','["http://www.monopoly-torg.ru/index.php/profnactil/s44kh1000"]') ON DUPLICATE KEY UPDATE `category_id`=VALUES(`category_id`),`root_category`=VALUES(`root_category`),`name`=VALUES(`name`),`slug`=VALUES(`slug`),`sku`=VALUES(`sku`),`short_description`=VALUES(`short_description`),`description_html`=VALUES(`description_html`),`image`=VALUES(`image`),`unit`=VALUES(`unit`),`price`=VALUES(`price`),`request_hint`=VALUES(`request_hint`),`active`=VALUES(`active`),`featured`=VALUES(`featured`),`sort_order`=VALUES(`sort_order`),`seo_title`=VALUES(`seo_title`),`seo_description`=VALUES(`seo_description`),`source_file`=VALUES(`source_file`),`specs_json`=VALUES(`specs_json`),`gallery_json`=VALUES(`gallery_json`),`old_urls_json`=VALUES(`old_urls_json`);
INSERT INTO `products` (`id`,`category_id`,`root_category`,`name`,`slug`,`sku`,`short_description`,`description_html`,`image`,`unit`,`price`,`request_hint`,`active`,`featured`,`sort_order`,`seo_title`,`seo_description`,`source_file`,`specs_json`,`gallery_json`,`old_urls_json`) VALUES (927,3,'profile','Профилированный лист С-8х1150','profile-s8kh1150','MNP-0927','Профнастил C-8х1150-A,B – один из классических видов стенового материала. Сегодня данная продукция имеет достаточно широкую сферу применения и используется для облицовки фасадов промышленных и жилых зданий, возведения стен и перегородок, в.','<div>Профилированный лист С-8х1150 <p><strong>Профнастил C-8х1150-A,B </strong>– один из классических видов стенового материала. Сегодня данная продукция имеет достаточно широкую сферу применения и используется для облицовки фасадов промышленных и жилых зданий, возведения стен и перегородок, в качестве кровельного покрытия. </p><p>Профнастил C-8х1150-A,B имеет трапецевидную форму профиля небольшой высоты (8 мм) и шагом средней длины (52,5 мм), он прекрасно дополнит архитектурные решения в любом современном стиле. Полимерное покрытие обладает насыщенным цветом, стойкостью к механическим повреждениям и атмосферным явлениям, ультрафиолетовым лучам, благодаря чему профнастил долгое время сохраняет свой насыщенный цвет и эксплуатационные качества. </p><p><img alt="Профлист С8x1150" loading="lazy" src="assets/img/products/p_10_1__a4b98bc5955bd4cdde196e66.jpg"/></p><p>Полимерное покрытие наносится на сторону А по умолчанию, на сторону В – по заказу клиента. Со склада можно приобрести листы профнастила C-8х1150стандартных размеров (длиной 2.0, 3.0 или 6.0 м) или же сделать индивидуальный заказ: минимальная длина составляет 0,5 м, максимальная - 12.0 м. </p><div><p>Области применения профнастила C8х1150-A,B </p><ul><li>стены, </li><li>облицовка, </li><li>потолки, </li><li>заборы из профнастила. </li></ul><p><img alt="Схема и конструкция продукции" loading="lazy" src="assets/img/products/p_10_2_1__01a1b3e12b4a11d7b8bc35a2.jpg"/></p><p><img alt="Схема и конструкция продукции" loading="lazy" src="assets/img/products/p_10_2_2__39371163d8a5e97a2f4e287a.jpg"/></p><table><tbody><tr><td><p>Тип </p></td><td><p>Высота профиля, мм </p></td><td><p>Ширина полная, мм </p></td><td><p>Ширина рабочая, мм </p></td><td><p>Ширина заготовки, мм </p></td><td><p>Толщина листа, мм </p></td><td><p>Масса 1м длины, кг </p></td><td><p>Масса 1м <sup>2 </sup>полной ширины, кг </p></td></tr><tr><td rowspan="4"><p>C-8х1150-А </p><p>C-8х1150-В </p></td><td rowspan="4"><p>8 </p></td><td rowspan="4"><p>1200 </p></td><td rowspan="4"><p>1150 </p></td><td rowspan="4"><p>1250 </p></td><td><p>0,4 </p></td><td><p>4,4 </p></td><td><p>3,67 </p></td></tr><tr><td><p>0,5 </p></td><td><p>5,42 </p></td><td><p>4,50 </p></td></tr><tr><td><p>0,55 </p></td><td><p>5,91 </p></td><td><p>4,92 </p></td></tr><tr><td><p>0,7 </p></td><td><p>7,4 </p></td><td><p>6,17 </p></td></tr></tbody></table></div></div>','assets/img/products/p_10_1__a4b98bc5955bd4cdde196e66.jpg','лист',NULL,'Укажите профиль, толщину, длину и количество листов, покрытие и цвет RAL.',1,0,927,'Профилированный лист С-8х1150 — купить по заявке | Монополия','Профилированный лист С-8х1150: подбор и поставка в Санкт-Петербурге. Укажите профиль, толщину, длину и количество листов, покрытие и цвет RAL. Расчет стоимости — по заявке.','site/www.monopoly-torg.ru/s8kh1150__a72b19657fdffa81f066f11a.html','[]','["assets/img/products/p_10_1__a4b98bc5955bd4cdde196e66.jpg", "assets/img/products/p_10_2_1__01a1b3e12b4a11d7b8bc35a2.jpg", "assets/img/products/p_10_2_2__39371163d8a5e97a2f4e287a.jpg"]','["http://www.monopoly-torg.ru/index.php/profnactil/s8kh1150"]') ON DUPLICATE KEY UPDATE `category_id`=VALUES(`category_id`),`root_category`=VALUES(`root_category`),`name`=VALUES(`name`),`slug`=VALUES(`slug`),`sku`=VALUES(`sku`),`short_description`=VALUES(`short_description`),`description_html`=VALUES(`description_html`),`image`=VALUES(`image`),`unit`=VALUES(`unit`),`price`=VALUES(`price`),`request_hint`=VALUES(`request_hint`),`active`=VALUES(`active`),`featured`=VALUES(`featured`),`sort_order`=VALUES(`sort_order`),`seo_title`=VALUES(`seo_title`),`seo_description`=VALUES(`seo_description`),`source_file`=VALUES(`source_file`),`specs_json`=VALUES(`specs_json`),`gallery_json`=VALUES(`gallery_json`),`old_urls_json`=VALUES(`old_urls_json`);
INSERT INTO `products` (`id`,`category_id`,`root_category`,`name`,`slug`,`sku`,`short_description`,`description_html`,`image`,`unit`,`price`,`request_hint`,`active`,`featured`,`sort_order`,`seo_title`,`seo_description`,`source_file`,`specs_json`,`gallery_json`,`old_urls_json`) VALUES (928,28,'transformers','МАСЛЯНЫЕ ТРАНСФОРМАТОРЫ','938-maslyanye-transformatory','MNP-0928','Выпуск масляных трансформаторов ТМГ освоен на Минском электротехническом заводе им. В. И. Козлова в 1986 году по лицензии и на оборудовании французской фирмы "Alstom Atlantic".','<div><h4>Преимущества масляных трансформаторов ТМГ производства Минского электротехнического завода им. В.И. Козлова в сравнении с ТМ и ТМЗ </h4><p>Выпуск масляных трансформаторов ТМГ освоен на <strong>Минском электротехническом заводе им. В. И. Козлова в 1986 году </strong>по лицензии и на оборудовании французской фирмы "Alstom Atlantic". </p><p>В производстве трансформаторов ТМГ, как и в трансформаторах ведущих мировых фирм по производству трансформаторов, применен ряд технических решений, увеличивающих их надежность и снижающих эксплуатационные затраты. </p><ul><li><strong><strong>Масляные трансформаторы ТМГ </strong>изготавливаются в герметичном исполнении </strong>с полным заполнением маслом, без расширителя и без воздушной или газовой подушки. </li><li><strong>Контакт масла с окружающей средой полностью отсутствует </strong>, что исключает увлажнение, окисление и шламообразование масла. </li><li><strong>Перед заливкой масло дегазируется </strong>, заливка его в бак производится в специальной вакуумзаливочной камере при глубоком вакууме, что обеспечивает удаление из масла растворенного в нем воздуха, удаление из изоляции воздушных включений, тем самым предотвращается окисление масла, обеспечивается высокая электрическая прочность изоляции трансформатора. </li><li><strong>Масло в трансформаторах ТМГ </strong>Минского электротехнического завода им. В.И. Козлова <strong>(в отличие от масляных трансформаторов типа ТМ, ТМЗ, ТМГ других производителей </strong>, у которых не осуществляется дегазация масла) практически <strong>не меняет своих свойств в течение всего срока службы трансформатора </strong>. Исключается необходимость проведения испытаний масла трансформатора ТМГ как при его хранении, так и при вводе в эксплуатацию и в процессе эксплуатации (''... Из герметизированных трансформаторов проба масла не отбирается.'' Правила устройства электроустановок. Седьмое издание. Москва, 2003. Глава 1.8.16, п. 13). </li><li>Не требуется проведение профилактических, текущих и капитальных ремонтов в течение всего срока эксплуатации трансформатора. </li></ul><p><strong>Масляные трансформаторы </strong>других типов требуют дополнительного проведения испытаний трансформаторного масла в процессе хранения, ввода в эксплуатацию, эксплуатации, проведения текущих и капитальных ремонтов. </p><p>Кроме того, <strong>трансформаторы ТМ </strong>дополнительно требуют проведения систематических осмотров для определения степени увлажнения сорбента воздухоосушителя. При насыщении сорбента влагой требуется его замена на новый (на приобретение которого требуется расход средств) или на регенерированный (на регенерацию требуется расход тепловой энергии). </p><p><strong>В трансформаторах типа ТМЗ </strong>при хранении и эксплуатации необходимо систематически контролировать обязательное наличие избыточного давления азота (необходимо его подкачивать даже при наличии полной герметизации), так как возможно снижение давления азота за счёт поглощения его маслом. </p><p>Суммарные расходы на выполнение всех вышеизложенных работ в течение срока эксплуатации трансформаторов типа ТМ и ТМЗ достигают от 40 до 63 % полной стоимости трансформатора (в зависимости от его мощности). </p><ul><li><strong>Гофрированные баки трансформаторов ТМГ Минского электротехнического завода им. В.И. Козлова </strong>абсолютно безопасны и имеют высокую надежность. Избыточное давление в баках при эксплуатации трансформаторов не превышает 0,18 ... 0,23 кгс/см <sup>2 </sup></li></ul><p>Перед запуском в серийное производство гофрированные баки <strong>масляных трансформаторов ТМГ </strong>Минского электротехнического завода им. В.И.Козлова (в отличие от трансформаторов ТМГ других производителей) подвергаются механическим испытаниям на цикличность для подтверждения их ресурса работы на расчетный срок службы трансформатора - 25 лет (10000 циклов на воздействие максимального и минимального давлений). </p><ul><li>Для ограничения давления в баках при перегрузках <strong>масляные трансформаторы ТМГ </strong>Минского электротехнического завода им. В.И. Козлова мощностью <strong>от 16 до 63 кВА </strong>снабжаются предохранительным клапаном, в трансформаторах мощностью 100 кВ <sup>. </sup>А и выше возможна установка электроконтактного мановакуумметра. Для проверки уровня масла трансформаторы ТМГ всех мощностей снабжаются поплавковым маслоуказателем. </li><li>Для регулирования напряжения <strong>масляные трансформаторы </strong>снабжаются переключателями с автоматическим внутренним фиксатором положений и контактами оптимальной формы. Эти технические решения исключают выход из строя трансформаторов по причине короткого замыкания секций обмоток, и тем самым обеспечивается более высокая надежность трансформаторов Минского электротехнического завода им. В.И. Козлова по сравнению с трансформаторами, выпускаемыми другими производителями. </li><li>Круглая форма обмоток и ярмовые балки повышенной жесткости, выполненные из швеллера, обеспечивают устойчивость трансформаторов при коротких замыканиях. </li></ul><p>Трансформаторы других производителей подвержены повреждениям при коротких замыканиях из-за овальной конструкции обмоток и недостаточно жестких ярмовых балок, выполненных из уголка . </p><ul><li>Трансформаторы ТМГ Минского электротехнического завода им. В.И. Козлова соответствуют всем российским стандартам, стандартам МЭК, сертифицированы на соответствие требованиям безопасности нормативных документов Госстандартом России. Система качества предприятия сертифицирована международным органом по сертификации - "KEMA", Голландия - на соответствие МС ИСО 9001:2000 и национальным органом по сертификации - БелГИСС - на соответствие СТБ ИСО 9001-2001. </li></ul><p><strong>Более 600 тысяч трансформаторов типа ТМГ производства Минского электротехнического завода им. В.И. Козлова </strong>надёжно и практически с нулевыми эксплуатационными издержками работают на промышленных объектах, в городских и сельских электросетях. </p><p><strong>Гарантия на силовые трансформаторы составляет 5 лет (на трансформаторы ТМТО - 3 </strong>года со дня ввода в эксплуатацию). </p></div>','assets/img/product-placeholder.svg','шт.',NULL,'Укажите мощность, напряжение, исполнение и комплектацию. Приложите опросный лист или проект.',1,0,928,'МАСЛЯНЫЕ ТРАНСФОРМАТОРЫ — купить по заявке | Монополия','МАСЛЯНЫЕ ТРАНСФОРМАТОРЫ: подбор и поставка в Санкт-Петербурге. Укажите мощность, напряжение, исполнение и комплектацию. Приложите опросный лист или проект. Расчет стоимости — по заявке.','site/www.monopoly-torg.ru/938-maslyanye-transformatory__03161010d1031f904a0f45f6.html','[]','[]','["http://www.monopoly-torg.ru/index.php/transformatornye-podstantsii/silovye-transformatory/938-maslyanye-transformatory"]') ON DUPLICATE KEY UPDATE `category_id`=VALUES(`category_id`),`root_category`=VALUES(`root_category`),`name`=VALUES(`name`),`slug`=VALUES(`slug`),`sku`=VALUES(`sku`),`short_description`=VALUES(`short_description`),`description_html`=VALUES(`description_html`),`image`=VALUES(`image`),`unit`=VALUES(`unit`),`price`=VALUES(`price`),`request_hint`=VALUES(`request_hint`),`active`=VALUES(`active`),`featured`=VALUES(`featured`),`sort_order`=VALUES(`sort_order`),`seo_title`=VALUES(`seo_title`),`seo_description`=VALUES(`seo_description`),`source_file`=VALUES(`source_file`),`specs_json`=VALUES(`specs_json`),`gallery_json`=VALUES(`gallery_json`),`old_urls_json`=VALUES(`old_urls_json`);
INSERT INTO `products` (`id`,`category_id`,`root_category`,`name`,`slug`,`sku`,`short_description`,`description_html`,`image`,`unit`,`price`,`request_hint`,`active`,`featured`,`sort_order`,`seo_title`,`seo_description`,`source_file`,`specs_json`,`gallery_json`,`old_urls_json`) VALUES (929,28,'transformers','Трансформаторы ТМГ','939-transformatory-tmg','MNP-0929','Трансформатор ТМГ: ТМГ 16, ТМГ 25, ТМГ 40, ТМГ 63, ТМГ 100, ТМГ 160, ТМГ 250, ТМГ 400 , ТМГ 630, ТМГ 1000, ТМГ 1250.','<div><h4>Трансформаторы ТМГ </h4><p><br/><img alt="b 127" loading="lazy" src="assets/img/products/b_127__fdb86d3d855b9d68b391621c.jpg"/><img alt="b 128" loading="lazy" src="assets/img/products/b_128__6299dda107a166a27b58cd24.gif"/><img alt="b 73" loading="lazy" src="assets/img/products/b_73__1265a0b9e6734906a1ec9db4.jpg"/></p><h4>Трехфазные масляные силовые трансформаторы ТМГ мощностью 16 - 1250 кВА, напряжением 6(10) - 35 кВ </h4><table><tbody><tr><td><em><strong>ТУ РБ 100211261.015-2001 </strong></em></td><td></td><td></td></tr></tbody></table><p><strong>Трансформатор ТМГ: ТМГ 16, ТМГ 25, ТМГ 40, ТМГ 63, ТМГ 100, ТМГ 160, ТМГ 250, ТМГ 400 , ТМГ 630, ТМГ 1000, ТМГ 1250. </strong></p><p>Трехфазные <strong>масляные силовые трансформаторы ТМГ </strong>предназначены для преобразования электроэнергии в сетях энергосистем и потребителей электроэнергии в условиях наружной или внутренней установки умеренного (от плюс 40 <sup>о </sup>С до минус 45 <sup>о </sup>С) или холодного (от плюс 40 <sup>о </sup>С до минус 60 <sup>о </sup>С) климата. Окружающая среда невзрывоопасная, не содержащая пыли в концентрациях, снижающих параметры изделий в недопустимых пределах. Трансформаторы не предназначены для работы в условиях тряски, вибрации, ударов, в химически активной среде. Высота установки над уровнем моря не более 1000 м. </p><p>Гофрированные баки <strong>трансформаторов ТМГ </strong>Минского электротехнического завода им. В.И. Козлова абсолютно безопасны и имеют высокую надежность. Избыточное давление в баках при эксплуатации трансформаторов не превышает 0,18 ... 0,23 кгс/см <sup>2 </sup>. Перед запуском в серийное производство гофрированные баки <strong>трансформаторов ТМГ </strong>Минского электротехнического завода им. В.И.Козлова (в отличие от трансформаторов ТМГ других производителей) подвергаются механическим испытаниям на цикличность для подтверждения их ресурса работы на <strong>расчетный срок службы трансформатора - 25 лет </strong>(10000 циклов на воздействие максимального и минимального давлений). </p><p>Номинальная частота 50 Гц. Регулирование напряжения осуществляется в диапазоне до ± 5 % <strong>на полностью отключенном трансформаторе </strong>(ПБВ) переключением ответвлений обмотки ВН ступенями по 2,5 %. </p><p><strong>Трансформаторы ТМГ герметичного исполнения, без маслорасширителей. </strong>Температурные изменения объема масла компенсируются изменением объема гофров к бака за счет пластичной их деформации. </p><p>Для контроля уровня масла <strong>трансформаторы ТМГ </strong>снабжаются маслоуказателем поплавкового типа. </p><p>Для недопущения избыточного давления в баке сверх допустимого в трансформаторах ТМГ мощностью от 16 до 63 кВ <sup>. </sup>А устанавливается предохранительный клапан. Для контроля внутреннего давления в баке и сигнализации в случае превышения им допустимых величин в трансформаторах мощностью 100 кВ <sup>. </sup>А и выше, размещаемых в помещении предусматривается (по заказу потребителя) установка электроконтактного мановакуумметра. </p><p>Для измерения температуры верхних слоев масла на крышке трансформатора ТМГ предусматривается гильза для установки термометра. </p><p>Для измерения температуры верхних слоев масла и управления внешними электрическими цепями <strong>трансформатор ТМГ мощностью 1000 кВА </strong>(по заказу потребителя) комплектуется манометрическим сигнализирующим термометром. </p><p><strong>Трансформаторы ТМГ мощностью 160 кВА </strong>и выше (по заказу потребителя) комплектуются роликами для перемещения трансформатора. </p><p><strong>Трансформаторы ТМГ Минского электротехнического завода им. В.И. Козлова </strong>соответствуют всем российским стандартам, стандартам МЭК, сертифицированы на соответствие требованиям безопасности нормативных документов Госстандартом России. Система качества предприятия сертифицирована международным органом по сертификации - "KEMA", Голландия - на соответствие МС ИСО 9001:2000 и национальным органом по сертификации - БелГИСС - на соответствие СТБ ИСО 9001-2001. </p><p>Более 600 тысяч трансформаторов типа ТМГ производства Минского электротехнического завода им. В.И. Козлова надёжно и практически с нулевыми эксплуатационными издержками работают на промышленных объектах, в городских и сельских электросетях. </p><p><strong>Гарантия на силовые трансформаторы составляет 5 лет </strong>(на трансформаторы ТМТО - 3 года со дня ввода в эксплуатацию). </p><h2>Номенклатура силовых трансформаторов ТМГ: </h2><table><tbody><tr><td>ТМГ-16 /6(10) <br/>ТМГ-25 /6(10) <br/>ТМГ-25 /15 <br/>ТМГ-25 /27,5 <br/>ТМГ-40 /6(10) <br/>ТМГ-40 /15 <br/>ТМГ-63 /6(10) <br/>ТМГ-63 /15 <br/>ТМГ-100 /6(10) <br/>ТМГ-100 /15 <br/>ТМГ-100 /27,5(35) <br/>ТМГ-160 /6(10) <br/>ТМГ-160 /15 <br/>ТМГ-160 /27,5(35) </td><td>ТМГ-250 /6(10) <br/>ТМГ-250 /15 <br/>ТМГ-250 /27,5(35) <br/>ТМГ-400 /6(10) <br/>ТМГ-400 /15 <br/>ТМГ-400 /27,5(35) <br/>ТМГ-630 /6(10) <br/>ТМГ-630 /20 <br/>ТМГ-1000 /6(10) <br/>ТМГ-1000 /20 <br/>ТМГ-1250 /6(10) <br/>ТМГ-1250 /6(10) с КИП <br/>ТМГ-1250 /20 </td></tr></tbody></table></div>','assets/img/products/b_127__fdb86d3d855b9d68b391621c.jpg','шт.',NULL,'Укажите мощность, напряжение, исполнение и комплектацию. Приложите опросный лист или проект.',1,1,929,'Трансформаторы ТМГ — купить по заявке | Монополия','Трансформаторы ТМГ: подбор и поставка в Санкт-Петербурге. Укажите мощность, напряжение, исполнение и комплектацию. Приложите опросный лист или проект. Расчет стоимости — по заявке.','site/www.monopoly-torg.ru/939-transformatory-tmg__48f211003831dddc53e383b2.html','[]','["assets/img/products/b_127__fdb86d3d855b9d68b391621c.jpg", "assets/img/products/b_128__6299dda107a166a27b58cd24.gif", "assets/img/products/b_73__1265a0b9e6734906a1ec9db4.jpg"]','["http://www.monopoly-torg.ru/index.php/transformatornye-podstantsii/silovye-transformatory/939-transformatory-tmg"]') ON DUPLICATE KEY UPDATE `category_id`=VALUES(`category_id`),`root_category`=VALUES(`root_category`),`name`=VALUES(`name`),`slug`=VALUES(`slug`),`sku`=VALUES(`sku`),`short_description`=VALUES(`short_description`),`description_html`=VALUES(`description_html`),`image`=VALUES(`image`),`unit`=VALUES(`unit`),`price`=VALUES(`price`),`request_hint`=VALUES(`request_hint`),`active`=VALUES(`active`),`featured`=VALUES(`featured`),`sort_order`=VALUES(`sort_order`),`seo_title`=VALUES(`seo_title`),`seo_description`=VALUES(`seo_description`),`source_file`=VALUES(`source_file`),`specs_json`=VALUES(`specs_json`),`gallery_json`=VALUES(`gallery_json`),`old_urls_json`=VALUES(`old_urls_json`);
INSERT INTO `products` (`id`,`category_id`,`root_category`,`name`,`slug`,`sku`,`short_description`,`description_html`,`image`,`unit`,`price`,`request_hint`,`active`,`featured`,`sort_order`,`seo_title`,`seo_description`,`source_file`,`specs_json`,`gallery_json`,`old_urls_json`) VALUES (930,28,'transformers','Трансформаторы ТМГ11','940-transformatory-tmg11','MNP-0930','Трехфазные масляные трансформаторы ТМГ11 предназначены для преобразования электроэнергии в сетях энергосистем и потребителей электроэнергии в условиях наружной или внутренней установки умеренного (от плюс 40 до минус 45 о С) или холодного (от.','<div><h4>Трансформаторы ТМГ11 </h4><p><img alt="b 141" loading="lazy" src="assets/img/products/b_141__9744c2b0a8067209571f73e7.jpg"/></p><h4>Трехфазные масляные силовые трансформаторы ТМГ11 мощностью 100 - 2500 кВА, напряжением 6(10) - 15 кВ </h4><table><tbody><tr><td><em><strong>ТУ РБ 100211261.015-2001 </strong></em></td><td></td><td></td></tr></tbody></table><p><strong>Трехфазные масляные трансформаторы ТМГ11 </strong>предназначены для преобразования электроэнергии в сетях энергосистем и потребителей электроэнергии в условиях наружной или внутренней установки умеренного (от плюс 40 до минус 45 <sup>о </sup>С) или холодного (от плюс 40 до минус 60 <sup>о </sup>С) климата. Окружающая среда невзрывоопасная, не содержащая пыли в концентрациях, снижающих параметры <br/>изделий в недопустимых пределах. Трансформаторы не предназначены для работы в условиях тряски, вибрации, ударов, в химически активной среде. Высота установки над уровнем моря не более 1000 м. </p><p>Номинальная частота 50 Гц. Регулирование напряжения осуществляется в диапазоне до ± 5% на полностью отключенном трансформаторе (ПБВ) переключением ответвлений обмотки ВН ступенями по 2,5%. </p><p><strong>Трансформаторы ТМГ11 </strong>герметичного исполнения, без маслорасширителей. </p><p>Температурные изменения объема масла компенсируются изменением объема гофров бака за счет пластичной их деформации. </p><p>Для контроля уровня масла в трансформаторах предусмотрен маслоуказатель поплавкового типа. </p><p>Для контроля внутреннего давления в баке и сигнализации в случае превышения им допустимых величин в трансформаторах, размещаемых в помещении, предусматривается по заказу потребителя установка электроконтактного мановакуумметра. </p><p>Для измерения температуры верхних слоев масла на крышке трансформаторов предусмотрена гильза для установки жидкостного стеклянного термометра. </p><p>По заказу потребителя <strong>трансформаторы ТМГ 11 </strong>комплектуются жидкостными стеклянными термометрами. </p><p>Для измерения температуры верхних слоев масла и управления внешними электрическими цепями <strong>трансформаторы ТМГ11 мощностью от 630 до 1600 кВА </strong>, предназначенные для эксплуатации в помещении или под навесом, по заказу потребителя комплектуются манометрическим сигнализирующим термометром. </p><p><strong>Ввод нейтрали стороны НН трансформатора рассчитан на продолжительную нагрузку током, равным 100 % номинального тока обмотки НН. </strong></p><p><strong>Трансформаторы ТМГ 11 мощностью от 250 до 2500 кВА </strong>комплектуются транспортными роликами для перемещения трансформатора в продольном и поперечном направлениях. </p><p><strong>Трансформаторы ТМГ 11 мощностью 160 кВА </strong>классов напряжения 10 и 15 кВ комплектуются транспортными роликами по заказу потребителя. </p><p>При установке транспортных роликов размеры Н, Н1 (см. таблицу) увеличиваются на 94 мм в трансформаторах мощностью 160 и 250 кВА. </p><p><strong>Трансформаторы ТМГ11 Минского электротехнического завода им. В.И. Козлова </strong>соответствуют всем российским стандартам, стандартам МЭК, сертифицированы на соответствие требованиям безопасности нормативных документов Госстандартом России. Система качества предприятия сертифицирована международным органом по сертификации - "KEMA", Голландия - на соответствие МС ИСО 9001:2000 и национальным органом по сертификации - БелГИСС - на соответствие СТБ ИСО 9001-2001. </p><p>Более 600 тысяч трансформаторов типа ТМГ производства Минского электротехнического завода им. В.И. Козлова надёжно и практически с нулевыми эксплуатационными издержками работают на промышленных объектах, в городских и сельских электросетях. </p><p><strong>Гарантия на силовые трансформаторы составляет 5 лет </strong>(на трансформаторы ТМТО - 3 года со дня ввода в эксплуатацию). </p><h2>Номенклатура трансформаторов ТМГ11: </h2><table><tbody><tr><td>ТМГ11 - 100 /6(10) <br/>ТМГ11 - 100 /15 <br/>ТМГ11 - 160 /6(10) <br/>ТМГ11 - 160 /15 <br/>ТМГ11 - 160/15 с КИП <br/>ТМГ11 - 250 /6(10) <br/>ТМГ11 - 250 /15 <br/>ТМГ11 - 250/15 с КИП <br/>ТМГ11 - 400 /6(10) <br/>ТМГ11 - 400 /15 <br/>ТМГ11 - 400/15 с КИП </td><td><p>ТМГ11 - 630 /6(10) <br/>ТМГ11 - 1000 /6(10) <br/>ТМГ11 - 1250 /6(10) <br/>ТМГ11 - 1600 /6(10) <br/>ТМГ11 - 2500 /6(10) <br/>ТМГ11 - 100 /6(10) с КИП <br/>ТМГ11 - 160 /6(10) с КИП <br/>ТМГ11 - 250 /6(10) с КИП <br/>ТМГ11 - 400 /6(10) с КИП <br/>ТМГ11 - 630 /6(10) с КИП <br/>ТМГ11 - 1000 /6(10) с КИП <br/>ТМГ11 - 1250 /6(10) с КИП <br/>ТМГ11 - 1600 /6(10) с КИП </p></td></tr></tbody></table></div>','assets/img/products/b_141__9744c2b0a8067209571f73e7.jpg','шт.',NULL,'Укажите мощность, напряжение, исполнение и комплектацию. Приложите опросный лист или проект.',1,0,930,'Трансформаторы ТМГ11 — купить по заявке | Монополия','Трансформаторы ТМГ11: подбор и поставка в Санкт-Петербурге. Укажите мощность, напряжение, исполнение и комплектацию. Приложите опросный лист или проект. Расчет стоимости — по заявке.','site/www.monopoly-torg.ru/940-transformatory-tmg11__798c701d561489968b4e05e4.html','[]','["assets/img/products/b_141__9744c2b0a8067209571f73e7.jpg"]','["http://www.monopoly-torg.ru/index.php/transformatornye-podstantsii/silovye-transformatory/940-transformatory-tmg11"]') ON DUPLICATE KEY UPDATE `category_id`=VALUES(`category_id`),`root_category`=VALUES(`root_category`),`name`=VALUES(`name`),`slug`=VALUES(`slug`),`sku`=VALUES(`sku`),`short_description`=VALUES(`short_description`),`description_html`=VALUES(`description_html`),`image`=VALUES(`image`),`unit`=VALUES(`unit`),`price`=VALUES(`price`),`request_hint`=VALUES(`request_hint`),`active`=VALUES(`active`),`featured`=VALUES(`featured`),`sort_order`=VALUES(`sort_order`),`seo_title`=VALUES(`seo_title`),`seo_description`=VALUES(`seo_description`),`source_file`=VALUES(`source_file`),`specs_json`=VALUES(`specs_json`),`gallery_json`=VALUES(`gallery_json`),`old_urls_json`=VALUES(`old_urls_json`);
INSERT INTO `products` (`id`,`category_id`,`root_category`,`name`,`slug`,`sku`,`short_description`,`description_html`,`image`,`unit`,`price`,`request_hint`,`active`,`featured`,`sort_order`,`seo_title`,`seo_description`,`source_file`,`specs_json`,`gallery_json`,`old_urls_json`) VALUES (931,28,'transformers','Трансформаторы ТМГ12 (энергосберегающие)','941-transformatory-tmg12-energosberegayushchie','MNP-0931','Новый масляный силовой трансформатор ТМГ 12 с самым низким уровнем потерь холостого хода и короткого замыкания из серийно выпускаемых в России и СНГ.','<div><h4>Трансформаторы ТМГ12 (энергосберегающие) </h4><p><img alt="b 141" loading="lazy" src="assets/img/products/b_125__4281df9c6aab14f1ad42d441.jpg"/></p><h4><strong>Трансформаторы ТМГ12 мощностью 250 - 1250 кВА </strong>с самым низким уровнем потерь холостого хода и короткого замыкания </h4><table><tbody><tr><td><em><strong>ТУ РБ 100211261.015-2001 </strong></em></td><td></td><td></td></tr></tbody></table><p><strong>ТМГ-12 рекомендованы ЛЕНЭНЕРГО </strong><strong>! </strong></p><p>Новый <strong>масляный силовой трансформатор ТМГ 12 </strong>с самым низким уровнем потерь холостого хода и короткого замыкания из серийно выпускаемых в России и СНГ. </p><p><strong>Трансформаторы ТМГ12 мощностью 250 - 1250 кВА </strong>, благодаря использованию новых инженерных технологий и усовершенствованной методике расчета, имеют самый низкий уровень потерь холостого хода и короткого замыкания из всех серийно выпускаемых трансформаторов подобного назначения. </p><p>В <strong>трансформаторах </strong>данной серии сохранены лучшие качества <strong>трансформаторов серий ТМГ и ТМГ 11 </strong>. Они практически не отличаются по габаритам и массе от <strong>ТМГ 11 </strong>, что исключает дополнительные затраты на их установку. </p><p><strong>Потери холостого хода и короткого замыкания в минских трансформаторах серии ТМГ 12 снижены на 30% по сравнению с трансформаторами других серий и производителей за счет того, что: </strong></p><ul><li>производятся из специальных сортов высококачественных кремнистых сталей, имеющих наибольшее сопротивление и пониженные потери на гистерезис (перемагничивание); </li><li>для изготовления используется большее количество материала, который оптимально распределен между массой магнитопровода и обмотки; </li><li>конструкция магнитопровода производится по самой передовой технологии Stap-lap, и состоит из пластин с косыми стыками, без отверстий в активной стали; </li><li>толщина пластин не превышает 0, 3 мм, а сами пластины лакируются для изоляции друг от друга; </li><li>сборка трансформатора производится высококвалифицированным персоналом на оборудовании ведущих мировых производителей, что исключает любые возможные механические повреждения стали и обеспечивает минимизацию потерь. </li></ul><p><strong>Даже при неполной загрузке и ценах на электроэнергию трансформатор ТМГ12 в сутки будет приносить не менее 40 рублей за счет повышенного КПД. </strong></p><p><strong>Минские трансформаторы ТМГ 12 </strong>используются в условиях наружной и внутренней установки умеренного или холодного (от – 60° С до + 40° С) климата и соответствуют европейскому стандарту CENELEC. </p><p>Низкие потери холостого хода и короткого замыкания делают <strong>трансформаторы ТМГ12 </strong>: </p><ul><li><strong>Энергосберегающими <br/></strong>Годовая экономия на потерях в трансформаторах ТМГ 12 мощностью 630 кВ А составит 6,7 тыс. кВт ч, а в ТМГ 12 мощностью 1000 кВ А составит 5,4 тыс. кВт ч. </li><li><strong>Быстро окупаемыми <br/></strong>Разница в цене между минским трансформатором ТМГ 12 с трансформаторами более ранних серий составляет около 10 %. Срок окупаемости дополнительных вложений с учетом этой разницы для ТМГ 12 мощностью 630 кВ А составит менее 1 года, а для ТМГ 12 мощностью 1000 кВ А – менее 2 лет. </li><li><strong>Малошумными <br/></strong>Улучшенные шумовые характеристики - дополнительное преимущество снижению потерь холостого хода и короткого замыкания. </li></ul><p>Ввод нейтрали обмотки НН рассчитан на продолжительную нагрузку номинальным током, что соответствует последним требованиям МЭК и значительно повышает надежность трансформаторов при несимметричных нагрузках. </p><p>Даже при неполной загрузке и нынешних ценах на электроэнергию, <strong>трансформатор ТМГ 12 </strong>каждые сутки будет приносить вам не менее 1$ за счет повышенного КПД по сравнению с аналогичными трансформаторами других производителей. </p><p><strong>Трансформаторы ТМГ12 </strong>соответствуют европейскому стандарту CENELEC. Аналоги данной серии трансформаторов выпускаются только такими ведущими мировыми производителями как SIEMENS, ABB, AREVA. </p><p>Учитывая 10% разницу в сопоставимых ценах трансформаторов серий ТМГ и ТМГ12, срок окупаемости дополнительных вложений в <strong>трансформаторы </strong>для <strong>ТМГ12 </strong>составит менее 2 лет. По истечении указанных сроков эксплуатация <strong>трансформаторов ТМГ12 </strong>начинает приносить экономический эффект за счет экономии потерь электроэнергии. <br/>За весь срок службы трансформатора – более 25 лет – он позволит обеспечить значительную экономию российских энергоресурсов. </p><table><tbody><tr><td><p><strong>Номинальная мощность <br/>кВА </strong></p></td><td><p><strong>Годовая экономия на потерях в трансформаторе ТМГ12 <br/>тыс. кВт ч </strong></p></td></tr><tr><td><strong>ТМГ 12 - 630 </strong></td><td><p>6,7 </p></td></tr><tr><td><strong>ТМГ 12 - 1000 </strong></td><td><p>5,4 </p></td></tr></tbody></table><p>Применение данных <strong>трансформаторов </strong>при проектировании, реконструкции и строительстве новых объектов является наиболее рентабельным (экономичным). </p><p><strong>Компания «МИТЭК» </strong>является первым заказчиком на изготовление данного вида <strong>силовых трансформаторов ТМГ 12 </strong>. </p><p>Заказы формируются заранее, срок изготовления <strong>трансформатора ТМГ 12 </strong>составляет 30 дней. </p></div>','assets/img/products/b_125__4281df9c6aab14f1ad42d441.jpg','шт.',NULL,'Укажите мощность, напряжение, исполнение и комплектацию. Приложите опросный лист или проект.',1,0,931,'Трансформаторы ТМГ12 (энергосберегающие) — купить по заявке | Монополия','Трансформаторы ТМГ12 (энергосберегающие): подбор и поставка в Санкт-Петербурге. Укажите мощность, напряжение, исполнение и комплектацию. Приложите опросный лист или проект. Расчет стоимости — по заявке.','site/www.monopoly-torg.ru/941-transformatory-tmg12-energosberegayushchie__7a1c295497dedd67f39a5fe4.html','[["Номинальная мощность кВА", "Годовая экономия на потерях в трансформаторе ТМГ12 тыс. кВт ч"], ["ТМГ 12 - 630", "6,7"], ["ТМГ 12 - 1000", "5,4"]]','["assets/img/products/b_125__4281df9c6aab14f1ad42d441.jpg"]','["http://www.monopoly-torg.ru/index.php/transformatornye-podstantsii/silovye-transformatory/941-transformatory-tmg12-energosberegayushchie"]') ON DUPLICATE KEY UPDATE `category_id`=VALUES(`category_id`),`root_category`=VALUES(`root_category`),`name`=VALUES(`name`),`slug`=VALUES(`slug`),`sku`=VALUES(`sku`),`short_description`=VALUES(`short_description`),`description_html`=VALUES(`description_html`),`image`=VALUES(`image`),`unit`=VALUES(`unit`),`price`=VALUES(`price`),`request_hint`=VALUES(`request_hint`),`active`=VALUES(`active`),`featured`=VALUES(`featured`),`sort_order`=VALUES(`sort_order`),`seo_title`=VALUES(`seo_title`),`seo_description`=VALUES(`seo_description`),`source_file`=VALUES(`source_file`),`specs_json`=VALUES(`specs_json`),`gallery_json`=VALUES(`gallery_json`),`old_urls_json`=VALUES(`old_urls_json`);
INSERT INTO `products` (`id`,`category_id`,`root_category`,`name`,`slug`,`sku`,`short_description`,`description_html`,`image`,`unit`,`price`,`request_hint`,`active`,`featured`,`sort_order`,`seo_title`,`seo_description`,`source_file`,`specs_json`,`gallery_json`,`old_urls_json`) VALUES (932,28,'transformers','Трансформаторы ТМГ 21 - 1000 (с обмоткой НН из алюминиевой фольги)','942-transformatory-tmg-21-1000-s-obmotkoj-nn-iz-alyuminievoj-folgi','MNP-0932','Трансформаторы ТМГ 21 - 1000/10-У1 (ХЛ1) - это трехфазные масляные трансформаторы общего назначения с сочетанием напряжений 6/0,4 кВ и 10/0,4 кВ , схемой и группой соединения обмоток Д/Ун-11 .','<div><h4>Трансформаторы ТМГ 21 - 1000 (с обмоткой НН из алюминиевой фольги) </h4><p><img alt="b 127" loading="lazy" src="assets/img/products/b_154__8abb46af4093c6350876cbc3.jpg"/></p><h4>Трехфазные трансформаторы ТМГ 21 мощностью 1000 кВА, напряжением 6(10) кВ </h4><table><tbody><tr><td><em><strong>ТУ РБ 100211261.015-2001 </strong></em></td><td></td><td></td></tr></tbody></table><p><strong>Трансформаторы ТМГ 21 - 1000/10-У1 (ХЛ1) </strong>- это трехфазные масляные трансформаторы общего назначения с сочетанием напряжений <strong>6/0,4 кВ и 10/0,4 кВ </strong>, схемой и группой соединения обмоток <strong>Д/Ун-11 </strong>. </p><p><strong>Обмотка низшего напряжения НН трансформатора ТМГ 21 выполнена </strong>не из алюминиевых проводов, а <strong>из алюминиевой фольги, что обеспечивает простоту намотки при высоком уровне надежности. </strong></p><p>Применение современных изоляционных и обмоточных материалов позволяет сделать конструкцию, в которой негативные последствия ударов токов внешнего короткого замыкания сведены к минимуму. Ширина алюминиевой ленты равна высоте обмотки низшего напряжения НН, за счет чего значительно уменьшаются осевые динамические усилия в силовом трансформаторе. В качестве межслоевой изоляции используется бумага типа DDP, которая спекается в процессе сушки обмоток. В итоге, создается плотная целостная конструкция с повышенной стойкостью к радиальным усилиям. </p><p>Для контроля уровня масла в трансформаторах ТМГ 21 предусмотрен маслоуказатель поплавкового типа. </p><p>Для контроля внутреннего давления в баке и сигнализации в случае превышения им допустимых величин в трансформаторах ТМГ21, размещаемых в помещении, предусматривается по заказу потребителя установка электроконтактного мановакуумметра. </p><p>Для измерения температуры верхних слоев масла на крышке трансформаторов предусмотрена гильза для установки жидкостного стеклянного термометра, которым трансформаторы комплектуются по заказу потребителя. </p><p>Для измерения температуры верхних слоев масла и управления внешними электрическими цепями трансформаторы ТМГ 21, предназначенные для эксплуатации в помещении или под навесом, по заказу потребителя комплектуются манометрическим сигнализирующим термометром. </p><p>Ввод нейтрали стороны НН трансформатора ТМГ 21 рассчитан на продолжительную нагрузку током, равным 100% номинального тока обмотки НН. </p><p>Трансформаторы ТМГ21 комплектуются транспортными роликами для перемещения трансформатора в продольном и поперечном направлениях. </p></div>','assets/img/products/b_154__8abb46af4093c6350876cbc3.jpg','шт.',NULL,'Укажите мощность, напряжение, исполнение и комплектацию. Приложите опросный лист или проект.',1,0,932,'Трансформаторы ТМГ 21 - 1000 (с обмоткой НН из алюминиевой фольги) — купить по заявке | Монополия','Трансформаторы ТМГ 21 - 1000 (с обмоткой НН из алюминиевой фольги): подбор и поставка в Санкт-Петербурге. Укажите мощность, напряжение, исполнение и комплектацию. Приложите опросный лист или проект. Расчет стоимости — по заявке.','site/www.monopoly-torg.ru/942-transformatory-tmg-21-1000-s-obmotkoj-nn-iz-__23e3926efc13078f903ab2ba.html','[]','["assets/img/products/b_154__8abb46af4093c6350876cbc3.jpg"]','["http://www.monopoly-torg.ru/index.php/transformatornye-podstantsii/silovye-transformatory/942-transformatory-tmg-21-1000-s-obmotkoj-nn-iz-alyuminievoj-folgi"]') ON DUPLICATE KEY UPDATE `category_id`=VALUES(`category_id`),`root_category`=VALUES(`root_category`),`name`=VALUES(`name`),`slug`=VALUES(`slug`),`sku`=VALUES(`sku`),`short_description`=VALUES(`short_description`),`description_html`=VALUES(`description_html`),`image`=VALUES(`image`),`unit`=VALUES(`unit`),`price`=VALUES(`price`),`request_hint`=VALUES(`request_hint`),`active`=VALUES(`active`),`featured`=VALUES(`featured`),`sort_order`=VALUES(`sort_order`),`seo_title`=VALUES(`seo_title`),`seo_description`=VALUES(`seo_description`),`source_file`=VALUES(`source_file`),`specs_json`=VALUES(`specs_json`),`gallery_json`=VALUES(`gallery_json`),`old_urls_json`=VALUES(`old_urls_json`);
INSERT INTO `products` (`id`,`category_id`,`root_category`,`name`,`slug`,`sku`,`short_description`,`description_html`,`image`,`unit`,`price`,`request_hint`,`active`,`featured`,`sort_order`,`seo_title`,`seo_description`,`source_file`,`specs_json`,`gallery_json`,`old_urls_json`) VALUES (933,28,'transformers','Трансформаторы ТМГСУ, ТМГСУ11 с симметрирующим устройством','943-transformatory-tmgsu-tmgsu11-s-simmetriruyushchim-ustrojstvom','MNP-0933','Трансформаторы ТМГСУ: ТМГСУ-25, ТМГСУ-40, ТМГСУ-63, ТМГСУ11-100, ТМГСУ11-160, ТМГСУ11-250.','<div><h4>Трансформаторы ТМГСУ, ТМГСУ11 с симметрирующим устройством </h4><p><img alt="b 127" loading="lazy" src="assets/img/products/b_107__1ede8c2d0192263c1a54f609.jpg"/></p><h4>Трехфазные масляные силовые трансформаторы ТМГСУ 25 –63 кВА, ТМГСУ11 100 –250 кВА, напряжением 6 (10) кВ </h4><table><tbody><tr><td><em><strong>ТУ РБ 100211261.015-2001 </strong></em></td><td></td><td></td></tr></tbody></table><p><strong>Трансформаторы ТМГСУ: ТМГСУ-25, ТМГСУ-40, ТМГСУ-63, ТМГСУ11-100, ТМГСУ11-160, ТМГСУ11-250. </strong></p><p>Трехфазные <strong>масляные силовые трансформаторы ТМГСУ, ТМГСУ 11 </strong>с симметрирующим устройством предназначены для преобразования электроэнергии в сетях энергосистем и потребителей электроэнергии в условиях наружной или внутренней установки умеренного (от плюс 40 <sup>о </sup>С до минус 45 <sup>о </sup>С) или холодного (от плюс 40 <sup>о </sup>С до минус 60 <sup>о </sup>С) климата. Окружающая среда невзрывоопасная, не содержащая пыли в концентрациях, снижающих параметры изделий в недопустимых пределах. <strong>Трансформаторы ТМГСУ, ТМГСУ не предназначены для работы в условиях тряски, вибрации, ударов, в химически активной среде </strong>. Высота установки над уровнем моря не более 1000 м. </p><p>Трансформаторы ТМГСУ, ТМГСУ11 <strong>обеспечивают </strong><strong>поддержание симметричности фазных напряжений </strong><strong>в сетях энергосистем и потребителей электроэнергии с неравномерной пофазной нагрузкой. </strong>Сопротивление нулевой последовательности трансформаторов серии ТМГСУ в среднем в три раза меньше, чем у трансформаторов с соответствующими параметрами без симметрирующего устройства. </p><p>Номинальная частота 50 Гц. Регулирование напряжения осуществляется в диапазоне до ± 5 % <strong>на полностью отключенном трансформаторе </strong>(ПБВ) переключением ответвлений обмотки ВН ступенями по 2,5 %. </p><p><strong>Трансформаторы ТМГСУ, ТМГСУ 11 герметичного исполнения </strong>, без маслорасширителей. Температурные изменения объема масла компенсируются изменением объема гофров бака за счет пластичной их деформации. </p><p>Для контроля уровня масла в трансформаторах предусмотрен маслоуказатель поплавкового типа. </p><p>Для недопущения избыточного давления в баке сверх допустимого в трансформаторах мощностью от 16 до 63 кВ <sup>. </sup>А устанавливается предохранительный клапан. Для измерения температуры верхних слоев масла на крышке трансформаторов предусматривается гильза для установки жидкостного термометра. <strong>Трансформаторы ТМГСУ мощностью 160 и 250 кВА </strong>по заказу потребителя комплектуются транспортными роликами для перемещения трансформатора в продольном и поперечном направлениях. </p></div>','assets/img/products/b_107__1ede8c2d0192263c1a54f609.jpg','шт.',NULL,'Укажите мощность, напряжение, исполнение и комплектацию. Приложите опросный лист или проект.',1,0,933,'Трансформаторы ТМГСУ, ТМГСУ11 с симметрирующим устройством — купить по заявке | Монополия','Трансформаторы ТМГСУ, ТМГСУ11 с симметрирующим устройством: подбор и поставка в Санкт-Петербурге. Укажите мощность, напряжение, исполнение и комплектацию. Приложите опросный лист или проект. Расчет стоимости — по заявке.','site/www.monopoly-torg.ru/943-transformatory-tmgsu-tmgsu11-s-simmetriruyus__f25455e0be546320d746baa4.html','[]','["assets/img/products/b_107__1ede8c2d0192263c1a54f609.jpg"]','["http://www.monopoly-torg.ru/index.php/transformatornye-podstantsii/silovye-transformatory/943-transformatory-tmgsu-tmgsu11-s-simmetriruyushchim-ustrojstvom"]') ON DUPLICATE KEY UPDATE `category_id`=VALUES(`category_id`),`root_category`=VALUES(`root_category`),`name`=VALUES(`name`),`slug`=VALUES(`slug`),`sku`=VALUES(`sku`),`short_description`=VALUES(`short_description`),`description_html`=VALUES(`description_html`),`image`=VALUES(`image`),`unit`=VALUES(`unit`),`price`=VALUES(`price`),`request_hint`=VALUES(`request_hint`),`active`=VALUES(`active`),`featured`=VALUES(`featured`),`sort_order`=VALUES(`sort_order`),`seo_title`=VALUES(`seo_title`),`seo_description`=VALUES(`seo_description`),`source_file`=VALUES(`source_file`),`specs_json`=VALUES(`specs_json`),`gallery_json`=VALUES(`gallery_json`),`old_urls_json`=VALUES(`old_urls_json`);
INSERT INTO `products` (`id`,`category_id`,`root_category`,`name`,`slug`,`sku`,`short_description`,`description_html`,`image`,`unit`,`price`,`request_hint`,`active`,`featured`,`sort_order`,`seo_title`,`seo_description`,`source_file`,`specs_json`,`gallery_json`,`old_urls_json`) VALUES (934,28,'transformers','Трансформаторы ТМГМШ (малошумные)','944-transformatory-tmgmsh-maloshumnye','MNP-0934','Трехфазные масляные силовые трансформаторы ТМГМШ предназначены для преобразования электроэнергии в сетях энергосистем и потребителей электроэнергии в условиях наружной или внутренней установки умеренного (от плюс 40 до минус 45 о С) или холодного.','<div><h4>Трансформаторы ТМГМШ (малошумные) </h4><p><img alt="b 141" loading="lazy" src="assets/img/products/b_48__0ed5cac6edd43ef6050cdf54.jpg"/></p><h4>Трехфазные масляные силовые трансформаторы ТМГМШ мощностью 25 – 1000 кВА, напряжением 6(10) кВ </h4><table><tbody><tr><td><em><strong>ТУ РБ 100211261.015-2001 </strong></em></td><td></td><td></td></tr></tbody></table><p><strong>ТМГМШ рекомендованы ЛЕНЭНЕРГО </strong><strong>! </strong></p><p><strong>Трехфазные масляные силовые трансформаторы ТМГМШ </strong>предназначены для преобразования электроэнергии в сетях энергосистем и потребителей электроэнергии в условиях наружной или внутренней установки умеренного (от плюс 40 до минус 45 <sup>о </sup>С) или холодного (от плюс 40 до минус 60 <sup>о </sup>С) климата. Окружающая среда невзрывоопасная, не содержащая пыли в концентрациях, снижающих параметры изделий в недопустимых пределах. <strong>Трансформаторы ТМГМШ </strong>не предназначены для работы в условиях тряски, вибрации, ударов, в химически активной среде. Высота установки над уровнем моря не более 1000 м. </p><p>Трансформаторы ТМГМШ предназначены <strong>для потребителей с повышенными требованиями к уровню шума и к уровню потерь холостого хода. </strong></p><p>Номинальная частота 50 Гц. Регулирование напряжения осуществляется в диапазоне до ± 5 % <strong>на полностью отключенном трансформаторе </strong>(ПБВ) переключением ответвлений обмотки ВН ступенями по 2,5 %. </p><p>Трансформаторы ТМГМШ <strong>герметичного исполнения, без маслорасширителей. </strong>Температурные изменения объема масла компенсируются <strong>изменением объема гофров бака за счет пластичной их деформации. </strong></p><p>Для контроля уровня масла в трансформаторах предусмотрен маслоуказатель поплавкового типа. <br/>Для недопущения избыточного давления в баке сверх допустимого в трансформаторах мощностью от 25 до 63 кВ <sup>. </sup>А устанавливается предохранительный клапан. </p><p>Для контроля внутреннего давления в баке и сигнализации в случае превышения им допустимой величины в <strong>трансформаторах ТМГМШ мощностью 630 и 1000 кВА </strong>, размещаемых в помещении, предусматривается по заказу потребителя установка электроконтактного мановакуумметра. </p><p>Для измерения температуры верхних слоев масла на крышке трансформаторов ТМГМШ предусмотрена гильза для установки жидкостного термометра. </p><p>Для измерения температуры верхних слоев масла и управления внешними электрическими цепями <strong>трансформаторы ТМГМШ мощностью от 630 до 1000 кВА </strong>по заказу потребителя <strong>комплектуются манометрическим сигнализирующим термометром </strong>. </p><p><strong>Трансформаторы ТМГМШ </strong>мощностью от 160 до 630 кВ <sup>. </sup>А по заказу потребителя комплектуются транспортными роликами для перемещения трансформатора в продольном и поперечном направлениях. </p></div>','assets/img/products/b_48__0ed5cac6edd43ef6050cdf54.jpg','шт.',NULL,'Укажите мощность, напряжение, исполнение и комплектацию. Приложите опросный лист или проект.',1,0,934,'Трансформаторы ТМГМШ (малошумные) — купить по заявке | Монополия','Трансформаторы ТМГМШ (малошумные): подбор и поставка в Санкт-Петербурге. Укажите мощность, напряжение, исполнение и комплектацию. Приложите опросный лист или проект. Расчет стоимости — по заявке.','site/www.monopoly-torg.ru/944-transformatory-tmgmsh-maloshumnye__d9d65bd8d6b38cbc9fe723c9.html','[]','["assets/img/products/b_48__0ed5cac6edd43ef6050cdf54.jpg"]','["http://www.monopoly-torg.ru/index.php/transformatornye-podstantsii/silovye-transformatory/944-transformatory-tmgmsh-maloshumnye"]') ON DUPLICATE KEY UPDATE `category_id`=VALUES(`category_id`),`root_category`=VALUES(`root_category`),`name`=VALUES(`name`),`slug`=VALUES(`slug`),`sku`=VALUES(`sku`),`short_description`=VALUES(`short_description`),`description_html`=VALUES(`description_html`),`image`=VALUES(`image`),`unit`=VALUES(`unit`),`price`=VALUES(`price`),`request_hint`=VALUES(`request_hint`),`active`=VALUES(`active`),`featured`=VALUES(`featured`),`sort_order`=VALUES(`sort_order`),`seo_title`=VALUES(`seo_title`),`seo_description`=VALUES(`seo_description`),`source_file`=VALUES(`source_file`),`specs_json`=VALUES(`specs_json`),`gallery_json`=VALUES(`gallery_json`),`old_urls_json`=VALUES(`old_urls_json`);
INSERT INTO `products` (`id`,`category_id`,`root_category`,`name`,`slug`,`sku`,`short_description`,`description_html`,`image`,`unit`,`price`,`request_hint`,`active`,`featured`,`sort_order`,`seo_title`,`seo_description`,`source_file`,`specs_json`,`gallery_json`,`old_urls_json`) VALUES (935,28,'transformers','Трансформатор ТМ 2500 кВА','945-transformator-tm-2500-kva','MNP-0935','Cиловой распределительный трансформатор серии ТМ мощностью 2500 кВА предназначен для крупных промышленных предприятий, имеющих свои энергоемкие производства, такие как нефтеперерабатывающие или металлургические.','<div><h4>Трансформатор ТМ 2500 кВА </h4><p><img alt="b 107" loading="lazy" src="assets/img/products/b_149__0f2901d8a290452b913921a0.jpg"/></p><h4>Силовой распределительный трансформатор серии ТМ мощностью 2500 кВА </h4><table><tbody><tr><td><em><strong>ТУ РБ 100211261.015-2001 </strong></em></td><td></td><td></td></tr></tbody></table><p><strong>Cиловой распределительный трансформатор серии ТМ мощностью 2500 кВА </strong>предназначен для крупных промышленных предприятий, имеющих свои энергоемкие производства, такие как нефтеперерабатывающие или металлургические. </p><p><strong>Трансформатор ТМ 2500 кВА </strong>предназначен для преобразования электроэнергии в сетях энергосистем и потребителей электроэнергии для наружной или внутренней их установки в условиях умеренного (-45 ... +40 <sup>0 </sup>С) или холодного (-60...+40 <sup>0 </sup>С) климата. </p><p>Окружающая среда невзрывоопасная, не содержит пыль в концентрациях, снижающих параметры изделий в недопустимых пределах. Высота установки над уровнем моря не более 1000 м. </p><p><strong>Трансформатор ТМ 2500 кВА </strong>не предназначен для работы в условиях тряски, вибрации, ударов или в химически активной среде. </p><p>Номинальная частота 50 гц. <strong>Трансформатор ТМ 2500 кВА </strong>имеет на каждой фазе стороны НН расщепленные вводы. Ввод нейтрали стороны НН <strong>трансформатора ТМ 2500 кВА </strong>рассчитан на продолжительную нагрузку током, равным 100% от номинального тока обмотки НН. Для регулирования уровня масла в расширители <strong>трансформатора ТМ 2500 кВА </strong>предусмотрен стрелочный электронноконтактный маслоуказатель. Регулирование напряжения осуществляется в диапазоне ±5% на полностью отключенном трансформаторе (ПБВ) переключением ответвлений обмотки ВН ступенями по 2,5%. </p></div>','assets/img/products/b_149__0f2901d8a290452b913921a0.jpg','шт.',NULL,'Укажите мощность, напряжение, исполнение и комплектацию. Приложите опросный лист или проект.',1,0,935,'Трансформатор ТМ 2500 кВА — купить по заявке | Монополия','Трансформатор ТМ 2500 кВА: подбор и поставка в Санкт-Петербурге. Укажите мощность, напряжение, исполнение и комплектацию. Приложите опросный лист или проект. Расчет стоимости — по заявке.','site/www.monopoly-torg.ru/945-transformator-tm-2500-kva__ad6cf3d65116932ba63b6e1e.html','[]','["assets/img/products/b_149__0f2901d8a290452b913921a0.jpg"]','["http://www.monopoly-torg.ru/index.php/transformatornye-podstantsii/silovye-transformatory/945-transformator-tm-2500-kva"]') ON DUPLICATE KEY UPDATE `category_id`=VALUES(`category_id`),`root_category`=VALUES(`root_category`),`name`=VALUES(`name`),`slug`=VALUES(`slug`),`sku`=VALUES(`sku`),`short_description`=VALUES(`short_description`),`description_html`=VALUES(`description_html`),`image`=VALUES(`image`),`unit`=VALUES(`unit`),`price`=VALUES(`price`),`request_hint`=VALUES(`request_hint`),`active`=VALUES(`active`),`featured`=VALUES(`featured`),`sort_order`=VALUES(`sort_order`),`seo_title`=VALUES(`seo_title`),`seo_description`=VALUES(`seo_description`),`source_file`=VALUES(`source_file`),`specs_json`=VALUES(`specs_json`),`gallery_json`=VALUES(`gallery_json`),`old_urls_json`=VALUES(`old_urls_json`);
INSERT INTO `products` (`id`,`category_id`,`root_category`,`name`,`slug`,`sku`,`short_description`,`description_html`,`image`,`unit`,`price`,`request_hint`,`active`,`featured`,`sort_order`,`seo_title`,`seo_description`,`source_file`,`specs_json`,`gallery_json`,`old_urls_json`) VALUES (936,28,'transformers','Трансформаторы ТМЭГ, ТМБГ для экскаваторов и буровых установок','946-transformatory-tmeg-tmbg-dlya-ekskavatorov-i-burovykh-ustanovok','MNP-0936','Трансформаторы ТМЭГ, ТМБГ: ТМЭГ-40, ТМЭГ-63, ТМЭГ-100, ТМЭГ-160, ТМЭГ-160, ТМЭГ-250, ТМБГ-250, ТМБГ-400, ТМБГ-630.','<div><h4>Трансформаторы ТМЭГ, ТМБГ для экскаваторов и буровых установок </h4><p><img alt="b 48" loading="lazy" src="assets/img/products/b_45__6107b48dfa490e7db5651417.gif"/><img alt="b 73" loading="lazy" src="assets/img/products/b_54__3f1da0a3fcfc75b3b54d4942.gif"/></p><h4>Трехфазные масляные силовые трансформаторы ТМЭГ мощностью 40 – 250 кВА, напряжением 6(10) кВ и ТМБГ мощностью 250 кВА, напряжением 6(10) кВ </h4><table><tbody><tr><td><em><strong>ТУ РБ 100211261.015-2001 </strong></em></td><td></td><td></td></tr></tbody></table><p><strong>Трансформаторы ТМЭГ, ТМБГ: ТМЭГ-40, ТМЭГ-63, ТМЭГ-100, ТМЭГ-160, ТМЭГ-160, ТМЭГ-250, ТМБГ-250, ТМБГ-400, ТМБГ-630. </strong></p><p><strong>Трехфазные масляные силовые трансформаторы ТМЭГ, ТМБГ </strong>предназначены для преобразования электроэнергии в составе электрооборудования соответственно <strong>экскаваторов и буровых установок </strong>в условиях умеренного (от плюс 35 до минус 45 <sup>о </sup>С) или холодного (от плюс 35 до минус 60 <sup>о </sup>С) климата. </p><p>Окружающая среда невзрывоопасная, запыленность воздуха не более 100 мг/м3. Высота установки над уровнем моря не более 1000 м. </p><p>Допускается эксплуатация при температуре окружающего воздуха до плюс 45 <sup>о </sup>С при снижении нагрузки на 15 %. В интервале температур окружающего воздуха от минус 60 до плюс 10 <sup>о </sup>С нагрузка может быть увеличена на 10 %. Регулирование напряжения осуществляется в диапазоне до ±5 % н <strong>а полностью отключенном трансформаторе </strong>(ПБВ) переключением ответвлений обмотки ВН ступенями по 2,5 %. </p><p><strong>Трансформаторы ТМЭГ, ТМБГ </strong>допускают работу в условиях тряски, вибрации, воздействия инерционных сил при разгоне и торможении поворотной платформы, в условиях крена и дифферента до 12 <sup>о </sup>. </p><p>Номинальные рабочие значения механических внешних воздействующих факторов <strong>трансформаторов ТМЭГ, ТМБГ </strong>для группы механического исполнения <strong>М29 </strong>, при этом: </p><ul><li>максимальная амплитуда ускорения синусоидальной вибрации до 5 м.с-2 (0,5g); </li><li>верхняя частота диапазона синусоидальной вибрации до 35 Гц. </li></ul><p><strong>Трансформаторы серии ТМЭГ и ТМБГ герметичного исполнения </strong>, без маслорасширителей. Температурные изменения объема масла <em>компенсируются изменением объема гофров бака за счет пластичной их деформации. </em></p><p>Для измерения температуры верхних слоев масла на крышке <strong>трансформаторов ТМЭГ, ТМБГ </strong>предусмотрена гильза для установки жидкостного термометра. </p><p>Выводы ВН и НН трансформаторов <strong>ТМЭГ, ТМБГ </strong>закрыты кожухом, защищающим их от механических повреждений и возможности случайного прикосновения к токоведущим частям. Степень защиты <strong>IР23. </strong></p><p><strong>Трансформаторы ТМБГ </strong>снабжены салазками. </p><p>Схема и группа соединения обмоток трансформаторов <strong>ТМЭГ, ТМБГ </strong>У/Ун-0, номинальная частота - 50 Гц, напряжение короткого замыкания - 4,5 %. </p></div>','assets/img/products/b_45__6107b48dfa490e7db5651417.gif','шт.',NULL,'Укажите мощность, напряжение, исполнение и комплектацию. Приложите опросный лист или проект.',1,0,936,'Трансформаторы ТМЭГ, ТМБГ для экскаваторов и буровых установок — купить по заявке | Монополия','Трансформаторы ТМЭГ, ТМБГ для экскаваторов и буровых установок: подбор и поставка в Санкт-Петербурге. Укажите мощность, напряжение, исполнение и комплектацию. Приложите опросный лист или проект. Расчет стоимости — по заявке.','site/www.monopoly-torg.ru/946-transformatory-tmeg-tmbg-dlya-ekskavatorov-i__e923f173953cdfdf4c25f0ee.html','[]','["assets/img/products/b_45__6107b48dfa490e7db5651417.gif", "assets/img/products/b_54__3f1da0a3fcfc75b3b54d4942.gif"]','["http://www.monopoly-torg.ru/index.php/transformatornye-podstantsii/silovye-transformatory/946-transformatory-tmeg-tmbg-dlya-ekskavatorov-i-burovykh-ustanovok"]') ON DUPLICATE KEY UPDATE `category_id`=VALUES(`category_id`),`root_category`=VALUES(`root_category`),`name`=VALUES(`name`),`slug`=VALUES(`slug`),`sku`=VALUES(`sku`),`short_description`=VALUES(`short_description`),`description_html`=VALUES(`description_html`),`image`=VALUES(`image`),`unit`=VALUES(`unit`),`price`=VALUES(`price`),`request_hint`=VALUES(`request_hint`),`active`=VALUES(`active`),`featured`=VALUES(`featured`),`sort_order`=VALUES(`sort_order`),`seo_title`=VALUES(`seo_title`),`seo_description`=VALUES(`seo_description`),`source_file`=VALUES(`source_file`),`specs_json`=VALUES(`specs_json`),`gallery_json`=VALUES(`gallery_json`),`old_urls_json`=VALUES(`old_urls_json`);
INSERT INTO `products` (`id`,`category_id`,`root_category`,`name`,`slug`,`sku`,`short_description`,`description_html`,`image`,`unit`,`price`,`request_hint`,`active`,`featured`,`sort_order`,`seo_title`,`seo_description`,`source_file`,`specs_json`,`gallery_json`,`old_urls_json`) VALUES (937,28,'transformers','Трансформаторы однофазные ОМ, ОМП, ОМГ','947-transformatory-odnofaznye-om-omp-omg','MNP-0937','Трансформаторы однофазные масляные ОМ, ОМП, ОМГ предназначены для преобразования электроэнергии в сетях энергосистем, питания аппаратуры сигнализации и автоблокировки железных дорог, питания других однофазных потребителей электроэнергии.','<div><h4>Трансформаторы однофазные ОМ, ОМП, ОМГ </h4><p><img alt="b 107" loading="lazy" src="assets/img/products/b_50__c97d1c3a290555b1477fb981.jpg"/><img alt="b 54" loading="lazy" src="assets/img/products/b_71__aeef91e589eb5f71df20449f.jpg"/><img alt="b 73" loading="lazy" src="assets/img/products/b_51__ec39a4e97a766f91faa854ec.jpg"/><img alt="b 52" loading="lazy" src="assets/img/products/b_52__3df34c84e41ef141326951b6.jpg"/></p><h4>Трансформаторы однофазные ОМ, ОМП, ОМГ: ОМ-0,25; ОМ-1,25; ОМ-2,5; ОМП-4; ОМ-4; ОМП-10; ОМГ-10 </h4><table><tbody><tr><td><em><strong>ТУ16-96 ИВЕМ.672113.002ТУ <br/>ТУ РБ 100211261.009-2001 </strong></em></td><td></td><td></td></tr></tbody></table><p><strong>Трансформаторы однофазные масляные ОМ, ОМП, ОМГ </strong>предназначены для преобразования электроэнергии в сетях энергосистем, питания аппаратуры сигнализации и автоблокировки железных дорог, питания других однофазных потребителей электроэнергии. </p><p>Трансформаторы <strong>ОМ, ОМП, ОМГ </strong>предназначены для работы в условиях умеренного (от плюс 40 <sup>о </sup>С до минус 45 <sup>о </sup>С), холодного или умеренно-холодного (от плюс 40 <sup>о </sup>С до минус 60 <sup>о </sup>С) климата. </p><p>Схема и группа соединения обмоток 1/1-0. Номинальная частота 50 Гц. </p><p>Регулирование напряжения трансформаторов <strong>ОМ, ОМП, ОМГ </strong>осуществляется <strong>без возбуждения трансформаторов </strong>(ПБВ) переключением ответвлений обмоток. </p><p>Окружающая среда невзрывоопасная, не содержащая пыли в концентрациях, снижающих параметры изделий в недопустимых пределах. Высота установки над уровнем моря не более 1000 м. </p></div>','assets/img/products/b_50__c97d1c3a290555b1477fb981.jpg','шт.',NULL,'Укажите мощность, напряжение, исполнение и комплектацию. Приложите опросный лист или проект.',1,0,937,'Трансформаторы однофазные ОМ, ОМП, ОМГ — купить по заявке | Монополия','Трансформаторы однофазные ОМ, ОМП, ОМГ: подбор и поставка в Санкт-Петербурге. Укажите мощность, напряжение, исполнение и комплектацию. Приложите опросный лист или проект. Расчет стоимости — по заявке.','site/www.monopoly-torg.ru/947-transformatory-odnofaznye-om-omp-omg__c1fb5198f626e2e48f1253f9.html','[]','["assets/img/products/b_50__c97d1c3a290555b1477fb981.jpg", "assets/img/products/b_71__aeef91e589eb5f71df20449f.jpg", "assets/img/products/b_51__ec39a4e97a766f91faa854ec.jpg", "assets/img/products/b_52__3df34c84e41ef141326951b6.jpg"]','["http://www.monopoly-torg.ru/index.php/transformatornye-podstantsii/silovye-transformatory/947-transformatory-odnofaznye-om-omp-omg"]') ON DUPLICATE KEY UPDATE `category_id`=VALUES(`category_id`),`root_category`=VALUES(`root_category`),`name`=VALUES(`name`),`slug`=VALUES(`slug`),`sku`=VALUES(`sku`),`short_description`=VALUES(`short_description`),`description_html`=VALUES(`description_html`),`image`=VALUES(`image`),`unit`=VALUES(`unit`),`price`=VALUES(`price`),`request_hint`=VALUES(`request_hint`),`active`=VALUES(`active`),`featured`=VALUES(`featured`),`sort_order`=VALUES(`sort_order`),`seo_title`=VALUES(`seo_title`),`seo_description`=VALUES(`seo_description`),`source_file`=VALUES(`source_file`),`specs_json`=VALUES(`specs_json`),`gallery_json`=VALUES(`gallery_json`),`old_urls_json`=VALUES(`old_urls_json`);
INSERT INTO `products` (`id`,`category_id`,`root_category`,`name`,`slug`,`sku`,`short_description`,`description_html`,`image`,`unit`,`price`,`request_hint`,`active`,`featured`,`sort_order`,`seo_title`,`seo_description`,`source_file`,`specs_json`,`gallery_json`,`old_urls_json`) VALUES (938,28,'transformers','Трансформатор ТМТО-80/0,38-У1','948-transformator-tmto-80-0-38-u1','MNP-0938','Трехфазный масляный трансформатор ТМТО-80/0,38-У1 предназначен для преобразования электроэнергии в составе устройств термической обработки бетона и грунта, питания электроинструмента и временного освещения в условиях умеренного климата. Рабочая.','<div><h4>Трансформатор ТМТО-80/0,38-У1 </h4><p><img alt="b 51" loading="lazy" src="assets/img/products/b_105__fa09576d82c224ced6945b1b.jpg"/></p><h4>Трехфазный масляный силовой трансформатор ТМТО-80/0,38-У1 (для подстанций КТПТО-80) </h4><table><tbody><tr><td><em><strong>ТУ РБ 100211261.015-2001 </strong></em></td><td></td><td></td></tr></tbody></table><p><strong>Трехфазный масляный трансформатор ТМТО-80/0,38-У1 </strong>предназначен для преобразования электроэнергии в составе устройств термической обработки бетона и грунта, питания электроинструмента и временного освещения в условиях умеренного климата. Рабочая температура окружающего воздуха от минус 45 <sup>о </sup>С до плюс 10 <sup>о </sup>С. </p><p>Окружающая среда невзрывоопасная, не содержащая пыли в концентрациях, снижающих параметры изделия в недопустимых пределах. <strong>Трансформатор ТМТО-80 </strong>не предназначен для работы в условиях тряски, вибрации, ударов, в химически активной среде. </p><p>Высота установки над уровнем моря не более 1000 м. Номинальная частота 50 Гц. Схема и группа соединения У/Д/Д-11-11. Напряжение в обмотке среднего напряжения (СН) регулируется ступенями <strong>при полностью отключенном трансформаторе </strong>(ПБВ). </p></div>','assets/img/products/b_105__fa09576d82c224ced6945b1b.jpg','шт.',NULL,'Укажите мощность, напряжение, исполнение и комплектацию. Приложите опросный лист или проект.',1,0,938,'Трансформатор ТМТО-80/0,38-У1 — купить по заявке | Монополия','Трансформатор ТМТО-80/0,38-У1: подбор и поставка в Санкт-Петербурге. Укажите мощность, напряжение, исполнение и комплектацию. Приложите опросный лист или проект. Расчет стоимости — по заявке.','site/www.monopoly-torg.ru/948-transformator-tmto-80-0-38-u1__293dcbb95f655aeb60be28a0.html','[]','["assets/img/products/b_105__fa09576d82c224ced6945b1b.jpg"]','["http://www.monopoly-torg.ru/index.php/transformatornye-podstantsii/silovye-transformatory/948-transformator-tmto-80-0-38-u1"]') ON DUPLICATE KEY UPDATE `category_id`=VALUES(`category_id`),`root_category`=VALUES(`root_category`),`name`=VALUES(`name`),`slug`=VALUES(`slug`),`sku`=VALUES(`sku`),`short_description`=VALUES(`short_description`),`description_html`=VALUES(`description_html`),`image`=VALUES(`image`),`unit`=VALUES(`unit`),`price`=VALUES(`price`),`request_hint`=VALUES(`request_hint`),`active`=VALUES(`active`),`featured`=VALUES(`featured`),`sort_order`=VALUES(`sort_order`),`seo_title`=VALUES(`seo_title`),`seo_description`=VALUES(`seo_description`),`source_file`=VALUES(`source_file`),`specs_json`=VALUES(`specs_json`),`gallery_json`=VALUES(`gallery_json`),`old_urls_json`=VALUES(`old_urls_json`);
INSERT INTO `products` (`id`,`category_id`,`root_category`,`name`,`slug`,`sku`,`short_description`,`description_html`,`image`,`unit`,`price`,`request_hint`,`active`,`featured`,`sort_order`,`seo_title`,`seo_description`,`source_file`,`specs_json`,`gallery_json`,`old_urls_json`) VALUES (939,28,'transformers','Трансформаторы ТМПН, ТМПНГ с первичным напряжением 0,38кВ','949-transformatory-tmpn-tmpng-s-pervichnym-napryazheniem-0-38kv','MNP-0939','Трехфазные масляные трансформаторы ТМПН, ТМПНГ с первичным напряжением 0,38 кВ предназначены преобразования электроэнергии в составе электроустановок питания погружных электронасосов добычи нефти в условиях умеренного (от плюс 40 о С до минус 45.','<div><h4>Трансформаторы ТМПН, ТМПНГ с первичным напряжением 0,38кВ </h4><p><img alt="b 50" loading="lazy" src="assets/img/products/b_109__f7532994d83131d61694bba3.jpg"/><img alt="b 51" loading="lazy" src="assets/img/products/b_110__13ef981ab18be1502b60c40c.jpg"/></p>Трансформаторы: ТМПН-63, ТМПН-100, ТМПНГ-100; ТМПНГ-102, ТМПН-125, ТМПН-160, ТМПНГ-160, ТМПНГ-165, ТМПН-250, ТМПНГ-250, ТМПНГ-253, ТМПНГ-300, ТМПНГ-404, ТМПНГ-426, ТМПНГ-426, ТМПНГ-520, ТМПНГ-630, ТМПНГ-665, ТМПНГ-700, ТМПНГ-900, ТМПНГ-1000, ТМПНГ-1023, ТМПН-1200 <table><tbody><tr><td><em><strong>ТУ РБ 05544590.030-98 </strong></em></td><td></td><td></td></tr></tbody></table><p>Трехфазные масляные <strong>трансформаторы ТМПН, ТМПНГ </strong>с первичным напряжением <strong>0,38 кВ </strong>предназначены преобразования электроэнергии в составе электроустановок питания погружных электронасосов добычи нефти в условиях умеренного (от плюс 40 <sup>о </sup>С до минус 45 <sup>о </sup>С) или холодного (от плюс 40 <sup>о </sup>С до минус 60 <sup>о </sup>С) климата. </p><p>Трансформаторы в исполнении АУХЛ1 допускают работу в составе частотно-регулируемого привода. При этом между частотным преобразователем и трансформатором должны быть установлены фильтры гармоник. <strong>При работе на частоте ниже номинальной должен соблюдаться закон U/f=const, при частоте выше номинальной должен соблюдаться закон U=const. </strong>Дополнительные технические характеристики и условия эксплуатации данных трансформаторов предоставляются по требованию потребителя. </p><p>Окружающая среда невзрывоопасная, не содержащая пыли в концентрациях, снижающих параметры изделий в недопустимых пределах. Трансформаторы не предназначены для работы в условиях тряски, вибрации, ударов, в химически активной среде. Высота установки над уровнем моря не более 1000 м. </p><p>Номинальная частота 50 Гц. Регулирование напряжения осуществляется <strong>на полностью отключенном трансформаторе </strong>(ПБВ). </p><p><strong>Трансформаторы ТМПН </strong>- с маслорасширителями, внутренний объем трансформаторов сообщается с окружающим воздухом. </p><p><strong>Трансформаторы ТМПНГ </strong>- герметичного исполнения с гофрированными или жесткими (гладкими) баками без маслорасширителей. Температурные изменения объема масла в трансформаторах с гофрированными баками компенсируются изменением объема гофров стенок бака за счет их пластичной деформации. </p><p>Температурные изменения объема масла в трансформаторах с гладкими баками компенсируются воздушной "подушкой". </p><p>Вводы НН и ВН <strong>трансформаторов ТМПНГ в жестких (гладких) </strong>баках расположены на боковой стенке бака, <strong>трансформаторов ТМПНГ (в гофробаках) и ТМПН - на крышке бака </strong>. </p><p>Вводы НН и ВН защищены кожухом. Степень защиты - IP 13. </p><p>Конструкция трансформаторов предусматривает кабельный ввод и вывод напряжения, обеспечивает надежное подключение кабелей без необходимости напаивания наконечников. </p><p>Для измерения температуры верхних слоев масла в трансформаторах предусматривается гильза для установки жидкостного термометра. </p><p>Для удобства перемещения в условиях эксплуатации <strong>трансформаторы ТМПН, ТМПНГ мощностью до 400 кВА </strong>снабжены салазками. </p><p>В <strong>трансформаторах ТМПН, ТМПНГ с жесткими (гладкими) баками </strong>предусматривается защита сливной пробки от несанкционированного слива масла. </p></div>','assets/img/products/b_109__f7532994d83131d61694bba3.jpg','шт.',NULL,'Укажите мощность, напряжение, исполнение и комплектацию. Приложите опросный лист или проект.',1,0,939,'Трансформаторы ТМПН, ТМПНГ с первичным напряжением 0,38кВ — купить по заявке | Монополия','Трансформаторы ТМПН, ТМПНГ с первичным напряжением 0,38кВ: подбор и поставка в Санкт-Петербурге. Укажите мощность, напряжение, исполнение и комплектацию. Приложите опросный лист или проект. Расчет стоимости — по заявке.','site/www.monopoly-torg.ru/949-transformatory-tmpn-tmpng-s-pervichnym-napry__b3743c84f7271b8abb046e8d.html','[]','["assets/img/products/b_109__f7532994d83131d61694bba3.jpg", "assets/img/products/b_110__13ef981ab18be1502b60c40c.jpg"]','["http://www.monopoly-torg.ru/index.php/transformatornye-podstantsii/silovye-transformatory/949-transformatory-tmpn-tmpng-s-pervichnym-napryazheniem-0-38kv"]') ON DUPLICATE KEY UPDATE `category_id`=VALUES(`category_id`),`root_category`=VALUES(`root_category`),`name`=VALUES(`name`),`slug`=VALUES(`slug`),`sku`=VALUES(`sku`),`short_description`=VALUES(`short_description`),`description_html`=VALUES(`description_html`),`image`=VALUES(`image`),`unit`=VALUES(`unit`),`price`=VALUES(`price`),`request_hint`=VALUES(`request_hint`),`active`=VALUES(`active`),`featured`=VALUES(`featured`),`sort_order`=VALUES(`sort_order`),`seo_title`=VALUES(`seo_title`),`seo_description`=VALUES(`seo_description`),`source_file`=VALUES(`source_file`),`specs_json`=VALUES(`specs_json`),`gallery_json`=VALUES(`gallery_json`),`old_urls_json`=VALUES(`old_urls_json`);
INSERT INTO `products` (`id`,`category_id`,`root_category`,`name`,`slug`,`sku`,`short_description`,`description_html`,`image`,`unit`,`price`,`request_hint`,`active`,`featured`,`sort_order`,`seo_title`,`seo_description`,`source_file`,`specs_json`,`gallery_json`,`old_urls_json`) VALUES (940,28,'transformers','Трансформаторы ТМПН, ТМПНГ с первичным напряжением 6; 10 кВ','950-transformatory-tmpn-tmpng-s-pervichnym-napryazheniem-6-10-kv','MNP-0940','Трехфазные масляные трансформаторы ТМПН, ТМПНГ с первичным напряжением 6; 10 кВ предназначены для преобразования электроэнергии в составе комплектных трансформаторных подстанций, питающих погружные электронасосы добычи нефти. Трансформаторы ТМПН,.','<div><h4>Трансформаторы ТМПН, ТМПНГ с первичным напряжением 6; 10 кВ </h4><p><img alt="b 50" loading="lazy" src="assets/img/products/b_67__711cc494039e47a17cfb4f8b.gif"/></p><h4>Трансформаторы ТМПН, ТМПНГ: ТМПН-100, ТМПН-250, ТМПНГ-403, ТМПНГ-1000. </h4><table><tbody><tr><td><em><strong>ТУ16-717.140-83 </strong></em></td><td></td><td></td></tr></tbody></table><p>Трехфазные масляные <strong>трансформаторы ТМПН, ТМПНГ </strong>с первичным напряжением <strong>6; 10 кВ </strong>предназначены для преобразования электроэнергии в составе комплектных трансформаторных подстанций, питающих погружные электронасосы добычи нефти. <strong>Трансформаторы ТМПН, ТМПНГ </strong>могут эксплуатироваться в условиях умеренного (от плюс 40 <sup>о </sup>С до минус 45 <sup>о </sup>С) или холодного (от плюс 40 <sup>о </sup>С до минус 60 <sup>о </sup>С) климата. </p><p>Окружающая среда невзрывоопасная, не содержащая пыли в концентрациях, снижающих параметры изделий в недопустимых пределах. <strong>Трансформаторы ТМПН, ТМПНГ </strong>не предназначены для работы в условиях тряски, вибрации, ударов, в химически активной среде. Высота установки над уровнем моря не более 1000 м. </p><p>Номинальная частота 50 Гц. Схема и группа соединения обмоток - У/Ун-11. </p><p>Регулирование напряжения осуществляется <strong>на полностью отключенном трансформаторе </strong>(ПБВ). </p><p><strong>Трансформаторы ТМПН, ТМПНГ </strong>рассчитаны на работу в двух режимах: </p><ul><li>питание погружных электродвигателей; </li><li>питание ремонтного фидера (напряжением <strong>0,4 кВ у ТМПН </strong>и <strong>0,384 кВ у ТМПНГ- 1000/6-УХЛ1 </strong>). </li></ul><p>У <strong>трансформаторов ТМПН </strong>вводы ВН расположены на стенке бака, вводы НН - на крышке бака.В трансформаторе <strong>ТМПНГ-400/6-УХЛ1 </strong>вводы ВН и НН расположены на боковой стенке бака. </p><p>В трансформаторе <strong>ТМПНГ-1000/6-УХЛ1 </strong>выводы ВН и НН расположены на крышке бака. </p><p><strong>Трансформаторы ТМПН - с маслорасширителями </strong>, внутренний объем трансформаторов сообщается с окружающим воздухом. </p><p><strong>Трансформатор ТМПНГ-403/6-УХЛ1 </strong>- герметичного исполнения, без маслорасширителя в жестком баке. Температурные изменения объема масла компенсируются "воздушной подушкой". <br/></p><p><strong>Трансформатор ТМПНГ-1000/6-УХЛ1 </strong>- герметичного исполнения, без маслорасширителя в гофробаке. Температурные изменения объема масла компенсируются изменением объема гофров за счет пластичной их деформации. </p><p>Для удобства перемещения трансформаторы комплектуются транспортными роликами. </p><p>Для измерения температуры верхних слоев масла в трансформаторах предусматривается гильза для установки термометра. </p></div>','assets/img/products/b_67__711cc494039e47a17cfb4f8b.gif','шт.',NULL,'Укажите мощность, напряжение, исполнение и комплектацию. Приложите опросный лист или проект.',1,0,940,'Трансформаторы ТМПН, ТМПНГ с первичным напряжением 6; 10 кВ — купить по заявке | Монополия','Трансформаторы ТМПН, ТМПНГ с первичным напряжением 6; 10 кВ: подбор и поставка в Санкт-Петербурге. Укажите мощность, напряжение, исполнение и комплектацию. Приложите опросный лист или проект. Расчет стоимости — по заявке.','site/www.monopoly-torg.ru/950-transformatory-tmpn-tmpng-s-pervichnym-napry__881fd19cbf67dffaf64ce820.html','[]','["assets/img/products/b_67__711cc494039e47a17cfb4f8b.gif"]','["http://www.monopoly-torg.ru/index.php/transformatornye-podstantsii/silovye-transformatory/950-transformatory-tmpn-tmpng-s-pervichnym-napryazheniem-6-10-kv"]') ON DUPLICATE KEY UPDATE `category_id`=VALUES(`category_id`),`root_category`=VALUES(`root_category`),`name`=VALUES(`name`),`slug`=VALUES(`slug`),`sku`=VALUES(`sku`),`short_description`=VALUES(`short_description`),`description_html`=VALUES(`description_html`),`image`=VALUES(`image`),`unit`=VALUES(`unit`),`price`=VALUES(`price`),`request_hint`=VALUES(`request_hint`),`active`=VALUES(`active`),`featured`=VALUES(`featured`),`sort_order`=VALUES(`sort_order`),`seo_title`=VALUES(`seo_title`),`seo_description`=VALUES(`seo_description`),`source_file`=VALUES(`source_file`),`specs_json`=VALUES(`specs_json`),`gallery_json`=VALUES(`gallery_json`),`old_urls_json`=VALUES(`old_urls_json`);
INSERT INTO `products` (`id`,`category_id`,`root_category`,`name`,`slug`,`sku`,`short_description`,`description_html`,`image`,`unit`,`price`,`request_hint`,`active`,`featured`,`sort_order`,`seo_title`,`seo_description`,`source_file`,`specs_json`,`gallery_json`,`old_urls_json`) VALUES (941,28,'transformers','СУХИЕ ТРАНСФОРМАТОРЫ','951-sukhie-transformatory','MNP-0941','Сухие трансформаторы Минского ЭТЗ им. В.И. Козлова имеют высокие эксплуатационные показатели и зарекомендовали себя как надежное электротехническое оборудование, работающее на крупнейших промышленных предприятиях. По сравнению с сухими.','<div><h4>СУХИЕ ТРАНСФОРМАТОРЫ </h4><h4>Минские сухие трансформаторы ТСЗГЛ- преимущества для российских покупателей </h4><p><strong>Сухие трансформаторы </strong><strong>Минского ЭТЗ им. В.И. Козлова </strong>имеют высокие эксплуатационные показатели и зарекомендовали себя как надежное электротехническое оборудование, работающее на крупнейших промышленных предприятиях. По сравнению с <strong>сухими трансформаторами TRIHAL, </strong><strong>трансформаторы ТСЗГЛ </strong>более привлекательны для российских покупателей из-за более низкой стоимости, т. к. производятся на одном из крупнеших, в постсоветском пространстве, заводе, являющимся одним из мировых лидеров в электротехнической сфере. При производстве <strong>сухих трансформаторов </strong>используются современные материалы и комплектующие. </p><p><strong>Сухие трансформаторы ТСЗГЛ </strong>- это качественная продукция, дающая вам: </p><ul><li>низкие значения потерь холостого хода (благодаря самой передовой технологии производства магнитопровода «Stap-lap») и короткого замыкания, что делает их энергосберегающими; </li><li>высокую электрическую прочность (в <strong>сухих трансформаторах </strong>используются обмотки ВН и НН «Siemens») по отношению к испытательному напряжению промышленной частоты и грозовому импульсу напряжения; </li><li>возможность эксплуатации <strong>сухих трансформаторов </strong>в условиях перегрузки по току; </li><li>высокую стойкость к механическим усилиям, возникающим в режиме короткого замыкания; </li><li>предотвращение возникновения трещин в эпоксидном компаунде при температурных и нагрузочных колебаниях в широких пределах сухих трансформаторов, так как для изоляции обмоток используется геафоль (эпоксидный компаунд с кварцевым наполнителем), дополнительно обмотки усилены стеклотканью. <strong>Минские сухие трансформаторы </strong>являются самыми экологичными, так как даже при воздействии дуговых разрядов этот материал не оказывает вредного влияния на окружающую среду, не выделяет никаких токсичных газов; </li><li>возможность работы без технического обслуживания; </li><li>самые высокие показатели по пожаробезопасности; </li><li>возможность работы в климатических условиях умеренного климата, то есть в диапазоне температур окружающей среды от минус 45°С до плюс 45°С (в то время как, европейское оборудование далеко не всегда рассчитано на работу в суровых российских условиях). </li></ul><p>Говоря о высокой надежности и качестве <strong>сухих трансформаторов </strong>, нужно учесть, что основная экономия средств приходится на период эксплуатации электротехнического оборудования, когда на установку, монтаж и наладку и последующие обслуживание будет тратиться значительно меньшее количество трудовых и финансовых усилий. Так каждый вложенный рубль сегодня даст вам как минимум 3 рубля прибыли в будущем. <br/>Мы экономим ваши средства, предлагая экономичное, надежное, современное, оборудование премиум-класса по выгодной цене, без потерь качества - это <strong>сухие трансформаторы ТСЗГЛ </strong>. </p></div>','assets/img/product-placeholder.svg','шт.',NULL,'Укажите мощность, напряжение, исполнение и комплектацию. Приложите опросный лист или проект.',1,0,941,'СУХИЕ ТРАНСФОРМАТОРЫ — купить по заявке | Монополия','СУХИЕ ТРАНСФОРМАТОРЫ: подбор и поставка в Санкт-Петербурге. Укажите мощность, напряжение, исполнение и комплектацию. Приложите опросный лист или проект. Расчет стоимости — по заявке.','site/www.monopoly-torg.ru/951-sukhie-transformatory__486bbc42cba9a05ee5a714ad.html','[]','[]','["http://www.monopoly-torg.ru/index.php/transformatornye-podstantsii/silovye-transformatory/951-sukhie-transformatory"]') ON DUPLICATE KEY UPDATE `category_id`=VALUES(`category_id`),`root_category`=VALUES(`root_category`),`name`=VALUES(`name`),`slug`=VALUES(`slug`),`sku`=VALUES(`sku`),`short_description`=VALUES(`short_description`),`description_html`=VALUES(`description_html`),`image`=VALUES(`image`),`unit`=VALUES(`unit`),`price`=VALUES(`price`),`request_hint`=VALUES(`request_hint`),`active`=VALUES(`active`),`featured`=VALUES(`featured`),`sort_order`=VALUES(`sort_order`),`seo_title`=VALUES(`seo_title`),`seo_description`=VALUES(`seo_description`),`source_file`=VALUES(`source_file`),`specs_json`=VALUES(`specs_json`),`gallery_json`=VALUES(`gallery_json`),`old_urls_json`=VALUES(`old_urls_json`);
INSERT INTO `products` (`id`,`category_id`,`root_category`,`name`,`slug`,`sku`,`short_description`,`description_html`,`image`,`unit`,`price`,`request_hint`,`active`,`featured`,`sort_order`,`seo_title`,`seo_description`,`source_file`,`specs_json`,`gallery_json`,`old_urls_json`) VALUES (942,28,'transformers','Сухие трансформаторы ТСГЛ, ТСЗГЛ, ТСЗГЛ11, ТСЗГЛФ11 с геафолевой литой изоляцией','952-sukhie-transformatory-tsgl-tszgl-tszgl11-tszglf11-s-geafolevoj-litoj-izolyatsiej','MNP-0942','На территории России установлено более 5000 сухих трансформаторов производства Минского электротехнического завода им. В.И. Козлова.','<div><h4>Сухие трансформаторы ТСГЛ, ТСЗГЛ, ТСЗГЛ11, ТСЗГЛФ11 с геафолевой литой изоляцией </h4><p><img alt="b 131" loading="lazy" src="assets/img/products/b_131__74cf581960faa9f0dc995bf2.jpg"/><img alt="b 113" loading="lazy" src="assets/img/products/b_113__b65c7ccdf92f0f3160bcf54f.jpg"/><img alt="b 132" loading="lazy" src="assets/img/products/b_132__fede6aa60b44d84935ff478b.jpg"/><img alt="b 29" loading="lazy" src="assets/img/products/b_29__2923a4c5824741b93aa1b561.jpg"/></p><h4>Сухие трансформаторы силовые трехфазные с геафолевой литой изоляцией ТСГЛ, ТСЗГЛ, ТСЗГЛ11, ТСЗГЛФ11 мощностью 100 – 2500 кВА (100, 160, 250, 400, 630, 1000, 1250, 1600, 2500 кВА), напряжением 6(10) кВ </h4><table><tbody><tr><td><em><strong>ТУ РБ 05544590.018-96 </strong></em></td><td></td><td></td></tr></tbody></table><p>Сухие трансформаторы силовые <strong>ТСГЛ, ТСЗГЛ, ТСЗГЛ11 </strong>(с вводами ВН внутри кожуха) и <strong>ТСЗГЛФ11 </strong>(с вводами ВН, выведенными на фланец, расположенный на торцевой поверхности кожуха) напряжением до 10 кВ предназначены для преобразования электроэнергии в сетях энергосистем и потребителей электроэнергии переменного тока номинальной частоты 50 Гц. <strong>Сухие трансформаторы </strong>предназначены для работы в помещениях, в условиях умеренного климата (от плюс 40 <sup>о </sup>С до минус 45 <sup>о </sup>С). Относительная влажность воздуха 75 % при 15 <sup>о </sup>С. Окружающая среда невзрывоопасная, не содержащая пыли в кон-центрациях, снижающих параметры изделий в недопустимых пределах. Высота установки над уровнем моря не более 1000 м. <strong>Сухие трансформаторы комплектуются обмотками фирмы "Siemens". Класс нагревостойкости обмоток F. <br/></strong><br/>Для изоляции обмоток используется эпоксидный компаунд с кварцевым наполнителем (геафоль). Дополнительно обмотки усилены стеклотканью, что исключает возникновение трещин в эпоксидном компаунде даже при перегрузке трансформаторов. Геафоль не оказывает вредного влияния на окружающую среду, не выделяет токсичных газов даже при воздействии дуговых разрядов. Благодаря такой изоляции обмотки не требуют технического обслуживания. <strong>Сухие трансформаторы ТСГЛ, ТСЗГЛ, ТСЗГЛ11, ТСЗГЛФ11 </strong>с геафолевой <strong>литой изоляцией </strong>могут работать в сетях, подверженных грозовым и коммутационным перенапряжениям, имеют низкий уровень шума, имеют высокую устойчивость к токам короткого замыкания.Сухие трансформаторы обеспечивают <strong>полную экологическую и пожарную безопасность </strong>, могут устанавливаться в местах, <strong>требующих повышенной безопасности </strong>(метро, шахтах, кинотеатрах, жилых и общественных зданиях), <strong>в местах с повышенными требованиями к охране окружающей среды </strong>(водозаборных станциях, спортивных сооружениях, курортных зонах), на промышленных предприятиях, металлургических комбинатах, химических производствах, электростанциях <strong>в непосредственной близости от центра нагрузки </strong>, что позволяет избежать <em>издержек </em>, связанных со строительством подстанций, <em>обеспечивает экономию </em>распределительных шин и кабелей низкого напряжения, <em>уменьшает </em>в них потери электроэнергии.Регулирование напряжения до ±5 % ступенями 2,5 % осуществляется <strong>на полностью отключенном трансформаторе </strong>(ПБВ) путем перестановки перемычек.Для защиты от перегрева по заказу потребителя <strong>сухие трансформаторы ТСГЛ, ТСЗГЛ, ТСЗГЛ11, ТСЗГЛФ11 </strong>комплектуются устройством тепловой защиты, управляемым термисторами, встроенными в обмотки НН. По заказу потребителя могут поставляться виброгасящие подкладки.Степень защиты <strong>сухих трансформаторов ТСГЛ </strong>- IР 00, ТСЗГЛ и ТСЗГЛФ - IР 21. Схема и группа соединения обмоток - Д/Ун-11, У/Ун-0, номинальное напряжение НН - 400В. </p><p><strong>На территории России установлено более 5000 сухих трансформаторов производства Минского электротехнического завода им. В.И. Козлова. <br/></strong></p></div>','assets/img/products/b_131__74cf581960faa9f0dc995bf2.jpg','шт.',NULL,'Укажите мощность, напряжение, исполнение и комплектацию. Приложите опросный лист или проект.',1,0,942,'Сухие трансформаторы ТСГЛ, ТСЗГЛ, ТСЗГЛ11, ТСЗГЛФ11 с геафолевой литой изоляцией — купить по заявке | Монополия','Сухие трансформаторы ТСГЛ, ТСЗГЛ, ТСЗГЛ11, ТСЗГЛФ11 с геафолевой литой изоляцией: подбор и поставка в Санкт-Петербурге. Укажите мощность, напряжение, исполнение и комплектацию. Приложите опросный лист или проект. Расчет стоимости — по заявке.','site/www.monopoly-torg.ru/952-sukhie-transformatory-tsgl-tszgl-tszgl11-tsz__ba929260b22e4910f6ce187f.html','[]','["assets/img/products/b_131__74cf581960faa9f0dc995bf2.jpg", "assets/img/products/b_113__b65c7ccdf92f0f3160bcf54f.jpg", "assets/img/products/b_132__fede6aa60b44d84935ff478b.jpg", "assets/img/products/b_29__2923a4c5824741b93aa1b561.jpg"]','["http://www.monopoly-torg.ru/index.php/transformatornye-podstantsii/silovye-transformatory/952-sukhie-transformatory-tsgl-tszgl-tszgl11-tszglf11-s-geafolevoj-litoj-izolyatsiej"]') ON DUPLICATE KEY UPDATE `category_id`=VALUES(`category_id`),`root_category`=VALUES(`root_category`),`name`=VALUES(`name`),`slug`=VALUES(`slug`),`sku`=VALUES(`sku`),`short_description`=VALUES(`short_description`),`description_html`=VALUES(`description_html`),`image`=VALUES(`image`),`unit`=VALUES(`unit`),`price`=VALUES(`price`),`request_hint`=VALUES(`request_hint`),`active`=VALUES(`active`),`featured`=VALUES(`featured`),`sort_order`=VALUES(`sort_order`),`seo_title`=VALUES(`seo_title`),`seo_description`=VALUES(`seo_description`),`source_file`=VALUES(`source_file`),`specs_json`=VALUES(`specs_json`),`gallery_json`=VALUES(`gallery_json`),`old_urls_json`=VALUES(`old_urls_json`);
INSERT INTO `products` (`id`,`category_id`,`root_category`,`name`,`slug`,`sku`,`short_description`,`description_html`,`image`,`unit`,`price`,`request_hint`,`active`,`featured`,`sort_order`,`seo_title`,`seo_description`,`source_file`,`specs_json`,`gallery_json`,`old_urls_json`) VALUES (943,28,'transformers','Сухие трансформаторы ТС, ТСЗ класса напряжения 0,66 кВ (380/220 В)','953-sukhie-transformatory-ts-tsz-klassa-napryazheniya-0-66-kv-380-220-v','MNP-0943','Трехфазные сухие трансформаторы ТС (без кожуха) и ТСЗ (с кожухом) предназначены для преобразования электроэнергии у потребителей в условиях умеренно-холодного климата в помещениях с искусственно регулируемыми климатическими условиями (от плюс 35.','<div><h4>Сухие трансформаторы ТС, ТСЗ класса напряжения 0,66 кВ (380/220 В) </h4><p><img alt="b 72" loading="lazy" src="assets/img/products/b_72__34e87bac75032d95919cae5d.jpg"/><img alt="b 56" loading="lazy" src="assets/img/products/b_56__a58b55379c9a416cddfa5d52.gif"/></p>Трехфазные сухие трансформаторы ТС (без кожуха) и ТСЗ (с кожухом) 16 - 100 кВА класса напряжения 0,66 кВ (380/220 В) <table><tbody><tr><td><em><strong>ТУ РБ 05544590.034-99 </strong></em></td><td></td><td></td></tr></tbody></table><p><strong>Трехфазные сухие трансформаторы ТС </strong>(без кожуха) и <strong>ТСЗ </strong>(с кожухом) предназначены для преобразования электроэнергии у потребителей в условиях умеренно-холодного климата в помещениях с искусственно регулируемыми климатическими условиями (от плюс 35 <sup>о </sup>С до плюс 1 <sup>о </sup>С). Окружающая среда невзрывоопасная, не содержащая пыли в концентрациях снижающих параметры в недопустимых пределах. Трансформаторы не предназначены для работы в условиях тряски, вибрации, ударов, в химически активной среде. Высота установки над уровнем моря не более 1000 м. </p><p><strong>Сухие трансформаторы </strong>имеют высокую надежность, практически не требуют затрат на обслуживание, экономичны. </p><p>Корректированный уровень звуковой мощности не более 65 дБА. </p><p>Степень защиты сухих трансформаторов ТС- IР 00, трансформаторов ТСЗ - IР 21. </p><p>Номинальная частота 50 Гц. </p><p>Класс нагревостойкости изоляции - А. </p><p>Высшее напряжение ВН </p><p>По заказу потребителей могут быть изготовлены <strong>сухие трансформаторы </strong>с любыми сочетаниями напряжений до 660 В и с другими схемами и группами соединения. </p></div>','assets/img/products/b_72__34e87bac75032d95919cae5d.jpg','шт.',NULL,'Укажите мощность, напряжение, исполнение и комплектацию. Приложите опросный лист или проект.',1,0,943,'Сухие трансформаторы ТС, ТСЗ класса напряжения 0,66 кВ (380/220 В) — купить по заявке | Монополия','Сухие трансформаторы ТС, ТСЗ класса напряжения 0,66 кВ (380/220 В): подбор и поставка в Санкт-Петербурге. Укажите мощность, напряжение, исполнение и комплектацию. Приложите опросный лист или проект. Расчет стоимости — по заявке.','site/www.monopoly-torg.ru/953-sukhie-transformatory-ts-tsz-klassa-napryazh__beebd42ad9a042fc4d28d8f1.html','[]','["assets/img/products/b_72__34e87bac75032d95919cae5d.jpg", "assets/img/products/b_56__a58b55379c9a416cddfa5d52.gif"]','["http://www.monopoly-torg.ru/index.php/transformatornye-podstantsii/silovye-transformatory/953-sukhie-transformatory-ts-tsz-klassa-napryazheniya-0-66-kv-380-220-v"]') ON DUPLICATE KEY UPDATE `category_id`=VALUES(`category_id`),`root_category`=VALUES(`root_category`),`name`=VALUES(`name`),`slug`=VALUES(`slug`),`sku`=VALUES(`sku`),`short_description`=VALUES(`short_description`),`description_html`=VALUES(`description_html`),`image`=VALUES(`image`),`unit`=VALUES(`unit`),`price`=VALUES(`price`),`request_hint`=VALUES(`request_hint`),`active`=VALUES(`active`),`featured`=VALUES(`featured`),`sort_order`=VALUES(`sort_order`),`seo_title`=VALUES(`seo_title`),`seo_description`=VALUES(`seo_description`),`source_file`=VALUES(`source_file`),`specs_json`=VALUES(`specs_json`),`gallery_json`=VALUES(`gallery_json`),`old_urls_json`=VALUES(`old_urls_json`);
INSERT INTO `products` (`id`,`category_id`,`root_category`,`name`,`slug`,`sku`,`short_description`,`description_html`,`image`,`unit`,`price`,`request_hint`,`active`,`featured`,`sort_order`,`seo_title`,`seo_description`,`source_file`,`specs_json`,`gallery_json`,`old_urls_json`) VALUES (944,28,'transformers','Сухие трансформаторы ТС, ТСЗ с изоляцией "Номекс" класса напряжения 10 кВ','954-sukhie-transformatory-ts-tsz-s-izolyatsiej-nomeks-klassa-napryazheniya-10-kv','MNP-0944','Трансформаторы силовые сухие трехфазные с изоляцией "Номекс" серии ТС (без кожуха), ТСЗ (с кожухом) напряжением до 10 кВ предназначены для преобразования электроэнергии у потребителей переменного тока с номинальной частотой 50 Гц. Номинальное.','<div><h4>Сухие трансформаторы ТС, ТСЗ с изоляцией "Номекс" класса напряжения 10 кВ </h4><p><img alt="b 111" loading="lazy" src="assets/img/products/b_111__3348429ef3960a78adf401d3.jpg"/><img alt="b 130" loading="lazy" src="assets/img/products/b_130__836a97f06604ccd5233d0d6e.jpg"/></p>Сухие трансформаторы ТС, ТСЗ: ТС-25, ТС-40, ТС-63, ТС-100; ТСЗ-25 ТСЗ-40 ТСЗ-63 ТСЗ-100 <table><tbody><tr><td><strong>ТУ РБ 100211261.037-2005 </strong></td><td></td><td></td></tr></tbody></table><p><strong>Трансформаторы силовые сухие трехфазные </strong>с изоляцией <strong>"Номекс" </strong>серии <strong>ТС </strong>(без кожуха), <strong>ТСЗ </strong>(с кожухом) напряжением до 10 кВ предназначены для преобразования электроэнергии у потребителей переменного тока с номинальной частотой 50 Гц. Номинальное напряжение ВН - 6 или 10 кВ, обмотки НН - 0,4 кВ. </p><p>Схема и группа соединения обмоток - У/Ун-0, Д/Ун-11. </p><p><strong>Сухие трансформаторы ТС и ТСЗ </strong>предназначены для работы в помещениях в условиях умеренного климата при температуре окружающего воздуха от плюс 40 до ми нус 45 <sup>о </sup>С, влажностью до 80 % при температуре 25 оС. Окружающая среда невзрывоопасная, не содержащая пыли в концентрациях, снижающих параметры изделий в недопустимых пределах. </p><p><strong>Сухие трансформаторы </strong><strong>ТС и ТСЗ </strong>не предназначены для работы в условиях тряски, вибрации, ударов, в химически активной среде. Высота установки над уровнем моря не более 1000 м. </p><p>Класс нагревостойкости обмотки низшего напряжения - Н, высшего - F. Регулирование напряжения до ±5 % ступенями по 2,5 % осуществляется на полностью отключенном трансформаторе (ПБВ) путем перестановки перемычки. Степень защиты трансформаторов ТС - IP00, ТСЗ - IP21. </p><p><strong>Сухие трансформаторы </strong><strong>ТС и ТСЗ </strong>предназначены для установки в промышленных помещениях и общественных зданиях, к которым предъявляются повышенные требования в части пожаробезопасности и экологической чистоты. <br/></p></div>','assets/img/products/b_111__3348429ef3960a78adf401d3.jpg','шт.',NULL,'Укажите мощность, напряжение, исполнение и комплектацию. Приложите опросный лист или проект.',1,0,944,'Сухие трансформаторы ТС, ТСЗ с изоляцией "Номекс" класса напряжения 10 кВ — купить по заявке | Монополия','Сухие трансформаторы ТС, ТСЗ с изоляцией "Номекс" класса напряжения 10 кВ: подбор и поставка в Санкт-Петербурге. Укажите мощность, напряжение, исполнение и комплектацию. Приложите опросный лист или проект. Расчет стоимости — по заявке.','site/www.monopoly-torg.ru/954-sukhie-transformatory-ts-tsz-s-izolyatsiej-n__c612801bc0effe418a96f18e.html','[]','["assets/img/products/b_111__3348429ef3960a78adf401d3.jpg", "assets/img/products/b_130__836a97f06604ccd5233d0d6e.jpg"]','["http://www.monopoly-torg.ru/index.php/transformatornye-podstantsii/silovye-transformatory/954-sukhie-transformatory-ts-tsz-s-izolyatsiej-nomeks-klassa-napryazheniya-10-kv"]') ON DUPLICATE KEY UPDATE `category_id`=VALUES(`category_id`),`root_category`=VALUES(`root_category`),`name`=VALUES(`name`),`slug`=VALUES(`slug`),`sku`=VALUES(`sku`),`short_description`=VALUES(`short_description`),`description_html`=VALUES(`description_html`),`image`=VALUES(`image`),`unit`=VALUES(`unit`),`price`=VALUES(`price`),`request_hint`=VALUES(`request_hint`),`active`=VALUES(`active`),`featured`=VALUES(`featured`),`sort_order`=VALUES(`sort_order`),`seo_title`=VALUES(`seo_title`),`seo_description`=VALUES(`seo_description`),`source_file`=VALUES(`source_file`),`specs_json`=VALUES(`specs_json`),`gallery_json`=VALUES(`gallery_json`),`old_urls_json`=VALUES(`old_urls_json`);
INSERT INTO `products` (`id`,`category_id`,`root_category`,`name`,`slug`,`sku`,`short_description`,`description_html`,`image`,`unit`,`price`,`request_hint`,`active`,`featured`,`sort_order`,`seo_title`,`seo_description`,`source_file`,`specs_json`,`gallery_json`,`old_urls_json`) VALUES (945,29,'transformers','КОМПЛЕКТНЫЕ ТРАНСФОРМАТОРНЫЕ ПОДСТАНЦИИ КТП (для электроснабжения с/х потребителей; небольших объектов)','955-komplektnye-transformatornye-podstantsii-ktp-dlya-elektrosnabzheniya-s-kh-potrebitelej-nebolshikh-ob-ektov','MNP-0945','Комплектные трансформаторные подстанции (КТП) представляют собой однотрансформаторные подстанции тупикового типа наружной установки. КТП служат для приема электрической энергии переменного тока напряжением 6 (10) или 35 кВ, преобразования ее в.','<div><h4>КОМПЛЕКТНЫЕ ТРАНСФОРМАТОРНЫЕ ПОДСТАНЦИИ КТП (для электроснабжения с/х потребителей; небольших объектов) </h4><p><strong>Комплектные трансформаторные подстанции (КТП) </strong>представляют собой однотрансформаторные подстанции тупикового типа наружной установки. КТП служат для приема электрической энергии переменного тока напряжением 6 (10) или 35 кВ, преобразования ее в электроэнергию напряжением 0,4 (0,23) кВ для потребителей в районах с умеренным климатом (от минус 45 <sup>o </sup>С до +40 <sup>o </sup>С). </p><p>КТП предназначены для электроснабжения сельскохозяйственных потребителей (в т.ч. фермерских хозяйств, садово-огороднических участков), отдельных населенных пунктов и небольших объектов, относящихся к III категории по надежности электроснабжения. </p><ul><li><div>Высоковольтный ввод в КТП - воздушный. </div></li><li><div>КТП подключается к ЛЭП посредством разъединителя, который поставляется комплектно с подстанцией (устанавливается на ближайшей опоре). </div></li><li><div>КТП обеспечивают учет активной электрической энергии. По требованию заказчика возможна установка счетчика реактивной энергии, а также счетчика любой модификации (совмещенного, электронного и т. д.). </div></li><li><div>Для создания нормальных условий работы индукционного счетчика предусмотрен обогрев. </div></li><li><div>В КТП имеется фидер уличного освещения, который оснащен устройством ручного (автоматического) включения и отключения. Возможно исполнение КТП без фидера уличного освещения (по требованию заказчика). </div></li><li><div>В КТП предусматриваются следующие виды защит: <br/>- от атмосферных перенапряжений; <br/>- от междуфазных коротких замыканий; <br/>- от перегрузки и коротких замыканий линий 0,4 кВ; <br/>- от коротких замыканий цепей обогрева и цепей освещения КТП. </div></li><li><div>КТП имеют электрические и механические блокировки, обеспечивающие безопасную работу обслуживающего персонала. </div></li><li><div>КТП: <br/>- безопасны для окружающей среды; <br/>- конструкция способствует быстрому монтажу и пуску на месте эксплуатации, а также быстрому демонтажу при изменении места установки; <br/>- имеют резиновые уплотнения на дверях; <br/>- имеют привлекательный эстетический вид; <br/>- комплектуются современными масляными трансформаторами герметичного исполнения серии ТМГ производства <strong>Минского Электротехнического завода им. В.И. Козлова </strong><br/></div></li></ul></div>','assets/img/product-placeholder.svg','шт.',NULL,'Укажите мощность, напряжение, исполнение и комплектацию. Приложите опросный лист или проект.',1,0,945,'КОМПЛЕКТНЫЕ ТРАНСФОРМАТОРНЫЕ ПОДСТАНЦИИ КТП (для электроснабжения с/х потребителей; небольших объектов) — купить по заявке | Монополия','КОМПЛЕКТНЫЕ ТРАНСФОРМАТОРНЫЕ ПОДСТАНЦИИ КТП (для электроснабжения с/х потребителей; небольших объектов): подбор и поставка в Санкт-Петербурге. Укажите мощность, напряжение, исполнение и комплектацию. Приложите опросный лист или проект. Расчет стоимости — по заявке.','site/www.monopoly-torg.ru/955-komplektnye-transformatornye-podstantsii-ktp__35d25340018bd111d64a2bad.html','[]','[]','["http://www.monopoly-torg.ru/index.php/transformatornye-podstantsii/transformatornye-podstantsii/955-komplektnye-transformatornye-podstantsii-ktp-dlya-elektrosnabzheniya-s-kh-potrebitelej-nebolshikh-ob-ektov"]') ON DUPLICATE KEY UPDATE `category_id`=VALUES(`category_id`),`root_category`=VALUES(`root_category`),`name`=VALUES(`name`),`slug`=VALUES(`slug`),`sku`=VALUES(`sku`),`short_description`=VALUES(`short_description`),`description_html`=VALUES(`description_html`),`image`=VALUES(`image`),`unit`=VALUES(`unit`),`price`=VALUES(`price`),`request_hint`=VALUES(`request_hint`),`active`=VALUES(`active`),`featured`=VALUES(`featured`),`sort_order`=VALUES(`sort_order`),`seo_title`=VALUES(`seo_title`),`seo_description`=VALUES(`seo_description`),`source_file`=VALUES(`source_file`),`specs_json`=VALUES(`specs_json`),`gallery_json`=VALUES(`gallery_json`),`old_urls_json`=VALUES(`old_urls_json`);
INSERT INTO `products` (`id`,`category_id`,`root_category`,`name`,`slug`,`sku`,`short_description`,`description_html`,`image`,`unit`,`price`,`request_hint`,`active`,`featured`,`sort_order`,`seo_title`,`seo_description`,`source_file`,`specs_json`,`gallery_json`,`old_urls_json`) VALUES (946,29,'transformers','Подстанции КТП 25 - 250 кВА шкафного типа (сельхозки): КТП-02, КТП-04 и КТПР','956-podstantsii-ktp-25-250-kva-shkafnogo-tipa-selkhozki-ktp-02-ktp-04-i-ktpr','MNP-0946','Подстанции КТП: КТП 25, КТП 40, КТП 63, КТП 100, КТП 160, КТП 250.','<div><h4>Подстанции КТП 25 - 250 кВА шкафного типа (сельхозки): КТП-02, КТП-04 и КТПР </h4><p><img alt="b 114" loading="lazy" src="assets/img/products/b_114__9adbd2d317dfd8754c7a334d.jpg"/><img alt="b 87" loading="lazy" src="assets/img/products/b_87__e8fb5da974a8a7ade878b48b.jpg"/></p>Комплектные трансформаторные подстанции КТП мощностью 25 - 250 кВА, напряжением 6(10) кВ шкафного типа: КТП-02, КТП-04 и КТПР <table><tbody><tr><td><em><strong>ТУ РБ 100211261.024-2003 </strong></em></td><td></td><td></td></tr></tbody></table><p><strong>Подстанции КТП: КТП 25, КТП 40, КТП 63, КТП 100, КТП 160, КТП 250. </strong></p><p><strong>Комплектные трансформаторные подстанции КТП </strong>- это однотрансформаторные <strong>подстанции тупикового типа наружной установки </strong>. КТП служат для приема электроэнергии переменного тока напряжением 6(10) или 35 кВ, преобразования ее в электрическую энергию напряжением 0,4 (0,23) кВ для потребителей в районах с умеренным климатом (от минус 45 <sup>o </sup>С до +40 <sup>o </sup>С). </p><p><strong>КТП </strong>предназначены для электроснабжения сельскохозяйственных потребителей (в т.ч. фермерских хозяйств, садово-огороднических участков), отдельных населенных пунктов и небольших объектов, относящихся к III категории по надежности электроснабжения. </p><ul><li><div>Высоковольтный ввод в <strong>КТП </strong>- воздушный. </div></li><li><div>КТП подключается к ЛЭП посредством разъединителя, который поставляется комплектно с подстанцией (устанавливается на ближайшей опоре). </div></li><li><div><strong>КТП </strong>обеспечивают учет активной электрической энергии. По требованию заказчика возможна установка счетчика реактивной энергии, а также счетчика любой модификации (совмещенного, электронного и т. д.). </div></li><li><div>Для создания нормальных условий работы индукционного счетчика предусмотрен обогрев. </div></li><li><div>В <strong>КТП </strong>имеется фидер уличного освещения, который оснащен устройством ручного (автоматического) включения и отключения. Возможно исполнение <strong>КТП </strong>без фидера уличного освещения (по требованию заказчика). </div></li><li><div>В <strong>КТП </strong>предусматриваются следующие виды защит: <br/>- от атмосферных перенапряжений; <br/>- от междуфазных коротких замыканий; <br/>- от перегрузки и коротких замыканий линий 0,4 кВ; <br/>- от коротких замыканий цепей обогрева и цепей освещения КТП. </div></li><li><div><strong>КТП </strong>имеют электрические и механические блокировки, обеспечивающие безопасную работу обслуживающего персонала. </div></li><li><div>достоинства КТП: <br/>- безопасны для окружающей среды; <br/>- конструкция способствует быстрому монтажу и пуску на месте эксплуатации, а также быстрому демонтажу при изменении места установки; <br/>- имеют резиновые уплотнения на дверях; <br/>- имеют привлекательный эстетический вид; <br/>- комплектуются современными масляными герметичными трансформаторами серии ТМГ <strong>производства МЭТЗ им. В.И. Козлова. </strong></div></li></ul>Особенности КТП -02, КТП -04 и КТПР мощностью 25 - 250 кВА, напряжением 6(10) кВ шкафного типа <ul><li>Выводы отходящих линий: <br/>- КТП -02 - воздушные (за исключением линии № 4, присоединение к которой осуществляется только кабелем), <br/>- КТП -04 - кабельные, <br/>- КТПР - воздушные. </li><li>На отходящих фидерах 0,4 кВ устанавливаются: <br/>- КТП -02, КТП -04 - автоматические выключатели, <br/>- КТПР - блоки рубильник-предохранитель. </li><li>Комплектно с КТП, КТПР поставляется площадка обслуживания шкафа РУНН (при её заказе). </li></ul>Номенклатура подстанций КТП шкафного типа: <table><tbody><tr><td><strong>КТП-25 </strong>(c РВО) <br/><strong>КТП-40 </strong>(c РВО) <br/><strong>КТП-63 </strong>(c РВО) <br/><strong>КТП-100 </strong>(c РВО) <br/><strong>КТП-160 </strong>(c РВО) <br/><strong>КТП-250 </strong>(c РВО) <br/>КТП-25 без РВО <br/>КТП-40 без РВО <br/>КТП-63 без РВО <br/>КТП-100 без РВО <br/>КТП-160 без РВО <br/>КТП-250 без РВО </td><td><strong>КТП </strong>В/К- <strong>25 </strong>/6-10 с РВО <br/><strong>КТП </strong>В/К- <strong>40 </strong>/6-10 с РВО <br/><strong>КТП </strong>В/К- <strong>63 </strong>/6-10 с РВО <br/><strong>КТП </strong>В/К- <strong>100 </strong>/6-10 с РВО <br/><strong>КТП </strong>В/К- <strong>160 </strong>/6-10 с РВО <br/><strong>КТП </strong>В/К- <strong>250 </strong>/6-10 с РВО <br/>КТП В/К- 25 /6-10 без РВО <br/>КТП В/К- 40 /6-10 без РВО <br/>КТП В/К- 63 /6-10 без РВО <br/>КТП В/К- 100 /6-10 без РВО <br/>КТП В/К- 160 /6-10 без РВО <br/>КТП В/К- 250 /6-10 без РВО </td></tr></tbody></table></div>','assets/img/products/b_114__9adbd2d317dfd8754c7a334d.jpg','шт.',NULL,'Укажите мощность, напряжение, исполнение и комплектацию. Приложите опросный лист или проект.',1,0,946,'Подстанции КТП 25 - 250 кВА шкафного типа (сельхозки): КТП-02, КТП-04 и КТПР — купить по заявке | Монополия','Подстанции КТП 25 - 250 кВА шкафного типа (сельхозки): КТП-02, КТП-04 и КТПР: подбор и поставка в Санкт-Петербурге. Укажите мощность, напряжение, исполнение и комплектацию. Приложите опросный лист или проект. Расчет стоимости — по заявке.','site/www.monopoly-torg.ru/956-podstantsii-ktp-25-250-kva-shkafnogo-tipa-se__e511b6ffd1657e9dee3ae629.html','[]','["assets/img/products/b_114__9adbd2d317dfd8754c7a334d.jpg", "assets/img/products/b_87__e8fb5da974a8a7ade878b48b.jpg"]','["http://www.monopoly-torg.ru/index.php/transformatornye-podstantsii/transformatornye-podstantsii/956-podstantsii-ktp-25-250-kva-shkafnogo-tipa-selkhozki-ktp-02-ktp-04-i-ktpr"]') ON DUPLICATE KEY UPDATE `category_id`=VALUES(`category_id`),`root_category`=VALUES(`root_category`),`name`=VALUES(`name`),`slug`=VALUES(`slug`),`sku`=VALUES(`sku`),`short_description`=VALUES(`short_description`),`description_html`=VALUES(`description_html`),`image`=VALUES(`image`),`unit`=VALUES(`unit`),`price`=VALUES(`price`),`request_hint`=VALUES(`request_hint`),`active`=VALUES(`active`),`featured`=VALUES(`featured`),`sort_order`=VALUES(`sort_order`),`seo_title`=VALUES(`seo_title`),`seo_description`=VALUES(`seo_description`),`source_file`=VALUES(`source_file`),`specs_json`=VALUES(`specs_json`),`gallery_json`=VALUES(`gallery_json`),`old_urls_json`=VALUES(`old_urls_json`);
INSERT INTO `products` (`id`,`category_id`,`root_category`,`name`,`slug`,`sku`,`short_description`,`description_html`,`image`,`unit`,`price`,`request_hint`,`active`,`featured`,`sort_order`,`seo_title`,`seo_description`,`source_file`,`specs_json`,`gallery_json`,`old_urls_json`) VALUES (947,29,'transformers','МТП (СТП) 25-100 кВА мачтовая','957-mtp-stp-25-100-kva-machtovaya','MNP-0947','Мачтовые подстанции МТП: МТП-25, МТП-40, МТП-63, МТП-100.','<div><h4>МТП (СТП) 25-100 кВА мачтовая </h4><p><img alt="b 133" loading="lazy" src="assets/img/products/b_133__0e49458c738df88fd58d4a54.jpg"/></p>Мачтовая трансформаторная подстанция МТП (СТП) мощностью 25-100 кВА напряжением 6 (10) кВ <table><tbody><tr><td><em><strong>ТУ РБ 100211261.024-2003 </strong></em></td><td></td><td></td></tr></tbody></table><p><strong>Мачтовые подстанции МТП: МТП-25, МТП-40, МТП-63, МТП-100. </strong></p><p>Особенности <strong>МТП (СТП) </strong>: </p><ul><li>Размещение шкафа РУНН в <strong>МТП (СТП) </strong>и высоковольтного оборудования производится в соответствии с типовыми проектами. </li><li>Комплектно с <strong>МТП (СТП) </strong>поставляется разъединитель, силовой трансформатор, высоковольтные разрядники и предохранители. </li><li>Выводы отходящих линий НН - воздушные; по требованию заказчика - кабельные. </li></ul></div>','assets/img/products/b_133__0e49458c738df88fd58d4a54.jpg','шт.',NULL,'Укажите мощность, напряжение, исполнение и комплектацию. Приложите опросный лист или проект.',1,0,947,'МТП (СТП) 25-100 кВА мачтовая — купить по заявке | Монополия','МТП (СТП) 25-100 кВА мачтовая: подбор и поставка в Санкт-Петербурге. Укажите мощность, напряжение, исполнение и комплектацию. Приложите опросный лист или проект. Расчет стоимости — по заявке.','site/www.monopoly-torg.ru/957-mtp-stp-25-100-kva-machtovaya__05f5e81924c04ca22fbc2c25.html','[]','["assets/img/products/b_133__0e49458c738df88fd58d4a54.jpg"]','["http://www.monopoly-torg.ru/index.php/transformatornye-podstantsii/transformatornye-podstantsii/957-mtp-stp-25-100-kva-machtovaya"]') ON DUPLICATE KEY UPDATE `category_id`=VALUES(`category_id`),`root_category`=VALUES(`root_category`),`name`=VALUES(`name`),`slug`=VALUES(`slug`),`sku`=VALUES(`sku`),`short_description`=VALUES(`short_description`),`description_html`=VALUES(`description_html`),`image`=VALUES(`image`),`unit`=VALUES(`unit`),`price`=VALUES(`price`),`request_hint`=VALUES(`request_hint`),`active`=VALUES(`active`),`featured`=VALUES(`featured`),`sort_order`=VALUES(`sort_order`),`seo_title`=VALUES(`seo_title`),`seo_description`=VALUES(`seo_description`),`source_file`=VALUES(`source_file`),`specs_json`=VALUES(`specs_json`),`gallery_json`=VALUES(`gallery_json`),`old_urls_json`=VALUES(`old_urls_json`);
INSERT INTO `products` (`id`,`category_id`,`root_category`,`name`,`slug`,`sku`,`short_description`,`description_html`,`image`,`unit`,`price`,`request_hint`,`active`,`featured`,`sort_order`,`seo_title`,`seo_description`,`source_file`,`specs_json`,`gallery_json`,`old_urls_json`) VALUES (948,29,'transformers','МТП (СТП) 160, 250 кВА мачтовая','958-mtp-stp-160-250-kva-machtovaya','MNP-0948','МТП (СТП) 160, 250 кВА мачтовая для промышленных, строительных и энергетических объектов.','<div><h4>МТП (СТП) 160, 250 кВА мачтовая </h4><p><img alt="b 134" loading="lazy" src="assets/img/products/b_134__c95c8b07687b6121af3fa06f.jpg"/></p>Мачтовая трансформаторная подстанция МТП (СТП) мощностью 160, 250 кВА напряжением 6 (10) кВ <table><tbody><tr><td><em><strong>ТУ РБ 100211261.024-2003 </strong></em></td><td></td><td></td></tr></tbody></table><p><strong>Мачтовые подстанции МТП: МТП-160, МТП-250. </strong></p><p>Особенностями данных <strong>МТП (СТП) </strong>являются: </p><ul><li>Выводы отходящих линий НН - воздушные; по требованию заказчика - кабельные; </li><li>Установка <strong>мачтовой подстанции МТП (СТП) </strong>, мотаж и подключение к сети осуществляется в соответствии с действующими типовыми проектами; </li><li>В конструкции <strong>МТП (СТП) </strong>предусмотрена возможность установки индукционного или электронного счётчика активной энергии на вводе 0,4 кВ; </li><li>Степень защиты оболочки шкафа РУНН - IP34; </li><li>Цепи ВН в <strong>МТП (СТП) </strong>устойчивы к токам короткого замыкания 10 кА в течение 3с. </li></ul></div>','assets/img/products/b_134__c95c8b07687b6121af3fa06f.jpg','шт.',NULL,'Укажите мощность, напряжение, исполнение и комплектацию. Приложите опросный лист или проект.',1,0,948,'МТП (СТП) 160, 250 кВА мачтовая — купить по заявке | Монополия','МТП (СТП) 160, 250 кВА мачтовая: подбор и поставка в Санкт-Петербурге. Укажите мощность, напряжение, исполнение и комплектацию. Приложите опросный лист или проект. Расчет стоимости — по заявке.','site/www.monopoly-torg.ru/958-mtp-stp-160-250-kva-machtovaya__d30628e4b1827a923c2d21a5.html','[]','["assets/img/products/b_134__c95c8b07687b6121af3fa06f.jpg"]','["http://www.monopoly-torg.ru/index.php/transformatornye-podstantsii/transformatornye-podstantsii/958-mtp-stp-160-250-kva-machtovaya"]') ON DUPLICATE KEY UPDATE `category_id`=VALUES(`category_id`),`root_category`=VALUES(`root_category`),`name`=VALUES(`name`),`slug`=VALUES(`slug`),`sku`=VALUES(`sku`),`short_description`=VALUES(`short_description`),`description_html`=VALUES(`description_html`),`image`=VALUES(`image`),`unit`=VALUES(`unit`),`price`=VALUES(`price`),`request_hint`=VALUES(`request_hint`),`active`=VALUES(`active`),`featured`=VALUES(`featured`),`sort_order`=VALUES(`sort_order`),`seo_title`=VALUES(`seo_title`),`seo_description`=VALUES(`seo_description`),`source_file`=VALUES(`source_file`),`specs_json`=VALUES(`specs_json`),`gallery_json`=VALUES(`gallery_json`),`old_urls_json`=VALUES(`old_urls_json`);
INSERT INTO `products` (`id`,`category_id`,`root_category`,`name`,`slug`,`sku`,`short_description`,`description_html`,`image`,`unit`,`price`,`request_hint`,`active`,`featured`,`sort_order`,`seo_title`,`seo_description`,`source_file`,`specs_json`,`gallery_json`,`old_urls_json`) VALUES (949,29,'transformers','МТПО (СТПО) 4 и 10 кВА мачтовая однофазная','959-mtpo-stpo-4-i-10-kva-machtovaya-odnofaznaya','MNP-0949','МТПО (СТПО) 4 и 10 кВА мачтовая однофазная для промышленных, строительных и энергетических объектов.','<div><h4>МТПО (СТПО) 4 и 10 кВА мачтовая однофазная </h4><p><img alt="b 95" loading="lazy" src="assets/img/products/b_95__efcf77a48db45e463669995b.jpg"/></p>Мачтовая трансформаторная подстанция однофазная МТПО (СТПО) мощностью 4 и 10 кВА, напряжением 6 (10) кВ <table><tbody><tr><td><em><strong>ТУ РБ 100211261.024-2003 </strong></em></td><td></td><td></td></tr></tbody></table><p>Особенности <strong>МТПО (СТПО) </strong>: </p><ul><li>служит для приема электрической энергии однофазного переменного тока; </li><li>размещение шкафа РУНН и высоковольтного оборудования (предохранителей, разрядников и силового трансформатора) производится в соответствии с типовыми проектами; </li><li>комплектно с <strong>МТПО (СТПО) </strong>поставляются металлоконструкции для установки шкафа РУНН, силового трансформатора, высоковольтных вентильных разрядников и высоковольтных предохранителей. </li></ul></div>','assets/img/products/b_95__efcf77a48db45e463669995b.jpg','шт.',NULL,'Укажите мощность, напряжение, исполнение и комплектацию. Приложите опросный лист или проект.',1,0,949,'МТПО (СТПО) 4 и 10 кВА мачтовая однофазная — купить по заявке | Монополия','МТПО (СТПО) 4 и 10 кВА мачтовая однофазная: подбор и поставка в Санкт-Петербурге. Укажите мощность, напряжение, исполнение и комплектацию. Приложите опросный лист или проект. Расчет стоимости — по заявке.','site/www.monopoly-torg.ru/959-mtpo-stpo-4-i-10-kva-machtovaya-odnofaznaya__d4289b4dc37637a4ab77a515.html','[]','["assets/img/products/b_95__efcf77a48db45e463669995b.jpg"]','["http://www.monopoly-torg.ru/index.php/transformatornye-podstantsii/transformatornye-podstantsii/959-mtpo-stpo-4-i-10-kva-machtovaya-odnofaznaya"]') ON DUPLICATE KEY UPDATE `category_id`=VALUES(`category_id`),`root_category`=VALUES(`root_category`),`name`=VALUES(`name`),`slug`=VALUES(`slug`),`sku`=VALUES(`sku`),`short_description`=VALUES(`short_description`),`description_html`=VALUES(`description_html`),`image`=VALUES(`image`),`unit`=VALUES(`unit`),`price`=VALUES(`price`),`request_hint`=VALUES(`request_hint`),`active`=VALUES(`active`),`featured`=VALUES(`featured`),`sort_order`=VALUES(`sort_order`),`seo_title`=VALUES(`seo_title`),`seo_description`=VALUES(`seo_description`),`source_file`=VALUES(`source_file`),`specs_json`=VALUES(`specs_json`),`gallery_json`=VALUES(`gallery_json`),`old_urls_json`=VALUES(`old_urls_json`);
INSERT INTO `products` (`id`,`category_id`,`root_category`,`name`,`slug`,`sku`,`short_description`,`description_html`,`image`,`unit`,`price`,`request_hint`,`active`,`featured`,`sort_order`,`seo_title`,`seo_description`,`source_file`,`specs_json`,`gallery_json`,`old_urls_json`) VALUES (950,29,'transformers','Подстанция КТПТО-80 для прогрева бетона','960-podstantsiya-ktpto-80-dlya-progreva-betona','MNP-0950','Подстанция КТПТО-80 наружной установки предназначена для электро- прогрева бетона и других способов термообработки бетона и замерзшего грунта','<div><h4>Подстанция КТПТО-80 для прогрева бетона </h4><p><img alt="b 30" loading="lazy" src="assets/img/products/b_30__7ab8fb2494cdfbbcf6acf5dc.jpg"/><img alt="b 155" loading="lazy" src="assets/img/products/b_155__b817f292f625c51978e41f6c.jpg"/><img alt="b 129" loading="lazy" src="assets/img/products/b_129__7e6c98943369d5aacb5cefc6.jpg"/></p>Комплектная трансформаторная подстанция КТПТО-80 (с трансформатором ТМТО-80/0,38) мощностью 80 кВА, напряжением 380/55-95 В <table><tbody><tr><td><em><strong>ТУ16-674.090-87 </strong></em></td><td></td><td></td></tr></tbody></table><p><strong>Подстанция КТПТО-80 наружной установки </strong>предназначена для электро- <strong>прогрева бетона </strong>и других способов термообработки бетона и замерзшего грунта </p><ul><li>с автоматическим регулированием температуры ( <strong>КТПТО-80 -07 </strong>), </li><li>с ручным регулированием температуры ( <strong>КТПТО-80 -02 </strong>), </li><li>с уменьшенными габаритными размерами и массой( <strong>КТПТО-80-11 </strong>) </li></ul><p>а также <strong>для питания временного освещения и ручного трехфазного электроинструмента </strong>на напряжение 42 В (в условиях строительных площадок). Нормальная работа и <strong>прогрев бетона </strong>с помошью <strong>подстанции КТПТО-80 </strong>обеспечивается при температуре окружающего воздуха от минус 40 <sup>o </sup>С до +10 <sup>o </sup>С. <strong>Подстанция КТПТО-80 </strong>оснащается трехфазным трехобмоточным трансформатором ТМТО-80/0,38 с естественным охлаждением. В КТПТО-80 имеются блокировки, обеспечивающие безопасность работ обслуживающего персонала, осуществляющего <strong>прогрев бетона </strong>. </p><p><br/>Блокировки исключают возможность: </p><ul><li><div>переключения ступеней регулирования напряжения силового трансформатора ТМТО-80 под напряжением; </div></li><li><div>открывания панели блока управления при включенном вводном автоматическом выключателе главной цепи. </div></li></ul><p>В <strong>КТПТО-80 </strong>предусмотрено питание стороннего потребителя на напряжение 380 В и ток 10 А, а также ручное (дистанционное и автоматическое) управление работой силового трансформатора. </p><p>В дистанционном режиме управление осуществляется кнопочным постом, который выносится за пределы зоны электро- <strong>прогрева бетона </strong>. </p><p>На УП «МЭТЗ им. В.И. Козлова» освоено серийное производство <strong>комплектной трансформаторной подстанции наружной установки КТПТО-80-11. </strong><strong>Подстанция КТПТО-80-11 отличается от старой КТПТО-80-07 уменьшенными габаритными размерами и массой при одинаковой стоимости </strong>. Считаем своевременным и целесообразным максимально широкое применение подстанции серии КТПТО-80-11 при проектировании, осуществлении реконструкции и строительстве новых объектов. В переходный период будет осуществляться выпуск старой и новой КТПТО. </p></div>','assets/img/products/b_30__7ab8fb2494cdfbbcf6acf5dc.jpg','шт.',NULL,'Укажите мощность, напряжение, исполнение и комплектацию. Приложите опросный лист или проект.',1,0,950,'Подстанция КТПТО-80 для прогрева бетона — купить по заявке | Монополия','Подстанция КТПТО-80 для прогрева бетона: подбор и поставка в Санкт-Петербурге. Укажите мощность, напряжение, исполнение и комплектацию. Приложите опросный лист или проект. Расчет стоимости — по заявке.','site/www.monopoly-torg.ru/960-podstantsiya-ktpto-80-dlya-progreva-betona__3dd054bafd335efc1bc7b461.html','[]','["assets/img/products/b_30__7ab8fb2494cdfbbcf6acf5dc.jpg", "assets/img/products/b_155__b817f292f625c51978e41f6c.jpg", "assets/img/products/b_129__7e6c98943369d5aacb5cefc6.jpg"]','["http://www.monopoly-torg.ru/index.php/transformatornye-podstantsii/transformatornye-podstantsii/960-podstantsiya-ktpto-80-dlya-progreva-betona"]') ON DUPLICATE KEY UPDATE `category_id`=VALUES(`category_id`),`root_category`=VALUES(`root_category`),`name`=VALUES(`name`),`slug`=VALUES(`slug`),`sku`=VALUES(`sku`),`short_description`=VALUES(`short_description`),`description_html`=VALUES(`description_html`),`image`=VALUES(`image`),`unit`=VALUES(`unit`),`price`=VALUES(`price`),`request_hint`=VALUES(`request_hint`),`active`=VALUES(`active`),`featured`=VALUES(`featured`),`sort_order`=VALUES(`sort_order`),`seo_title`=VALUES(`seo_title`),`seo_description`=VALUES(`seo_description`),`source_file`=VALUES(`source_file`),`specs_json`=VALUES(`specs_json`),`gallery_json`=VALUES(`gallery_json`),`old_urls_json`=VALUES(`old_urls_json`);
INSERT INTO `products` (`id`,`category_id`,`root_category`,`name`,`slug`,`sku`,`short_description`,`description_html`,`image`,`unit`,`price`,`request_hint`,`active`,`featured`,`sort_order`,`seo_title`,`seo_description`,`source_file`,`specs_json`,`gallery_json`,`old_urls_json`) VALUES (951,29,'transformers','КОМПЛЕКТНЫЕ ТРАНСФОРМАТОРНЫЕ ПОДСТАНЦИИ КТП киоскового типа (для электроснабжения промышленных обьектов)','961-komplektnye-transformatornye-podstantsii-ktp-kioskovogo-tipa-dlya-elektrosnabzheniya-promyshlennykh-obektov','MNP-0951','Комплектные трансформаторные подстанции (КТП) киоскового типа представляют собой одно- или двухтрансформаторные подстанции наружной установки и служат для приема электрической энергии трехфазного переменного тока частоты 50 Гц напряжением 6 или.','<div><h4>КОМПЛЕКТНЫЕ ТРАНСФОРМАТОРНЫЕ ПОДСТАНЦИИ КТП киоскового типа (для электроснабжения промышленных обьектов) </h4><p><strong>Комплектные трансформаторные подстанции (КТП) киоскового типа </strong>представляют собой <strong>одно- или двухтрансформаторные подстанции наружной установки </strong>и служат для приема электрической энергии трехфазного переменного тока частоты 50 Гц напряжением 6 или 10 кВ, транзита её (подстанции проходного типа), преобразования ее в электроэнергию напряжением 0,4 кВ и снабжения ею потребителей в районах с умеренным климатом (от минус 45 <sup>o </sup>С до + 40 <sup>o </sup>С). </p><p><strong>КТП киоскового типа </strong>предназначены для электроснабжения промышленных объектов и отдельных населенных пунктов. </p><p>Высоковольтный ввод <strong>в киосковую подстанцию КТП 6 (10) кВ </strong>- кабельный или воздушный; выводы отходящих линий 0,4 кВ - кабельные или воздушно-кабельные. </p><ul><li>На отходящих фидерах устанавливаются автоматические выключатели стационарного или выдвижного исполнения. </li><li>Конструктивно КТП выполняются в шкафном исполнении. Основные составные части соединяются болтовыми соединениями. </li><li>Конструкция <strong>подстанции КТП киоскового типа </strong>предусматривает ее установку на фундаменте, а также установку на бетонных блоках высотой 600 мм (в комплект поставки не входят). </li><li><strong>Подстанция КТП наружной установки с воздушным вводом </strong>подключается к ЛЭП посредством разъединителя, который поставляется комплектно с подстанцией и устанавливается на ближайшей опоре. </li><li>Подстанции обеспечивают <strong>учет </strong>активной электрической энергии. По требованию заказчика возможна установка счетчика реактивной энергии, а также счетчика любой модификации (совмещенного, электронного и т.д.). </li><li>Для создания нормальных условий эксплуатации <strong>КТП </strong>схемой предусмотрено внутреннее <strong>освещение </strong>и <strong>обогрев </strong>аппаратуры. Включение электронагревателей может производиться вручную или автоматически. </li><li>В <strong>КТП </strong>имеется фидер уличного освещения, который оснащен устройством ручного и автоматического включения и отключения. По требованию заказчика возможно исполнение <strong>КТП </strong>без фидера уличного освещения. </li><li>Схема <strong>подстанции КТП наружной установки </strong>предусматривает контроль тока и напряжения на стороне 0,4 кВ. </li><li>В КТП предусматриваются следующие <strong>виды защит </strong>: </li></ul><p>- от атмосферных перенапряжений (при наличии воздушных линий); </p><p>- от междуфазных коротких замыканий; </p><p>- от перегрузки силового трансформатора; </p><p>- от перегрузки и коротких замыканий линий 0,4 кВ; </p><p>- от коротких замыканий цепей обогрева, цепей освещения КТП; </p><p>- газовая защита трансформатора (в КТП-1000 кВА; в <strong>КТП-630 кВА </strong>-по требованию заказчика). </p><ul><li><strong>Киосковые подстанции КТП </strong>имеют <strong>полный комплект </strong>электрических и механических <strong>блокировок </strong>, обеспечивающих безопасную работу обслуживающего персонала. </li><li>Цепи ВН в <strong>КТП мощностью 63-630 кВА </strong>устойчивы (в течение 1с) к токам короткого замыкания: динамически - 16 кА, термически - 6,3 кА; цепи ВН в <strong>КТП 1000 кВА </strong>: динамически - 32 кА, термически -12,5 кА. </li><li>Cтепень защиты оболочки КТП IP 34 (IP 23 - для шкафа трансформатора). </li><li>Конструкция шкафа трансформатора и шкафа трансформаторного ввода обеспечивает локализацию воздействия открытой электрической цепи в пределах шкафа. </li><li><strong>Локализационная способность </strong>обеспечивается при токе к.з. 6,3 А, действующего в течение 1 с. </li><li>КТП: </li></ul><p>- безопасны для окружающей среды; </p><p>- конструкция способствует быстрому монтажу и пуску на месте эксплуатации, а также быстрому демонтажу при изменении мест установки; </p><p>- имеют резиновые уплотнения на дверях и на стыковых сборных соединениях; </p><p>- имеют привлекательный эстетический вид; </p><p>- комплектуются современными трансформаторами герметичного исполнения серии ТМГ производства <strong>Минского ЭТЗ им. В.И. Козлова </strong>. </p><p><em><strong>По требованию заказчика возможно изготовление КТП любого исполнения и комплектации, в т.ч. с вакуумными выключателями. </strong></em></p>Номенклатура подстанций КТП киоскового типа: <table><tbody><tr><td>КТП-ТАС К/К 100 /6-10/0,4-03У1 <br/>КТП-ТАС К/К 160 /6-10/0,4-03У1 <br/>КТП-ТАС К/К 250 /6-10/0,4-03У1 <br/><strong>КТП </strong>-ТАС К/К <strong>400 </strong>/6-10/0,4-03У1 <br/><strong>КТП </strong>ТАС М К/К <strong>630 </strong>/6-10/0,4-04У1 <br/><strong>КТП </strong>-ТАС К/К <strong>630 </strong>/6-10/0,4 <br/><strong>КТП </strong>ТАС К/К <strong>1000 / </strong>6-10/0,4 <p><strong>2КТП </strong>ТАС К/К <strong>63 </strong>/6-10/0,4-07У1 <br/><strong>2КТП </strong>ТАС К/К <strong>100 </strong>/6-10/0,4-07У1 <br/><strong>2КТП </strong>ТАС К/К <strong>160 </strong>/ 6-10/0,4-07У1 <br/><strong>2КТП </strong>ТАС К/К <strong>250 </strong>/6-10/0,4-07У1 <br/><strong>2КТП </strong>ТАС К/К <strong>630 </strong>/6-10/0,4 </p><p>КТП-ТАС К/ВК 63/6-10/0,4-03У1 <br/>КТП-ТАС К/ВК 100/6-10/0,4-03У1 <br/>КТП-ТАС К/ВК 160/6-10/0,4-03У1 <br/>КТП-ТАС К/ВК 250/6-10/0,4-03У1 <br/><strong>КТП </strong>-ТАС К/ВК <strong>400 </strong>/6-10/0,4-03У1 <br/>КТП-ТАС В/К 63/6-10/0,4-03У1 <br/>КТП-ТАС В/К 100/6-10/0,4-03У1 <br/>КТП-ТАС В/К 160/6-10/0,4-03У1 <br/>КТП-ТАС В/К 250/6-10/0,4-03У1 <br/><strong>КТП </strong>-ТАС В/К <strong>400 </strong>/6-10/0,4-03У1 <br/><strong>КТП </strong>ТАС М В/К <strong>630 </strong>/6-10/0,4-04У1 <br/><strong>КТП </strong>ТАС В/К <strong>630 </strong>/6-10/0,4-05У1 </p><p>2КТП ТАС В/К 63/6-10/0,4-07У1 <br/>2КТП ТАС В/К 100/6-10/0,4-07У1 <br/>2КТП ТАС В/К 160/6-10/0,4-07У1 <br/>2КТП ТАС В/К 250/6-10/0,4-07У1 </p><p>КТП-ТАС В/ВК 63/6-10/0,4-03У1 <br/>КТП-ТАС В/ВК 100/6-10/0,4-03У1 <br/>КТП-ТАС В/ВК 160/6-10/0,4-03У1 <br/>КТП-ТАС В/ВК 250/6-10/0,4-03У1 <br/><strong>КТП </strong>-ТАС В/ВК <strong>400 </strong>/6-10/0,4-03У1 <br/><strong>КТП </strong>-ТАС В/ВК <strong>630 </strong>/6-10/0,4 <br/><strong>КТП </strong>-ТАС В/ВК <strong>1000 </strong>/6-10/0,4 </p></td><td><p><strong>КТП </strong>ТАС М В/К <strong>63 </strong><br/>КТП ТАС М В/К 100 <br/>КТП ТАС М В/К 160 <br/>КТП ТАС М В/К 250 <br/><strong>КТП </strong>ТАС М В/В <strong>63 </strong><br/>КТП ТАС М В/В 100 <br/>КТП ТАС М В/В 160 <br/>КТП ТАС М В/В 250 </p><p>КТП ПАС К/К 63 <br/>КТП ПАС К/К 100 <br/>КТП ПАС К/К 160 <br/>КТП ПАС К/К 250 <br/><strong>КТП </strong>ПАС К/К <strong>400 </strong><br/><strong>КТП </strong>ПАС М К/К <strong>630 </strong><br/>КТП ПАС К/ВК 63 <br/>КТП ПАС К/ВК 100 <br/>КТП ПАС К/ВК 160 <br/>КТП ПАС К/ВК 250 <br/>КТП ПАС К/ВК 400 <br/>КТП ПАС В/К 63 <br/>КТП ПАС В/К 100 <br/>КТП ПАС В/К 160 <br/>КТП ПАС В/К 250 <br/><strong>КТП </strong>ПАС В/К <strong>400 </strong><br/><strong>КТП </strong>ПАС М В/К <strong>630 </strong><br/>КТП ПАС В/ВК 63 <br/>КТП ПАС В/ВК 100 <br/>КТП ПАС В/ВК 160 <br/>КТП ПАС В/ВК 250 <br/><strong>КТП </strong>ПАС В/ВК <strong>400 </strong></p><p>КТП-ТАС КУ К/К 63 <br/>КТП-ТАС КУ К/К 100 <br/>КТП-ТАС КУ К/К 160 <br/>КТП-ТАС КУ К/К 250 <br/><strong>КТП </strong>-ТАС КУ К/К <strong>400 </strong><br/>КТП-ТАС КУ В/К 63 <br/>КТП-ТАС КУ В/К 100 <br/>КТП-ТАС КУ В/К 160 <br/>КТП-ТАС КУ В/К 250 <br/><strong>КТП </strong>-ТАС КУ В/К <strong>400 </strong></p></td></tr></tbody></table></div>','assets/img/product-placeholder.svg','шт.',NULL,'Укажите мощность, напряжение, исполнение и комплектацию. Приложите опросный лист или проект.',1,0,951,'КОМПЛЕКТНЫЕ ТРАНСФОРМАТОРНЫЕ ПОДСТАНЦИИ КТП киоскового типа (для электроснабжения промышленных обьектов) — купить по заявке | Монополия','КОМПЛЕКТНЫЕ ТРАНСФОРМАТОРНЫЕ ПОДСТАНЦИИ КТП киоскового типа (для электроснабжения промышленных обьектов): подбор и поставка в Санкт-Петербурге. Укажите мощность, напряжение, исполнение и комплектацию. Приложите опросный лист или проект. Расчет стоимости — по заявке.','site/www.monopoly-torg.ru/961-komplektnye-transformatornye-podstantsii-ktp__54f0f2b4e1dbecce627c2246.html','[]','[]','["http://www.monopoly-torg.ru/index.php/transformatornye-podstantsii/transformatornye-podstantsii/961-komplektnye-transformatornye-podstantsii-ktp-kioskovogo-tipa-dlya-elektrosnabzheniya-promyshlennykh-obektov"]') ON DUPLICATE KEY UPDATE `category_id`=VALUES(`category_id`),`root_category`=VALUES(`root_category`),`name`=VALUES(`name`),`slug`=VALUES(`slug`),`sku`=VALUES(`sku`),`short_description`=VALUES(`short_description`),`description_html`=VALUES(`description_html`),`image`=VALUES(`image`),`unit`=VALUES(`unit`),`price`=VALUES(`price`),`request_hint`=VALUES(`request_hint`),`active`=VALUES(`active`),`featured`=VALUES(`featured`),`sort_order`=VALUES(`sort_order`),`seo_title`=VALUES(`seo_title`),`seo_description`=VALUES(`seo_description`),`source_file`=VALUES(`source_file`),`specs_json`=VALUES(`specs_json`),`gallery_json`=VALUES(`gallery_json`),`old_urls_json`=VALUES(`old_urls_json`);
INSERT INTO `products` (`id`,`category_id`,`root_category`,`name`,`slug`,`sku`,`short_description`,`description_html`,`image`,`unit`,`price`,`request_hint`,`active`,`featured`,`sort_order`,`seo_title`,`seo_description`,`source_file`,`specs_json`,`gallery_json`,`old_urls_json`) VALUES (952,29,'transformers','Подстанции КТП ПАС и КТП ТАС (проходные и тупиковые) 63 - 400 кВА','962-podstantsii-ktp-pas-i-ktp-tas-prokhodnye-i-tupikovye-63-400-kva','MNP-0952','Комплектные трансформаторные подстанции КТП ПАС и КТП ТАС (проходные и тупиковые) киоскового типа представляют собой однотрансформаторные подстанции наружной установки и служат для приема электрической энергии трехфазного переменного тока частоты.','<div><h4>Подстанции КТП ПАС и КТП ТАС (проходные и тупиковые) 63 - 400 кВА </h4><p><img alt="b 147" loading="lazy" src="assets/img/products/b_147__f998ad5eb748a4a70d73de88.jpg"/></p>Комплектные трансформаторные подстанции КТП ПАС и КТП ТАС (проходного и тупикового типа) мощностью 63 - 400 кВА напряжением 6 (10) кВ <table><tbody><tr><td><em><strong>ТУ РБ 100211261.029-2003 </strong></em></td><td></td><td></td></tr></tbody></table><p><strong>Комплектные трансформаторные подстанции КТП ПАС и КТП ТАС (проходные и тупиковые) киоскового типа </strong>представляют собой однотрансформаторные подстанции наружной установки и служат для приема электрической энергии трехфазного переменного тока частоты 50 Гц напряжением 6 или 10 кВ, её транзита (подстанции проходного типа) и преобразования ее в электроэнергию напряжением 0,4 кВ, а также электроснабжения и защиты потребителей населенных пунктов, промышленных и других объектов в районах с умеренным климатом (от -45 до + 40 градусов С). </p><p>Трансформаторные <strong>подстанции КТП ПАС и КТП ТАС (проходные и тупиковые) киоскового типа </strong>предназначены для электроснабжения промышленных объектов и отдельных населённых пунктов. </p><p>Высоковольтный ввод в <strong>подстанцию КТП ПАС и КТП ТАС </strong>- 6 (10) кВ - кабельный или воздушный; выводы отходящих линий - 0,4 кВ - кабельные или воздушно-кабельные. </p></div>','assets/img/products/b_147__f998ad5eb748a4a70d73de88.jpg','шт.',NULL,'Укажите мощность, напряжение, исполнение и комплектацию. Приложите опросный лист или проект.',1,0,952,'Подстанции КТП ПАС и КТП ТАС (проходные и тупиковые) 63 - 400 кВА — купить по заявке | Монополия','Подстанции КТП ПАС и КТП ТАС (проходные и тупиковые) 63 - 400 кВА: подбор и поставка в Санкт-Петербурге. Укажите мощность, напряжение, исполнение и комплектацию. Приложите опросный лист или проект. Расчет стоимости — по заявке.','site/www.monopoly-torg.ru/962-podstantsii-ktp-pas-i-ktp-tas-prokhodnye-i-t__64b7c16ed2fe1bbf4e9e7705.html','[]','["assets/img/products/b_147__f998ad5eb748a4a70d73de88.jpg"]','["http://www.monopoly-torg.ru/index.php/transformatornye-podstantsii/transformatornye-podstantsii/962-podstantsii-ktp-pas-i-ktp-tas-prokhodnye-i-tupikovye-63-400-kva"]') ON DUPLICATE KEY UPDATE `category_id`=VALUES(`category_id`),`root_category`=VALUES(`root_category`),`name`=VALUES(`name`),`slug`=VALUES(`slug`),`sku`=VALUES(`sku`),`short_description`=VALUES(`short_description`),`description_html`=VALUES(`description_html`),`image`=VALUES(`image`),`unit`=VALUES(`unit`),`price`=VALUES(`price`),`request_hint`=VALUES(`request_hint`),`active`=VALUES(`active`),`featured`=VALUES(`featured`),`sort_order`=VALUES(`sort_order`),`seo_title`=VALUES(`seo_title`),`seo_description`=VALUES(`seo_description`),`source_file`=VALUES(`source_file`),`specs_json`=VALUES(`specs_json`),`gallery_json`=VALUES(`gallery_json`),`old_urls_json`=VALUES(`old_urls_json`);
INSERT INTO `products` (`id`,`category_id`,`root_category`,`name`,`slug`,`sku`,`short_description`,`description_html`,`image`,`unit`,`price`,`request_hint`,`active`,`featured`,`sort_order`,`seo_title`,`seo_description`,`source_file`,`specs_json`,`gallery_json`,`old_urls_json`) VALUES (953,29,'transformers','Подстанция КТП ПАС-M и КТП ТАС-M (проходного и тупикового типа модернизированная) 630 кВА','963-podstantsiya-ktp-pas-m-i-ktp-tas-m-prokhodnogo-i-tupikovogo-tipa-modernizirovannaya-630-kva','MNP-0953','Подстанция КТП ПАС-M и КТП ТАС-M (проходного и тупикового типа модернизированная) 630 кВА для промышленных, строительных и энергетических объектов.','<div><h4>Подстанция КТП ПАС-M и КТП ТАС-M (проходного и тупикового типа модернизированная) 630 кВА </h4><p><img alt="b 32" loading="lazy" src="assets/img/products/b_32__eb8dd4f01baa19d646bd80ca.jpg"/></p>Комплектные трансформаторные подстанции КТП ПАС-M и КТП ТАС-M (проходного и тупикового типа модернизированные) мощностью 630 кВА напряжением 6 (10) кВ <table><tbody><tr><td><em><strong>ТУ РБ 100211261.029-2003 </strong></em></td><td></td><td></td></tr></tbody></table><p>Особенностью <strong>КТП ПАС-M </strong>и <strong>КТП ТАС-M 630 кВА </strong>является: </p><ul><li>Выводы отходящих линий - кабельные; </li><li>Максимальное количество отходящих линий - восемь; </li><li>Наличие защиты (УЗО) в цепях внутреннего освещения от поражения электрическим током людей при прикосновении к токоведущим частям электроприборов или нарушении их изоляции; </li><li>комплектация <strong>КТП ПАС-M </strong>и <strong>КТП ТАС-M 630 кВА </strong>счётчиками активной и реактивной энергии (по требованию заказчика возможна установка только активного счётчика). </li></ul></div>','assets/img/products/b_32__eb8dd4f01baa19d646bd80ca.jpg','шт.',NULL,'Укажите мощность, напряжение, исполнение и комплектацию. Приложите опросный лист или проект.',1,0,953,'Подстанция КТП ПАС-M и КТП ТАС-M (проходного и тупикового типа модернизированная) 630 кВА — купить по заявке | Монополия','Подстанция КТП ПАС-M и КТП ТАС-M (проходного и тупикового типа модернизированная) 630 кВА: подбор и поставка в Санкт-Петербурге. Укажите мощность, напряжение, исполнение и комплектацию. Приложите опросный лист или проект. Расчет стоимости — по заявке.','site/www.monopoly-torg.ru/963-podstantsiya-ktp-pas-m-i-ktp-tas-m-prokhodno__cb6c83dc2c359bf50114d1e8.html','[]','["assets/img/products/b_32__eb8dd4f01baa19d646bd80ca.jpg"]','["http://www.monopoly-torg.ru/index.php/transformatornye-podstantsii/transformatornye-podstantsii/963-podstantsiya-ktp-pas-m-i-ktp-tas-m-prokhodnogo-i-tupikovogo-tipa-modernizirovannaya-630-kva"]') ON DUPLICATE KEY UPDATE `category_id`=VALUES(`category_id`),`root_category`=VALUES(`root_category`),`name`=VALUES(`name`),`slug`=VALUES(`slug`),`sku`=VALUES(`sku`),`short_description`=VALUES(`short_description`),`description_html`=VALUES(`description_html`),`image`=VALUES(`image`),`unit`=VALUES(`unit`),`price`=VALUES(`price`),`request_hint`=VALUES(`request_hint`),`active`=VALUES(`active`),`featured`=VALUES(`featured`),`sort_order`=VALUES(`sort_order`),`seo_title`=VALUES(`seo_title`),`seo_description`=VALUES(`seo_description`),`source_file`=VALUES(`source_file`),`specs_json`=VALUES(`specs_json`),`gallery_json`=VALUES(`gallery_json`),`old_urls_json`=VALUES(`old_urls_json`);
