INSERT INTO `products` (`id`,`category_id`,`root_category`,`name`,`slug`,`sku`,`short_description`,`description_html`,`image`,`unit`,`price`,`request_hint`,`active`,`featured`,`sort_order`,`seo_title`,`seo_description`,`source_file`,`specs_json`,`gallery_json`,`old_urls_json`) VALUES (961,29,'transformers','МТПЖ (СТПЖ) мощностью 1,25 - 10 кВА напряжением 6 (10) кВ мачтовая','971-mtpzh-stpzh-moshchnostyu-1-25-10-kva-napryazheniem-6-10-kv-machtovaya','MNP-0961','Подстанция МТПЖ (СТПЖ) мощностью 1,25; 2,5; 4; 10 кВ . А служат для приёма электрической энергии напряжением 6 или 10 кВ, преобразования в электроэнергию напряжением 0,23 кВ и снабжения ею устройств сигнализации, центролизации, автоблокировки,.','<div><h4>МТПЖ (СТПЖ) мощностью 1,25 - 10 кВА напряжением 6 (10) кВ мачтовая </h4><p><img alt="b 99" loading="lazy" src="assets/img/products/b_99__bbdacfe1aae59f8a744888c4.jpg"/></p><p><strong>Подстанция МТПЖ (СТПЖ) </strong>мощностью 1,25; 2,5; 4; 10 кВ <sup>. </sup>А служат для приёма электрической энергии напряжением 6 или 10 кВ, преобразования в электроэнергию напряжением 0,23 кВ и снабжения ею устройств сигнализации, центролизации, автоблокировки, освещения и других маломощных железнодорожных объектов в районах с умеренным климатом (от минус 45 <sup>o </sup>С до +40 <sup>o </sup>С). </p><p>Особенности <strong>МТПЖ (СТПЖ) </strong>: </p><ul><li><div>Представляют собой однофазные подстанции; </div></li><li><div>Расположение оборудования: <br/><em>1 вариант </em>- вся аппаратура на одной опоре ВЛ 6 (10) кВ; <br/><em>2 вариант </em>- вся аппаратура (кроме разъединителя) на одной опоре, разъединитель - на ближайшей опоре ВЛ 6 (10) кВ (отдельно). </div></li><li><div><strong>Подстанция МТПЖ (СТПЖ) </strong>поставляется с одной или двумя отходящими линиями (по заказу). </div></li></ul></div>','assets/img/products/b_99__bbdacfe1aae59f8a744888c4.jpg','шт.',NULL,'Укажите мощность, напряжение, исполнение и комплектацию. Приложите опросный лист или проект.',1,0,961,'МТПЖ (СТПЖ) мощностью 1,25 - 10 кВА напряжением 6 (10) кВ мачтовая — купить по заявке | Монополия','МТПЖ (СТПЖ) мощностью 1,25 - 10 кВА напряжением 6 (10) кВ мачтовая: подбор и поставка в Санкт-Петербурге. Укажите мощность, напряжение, исполнение и комплектацию. Приложите опросный лист или проект. Расчет стоимости — по заявке.','site/www.monopoly-torg.ru/971-mtpzh-stpzh-moshchnostyu-1-25-10-kva-napryaz__488503637518dcaca20d5ccf.html','[]','["assets/img/products/b_99__bbdacfe1aae59f8a744888c4.jpg"]','["http://www.monopoly-torg.ru/index.php/transformatornye-podstantsii/transformatornye-podstantsii/971-mtpzh-stpzh-moshchnostyu-1-25-10-kva-napryazheniem-6-10-kv-machtovaya"]') ON DUPLICATE KEY UPDATE `category_id`=VALUES(`category_id`),`root_category`=VALUES(`root_category`),`name`=VALUES(`name`),`slug`=VALUES(`slug`),`sku`=VALUES(`sku`),`short_description`=VALUES(`short_description`),`description_html`=VALUES(`description_html`),`image`=VALUES(`image`),`unit`=VALUES(`unit`),`price`=VALUES(`price`),`request_hint`=VALUES(`request_hint`),`active`=VALUES(`active`),`featured`=VALUES(`featured`),`sort_order`=VALUES(`sort_order`),`seo_title`=VALUES(`seo_title`),`seo_description`=VALUES(`seo_description`),`source_file`=VALUES(`source_file`),`specs_json`=VALUES(`specs_json`),`gallery_json`=VALUES(`gallery_json`),`old_urls_json`=VALUES(`old_urls_json`);
INSERT INTO `products` (`id`,`category_id`,`root_category`,`name`,`slug`,`sku`,`short_description`,`description_html`,`image`,`unit`,`price`,`request_hint`,`active`,`featured`,`sort_order`,`seo_title`,`seo_description`,`source_file`,`specs_json`,`gallery_json`,`old_urls_json`) VALUES (962,29,'transformers','КТП ОС мощностью 25; 40; 63 кВА напряжением 6(10) кВ','972-ktp-os-moshchnostyu-25-40-63-kva-napryazheniem-6-10-kv','MNP-0962','Комплектные трансформаторные подстанции служат для приёма электрической энергии трехфазного переменного тока частотой 50 Гц, напряжением 6 или 10 кВ, преобразования её в электроэнергию напряжением 0,23 кВ и снабжения ею потребителей в сетях с.','<div><h4>КТП ОС мощностью 25; 40; 63 кВА напряжением 6(10) кВ </h4><p><img alt="b 100" loading="lazy" src="assets/img/products/b_100__9fdc28a37ebc9e088f2cc216.jpg"/></p><p>Комплектные трансформаторные подстанции служат для приёма электрической энергии трехфазного переменного тока частотой 50 Гц, напряжением 6 или 10 кВ, преобразования её в электроэнергию напряжением 0,23 кВ и снабжения ею потребителей в сетях с изолированной нейтралью. </p><p>Подстанции предназначены для питания цепей электрообогрева железнодорожных стрелочных переводов в районах с умеренным климатом (от минус 45 <sup>o </sup>С до +40 <sup>o </sup>С). </p><p>КТП ОС выполняется с воздушным высоковольтным вводом и кабельными линиями 0,23 кВ. </p><p>Представляют собой однотрансформаторные подстанции наружной установки. </p><p>КТП ОС подключается к ЛЭП 6(10) кВ посредством разъединителя, который поставляется комплектно с подстанцией и устанавливается на ближайшей опоре. </p><p>В КТП ОС на отходящих линиях установлены <em>стационарные автоматы </em>. </p><p>Патроны высоковольтных предохранителей установлены внутри шкафа УВН. </p><p>Подстанции обеспечивают учёт активной электрической энергии. </p><p>В КТП ОС имеются <em>электрические и механические блокировки </em>, обеспечивающие безопасную работу обслуживающего персонала. </p></div>','assets/img/products/b_100__9fdc28a37ebc9e088f2cc216.jpg','шт.',NULL,'Укажите мощность, напряжение, исполнение и комплектацию. Приложите опросный лист или проект.',1,0,962,'КТП ОС мощностью 25; 40; 63 кВА напряжением 6(10) кВ — купить по заявке | Монополия','КТП ОС мощностью 25; 40; 63 кВА напряжением 6(10) кВ: подбор и поставка в Санкт-Петербурге. Укажите мощность, напряжение, исполнение и комплектацию. Приложите опросный лист или проект. Расчет стоимости — по заявке.','site/www.monopoly-torg.ru/972-ktp-os-moshchnostyu-25-40-63-kva-napryazheni__af0a5a48cdeda6a355709211.html','[]','["assets/img/products/b_100__9fdc28a37ebc9e088f2cc216.jpg"]','["http://www.monopoly-torg.ru/index.php/transformatornye-podstantsii/transformatornye-podstantsii/972-ktp-os-moshchnostyu-25-40-63-kva-napryazheniem-6-10-kv"]') ON DUPLICATE KEY UPDATE `category_id`=VALUES(`category_id`),`root_category`=VALUES(`root_category`),`name`=VALUES(`name`),`slug`=VALUES(`slug`),`sku`=VALUES(`sku`),`short_description`=VALUES(`short_description`),`description_html`=VALUES(`description_html`),`image`=VALUES(`image`),`unit`=VALUES(`unit`),`price`=VALUES(`price`),`request_hint`=VALUES(`request_hint`),`active`=VALUES(`active`),`featured`=VALUES(`featured`),`sort_order`=VALUES(`sort_order`),`seo_title`=VALUES(`seo_title`),`seo_description`=VALUES(`seo_description`),`source_file`=VALUES(`source_file`),`specs_json`=VALUES(`specs_json`),`gallery_json`=VALUES(`gallery_json`),`old_urls_json`=VALUES(`old_urls_json`);
INSERT INTO `products` (`id`,`category_id`,`root_category`,`name`,`slug`,`sku`,`short_description`,`description_html`,`image`,`unit`,`price`,`request_hint`,`active`,`featured`,`sort_order`,`seo_title`,`seo_description`,`source_file`,`specs_json`,`gallery_json`,`old_urls_json`) VALUES (963,29,'transformers','КТП НД (шкафного типа) мощностью 40 - 100 кВА для нефтедобычи','973-ktp-nd-shkafnogo-tipa-moshchnostyu-40-100-kva-dlya-neftedobychi','MNP-0963','Комплектные трансформаторные подстанции для нефтедобычи КТП НД (наружной установки) служат для приёма энергии промышленной частоты напряжением 6 (10) кВ, преобразования её в электроэнергию напряжением 0,4 кВ и снабжения ею промысловых скважин.','<div><h4>КТП НД (шкафного типа) мощностью 40 - 100 кВА для нефтедобычи </h4><p><img alt="b 34" loading="lazy" src="assets/img/products/b_34__0f2bea90d7db857712c2f5f5.jpg"/></p><p><strong>Комплектные трансформаторные подстанции для нефтедобычи КТП НД (наружной установки) </strong>служат для приёма энергии промышленной частоты напряжением 6 (10) кВ, преобразования её в электроэнергию напряжением 0,4 кВ и снабжения ею промысловых скважин добычи нефти и других промышленных объектов в районах с умеренным климатом (от минус 45 <sup>o </sup>C до +40 <sup>o </sup>С). </p><p>Комплектно с <strong>КТП НД </strong>поставляется высоковольтный разъединитель, который устанавливается на ближайшей опоре ЛЭП. </p><p>Ввод ВН - воздушный; вывод НН - кабельный. </p><p>В <strong>КТП НД </strong>имеются блокировки, обеспечивающие безопасную работу обслуживающего персонала. </p></div>','assets/img/products/b_34__0f2bea90d7db857712c2f5f5.jpg','шт.',NULL,'Укажите мощность, напряжение, исполнение и комплектацию. Приложите опросный лист или проект.',1,0,963,'КТП НД (шкафного типа) мощностью 40 - 100 кВА для нефтедобычи — купить по заявке | Монополия','КТП НД (шкафного типа) мощностью 40 - 100 кВА для нефтедобычи: подбор и поставка в Санкт-Петербурге. Укажите мощность, напряжение, исполнение и комплектацию. Приложите опросный лист или проект. Расчет стоимости — по заявке.','site/www.monopoly-torg.ru/973-ktp-nd-shkafnogo-tipa-moshchnostyu-40-100-kv__25bf6f9bb6147bd8ef1c4366.html','[]','["assets/img/products/b_34__0f2bea90d7db857712c2f5f5.jpg"]','["http://www.monopoly-torg.ru/index.php/transformatornye-podstantsii/transformatornye-podstantsii/973-ktp-nd-shkafnogo-tipa-moshchnostyu-40-100-kva-dlya-neftedobychi"]') ON DUPLICATE KEY UPDATE `category_id`=VALUES(`category_id`),`root_category`=VALUES(`root_category`),`name`=VALUES(`name`),`slug`=VALUES(`slug`),`sku`=VALUES(`sku`),`short_description`=VALUES(`short_description`),`description_html`=VALUES(`description_html`),`image`=VALUES(`image`),`unit`=VALUES(`unit`),`price`=VALUES(`price`),`request_hint`=VALUES(`request_hint`),`active`=VALUES(`active`),`featured`=VALUES(`featured`),`sort_order`=VALUES(`sort_order`),`seo_title`=VALUES(`seo_title`),`seo_description`=VALUES(`seo_description`),`source_file`=VALUES(`source_file`),`specs_json`=VALUES(`specs_json`),`gallery_json`=VALUES(`gallery_json`),`old_urls_json`=VALUES(`old_urls_json`);
INSERT INTO `products` (`id`,`category_id`,`root_category`,`name`,`slug`,`sku`,`short_description`,`description_html`,`image`,`unit`,`price`,`request_hint`,`active`,`featured`,`sort_order`,`seo_title`,`seo_description`,`source_file`,`specs_json`,`gallery_json`,`old_urls_json`) VALUES (964,29,'transformers','КТП ПН-82, КТП ПН-05 (с контроллером) мощностью 100; 250 кВА, напряжением 6(10) кВ','974-ktp-pn-82-ktp-pn-05-s-kontrollerom-moshchnostyu-100-250-kva-napryazheniem-6-10-kv','MNP-0964','Подстанции трансформаторные комплектные серии КТППН представляют собой однотрансформаторные подстанции наружной установки. Служат для приема электрической энергии трехфазного переменного тока частоты 50 Гц напряжением 6(10) кВ, её транзита,.','<div><h4>КТП ПН-82, КТП ПН-05 (с контроллером) мощностью 100; 250 кВА, напряжением 6(10) кВ </h4><p><img alt="b 33" loading="lazy" src="assets/img/products/b_33__bb06a21fe340045757371d4e.jpg"/></p><p><strong>Подстанции трансформаторные комплектные серии КТППН </strong>представляют собой однотрансформаторные подстанции наружной установки. Служат для приема электрической энергии трехфазного переменного тока частоты 50 Гц напряжением 6(10) кВ, её транзита, преобразования и питания ею, управления и защиты электродвигателей погружных насосов добычи нефти из одиночных скважин мощностью от 16 до 250 кВт включительно. При необходимости <strong>КТППН </strong>может использоваться для питания электродвигателей станков-качалок с током нагрузки до 60 А. </p><p><strong>КТП ПН - 82 </strong>- представляют собой ТП с блоком управления БУ-01(БРГ). <br/><strong>КТП ПН - 05 </strong>- представляют собой модернизированную КТППН - 82 с контроллером </p><p>В <strong>КТППН </strong>имеются блокировки, обеспечивающие безопасную работу обслуживающего персонала. КТППН устанавливается на фундаменте. Комплектно с <strong>КТППН </strong>поставляется разъединитель наружной установки. </p><p><strong>Особенности КТППН: </strong></p><ul><li><div>Высоковольтный ввод в подстанцию - воздушный; </div></li><li><div>Выводы отходящих линий НН и СН - кабельные. </div></li><li><div>Силовой трансформатор предназначен для работы в двух режимах: <br/>- в режиме питания электродвигателя погружных насосов; <br/>- в режиме питания ремонтного фидера или станка-качалки. <br/><strong><em>При работе в режиме питания электродвигателя питание ремонтного фидера или станка-качалки невозможно и наоборот. </em></strong></div></li><li><div>В шкафу СН установлены штепсельные разъемы для присоединения следующих токоприемников: <br/>- на трехфазное напряжение 380 В с током нагрузки до 60 А для питания ремонтного фидера; <br/>- на однофазное напряжение 220 В с током нагрузки до 25 А; <br/>- на однофазное напряжение 36 В с током нагрузки до 6 А. </div></li><li><div>Предусмотрено место для установки приборов учета электроэнергии. </div></li></ul></div>','assets/img/products/b_33__bb06a21fe340045757371d4e.jpg','шт.',NULL,'Укажите мощность, напряжение, исполнение и комплектацию. Приложите опросный лист или проект.',1,0,964,'КТП ПН-82, КТП ПН-05 (с контроллером) мощностью 100; 250 кВА, напряжением 6(10) кВ — купить по заявке | Монополия','КТП ПН-82, КТП ПН-05 (с контроллером) мощностью 100; 250 кВА, напряжением 6(10) кВ: подбор и поставка в Санкт-Петербурге. Укажите мощность, напряжение, исполнение и комплектацию. Приложите опросный лист или проект. Расчет стоимости — по заявке.','site/www.monopoly-torg.ru/974-ktp-pn-82-ktp-pn-05-s-kontrollerom-moshchnos__becf226c3fd9fe691d0018de.html','[]','["assets/img/products/b_33__bb06a21fe340045757371d4e.jpg"]','["http://www.monopoly-torg.ru/index.php/transformatornye-podstantsii/transformatornye-podstantsii/974-ktp-pn-82-ktp-pn-05-s-kontrollerom-moshchnostyu-100-250-kva-napryazheniem-6-10-kv"]') ON DUPLICATE KEY UPDATE `category_id`=VALUES(`category_id`),`root_category`=VALUES(`root_category`),`name`=VALUES(`name`),`slug`=VALUES(`slug`),`sku`=VALUES(`sku`),`short_description`=VALUES(`short_description`),`description_html`=VALUES(`description_html`),`image`=VALUES(`image`),`unit`=VALUES(`unit`),`price`=VALUES(`price`),`request_hint`=VALUES(`request_hint`),`active`=VALUES(`active`),`featured`=VALUES(`featured`),`sort_order`=VALUES(`sort_order`),`seo_title`=VALUES(`seo_title`),`seo_description`=VALUES(`seo_description`),`source_file`=VALUES(`source_file`),`specs_json`=VALUES(`specs_json`),`gallery_json`=VALUES(`gallery_json`),`old_urls_json`=VALUES(`old_urls_json`);
INSERT INTO `products` (`id`,`category_id`,`root_category`,`name`,`slug`,`sku`,`short_description`,`description_html`,`image`,`unit`,`price`,`request_hint`,`active`,`featured`,`sort_order`,`seo_title`,`seo_description`,`source_file`,`specs_json`,`gallery_json`,`old_urls_json`) VALUES (965,29,'transformers','КТП ПН-400, КТП ПН-1000 мощностью 400; 1000 кВА, напряжением 6 кВ','975-ktp-pn-400-ktp-pn-1000-moshchnostyu-400-1000-kva-napryazheniem-6-kv','MNP-0965','Подстанции трансформаторные комплектные серии КТППН представляют собой однотрансформаторные подстанции наружной установки и служат для приема электрической энергии трехфазного переменного тока частоты 50 Гц напряжением 6 кВ, транзита ее,.','<div><h4>КТП ПН-400, КТП ПН-1000 мощностью 400; 1000 кВА, напряжением 6 кВ </h4><p><img alt="b 96" loading="lazy" src="assets/img/products/b_96__4aecae5e5ff596689d674055.jpg"/></p><p><strong>Подстанции трансформаторные комплектные серии КТППН </strong>представляют собой однотрансформаторные подстанции наружной установки и служат для приема электрической энергии трехфазного переменного тока частоты 50 Гц напряжением 6 кВ, транзита ее, преобразования и питания ею, управления и защиты электродвигателей погружных насосов добычи нефти из одиночных скважин мощностью до 700 кВт включительно. При необходимости <strong>КТППН </strong>может использоваться для питания электродвигателей станков-качалок с током нагрузки до 60А. </p><p>В <strong>КТППН </strong>имеются блокировки, обеспечивающие безопасную работу обслуживающего персонала. </p><p><strong>КТППН </strong>устанавливается на утрамбованной площадке или фундаменте. </p><p>Комплектно с КТППН поставляется разъединитель наружной установки. </p><p><strong>Особенности КТППН: </strong></p><ul><li><div>Высоковольтный ввод в подстанцию - воздушный; выводы отходящих линий НН и СН - кабельные. </div></li><li><div>Силовой трансформатор предназначен для работы в двух режимах: <br/>- в режиме питания электродвигателя погружных насосов; <br/>- в режиме питания ремонтного фидера или станка-качалки. <br/><em>При работе в режиме питания электродвигателя питание ремонтного фидера или станка-качалки невозможно и наоборот. </em></div></li><li><div>В шкафу СН установлены штепсельные разъемы для присоединения следующих токоприемников: <br/>- на трехфазное напряжение 380 В с током нагрузки до 60 А для питания ремонтного фидера; <br/>- на однофазное напряжение 220 В с током нагрузки до 25 А; <br/>- на однофазное напряжение 36 В с током нагрузки до 6 А. </div></li><li><div>Предусмотрено место для установки приборов учета электроэнергии. </div></li><li><div>В КТППН управление погружным электродвигателем (ПЭД) осуществляется контроллером. </div></li><li><div>В КТППН предусмотрен отдельный отсек для подключения кабеля от ПЭД. </div></li></ul></div>','assets/img/products/b_96__4aecae5e5ff596689d674055.jpg','шт.',NULL,'Укажите мощность, напряжение, исполнение и комплектацию. Приложите опросный лист или проект.',1,0,965,'КТП ПН-400, КТП ПН-1000 мощностью 400; 1000 кВА, напряжением 6 кВ — купить по заявке | Монополия','КТП ПН-400, КТП ПН-1000 мощностью 400; 1000 кВА, напряжением 6 кВ: подбор и поставка в Санкт-Петербурге. Укажите мощность, напряжение, исполнение и комплектацию. Приложите опросный лист или проект. Расчет стоимости — по заявке.','site/www.monopoly-torg.ru/975-ktp-pn-400-ktp-pn-1000-moshchnostyu-400-1000__4eee6b17688770d9eb2a4a75.html','[]','["assets/img/products/b_96__4aecae5e5ff596689d674055.jpg"]','["http://www.monopoly-torg.ru/index.php/transformatornye-podstantsii/transformatornye-podstantsii/975-ktp-pn-400-ktp-pn-1000-moshchnostyu-400-1000-kva-napryazheniem-6-kv"]') ON DUPLICATE KEY UPDATE `category_id`=VALUES(`category_id`),`root_category`=VALUES(`root_category`),`name`=VALUES(`name`),`slug`=VALUES(`slug`),`sku`=VALUES(`sku`),`short_description`=VALUES(`short_description`),`description_html`=VALUES(`description_html`),`image`=VALUES(`image`),`unit`=VALUES(`unit`),`price`=VALUES(`price`),`request_hint`=VALUES(`request_hint`),`active`=VALUES(`active`),`featured`=VALUES(`featured`),`sort_order`=VALUES(`sort_order`),`seo_title`=VALUES(`seo_title`),`seo_description`=VALUES(`seo_description`),`source_file`=VALUES(`source_file`),`specs_json`=VALUES(`specs_json`),`gallery_json`=VALUES(`gallery_json`),`old_urls_json`=VALUES(`old_urls_json`);
INSERT INTO `products` (`id`,`category_id`,`root_category`,`name`,`slug`,`sku`,`short_description`,`description_html`,`image`,`unit`,`price`,`request_hint`,`active`,`featured`,`sort_order`,`seo_title`,`seo_description`,`source_file`,`specs_json`,`gallery_json`,`old_urls_json`) VALUES (966,29,'transformers','Устройство комплектное серии ШГС-5805, ШГС-5805М (модернизированное)','976-ustrojstvo-komplektnoe-serii-shgs-5805-shgs-5805m-modernizirovannoe','MNP-0966','Устройства комплектные серии ШГС предназначены для приема электрической энергии трехфазного переменного тока частоты 50 Гц напряжением 380 В и преобразования ее в электроэнергию напряжением, соответствующим напряжению двигателя, а также для.','<div><h4>Устройство комплектное серии ШГС-5805, ШГС-5805М (модернизированное) </h4><p><img alt="b 36" loading="lazy" src="assets/img/products/b_36__9f8550e402df84759253cd2c.jpg"/></p><p>Устройства комплектные серии ШГС предназначены для приема электрической энергии трехфазного переменного тока частоты 50 Гц напряжением 380 В и преобразования ее в электроэнергию напряжением, соответствующим напряжению двигателя, а также для управления и защиты погружных электронасосов добычи нефти с двигателями серии ПЭД мощностью от 14 до 100 кВт с номинальным током не более 50 А и номинальным напряжением 220 В переменного тока в районах с умеренным климатом (от минус 45 <sup>o </sup>С до +40 <sup>o </sup>С). </p><p><em>Минский электротехнический завод им. В.И. Козлова является крупнейшим производителем станций управления типа ШГС-5805 с блоком управления БУ-01 (БРГ). </em></p><p>Устройства комплектные серии ШГС-5805М представляют собой модернизированную станцию ШГС с контроллером (производства АО "Ижевский радиозавод"). </p><p>Контроллер имеет два исполнения - вариант работы с погружным датчиком и без него, а также позволяет подключать устройства телемеханики. При необходимости отслеживать текущие параметры в забое скважины. В конструкции скважины применяется блок погружной, запитываемый от контроллера серии ТМ. </p></div>','assets/img/products/b_36__9f8550e402df84759253cd2c.jpg','шт.',NULL,'Укажите мощность, напряжение, исполнение и комплектацию. Приложите опросный лист или проект.',1,0,966,'Устройство комплектное серии ШГС-5805, ШГС-5805М (модернизированное) — купить по заявке | Монополия','Устройство комплектное серии ШГС-5805, ШГС-5805М (модернизированное): подбор и поставка в Санкт-Петербурге. Укажите мощность, напряжение, исполнение и комплектацию. Приложите опросный лист или проект. Расчет стоимости — по заявке.','site/www.monopoly-torg.ru/976-ustrojstvo-komplektnoe-serii-shgs-5805-shgs-__1d42104dadc89c3c14f7d072.html','[]','["assets/img/products/b_36__9f8550e402df84759253cd2c.jpg"]','["http://www.monopoly-torg.ru/index.php/transformatornye-podstantsii/transformatornye-podstantsii/976-ustrojstvo-komplektnoe-serii-shgs-5805-shgs-5805m-modernizirovannoe"]') ON DUPLICATE KEY UPDATE `category_id`=VALUES(`category_id`),`root_category`=VALUES(`root_category`),`name`=VALUES(`name`),`slug`=VALUES(`slug`),`sku`=VALUES(`sku`),`short_description`=VALUES(`short_description`),`description_html`=VALUES(`description_html`),`image`=VALUES(`image`),`unit`=VALUES(`unit`),`price`=VALUES(`price`),`request_hint`=VALUES(`request_hint`),`active`=VALUES(`active`),`featured`=VALUES(`featured`),`sort_order`=VALUES(`sort_order`),`seo_title`=VALUES(`seo_title`),`seo_description`=VALUES(`seo_description`),`source_file`=VALUES(`source_file`),`specs_json`=VALUES(`specs_json`),`gallery_json`=VALUES(`gallery_json`),`old_urls_json`=VALUES(`old_urls_json`);
INSERT INTO `products` (`id`,`category_id`,`root_category`,`name`,`slug`,`sku`,`short_description`,`description_html`,`image`,`unit`,`price`,`request_hint`,`active`,`featured`,`sort_order`,`seo_title`,`seo_description`,`source_file`,`specs_json`,`gallery_json`,`old_urls_json`) VALUES (967,29,'transformers','Комплектное устройство серии КУ-01','977-komplektnoe-ustrojstvo-serii-ku-01','MNP-0967','Комплектное устройство серии КУ-01 для промышленных, строительных и энергетических объектов.','<div><h4>Комплектное устройство серии КУ-01 </h4><p><img alt="b 31" loading="lazy" src="assets/img/products/b_31__eb637bbaf12282b3ed1a18bc.jpg"/></p><p>Комплектные устройства предназначены для приема электрической энергии трехфазного переменного тока частоты 50 Гц напряжением 380 В и преобразования её в электроэнергию напряжением, соответствующим напряжению двигателя, а также для управления и защиты погружных электронасосов добычи нефти с двигателями серии ПЭД мощностью от 14 до 100 кВт с номинальным током не более 50 А и номинальным напряжением до 2200 В переменного тока, в районах с умеренным климатом (от минус 45 <sup>o </sup>C до +40 <sup>o </sup>C). Устройство представляет собой установку, состоящую из силового трансформатора и станции ШГС, которые монтируются на одной раме, соединяются между собой механически и электрически. <em>Это обеспечивает их высокую монтажную готовность и приводит к сокращению строительно-монтажных работ при установке на месте эксплуатации (по сравнению с покупкой оборудования раздельно). </em></p></div>','assets/img/products/b_31__eb637bbaf12282b3ed1a18bc.jpg','шт.',NULL,'Укажите мощность, напряжение, исполнение и комплектацию. Приложите опросный лист или проект.',1,0,967,'Комплектное устройство серии КУ-01 — купить по заявке | Монополия','Комплектное устройство серии КУ-01: подбор и поставка в Санкт-Петербурге. Укажите мощность, напряжение, исполнение и комплектацию. Приложите опросный лист или проект. Расчет стоимости — по заявке.','site/www.monopoly-torg.ru/977-komplektnoe-ustrojstvo-serii-ku-01__fadf4fae9e29eb7bb18c9198.html','[]','["assets/img/products/b_31__eb637bbaf12282b3ed1a18bc.jpg"]','["http://www.monopoly-torg.ru/index.php/transformatornye-podstantsii/transformatornye-podstantsii/977-komplektnoe-ustrojstvo-serii-ku-01"]') ON DUPLICATE KEY UPDATE `category_id`=VALUES(`category_id`),`root_category`=VALUES(`root_category`),`name`=VALUES(`name`),`slug`=VALUES(`slug`),`sku`=VALUES(`sku`),`short_description`=VALUES(`short_description`),`description_html`=VALUES(`description_html`),`image`=VALUES(`image`),`unit`=VALUES(`unit`),`price`=VALUES(`price`),`request_hint`=VALUES(`request_hint`),`active`=VALUES(`active`),`featured`=VALUES(`featured`),`sort_order`=VALUES(`sort_order`),`seo_title`=VALUES(`seo_title`),`seo_description`=VALUES(`seo_description`),`source_file`=VALUES(`source_file`),`specs_json`=VALUES(`specs_json`),`gallery_json`=VALUES(`gallery_json`),`old_urls_json`=VALUES(`old_urls_json`);
INSERT INTO `pages` (`id`,`slug`,`title`,`h1`,`lead`,`body_html`,`image`,`template`,`seo_title`,`seo_description`,`active`,`sort_order`) VALUES (1,'home','Кабель, металлопрокат, профнастил и трансформаторы в Санкт-Петербурге','Материалы и оборудование для вашего проекта','Кабельная продукция, металлопрокат, профнастил и трансформаторное оборудование. Подберем позиции по спецификации и подготовим единое коммерческое предложение.','<p>Торговая компания «Монополия» работает на строительном рынке с 2009 года. Помогаем комплектовать объекты: от кабельной линии и ведомости металла до оборудования электроснабжения.</p>','assets/img/cable.webp','home','Кабель, металлопрокат, профнастил и трансформаторы в Санкт-Петербурге | Торговая компания «Монополия»','Поставки кабеля, металлопроката, профнастила, трансформаторов и КТП в Санкт-Петербурге. Подбор по проекту и расчет стоимости по заявке. Торговая компания «Монополия».',1,0) ON DUPLICATE KEY UPDATE `slug`=VALUES(`slug`),`title`=VALUES(`title`),`h1`=VALUES(`h1`),`lead`=VALUES(`lead`),`body_html`=VALUES(`body_html`),`image`=VALUES(`image`),`template`=VALUES(`template`),`seo_title`=VALUES(`seo_title`),`seo_description`=VALUES(`seo_description`),`active`=VALUES(`active`),`sort_order`=VALUES(`sort_order`);
INSERT INTO `pages` (`id`,`slug`,`title`,`h1`,`lead`,`body_html`,`image`,`template`,`seo_title`,`seo_description`,`active`,`sort_order`) VALUES (2,'about','О компании','Надежная комплектация начинается с внимания к деталям','Торговая компания «Монополия» поставляет материалы и оборудование для строительства, промышленности и энергетики с 2009 года.','<h2>Четыре направления в одной поставке</h2><p>В нашем каталоге представлены кабели и провода, металлопрокат, профилированные листы, силовые трансформаторы и комплектные трансформаторные подстанции. Работаем со спецификациями строительных и производственных предприятий, проектных организаций и частных заказчиков.</p><p>При подборе учитываем назначение продукции, размеры, марку, условия эксплуатации и требования проекта. Если исходных данных недостаточно, менеджер уточнит параметры до подготовки предложения.</p><h2>Как строится сотрудничество</h2><p>Вы направляете список материалов, ведомость или опросный лист. Мы согласуем характеристики, объем, комплектность, стоимость и условия поставки. Затем фиксируем договоренности в коммерческом предложении и документах заказа.</p><p>Сроки, наличие и возможные замены обсуждаются по конкретной заявке. Такой подход помогает связать поставку с графиком работ и избежать ошибок в комплектации.</p><h2>От небольшого заказа до комплексной спецификации</h2><p>Помогаем собрать несколько групп продукции в одном запросе. Заявку можно начать с отдельной позиции каталога, а затем добавить материалы вручную или приложить файл. Для проектного оборудования принимаем технические требования и опросные листы.</p><p>Офис компании находится в Санкт-Петербурге. Условия доставки в другой регион согласуем при расчете заказа.</p>','assets/img/about.webp','content','О компании | Торговая компания «Монополия»','Торговая компания «Монополия»: поставки строительных материалов и электротехнического оборудования с 2009 года. Подбор, комплектация и согласование доставки.',1,1) ON DUPLICATE KEY UPDATE `slug`=VALUES(`slug`),`title`=VALUES(`title`),`h1`=VALUES(`h1`),`lead`=VALUES(`lead`),`body_html`=VALUES(`body_html`),`image`=VALUES(`image`),`template`=VALUES(`template`),`seo_title`=VALUES(`seo_title`),`seo_description`=VALUES(`seo_description`),`active`=VALUES(`active`),`sort_order`=VALUES(`sort_order`);
INSERT INTO `pages` (`id`,`slug`,`title`,`h1`,`lead`,`body_html`,`image`,`template`,`seo_title`,`seo_description`,`active`,`sort_order`) VALUES (3,'delivery','Условия поставки','Поставка с учетом вашего графика работ','Стоимость, наличие, срок комплектации и способ доставки согласуем по каждой заявке. Все ключевые условия фиксируются до оформления заказа.','<h2>Подготовка коммерческого предложения</h2><p>Для расчета укажите наименование и характеристики продукции, количество, адрес доставки и желаемую дату получения. Если есть проектная спецификация, ведомость металла или опросный лист, приложите файл: это ускорит согласование и сократит число уточнений.</p><h2>Оплата и документы</h2><p>Заказ оформляется после согласования состава поставки и коммерческих условий. Порядок оплаты указывается в счете и договоре. Сайт принимает заявки на расчет; онлайн-оплата не предусмотрена.</p><p>Сопроводительные документы определяются видом продукции и согласованными условиями. Паспорта, сертификаты и документы о качестве запрашиваются для выбранного исполнения или партии.</p><h2>Доставка и самовывоз</h2><p>Доставку рассчитываем с учетом региона, габаритов, массы и особенностей разгрузки. Длинномерный прокат, кабельные барабаны и электротехническое оборудование требуют подходящего транспорта и согласования подъезда к объекту.</p><p>Если нужен самовывоз, менеджер подтвердит место и время выдачи, готовность продукции и требования к автомобилю. Офис продаж не является универсальной точкой отгрузки всех товарных групп.</p><h2>Приемка продукции</h2><p>При получении сопоставьте маркировку, количество и комплектность с документами, осмотрите упаковку и продукцию. При обнаружении расхождений зафиксируйте их в документах приемки и свяжитесь с менеджером.</p><h2>Изменения в спецификации</h2><p>Замены, дополнительные позиции и изменения количества согласуются до отгрузки. Для продукции, изготовленной под проект, возможность изменения заказа зависит от стадии производства и условий договора.</p>','assets/img/delivery.webp','content','Условия поставки | Торговая компания «Монополия»','Условия поставки кабеля, металлопроката, профнастила и трансформаторов: расчет заказа, оплата, документы, доставка и самовывоз. Торговая компания «Монополия».',1,2) ON DUPLICATE KEY UPDATE `slug`=VALUES(`slug`),`title`=VALUES(`title`),`h1`=VALUES(`h1`),`lead`=VALUES(`lead`),`body_html`=VALUES(`body_html`),`image`=VALUES(`image`),`template`=VALUES(`template`),`seo_title`=VALUES(`seo_title`),`seo_description`=VALUES(`seo_description`),`active`=VALUES(`active`),`sort_order`=VALUES(`sort_order`);
INSERT INTO `pages` (`id`,`slug`,`title`,`h1`,`lead`,`body_html`,`image`,`template`,`seo_title`,`seo_description`,`active`,`sort_order`) VALUES (4,'documents','Документы и техническая библиотека','Документы для обоснованного выбора','Подберем сопроводительные документы к выбранной продукции и поможем уточнить требования спецификации. В библиотеке собраны технические материалы из каталога компании.','<h2>Документы на поставляемую продукцию</h2><p>Комплект документов зависит от товарной группы, производителя и исполнения. Для запроса укажите марку или модель, требуемый стандарт и объем поставки. Менеджер уточнит возможность предоставления паспорта, сертификата или документа о качестве для конкретной партии.</p><h2>Расчет вместо устаревшего прайс-листа</h2><p>Цена определяется по характеристикам, объему и условиям поставки. Добавьте позиции в заявку или направьте спецификацию на monopoly@list.ru — получите предложение по вашему заказу.</p><h2>Техническая библиотека</h2><p>Ниже доступны архивные справочные документы исходного каталога. Они помогают изучить обозначения и сортамент. Применимость стандарта и действующий комплект документов для заказа подтверждаются при согласовании поставки.</p>','assets/img/documents.webp','documents','Документы и техническая библиотека | Торговая компания «Монополия»','Подберем сопроводительные документы к выбранной продукции и поможем уточнить требования спецификации. В библиотеке собраны технические материалы из каталога компании.',1,3) ON DUPLICATE KEY UPDATE `slug`=VALUES(`slug`),`title`=VALUES(`title`),`h1`=VALUES(`h1`),`lead`=VALUES(`lead`),`body_html`=VALUES(`body_html`),`image`=VALUES(`image`),`template`=VALUES(`template`),`seo_title`=VALUES(`seo_title`),`seo_description`=VALUES(`seo_description`),`active`=VALUES(`active`),`sort_order`=VALUES(`sort_order`);
INSERT INTO `pages` (`id`,`slug`,`title`,`h1`,`lead`,`body_html`,`image`,`template`,`seo_title`,`seo_description`,`active`,`sort_order`) VALUES (5,'faq','Вопросы и ответы','Ответы на частые вопросы','Как оформить заявку, какие параметры указать и когда согласуются цена и доставка. Если вашего вопроса нет в списке, свяжитесь с менеджером.','<p>Можно отправить запрос без выбора позиции в каталоге: достаточно описать задачу и приложить имеющиеся материалы. Ответ направим по указанным контактам.</p>','assets/img/documents.webp','faq','Вопросы и ответы | Торговая компания «Монополия»','Как оформить заявку, какие параметры указать и когда согласуются цена и доставка. Если вашего вопроса нет в списке, свяжитесь с менеджером.',1,4) ON DUPLICATE KEY UPDATE `slug`=VALUES(`slug`),`title`=VALUES(`title`),`h1`=VALUES(`h1`),`lead`=VALUES(`lead`),`body_html`=VALUES(`body_html`),`image`=VALUES(`image`),`template`=VALUES(`template`),`seo_title`=VALUES(`seo_title`),`seo_description`=VALUES(`seo_description`),`active`=VALUES(`active`),`sort_order`=VALUES(`sort_order`);
INSERT INTO `pages` (`id`,`slug`,`title`,`h1`,`lead`,`body_html`,`image`,`template`,`seo_title`,`seo_description`,`active`,`sort_order`) VALUES (6,'contacts','Контакты','Обсудим вашу поставку','Направьте спецификацию или задайте вопрос о продукции. Менеджер уточнит параметры и подготовит коммерческое предложение.','<p>При посещении офиса заранее свяжитесь с нами, чтобы согласовать встречу. Место отгрузки и условия самовывоза подтверждаются отдельно для выбранной продукции.</p>','assets/img/contacts.webp','contacts','Контакты | Торговая компания «Монополия»','Контакты торговой компании «Монополия»: Санкт-Петербург, Киришская ул., д. 2А. Телефон +7 (812) 932-86-48, электронная почта monopoly@list.ru.',1,5) ON DUPLICATE KEY UPDATE `slug`=VALUES(`slug`),`title`=VALUES(`title`),`h1`=VALUES(`h1`),`lead`=VALUES(`lead`),`body_html`=VALUES(`body_html`),`image`=VALUES(`image`),`template`=VALUES(`template`),`seo_title`=VALUES(`seo_title`),`seo_description`=VALUES(`seo_description`),`active`=VALUES(`active`),`sort_order`=VALUES(`sort_order`);
INSERT INTO `pages` (`id`,`slug`,`title`,`h1`,`lead`,`body_html`,`image`,`template`,`seo_title`,`seo_description`,`active`,`sort_order`) VALUES (7,'search','Поиск по каталогу','Найдите нужную марку или исполнение','Ищите по наименованию, маркировке или техническим характеристикам. Несколько найденных позиций можно объединить в одну заявку.','<p>Если подходящая позиция не найдена, отправьте ее наименование и параметры через форму заявки. Менеджер уточнит возможность поставки.</p>','','search','Поиск по каталогу | Торговая компания «Монополия»','Ищите по наименованию, маркировке или техническим характеристикам. Несколько найденных позиций можно объединить в одну заявку.',1,6) ON DUPLICATE KEY UPDATE `slug`=VALUES(`slug`),`title`=VALUES(`title`),`h1`=VALUES(`h1`),`lead`=VALUES(`lead`),`body_html`=VALUES(`body_html`),`image`=VALUES(`image`),`template`=VALUES(`template`),`seo_title`=VALUES(`seo_title`),`seo_description`=VALUES(`seo_description`),`active`=VALUES(`active`),`sort_order`=VALUES(`sort_order`);
INSERT INTO `pages` (`id`,`slug`,`title`,`h1`,`lead`,`body_html`,`image`,`template`,`seo_title`,`seo_description`,`active`,`sort_order`) VALUES (8,'request','Корзина и заявка на расчет','Ваша заявка на поставку','Соберите позиции, укажите объем и важные характеристики. Можно добавить товар вручную или приложить готовую спецификацию.','<p>Заявка используется для подготовки коммерческого предложения. Итоговая стоимость, наличие, сроки и условия доставки согласуются с менеджером.</p>','','request','Корзина и заявка на расчет | Торговая компания «Монополия»','Соберите позиции, укажите объем и важные характеристики. Можно добавить товар вручную или приложить готовую спецификацию.',1,7) ON DUPLICATE KEY UPDATE `slug`=VALUES(`slug`),`title`=VALUES(`title`),`h1`=VALUES(`h1`),`lead`=VALUES(`lead`),`body_html`=VALUES(`body_html`),`image`=VALUES(`image`),`template`=VALUES(`template`),`seo_title`=VALUES(`seo_title`),`seo_description`=VALUES(`seo_description`),`active`=VALUES(`active`),`sort_order`=VALUES(`sort_order`);
INSERT INTO `pages` (`id`,`slug`,`title`,`h1`,`lead`,`body_html`,`image`,`template`,`seo_title`,`seo_description`,`active`,`sort_order`) VALUES (9,'success','Заявка принята','Спасибо, заявка принята','Мы сохранили вашу спецификацию. Менеджер свяжется с вами по указанным контактам для уточнения параметров поставки.','<p>Если требуется дополнить заявку, напишите на monopoly@list.ru и укажите номер обращения. Это поможет связать новые материалы с вашим запросом.</p>','','success','Заявка принята | Торговая компания «Монополия»','Мы сохранили вашу спецификацию. Менеджер свяжется с вами по указанным контактам для уточнения параметров поставки.',1,8) ON DUPLICATE KEY UPDATE `slug`=VALUES(`slug`),`title`=VALUES(`title`),`h1`=VALUES(`h1`),`lead`=VALUES(`lead`),`body_html`=VALUES(`body_html`),`image`=VALUES(`image`),`template`=VALUES(`template`),`seo_title`=VALUES(`seo_title`),`seo_description`=VALUES(`seo_description`),`active`=VALUES(`active`),`sort_order`=VALUES(`sort_order`);
INSERT INTO `pages` (`id`,`slug`,`title`,`h1`,`lead`,`body_html`,`image`,`template`,`seo_title`,`seo_description`,`active`,`sort_order`) VALUES (10,'privacy','Политика конфиденциальности','Обработка персональных данных','Торговая компания «Монополия» обрабатывает контактные данные, чтобы отвечать на обращения, рассчитывать поставки и согласовывать заказы.','<h2>Какие данные мы получаем</h2><p>При отправке формы вы предоставляете имя, телефон, адрес электронной почты и, по желанию, название организации, город, сообщение и спецификацию. В файлах следует передавать только сведения, необходимые для расчета поставки.</p><h2>Цель и основание обработки</h2><p>Данные используются для ответа на обращение, уточнения технических параметров, подготовки коммерческого предложения и дальнейшего оформления согласованного заказа. Отправка формы сопровождается отдельным подтверждением согласия на обработку данных для этих целей.</p><h2>Хранение и доступ</h2><p>Обращения хранятся в системе учета заявок. Доступ к ним предоставляется сотрудникам, которые обрабатывают запросы. Сообщения могут передаваться через почтовую инфраструктуру для уведомления ответственного сотрудника. Контактные данные не публикуются на сайте и не используются для рекламных рассылок без отдельного согласия.</p><p>Данные сохраняются в течение срока, необходимого для обработки обращения и исполнения заказа, с учетом применимых требований к хранению документов. После отпадения цели обработки данные удаляются или обезличиваются.</p><h2>Файлы cookie и статистика</h2><p>Технические cookie поддерживают сессию, безопасность форм и корзину. Собственная статистика сайта учитывает просмотренные страницы, источник перехода и тип устройства. В статистические отчеты не записываются текст заявки, имя, телефон, email или полный IP-адрес. Сторонние рекламные счетчики не используются.</p><p>Сбор статистики можно отключить кнопкой «Отключить статистику» в нижней части страницы. Технические cookie необходимы для работы корзины и форм.</p><h2>Ваши права и связь с компанией</h2><p>Чтобы уточнить данные, отозвать согласие или запросить удаление сведений, направьте обращение на monopoly@list.ru. Укажите контакт, использованный в заявке, и номер обращения, если он известен. Мы рассмотрим запрос и сообщим о результате.</p><p>Адрес для связи: 195299, Санкт-Петербург, Киришская ул., д. 2А, помещение 8Н. Телефон: +7 (812) 932-86-48.</p>','','content','Политика конфиденциальности | Торговая компания «Монополия»','Торговая компания «Монополия» обрабатывает контактные данные, чтобы отвечать на обращения, рассчитывать поставки и согласовывать заказы.',1,9) ON DUPLICATE KEY UPDATE `slug`=VALUES(`slug`),`title`=VALUES(`title`),`h1`=VALUES(`h1`),`lead`=VALUES(`lead`),`body_html`=VALUES(`body_html`),`image`=VALUES(`image`),`template`=VALUES(`template`),`seo_title`=VALUES(`seo_title`),`seo_description`=VALUES(`seo_description`),`active`=VALUES(`active`),`sort_order`=VALUES(`sort_order`);
INSERT INTO `pages` (`id`,`slug`,`title`,`h1`,`lead`,`body_html`,`image`,`template`,`seo_title`,`seo_description`,`active`,`sort_order`) VALUES (11,'information','Техническая информация','Практические материалы по продукции','Обозначения, конструкция, сортамент и применение материалов из каталога. Используйте справочные материалы вместе с требованиями вашего проекта.','<p>Параметры окончательного исполнения подтверждаются технической документацией производителя и согласованной спецификацией. Для подбора направьте марку, размеры и условия эксплуатации.</p>','assets/img/documents.webp','information','Техническая информация | Торговая компания «Монополия»','Обозначения, конструкция, сортамент и применение материалов из каталога. Используйте справочные материалы вместе с требованиями вашего проекта.',1,10) ON DUPLICATE KEY UPDATE `slug`=VALUES(`slug`),`title`=VALUES(`title`),`h1`=VALUES(`h1`),`lead`=VALUES(`lead`),`body_html`=VALUES(`body_html`),`image`=VALUES(`image`),`template`=VALUES(`template`),`seo_title`=VALUES(`seo_title`),`seo_description`=VALUES(`seo_description`),`active`=VALUES(`active`),`sort_order`=VALUES(`sort_order`);
INSERT INTO `pages` (`id`,`slug`,`title`,`h1`,`lead`,`body_html`,`image`,`template`,`seo_title`,`seo_description`,`active`,`sort_order`) VALUES (12,'calculators','Калькуляторы материалов','Предварительный расчет количества и массы','Оцените теоретическую массу стального проката и площадь профилированных листов. Расчет помогает подготовить заявку; отгрузочные значения уточняются по спецификации.','<h2>Как пользоваться расчетом</h2><p>Введите размеры в указанных единицах и количество. Для стальных изделий используется расчетная плотность 7 850 кг/м³. Результат является теоретическим: фактическая масса зависит от допуска размеров и исполнения.</p><h2>Транспортные расходы</h2><p>Стоимость автомобильной или железнодорожной перевозки зависит от маршрута, массы, габаритов и условий выдачи. Для расчета доставки направьте заявку с адресом объекта. На сайте не используются устаревшие тарифные таблицы.</p>','','calculators','Калькуляторы материалов | Торговая компания «Монополия»','Оцените теоретическую массу стального проката и площадь профилированных листов. Расчет помогает подготовить заявку; отгрузочные значения уточняются по спецификации.',1,11) ON DUPLICATE KEY UPDATE `slug`=VALUES(`slug`),`title`=VALUES(`title`),`h1`=VALUES(`h1`),`lead`=VALUES(`lead`),`body_html`=VALUES(`body_html`),`image`=VALUES(`image`),`template`=VALUES(`template`),`seo_title`=VALUES(`seo_title`),`seo_description`=VALUES(`seo_description`),`active`=VALUES(`active`),`sort_order`=VALUES(`sort_order`);
INSERT INTO `pages` (`id`,`slug`,`title`,`h1`,`lead`,`body_html`,`image`,`template`,`seo_title`,`seo_description`,`active`,`sort_order`) VALUES (13,'sitemap','Карта сайта','Все разделы сайта','Быстрый переход к товарным направлениям и полезной информации о поставках.','','','sitemap','Карта сайта | Торговая компания «Монополия»','Быстрый переход к товарным направлениям и полезной информации о поставках.',1,12) ON DUPLICATE KEY UPDATE `slug`=VALUES(`slug`),`title`=VALUES(`title`),`h1`=VALUES(`h1`),`lead`=VALUES(`lead`),`body_html`=VALUES(`body_html`),`image`=VALUES(`image`),`template`=VALUES(`template`),`seo_title`=VALUES(`seo_title`),`seo_description`=VALUES(`seo_description`),`active`=VALUES(`active`),`sort_order`=VALUES(`sort_order`);
INSERT INTO `pages` (`id`,`slug`,`title`,`h1`,`lead`,`body_html`,`image`,`template`,`seo_title`,`seo_description`,`active`,`sort_order`) VALUES (14,'404','Страница не найдена','Эта страница не найдена','Возможно, адрес изменился. Найдите нужную продукцию в каталоге или отправьте наименование через форму заявки.','','','error','Страница не найдена | Торговая компания «Монополия»','Возможно, адрес изменился. Найдите нужную продукцию в каталоге или отправьте наименование через форму заявки.',1,13) ON DUPLICATE KEY UPDATE `slug`=VALUES(`slug`),`title`=VALUES(`title`),`h1`=VALUES(`h1`),`lead`=VALUES(`lead`),`body_html`=VALUES(`body_html`),`image`=VALUES(`image`),`template`=VALUES(`template`),`seo_title`=VALUES(`seo_title`),`seo_description`=VALUES(`seo_description`),`active`=VALUES(`active`),`sort_order`=VALUES(`sort_order`);
INSERT INTO `pages` (`id`,`slug`,`title`,`h1`,`lead`,`body_html`,`image`,`template`,`seo_title`,`seo_description`,`active`,`sort_order`) VALUES (15,'information/sertifikaty-na-profnastil','Сертификаты на профлист','Сертификаты на профлист','Справочный материал из технической библиотеки торговой компании «Монополия».','<div><div>Сертификаты на профнастил <ul><li>Санитарно-эпидемиологическое заключение на: - Стальные профилированные листы - металлочерепица - комплектующие изделия - профили - элементы конструкционные гнутоштампованные - фасадные кассеты с защитно-декоративным полимерным покрытием. <a href="assets/documents/1__3d23c0607bf6960c485f7ddb.pdf" rel="noopener" target="_blank">Скачать </a></li><li>Сертификат соответствия на:- Профили стальные холодногнутые с защитно-декоративным полимерным покрытием с волновым очертанием и комплектующие изделия к нимИзготовитель - "Металл Профиль" , Республика Беларусь <a href="assets/img/products/sootv1__51992a7996960fb04ff549e1.jpg" rel="noopener" target="_blank">Скачать </a></li></ul><h2>Сертификаты на профнастил: </h2><p><a href="assets/img/products/sez1__81c9c43e6090d082b80a8493.jpg" rel="noopener" target="_blank"><img alt="Санитарно-эпидемиологическое заключение" loading="lazy" src="assets/img/products/sez1__81c9c43e6090d082b80a8493.jpg"/></a><a href="assets/img/products/sez2__8f25843d28d484a3e7e54f14.jpg" rel="noopener" target="_blank"><img alt="Санитарно-эпидемиологическое заключение" loading="lazy" src="assets/img/products/sez2__8f25843d28d484a3e7e54f14.jpg"/></a></p><p><a href="assets/img/products/sootv1__51992a7996960fb04ff549e1.jpg" rel="noopener" target="_blank"><img alt="Сертификат соответствия" loading="lazy" src="assets/img/products/sootv1__51992a7996960fb04ff549e1.jpg"/></a><a href="assets/img/products/sootv2__937d859f15c8c21553c1682e.jpg" rel="noopener" target="_blank"><img alt="Сертификат соответствия" loading="lazy" src="assets/img/products/sootv2__937d859f15c8c21553c1682e.jpg"/></a><a href="assets/img/products/sootv3__608e17c68a728369e0e48591.jpg" rel="noopener" target="_blank"><img alt="Сертификат соответствия" loading="lazy" src="assets/img/products/sootv3__608e17c68a728369e0e48591.jpg"/></a><a href="assets/img/products/sootv4__93e720af4a77ee3f54ec83ff.jpg" rel="noopener" target="_blank"><img alt="Сертификат соответствия" loading="lazy" src="assets/img/products/sootv4__93e720af4a77ee3f54ec83ff.jpg"/></a></p></div></div>','assets/img/documents.webp','article','Сертификаты на профлист | Торговая компания «Монополия»','Сертификаты на профлист. Технические сведения и подбор продукции по спецификации.',1,14) ON DUPLICATE KEY UPDATE `slug`=VALUES(`slug`),`title`=VALUES(`title`),`h1`=VALUES(`h1`),`lead`=VALUES(`lead`),`body_html`=VALUES(`body_html`),`image`=VALUES(`image`),`template`=VALUES(`template`),`seo_title`=VALUES(`seo_title`),`seo_description`=VALUES(`seo_description`),`active`=VALUES(`active`),`sort_order`=VALUES(`sort_order`);
INSERT INTO `pages` (`id`,`slug`,`title`,`h1`,`lead`,`body_html`,`image`,`template`,`seo_title`,`seo_description`,`active`,`sort_order`) VALUES (16,'information/vidy-profnastila','Виды профнастила','Виды профнастила','Справочный материал из технической библиотеки торговой компании «Монополия».','','assets/img/documents.webp','article','Виды профнастила | Торговая компания «Монополия»','Виды профнастила. Технические сведения и подбор продукции по спецификации.',1,15) ON DUPLICATE KEY UPDATE `slug`=VALUES(`slug`),`title`=VALUES(`title`),`h1`=VALUES(`h1`),`lead`=VALUES(`lead`),`body_html`=VALUES(`body_html`),`image`=VALUES(`image`),`template`=VALUES(`template`),`seo_title`=VALUES(`seo_title`),`seo_description`=VALUES(`seo_description`),`active`=VALUES(`active`),`sort_order`=VALUES(`sort_order`);
INSERT INTO `pages` (`id`,`slug`,`title`,`h1`,`lead`,`body_html`,`image`,`template`,`seo_title`,`seo_description`,`active`,`sort_order`) VALUES (17,'information/assortiment-produktsii','Ассортимент продукции','Ассортимент продукции','Справочный материал из технической библиотеки торговой компании «Монополия».','','assets/img/documents.webp','article','Ассортимент продукции | Торговая компания «Монополия»','Ассортимент продукции. Технические сведения и подбор продукции по спецификации.',1,16) ON DUPLICATE KEY UPDATE `slug`=VALUES(`slug`),`title`=VALUES(`title`),`h1`=VALUES(`h1`),`lead`=VALUES(`lead`),`body_html`=VALUES(`body_html`),`image`=VALUES(`image`),`template`=VALUES(`template`),`seo_title`=VALUES(`seo_title`),`seo_description`=VALUES(`seo_description`),`active`=VALUES(`active`),`sort_order`=VALUES(`sort_order`);
INSERT INTO `pages` (`id`,`slug`,`title`,`h1`,`lead`,`body_html`,`image`,`template`,`seo_title`,`seo_description`,`active`,`sort_order`) VALUES (18,'information/37-pravka-i-gibka-armatury','Правка и гибка арматуры','Правка и гибка арматуры','Справочный материал из технической библиотеки торговой компании «Монополия».','<div><div><h4>Правка и гибка арматуры </h4><p><img alt="Схема и конструкция продукции" loading="lazy" src="assets/img/products/m_1_1__425dfecc8edfdd43795bcf9f.jpg"/><img alt="Схема и конструкция продукции" loading="lazy" src="assets/img/products/m_1_2__706f512cbec47b2b8a1ee444.jpg"/><img alt="Схема и конструкция продукции" loading="lazy" src="assets/img/products/m_1_3__84bd60aa59a726b3b474c8ad.jpg"/></p><p><strong>Правка и гибка арматуры на станках Format S (Италия) и G-Star 16E (Греция) </strong></p><p>Гибочно-профильные станки с числовым программным управлением FORMAT S и G-Star 16E предназначены для выполнения таких операций, как резка и правка арматурной стали, а также <strong>гибка арматуры </strong>и профилирование фигур любой сложности из стальной арматурной проволоки и арматурной стали диаметром до 16 мм. </p><p><strong>Продукция </strong></p><ul><li>мерные стержни из арматурной стали, выполненные в соответствии с требованием заказчика </li><li>скобы, хомуты, петли, анкера и другие закладные детали любой сложности из арматурной стали по размерам заказчика. </li></ul><p><strong>Технические характеристики </strong></p><table><tbody><tr><td></td><td><p>Format S </p></td><td><p>G-Star 16E </p></td></tr><tr><td><p>Диаметр арматуры </p></td><td><p>4-12 мм </p></td><td><p>6-16 мм </p></td></tr><tr><td><p>Угол изгиба (max) </p></td><td><p>± 180º </p></td><td><p>± 180º </p></td></tr><tr><td><p>Точность резки </p></td><td><p>± 1 мм </p></td><td><p>± 0,5 мм </p></td></tr><tr><td><p>Точность гибки </p></td><td><p>± 1º </p></td><td><p>± 0,5º </p></td></tr><tr><td><p>Длина стороны (max) </p></td><td><p>2 000 мм </p></td><td><p>1 800 мм </p></td></tr></tbody></table><p><strong>Производительность: </strong>уникальная система MEP SYSTEM позволяет проводить правку и протяжку арматурного проката со скоростью 90 метров в минуту. Переналадка с одного диаметра арматуры на другой происходит посредством электронного управления. Станки оборудованы специальными устройствами для бесперебойной работы в условиях российских зим и допускают безостановочную работу при температурах воздуха до 18° ниже нуля. </p><p><strong>Качество: </strong>автоматическая коррекция углов изгиба обеспечивает точность геометрической формы изделий. ПК MULTIBOX SYSTEM позволяет настраивать один из 9 режимов обработки на один диаметр арматуры в зависимости от класса и качества проката. </p><p><strong>Дополнительные преимущества: </strong><br/>фигурная и объемная гибка, позволяющая изготавливать сложные декоративные изделия, которые могут применяться в качестве элементов решеток, ворот, оград и т.д. </p><p><strong>Ваши выгоды </strong></p><ul><li>Весомая минимизация металлоотходов </li><li>Высокая точность и повторяемость деталей </li><li>Значительная оптимизация складских остатков </li><li>Ускорение производственного цикла </li><li>Повышение экономической эффективности </li><li>Снижение себестоимости строительства и издержек производства </li></ul></div></div>','assets/img/documents.webp','article','Правка и гибка арматуры | Торговая компания «Монополия»','Правка и гибка арматуры. Технические сведения и подбор продукции по спецификации.',1,17) ON DUPLICATE KEY UPDATE `slug`=VALUES(`slug`),`title`=VALUES(`title`),`h1`=VALUES(`h1`),`lead`=VALUES(`lead`),`body_html`=VALUES(`body_html`),`image`=VALUES(`image`),`template`=VALUES(`template`),`seo_title`=VALUES(`seo_title`),`seo_description`=VALUES(`seo_description`),`active`=VALUES(`active`),`sort_order`=VALUES(`sort_order`);
INSERT INTO `pages` (`id`,`slug`,`title`,`h1`,`lead`,`body_html`,`image`,`template`,`seo_title`,`seo_description`,`active`,`sort_order`) VALUES (19,'information/38-pravka-i-rezka-armatury','Правка и резка арматуры','Правка и резка арматуры','Справочный материал из технической библиотеки торговой компании «Монополия».','<div><div><h4>Правка и резка арматуры </h4><p><img alt="Схема и конструкция продукции" loading="lazy" src="assets/img/products/m_2_1__6a137d253609a11a60d751a7.jpg"/><img alt="Схема и конструкция продукции" loading="lazy" src="assets/img/products/m_2_2__668e7fe645515ab1bbdbd1c9.jpg"/></p><p><strong>Размотка, правка и резка арматуры Ø 4-16 мм на станках модель MELC 16x2 и 16х4 PLC/12 (Греция) </strong></p><p><strong>Качество: </strong>минимальное напряжение металла, полное отсутствие следов на арматуре, высокое качество выпрямления. </p><p><strong>Дополнительные преимущества: </strong>измерение длины осуществляется с помощью электронного вращающегося кодового датчика, что гарантирует высокую точность. Возможность упаковки изделий в связки. </p><p><strong>Ваши выгоды </strong></p><ul><li>Минимизация металлоотходов </li><li>Высокая точность и повторяемость деталей </li><li>Значительная оптимизация складских остатков </li><li>Ускорение производственного цикла </li><li>Повышение экономической эффективности </li></ul><p><strong>Технические характеристики </strong></p><table><tbody><tr><td><p>диапазон диаметра арматуры </p></td><td><p>Ø4-Ø16 мм </p></td></tr><tr><td><p>макс. длина отреза </p></td><td><p>12.000 мм </p></td></tr><tr><td><p>мин. длина отреза </p></td><td><p>1000 мм </p></td></tr><tr><td><p>точность резки </p></td><td><p>3 мм </p></td></tr></tbody></table></div></div>','assets/img/documents.webp','article','Правка и резка арматуры | Торговая компания «Монополия»','Правка и резка арматуры. Технические сведения и подбор продукции по спецификации.',1,18) ON DUPLICATE KEY UPDATE `slug`=VALUES(`slug`),`title`=VALUES(`title`),`h1`=VALUES(`h1`),`lead`=VALUES(`lead`),`body_html`=VALUES(`body_html`),`image`=VALUES(`image`),`template`=VALUES(`template`),`seo_title`=VALUES(`seo_title`),`seo_description`=VALUES(`seo_description`),`active`=VALUES(`active`),`sort_order`=VALUES(`sort_order`);
INSERT INTO `pages` (`id`,`slug`,`title`,`h1`,`lead`,`body_html`,`image`,`template`,`seo_title`,`seo_description`,`active`,`sort_order`) VALUES (20,'information/40-proizvodstvo-kladochnoj-setki','Производство кладочной сетки','Производство кладочной сетки','Справочный материал из технической библиотеки торговой компании «Монополия».','<div><div><h4>Производство кладочной сетки </h4><p><img alt="Схема и конструкция продукции" loading="lazy" src="assets/img/products/m_4_1__1767499dabb0b7534468046c.jpg"/><img alt="Схема и конструкция продукции" loading="lazy" src="assets/img/products/m_4_2__2f8d16cb76d542384691ca6c.jpg"/></p><p><strong>Изготовление плоских армокаркасов и кладочной сетки на линии Plegmomat PLC 24-25 ET Fse 49 16x12) </strong></p><p>Оборудование предназначено для изготовления таких видов продукции, как <strong>сетка кладочная </strong>и плоские арматурные каркасы. </p><p><strong>Качество </strong>: Электронное управление приводами сварочной линии, а также встроенная система самодиагностики позволяет выпускать продукцию самого высокого качества с заданными параметрами. </p><p><strong>Дополнительные преимущества </strong>: система электронного управления позволяет настроить станок на производство сетки с различным расстоянием между поперечными прутками. Возможно изготовление сложных армокаркасов: готовое изделие - <strong>сетка кладочная </strong>с продольными и поперечными прутками разного диаметра. </p><p><strong>Ваши выгоды: </strong></p><ul><li>Сокращение производственного цикла </li><li>Сокращение затрат (сокращение ручного труда на объекте) </li><li>Весомая минимизация отходов </li><li>Повышение качества строительства </li><li>Снижение срока монтажа </li><li>Снижение себестоимости строительства и издержек производства </li></ul><p><strong>Технические характеристики </strong></p><table><tbody><tr><td><p>Диаметр арматурных стержней </p></td><td><p>4-16 мм </p></td></tr><tr><td><p>Ширина сетки, (max) </p></td><td><p>2500 мм </p></td></tr><tr><td><p>Ширина сетки, (min) </p></td><td><p>1 200 мм </p></td></tr><tr><td><p>Длина сетки, (max) </p></td><td><p>6 000 мм </p></td></tr><tr><td><p>Длина сетки, (min) </p></td><td><p>1 200 мм </p></td></tr><tr><td><p>Размер ячейки сетки </p></td><td><p>50-1000 мм </p></td></tr></tbody></table></div></div>','assets/img/documents.webp','article','Производство кладочной сетки | Торговая компания «Монополия»','Производство кладочной сетки. Технические сведения и подбор продукции по спецификации.',1,19) ON DUPLICATE KEY UPDATE `slug`=VALUES(`slug`),`title`=VALUES(`title`),`h1`=VALUES(`h1`),`lead`=VALUES(`lead`),`body_html`=VALUES(`body_html`),`image`=VALUES(`image`),`template`=VALUES(`template`),`seo_title`=VALUES(`seo_title`),`seo_description`=VALUES(`seo_description`),`active`=VALUES(`active`),`sort_order`=VALUES(`sort_order`);
INSERT INTO `pages` (`id`,`slug`,`title`,`h1`,`lead`,`body_html`,`image`,`template`,`seo_title`,`seo_description`,`active`,`sort_order`) VALUES (21,'information/41-porezka-v-razmer','Порезка в размер','Порезка в размер','Справочный материал из технической библиотеки торговой компании «Монополия».','<div><div><h4>Порезка в размер </h4><h4><img alt="Схема и конструкция продукции" loading="lazy" src="assets/img/products/m_5_1__3c1906296e083553728abbf7.jpg"/><img alt="Схема и конструкция продукции" loading="lazy" src="assets/img/products/m_5_2__75d49e5c38053c30d205ecbf.jpg"/><img alt="Схема и конструкция продукции" loading="lazy" src="assets/img/products/m_5_3__2f7eeb902354cfd862794369.jpg"/></h4><p><strong>Порезка длинного проката на ленточнопильных станках Sirius, Pegasus, Jupiter (Италия) </strong></p><p>Ленточнопильные станки, предназначенные для порезки различных типов фасонного проката из черных и цветных металлов. Возможность реза под любым углом от 0° до 60°. </p><p><strong>Основные технические характеристики SIRIUS </strong></p><p>Вес 400 кг </p><p>Габаритные размеры 800х1400х1500 мм </p><p>Главный двигатель 1,1 кВ </p><p>Скорость ленточной пилы </p><p>(стандартно) 30 и 60 м/мин </p><p>Скорость ленточной пилы </p><p>(вариатор) от 20 до 100 м/мин </p><p>Размер ленточной пилы 2700(±5) х 27 х 0,9 мм </p><p><strong>Основные технические характеристики Pegasus </strong></p><p>Вес 800 кг </p><p>Габаритные размеры 1200 х 2150 х 1600 мм </p><p>Главный двигатель 2,2 кВ </p><p>Скорость ленточной пилы от 16 до 80 м/мин </p><p>Размер ленточной пилы 4120(±5) х 34 х 1,1 мм </p><p><strong>Основные технические характеристики Jupiter </strong></p><p>Вес 1150 кг </p><p>Габаритные размеры 2600 х 1700 х 1500 мм </p><p>Главный двигатель 1,1 кВ </p><p>Скорость ленточной пилы от 20 до 100 м/мин </p><p>Размер ленточной пилы 3180(±5) х 27 х 0,9 мм </p><p><strong>Максимальные габариты используемых заготовок при резке под разными углами </strong></p><table><tbody><tr><td></td><td></td><td><p><img alt="Схема и конструкция продукции" loading="lazy" src="assets/img/products/m_5_4_1__4e3137bd3af3a3ba87b59239.jpg"/></p></td><td><p><img alt="Схема и конструкция продукции" loading="lazy" src="assets/img/products/m_5_4_2__7eafb308a4787879853b4003.jpg"/></p></td><td><p><img alt="Схема и конструкция продукции" loading="lazy" src="assets/img/products/m_5_4_3__cc2d6a582c857d20ed571a17.jpg"/></p></td><td><p><img alt="Схема и конструкция продукции" loading="lazy" src="assets/img/products/m_5_4_4__50ab5223c41bf5930644cc78.jpg"/></p></td></tr><tr><td></td><td><p><strong>угол реза </strong></p></td><td><p><strong>D </strong></p></td><td><p><strong>A x B </strong></p></td><td><p><strong>A x B </strong></p></td><td><p><strong>A x B </strong></p></td></tr><tr><td rowspan="3"><p><strong>Sirius </strong></p></td><td><p>0° </p></td><td><p>230 </p></td><td><p>230х230 </p></td><td><p>260х260 </p></td><td><p>280х170 </p></td></tr><tr><td><p>45° </p></td><td><p>175 </p></td><td><p>165х165 </p></td><td><p>145х230 </p></td><td><p>175х170 </p></td></tr><tr><td><p>60° </p></td><td><p>110 </p></td><td><p>90х90 </p></td><td><p>90х90 </p></td><td><p>110х80 </p></td></tr><tr><td rowspan="3"><p><strong>Pegasus </strong></p></td><td><p>0° </p></td><td><p>320 </p></td><td><p>320х320 </p></td><td><p>320х320 </p></td><td><p>500х320 </p></td></tr><tr><td><p>45° </p></td><td><p>320 </p></td><td><p>260х260 </p></td><td><p>260х260 </p></td><td><p>370х260 </p></td></tr><tr><td><p>60° </p></td><td><p>200 </p></td><td><p>130х130 </p></td><td><p>130х130 </p></td><td><p>240х130 </p></td></tr><tr><td rowspan="3"><p><strong>Jupiter </strong></p></td><td><p>0° </p></td><td><p>240 </p></td><td><p>240х240 </p></td><td><p>280х240 </p></td><td><p>300х220 </p></td></tr><tr><td><p>45° </p></td><td><p>200 </p></td><td><p>180х180 </p></td><td><p>160х240 </p></td><td><p>200х100 </p></td></tr><tr><td><p>60° </p></td><td><p>120 </p></td><td><p>120х120 </p></td><td><p>120х120 </p></td><td><p>110х160 </p></td></tr></tbody></table><p><strong>Ваши выгоды </strong>: </p><ul><li><p>отсутствие необходимости механической обработки торца </p></li><li><p>высокая точность реза под углом 45° и 60° </p></li><li><p>отсутствие заусенцев после резки проката </p></li><li><p>снижение затрат на металлоотходы </p></li><li><p>повышение рентабельности вашего производства </p></li></ul></div></div>','assets/img/documents.webp','article','Порезка в размер | Торговая компания «Монополия»','Порезка в размер. Технические сведения и подбор продукции по спецификации.',1,20) ON DUPLICATE KEY UPDATE `slug`=VALUES(`slug`),`title`=VALUES(`title`),`h1`=VALUES(`h1`),`lead`=VALUES(`lead`),`body_html`=VALUES(`body_html`),`image`=VALUES(`image`),`template`=VALUES(`template`),`seo_title`=VALUES(`seo_title`),`seo_description`=VALUES(`seo_description`),`active`=VALUES(`active`),`sort_order`=VALUES(`sort_order`);
INSERT INTO `pages` (`id`,`slug`,`title`,`h1`,`lead`,`body_html`,`image`,`template`,`seo_title`,`seo_description`,`active`,`sort_order`) VALUES (22,'information/42-raskroj-listovogo-prokata','Раскрой листового проката','Раскрой листового проката','Справочный материал из технической библиотеки торговой компании «Монополия».','<div><div><h4>Раскрой листового проката </h4><p><img alt="Схема и конструкция продукции" loading="lazy" src="assets/img/products/m_6_1_1__9536a73b66f4c58c094b9e31.jpg"/><img alt="Схема и конструкция продукции" loading="lazy" src="assets/img/products/m_6_1_2__72d0aac344a454b19043ffd1.jpg"/><img alt="Схема и конструкция продукции" loading="lazy" src="assets/img/products/m_6_1_3__e2af20485460dff5e7e9ee26.jpg"/></p><p><img alt="Схема и конструкция продукции" loading="lazy" src="assets/img/products/m_6_1_4__9236d3a4655d89837a7ce243.jpg"/><img alt="Схема и конструкция продукции" loading="lazy" src="assets/img/products/m_6_1_5__183448ca108f589e7711adb7.jpg"/></p><p><strong>Раскрой плоского проката на гильотинных ножницах COLGAR CI-34-TR COLGAR CI-34-TR (Италия) </strong></p><p>Назначение оборудования: раскрой и изготовление заготовок из плоского проката. <br/><strong>Основные технические характеристики </strong></p><table><tbody><tr><td>Описание </td><td><p>Показатель </p></td></tr><tr><td rowspan="2"><p>Макс. толщина разрезаемого листа </p></td><td><p>Ст.3-20мм </p></td></tr><tr><td><p>Ст.09Г2С-16мм </p></td></tr><tr><td><p>Ширина реза </p></td><td><p>До 3 м </p></td></tr><tr><td><p>Качество поверхности торца </p></td><td><p>высокое </p></td></tr><tr><td><p>Производительность </p></td><td><p>10/27 резов/мин </p></td></tr><tr><td><p>Точность линии реза, допуск </p></td><td><p>0,2мм </p></td></tr></tbody></table><p>Современная система контроля с ЧПУ, высочайшая производительность. </p><p><strong>Ваши выгоды: </strong></p><ul><li>Изготовление заготовок из листового проката требуемых размеров </li><li>Снижение затрат на металлоотходы </li><li>Повышение производительности труда и рентабельности вашего производства </li></ul><p><strong>Линия поперечной резки рулонного листового проката CAMU RDC 1500/6 (Италия) </strong><br/>Предназначены для резки рулонного листового проката толщиной от 2 мм до 6 мм с непрерывной чистовой правкой <br/>полосы и отрезкой летучими ножницами. </p><p><strong>Основные технические характеристики </strong></p><table><tbody><tr><td>Материал </td><td><p>Сталь холоднокатаная, горячекатаная в рулонах, макс. предел прочности 700 N/mm2/ </p></td></tr><tr><td><p>Толщина полосы </p></td><td><p>2 – 6 мм </p></td></tr><tr><td><p>Макс. рабочая скорость </p></td><td><p>50 м/мин (при длине листов 6 м) </p></td></tr><tr><td><p>Принцип работы линии </p></td><td><p>Непрерывный с чистовой правкой полосы и отрезкой летучими ножницами. </p></td></tr><tr><td><p>Ширина мерных листов </p></td><td><p>500 – 1550 мм </p></td></tr><tr><td><p>Точность резки по длине </p></td><td><p>± (1-1,5)мм в зависимости от толщины листа, макс. ± 1,5 мм для толщины 6 мм </p></td></tr><tr><td><p>Длина мерных листов </p></td><td><p>500 – 7000 мм </p></td></tr><tr><td><p>Макс. вес пачки листов </p></td><td><p>5000 кг </p></td></tr><tr><td><p>Макс. высота пачки листов </p></td><td><p>400 мм </p></td></tr></tbody></table><p><strong>Ваши выгоды: </strong></p><ul><li>Минимизация металлоотходов </li><li>Идеальное качество поверхности листа </li><li>Поставка листового проката требуемых размеров в любом объеме </li><li>Изготовление и поставка проката в кратчайшие сроки </li></ul></div></div>','assets/img/documents.webp','article','Раскрой листового проката | Торговая компания «Монополия»','Раскрой листового проката. Технические сведения и подбор продукции по спецификации.',1,21) ON DUPLICATE KEY UPDATE `slug`=VALUES(`slug`),`title`=VALUES(`title`),`h1`=VALUES(`h1`),`lead`=VALUES(`lead`),`body_html`=VALUES(`body_html`),`image`=VALUES(`image`),`template`=VALUES(`template`),`seo_title`=VALUES(`seo_title`),`seo_description`=VALUES(`seo_description`),`active`=VALUES(`active`),`sort_order`=VALUES(`sort_order`);
INSERT INTO `pages` (`id`,`slug`,`title`,`h1`,`lead`,`body_html`,`image`,`template`,`seo_title`,`seo_description`,`active`,`sort_order`) VALUES (23,'information/43-antikorrozijnaya-obrabotka','Антикоррозийная обработка','Антикоррозийная обработка','Справочный материал из технической библиотеки торговой компании «Монополия».','<div><div><h4>Антикоррозийная обработка </h4><p><img alt="Схема и конструкция продукции" loading="lazy" src="assets/img/products/m_7_1_1__29a5a5b224c9a7c05c8c3c74.jpg"/><img alt="Схема и конструкция продукции" loading="lazy" src="assets/img/products/m_7_1_2__77fe48e78d12aaaa6d0c00dc.jpg"/><img alt="Схема и конструкция продукции" loading="lazy" src="assets/img/products/m_7_1_3__320b98cdfab8c6879000a1d1.jpg"/></p><p><img alt="Схема и конструкция продукции" loading="lazy" src="assets/img/products/m_7_1_4__dd80c3df4ca0a0a461160053.jpg"/></p><p><strong>Антикоррозийная обработка прокатных листов и профилей на автоматической линии RÖSLER (Германия) </strong></p><p>Производитель линии – немецкая фирма «Рёслер», мировой лидер в сфере обработки поверхностей. <br/><br/><strong>Материал: </strong><br/>покрытый ржавчиной или окалиной листовой металл, профили, трубы или сварочные конструкции, как крупно, так и малогабаритные. <br/><br/><strong>Качество: </strong><br/>Электропроводная грунтовка позволяет после нанесения проводить электросварочные работы по металлопрокату без зачистки покрытия. Качество: степень чистоты поверхности соответствует стандартам ISO 8501-1 до Sa 2,5 и ГОСТ 9.402-2004. <br/>Защитный грунт не оказывает влияние на качество сварного шва, ему свойственна высокая адгезия, хорошая механическая стойкость, срок защиты поверхности не менее 24 мес., толщина слоя покрытия 16-30 мкм <br/><strong>Ваши выгоды: </strong></p><ul><li>Максимальная защита поверхности металла от коррозии высококачественным грунтом </li><li>Существенное улучшение качества, увеличение срока службы и надежности металлоконструкций и металлоизделий </li><li>Повышение эффективности вашего производства </li></ul><p><strong>Основные технические характеристики </strong></p><table><tbody><tr><td>Ширина проката (max) </td><td><p>2000 мм </p></td></tr><tr><td><p>Высота проката (max) </p></td><td><p>500 мм </p></td></tr><tr><td><p>Длина проката (max) </p></td><td><p>До 12000 мм </p></td></tr><tr><td><p>Толщина проката (min) </p></td><td><p>3,0 мм </p></td></tr><tr><td><p>Скорость конвейера (max) </p></td><td><p>До 3,0 м/мин. </p></td></tr></tbody></table></div></div>','assets/img/documents.webp','article','Антикоррозийная обработка | Торговая компания «Монополия»','Антикоррозийная обработка. Технические сведения и подбор продукции по спецификации.',1,22) ON DUPLICATE KEY UPDATE `slug`=VALUES(`slug`),`title`=VALUES(`title`),`h1`=VALUES(`h1`),`lead`=VALUES(`lead`),`body_html`=VALUES(`body_html`),`image`=VALUES(`image`),`template`=VALUES(`template`),`seo_title`=VALUES(`seo_title`),`seo_description`=VALUES(`seo_description`),`active`=VALUES(`active`),`sort_order`=VALUES(`sort_order`);
INSERT INTO `pages` (`id`,`slug`,`title`,`h1`,`lead`,`body_html`,`image`,`template`,`seo_title`,`seo_description`,`active`,`sort_order`) VALUES (24,'information/44-plazmennyj-raskroj-listovogo-prokata','Плазменный раскрой листового проката','Плазменный раскрой листового проката','Справочный материал из технической библиотеки торговой компании «Монополия».','<div><div><h4>Плазменный раскрой листового проката </h4><p><img alt="Схема и конструкция продукции" loading="lazy" src="assets/img/products/m_8_1_1__c2eed835ccfacaf7c4a43388.jpg"/><img alt="Схема и конструкция продукции" loading="lazy" src="assets/img/products/m_8_1_2__f720875cd085b6e554da850c.jpg"/><img alt="Схема и конструкция продукции" loading="lazy" src="assets/img/products/m_8_1_3__9ead6818f11cc80a1322de37.jpg"/></p><p><img alt="Схема и конструкция продукции" loading="lazy" src="assets/img/products/m_8_1_4__e1ed713e3ac7969a37a208c8.jpg"/><img alt="Схема и конструкция продукции" loading="lazy" src="assets/img/products/m_8_1_5__faea0c3701803f8bb5bb8de2.jpg"/><img alt="Схема и конструкция продукции" loading="lazy" src="assets/img/products/m_8_1_6__7fed473b4697d4058dccef95.jpg"/></p><p><strong>Плазменный и кислородный раскрой на автоматической линии Lineacord PCL40 (Италия) </strong></p><p>Производитель: SOITAAB Impianti S.r.l. (Италия) </p><p>Назначение оборудования: изготовление деталей и заготовок из листовой стали любых марок. </p><p><strong>Основные технические характеристики </strong></p><table><tbody><tr><td><p>Ширина листа (mах) </p></td><td><p>3000мм </p></td></tr></tbody><tbody><tr><td><p>Длина листа (mах) </p></td><td><p>13000мм </p></td></tr></tbody><tbody><tr><td><p>Точность позиционирования </p></td><td><p>±0,2мм на 10 метрах </p></td></tr></tbody><tbody><tr><td><p>Скорость позиционирования </p></td><td><p>20000мм/мин </p></td></tr></tbody><tbody><tr><td rowspan="2"><p>Толщина обрабатываемого </p><p>проката </p></td><td><p>для плазменной резки-32мм </p></td></tr><tr><td><p>для кислородной резки-250мм </p></td></tr></tbody><tbody><tr><td><p>Допуски диагональной точности </p></td><td><p>Соответствуют стандартам </p></td></tr></tbody></table><p>Качество: высокое качество поверхности реза, малая ширина реза. Изготовление заготовок любых геометрических форм. Применение плазменной резки позволяет отказаться от последующей обработки кромок для сварки. </p><p>Ваши выгоды: </p><ul><li>Высокотехнологичная плазменная резка позволяет ускорить производственный цикл: стальные заготовки и детали поставляются предприятию для непосредственного использования </li><li>На линии плазменной резки возможно изготовление деталей сложной формы, в том числе с отверстиями, в кратчайшие сроки </li></ul><p>Дополнительные преимущества: возможность раскроя листа большой толщины. </p></div></div>','assets/img/documents.webp','article','Плазменный раскрой листового проката | Торговая компания «Монополия»','Плазменный раскрой листового проката. Технические сведения и подбор продукции по спецификации.',1,23) ON DUPLICATE KEY UPDATE `slug`=VALUES(`slug`),`title`=VALUES(`title`),`h1`=VALUES(`h1`),`lead`=VALUES(`lead`),`body_html`=VALUES(`body_html`),`image`=VALUES(`image`),`template`=VALUES(`template`),`seo_title`=VALUES(`seo_title`),`seo_description`=VALUES(`seo_description`),`active`=VALUES(`active`),`sort_order`=VALUES(`sort_order`);
INSERT INTO `pages` (`id`,`slug`,`title`,`h1`,`lead`,`body_html`,`image`,`template`,`seo_title`,`seo_description`,`active`,`sort_order`) VALUES (25,'information/45-proizvodstvo-pvl','Производство ПВЛ','Производство ПВЛ','Справочный материал из технической библиотеки торговой компании «Монополия».','<div><div><h4>Производство ПВЛ </h4><p><img alt="Схема и конструкция продукции" loading="lazy" src="assets/img/products/m_9_1_1__9dba568c5b6fbfba8254fe77.jpg"/><img alt="Схема и конструкция продукции" loading="lazy" src="assets/img/products/m_9_1_2__7e8ea0889c92ae4051de29bf.jpg"/><img alt="Схема и конструкция продукции" loading="lazy" src="assets/img/products/m_9_1_3__0ea7943d39fda6c52d710a98.jpg"/></p><p><strong>Изготовление ПВЛ на кривошипно-шатунном прессе ЕТ 2145-07 </strong></p><p>Назначение оборудования: производство просечновытяжного листа. Качество продукции соответствует ТУ 0971-001-44028369-2006. </p><table><tbody><tr><td colspan="2"><p><strong>Основные технические характеристики </strong></p></td></tr><tr><td><p>Толщина обрабатываемого листа </p></td><td><p>1-6 мм </p></td></tr><tr><td><p>Ширина обрабатываемого листа (mах) </p></td><td><p>1250 мм </p></td></tr><tr><td><p>Длина (min) </p></td><td><p>215 мм </p></td></tr><tr><td><p>Допустимая неплоскостность на 1м длины </p></td><td><p>12 мм </p></td></tr><tr><td><p>Качество поверхности торца </p></td><td><p>высокое </p></td></tr><tr><td><p>Производительность </p></td><td><p>10/27 резов/мин </p></td></tr><tr><td><p>Точность линии реза, допуск </p></td><td><p>0,2 мм </p></td></tr></tbody></table><p>Преимущества ПВЛ: </p><ul><li><p>Лист <strong>ПВЛ </strong>на 80% легче по сравнению с цельным листом аналогичных габаритных размеров </p></li><li>Поверхность ПВЛ и его высокие показатели жесткости, а также способность к самоочищению от грязи, породы, снега и влаги делает его идеальным материалом для использования в качестве настила и ограждений эстетичного внешнего вида с повышенными эксплуатационными характеристиками и значительной экономией металла. </li><li>Листы <strong>ПВЛ </strong>предназначены для различных целей в машиностроении, промышленном и гражданском строительстве (устройства настилов, площадок и ступеней маршевых лестниц в производственных зданиях и сооружениях), эксплуатируемых в районах с расчетной температурой -65°С и выше. </li></ul></div></div>','assets/img/documents.webp','article','Производство ПВЛ | Торговая компания «Монополия»','Производство ПВЛ. Технические сведения и подбор продукции по спецификации.',1,24) ON DUPLICATE KEY UPDATE `slug`=VALUES(`slug`),`title`=VALUES(`title`),`h1`=VALUES(`h1`),`lead`=VALUES(`lead`),`body_html`=VALUES(`body_html`),`image`=VALUES(`image`),`template`=VALUES(`template`),`seo_title`=VALUES(`seo_title`),`seo_description`=VALUES(`seo_description`),`active`=VALUES(`active`),`sort_order`=VALUES(`sort_order`);
INSERT INTO `pages` (`id`,`slug`,`title`,`h1`,`lead`,`body_html`,`image`,`template`,`seo_title`,`seo_description`,`active`,`sort_order`) VALUES (26,'information/46-izgotovlenie-zakladnykh-detalej','Изготовление закладных деталей','Изготовление закладных деталей','Справочный материал из технической библиотеки торговой компании «Монополия».','<div><div><h4>Изготовление закладных деталей </h4><p><img alt="Схема и конструкция продукции" loading="lazy" src="assets/img/products/m_10_1_1__800f6f7fefb0337ce76848ab.jpg"/><img alt="Схема и конструкция продукции" loading="lazy" src="assets/img/products/m_10_1_2__01f621de36a914b2a46e8113.jpg"/><img alt="Схема и конструкция продукции" loading="lazy" src="assets/img/products/m_10_1_3__4cf2a2789ac88b6563b1e48f.jpg"/></p><p><img alt="Схема и конструкция продукции" loading="lazy" src="assets/img/products/m_10_1_4__16bfff39aedde220b0affbe3.jpg"/><img alt="Схема и конструкция продукции" loading="lazy" src="assets/img/products/m_10_1_5__be7ba52570d85566b5198618.jpg"/><img alt="Схема и конструкция продукции" loading="lazy" src="assets/img/products/m_10_1_6__925be95f201b500a3aa7df9b.jpg"/></p><p><strong>Изготовление закладных деталей </strong></p><p>Гильотина COLGAR и линия плазменного и кислородного раскроя Lineacord позволяют изготавливать плоские закладные детали из листовой стали с отклонением от плоскостности до 3 мм (по ГОСТ 10922-90 п. 2.4) и предельными отклонениями линейных размеров закладных деталей в соответствии с таблицей. В зависимости от серии, вида элемента, назначения и положения в конструкции закладные детали могут иметь различную форму: как простую (прямоугольную, квадратную), так и сложную (круглую, ступенчатую, полукруглую, многогранную, с внутренними отверстиями). </p><table><tbody><tr><td rowspan="2"><p>Длина и ширина плоского элемента закладного изделия, мм </p></td><td colspan="10"><p>Предельные отклонения размеров изделия, применяемых в железобетонных конструкциях, класс точности, применяемое оборудование </p></td></tr><tr><td><p>5 </p></td><td><p>оборудование </p></td><td><p>6 </p></td><td><p>оборудование </p></td><td><p>7 </p></td><td><p>оборудование </p></td><td><p>8 </p></td><td><p>оборудование </p></td><td><p>монолит </p></td><td><p>оборудование </p></td></tr><tr><td><p>до 250 включ. </p></td><td><p>±1,5 </p></td><td><p>гильотина </p><p>толщ. до 16 мм </p><p>плазма/ </p><p>кислород </p></td><td><p>±2,5 </p></td><td><p>гильотина </p><p>плазма/ </p><p>кислород </p></td><td><p>±4,0 </p></td><td><p>гильотина </p><p>плазма/ </p><p>кислород </p></td><td><p>±6,0 </p></td><td><p>гильотина </p><p>плазма/ </p><p>кислород </p></td><td><p>±6,0 </p></td><td><p>гильотина </p><p>плазма/ </p><p>кислород </p></td></tr><tr><td><p>св.250 до 500 </p></td><td><p>±2,0 </p></td><td><p>гильотина </p><p>плазма/ </p><p>кислород </p></td><td><p>±3,0 </p></td><td><p>гильотина </p><p>плазма/ </p><p>кислород </p></td><td><p>±5,0 </p></td><td><p>гильотина </p><p>плазма/ </p><p>кислород </p></td><td><p>±8,0 </p></td><td><p>гильотина </p><p>плазма/ </p><p>кислород </p></td><td><p>±8,0 </p></td><td><p>гильотина </p><p>плазма/ </p><p>кислород </p></td></tr><tr><td><p>св. 500 </p></td><td><p>±2,5 </p></td><td><p>гильотина </p><p>плазма/ </p><p>кислород </p></td><td><p>±4,0 </p></td><td><p>гильотина </p><p>плазма/ </p><p>кислород </p></td><td><p>±6,5 </p></td><td><p>гильотина </p><p>плазма/ </p><p>кислород </p></td><td><p>±10,5 </p></td><td><p>гильотина </p><p>плазма/ </p><p>кислород </p></td><td><p>±10,5 </p></td><td><p>гильотина </p><p>плазма/ </p><p>кислород </p></td></tr></tbody></table><p>Примечание: данная таблица составлена в соответствии с требованиями ГОСТ 10922-90 (2003) </p><p><strong>Максимальная толщина листового проката при изготовлении закладных деталей: </strong></p><table><tbody><tr><td><p>На г1ильотине </p></td><td><p>20 мм </p></td></tr><tr><td><p>Кислородная резка </p></td><td><p>100 мм </p></td></tr><tr><td><p>Плазменная резка </p></td><td><p>50 мм </p></td></tr></tbody></table></div></div>','assets/img/documents.webp','article','Изготовление закладных деталей | Торговая компания «Монополия»','Изготовление закладных деталей. Технические сведения и подбор продукции по спецификации.',1,25) ON DUPLICATE KEY UPDATE `slug`=VALUES(`slug`),`title`=VALUES(`title`),`h1`=VALUES(`h1`),`lead`=VALUES(`lead`),`body_html`=VALUES(`body_html`),`image`=VALUES(`image`),`template`=VALUES(`template`),`seo_title`=VALUES(`seo_title`),`seo_description`=VALUES(`seo_description`),`active`=VALUES(`active`),`sort_order`=VALUES(`sort_order`);
INSERT INTO `pages` (`id`,`slug`,`title`,`h1`,`lead`,`body_html`,`image`,`template`,`seo_title`,`seo_description`,`active`,`sort_order`) VALUES (27,'information/933-sortovoj-prokat','Сортовой прокат','Сортовой прокат','Справочный материал из технической библиотеки торговой компании «Монополия».','<div><div><p>Сортовой прокат </p><p><img alt="m 13 1 1" loading="lazy" src="assets/img/products/m_13_1_1__70ab621f6c0c4c04cb20359b.jpg"/><img alt="m 13 1 2" loading="lazy" src="assets/img/products/m_13_1_2__c02e232268d15ad3c9dc938e.jpg"/><img alt="m 13 1 3" loading="lazy" src="assets/img/products/m_13_1_3__f4922478a48e9e1e445362ad.jpg"/></p><p>К <strong>сортовому прокату </strong>относятся следующие виды металлопроката: </p><ul><li><strong>Круг; </strong></li><li><strong>Квадрат; </strong></li><li><strong>Шестигранник; </strong></li><li><strong>Полоса. </strong></li></ul><p><strong>Прокат стальной горячекатаный круглый ГОСТ 2590-88 </strong></p><p>Стандарт распространяется на стальной горячекатаный прокат круглого сечения диаметром от 5 до 270 мм включительно. </p><p>По прочности прокат подразделяют: </p><ul><li>А - высокой точности; </li><li>Б - повышенной точности; </li><li>В - обычной точности. </li></ul><p>Прокат диаметром до 9 мм изготовляют в мотках, свыше 9 мм — в прутках. </p><p>Круги изготавливают как из рядовых сталей: ст3, ст2, ст5 и т.д., так и из низколегированных: ст09Г2С, 15ХСНД и т.п., а также из конструкционных ст10, ст20, ст35, ст45, ст40Х, ст30хгса и нержавеющих сталей. </p><p>Используется круглый прокат для армирования железобетона, его применяют в качестве заготовок для производства труб, для изготовления деталей в машиностроении и станкостроении, для конструирования железнодорожного крепежа, для производства мелющих шаров, а также в качестве декоративных элементов в оградах и других бытовых конструкциях. </p><p><strong>Прокат стальной горячекатаный квадратный ГОСТ 2591-88 </strong></p><p>Стандарт распространяется на стальной горячекатаный прокат квадратного сечения с размером сторон от 6 до 200 мм включительно. </p><p>По точности прокат изготовляют: </p><ul><li>Б - повышенной точности; </li><li>В - обычной точности. </li></ul><p>Квадратная сталь размером 5 мм и выше изготавливается в прутках, размером менее 5 мм - в мотках. </p><p>В зависимости от назначения прутки изготавливаются: </p><ul><li>мерной длины; </li><li>кратной мерной длины; </li><li>мерной длины с остатком до 15%; </li><li>кратной мерной длины с остатком до 15% </li></ul><p>Качество стали, используемой для изготовления стального квадрата, зависит от длины квадрата. Это может быть: </p><ul><li>углеродистая сталь обычного качества или низколегированная сталь – для квадрата длиной от 2 до 12 м; </li><li>качественная углеродистая или легированная сталь – для квадрата со стороной от 2 до 6 м; </li><li>высоколегированная сталь – для квадратов от 1,5 до 6 м длиной. </li></ul><p>Используется квадратный прокат для изготовления деталей в авто- и сельхозмашиностроении, станкостроении, в промышленном и гражданском строительстве, в бытовых конструкциях. </p><p><strong>Прокат стальной </strong><strong>горячекатаный шестигранный ГОСТ 2879-88 </strong></p><p>Стандарт распространяется на прокат стальной горячекатаный шестигранного сечения диаметром вписанного круга от 8 мм до 100 мм включительно. <br/>По точности прокатки прокат изготовляют: </p><ul><li>Б – повышенной точности; </li><li>В – обычной точности. </li></ul><p>Шестигранник изготовляется из углеродистой, легированной, высоколегированной горячекатаной сталей. </p><p>Используются шестигранники стальные для изготовления крепежных изделий (болтов, гаек и т.п.), широко применяют в машиностроении для изготовления различных частей механизмов и инструмента. </p><p><strong>Полоса стальная горячекатаная ГОСТ 103-76 </strong></p><p>Стандарт распространяется на стальную горячекатаную полосу общего назначения и стальную полосу для гаек шириной от 11 до 200мм и толщиной от 4 до 60мм. </p><p>Полосы изготовляют длиной: </p><ul><li>от 3 до 10 м — из углеродистой стали обыкновенного качества, низколегированной и фосфористой; </li><li>от 2 до 6 м — из углеродистой качественной и легированной стали. </li></ul><p>В зависимости от назначения полосы изготовляют: </p><ul><li>мерной длины; </li><li>кратной мерной длины; </li><li>мерной длины с остатком не более 15% массы партии; </li><li>кратной мерной длины с остатком не более 15% массы партии; </li><li>немерной длины. </li></ul><p>Полоса стальная предназначена для изготовления металлоконструкций, гнутых профилей (уголок, швеллер), а также для изготовления рессор и режущих инструментов (резцы и др). Полоса стальная используется в строительстве — как элемент-деталь строительных работ и для декоративной внешней отделки зданий. </p></div></div>','assets/img/documents.webp','article','Сортовой прокат | Торговая компания «Монополия»','Сортовой прокат. Технические сведения и подбор продукции по спецификации.',1,26) ON DUPLICATE KEY UPDATE `slug`=VALUES(`slug`),`title`=VALUES(`title`),`h1`=VALUES(`h1`),`lead`=VALUES(`lead`),`body_html`=VALUES(`body_html`),`image`=VALUES(`image`),`template`=VALUES(`template`),`seo_title`=VALUES(`seo_title`),`seo_description`=VALUES(`seo_description`),`active`=VALUES(`active`),`sort_order`=VALUES(`sort_order`);
INSERT INTO `pages` (`id`,`slug`,`title`,`h1`,`lead`,`body_html`,`image`,`template`,`seo_title`,`seo_description`,`active`,`sort_order`) VALUES (28,'information/934-fasonnyj-prokat','Фасонный прокат','Фасонный прокат','Справочный материал из технической библиотеки торговой компании «Монополия».','<div><div><p>Фасонный прокат </p><p><img alt="m 14 1 1" loading="lazy" src="assets/img/products/m_14_1_1__e8abe6ac09a9500c2c938ac5.jpg"/><img alt="m 14 1 2" loading="lazy" src="assets/img/products/m_14_1_2__ad9629f3d95b4e0cc63e4ad4.jpg"/><img alt="m 14 1 3" loading="lazy" src="assets/img/products/m_14_1_3__2819923f9e193596488a9e86.jpg"/></p><p>К <strong>фасонному прокату </strong>относятся следующие виды металлопроката: </p><ul><li>Общего (массового) потребления: </li></ul><p><strong>– угловой прокат; </strong><br/><strong>– швеллера; </strong><br/><strong>– балки двутавровые; </strong></p><ul><li>Специального назначения: </li></ul><p>– рельсы железнодорожные; <br/>– профили судостроения и т.п. </p><p><strong>Двутавровая балка </strong>— двутавр — это стальная балка Н-образного сечения, изготавливаемая по ГОСТ 26020-83, ГОСТ 8239-89, ГОСТ 19425-74 из углеродистой и низколегированной стали с химическим составом по ГОСТ 380. </p><p>Классификация стальных балок: </p><p>По способу изготовления стальные двутавровые балки бывают: </p><ul><li>Горячекатаные – изготовленные методом горячей прокатки из стальной заготовки; </li><li>Сварные – изготовленные методом сварки при помощи специального оборудования. </li></ul><p>По положению граней: </p><ul><li>балки двутавровые с уклоном внутренних граней; </li><li>балки двутавровые с параллельными гранями. </li></ul><p>По ширине граней полок: </p><ul><li>балка двутавровая с нормальной шириной полки — Б; </li><li>широкополочная двутавровая балка — Ш; </li><li>колонная балка металлическая — К. </li></ul><p>По эксплутационным характеристикам: </p><ul><li>балки двутавровые для подвесных путей — М; </li><li>балки металлические для армирования шахтных стволов — С. </li></ul><p>По длине: </p><ul><li>немерной длины; </li><li>мерной длины; </li><li>длины кратной мерной. </li></ul><p>Двутавровые балки используется в перекрытиях, рабочих площадках, эстакадах, мостах, подкрановых балках и в других металлических конструкциях. Наиболее часто используются двутавровые балки в большепролетных конструкциях промышленных зданий. </p><p>Двутавры стальные горячекатаные <strong>ГОСТ 8239-89 </strong></p><p>Стандарт устанавливает сортамент горячекатаных стальных двутавров с уклоном внутренних граней полок <br/>Горячекатаные стальные двутавры с уклоном внутренних граней полок по точности прокатки изготовляют: </p><ul><li><strong>Б </strong>– повышенной точности; </li><li><strong>В </strong>– обычной точности. </li></ul><p>Двутавры стальные горячекатаные с параллельными гранями полок <strong>ГОСТ 26020-83 </strong></p><p>Стандарт распространяется на стальные горячекатаные двутавры с параллельными гранями полок высотой от 100 до 1000мм и шириной полок от 55 до 400мм. </p><p><strong>Швеллер стальной </strong>— один из видов фасонного проката, представляющий собой сплошной металлический профиль П-образного сечения из стали различных марок. Применяется для придания жесткости и устойчивости конструкциям: швеллеры хорошо работают на изгиб и воспринимают осевые нагрузки, за счет чего увеличивается прочность конструкции в целом. </p><p>По способу изготовления: </p><ul><li>стальные швеллеры горячекатаные — ГОСТ 8240-89; </li><li>стальные швеллеры гнутые равнополочные — ГОСТ 8278-83; </li><li>стальные швеллеры гнутые неравнополочные — ГОСТ 8281-80. </li></ul><p>По виду стали: </p><ul><li>швеллеры стальные обыкновенного качества; </li><li>швеллеры стальные низколегированные; </li><li>швеллеры стальные углеродистые. </li></ul><p>По точности прокатки: </p><ul><li>швеллеры стальные высокой точности — А; </li><li>швеллеры стальные повышенной точности — Б; </li><li>швеллеры стальные обычной точности — В. </li></ul><p>Требования высокой и повышенной точности соответствуют высшей категории качества стального швеллера. <br/>По форме и размерам: </p><ul><li>швеллеры стальные с уклоном внутренних граней полок — У; </li><li>швеллеры стальные с параллельными гранями полок — П; </li><li>швеллеры стальные экономичные — Э; </li><li>швеллеры легкие с параллельными гранями полок — Л; </li><li>швеллеры стальные специальные — С. </li></ul><p>По специализации (ГОСТ 19425-74): </p><ul><li>швеллеры стальные для подвесных путей — М; </li><li>швеллеры стальные для армировки шахтных стволов — С; </li><li>швеллеры стальные для автомобильной промышленности — С; </li><li>швеллеры стальные для вагоностроения — В. </li></ul><p>Швеллеры гнутые стальные изготавливаются на профилегибочных станках из холоднокатаной, горячекатаной или рулонной стали обыкновенного качества, углеродистой, качественной, конструкционной или низколегированной стали согласно требованиям ГОСТ 11474-76. Отличительные черты швеллера гнутого — скругленные углы и одинаковая толщина по всему периметру. Существуют 2 вида швеллеров гнутых: с равной длиной полок (граней) — равнополочные швеллеры гнутые (ГОСТ 8278-83) и неравнополочные (ГОСТ 8281-80). </p><p>В отличие от горячекатаного швеллер гнутый не применяется в несущих конструкциях. Чаще стальной гнутый швеллер используется в качестве декоративного элемента для закрытия коммуникаций или направляющей для каких-либо движущихся конструкций. </p><p><strong>Угол стальной </strong>представляет собой сплошной профиль, в поперечном сечении которого отсутствует внутреннее полое пространство. Угол стальной изготавливают из углеродистой стали обыкновенного качества (ГОСТ 380-94) марок Ст0-Ст6, 09г2с, 3сп5 и др. и низколегированной стали повышенной прочности (ГОСТ 19281-89) марок 08Г2С, 12ГС, 16ГС и др. </p><p>Уголок стальной производят по следующим стандартам: </p><ul><li>уголок равнополочный горячекатаный (г/к) — ГОСТ 8509-93; </li><li>уголок металлический неравнополочный г/к — ГОСТ 8510-86; </li><li>уголок гнутый равнополочный — ГОСТ 19771-93; </li><li>уголок гнутый неравнополочный — ГОСТ 19772-93. </li></ul><p>Классификация стальных уголков: </p><p>По длине граней полок: </p><ul><li>уголки стальные равнополочные; </li><li>уголки стальные неравнополочные. </li></ul><p>По точности изготовления: </p><ul><li>уголок металлический высокой точности — А; </li><li>стальной уголок повышенной точности — Б; </li><li>металлический уголок обычной точности — B. </li></ul><p>По способу изготовления: </p><ul><li>уголки стальные горячекатаные; </li><li>металлические уголки холоднокатаные; </li><li>гнутые уголки из листового проката. </li></ul><p>По характеристике длины: </p><ul><li>мерной длины; </li><li>длины кратной мерной; </li><li>немерной длины. </li></ul><p><strong>Рельсы железнодорожные </strong>— стальные балки специального сечения, укладываемые на шпалах или других опорах для образования, как правило, двухниточного пути, по которому перемещается подвижной состав железнодорожного транспорта, городских железных дорог, специализированный состав в шахтах, карьерах, крановое оборудование. </p><p>Рельсы для железнодорожного транспорта изготавливаются из углеродистой стали. Наиболее распространены в странах СНГ рельсы следующих типов: Р50, Р65, Р75. </p><p>Рельсы железнодорожные подразделяют: </p><ul><li><strong>по типам: </strong><ul><li>Р50; </li><li>Р65; </li><li>Р65К (для наружных нитей кривых участков пути); </li><li>Р75; </li></ul></li><li><strong>по категориям качества: </strong><ul><li>В — рельсы термоупрочненные высшего качества; </li><li>Т1, Т2 — рельсы термоупрочненные; </li><li>Н — рельсы нетермоупрочненные; </li></ul></li><li><strong>по наличию болтовых отверстий: </strong><ul><li>с отверстиями на обоих концах; </li><li>без отверстий; </li></ul></li><li><strong>по способу выплавки стали: </strong><ul><li>М — из мартеновской стали; </li><li>К — из конвертерной стали; </li><li>Э — из электростали; </li></ul></li><li><strong>по виду исходных заготовок: </strong><ul><li>из слитков; </li><li>из непрерывно-литых заготовок (НЛЗ). </li></ul></li></ul><p><strong>Шпунт </strong>— металлический профиль, представляющий собой жёлоб c закруглёнными краями боковых стенок (пазами) или замками. Шпунты могут соединяться в секции по 2 или 3 шпунта. Длина шпунтов может доходить до 34 метров. Кроме корытообразного профиля, выпускают Z-образный и плоский шпунт, имеющий замки. </p><p>Среди всех разновидностей шпунтов следует выделить шпунт Ларсена. К его достоинствам можно отнести антикоррозийную устойчивость, удобство и простоту монтажа. Шпунт Ларсена забивают в грунт сваебойными молотами или погружают с помощью вибропогружателей. Каждая последующая свая погружается в грунт в специальный паз на предыдущей и разворачивается, относительно первой на 180 градусов. Образуется непрерывная конструкция, которую можно составить в виде кольца. Внутри конструкции откачивают воду и ведут необходимые работы. После окончания работ, шпунт извлекается и может быть использован повторно. </p><p><strong>Шахтная стойка </strong>. Профили СВП для крепи горных выработок изготовлются по ГОСТ 18662. </p><p>Длина: 9 000–12 000 мм <br/>Предельные отклонения по высоте: +1,0/-1,5 мм. <br/>Скручивание вокруг продольной оси: не допускается. </p></div></div>','assets/img/documents.webp','article','Фасонный прокат | Торговая компания «Монополия»','Фасонный прокат. Технические сведения и подбор продукции по спецификации.',1,27) ON DUPLICATE KEY UPDATE `slug`=VALUES(`slug`),`title`=VALUES(`title`),`h1`=VALUES(`h1`),`lead`=VALUES(`lead`),`body_html`=VALUES(`body_html`),`image`=VALUES(`image`),`template`=VALUES(`template`),`seo_title`=VALUES(`seo_title`),`seo_description`=VALUES(`seo_description`),`active`=VALUES(`active`),`sort_order`=VALUES(`sort_order`);
INSERT INTO `pages` (`id`,`slug`,`title`,`h1`,`lead`,`body_html`,`image`,`template`,`seo_title`,`seo_description`,`active`,`sort_order`) VALUES (29,'information/749-tekhnicheskie-osobennosti-provodov-sip','Технические особенности проводов СИП','Технические особенности проводов СИП','Справочный материал из технической библиотеки торговой компании «Монополия».','<div><div><p>Технические особенности проводов СИП </p><p>Провода предназначены для передачи электрической энергии в воздушных линиях электропередачи (ВЛ) и линейных ответвлениях от ВЛ. </p><p>Самонесущие изолированные провода предназначены для ВЛ на номинальное напряжение до 0,6/1 кВ включительно с номинальной частотой 50 Гц. </p><p>Самонесущие защищенные провода предназначены для ВЛ на номинальное напряжение 20 кВ (для сетей на номинальное напряжение 10, 15, 20 кВ) и 35 кВ (для сетей на номинальное напряжение 35 кВ) с номинальной частотой 50 Гц. </p><h3>Конструкция: </h3><table><tbody><tr><td><img alt="sip-1" loading="lazy" src="assets/img/products/sip-1__b5181c2eee42fb4f152ded39.gif"/></td><td><img alt="sip-2" loading="lazy" src="assets/img/products/sip-2__d7430f0a7a211d344ac596f0.gif"/></td><td><img alt="sip-3" loading="lazy" src="assets/img/products/sip-3__231ff194ca5d057592d1b464.gif"/></td><td><img alt="sip-4" loading="lazy" src="assets/img/products/sip-4__39cdc8d25e50f28ac6725b78.gif"/></td></tr><tr><td>СИП – 1 <br/></td><td>СИП – 2А <br/></td><td>СИП – 3 <br/></td><td>СИП – 4 <br/>СИП – 5 <br/></td></tr></tbody></table><ol><li><p>Фазная токопроводящая жила из алюминия, многопроволочная, уплотненная. </p></li><li><p>Нулевая несущая жила из алюминиевого сплава ABE или сталеалюминевая, многопроволочная, уплотненная. </p></li><li><p>Изоляция: </p><ul><li><p>светостабилизированного термопластичного полиэтилена (LDPE) для проводов СИП-1, СИП-4. </p></li><li><p>светостабилизированного сшитого полиэтилена (XLPE) для проводов СИП-2, СИП-2А, СИП-3, СИП-5. </p></li></ul></li></ol><p><strong>Номенклатура и конструктивные особенности СИП <br/></strong></p><table><tbody><tr><th><p>Марка провода </p></th><th><p>Конструктивные особенности </p></th><th><p>Преимущественная область применения </p></th></tr><tr><td><p>СИП-1 </p></td><td><p>Провод самонесущий с алюминиевыми жилами, с изоляцией из светостабилизированного сшитого полиэтилена (ПЭ), с нулевой несущей неизолированной сталеалюминиевой жилой </p></td><td><p>Для магистралей воздушных линий электропередачи (ВЛ) и линейных ответвлений от ВЛ в атмосфере воздуха типов I и II по ГОСТ 15150-69 </p></td></tr><tr><td><p>СИП-2 </p></td><td><p>То же, с нулевой несущей сталеалюминиевой жилой, изолированной светостабилизированным сшитым ПЭ </p></td><td><p>Для магистралей ВЛ и линейных ответвлений от ВЛ в атмосфере воздуха типов II и III по ГОСТ 15150-69, в том числе на побережьях морей, соленых озер, в промышленных районах и районах засоленных песков </p></td></tr><tr><td><p>СИП-3 </p></td><td><p>Провод самонесущий защищенный сталеалюминиевый с защитной изоляцией из светостабилизированного сшитого ПЭ </p></td><td><p>Для ВЛ на номинальное напряжение 10-35 кВ в атмосфере воздуха типов II и III по ГОСТ 15150-69, в том числе на побережьях морей, соленых озер, в промышленных районах и районах засоленных песков </p></td></tr><tr><td><p>СИП-4 </p></td><td><p>Провод самонесущий изолированный без несущего элемента, с алюминиевыми токопроводящими жилами, с изоляцией из светостабилизированного сшитого ПЭ </p></td><td><p>Для ответвлений от ВЛ к вводу и для прокладки по стенам зданий и инженерных сооружений в атмосфере воздуха типов II и III по ГОСТ 15150-69 </p></td></tr></tbody></table></div></div>','assets/img/documents.webp','article','Технические особенности проводов СИП | Торговая компания «Монополия»','Технические особенности проводов СИП. Технические сведения и подбор продукции по спецификации.',1,28) ON DUPLICATE KEY UPDATE `slug`=VALUES(`slug`),`title`=VALUES(`title`),`h1`=VALUES(`h1`),`lead`=VALUES(`lead`),`body_html`=VALUES(`body_html`),`image`=VALUES(`image`),`template`=VALUES(`template`),`seo_title`=VALUES(`seo_title`),`seo_description`=VALUES(`seo_description`),`active`=VALUES(`active`),`sort_order`=VALUES(`sort_order`);
INSERT INTO `pages` (`id`,`slug`,`title`,`h1`,`lead`,`body_html`,`image`,`template`,`seo_title`,`seo_description`,`active`,`sort_order`) VALUES (30,'information/1032-praj-list-na-metalloprokat','Прайс-лист на металлопрокат','Прайс-лист на металлопрокат','Справочный материал из технической библиотеки торговой компании «Монополия».','<div><div>Типоразмеры и исполнения на металлопрокат <p>Если Вы не можете найти необходимый материал или стоимость, если у Вас возникли вопросы, менеджеры компании с удовольствием проконсультируют Вас по тел. : 8 (812) 536-98-97, 8 (812) 932-86-48 </p><table><tbody><tr><td colspan="3"><p><strong>Арматура строительная гладкая А1 </strong></p></td><td></td><td rowspan="9"><p><strong>отправить заявку </strong></p></td></tr><tr><td><p><strong>Наименование </strong></p></td><td><p><strong>Марка стали </strong></p></td><td><p><strong>ГОСТ </strong></p></td><td><p><strong>Цена, тн. </strong></p></td></tr><tr><td><p><strong>Арматура 8 </strong></p></td><td><p>ст3сп </p></td><td><p>ГОСТ 5781-82 </p></td><td></td></tr><tr><td><p><strong>Арматура 10 </strong></p></td><td><p>ст3сп </p></td><td><p>ГОСТ 5781-82 </p></td><td></td></tr><tr><td><p><strong>Арматура 12 </strong></p></td><td><p>ст3сп </p></td><td><p>ГОСТ 5781-82 </p></td><td></td></tr><tr><td><p><strong>Арматура 14 </strong></p></td><td><p>ст3сп </p></td><td><p>ГОСТ 5781-82 </p></td><td></td></tr><tr><td><p><strong>Арматура 16 </strong></p></td><td><p>ст3сп </p></td><td><p>ГОСТ 5781-82 </p></td><td></td></tr><tr><td><p><strong>Арматура 18 </strong></p></td><td><p>ст3сп </p></td><td><p>ГОСТ 5781-82 </p></td><td></td></tr><tr><td><p><strong>Арматура 20 </strong></p></td><td><p>ст3сп </p></td><td><p>ГОСТ 5781-82 </p></td><td></td></tr><tr><td></td><td></td><td></td><td></td><td></td></tr><tr><td colspan="3"><p><strong>Арматура строительная рифленая А500С </strong></p></td><td></td><td rowspan="16"><p><strong>отправить заявку </strong></p></td></tr><tr><td><p><strong>Наименование </strong></p></t