INSERT INTO `pages` (`id`,`slug`,`title`,`h1`,`lead`,`body_html`,`image`,`template`,`seo_title`,`seo_description`,`active`,`sort_order`) VALUES (31,'information/1033-prajs-list-na-kabelnuyu-produktsiyu','Прайс-лист на кабельную продукцию','Прайс-лист на кабельную продукцию','Справочный материал из технической библиотеки торговой компании «Монополия».','<div><div><p>Типоразмеры и исполнения временно отсутствует, приносим свои извинения. </p></div></div>','assets/img/documents.webp','article','Прайс-лист на кабельную продукцию | Торговая компания «Монополия»','Прайс-лист на кабельную продукцию. Технические сведения и подбор продукции по спецификации.',1,30) ON DUPLICATE KEY UPDATE `slug`=VALUES(`slug`),`title`=VALUES(`title`),`h1`=VALUES(`h1`),`lead`=VALUES(`lead`),`body_html`=VALUES(`body_html`),`image`=VALUES(`image`),`template`=VALUES(`template`),`seo_title`=VALUES(`seo_title`),`seo_description`=VALUES(`seo_description`),`active`=VALUES(`active`),`sort_order`=VALUES(`sort_order`);
INSERT INTO `pages` (`id`,`slug`,`title`,`h1`,`lead`,`body_html`,`image`,`template`,`seo_title`,`seo_description`,`active`,`sort_order`) VALUES (32,'information/1034-prajs-list-na-profnastil','Прайс-лист на профнастил','Прайс-лист на профнастил','Справочный материал из технической библиотеки торговой компании «Монополия».','<div><div><p>Типоразмеры и исполнения временно отсутствует, приносим свои извинения. </p></div></div>','assets/img/documents.webp','article','Прайс-лист на профнастил | Торговая компания «Монополия»','Прайс-лист на профнастил. Технические сведения и подбор продукции по спецификации.',1,31) ON DUPLICATE KEY UPDATE `slug`=VALUES(`slug`),`title`=VALUES(`title`),`h1`=VALUES(`h1`),`lead`=VALUES(`lead`),`body_html`=VALUES(`body_html`),`image`=VALUES(`image`),`template`=VALUES(`template`),`seo_title`=VALUES(`seo_title`),`seo_description`=VALUES(`seo_description`),`active`=VALUES(`active`),`sort_order`=VALUES(`sort_order`);
INSERT INTO `faqs` (`id`,`question`,`answer`,`sort_order`,`active`) VALUES (1,'Как получить стоимость товара?','Добавьте позицию в заявку, укажите характеристики и количество. Мы рассчитаем стоимость с учетом исполнения, объема и условий поставки. Для нескольких позиций можно приложить готовую спецификацию.',0,1) ON DUPLICATE KEY UPDATE `question`=VALUES(`question`),`answer`=VALUES(`answer`),`sort_order`=VALUES(`sort_order`),`active`=VALUES(`active`);
INSERT INTO `faqs` (`id`,`question`,`answer`,`sort_order`,`active`) VALUES (2,'Можно ли отправить заявку без товаров из каталога?','Да. Добавьте свободную позицию или заполните сообщение и приложите файл. Укажите известные параметры и задачу: менеджер уточнит недостающие данные.',1,1) ON DUPLICATE KEY UPDATE `question`=VALUES(`question`),`answer`=VALUES(`answer`),`sort_order`=VALUES(`sort_order`),`active`=VALUES(`active`);
INSERT INTO `faqs` (`id`,`question`,`answer`,`sort_order`,`active`) VALUES (3,'Что указать при подборе кабеля?','Марку, количество и сечение жил, рабочее напряжение, длину и условия прокладки. Если марка не определена, направьте требования проекта или опишите оборудование и условия эксплуатации.',2,1) ON DUPLICATE KEY UPDATE `question`=VALUES(`question`),`answer`=VALUES(`answer`),`sort_order`=VALUES(`sort_order`),`active`=VALUES(`active`);
INSERT INTO `faqs` (`id`,`question`,`answer`,`sort_order`,`active`) VALUES (4,'Какие данные нужны для металлопроката?','Тип изделия, размеры, марку стали, требуемый стандарт и количество или массу. Для поставки на объект укажите адрес и условия разгрузки.',3,1) ON DUPLICATE KEY UPDATE `question`=VALUES(`question`),`answer`=VALUES(`answer`),`sort_order`=VALUES(`sort_order`),`active`=VALUES(`active`);
INSERT INTO `faqs` (`id`,`question`,`answer`,`sort_order`,`active`) VALUES (5,'Как оформить запрос на профнастил?','Укажите марку профиля, толщину металла, длину и количество листов, вид покрытия и цвет RAL. Если нужны разные длины, внесите их отдельными строками или приложите ведомость.',4,1) ON DUPLICATE KEY UPDATE `question`=VALUES(`question`),`answer`=VALUES(`answer`),`sort_order`=VALUES(`sort_order`),`active`=VALUES(`active`);
INSERT INTO `faqs` (`id`,`question`,`answer`,`sort_order`,`active`) VALUES (6,'Что нужно для расчета трансформатора или КТП?','Мощность, напряжения, исполнение, требования к комплектации и размещению. Для проектного оборудования лучше приложить опросный лист, схему или спецификацию.',5,1) ON DUPLICATE KEY UPDATE `question`=VALUES(`question`),`answer`=VALUES(`answer`),`sort_order`=VALUES(`sort_order`),`active`=VALUES(`active`);
INSERT INTO `faqs` (`id`,`question`,`answer`,`sort_order`,`active`) VALUES (7,'Можно ли оплатить заказ на сайте?','Сайт принимает заявки на расчет. После согласования заказа оплата производится по выставленному счету и условиям договора. Онлайн-оплата на сайте не предусмотрена.',6,1) ON DUPLICATE KEY UPDATE `question`=VALUES(`question`),`answer`=VALUES(`answer`),`sort_order`=VALUES(`sort_order`),`active`=VALUES(`active`);
INSERT INTO `faqs` (`id`,`question`,`answer`,`sort_order`,`active`) VALUES (8,'Как узнать наличие и сроки?','Наличие, срок комплектации или изготовления и дату отгрузки подтверждаем по конкретным позициям в коммерческом предложении. Укажите желаемую дату поставки в комментарии к заявке.',7,1) ON DUPLICATE KEY UPDATE `question`=VALUES(`question`),`answer`=VALUES(`answer`),`sort_order`=VALUES(`sort_order`),`active`=VALUES(`active`);
INSERT INTO `faqs` (`id`,`question`,`answer`,`sort_order`,`active`) VALUES (9,'Можно ли получить сертификаты и паспорта?','Запросите необходимые документы вместе с заявкой, указав марку, модель и исполнение. Комплект документов зависит от продукции и конкретной партии.',8,1) ON DUPLICATE KEY UPDATE `question`=VALUES(`question`),`answer`=VALUES(`answer`),`sort_order`=VALUES(`sort_order`),`active`=VALUES(`active`);
INSERT INTO `faqs` (`id`,`question`,`answer`,`sort_order`,`active`) VALUES (10,'Какие файлы можно приложить?','Поддерживаются PDF, XLS, XLSX, CSV, DOC, DOCX, JPG и PNG размером до 10 МБ. Если спецификация больше, отправьте ее на monopoly@list.ru.',9,1) ON DUPLICATE KEY UPDATE `question`=VALUES(`question`),`answer`=VALUES(`answer`),`sort_order`=VALUES(`sort_order`),`active`=VALUES(`active`);
INSERT INTO `faqs` (`id`,`question`,`answer`,`sort_order`,`active`) VALUES (11,'Как согласовать доставку или самовывоз?','Укажите регион, адрес, массу или количество и особенности разгрузки. Менеджер предложит подходящий способ доставки либо подтвердит место и время самовывоза.',10,1) ON DUPLICATE KEY UPDATE `question`=VALUES(`question`),`answer`=VALUES(`answer`),`sort_order`=VALUES(`sort_order`),`active`=VALUES(`active`);
